#include <stdlib.h>
#include <string.h>

typedef struct {
    // Define the structure for RrcConnectionReconfigurationIndication
} RrcConnectionReconfigurationIndication;

typedef struct {
    // Define the structure for RrcMessage
} RrcMessage;

typedef struct NFDataPdu_t {
    RrcConnectionReconfigurationIndication indication;
    RrcMessage *message;
} NFDataPdu_t;

typedef struct {
    NFDataPdu_t **array;
    size_t count;
    size_t capacity;
} NFDataArray_t;

NFDataArray_t* nfdataArray_create() {
    NFDataArray_t *array = (NFDataArray_t*)malloc(sizeof(NFDataArray_t));
    array->array = NULL;
    array->count = 0;
    array->capacity = 0;
    return array;
}

void nfdataArray_destroy(NFDataArray_t *array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->array[i]->message);
        free(array->array[i]);
    }
    free(array->array);
    free(array);
}

int nfdataArray_add(NFDataArray_t *array, RrcConnectionReconfigurationIndication indication) {
    if (array->count >= array->capacity) {
        size_t new_capacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        NFDataPdu_t **new_array = (NFDataPdu_t**)realloc(array->array, new_capacity * sizeof(NFDataPdu_t*));
        if (!new_array) return -1; // Memory allocation failed
        array->array = new_array;
        array->capacity = new_capacity;
    }
    NFDataPdu_t *new_pdu = (NFDataPdu_t*)malloc(sizeof(NFDataPdu_t));
    if (!new_pdu) return -1; // Memory allocation failed
    new_pdu->indication = indication;
    new_pdu->message = (RrcMessage*)malloc(sizeof(RrcMessage));
    if (!new_pdu->message) {
        free(new_pdu);
        return -1; // Memory allocation failed
    }
    array->array[array->count++] = new_pdu;
    return 0;
}

int nfdataArray_update(NFDataArray_t *array, size_t index, RrcConnectionReconfigurationIndication indication) {
    if (index >= array->count) return -1; // Index out of bounds
    free(array->array[index]->message);
    array->array[index]->indication = indication;
    array->array[index]->message = (RrcMessage*)malloc(sizeof(RrcMessage));
    if (!array->array[index]->message) return -1; // Memory allocation failed
    return 0;
}

void nfdataArray_process(NFDataArray_t *array, void (*process_message)(RrcMessage *)) {
    for (size_t i = 0; i < array->count; ++i) {
        process_message(array->array[i]->message);
    }
}
