typedef struct {
    int value;
    int status; // 0 for invalid, 1 for valid
} record;

void initialize_arrays(long *offsets, int *keys, record **records, size_t size) {
    srand(time(NULL)); // Seed with current time

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand(); // Random offset value
        keys[i] = rand() % 1000; // Random key within range [0, 999]

        *records = realloc(*records, (i + 1) * sizeof(record));
        if (*records == NULL) {
            fprintf(stderr, "Memory allocation failed. Attempting to reduce size.\n");
            size /= 2;
            i--; // Retry with reduced size
            continue;
        }

        (*records)[i].value = rand() % 100; // Random value within range [0, 99]
        (*records)[i].status = 1; // Initialize status as valid
    }
}

void cleanup(long *offsets, int *keys, record **records) {
    free(offsets);
    free(keys);
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}

int main() {
    size_t size = 1000; // Example size
    long *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));
    record *records = NULL;

    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Initial memory allocation failed.\n");
        return 1;
    }

    initialize_arrays(offsets, keys, &records, size);

    // Use the arrays...

    cleanup(offsets, keys, &records);
    return 0;
}
