#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024

void process_file(const char *filename, int count_non_empty, int skip_comments, FILE *output) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    long total_lines = 0, non_empty_lines = 0, skipped_lines = 0;
    char line[MAX_LINE_LENGTH];

    while (fgets(line, sizeof(line), file)) {
        total_lines++;
        if (skip_comments && (line[0] == '#' || isspace(line[0]))) {
            skipped_lines++;
        } else if (count_non_empty && strlen(line) > 1) {
            non_empty_lines++;
        }
    }

    fclose(file);

    fprintf(output, "File: %s\n", filename);
    fprintf(output, "Total lines: %ld\n", total_lines);
    fprintf(output, "Non-empty lines: %ld\n", non_empty_lines);
    fprintf(output, "Skipped lines: %ld\n\n", skipped_lines);
}

void display_manpage() {
    printf("Usage: program_name [-c] [-s] [-o output_file] [--manpage]\n");
    printf("-c: Count only non-empty lines.\n");
    printf("-s: Skip lines that start with # or are entirely whitespace.\n");
    printf("-o output_file: Redirect the output to a specified file instead of printing to the console.\n");
    printf("--manpage: Display detailed usage information.\n");
}

int main(int argc, char *argv[]) {
    int count_non_empty = 0;
    int skip_comments = 0;
    const char *output_file = NULL;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0) {
            count_non_empty = 1;
        } else if (strcmp(argv[i], "-s") == 0) {
            skip_comments = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            output_file = argv[i] + 3;
        } else if (strcmp(argv[i], "--manpage") == 0) {
            display_manpage();
            return 0;
        }
    }

    FILE *output = stdout;
    if (output_file) {
        output = fopen(output_file, "w");
        if (!output) {
            perror("Error opening output file");
            return 1;
        }
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-c") == 0 || strcmp(argv[i], "-s") == 0 || strcmp(argv[i], "--manpage") == 0) continue;
        process_file(argv[i], count_non_empty, skip_comments, output);
    }

    if (output != stdout) fclose(output);

    return 0;
}
