#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_HOSTS 100
#define CSV_BUFFER_SIZE 4096

typedef struct {
    char hostname[256];
    char ip_address[16];
} HostInfo;

HostInfo hosts[MAX_HOSTS];
int host_count = 0;
pthread_mutex_t lock;

void* resolve_dns(void* arg) {
    int index = *(int*)arg;
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hosts[index].hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char* ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        strcpy(hosts[index].ip_address, ipstr);
        break; // get only the first result
    }

    freeaddrinfo(res); // all done with this structure

    return NULL;
}

void process_csv(const char* csv_data) {
    FILE* fp = fmemopen((char*)csv_data, strlen(csv_data), "r");
    if (!fp) {
        perror("fmemopen");
        return;
    }

    char buffer[CSV_BUFFER_SIZE];
    while (fgets(buffer, sizeof(buffer), fp)) {
        char* token = strtok(buffer, ",");
        int count = 0;
        double sum = 0;

        while (token != NULL) {
            if (count >= 2) {
                break;
            }
            sum += atof(token);
            count++;
            token = strtok(NULL, ",");
        }

        if (count == 2) {
            printf("Average of last two fields: %.2f\n", sum / 2);
        } else {
            printf("Invalid record format\n");
        }
    }

    fclose(fp);
}

int main() {
    // Simulate receiving CSV data via network
    const char* csv_data = "1,2,3\n4,5,6\n7,8,9";

    pthread_t threads[MAX_HOSTS];
    int thread_ids[MAX_HOSTS];

    // Resolve DNS for each hostname
    for (int i = 0; i < host_count; i++) {
        thread_ids[i] = i;
        if (pthread_create(&threads[i], NULL, resolve_dns, &thread_ids[i]) != 0) {
            perror("pthread_create");
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < host_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Process CSV data
    process_csv(csv_data);

    // Free allocated memory and log statistics

    return EXIT_SUCCESS;
}
```

