#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define MAX_INTS 1000

int* receive_integers(int *count) {
    int *ints = (int*)malloc(MAX_INTS * sizeof(int));
    if (!ints) {
        perror("Memory allocation failed");
        return NULL;
    }

    *count = 0;
    char buffer[256];
    while (*count < MAX_INTS && fgets(buffer, sizeof(buffer), stdin)) {
        int num;
        if (sscanf(buffer, "%d", &num) == 1) {
            ints[*count] = num;
            (*count)++;
        } else {
            fprintf(stderr, "Malformed data packet received\n");
            break;
        }
    }

    if (*count == 0) {
        free(ints);
        return NULL;
    }

    return ints;
}

void print_largest_int(int *ints, int count) {
    if (count == 0) {
        printf("No integers found.\n");
        return;
    }

    int largest = ints[0];
    for (int i = 1; i < count; i++) {
        if (ints[i] > largest) {
            largest = ints[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

int main() {
    int count;
    int *ints = receive_integers(&count);

    if (ints) {
        print_largest_int(ints, count);
        free(ints);
    }

    return 0;
}
```

