#define MAX_LOG_SIZE 1024 * 1024 * 1024 // 1GB
#define MAX_LOG_FILES 10

typedef struct {
    char log_dir[MAX_LOG_SIZE];
    int max_log_files;
    size_t total_size;
    pthread_mutex_t lock;
} LogSystem;

void init_log_system(LogSystem *log_sys, const char *log_dir, int max_log_files) {
    strncpy(log_sys->log_dir, log_dir, MAX_LOG_SIZE);
    log_sys->max_log_files = max_log_files;
    log_sys->total_size = 0;
    pthread_mutex_init(&log_sys->lock, NULL);
}

void append_to_log(LogSystem *log_sys, const char *message) {
    pthread_mutex_lock(&log_sys->lock);

    // Check if adding this message exceeds the total size limit
    size_t new_size = strlen(message) + 1; // Include null terminator
    if (log_sys->total_size + new_size > MAX_LOG_SIZE) {
        // Archive old logs to make space
        archive_old_logs(log_sys);
    }

    // Append the message to a log file
    char filename[MAX_LOG_SIZE];
    snprintf(filename, MAX_LOG_SIZE, "%s/log_%d.txt", log_sys->log_dir, log_sys->total_size / (MAX_LOG_SIZE / log_sys->max_log_files));
    FILE *file = fopen(filename, "a");
    if (file) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(file, "[%s] %s\n", timestamp, message);
        fclose(file);

        // Update total size
        log_sys->total_size += new_size;
    }

    pthread_mutex_unlock(&log_sys->lock);
}

void archive_old_logs(LogSystem *log_sys) {
    // Implement logic to archive old logs based on retention policies
    // This could involve moving files to a different directory or compressing them
}

int main() {
    LogSystem log_sys;
    init_log_system(&log_sys, "/var/log/myapp", MAX_LOG_FILES);

    append_to_log(&log_sys, "This is a test log message.");

    return 0;
}
