import os
import hashlib
import requests
from datetime import datetime

# Configuration management service details
API_URL = "https://api.configservice.com/v1"
API_KEY = "your_api_key_here"

# Directory structure for different environments
ENVIRONMENTS = {
    'production': '/path/to/production/config',
    'staging': '/path/to/staging/config',
    'development': '/path/to/development/config'
}

def fetch_config_from_api(environment):
    headers = {'Authorization': f'Bearer {API_KEY}'}
    response = requests.get(f"{API_URL}/config/{environment}", headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        print(f"Failed to fetch config for {environment}: {response.status_code}")
        return None

def update_config_files(environment, new_config):
    config_dir = ENVIRONMENTS[environment]
    for file_name, content in new_config.items():
        file_path = os.path.join(config_dir, file_name)
        with open(file_path, 'w') as file:
            file.write(content)

def calculate_checksum(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

def validate_config_integrity(environment):
    config_dir = ENVIRONMENTS[environment]
    for file_name in os.listdir(config_dir):
        file_path = os.path.join(config_dir, file_name)
        if not os.path.isfile(file_path):
            continue
        original_checksum = calculate_checksum(file_path)
        # Simulate fetching checksum from a secure storage
        stored_checksum = fetch_stored_checksum(file_path)
        if original_checksum != stored_checksum:
            print(f"Checksum mismatch for {file_path}")
            return False
    return True

def fetch_stored_checksum(file_path):
    # Placeholder function to simulate fetching checksum from a secure storage
    return "stored_checksum_here"

def log_error(error_message):
    with open('error_log.txt', 'a') as log_file:
        log_file.write(f"{datetime.now()}: {error_message}\n")

def rollback_config(environment, backup_dir):
    config_dir = ENVIRONMENTS[environment]
    for file_name in os.listdir(config_dir):
        file_path = os.path.join(config_dir, file_name)
        backup_path = os.path.join(backup_dir, file_name)
        if os.path.exists(backup_path):
            os.replace(backup_path, file_path)

def main():
    backup_dir = '/path/to/backup'
    for environment in ENVIRONMENTS:
        try:
            new_config = fetch_config_from_api(environment)
            if not new_config:
                continue
            update_config_files(environment, new_config)
            if validate_config_integrity(environment):
                print(f"Configuration updated successfully for {environment}")
            else:
                rollback_config(environment, backup_dir)
                log_error(f"Failed to validate config for {environment}, rolling back")
        except Exception as e:
            log_error(f"An error occurred: {e}")

if __name__ == "__main__":
    main()
```

This script provides a basic structure for updating network configuration templates across multiple environments. It includes functions for fetching configurations from an API, updating local files, validating checksums, and handling errors or failures gracefully. The rollback mechanism ensures that the network service remains unaffected in case of issues during the update process.']

