import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class PokemonBatchAnalyzer {

    private static final int MAX_RETRIES = 5;
    private static final long INITIAL_BACKOFF_MS = 100;
    private static final ExecutorService executorService = Executors.newFixedThreadPool(10);

    public static List<String> analyzePokemonBatch(List<Pokemon> pokemonList) {
        List<CompletableFuture<String>> futures = new ArrayList<>();

        for (Pokemon pokemon : pokemonList) {
            CompletableFuture<String> future = CompletableFuture.supplyAsync(() -> processPokemon(pokemon), executorService);
            futures.add(future);
        }

        return CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply(v -> futures.stream()
                        .map(CompletableFuture::join)
                        .collect(Collectors.toList()))
                .join();
    }

    private static String processPokemon(Pokemon pokemon) {
        if (pokemon == null) {
            return "Invalid Pokemon object";
        }

        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
            try {
                String basicInfo = fetchBasicInfo(pokemon.getName());
                String detailedData = fetchDetailedData(pokemon.getName());

                // Process and combine data
                return generateReport(basicInfo, detailedData);
            } catch (Exception e) {
                retryCount++;
                if (retryCount >= MAX_RETRIES) {
                    throw new RuntimeException("Failed to process Pokemon after " + MAX_RETRIES + " attempts", e);
                }
                long backoff = INITIAL_BACKOFF_MS * (1 << retryCount);
                try {
                    Thread.sleep(backoff);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                    throw new RuntimeException("Thread interrupted during retry", ie);
                }
            }
        }

        return "Failed to process Pokemon after " + MAX_RETRIES + " attempts";
    }

    private static String fetchBasicInfo(String name) throws Exception {
        // Simulate API call
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("Invalid Pokemon name");
        }
        return "Name: " + name + ", Types: Grass, Poison";
    }

    private static String fetchDetailedData(String name) throws Exception {
        // Simulate auxiliary service call
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("Invalid Pokemon name");
        }
        return "Weaknesses: Fire, Ice, Flying, Psychic, Bug\nSynergies: Dragon, Fairy";
    }

    private static String generateReport(String basicInfo, String detailedData) {
        // Combine data into a report
        return basicInfo + "\n" + detailedData;
    }

