#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>
#include <pthread.h>

typedef struct {
    sem_t *sem;
    char name[256];
} Semaphore;

typedef struct {
    Semaphore **sems;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SemaphoreCollection;

SemaphoreCollection* create_semaphore_collection() {
    SemaphoreCollection *collection = (SemaphoreCollection*)malloc(sizeof(SemaphoreCollection));
    collection->sems = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_semaphore_collection(SemaphoreCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        sem_destroy(collection->sems[i]->sem);
        free(collection->sems[i]);
    }
    free(collection->sems);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

Semaphore* create_semaphore(SemaphoreCollection *collection, const char *name, unsigned int initial_value) {
    Semaphore *sem = (Semaphore*)malloc(sizeof(Semaphore));
    sem->sem = sem_open(name, O_CREAT | O_EXCL, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        free(sem);
        return NULL;
    }
    strcpy(sem->name, name);

    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 4;
        Semaphore **new_sems = (Semaphore**)realloc(collection->sems, new_capacity * sizeof(Semaphore*));
        if (!new_sems) {
            perror("Failed to allocate memory for semaphore collection");
            sem_close(sem->sem);
            sem_unlink(name);
            free(sem);
            pthread_mutex_unlock(&collection->lock);
            return NULL;
        }
        collection->sems = new_sems;
        collection->capacity = new_capacity;
    }
    collection->sems[collection->count++] = sem;
    pthread_mutex_unlock(&collection->lock);

    return sem;
}

int delete_semaphore(SemaphoreCollection *collection, const char *name) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->sems[i]->name, name) == 0) {
            sem_close(collection->sems[i]->sem);
            sem_unlink(name);
            free(collection->sems[i]);
            memmove(&collection->sems[i], &collection->sems[i + 1], (collection->count - i - 1) * sizeof(Semaphore*));
            --collection->count;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&collection->lock);
    fprintf(stderr, "Semaphore %s not found\n", name);
    return -1;
}

int semaphore_wait(Semaphore *sem) {
    return sem_wait(sem->sem);
}

int semaphore_post(Semaphore *sem) {
    return sem_post(sem->sem);
}
