// Function to simulate interaction with an external data source
bool validateTarget(const int& target) {
    // Simulate a network delay or failure
    std::this_thread::sleep_for(std::chrono::milliseconds(100));
    return true; // Assume validation always succeeds for simplicity
}

void processVector(std::vector<int>& vec, const int& target, int& updateValue) {
    auto future = std::async(std::launch::async, validateTarget, target);

    // Search for the first occurrence of the target in the vector
    auto it = std::find(vec.begin(), vec.end(), target);

    if (it != vec.end()) {
        // Target found, update the third integer argument
        updateValue += 10;
    } else {
        // Target not found, decrement the third integer argument
        updateValue -= 5;
    }

    // Wait for the external data source validation to complete
    if (future.get()) {
        std::cout << "Validation successful." << std::endl;
    } else {
        std::cerr << "Validation failed. Proceeding with local update." << std::endl;
    }
}

int main() {
    std::vector<int> vec = {1, 2, 3, 4, 5};
    int target = 3;
    int updateValue = 0;

    processVector(vec, target, updateValue);

    std::cout << "Updated value: " << updateValue << std::endl;

    return 0;
}
