namespace LoggingConfig {
    class ConfigManager {
    public:
        ConfigManager(const std::string& configFilePath) : configFilePath(configFilePath), configCache(nullptr), cacheValid(false) {
            loadConfig();
        }

        ~ConfigManager() {
            delete configCache;
        }

        void reloadConfig() {
            std::lock_guard<std::mutex> lock(mutex);
            loadConfig();
        }

        const Json::Value& getConfig() const {
            return *configCache;
        }

    private:
        std::string configFilePath;
        Json::Value* configCache;
        bool cacheValid;
        mutable std::mutex mutex;

        void loadConfig() {
            try {
                std::ifstream configFile(configFilePath);
                if (!configFile.is_open()) {
                    throw std::runtime_error("Failed to open configuration file");
                }

                Json::Value newConfig;
                configFile >> newConfig;
                configFile.close();

                delete configCache;
                configCache = new Json::Value(newConfig);
                cacheValid = true;
            } catch (const std::exception& e) {
                std::cerr << "Error loading configuration: " << e.what() << std::endl;
                if (configCache == nullptr) {
                    configCache = new Json::Value();
                }
            }
        }
    };
}

int main() {
    LoggingConfig::ConfigManager configManager("logging_config.json");

    // Example usage
    while (true) {
        const auto& config = configManager.getConfig();
        std::cout << "Current logging level: " << config["log_level"].asString() << std::endl;
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    return 0;
}
