        foreach (var command in sqlCommands)
        {
            var databaseName = GetDatabaseFromCommand(command);
            if (_connectionStrings.ContainsKey(databaseName))
            {
                using (var connection = CreateConnection(_connectionStrings[databaseName]))
                {
                    try
                    {
                        await connection.OpenAsync();
                        var parameters = ParseParameters(command, _defaultParameters);
                        var reader = await ExecuteQueryAsync(connection, command, parameters);
                        results[databaseName] = reader;
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, $"Error executing query on database {databaseName}: {command}");
                    }
                }
            }
        }

        return results;
