public class DirectoryManager
{
    public void CreateDirectoryAndSetEnvironmentVariable(Config config)
    {
        string directoryPath = Environment.GetEnvironmentVariable(config.EnvironmentVariableName);

        if (string.IsNullOrEmpty(directoryPath))
        {
            try
            {
                directoryPath = Path.Combine(Environment.CurrentDirectory, config.DirectoryName);
                Directory.CreateDirectory(directoryPath);
                Environment.SetEnvironmentVariable(config.EnvironmentVariableName, directoryPath);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error creating directory or setting environment variable: {ex.Message}");
                return;
            }
        }

        try
        {
            XPathDocument xmlDoc = new XPathDocument(config.XmlFilePath);
            XPathNavigator navigator = xmlDoc.CreateNavigator();
            XPathNodeIterator nodes = navigator.Select($"//{config.ElementTagName}");

            if (!nodes.MoveNext())
            {
                Console.WriteLine("No element found with the specified tag name.");
            }
            else if (nodes.MoveNext())
            {
                Console.WriteLine("More than one element found with the specified tag name.");
            }
            else
            {
                // Process the single node as needed
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
        }
    }
}

public class Config
{
    public string DirectoryName { get; set; }
    public string EnvironmentVariableName { get; set; }
    public string XmlFilePath { get; set; }
    public string ElementTagName { get; set; }
}
