import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class MD5HashProcessor {

    private static final int MAX_STRING_LENGTH = 1024;
    private static final int MAX_RETRIES = 3;
    private static final String CONFIG_SERVER_URL = "http://configserver.com/md5BatchSize";
    private static final ConcurrentHashMap<String, Integer> configCache = new ConcurrentHashMap<>();

    public Map<String, String> processStrings(List<String> inputStrings) {
        Map<String, String> result = new HashMap<>();
        int batchSize = getConfig("md5BatchSize");

        for (int i = 0; i < inputStrings.size(); i += batchSize) {
            int end = Math.min(i + batchSize, inputStrings.size());
            List<String> batch = inputStrings.subList(i, end);

            for (String input : batch) {
                try {
                    if (!isValidInput(input)) {
                        logWarning("Invalid input: " + input);
                        result.put(input, "Invalid input");
                        continue;
                    }

                    String hash = retryHashing(input, MAX_RETRIES);
                    result.put(input, hash);
                } catch (Exception e) {
                    logError("Failed to process string: " + input, e);
                    result.put(input, "Processing failed");
                }
            }
        }

        return result;
    }

    private boolean isValidInput(String input) {
        return input != null && !input.isEmpty() && input.length() <= MAX_STRING_LENGTH;
    }

    private int getConfig(String key) {
        return configCache.computeIfAbsent(key, k -> fetchConfigFromServer(k));
    }

    private int fetchConfigFromServer(String key) {
        // Simulate fetching configuration from a remote server
        try {
            // Replace with actual HTTP request to CONFIG_SERVER_URL
            String response = "10"; // Example response
            return Integer.parseInt(response);
        } catch (Exception e) {
            logError("Failed to fetch config for: " + key, e);
            throw new ConfigRetrievalException("Failed to retrieve configuration", e);
        }
    }

    private String retryHashing(String input, int retries) throws Exception {
        for (int i = 0; i <= retries; i++) {
            try {
                return hashString(input);
            } catch (Exception e) {
                if (i == retries) {
                    throw e;
                }
                logWarning("Retrying hashing for: " + input + ", attempt: " + (i + 1));
            }
        }
        return null; // Should never reach here due to exception rethrowing
    }

    private String hashString(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : messageDigest) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private void logWarning(String message) {
        System.out.println("WARNING: " + message);
    }

    private void logError(String message, Exception e) {
        System.err.println("ERROR: " + message);
        e.printStackTrace();
    }

    public static class ConfigRetrievalException extends RuntimeException {
        public ConfigRetrievalException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
