const fs = require('fs').promises;
const path = require('path');
const { promisify } = require('util');

const readFileAsync = promisify(fs.readFile);

const cache = new Map();

async function processFiles(directory, extension) {
  const key = `${directory}-${extension}`;

  if (cache.has(key)) {
    return cache.get(key);
  }

  try {
    let files = await fs.readdir(directory);
    files = files.filter(file => path.extname(file).toLowerCase() === `.${extension.toLowerCase()}`);

    const fileContents = await Promise.all(files.map(async file => {
      try {
        const filePath = path.join(directory, file);
        const stats = await fs.stat(filePath);

        if (stats.size > 10 * 1024 * 1024) {
          throw new Error('File size exceeds 10 MB');
        }

        return readFileAsync(filePath, 'utf8');
      } catch (error) {
        console.error(`Error processing file ${file}:`, error);
        return null;
      }
    }));

    const result = fileContents.filter(content => content !== null);

    if (result.length > 10000) {
      throw new Error('Too many files processed');
    }

    cache.set(key, result);
    return result;
  } catch (error) {
    console.error(`Error processing directory ${directory}:`, error);
    throw error;
  }
}
