const fs = require('fs');
const path = require('path');
const util = require('util');
const { exec } = require('child_process');

function loadModule(modulePath) {
  return require(path.resolve(__dirname, modulePath));
}

function logTestDetails(moduleName, testName, duration) {
  console.log(`Module: ${moduleName}, Test: ${testName}, Duration: ${duration}ms`);
}

async function runTests(module, testNames, retryCount = 3) {
  for (const testName of testNames) {
    let attempts = 0;
    while (attempts < retryCount) {
      try {
        const start = Date.now();
        await module[testName]();
        const duration = Date.now() - start;
        logTestDetails(module.name, testName, duration);
        break;
      } catch (error) {
        attempts++;
        if (attempts === retryCount) {
          console.error(`Test ${testName} failed after ${retryCount} attempts`);
        }
      }
    }
  }
}

async function sendResultsToExternalService(results) {
  const options = {
    method: 'POST',
    url: 'https://external-logging-service.com/api/results',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(results),
  };
  return new Promise((resolve, reject) => {
    exec(`curl ${util.inspect(options)}`, (error, stdout, stderr) => {
      if (error) {
        reject(error);
      } else {
        resolve(stdout);
      }
    });
  });
}

async function executeTests(modulePath, testNames, config = {}) {
  const module = loadModule(modulePath);
  const results = [];
  try {
    await runTests(module, testNames, config.retryCount || 3);
    results.push({ moduleName: module.name, tests: testNames.map(testName => ({ testName, status: 'success' })) });
  } catch (error) {
    results.push({ moduleName: module.name, tests: testNames.map(testName => ({ testName, status: 'failure', error: error.message })) });
  }
  await sendResultsToExternalService(results);
}

module.exports = executeTests;
