async function generateFooter(scripts) {
  if (scripts.length > 50) {
    throw new Error('Maximum of 50 scripts per footer allowed.');
  }

  const processedScripts = new Set();
  const log = [];

  for (const script of scripts) {
    if (!script.scriptId || !script.scriptContent) {
      throw new Error('Each script must have a unique identifier and content.');
    }
    if (processedScripts.has(script.scriptId)) {
      continue;
    }

    processedScripts.add(script.scriptId);
    log.push(script.scriptId);

    try {
      const scriptElement = document.createElement('script');
      scriptElement.id = `footer-script-${script.scriptId}`;
      scriptElement.textContent = script.scriptContent;

      // Check for existing footer with the same scriptId
      if (!document.getElementById(`footer-script-${script.scriptId}`)) {
        document.body.appendChild(scriptElement);
      }
    } catch (error) {
      console.error(`Error processing script ${script.scriptId}:`, error);
    }
  }

  return new Promise((resolve, reject) => {
    try {
      const htmlString = Array.from(document.querySelectorAll('script'))
        .filter(script => script.id.startsWith('footer-script-'))
        .map(script => script.outerHTML)
        .join('');

      resolve(htmlString);
    } catch (error) {
      reject(error);
    }
  });
}
