function refreshDialogFields(resourceId, url, fieldNames) {
  const MAX_RETRIES = 3;
  const BACKOFF_FACTOR = 2;

  function sendRequest(fieldName) {
    return new Promise((resolve, reject) => {
      let retries = 0;
      const attemptRequest = () => {
        fetch(`${url}/${resourceId}/${fieldName}`)
          .then(response => response.json())
          .then(data => {
            resolve({ fieldName, data });
          })
          .catch(error => {
            if (retries < MAX_RETRIES) {
              retries++;
              setTimeout(attemptRequest, BACKOFF_FACTOR ** retries * 100);
            } else {
              reject(new Error(`Failed to refresh ${fieldName} after ${MAX_RETRIES} attempts`));
            }
          });
      };
      attemptRequest();
    });
  }

  async function processFields() {
    try {
      const results = await Promise.all(fieldNames.map(sendRequest));
      fieldNames.forEach((fieldName, index) => {
        if (results.some(result => result.fieldName === fieldName)) {
          // Update the forward list in place
          fieldNames[index] = results.find(result => result.fieldName === fieldName).data;
        }
      });
    } catch (error) {
      console.error('Error refreshing dialog fields:', error);
    }
  }

  processFields();
}
