function traverseDOM(ancestorSelector, targetSelector, maxDepth = 10) {
    const results = [];
    let currentDepth = 0;

    function traverse(element) {
        if (currentDepth > maxDepth || !element) return;
        currentDepth++;

        if (element.matches(targetSelector)) {
            results.push(element);
        }

        for (let child of element.children) {
            traverse(child);
        }
        currentDepth--;
    }

    const ancestorElement = document.querySelector(ancestorSelector);
    if (ancestorElement) {
        traverse(ancestorElement);
    } else {
        console.warn('Ancestor element not found');
    }

    return results;
}
