class FileLoader {
  constructor(apiUrl) {
    this.apiUrl = apiUrl;
    this.fileCache = {};
    this.requestQueue = [];
    this.isProcessingRequest = false;
  }

  async loadFile(filename) {
    const uniqueFilename = this.generateUniqueFilename(filename);
    if (this.fileCache[uniqueFilename]) {
      return this.fileCache[uniqueFilename];
    }

    if (!this.isProcessingRequest) {
      this.processRequestQueue();
    }

    this.requestQueue.push(uniqueFilename);
  }

  async processRequestQueue() {
    this.isProcessingRequest = true;
    while (this.requestQueue.length > 0) {
      const filename = this.requestQueue.shift();
      try {
        const response = await fetch(`${this.apiUrl}/${filename}`);
        if (!response.ok) {
          throw new Error(`Failed to load file: ${filename}`);
        }
        const script = document.createElement('script');
        script.src = URL.createObjectURL(await response.blob());
        document.head.appendChild(script);
        this.fileCache[filename] = script;
      } catch (error) {
        console.error(error);
      }
    }
    this.isProcessingRequest = false;
  }

  generateUniqueFilename(filename) {
    const timestamp = Date.now();
    const digits = filename.match(/\d+/g).join('');
    return `${filename.replace(/\.\w+$/, '')}_${timestamp}_${digits}.js`;
  }
}

// Usage
const fileLoader = new FileLoader('https://api.example.com/files');
fileLoader.loadFile('example.js').then(script => {
  console.log('Script loaded:', script);
}).catch(error => {
  console.error('Error loading script:', error);
});
