public class LogProcessor {

    private final ConcurrentHashMap<String, EventStats> dailyEventStats = new ConcurrentHashMap<>();
    private final ExternalMetadataService metadataService = new ExternalMetadataService();
    private final MetadataCache metadataCache = new MetadataCache();

    public void processLogEntry(LogEntry entry) {
        String dayKey = getDayKey(entry.getTimestamp());
        EventStats stats = dailyEventStats.computeIfAbsent(dayKey, k -> new EventStats());

        try {
            EventMetadata metadata = fetchMetadata(entry.getEventId(), entry.getTimestamp());
            long processingTime = calculateProcessingTime(metadata);

            synchronized (stats) {
                stats.totalEvents.incrementAndGet();
                stats.totalProcessingTime.addAndGet(processingTime);
                stats.eventTypeCount.merge(entry.getEventType(), 1, Integer::sum);
            }
        } catch (Exception e) {
            // Log error and continue processing
            System.err.println("Error processing log entry: " + e.getMessage());
        }
    }

    private String getDayKey(LocalDateTime timestamp) {
        return timestamp.toLocalDate().toString();
    }

    private EventMetadata fetchMetadata(String eventId, LocalDateTime timestamp) throws Exception {
        EventMetadata cachedMetadata = metadataCache.get(eventId);
        if (cachedMetadata != null) {
            return cachedMetadata;
        }

        EventMetadata metadata = metadataService.fetchMetadata(eventId);
        if (metadata == null) {
            // Handle missing metadata gracefully
            metadata = new EventMetadata();
        }

        metadataCache.put(eventId, metadata);
        return metadata;
    }

    private long calculateProcessingTime(EventMetadata metadata) {
        // Simulate processing time calculation based on metadata
        return metadata.getComplexity() * 10; // Example calculation
    }

    public void printDailyStats() {
        for (EventStats stats : dailyEventStats.values()) {
            System.out.println("Day: " + stats.dayKey);
            for (String eventType : stats.eventTypeCount.keySet()) {
                double averageProcessingTime = (double) stats.totalProcessingTime.get() / stats.eventTypeCount.get(eventType);
                System.out.printf("  Event Type: %s, Average Processing Time: %.2f\n", eventType, averageProcessingTime);
            }
        }
    }

    private static class EventStats {
        final String dayKey;
        final AtomicInteger totalEvents = new AtomicInteger();
        final AtomicLong totalProcessingTime = new AtomicLong();
        final ConcurrentHashMap<String, Integer> eventTypeCount = new ConcurrentHashMap<>();

        EventStats() {
            this.dayKey = getDayKey(LocalDateTime.now());
        }
    }

    private static class EventMetadata {
        int complexity;

        // Getters and setters
        public int getComplexity() {
            return complexity;
        }

        public void setComplexity(int complexity) {
            this.complexity = complexity;
        }
    }

    private static class ExternalMetadataService {
        public EventMetadata fetchMetadata(String eventId) throws Exception {
            // Simulate external service call
            Thread.sleep(10); // Simulate delay
            return new EventMetadata();
        }
    }

    private static class MetadataCache {
        private final ConcurrentHashMap<String, EventMetadata> cache = new ConcurrentHashMap<>();

        public EventMetadata get(String eventId) {
            return cache.get(eventId);
        }

        public void put(String eventId, EventMetadata metadata) {
            cache.put(eventId, metadata);
        }
    }
