import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Set;

public class NioClientService {

    private Selector selector;
    private SocketChannel channel;
    private ByteBuffer buffer = ByteBuffer.allocate(1024);
    private int connectionTimeout;

    public NioClientService(String serverAddress, int port, int connectionTimeout) throws IOException {
        this.connectionTimeout = connectionTimeout;
        selector = Selector.open();
        channel = SocketChannel.open(new InetSocketAddress(serverAddress, port));
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_CONNECT);
        connect();
    }

    private void connect() throws IOException {
        if (channel.isConnectionPending()) {
            channel.finishConnect();
        }
        channel.register(selector, SelectionKey.OP_READ | SelectionKey.OP_WRITE);
    }

    public void send(String message) throws IOException {
        buffer.clear();
        buffer.put(message.getBytes());
        buffer.flip();
        channel.write(buffer);
    }

    public String receive() throws IOException {
        buffer.clear();
        int bytesRead = channel.read(buffer);
        if (bytesRead == -1) {
            throw new IOException("Connection closed by server");
        }
        return new String(buffer.array(), 0, bytesRead);
    }

    public void run() {
        try {
            while (true) {
                selector.select(connectionTimeout);
                Set<SelectionKey> selectedKeys = selector.selectedKeys();
                Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

                while (keyIterator.hasNext()) {
                    SelectionKey key = keyIterator.next();

                    if (key.isConnectable()) {
                        connect();
                    }

                    if (key.isReadable()) {
                        receiveData(key);
                    }

                    if (key.isWritable()) {
                        sendData(key);
                    }

                    keyIterator.remove();
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void receiveData(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        buffer.clear();
        int bytesRead = channel.read(buffer);
        if (bytesRead == -1) {
            channel.close();
        } else if (bytesRead > 0) {
            buffer.flip();
            byte[] data = new byte[buffer.remaining()];
            buffer.get(data);
            System.out.println("Received: " + new String(data));
        }
    }

    private void sendData(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();
        if (channel.isWritable()) {
            buffer.clear();
            buffer.put("Hello Server".getBytes());
            buffer.flip();
            channel.write(buffer);
        }
    }

    public static void main(String[] args) {
        try {
            NioClientService client = new NioClientService("localhost", 8080, 5000);
            client.run();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
