public class ThemeCache {
    private Map<String, Bitmap> cache = new HashMap<>();
    private File cacheRootDir;
    private int maxMemory;
    private float scaleFactor;

    public ThemeCache(File cacheRootDir, int maxMemory, float scaleFactor) {
        this.cacheRootDir = cacheRootDir;
        this.maxMemory = maxMemory;
        this.scaleFactor = scaleFactor;
    }

    public void loadThemes() {
        File[] files = cacheRootDir.listFiles((dir, name) -> name.endsWith(".png"));
        if (files != null) {
            for (File file : files) {
                Bitmap bitmap = decodeSampledBitmapFromFile(file.getAbsolutePath(), 1024, 1024);
                cache.put(file.getName(), bitmap);
            }
        }
    }

    public Bitmap getTheme(String themeName) {
        Bitmap bitmap = cache.get(themeName);
        if (bitmap == null) {
            File file = new File(cacheRootDir, themeName + ".png");
            if (file.exists()) {
                bitmap = decodeSampledBitmapFromFile(file.getAbsolutePath(), 1024, 1024);
                cache.put(themeName, bitmap);
            }
        }
        return bitmap;
    }

    private Bitmap decodeSampledBitmapFromFile(String filePath, int reqWidth, int reqHeight) {
        // Decode image size
        BitmapFactory.Options options = new BitmapFactory.Options();
        options.inJustDecodeBounds = true;
        BitmapFactory.decodeFile(filePath, options);

        // Calculate inSampleSize
        options.inSampleSize = calculateInSampleSize(options, reqWidth, reqHeight);

        // Decode bitmap with inSampleSize set
        options.inJustDecodeBounds = false;
        return BitmapFactory.decodeFile(filePath, options);
    }

    private int calculateInSampleSize(BitmapFactory.Options options, int reqWidth, int reqHeight) {
        final int height = options.outHeight;
        final int width = options.outWidth;
        int inSampleSize = 1;

        if (height > reqHeight || width > reqWidth) {
            final int halfHeight = height / 2;
            final int halfWidth = width / 2;

            while ((halfHeight / inSampleSize) >= reqHeight && (halfWidth / inSampleSize) >= reqWidth) {
                inSampleSize *= 2;
            }
        }

        return inSampleSize;
    }

