import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private ScheduledExecutorService scheduler;
    private int startInterval;
    private int stopInterval;
    private boolean isRunning = false;
    private ExternalDependencyChecker dependencyChecker;

    public ServiceManager(int startInterval, int stopInterval) {
        this.startInterval = startInterval;
        this.stopInterval = stopInterval;
        this.scheduler = Executors.newScheduledThreadPool(2);
        this.dependencyChecker = new ExternalDependencyChecker();
    }

    public void startService() {
        if (!isRunning) {
            isRunning = true;
            scheduler.scheduleAtFixedRate(this::start, 0, startInterval, TimeUnit.SECONDS);
            scheduler.scheduleAtFixedRate(this::stop, 0, stopInterval, TimeUnit.SECONDS);
        }
    }

    private void start() {
        try {
            logServiceEvent("Starting service");
            if (dependencyChecker.isHealthy()) {
                // Start the actual service logic here
                System.out.println("Service started successfully");
            } else {
                logServiceEvent("Failed to start due to external dependency issues");
            }
        } catch (Exception e) {
            handleStartFailure(e);
        }
    }

    private void stop() {
        if (isRunning) {
            isRunning = false;
            try {
                logServiceEvent("Stopping service");
                // Stop the actual service logic here
                System.out.println("Service stopped successfully");
                sendHealthReport();
            } catch (Exception e) {
                handleStopFailure(e);
            }
        }
    }

    private void logServiceEvent(String message) {
        System.out.println("[" + System.currentTimeMillis() + "] " + message);
    }

    private void handleStartFailure(Exception e) {
        // Implement retry logic and error handling here
        System.out.println("Failed to start service: " + e.getMessage());
    }

    private void handleStopFailure(Exception e) {
        // Implement cleanup and error handling here
        System.out.println("Failed to stop service: " + e.getMessage());
    }

    private void sendHealthReport() {
        // Send health report to external monitoring system
        System.out.println("Sending health report");
    }

    public void setIntervals(int startInterval, int stopInterval) {
        this.startInterval = startInterval;
        this.stopInterval = stopInterval;
        if (isRunning) {
            scheduler.shutdown();
            scheduler = Executors.newScheduledThreadPool(2);
            startService();
        }
    }

    public static void main(String[] args) {
        ServiceManager serviceManager = new ServiceManager(10, 30);
        Runtime.getRuntime().addShutdownHook(new Thread(serviceManager::stopService));
        serviceManager.startService();
    }
}

class ExternalDependencyChecker {
    public boolean isHealthy() {
        // Check external dependencies here
        return true;
    }
}
