use hyper::{Client, Uri};
use hyper_tls::HttpsConnector;
use tokio::time::Duration;
use tracing::{error, info};

#[derive(Debug)]
struct HttpClientConfig {
    certificate_validation: bool,
    connection_pool_limit: usize,
    retry_policy: RetryPolicy,
}

#[derive(Debug)]
enum RetryPolicy {
    Fixed(u32),
    ExponentialBackoff { initial_delay: Duration, max_delay: Duration },
}

fn create_http_client(config: HttpClientConfig) -> Client<HttpsConnector> {
    let https = HttpsConnector::new();
    let client = Client::builder()
        .pool_max_idle_per_host(config.connection_pool_limit)
        .build(https);

    client
}

async fn send_request(client: &Client<HttpsConnector>, uri: Uri) -> Result<(), Box<dyn std::error::Error>> {
    let response = client.get(uri).await?;
    if response.status().is_success() {
        info!("Request successful");
    } else {
        error!("Request failed with status: {}", response.status());
    }
    Ok(())
}

fn main() {
    let config = HttpClientConfig {
        certificate_validation: true,
        connection_pool_limit: 100,
        retry_policy: RetryPolicy::Fixed(3),
    };

    let client = create_http_client(config);
    let uri = Uri::from_static("https://example.com");

    tokio::runtime::Runtime::new().unwrap().block_on(async move {
        if let Err(e) = send_request(&client, uri).await {
            error!("Error sending request: {}", e);
        }
    });
}
