use std::process::{Command, Stdio};
use std::time::{Instant, SystemTime};
use libc::{getrusage, RUSAGE_SELF, struct_rusage};
use std::ffi::CString;
use std::os::unix::ffi::OsStrExt;

fn get_resident_set_size() -> Option<usize> {
    unsafe {
        let mut usage = std::mem::zeroed();
        if getrusage(RUSAGE_SELF, &mut usage) == 0 {
            Some(usage.ru_maxrss as usize * 1024)
        } else {
            None
        }
    }
}

fn compile_with_metrics() -> i32 {
    let start_time = Instant::now();
    let start_rss = get_resident_set_size();

    let output = Command::new("rustc")
        .arg("--crate-type=bin")
        .arg("main.rs")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to execute command");

    let status = output.wait().expect("Failed to wait on child");
    let end_rss = get_resident_set_size();

    if let Some(start_rss) = start_rss {
        println!("Compilation time: {:?}", start_time.elapsed());
        println!("Initial RSS: {} KB", start_rss);
        if let Some(end_rss) = end_rss {
            println!("Final RSS: {} KB", end_rss);
        }
    }

    status.code().unwrap_or(1)
}
