<?php

function updateUserProfile($userId, $email, $phone, $address) {
    $apiEndpoints = [
        'email' => 'https://api.example.com/updateEmail',
        'phone' => 'https://api.example.com/updatePhone',
        'address' => 'https://api.example.com/updateAddress'
    ];

    $logFile = '/path/to/logfile.log';

    $updates = [];
    foreach ($apiEndpoints as $field => $endpoint) {
        try {
            $response = makeApiRequest($endpoint, [
                'user_id' => $userId,
                $field => $$field
            ], 3);

            if ($response['success']) {
                $updates[$field] = ['status' => 'success', 'message' => $response['message']];
            } else {
                $updates[$field] = ['status' => 'failure', 'message' => $response['error']];
            }
        } catch (Exception $e) {
            $updates[$field] = ['status' => 'failure', 'message' => $e->getMessage()];
        }

        logUpdate($logFile, $userId, $field, $updates[$field]['status'], $updates[$field]['message']);
    }

    return $updates;
}

function makeApiRequest($url, $data, $maxRetries = 3) {
    for ($retry = 0; $retry <= $maxRetries; $retry++) {
        try {
            $options = [
                'http' => [
                    'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
                    'method'  => 'POST',
                    'content' => http_build_query($data)
                ]
            ];
            $context  = stream_context_create($options);
            $response = file_get_contents($url, false, $context);

            if ($response === FALSE) {
                throw new Exception('Network failure');
            }

            return json_decode($response, true);
        } catch (Exception $e) {
            if ($retry == $maxRetries) {
                throw $e;
            }
            sleep(pow(2, $retry));
        }
    }
}

function logUpdate($logFile, $userId, $field, $status, $message) {
    $timestamp = date('Y-m-d H:i:s');
    file_put_contents($logFile, "$timestamp - User ID: $userId, Field: $field, Status: $status, Message: $message\n", FILE_APPEND);
}
