<?php

session_start();

function authenticateAndResolve($provider, $clientId, $clientSecret, $redirectUri, $code) {
    // OAuth 2.0 Authentication
    $tokenUrl = "https://$provider/oauth/token";
    $params = [
        'grant_type' => 'authorization_code',
        'client_id' => $clientId,
        'client_secret' => $clientSecret,
        'redirect_uri' => $redirectUri,
        'code' => $code
    ];

    $ch = curl_init($tokenUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($params));
    $response = curl_exec($ch);
    if (curl_errno($ch)) {
        error_log('OAuth 2.0 Token Request Error: ' . curl_error($ch));
        return false;
    }
    $tokenData = json_decode($response, true);

    // Store Access Token in Session
    $_SESSION['access_token'] = $tokenData['access_token'];

    // Retrieve User-Specific Information
    $userInfoUrl = "https://$provider/userinfo";
    $headers = [
        'Authorization: Bearer ' . $_SESSION['access_token']
    ];
    curl_setopt($ch, CURLOPT_URL, $userInfoUrl);
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    $userResponse = curl_exec($ch);
    if (curl_errno($ch)) {
        error_log('User Info Request Error: ' . curl_error($ch));
        return false;
    }
    $userData = json_decode($userResponse, true);

    // DNS Resolution
    $domain = $userData['custom_domain'];
    $ipAddress = gethostbyname($domain);
    if (filter_var($ipAddress, FILTER_VALIDATE_IP) === false) {
        error_log('DNS Resolution Error: Invalid IP address');
        return false;
    }

    return $ipAddress;
}

// Example Usage
$provider = 'example.com';
$clientId = 'your_client_id';
$clientSecret = 'your_client_secret';
$redirectUri = 'http://yourdomain.com/callback.php';
$code = $_GET['code'];

$ip = authenticateAndResolve($provider, $clientId, $clientSecret, $redirectUri, $code);
if ($ip) {
    echo "IP Address: $ip";
} else {
    echo "Authentication or DNS resolution failed.";
}
