    return 1; // Return 1 if valid, 0 otherwise
}

StateManager* init_state_manager(FSA* fsa) {
    StateManager* manager = (StateManager*)malloc(sizeof(StateManager));
    if (manager == NULL) {
        return NULL;
    }
    pthread_mutex_init(&manager->lock, NULL);
    manager->state_sequence = NULL;
    manager->last_state_id = 0;
    manager->cache_valid = 0;
    manager->fsa = fsa;
    return manager;
}

State* add_state(StateManager* manager, int state_id) {
    pthread_mutex_lock(&manager->lock);

    if (!manager->cache_valid) {
        // Fetch and cache the latest validation rules from the external service
        // This is a placeholder for actual implementation
        manager->cache_valid = 1;
    }

    if (!validate_state(manager->fsa, state_id)) {
        pthread_mutex_unlock(&manager->lock);
        return NULL; // State is invalid
    }

    State* new_state = create_state(state_id);
    if (new_state == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return NULL; // Memory allocation failed
    }

    if (manager->state_sequence == NULL) {
        manager->state_sequence = new_state;
    } else {
        State* current = manager->state_sequence;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_state;
    }

    manager->last_state_id = state_id;

    pthread_mutex_unlock(&manager->lock);
    return new_state;
}

void free_state_manager(StateManager* manager) {
    State* current = manager->state_sequence;
    while (current != NULL) {
        State* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
