#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKETS 1000

typedef struct {
    int sequence_number;
    unsigned char payload[1500];
    size_t payload_size;
    time_t timestamp;
} Packet;

unsigned int process_packets(Packet packets[], int packet_count, Packet *highest_checksum_packet) {
    if (packet_count == 0) return 0;

    unsigned int highest_checksum = 0;
    for (int i = 0; i < packet_count; i++) {
        // Calculate payload checksum
        unsigned int checksum = 0;
        for (size_t j = 0; j < packets[i].payload_size; j++) {
            checksum += packets[i].payload[j];
        }

        if (checksum > highest_checksum) {
            highest_checksum = checksum;
            *highest_checksum_packet = packets[i];
        }
    }

    return highest_checksum;
