public class DynamicValueGenerator
{
    private float _minFloatRange = 0f;
    private float _maxFloatRange = 1f;
    private int _minIntRange = 0;
    private int _maxIntRange = 100;
    private Random _random;

    public DynamicValueGenerator()
    {
        _random = new Random();
    }

    public void SetRange(float minFloat, float maxFloat, int minInt, int maxInt)
    {
        if (minFloat >= maxFloat || minInt >= maxInt)
        {
            Debug.LogWarning("Invalid range provided. Adjusting to default values.");
            _minFloatRange = 0f;
            _maxFloatRange = 1f;
            _minIntRange = 0;
            _maxIntRange = 100;
        }
        else
        {
            _minFloatRange = minFloat;
            _maxFloatRange = maxFloat;
            _minIntRange = minInt;
            _maxIntRange = maxInt;
        }
    }

    public float GetRandomFloat(bool inclusive)
    {
        return inclusive ? UnityEngine.Random.Range(_minFloatRange, _maxFloatRange) : UnityEngine.Random.Range(_minFloatRange, _maxFloatRange);
    }

    public int GetRandomInt(bool inclusive)
    {
        if (inclusive)
        {
            return _random.Next(_minIntRange, _maxIntRange + 1);
        }
        else
        {
            return _random.Next(_minIntRange, _maxIntRange);
        }
    }

    public List<float> GenerateSampleValues(int count = 10)
    {
        List<float> sampleValues = new List<float>();
        for (int i = 0; i < count; i++)
        {
            sampleValues.Add(GetRandomFloat(true));
        }
        return sampleValues;
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator - Float Range: {_minFloatRange} to {_maxFloatRange}, Int Range: {_minIntRange} to {_maxIntRange}";
    }
}
