async function asyncReduce(array, initialValue, callback) {
  // Type checking
  if (!Array.isArray(array) || array.some(isNaN)) throw new Error('Invalid input: array must contain only numbers');
  if (isNaN(initialValue)) throw new Error('Invalid input: initial value must be a number');

  let result = initialValue;
  for (let i = 0; i < array.length; i++) {
    try {
      const timeoutPromise = new Promise((resolve, reject) => {
        setTimeout(() => resolve(), 5000); // 5 seconds per element
      });

      const callbackResult = await Promise.race([callback(result, array[i]), timeoutPromise]);
      result = callbackResult;
    } catch (error) {
      console.error(`Error processing element at index ${i}:`, error);
      // Handle error, e.g., retry or alternative processing
    }
  }

  return result;
}

// Example usage:
const numbers = Array.from({ length: 10000 }, (_, i) => Math.random() * 100);
asyncReduce(numbers, 0, (acc, num) => acc + num)
  .then(result => console.log('Reduced value:', result))
  .catch(error => console.error('Error during reduction:', error));
