#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONFIG_SIZE 1024 * 1024 // 1 MB

typedef struct {
    char *key;
    char *value;
} ConfigSetting;

typedef struct {
    ConfigSetting **settings;
    size_t count;
    size_t capacity;
} ConfigList;

ConfigList* load_config(const char *ip, int port) {
    ConfigList *config = (ConfigList*)malloc(sizeof(ConfigList));
    config->settings = NULL;
    config->count = 0;
    config->capacity = 0;

    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        free(config);
        return NULL;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        free(config);
        return NULL;
    }

    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(sockfd);
        free(config);
        return NULL;
    }

    char *buffer = (char*)malloc(MAX_CONFIG_SIZE);
    ssize_t bytes_received = recv(sockfd, buffer, MAX_CONFIG_SIZE - 1, 0);
    if (bytes_received <= 0) {
        perror("Failed to receive data");
        close(sockfd);
        free(buffer);
        free(config);
        return NULL;
    }

    buffer[bytes_received] = '\0';
    close(sockfd);

    char *line = strtok(buffer, "\n");
    while (line != NULL) {
        if (config->count >= config->capacity) {
            config->capacity = (config->capacity == 0) ? 1 : config->capacity * 2;
            config->settings = (ConfigSetting**)realloc(config->settings, config->capacity * sizeof(ConfigSetting*));
        }

        char *key_value = strtok(line, "=");
        if (key_value != NULL) {
            ConfigSetting *setting = (ConfigSetting*)malloc(sizeof(ConfigSetting));
            setting->key = strdup(key_value);

            key_value = strtok(NULL, "=");
            if (key_value != NULL) {
                setting->value = strdup(key_value);
                config->settings[config->count++] = setting;
            } else {
                free(setting->key);
                free(setting);
            }
        }

        line = strtok(NULL, "\n");
    }

    free(buffer);
    return config;
}

void iterate_config(ConfigList *config) {
    for (size_t i = 0; i < config->count; ++i) {
        printf("Key: %s, Value: %s\n", config->settings[i]->key, config->settings[i]->value);
    }
}

void free_config(ConfigList *config) {
    for (size_t i = 0; i < config->count; ++i) {
        free(config->settings[i]->key);
        free(config->settings[i]->value);
        free(config->settings[i]);
    }
    free(config->settings);
    free(config);
}
