Theme *cache[CACHE_SIZE_LIMIT];
int cache_count = 0;

void load_theme_from_file(const char *file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) return;

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        Theme *theme = malloc(sizeof(Theme));
        theme->theme_name = strdup(strtok(line, ":"));
        theme->bitmap_path = strdup(strtok(NULL, ":"));
        theme->last_accessed = time(NULL);
        cache[cache_count++] = theme;
    }
    fclose(file);
}

void update_theme_cache() {
    for (int i = 0; i < cache_count; i++) {
        if (time(NULL) - cache[i]->last_accessed > TIMEOUT_SECONDS) {
            free(cache[i]->theme_name);
            free(cache[i]->bitmap_path);
            free(cache[i]);
            memmove(&cache[i], &cache[i + 1], sizeof(Theme *) * (cache_count - i - 1));
            cache_count--;
            i--;
        }
    }
}

