EVP_CIPHER_CTX* init_aes_256_cbc(const char* password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    unsigned char key[32];
    unsigned char iv[16];

    // Derive the encryption key using SHA-256
    SHA256((unsigned char*)password, strlen(password), key);

    // Generate a random IV
    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize the cipher context for encryption
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
