#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>

void execute_command_in_background(const char *command, int timeout) {
    pid_t pid;
    int status;

    // Fork a new process to run the command in the background
    pid = fork();
    if (pid == -1) {
        perror("fork");
        return;
    } else if (pid == 0) {
        // Child process: Execute the command
        execl("/bin/sh", "sh", "-c", command, NULL);
        perror("execl"); // This line should never be reached if execl succeeds
        exit(EXIT_FAILURE);
    }

    // Parent process: Monitor the child process
    alarm(timeout); // Set an alarm for the timeout

    while (1) {
        pid_t terminated_pid = waitpid(pid, &status, WNOHANG);
        if (terminated_pid == -1) {
            perror("waitpid");
            return;
        } else if (terminated_pid == 0) {
            sleep(1); // Wait for the child process to finish
        } else {
            if (WIFEXITED(status)) {
                printf("Command exited with status %d\n", WEXITSTATUS(status));
            } else if (WIFSIGNALED(status)) {
                printf("Command terminated by signal %d\n", WTERMSIG(status));
            }
            alarm(0); // Reset the alarm
            return;
        }
    }
}

int main() {
    const char *command = "sleep 10";
    int timeout = 5;

    execute_command_in_background(command, timeout);

    return 0;
}
```

This code snippet provides a basic implementation of a function that executes an external command in the background and monitors its execution. It uses `fork()` to create a new process for the command, `execl()` to run the command, and `waitpid()` with `WNOHANG` to check if the command has finished executing. The `alarm()` function is used to set a timeout for the command's execution.

