using System;
using System.Diagnostics;
using System.IO;
using System.Collections.Generic;

public class WebAppIntegrator
{
    public static Process IntegrateWebApplication(string directoryPath, string siteName, Dictionary<string, string> environmentVariables)
    {
        // Validate web.config file
        if (!ValidateWebConfig(directoryPath))
        {
            LogError("web.config is missing or malformed.");
            return null;
        }

        // Set up process start information
        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = "dotnet",
            Arguments = $"run --project {directoryPath}",
            WorkingDirectory = directoryPath,
            EnvironmentVariables = environmentVariables,
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        // Start the process
        Process process = new Process { StartInfo = startInfo };
        try
        {
            process.Start();
            LogInfo($"Web application started with PID: {process.Id}");

            // Handle output and errors
            process.OutputDataReceived += (sender, e) => LogInfo(e.Data);
            process.ErrorDataReceived += (sender, e) => LogError(e.Data);

            process.BeginOutputReadLine();
            process.BeginErrorReadLine();

            return process;
        }
        catch (Exception ex)
        {
            LogError($"Failed to start web application: {ex.Message}");
            return null;
        }
    }

    private static bool ValidateWebConfig(string directoryPath)
    {
        string configPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(configPath))
        {
            LogError("web.config file not found.");
            return false;
        }

        try
