using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class MessageProcessor
{
    private readonly byte[] _encryptionKey;
    private readonly byte[] _hmacKey;
    private const int MaxDecryptionAttempts = 5;

    public MessageProcessor(byte[] encryptionKey, byte[] hmacKey)
    {
        _encryptionKey = encryptionKey;
        _hmacKey = hmacKey;
    }

    public string ProcessMessage(string base64EncodedMessage, byte[] aad, byte[] signature)
    {
        try
        {
            if (!ValidateSignature(base64EncodedMessage, aad, signature))
                return "Validation failed: Signature is invalid.";

            byte[] decodedMessage = Convert.FromBase64String(base64EncodedMessage);
            int ivLength = 8; // Example IV length, adjust as needed

            for (int attempt = 0; attempt < MaxDecryptionAttempts; attempt++)
            {
                try
                {
                    byte[] decryptedBytes = DecryptMessage(decodedMessage, ivLength);
                    return Encoding.UTF8.GetString(decryptedBytes);
                }
                catch (Exception ex)
                {
                    if (attempt == MaxDecryptionAttempts - 1)
                        throw;
                    // Log error and retry
                    Console.WriteLine($"Decryption attempt {attempt + 1} failed: {ex.Message}");
                }
            }

            return "Failure: Maximum decryption attempts reached.";
        }
        catch (Exception ex)
        {
            // Log detailed error information
            Console.WriteLine($"Error processing message: {ex.Message}");
            return "Failure: An unexpected error occurred.";
        }
    }

    private bool ValidateSignature(string base64EncodedMessage, byte[] aad, byte[] signature)
    {
        using (HMACSHA256 hmac = new HMACSHA256(_hmacKey))
        {
            byte[] messageBytes = Convert.FromBase64String(base64EncodedMessage);
            byte[] computedSignature = hmac.ComputeHash(messageBytes, 0, messageBytes.Length - ivLength);

            return computedSignature.SequenceEqual(signature);
        }
    }

    private byte[] DecryptMessage(byte[] encodedMessage, int ivLength)
    {
        using (TripleDES tdes = TripleDES.Create())
        {
            tdes.Key = _encryptionKey;
            tdes.IV = new byte[ivLength]; // Initialize IV as needed

            ICryptoTransform decryptor = tdes.CreateDecryptor(tdes.Key, tdes.IV);
            using (MemoryStream msDecrypt = new MemoryStream(encodedMessage))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (MemoryStream msOutput = new MemoryStream())
                    {
                        csDecrypt.CopyTo(msOutput);
                        return msOutput.ToArray();
                    }
                }
            }
        }
    }
}
