using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class FileProcessor
{
    private readonly int _minFileSize;
    private readonly ILogger _logger;

    public FileProcessor(int minFileSize, ILogger logger)
    {
        _minFileSize = minFileSize;
        _logger = logger;
    }

    public async Task ProcessFilesAsync(List<string> filePaths)
    {
        var tasks = new List<Task>();

        foreach (var filePath in filePaths)
        {
            if (File.Exists(filePath) && new FileInfo(filePath).Length >= _minFileSize)
            {
                tasks.Add(ProcessFileAsync(filePath));
            }
        }

        await Task.WhenAll(tasks);
    }

    private async Task ProcessFileAsync(string filePath)
    {
        try
        {
            var content = await File.ReadAllTextAsync(filePath);
            var hash = GenerateSHA256Hash(content);

            _logger.Log($"Processed file: {filePath}, Hash: {hash}");
        }
        catch (Exception ex)
        {
            _logger.LogError($"Error processing file: {filePath}, Error: {ex.Message}");
        }
    }

    private string GenerateSHA256Hash(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < bytes.Length; i++)
            {
                builder.Append(bytes[i].ToString("x2"));
            }
            return builder.ToString();
        }
    }
}

public interface ILogger
{
    void Log(string message);
    void LogError(string error);
}

public class ConsoleLogger : ILogger
{
    public void Log(string message)
    {
        Console.WriteLine(message);
    }

    public void LogError(string error)
    {
        Console.Error.WriteLine(error);
    }
}
```

