        aes.IV = Convert.FromBase64String(iv);
        aes.Padding = paddingMode;
        _cryptoTransforms[keyId] = aes.CreateDecryptor(aes.Key, aes.IV);
    }

    public byte[] Decrypt(byte[] ciphertext, string keyId)
