using System;
using System.IO;
using System.IO.Compression;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading.Tasks;

public class DataCache
{
    private readonly Dictionary<string, object> _cache = new Dictionary<string, object>();
    private readonly object _lock = new object();

    public async Task<T> LoadAndDeserializeAsync<T>(string filePath)
    {
        if (_cache.ContainsKey(filePath))
        {
            return (T)_cache[filePath];
        }

        lock (_lock)
        {
            if (_cache.ContainsKey(filePath))
            {
                return (T)_cache[filePath];
            }
        }

        T data;
        using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, bufferSize: 4096, useAsync: true))
        {
            var compressionMethod = GetCompressionMethod(stream);
            switch (compressionMethod)
            {
                case CompressionMethod.GZip:
                    data = await DecompressAndDeserializeAsync<T>(stream, DecompressionStream.Create(stream));
                    break;
                case CompressionMethod.Deflate:
                    data = await DecompressAndDeserializeAsync<T>(stream, new DeflateStream(stream, CompressionMode.Decompress));
                    break;
                default:
                    throw new NotSupportedException("Unsupported compression method.");
            }
        }

        lock (_lock)
        {
            _cache[filePath] = data;
        }

        return data;
    }

    private async Task<T> DecompressAndDeserializeAsync<T>(Stream compressedStream, Stream decompressedStream)
    {
        var formatter = new BinaryFormatter();
        using (var memoryStream = new MemoryStream())
        {
            await decompressedStream.CopyToAsync(memoryStream);
            memoryStream.Position = 0;
            return (T)formatter.Deserialize(memoryStream);
        }
    }

    private CompressionMethod GetCompressionMethod(Stream stream)
    {
        // Implement logic to detect the compression method
        throw new NotImplementedException();
    }
}

public enum CompressionMethod
{
    GZip,
    Deflate
}
