long* allocateLongArray(int size) {
    long* array = (long*)malloc(size * sizeof(long));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for long array\n");
        return (long*)calloc(size / 2, sizeof(long)); // Fallback to half the size
    }
    return array;
}

int* allocateIntArray(int size) {
    int* array = (int*)malloc(size * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for int array\n");
        return (int*)calloc(size / 2, sizeof(int)); // Fallback to half the size
    }
    return array;
}

record* allocateRecordArray(int size) {
    record* array = (record*)malloc(size * sizeof(record));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for record array\n");
        return (record*)calloc(size / 2, sizeof(record)); // Fallback to half the size
    }
    return array;
}

void initializeArrays(long* offsets, int* keys, record* records, int size) {
    for (int i = 0; i < size; i++) {
        offsets[i] = rand();
        keys[i] = rand();
        records[i].value = rand();
        records[i].status = 1;
    }
}

void cleanupArrays(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}
