// Create a connection pool for MySQL
const mysqlPool = mysql.createPool({
  host: 'localhost',
  user: 'user',
  password: 'password',
  database: 'database',
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

// Create a connection pool for PostgreSQL
const pgPool = new Pool({
  user: 'user',
  host: 'localhost',
  database: 'database',
  password: 'password',
  port: 5432,
  max: 10,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000
});

async function updateUserProfile(userId, updates) {
  let connection;
  try {
    // Acquire a connection from the pool
    if (process.env.DB_TYPE === 'mysql') {
      connection = await mysqlPool.getConnection();
    } else if (process.env.DB_TYPE === 'postgres') {
      connection = await pgPool.connect();
    }

    // Start a transaction
    await connection.beginTransaction();

    // Prepare and execute update queries
    for (const [key, value] of Object.entries(updates)) {
      const query = `UPDATE users SET ${key} = ? WHERE id = ?`;
      await connection.execute(query, [value, userId]);
    }

    // Commit the transaction
    await connection.commit();
  } catch (error) {
    if (connection) {
      try {
        // Rollback the transaction on error
        await connection.rollback();
      } catch (rollbackError) {
        console.error('Failed to rollback transaction:', rollbackError);
      }
    }
    console.error('Update failed:', error);
    throw error;
  } finally {
    if (connection) {
      // Release the connection back to the pool
      if (process.env.DB_TYPE === 'mysql') {
        connection.release();
      } else if (process.env.DB_TYPE === 'postgres') {
        connection.release();
      }
    }
  }
}

// Example usage:
(async () => {
  try {
    await updateUserProfile(1, { name: 'John Doe', email: 'john.doe@example.com' });
    console.log('User profile updated successfully');
  } catch (error) {
    console.error('Error updating user profile:', error);
  }
})();
```

This code snippet demonstrates a scalable and efficient JavaScript function for updating user profiles in a relational database. It uses connection pooling, handles transaction management, and includes basic error recovery and logging. The function is designed to be easily extendable and maintainable, with considerations for performance optimization and future integration points."]

