import json
from typing import Any, Callable, Dict, Type, Union

class DynamicJSONParser:
    _factory_registry: Dict[str, Callable[[Dict], Any]] = {}

    @classmethod
    def add_factory(cls, factory_id: str, factory_func: Callable[[Dict], Any]):
        cls._factory_registry[factory_id] = factory_func

    @classmethod
    def get_factory(cls, factory_id: str) -> Callable[[Dict], Any]:
        return cls._factory_registry.get(factory_id)

    @staticmethod
    def validate_json(json_data: Dict, schema: Dict[str, Type]):
        for key, expected_type in schema.items():
            if key not in json_data or not isinstance(json_data[key], expected_type):
                raise ValueError(f"Invalid JSON data: {json_data}")

    @classmethod
    def parse_json(cls, json_str: str, factory_id: str, schema: Dict[str, Type]) -> Any:
        try:
            json_data = json.loads(json_str)
            cls.validate_json(json_data, schema)
            factory_func = cls.get_factory(factory_id)
            if not factory_func:
                raise ValueError(f"Factory function for ID '{factory_id}' not found")
            return factory_func(json_data)
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON format: {e}")
        except Exception as e:
            raise ValueError(f"Error during parsing: {e}")

# Example usage
class User:
    def __init__(self, name: str, age: int):
        self.name = name
        self.age = age

def user_factory(data: Dict) -> User:
    return User(name=data['name'], age=data['age'])

DynamicJSONParser.add_factory('user', user_factory)

schema = {
    'name': str,
    'age': int
}

json_str = '{"name": "John", "age": 30}'
parsed_user = DynamicJSONParser.parse_json(json_str, 'user', schema)
print(parsed_user.name, parsed_user.age)  # Output: John 30
