#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MAX_VALUE 100

typedef struct {
    int value;
} Record;

typedef struct {
    Record *records;
    long *offsets;
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager(size_t max_size) {
    RecordManager *manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record*)malloc(max_size * sizeof(Record));
    manager->offsets = (long*)malloc(max_size * sizeof(long));
    manager->count = 0;
    manager->max_size = max_size;
    pthread_mutex_init(&manager->lock, NULL);

    if (!manager->records || !manager->offsets) {
        free(manager->records);
        free(manager->offsets);
        free(manager);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < max_size; ++i) {
        manager->records[i].value = rand() % (MAX_VALUE + 1);
        manager->offsets[i] = i * sizeof(Record);
    }

    return manager;
}

void destroy_record_manager(RecordManager *manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager->records);
    free(manager->offsets);
    free(manager);
}

int add_record(RecordManager *manager, int value) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->max_size) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Allocation failure
    }

    size_t index = manager->count;
    manager->records[index].value = value;
    manager->offsets[index] = index * sizeof(Record);
    manager->count++;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

int get_record_value(RecordManager *manager, size_t index) {
    if (index >= manager->count) return -1; // Invalid index

    pthread_mutex_lock(&manager->lock);
    int value = manager->records[index].value;
    pthread_mutex_unlock(&manager->lock);

    return value;
}

int set_record_value(RecordManager *manager, size_t index, int value) {
    if (index >= manager->count) return -1; // Invalid index

    pthread_mutex_lock(&manager->lock);
    manager->records[index].value = value;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}
