typedef struct {
    RrcConnectionReconfigurationIndication indication;
    RrcMessage *message;
} NFDataPdu_t;

typedef struct {
    NFDataPdu_t **array;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray_t;

DynamicArray_t* dynamic_array_create() {
    DynamicArray_t *array = malloc(sizeof(DynamicArray_t));
    array->array = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void dynamic_array_destroy(DynamicArray_t *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->array[i]->message);
        free(array->array[i]);
    }
    free(array->array);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void dynamic_array_add(DynamicArray_t *array, RrcConnectionReconfigurationIndication indication, RrcMessage *message) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity > 0 ? array->capacity * 2 : 1;
        NFDataPdu_t **new_array = realloc(array->array, new_capacity * sizeof(NFDataPdu_t *));
        if (!new_array) {
            pthread_mutex_unlock(&array->lock);
            return; // Handle memory allocation failure
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    NFDataPdu_t *pdu = malloc(sizeof(NFDataPdu_t));
    pdu->indication = indication;
    pdu->message = message;
    array->array[array->size++] = pdu;
    pthread_mutex_unlock(&array->lock);
}

void dynamic_array_update(DynamicArray_t *array, size_t index, RrcConnectionReconfigurationIndication indication, RrcMessage *message) {
    pthread_mutex_lock(&array->lock);
    if (index < array->size) {
        free(array->array[index]->message);
        array->array[index]->indication = indication;
        array->array[index]->message = message;
    }
    pthread_mutex_unlock(&array->lock);
}

void dynamic_array_process(DynamicArray_t *array, void (*process_message)(RrcMessage *)) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        process_message(array->array[i]->message);
    }
    pthread_mutex_unlock(&array->lock);
}

void dynamic_array_cleanup(DynamicArray_t *array) {
