#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 10000

typedef struct {
    sem_t *sems[MAX_SEMAPHORES];
    int count;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager() {
    SemaphoreManager *manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    if (!manager) {
        perror("Failed to allocate memory for semaphore manager");
        return NULL;
    }
    memset(manager, 0, sizeof(SemaphoreManager));
    return manager;
}

int create_semaphore(SemaphoreManager *manager, const char *name, int initial_value) {
    // Check if semaphore already exists
    for (int i = 0; i < manager->count; ++i) {
        if (strcmp(name, sem_getvalue(manager->sems[i], NULL)) == 0) {
            fprintf(stderr, "Semaphore %s already exists\n", name);
            return -1;
        }
    }

    // Create semaphore
    sem_t *sem = sem_open(name, O_CREAT | O_EXCL, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return -1;
    }

    // Add semaphore to manager
    if (manager->count >= MAX_SEMAPHORES) {
        fprintf(stderr, "Semaphore manager is full\n");
        sem_close(sem);
        sem_unlink(name);
        return -1;
    }
    manager->sems[manager->count++] = sem;

    return 0;
}

int delete_semaphore(SemaphoreManager *manager, const char *name) {
    for (int i = 0; i < manager->count; ++i) {
        if (strcmp(name, sem_getvalue(manager->sems[i], NULL)) == 0) {
            sem_close(manager->sems[i]);
            sem_unlink(name);
            memmove(&manager->sems[i], &manager->sems[i + 1], sizeof(sem_t*) * (manager->count - i - 1));
            manager->count--;
            return 0;
        }
    }
    fprintf(stderr, "Semaphore %s not found\n", name);
    return -1;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    for (int i = 0; i < manager->count; ++i) {
        sem_close(manager->sems[i]);
        sem_unlink(sem_getvalue(manager->sems[i], NULL));
    }
    free(manager);
}
