#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int find(int *parent, int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void unionSet(int *parent, int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset)
        parent[xset] = yset;
}

int areDisjoint(int *parent, int x, int y) {
    return find(parent, x) != find(parent, y);
}

void printLargest(int *keys, int n) {
    int max = keys[0];
    for (int i = 1; i < n; i++)
        if (keys[i] > max)
            max = keys[i];
    printf("Largest integer: %d\n", max);
}

int main() {
    int *offsets, *keys;
    record *records;
    int n, range, x, y;
    clock_t start, end;

    printf("Enter the number of elements: ");
    scanf("%d", &n);

    offsets = (long *)malloc(n * sizeof(long));
    keys = (int *)malloc(n * sizeof(int));
    records = (record *)malloc(n * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    srand(time(0));
    for (int i = 0; i < n; i++) {
        offsets[i] = i;
        keys[i] = rand() % range + 1;
        records[i].value = rand() % range + 1;
    }

    int *parent = (int *)calloc(n, sizeof(int));
    if (!parent) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return 1;
    }

    for (int i = 0; i < n; i++)
        parent[i] = -1;

    printf("Enter the range for random values: ");
    scanf("%d", &range);

    for (int i = 0; i < n; i++) {
        x = rand() % n;
        y = rand() % n;
        start = clock();
        if (areDisjoint(parent, x, y)) {
            unionSet(parent, x, y);
            printf("Pair (%d, %d) is disjoint. Time taken: %f ms\n", x, y, ((double)(clock() - start)) / CLOCKS_PER_SEC * 1000);
        } else {
            printf("Pair (%d, %d) is not disjoint.\n", x, y);
        }
    }

    printLargest(keys, n);

    free(offsets);
    free(keys);
    free(records);
    free(parent);

    return 0;
}
