    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        entries[i].value = min_value + (double)(rand() / (RAND_MAX / (max_value - min_value)));

        // Initialize linked list
        Node* head = NULL;
        Node* tail = NULL;

        for (int j = 0; j < 5; ++j) { // Example: Each entry has a list of 5 nodes
            Node* newNode = (Node*)malloc(sizeof(Node));
            if (!newNode) {
                log_message("Memory allocation failed for node");
                free_entries(entries, i);
                return NULL;
            }

            newNode->data = j + 1; // Example data initialization
            newNode->next = NULL;

            if (!head) {
                head = newNode;
                tail = newNode;
            } else {
                tail->next = newNode;
                tail = newNode;
            }
        }

        entries[i].list = head;
    }

    log_message("Entries initialized successfully");
    return entries;
}

void free_entries(Entry* entries, int size) {
    if (!entries) {
        return;
    }

    for (int i = 0; i < size; ++i) {
        Node* current = entries[i].list;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }

    free(entries);
    log_message("Entries and their lists freed successfully");
}

int main() {
    int size = 10; // Example array size
    double min_value = 0.0;
    double max_value = 100.0;

    Entry* entries = initialize_entries(size, min_value, max_value);
    if (entries) {
        free_entries(entries, size);
    }

    return 0;
}
