void log_message(const char *message) {
    printf("%s\n", message);
}

int execute_command(const char *command) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 0;
    } else if (pid == 0) {
        execlp(command, command, NULL);
        perror("execlp");
        exit(EXIT_FAILURE);
    } else {
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0;
    }
}

void *initialize_data(int num_records, int key_range_start, int key_range_end, int offset_range_start, int offset_range_end) {
    long *offsets = (long *)malloc(num_records * sizeof(long));
    if (!offsets) {
        log_message("Failed to allocate memory for offsets");
        return NULL;
    }

    int *keys = (int *)malloc(num_records * sizeof(int));
    if (!keys) {
        log_message("Failed to allocate memory for keys");
        free(offsets);
        return NULL;
    }

    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        log_message("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (offset_range_end - offset_range_start + 1) + offset_range_start;
        keys[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        records[i].value = rand() % (key_range_end - key_range_start + 1) + key_range_start;
    }

    log_message("Data initialization successful");
    return records;
}

void cleanup_data(void *data, int num_records) {
    record *records = (record *)data;
    free(records);
    log_message("Data cleanup successful");
}

int main() {
    int num_records = 1000;
    void *data = initialize_data(num_records, 1, 100, 1000, 2000);
    if (data) {
        cleanup_data(data, num_records);
    }

    if (execute_command("ls -l")) {
        log_message("Command executed successfully");
    } else {
        log_message("Command execution failed");
    }

    return 0;
}
