void allocate_and_initialize(int num_records, int range_start, int range_end) {
    if (num_records <= 0 || range_start > range_end) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    srand(time(NULL));
    int random_values[num_records];
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % (range_end - range_start + 1) + range_start;
        records[i].value = keys[i];
        records[i].identifier = (char*)malloc(20 * sizeof(char));
        sprintf(records[i].identifier, "Record_%d", i);
        random_values[i] = keys[i];
    }

    log_execution(0, num_records - 1, random_values);

    for (int i = 0; i < num_records; i++) {
        free(records[i].identifier);
    }
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int num_records = 10;
    int range_start = 1;
    int range_end = 100;

    allocate_and_initialize(num_records, range_start, range_end);

    return 0;
}
