// Circuit breaker pattern
class CircuitBreaker {
public:
    void request() {
        if (isOpen()) {
            throw std::runtime_error("Circuit is open");
        }
        // Simulate a network request
        if (std::rand() % 2 == 0) {
            throw std::runtime_error("Network error");
        }
