    }
};

// Backoff strategy
class ExponentialBackoff {
public:
    void retry() {
        std::this_thread::sleep_for(std::chrono::milliseconds(backoff_time));
        backoff_time *= 2;
    }

private:
    int backoff_time = 100; // Initial backoff time in milliseconds
};

// Memory management strategy
void allocateMemory() {
    const size_t num_records = 1000;
