typedef struct {
    int value;
    long timestamp;
    int id;
} IntegerMetadata;

int processIntegerStream(IntegerMetadata* metadataArray, int count) {
    if (count > 1000) {
        printf("Error: Data stream exceeds maximum allowed elements.\n");
        return -1;
    }

    int* integers = (int*)malloc(count * sizeof(int));
    if (!integers) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    int maxInt = INT_MIN;
    long totalSum = 0;
    int validCount = 0;

    for (int i = 0; i < count; i++) {
        integers[i] = metadataArray[i].value;
        if (integers[i] > maxInt) {
            maxInt = integers[i];
        }
        totalSum += integers[i];
        validCount++;
    }

    double average = (double)totalSum / validCount;

    printf("Largest integer: %d\n", maxInt);
    printf("Average of integers: %.2f\n", average);

    free(integers);
    return 0;
}

int main() {
    // Example usage
    IntegerMetadata metadata[] = {
        {10, 1633072800, 1},
        {-5, 1633072801, 2},
        {0, 1633072802, 3}
    };
    int count = sizeof(metadata) / sizeof(metadata[0]);

    processIntegerStream(metadata, count);

    return 0;
}
