const processUserActivityFeed = async (config) => {
  const { sources, filters, pagination } = config;
  let aggregatedReport = [];
  let page = 1;

  while (true) {
    try {
      const responses = await Promise.all(
        sources.map(source => fetch(`${source.url}?page=${page}&limit=${pagination.limit}`, source.options))
      );

      const dataPromises = responses.map(response => response.json());
      const data = await Promise.all(dataPromises);

      const filteredData = data.flat().filter(item => filters.includes(item.type));

      aggregatedReport = [...aggregatedReport, ...filteredData];

      if (data.some(sourceData => sourceData.length < pagination.limit)) {
        break;
      }

      page++;
    } catch (error) {
      console.error(`Error fetching data from sources: ${error}`);
      // Implement retry logic or handle partial failures
    }
  }

  return aggregatedReport;
};
