using System;
using System.Collections.Generic;
using UnityEngine;

public class DynamicRandomValueGenerator : MonoBehaviour
{
    private System.Random _random = new System.Random();
    private float _minFloatRange = 0f, _maxFloatRange = 1f;
    private int _minIntRange = 0, _maxIntRange = 100;
    private bool _inclusiveFloats = true, _inclusiveInts = true;
    private bool _useCustomSeed = false;
    private long _customSeed = 0;

    public void SetRange(float minFloatRange, float maxFloatRange, int minIntRange, int maxIntRange, bool inclusiveFloats, bool inclusiveInts)
    {
        if (minFloatRange >= maxFloatRange || minIntRange >= maxIntRange)
        {
            Debug.LogWarning("Invalid range. Min value must be less than max value.");
            return;
        }

        _minFloatRange = minFloatRange;
        _maxFloatRange = maxFloatRange;
        _minIntRange = minIntRange;
        _maxIntRange = maxIntRange;
        _inclusiveFloats = inclusiveFloats;
        _inclusiveInts = inclusiveInts;

        if (_useCustomSeed)
            _random = new System.Random(_customSeed);
    }

    public void SetCustomSeed(long seed)
    {
        _useCustomSeed = true;
        _customSeed = seed;
        _random = new System.Random(seed);
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(_minFloatRange, _maxFloatRange) + (_inclusiveFloats ? 0 : -UnityEngine.Random.Epsilon);
    }

    public int GetRandomInt()
    {
        return _random.Next(_minIntRange, _maxIntRange + (_inclusiveInts ? 1 : 0));
    }

    public List<float> GenerateSampleValues(int count = 20)
    {
        List<float> values = new List<float>();
        for (int i = 0; i < count; i++)
        {
            values.Add(GetRandomFloat());
        }
        return values;
    }

    public override string ToString()
    {
        return $"DynamicRandomValueGenerator: Float Range ({_minFloatRange}, {_maxFloatRange}), Int Range ({_minIntRange}, {_maxIntRange})";
    }

    public void GeneratePerformanceProfile(int iterations)
    {
        Stopwatch stopwatch = new Stopwatch();
        stopwatch.Start();

        for (int i = 0; i < iterations; i++)
        {
            GetRandomFloat();
            GetRandomInt();
        }

        stopwatch.Stop();
        Debug.Log($"Performance Profile: {stopwatch.ElapsedMilliseconds} ms");
    }
}
