        keys[i] = rand() % num_records;
    }
    return keys;
}

long* generate_offsets(int num_records, long min_offset, long max_offset) {
    long* offsets = (long*)malloc(num_records * sizeof(long));
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
    }
    return offsets;
}

record* initialize_records(int num_records, int* keys, long* offsets) {
    record* records = (record*)malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % 1000;
    }
    return records;
}

void free_resources(int* keys, long* offsets, record* records) {
    free(keys);
    free(offsets);
    free(records);
}

int main() {
    srand(time(NULL));
    int num_records = 1000;
    int min_offset = 0;
    int max_offset = 10000;

    int* keys = generate_keys(num_records);
    long* offsets = generate_offsets(num_records, min_offset, max_offset);
    record* records = initialize_records(num_records, keys, offsets);

    // Use the records array...

