#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/err.h>
#include <argon2.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[16];
    unsigned char key[32];
} AESCipherContext;

int generate_iv(unsigned char *iv, size_t len) {
    return RAND_bytes(iv, len);
}

int derive_key(const char *passphrase, const unsigned char *salt, size_t salt_len, unsigned char *key, size_t key_len) {
    argon2id_ctx ctx;
    int ret = argon2id_init(&ctx, Argon2_id13, passphrase, strlen(passphrase), salt, salt_len, NULL, 0, key, key_len, 4, 16);
    if (ret != ARGON2_OK) {
        ERR_print_errors_fp(stderr);
        return -1;
    }
    ret = argon2id_ctx_exec(&ctx);
    if (ret != ARGON2_OK) {
        ERR_print_errors_fp(stderr);
        return -1;
    }
    argon2id_free(&ctx);
    return 0;
}

AESCipherContext* init_aes_cipher(const char *passphrase, const unsigned char *salt, size_t salt_len, unsigned char *iv_source, size_t iv_len) {
    AESCipherContext *ctx = (AESCipherContext*)malloc(sizeof(AESCipherContext));
    if (!ctx) return NULL;

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx);
        return NULL;
    }

    if (generate_iv(iv_source, iv_len) != 1) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }
    memcpy(ctx->iv, iv_source, iv_len);

    if (derive_key(passphrase, salt, salt_len, ctx->key, sizeof(ctx->key)) != 0) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    if (1 != EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(AESCipherContext *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
    }
}
