void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed. Trying with half the size.\n");
        return allocate_memory(size / 2);
    }
    return ptr;
}

void initialize_arrays(long** offsets, int** keys, record** records, time_t** timestamps, size_t size) {
    *offsets = (long*)allocate_memory(size * sizeof(long));
    *keys = (int*)allocate_memory(size * sizeof(int));
    *records = (record*)allocate_memory(size * sizeof(record));
    *timestamps = (time_t*)allocate_memory(size * sizeof(time_t));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *timestamps == NULL) {
        fprintf(stderr, "Failed to allocate memory for all arrays.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize arrays
    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = i * 10;
        (*keys)[i] = i;
        (*records)[i].value = i * 2;
        (*records)[i].status_flag = 1;
        (*timestamps)[i] = time(NULL);
    }
}

void cleanup_arrays(long* offsets, int* keys, record* records, time_t* timestamps) {
    free(offsets);
    free(keys);
    free(records);
    free(timestamps);
}

int main() {
    size_t size = 100;
    long* offsets;
    int* keys;
    record* records;
    time_t* timestamps;

    initialize_arrays(&offsets, &keys, &records, &timestamps, size);

    // Use the arrays...

    cleanup_arrays(offsets, keys, records, timestamps);
    return 0;
}
