#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_WEIGHT 100.0f

typedef struct {
    float value;
    char label;
    float weight;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    float total_weight;
    pthread_mutex_t mutex;
} RecordList;

void init_record_list(RecordList* list, size_t initial_capacity) {
    list->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!list->records) {
        perror("Failed to allocate memory for record list");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;
    list->total_weight = 0.0f;
    pthread_mutex_init(&list->mutex, NULL);
}

void free_record_list(RecordList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->records);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
}

int insert_record(RecordList* list, Record record) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity || list->total_weight + record.weight > MAX_WEIGHT) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Not enough space or weight limit exceeded
    }
    for (size_t i = 0; i < list->size; ++i) {
        if (list->records[i].label == record.label) {
            pthread_mutex_unlock(&list->mutex);
            return -2; // Duplicate label
        }
    }
    list->records[list->size++] = record;
    list->total_weight += record.weight;
    pthread_mutex_unlock(&list->mutex);
    printf("Record inserted successfully\n");
    return 0;
}

int update_record(RecordList* list, char label, Record new_record) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->records[i].label == label) {
            float weight_diff = new_record.weight - list->records[i].weight;
            if (list->total_weight + weight_diff > MAX_WEIGHT) {
                pthread_mutex_unlock(&list->mutex);
                return -1; // Weight limit exceeded
            }
            list->records[i] = new_record;
            list->total_weight += weight_diff;
            pthread_mutex_unlock(&list->mutex);
            printf("Record updated successfully\n");
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -2; // Record not found
}

int delete_record(RecordList* list, char label) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        if (list->records[i].label == label) {
            float weight_diff = -list->records[i].weight;
            memmove(&list->records[i], &list->records[i + 1], (list->size - i - 1) * sizeof(Record));
            list->size--;
            list->total_weight += weight_diff;
            pthread_mutex_unlock(&list->mutex);
            printf("Record deleted successfully\n");
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -2; // Record not found
}
