        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        pthread_mutex_unlock(&mutex);
    }

    return records;
}

void resize_records(record** records, size_t* capacity, size_t new_capacity) {
    record* new_records = allocate_memory(new_capacity * sizeof(record));
    if (new_records == NULL) {
        return;
    }

    for (size_t i = 0; i < *capacity && i < new_capacity; ++i) {
        new_records[i] = (*records)[i];
    }

    deallocate_memory(*records);
    *records = new_records;
    *capacity = new_capacity;
}

void free_records(record* records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        // Assuming no need to free individual record fields
    }
    deallocate_memory(records);
