#define MAX_DATA_ENTRIES 100

typedef struct {
    long timestamp;
    int status_code;
    char* description;
} data;

typedef struct {
    data entries[MAX_DATA_ENTRIES];
    int count;
} report;

void initialize_data(data* d) {
    d->timestamp = time(NULL);
    d->status_code = rand() % 100 + 1;
    asprintf(&d->description, "Status %d", d->status_code);
}

report* create_report(int num_entries) {
    if (num_entries <= 0 || num_entries > MAX_DATA_ENTRIES) {
        return NULL; // Handle edge case
    }

    report* r = malloc(sizeof(report));
    if (!r) {
        perror("Failed to allocate memory for report");
        return NULL;
    }
    r->count = num_entries;

    for (int i = 0; i < num_entries; i++) {
        initialize_data(&r->entries[i]);
    }

    return r;
}

void free_report(report* r) {
    if (!r) {
        return;
    }

    for (int i = 0; i < r->count; i++) {
        free(r->entries[i].description);
    }
    free(r);
}

// Example usage
int main() {
    srand(time(NULL));

    report* my_report = create_report(5);
    if (my_report) {
        printf("Report created with %d entries\n", my_report->count);
        for (int i = 0; i < my_report->count; i++) {
            printf("Entry %d: Timestamp=%ld, Status=%d, Description=%s\n",
                   i, my_report->entries[i].timestamp,
                   my_report->entries[i].status_code,
                   my_report->entries[i].description);
        }
        free_report(my_report);
    }

    return 0;
}
