    Report** reports = (Report**)malloc(num_reports * sizeof(Report*));
    if (!reports) {
        perror("Failed to allocate memory for report array");
        return NULL;
    }
    for (int i = 0; i < num_reports; ++i) {
        reports[i] = (Report*)malloc(sizeof(Report));
        if (!reports[i]) {
            perror("Failed to allocate memory for individual report");
            // Free previously allocated reports
            for (int j = 0; j < i; ++j) {
                free(reports[j]);
            }
            free(reports);
            return NULL;
        }
        memset(reports[i], 0, sizeof(Report));
    }
    return reports;
}

void initialize_report(Report* report, long timestamp, int category, const char* description) {
    report->timestamp = timestamp;
    report->category = category;
    report->description = strdup(description);
    srand(time(NULL)); // Seed for random number generation
    for (int i = 0; i < 10; ++i) {
        report->statuses[i].timestamp = time(NULL);
        report->statuses[i].status_code = rand() % 100 + 1;
        char short_desc[50];
        snprintf(short_desc, sizeof(short_desc), "Status %d", report->statuses[i].status_code);
        report->statuses[i].short_description = strdup(short_desc);
    }
}

void free_report(Report* report) {
    if (report->description) {
        free(report->description);
    }
    for (int i = 0; i < 10; ++i) {
        if (report->statuses[i].short_description) {
            free(report->statuses[i].short_description);
        }
    }
    // Free data entries if needed
    free(report);
}

void free_report_array(Report** reports, int num_reports) {
    for (int i = 0; i < num_reports; ++i) {
        free_report(reports[i]);
    }
    free(reports);
}
