        ds->records[i]->key = rand() % num_records; // Ensure unique keys
        ds->records[i]->value = (float)rand() / RAND_MAX;
        ds->records[i]->str = strdup("example");
        ds->records[i]->next = NULL;
        ds->records[i]->status = ACTIVE;

        // Initialize union data based on status
        if (ds->records[i]->status == ACTIVE) {
            ds->records[i]->data.i_val = rand();
        } else {
            ds->records[i]->data.d_val = (double)rand() / RAND_MAX;
        }
    }

    printf("Data structures initialized successfully\n");
}

void free_data_structures(DataStructure* ds, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (ds->records[i]) {
            free(ds->records[i]->str);
            free(ds->records[i]);
        }
    }

    free(ds->records);

    printf("Data structures freed successfully\n");
}
