typedef struct {
    char *directory;
    char *output_directory;
    char *transformation;
    int num_threads;
} ImageProcessingConfig;

typedef struct {
    ImageProcessingConfig *config;
    char *file_path;
} ImageTask;

void* process_image(void *arg) {
    ImageTask *task = (ImageTask *)arg;
    MagickWand *wand = NewMagickWand();
    if (!wand) {
        fprintf(stderr, "Failed to create wand\n");
        return NULL;
    }

    if (MagickReadImage(wand, task->file_path) != MagickTrue) {
        fprintf(stderr, "Failed to read image: %s\n", task->file_path);
        DestroyMagickWand(wand);
        return NULL;
    }

    // Apply transformation
    if (MagickTransformImage(wand, task->config->transformation) != MagickTrue) {
        fprintf(stderr, "Failed to transform image: %s\n", task->file_path);
        DestroyMagickWand(wand);
        return NULL;
    }

    char output_path[256];
    snprintf(output_path, sizeof(output_path), "%s/%s", task->config->output_directory, task->file_path);

    if (MagickWriteImage(wand, output_path) != MagickTrue) {
        fprintf(stderr, "Failed to write image: %s\n", output_path);
        DestroyMagickWand(wand);
        return NULL;
    }

    DestroyMagickWand(wand);
    free(task->file_path);
    free(task);

    return NULL;
}

int process_directory(ImageProcessingConfig *config) {
    DIR *dir = opendir(config->directory);
    if (!dir) {
        fprintf(stderr, "Failed to open directory: %s\n", config->directory);
        return -1;
    }

    pthread_t threads[config->num_threads];
    int thread_count = 0;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char file_path[256];
        snprintf(file_path, sizeof(file_path), "%s/%s", config->directory, entry->d_name);

        ImageTask *task = (ImageTask *)malloc(sizeof(ImageTask));
        task->config = config;
        task->file_path = strdup(file_path);

        if (pthread_create(&threads[thread_count], NULL, process_image, task) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            free(task);
            continue;
        }

        thread_count++;
        if (thread_count >= config->num_threads) {
            for (int i = 0; i < thread_count; i++) {
                pthread_join(threads[i], NULL);
            }
            thread_count = 0;
        }
    }

    closedir(dir);

    // Join remaining threads
    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

MagickWand* transform_images(ImageProcessingConfig *config) {
    if (process_directory(config) != 0) {
        fprintf(stderr, "Failed to process directory\n");
        return NULL;
    }

