#include <stdlib.h>
#include <pthread.h>

typedef struct NFDataPdu_t {
    RrcConnectionReconfigurationIndication indication;
    RrcMessage* message;
} NFDataPdu_t;

typedef struct DynamicArray {
    NFDataPdu_t** data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* dynamic_array_create() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->data = NULL;
    array->size = 0;
    array->capacity = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void dynamic_array_destroy(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i]->message);
        free(array->data[i]);
    }
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int dynamic_array_add(DynamicArray* array, NFDataPdu_t* pdu) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        NFDataPdu_t** new_data = (NFDataPdu_t**)realloc(array->data, new_capacity * sizeof(NFDataPdu_t*));
        if (!new_data) {
            pthread_mutex_unlock(&array->lock);
            return 1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }
    array->data[array->size++] = pdu;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int dynamic_array_update(DynamicArray* array, size_t index, NFDataPdu_t* pdu) {
    if (index >= array->size) return 1;
    pthread_mutex_lock(&array->lock);
    free(array->data[index]->message);
    array->data[index] = pdu;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void dynamic_array_process(DynamicArray* array, void (*process_message)(RrcMessage*)) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        process_message(array->data[i]->message);
    }
    pthread_mutex_unlock(&array->lock);
}

int dynamic_array_size(DynamicArray* array) {
    return array->size;
}
