    sem_t *sem = sem_open(name, O_CREAT | O_EXCL, 0644, initial_value);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return NULL;
    }
    return sem;
}

// Function to delete a named semaphore
void delete_semaphore(sem_t* sem, const char* name) {
    if (sem_close(sem) != 0) {
        perror("Failed to close semaphore");
    }
    if (sem_unlink(name) != 0) {
        perror("Failed to unlink semaphore");
    }
}

// Function to log semaphore operations
void log_semaphore_operation(const char* operation, const char* name) {
    printf("%s on semaphore %s\n", operation, name);
}
