<?php

class PasswordDAO {
    private $pdo;

    public function __construct($dsn, $username, $password) {
        try {
            $this->pdo = new PDO($dsn, $username, $password);
            $this->pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        } catch (PDOException $e) {
            die("Could not connect to the database $dsn :" . $e->getMessage());
        }
    }

    public function updatePassword($userId, $newPassword) {
        // Validate password rules
        if (strlen($newPassword) < 8 || !preg_match('/[A-Za-z]/', $newPassword) || !preg_match('/\d/', $newPassword)) {
            throw new Exception("Invalid password. It must be at least 8 characters long and contain both letters and numbers.");
        }

        // Check for uniqueness
        $stmt = $this->pdo->prepare('SELECT COUNT(*) FROM users WHERE password = :password');
        $stmt->execute(['password' => $newPassword]);
        if ($stmt->fetchColumn() > 0) {
            throw new Exception("This password is already in use.");
        }

        // Update password atomically
        $stmt = $this->pdo->prepare('UPDATE users SET password = :password WHERE id = :id');
        $stmt->execute(['password' => password_hash($newPassword, PASSWORD_DEFAULT), 'id' => $userId]);
    }
}

