typedef struct {
    UserSessionState state;
    SecurityContext *context;
} NetworkEventLog_t;

typedef struct {
    NetworkEventLog_t **logs;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SessionManager_t;

void init_session_manager(SessionManager_t *manager, size_t initial_capacity) {
    manager->logs = (NetworkEventLog_t **)malloc(initial_capacity * sizeof(NetworkEventLog_t *));
    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void free_session_manager(SessionManager_t *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->logs[i]->context);
        free(manager->logs[i]);
    }
    free(manager->logs);
    pthread_mutex_destroy(&manager->lock);
}

void add_session_state(SessionManager_t *manager, UserSessionState state, SecurityContext *context) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        manager->capacity *= 2;
        manager->logs = (NetworkEventLog_t **)realloc(manager->logs, manager->capacity * sizeof(NetworkEventLog_t *));
    }
    NetworkEventLog_t *new_log = (NetworkEventLog_t *)malloc(sizeof(NetworkEventLog_t));
    new_log->state = state;
    new_log->context = context;
    manager->logs[manager->count++] = new_log;
    pthread_mutex_unlock(&manager->lock);
}

void update_session_state(SessionManager_t *manager, size_t index, UserSessionState state) {
    pthread_mutex_lock(&manager->lock);
    if (index < manager->count) {
        manager->logs[index]->state = state;
    }
    pthread_mutex_unlock(&manager->lock);
}

void process_logs(SessionManager_t *manager, void (*process_context)(SecurityContext *)) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        process_context(manager->logs[i]->context);
    }
    pthread_mutex_unlock(&manager->lock);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
