#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    long timestamp;
    int status_code;
    char* description;
} report;

typedef struct {
    report* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} report_pool;

report_pool* create_report_pool() {
    report_pool* pool = (report_pool*)malloc(sizeof(report_pool));
    if (!pool) return NULL;

    pool->data = (report*)calloc(INITIAL_CAPACITY, sizeof(report));
    if (!pool->data) {
        free(pool);
        return NULL;
    }

    pool->capacity = INITIAL_CAPACITY;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroy_report_pool(report_pool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->data[i].description);
    }
    free(pool->data);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

report* allocate_report(report_pool* pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->size == pool->capacity) {
        size_t new_capacity = pool->capacity * GROWTH_FACTOR;
        report* new_data = (report*)realloc(pool->data, new_capacity * sizeof(report));
        if (!new_data) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->data = new_data;
        pool->capacity = new_capacity;
    }

    report* new_report = &pool->data[pool->size++];
    new_report->timestamp = time(NULL);
    new_report->status_code = rand() % 100 + 1;
    asprintf(&new_report->description, "Status %d", new_report->status_code);

    pthread_mutex_unlock(&pool->lock);
    return new_report;
}

void free_report(report* report) {
    if (report) {
        free(report->description);
        memset(report, 0, sizeof(report));
    }
}
