LogRecord* createLoggingSystem(size_t numRecords, size_t maxMessageLength, unsigned int seed) {
    if (numRecords == 0 || maxMessageLength == 0) {
        return NULL; // Handle edge cases
    }

    LogRecord *records = (LogRecord *)malloc(numRecords * sizeof(LogRecord));
    if (!records) {
        return NULL; // Allocation failed
    }

    srand(seed);
    int keys[numRecords];
    for (size_t i = 0; i < numRecords; ++i) {
        do {
            keys[i] = rand() % 10000; // Random key in range [0, 9999]
        } while (i > 0 && keys[i] == keys[i - 1]); // Ensure no duplicates
    }

    for (size_t i = 0; i < numRecords; ++i) {
        records[i].key = keys[i];
        records[i].message = (char *)calloc(maxMessageLength + 1, sizeof(char));
        if (!records[i].message) {
            // Cleanup previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(records[j].message);
            }
            free(records);
            return NULL; // Allocation failed
        }
        records[i].length = rand() % maxMessageLength;
        for (size_t j = 0; j < records[i].length; ++j) {
            records[i].message[j] = 'A' + rand() % ('Z' - 'A' + 1); // Random ASCII character
        }
        records[i].updated = false;
    }

    return records;
}
