void allocate_and_initialize(int n, int minValue, int maxValue, int maxMemoryUsageBytes) {
    if (n <= 0 || maxMemoryUsageBytes <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    size_t totalSize = n * sizeof(long) + n * sizeof(int) + n * sizeof(record);
    if (totalSize > maxMemoryUsageBytes * 1024) {
        fprintf(stderr, "Insufficient memory for allocation.\n");
        return;
    }

    long* offsetArray = aligned_alloc(64, n * sizeof(long));
    int* keyArray = aligned_alloc(64, n * sizeof(int));
    record* records = aligned_alloc(64, n * sizeof(record));

    if (!offsetArray || !keyArray || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        offsetArray[i] = i * 1024; // Example initialization
        keyArray[i] = rand() % (maxValue - minValue + 1) + minValue;
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    // Perform operations with the allocated arrays and records

    free(offsetArray);
    free(keyArray);
    free(records);
}

