#define MAX_LOG_ENTRIES 1024
#define MIN_KEY 100
#define MAX_KEY 999

typedef struct {
    int key;
    char *message;
    size_t length;
    bool updated;
} LogEntry;

typedef struct {
    LogEntry *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} LoggingSystem;

LoggingSystem *create_logging_system(size_t initial_capacity) {
    LoggingSystem *system = (LoggingSystem *)malloc(sizeof(LoggingSystem));
    if (!system) return NULL;

    system->entries = (LogEntry *)calloc(initial_capacity, sizeof(LogEntry));
    if (!system->entries) {
        free(system);
        return NULL;
    }

    system->count = 0;
    system->capacity = initial_capacity;
    pthread_mutex_init(&system->lock, NULL);

    return system;
}

void destroy_logging_system(LoggingSystem *system) {
    for (size_t i = 0; i < system->count; ++i) {
        free(system->entries[i].message);
    }
    free(system->entries);
    pthread_mutex_destroy(&system->lock);
    free(system);
}

int add_log_entry(LoggingSystem *system, int key, const char *message) {
    pthread_mutex_lock(&system->lock);

    if (system->count >= system->capacity) {
        // Handle capacity overflow
        pthread_mutex_unlock(&system->lock);
        return -1;
    }

    LogEntry *entry = &system->entries[system->count];
    entry->key = key;
    entry->message = strdup(message);
    entry->length = strlen(message);
    entry->updated = true;

    system->count++;
    pthread_mutex_unlock(&system->lock);

    return 0;
}

// Additional functions for logging system operations would go here

int main() {
    srand(time(NULL));
    LoggingSystem *log_system = create_logging_system(MAX_LOG_ENTRIES);
    if (!log_system) {
        fprintf(stderr, "Failed to create logging system\n");
        return EXIT_FAILURE;
    }

    // Example usage
    add_log_entry(log_system, 123, "This is a log message");

    destroy_logging_system(log_system);
    return EXIT_SUCCESS;
}
