#include <iostream>
#include <string>
#include <boost/asio.hpp>
#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>

namespace beast = boost::beast;         // from <boost/beast.hpp>
namespace http = beast::http;           // from <boost/beast/http.hpp>
namespace net = boost::asio;            // from <boost/asio.hpp>
using tcp = boost::asio::ip::tcp;       // from <boost/asio/ip/tcp.hpp>

class HttpClient {
public:
    HttpClient(net::io_context& ioc, std::string host, std::string port)
        : resolver_(ioc), stream_(ioc), host_(std::move(host)), port_(std::move(port)) {}

    void get(const std::string& target) {
        do_get(target);
    }

    void post(const std::string& target, const std::string& body) {
        do_post(target, body);
    }

private:
    void do_get(const std::string& target) {
        // Resolve the host and port
        resolver_.async_resolve(host_, port_,
            [this, target](beast::error_code ec, tcp::resolver::results_type results) {
                if (!ec)
                    do_connect(results.begin());
            });
    }

    void do_post(const std::string& target, const std::string& body) {
        // Resolve the host and port
        resolver_.async_resolve(host_, port_,
            [this, target, body](beast::error_code ec, tcp::resolver::results_type results) {
                if (!ec)
                    do_connect(results.begin());
            });
    }

    void do_connect(tcp::resolver::results_type begin) {
        // Connect to the host
        net::async_connect(stream_.next_layer(), begin,
            [this](beast::error_code ec, tcp::resolver::results_type::iterator it) {
                if (!ec)
                    do_handshake();
            });
    }

    void do_handshake() {
        // Perform SSL handshake
        stream_.async_handshake(net::ssl::stream_base::client,
            [this](beast::error_code ec) {
                if (!ec)
                    do_request();
            });
    }

    void do_request() {
        // Send a GET request
        http::request<http::string_body> req{http::verb::get, "/", 11};
        req.set(http::field::host, host_);
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);

        http::async_write(stream_, req,
            [this](beast::error_code ec, std::size_t bytes_transferred) {
                if (!ec)
                    do_read();
            });
    }

    void do_read() {
        // Read the response
        http::async_read(stream_, buffer_,
            [this](beast::error_code ec, std::size_t bytes_transferred) {
                if (!ec)
                    std::cout << "Response: " << beast::make_printable(buffer_.data()) << std::endl;
            });
    }

private:
    tcp::resolver resolver_;
    net::ssl::stream<tcp::socket> stream_;
    std::string host_;
    std::string port_;
    http::request<http::string_body> req_;
    http::response<http::dynamic_body> res_;
    beast::flat_buffer buffer_;
};

int main() {
    try {
        net::io_context ioc;
        HttpClient client(ioc, "example.com", "443");

        client.get("/");
        client.post("/", "data");

        ioc.run();
    } catch (std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }

    return 0;
}
