static CryptoAlgorithm algorithms[3];
static int algorithm_count = 0;

void load_crypto_algorithms(const char *config) {
    pthread_mutex_lock(&crypto_lock);
    for (int i = 0; i < algorithm_count; i++) {
        EVP_CIPHER_free(algorithms[i].cipher);
        EVP_MD_free(algorithms[i].digest);
    }
    algorithm_count = 0;

    const char *token = strtok(config, "-");
    while (token != NULL && algorithm_count < 3) {
        if (strcmp(token, "AES") == 0) {
            algorithms[algorithm_count].cipher = EVP_aes_256_cbc();
        } else if (strcmp(token, "RSA") == 0) {
            // RSA key generation is not directly supported by OpenSSL's EVP API
            // This would typically involve using RSA_new(), RSA_generate_key_ex(), etc.
            algorithms[algorithm_count].cipher = NULL;
        } else if (strcmp(token, "SHA256") == 0) {
            algorithms[algorithm_count].digest = EVP_sha256();
        }
        token = strtok(NULL, "-");
        algorithm_count++;
    }

    for (int i = 0; i < algorithm_count; i++) {
        if (algorithms[i].cipher != NULL) {
            EVP_add_cipher(algorithms[i].cipher);
        }
        if (algorithms[i].digest != NULL) {
            EVP_add_digest(algorithms[i].digest);
            // Optionally, add digest aliases for compatibility
            // EVP_add_digest_alias(algorithms[i].digest, "ALIAS_NAME");
        }
    }

    pthread_mutex_unlock(&crypto_lock);
}

void unload_crypto_algorithms() {
    pthread_mutex_lock(&crypto_lock);
    for (int i = 0; i < algorithm_count; i++) {
        if (algorithms[i].cipher != NULL) {
            EVP_CIPHER_free(algorithms[i].cipher);
        }
        if (algorithms[i].digest != NULL) {
            EVP_MD_free(algorithms[i].digest);
        }
    }
    algorithm_count = 0;
    pthread_mutex_unlock(&crypto_lock);
}

