#define MAX_CONCURRENT_THREADS 100

typedef struct {
    RrcConnectionReconfigurationIndication indication;
    RrcMessage* message;
} NFDataPdu_t;

typedef struct {
    NFDataPdu_t** data;
    size_t capacity;
    size_t size;
    atomic_int next_index;
} DynamicArray_t;

DynamicArray_t* dynamic_array_create(size_t initial_capacity) {
    DynamicArray_t* array = (DynamicArray_t*)malloc(sizeof(DynamicArray_t));
    array->data = (NFDataPdu_t**)calloc(initial_capacity, sizeof(NFDataPdu_t*));
    array->capacity = initial_capacity;
    array->size = 0;
    atomic_init(&array->next_index, 0);
    return array;
}

void dynamic_array_add(DynamicArray_t* array, NFDataPdu_t* pdu) {
    if (array->size >= array->capacity) {
        array->data = realloc(array->data, array->capacity * 2 * sizeof(NFDataPdu_t*));
        array->capacity *= 2;
    }
    array->data[array->size++] = pdu;
}

void dynamic_array_update(DynamicArray_t* array, size_t index, NFDataPdu_t* new_pdu) {
    if (index < array->size) {
        free(array->data[index]->message);
        array->data[index] = new_pdu;
    }
}

void dynamic_array_process(DynamicArray_t* array, void (*process_message)(RrcMessage*)) {
    size_t index = atomic_fetch_add(&array->next_index, 1);
    while (index < array->size) {
        process_message(array->data[index]->message);
        index = atomic_fetch_add(&array->next_index, 1);
    }
}

void dynamic_array_destroy(DynamicArray_t* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->data[i]->message);
        free(array->data[i]);
    }
    free(array->data);
    free(array);
}
