typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[16];
} AES_GCM_CTX;

int aes_gcm_init(AES_GCM_CTX **ctx, const char *password, size_t password_len, const unsigned char *aad, size_t aad_len, size_t iv_len) {
    if (iv_len < 12 || iv_len > 16) {
        return -1; // Invalid IV length
    }

    *ctx = malloc(sizeof(AES_GCM_CTX));
    if (*ctx == NULL) {
        return -1; // Memory allocation failed
    }

    EVP_CIPHER_CTX_init((*ctx)->ctx);
    SHA256((unsigned char *)password, password_len, (*ctx)->key);

    int ret = EVP_EncryptInit_ex((*ctx)->ctx, EVP_aes_128_gcm(), NULL, (*ctx)->key, NULL);
    if (!ret) {
        EVP_CIPHER_CTX_free((*ctx)->ctx);
        free(*ctx);
        return -1; // Initialization failed
    }

    ret = EVP_CIPHER_CTX_ctrl((*ctx)->ctx, EVP_CTRL_GCM_SET_IVLEN, iv_len, NULL);
    if (!ret) {
        EVP_CIPHER_CTX_free((*ctx)->ctx);
        free(*ctx);
        return -1; // IV length setting failed
    }

    ret = EVP_EncryptUpdate((*ctx)->ctx, NULL, NULL, aad, aad_len);
    if (!ret) {
        EVP_CIPHER_CTX_free((*ctx)->ctx);
        free(*ctx);
        return -1; // AAD processing failed
    }

    return 0;
}

void aes_gcm_cleanup(AES_GCM_CTX *ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
    }
}
