#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

int find(int *parent, int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void unionSet(int *parent, int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset)
        parent[xset] = yset;
}

int areDisjoint(int *parent, int i, int j) {
    return find(parent, i) != find(parent, j);
}

void logMessage(const char *message) {
    printf("%s\n", message);
}

record* initializeRecords(int *keys, int keyCount, int offsetRange, int *largestKey, int *disjointPairs) {
    record *records = (record *)malloc(keyCount * sizeof(record));
    if (!records) {
        logMessage("Memory allocation failed for records");
        return NULL;
    }

    int *parent = (int *)calloc(keyCount, sizeof(int));
    if (!parent) {
        logMessage("Memory allocation failed for parent array");
        free(records);
        return NULL;
    }

    srand(time(0));

    for (int i = 0; i < keyCount; ++i) {
        records[i].value = rand() % offsetRange + 1;
        keys[i] = i;

        if (!areDisjoint(parent, i, keys[i])) {
            logMessage("Duplicate key found");
            free(records);
            free(parent);
            return NULL;
        }

        unionSet(parent, i, keys[i]);
    }

    *largestKey = keys[keyCount - 1];
    *disjointPairs = keyCount;

    free(parent);
    return records;
}

void cleanupRecords(record *records, int keyCount) {
    if (records) {
        free(records);
        logMessage("Records freed");
    }
}

int main() {
    int keyCount, offsetRange;
    printf("Enter the number of keys and offset range: ");
    scanf("%d %d", &keyCount, &offsetRange);

    int *keys = (int *)malloc(keyCount * sizeof(int));
    if (!keys) {
        logMessage("Memory allocation failed for keys");
        return 1;
    }

    record *records = initializeRecords(keys, keyCount, offsetRange, NULL, NULL);
    if (!records) {
        free(keys);
        return 1;
    }

    int largestKey, disjointPairs;
    records = initializeRecords(keys, keyCount, offsetRange, &largestKey, &disjointPairs);
    if (records) {
        printf("Largest Key: %d\n", largestKey);
        printf("Disjoint Pairs: %d\n", disjointPairs);

        cleanupRecords(records, keyCount);
    }

    free(keys);
    return 0;
}
