void allocate_and_initialize(long **offsets, int *keys, record **records, size_t n, size_t m, size_t k, size_t max_records, size_t memory_limit, int min_key, int max_key, int min_value, int max_value) {
    if (n == 0 || m == 0 || k == 0) {
        *offsets = NULL;
        *keys = NULL;
        *records = NULL;
        return;
    }

    size_t offsets_size = n * sizeof(long);
    size_t keys_size = m * sizeof(int);
    size_t records_size = k * sizeof(record);

    if (offsets_size + keys_size + records_size > memory_limit) {
        *offsets = NULL;
        *keys = NULL;
        *records = NULL;
        return;
    }

    *offsets = (long *)malloc(offsets_size);
    *keys = (int *)malloc(keys_size);
    *records = (record *)malloc(records_size);

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        *offsets = NULL;
        *keys = NULL;
        *records = NULL;
        return;
    }

    for (size_t i = 0; i < n; ++i) {
        (*offsets)[i] = 0;
    }

    for (size_t i = 0; i < m; ++i) {
        (*keys)[i] = min_key + rand() % (max_key - min_key + 1);
    }

    srand(time(NULL));
    for (size_t i = 0; i < k && i < max_records; ++i) {
        (*records)[i].value = min_value + rand() % (max_value - min_value + 1);
    }
}

void free_allocated_memory(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
