#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} record;

typedef struct node {
    double data;
    struct node* next;
} node;

typedef struct entry {
    double key;
    node* head;
} entry;

void initialize_data(long* offsets, int* keys, record** records, entry** entries, size_t n, size_t m, size_t k, size_t max_records, size_t memory_limit, double min_key, double max_key, double min_value, double max_value) {
    // Initialize offsets and keys
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = 0;
        keys[i] = (int)(min_key + rand() / (RAND_MAX / (max_key - min_key)));
    }

    // Allocate records with proper alignment
    size_t record_size = sizeof(record);
    size_t aligned_record_size = ((record_size + 15) & ~15); // Align to 16 bytes for multi-threaded access
    size_t total_records_size = k * aligned_record_size;
    if (total_records_size > memory_limit) {
        fprintf(stderr, "Memory limit exceeded\n");
        exit(EXIT_FAILURE);
    }
    records[0] = (record*)aligned_alloc(16, total_records_size);
    for (size_t i = 1; i < k; ++i) {
        records[i] = &records[0][i];
    }

    // Initialize records
    for (size_t i = 0; i < k; ++i) {
        records[i]->value = (int)(min_value + rand() / (RAND_MAX / (max_value - min_value)));
    }

    // Allocate entries with proper alignment
    size_t entry_size = sizeof(entry);
    size_t aligned_entry_size = ((entry_size + 15) & ~15); // Align to 16 bytes for multi-threaded access
    size_t total_entries_size = m * aligned_entry_size;
    if (total_entries_size > memory_limit) {
        fprintf(stderr, "Memory limit exceeded\n");
        exit(EXIT_FAILURE);
    }
    entries[0] = (entry*)aligned_alloc(16, total_entries_size);
    for (size_t i = 1; i < m; ++i) {
        entries[i] = &entries[0][i];
    }

    // Initialize entries
    srand(time(NULL));
    for (size_t i = 0; i < m; ++i) {
        entries[i]->key = min_key + rand() / (RAND_MAX / (max_key - min_key));
        node* head = NULL;
        for (int j = 0; j < 5; ++j) { // Example: Each entry has a linked list of 5 nodes
            node* new_node = (node*)malloc(sizeof(node));
            new_node->data = min_value + rand() / (RAND_MAX / (max_value - min_value));
            new_node->next = head;
            head = new_node;
        }
        entries[i]->head = head;
    }

    // Log initialization
    printf("Data initialized successfully\n");
}

void cleanup_data(long* offsets, int* keys, record** records, entry** entries) {
    // Free records and their linked lists
    for (size_t i = 0; i < k; ++i) {
        node* current = records[i]->head;
        while (current != NULL) {
            node* next = current->next;
            free(current);
            current = next;
        }
    }

    // Free entries and their linked lists
    for (size_t i = 0; i < m; ++i) {
        node* current = entries[i]->head;
        while (current != NULL) {
            node* next = current->next;
            free(current);
            current = next;
        }
    }

    // Free records and entries arrays
    free(records[0]);
    free(entries[0]);

    // Log cleanup
    printf("Data cleaned up successfully\n");
}
