using System;
using System.IO;
using System.Security.AccessControl;
using System.Xml.XPath;
using Microsoft.Extensions.Logging;

public class DataStorageManager
{
    private readonly ILogger<DataStorageManager> _logger;
    private string _dataPath;

    public DataStorageManager(ILogger<DataStorageManager> logger)
    {
        _logger = logger;
        InitializeDataPath();
    }

    private void InitializeDataPath()
    {
        var envPath = Environment.GetEnvironmentVariable("DATA_PATH");
        if (envPath != null && Directory.Exists(envPath))
        {
            _dataPath = envPath;
        }
        else
        {
            try
            {
                var homeDir = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
                _dataPath = Path.Combine(homeDir, "DataStore");
                Directory.CreateDirectory(_dataPath);
                SetDirectoryPermissions(_dataPath);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to create default data path. Using fallback.");
                // Fallback mechanism here
            }
        }
    }

    private void SetDirectoryPermissions(string path)
    {
        var security = Directory.GetAccessControl(path);
        var rule = new FileSystemAccessRule(
            Environment.UserDomainName + "\\" + Environment.UserName,
            FileSystemRights.FullControl,
            InheritanceFlags.ObjectInherit | InheritanceFlags.ContainerInherit,
            PropagationFlags.None,
            AccessControlType.Allow
        );
        security.AddAccessRule(rule);
        Directory.SetAccessControl(path, security);
    }

    public async Task<XPathNavigator> ParseXmlAsync(string filePath, string elementName)
    {
        if (!File.Exists(filePath))
        {
            throw new FileNotFoundException("XML file not found.", filePath);
        }

        try
        {
            using (var reader = XmlReader.Create(filePath))
            {
                var doc = new XPathDocument(reader);
                var navigator = doc.CreateNavigator();
                var node = navigator.SelectSingleNode($"//{elementName}");
                if (node == null)
                {
                    throw new InvalidOperationException($"No element found with name '{elementName}'.");
                }
                return navigator.Clone();
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error parsing XML file.");
            throw;
        }
    }

    // Additional methods for integration, scalability, and resource management
}
