typedef struct node {
    double value;
    struct node* next;
    struct node* prev;
} Node;

typedef struct entry {
    double data;
    Node* head;
} Entry;

typedef struct batch {
    Entry** entries;
    int size;
    int capacity;
} Batch;

typedef struct report {
    // Define the structure for report
} Report;

void log_message(const char* message) {
    printf("%s\n", message);
}

Entry* create_entry(double value) {
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    if (!entry) {
        log_message("Memory allocation failed for entry");
        return NULL;
    }
    entry->data = value;
    entry->head = NULL;
    return entry;
}

Batch* create_batch(int initial_capacity) {
    Batch* batch = (Batch*)malloc(sizeof(Batch));
    if (!batch) {
        log_message("Memory allocation failed for batch");
        return NULL;
    }
    batch->entries = (Entry**)malloc(initial_capacity * sizeof(Entry*));
    if (!batch->entries) {
        free(batch);
        log_message("Memory allocation failed for batch entries");
        return NULL;
    }
    batch->size = 0;
    batch->capacity = initial_capacity;
    return batch;
}

void resize_batch(Batch* batch, int new_capacity) {
    Entry** new_entries = (Entry**)realloc(batch->entries, new_capacity * sizeof(Entry*));
    if (!new_entries) {
        log_message("Memory reallocation failed for batch entries");
        return;
    }
    batch->entries = new_entries;
    batch->capacity = new_capacity;
}

void populate_batch(Batch* batch, int num_entries, double min_value, double max_value) {
    srand(time(NULL));
    for (int i = 0; i < num_entries; ++i) {
        Entry* entry = create_entry((max_value - min_value) * rand() / RAND_MAX + min_value);
        if (!entry) continue;
        batch->entries[batch->size++] = entry;
        if (batch->size == batch->capacity) {
            resize_batch(batch, batch->capacity * 2);
        }
    }
}

void free_entry(Entry* entry) {
    Node* current = entry->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(entry);
}

void free_batch(Batch* batch) {
    for (int i = 0; i < batch->size; ++i) {
        free_entry(batch->entries[i]);
    }
    free(batch->entries);
    free(batch);
}

