#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_FILE_SIZE 1024 * 1024 // 1 MB

typedef struct {
    char interface_name[50];
    struct in_addr ip_address;
    struct in_addr subnet_mask;
    struct in_addr gateway;
} NetworkInterface;

NetworkInterface* parse_config_file(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    if (file_size > MAX_FILE_SIZE) {
        fprintf(stderr, "File size exceeds maximum allowed\n");
        fclose(file);
        return NULL;
    }

    char* buffer = malloc(file_size + 1);
    if (!buffer) {
        perror("Failed to allocate memory for file content");
        fclose(file);
        return NULL;
    }

    fread(buffer, 1, file_size, file);
    buffer[file_size] = '\0';
    fclose(file);

    NetworkInterface* interfaces = malloc(sizeof(NetworkInterface));
    *count = 0;

    char* line = strtok(buffer, "\n");
    while (line) {
        if (*count >= 1024) { // Assuming a maximum of 1024 interfaces
            fprintf(stderr, "Too many interfaces in the file\n");
            free(interfaces);
            free(buffer);
            return NULL;
        }

        char* token = strtok(line, " ");
        strcpy(interfaces[*count].interface_name, token);

        token = strtok(NULL, " ");
        if (inet_pton(AF_INET, token, &interfaces[*count].ip_address) != 1) {
            fprintf(stderr, "Invalid IP address format\n");
            free(interfaces);
            free(buffer);
            return NULL;
        }

        token = strtok(NULL, " ");
        if (inet_pton(AF_INET, token, &interfaces[*count].subnet_mask) != 1) {
            fprintf(stderr, "Invalid subnet mask format\n");
            free(interfaces);
            free(buffer);
            return NULL;
        }

        token = strtok(NULL, " ");
        if (inet_pton(AF_INET, token, &interfaces[*count].gateway) != 1) {
            fprintf(stderr, "Invalid gateway address format\n");
            free(interfaces);
            free(buffer);
            return NULL;
        }

        (*count)++;
        interfaces = realloc(interfaces, (*count + 1) * sizeof(NetworkInterface));
    }

    free(buffer);
    return interfaces;
}

void find_highest_priority_interface(NetworkInterface* interfaces, int count) {
    if (count == 0) {
        printf("No valid interfaces found.\n");
        return;
    }

    NetworkInterface* highest_priority = &interfaces[0];
    for (int i = 1; i < count; i++) {
        if (ntohl(interfaces[i].ip_address.s_addr) > ntohl(highest_priority->ip_address.s_addr)) {
            highest_priority = &interfaces[i];
        }
    }

    printf("Interface with the highest IP address: %s\n", highest_priority->interface_name);
}

int main() {
    int count;
    NetworkInterface* interfaces = parse_config_file("config.txt", &count);

    if (interfaces) {
        find_highest_priority_interface(interfaces, count);
        free(interfaces);
    }

    return 0;
}
