entry* initialize_arrays(time_t start_time, size_t array_size) {
    entry *entries = (entry *)malloc(array_size * sizeof(entry));
    if (!entries) {
        log_message("Memory allocation failed for entries");
        return NULL;
    }

    unsigned long *timestamps = (unsigned long *)malloc(array_size * sizeof(unsigned long));
    if (!timestamps) {
        log_message("Memory allocation failed for timestamps");
        free(entries);
        return NULL;
    }

    char **strings = (char **)malloc(array_size * sizeof(char *));
    if (!strings) {
        log_message("Memory allocation failed for strings");
        free(timestamps);
        free(entries);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < array_size; ++i) {
        // Generate unique string
        char *str = (char *)malloc(STRING_LENGTH + 1);
        if (!str) {
            log_message("Memory allocation failed for string");
            for (size_t j = 0; j < i; ++j) {
                free(strings[j]);
            }
            free(strings);
            free(timestamps);
            free(entries);
            return NULL;
        }
        for (int j = 0; j < STRING_LENGTH; ++j) {
            str[j] = 'A' + rand() % ('Z' - 'A' + 1);
        }
        str[STRING_LENGTH] = '\0';
        strings[i] = str;

        // Assign unique timestamp
        timestamps[i] = start_time + i;

        // Initialize struct entry
        entries[i].flag = rand();
        entries[i].value = (double)rand() / RAND_MAX;
    }

    log_message("Arrays initialized successfully");
    return entries;
}

void cleanup_arrays(entry *entries, char **strings, unsigned long *timestamps, size_t array_size) {
    for (size_t i = 0; i < array_size; ++i) {
        free(strings[i]);
    }
    free(strings);
    free(timestamps);
    free(entries);
    log_message("Arrays cleaned up successfully");
}

int main() {
    time_t start_time = time(NULL);
    entry *entries = initialize_arrays(start_time, ARRAY_SIZE);

    if (entries) {
        // Use the arrays here
        cleanup_arrays(entries, NULL, NULL, ARRAY_SIZE);
    }

    return 0;
}
