#define MAX_STRING_LENGTH 100

typedef struct {
    char* str;
    unsigned int flag;
    double value;
} entry;

entry* create_entry(const char* prefix, unsigned int flag, double value) {
    entry* e = (entry*)malloc(sizeof(entry));
    if (!e) return NULL;

    e->str = (char*)malloc(MAX_STRING_LENGTH * sizeof(char));
    if (!e->str) {
        free(e);
        return NULL;
    }

    snprintf(e->str, MAX_STRING_LENGTH, "%s_%lu", prefix, time(NULL));
    e->flag = flag;
    e->value = value;

    return e;
}

void destroy_entry(entry* e) {
    if (e) {
        free(e->str);
        free(e);
    }
}

entry** create_entries(const char* prefix, unsigned int count, unsigned int flag, double value) {
    entry** entries = (entry**)malloc(count * sizeof(entry*));
    if (!entries) return NULL;

    for (unsigned int i = 0; i < count; ++i) {
        entries[i] = create_entry(prefix, flag, value);
        if (!entries[i]) {
            for (unsigned int j = 0; j < i; ++j) destroy_entry(entries[j]);
            free(entries);
            return NULL;
        }
    }

    return entries;
}

void destroy_entries(entry** entries, unsigned int count) {
    for (unsigned int i = 0; i < count; ++i) destroy_entry(entries[i]);
    free(entries);
}

