typedef struct {
    int x;
    int y;
    unsigned long timestamp;
} point;

int parse_csv(const char *filename, double **double_array, char ***char_array, point **point_array) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1; // File opening failed

    // Allocate initial memory for arrays
    *double_array = (double *)malloc(100 * sizeof(double));
    *char_array = (char **)malloc(100 * sizeof(char *));
    *point_array = (point *)malloc(100 * sizeof(point));

    if (!*double_array || !*char_array || !*point_array) {
        fclose(file);
        return -2; // Memory allocation failed
    }

    int double_count = 0, char_count = 0, point_count = 0;
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        if (line[0] == '#' || line[0] == '\n') continue; // Skip comments and empty lines

        char *token = strtok(line, ",");
        double double_value = atof(token);
        token = strtok(NULL, ",");
        point p;
        p.x = atoi(token);
        token = strtok(NULL, ",");
        p.y = atoi(token);
        token = strtok(NULL, ",");
        p.timestamp = strtoul(token, NULL, 10);

        // Allocate memory for string and copy data
        (*char_array)[char_count] = (char *)malloc(257 * sizeof(char));
        if (!(*char_array)[char_count]) {
            fclose(file);
            return -3; // Memory allocation failed
        }
        strcpy((*char_array)[char_count], token);

        // Store parsed data in arrays
        (*double_array)[double_count++] = double_value;
        (*point_array)[point_count++] = p;

        // Check if more memory is needed and allocate if necessary
        if (double_count >= 100) {
            *double_array = realloc(*double_array, (double_count + 50) * sizeof(double));
        }
        if (char_count >= 100) {
            *char_array = realloc(*char_array, (char_count + 50) * sizeof(char *));
            for (int i = char_count; i < char_count + 50; i++) {
                (*char_array)[i] = (char *)malloc(257 * sizeof(char));
            }
        }
        if (point_count >= 100) {
            *point_array = realloc(*point_array, (point_count + 50) * sizeof(point));
        }

        // Handle potential parsing errors
        if (!*double_array || !*char_array || !*point_array) {
            fclose(file);
            return -4; // Memory allocation failed
        }
    }

    fclose(file);
    return point_count;
}

void free_resources(double *double_array, char **char_array, point *point_array, int count) {
    for (int i = 0; i < count; i++) {
        free(char_array[i]);
    }
    free(double_array);
    free(char_array);
    free(point_array);
}
