typedef struct node {
    int data;
    struct node* next;
} Node;

typedef struct entry {
    double value;
    Node* list;
} Entry;

Entry* initialize_entries(int size) {
    Entry* entries = (Entry*)malloc(size * sizeof(Entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        entries[i].value = ((double)rand() / RAND_MAX) * 100.0; // Generate random value between 0 and 100

        Node* head = NULL;
        Node* tail = NULL;

        for (int j = 0; j < 5; j++) { // Initialize linked list with predefined data
            Node* newNode = (Node*)malloc(sizeof(Node));
            if (!newNode) {
                fprintf(stderr, "Memory allocation failed\n");
                free_entries(entries, i);
                return NULL;
            }
            newNode->data = j * 10;
            newNode->next = NULL;

            if (!head) {
                head = newNode;
                tail = newNode;
            } else {
                tail->next = newNode;
                tail = newNode;
            }
        }

        entries[i].list = head;
    }

    return entries;
}

void free_entries(Entry* entries, int size) {
    for (int i = 0; i < size; i++) {
        Node* current = entries[i].list;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }

    free(entries);
}

void log_message(const char* message) {
    printf("%s\n", message);
}
