    long* offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    int* keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        return NULL;
    }

    record* records = (record*)malloc(MAX_RECORDS * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        return NULL;
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_mutex_lock(&mutex);
        offsets[i] = rand();
        keys[i] = rand() % 100; // Random value within the range [0, 99]
        records[i].value = keys[i];
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    printf("Initialization complete\n");

    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, initialize_records, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    printf("Cleanup complete\n");

    return EXIT_SUCCESS;
}
