#include <time.h>

#define MAX_RECORDS 100

typedef struct {
    long offset;
    int key;
    double value;
} Record;

void initializeArrays(long **offsets, int **keys, double **values, Record **records) {
    *offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    *keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    *values = (double *)malloc(MAX_RECORDS * sizeof(double));
    *records = (Record *)malloc(MAX_RECORDS * sizeof(Record));

    if (*offsets == NULL || *keys == NULL || *values == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void populateRecords(long *offsets, int *keys, double *values, Record *records, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        offsets[i] = rand() % 1000L;
        keys[i] = rand() % 1000;
        values[i] = ((double)rand()) / RAND_MAX * 100.0;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = values[i];
    }
}

void readData(long **offsets, int **keys, double **values, Record **records, FILE *stream) {
    int count = 0;
    while (fscanf(stream, "%ld %d %lf", &(*offsets)[count], &(*keys)[count], &(*values)[count]) == 3 && count < MAX_RECORDS) {
        (*records)[count].offset = (*offsets)[count];
        (*records)[count].key = (*keys)[count];
        (*records)[count].value = (*values)[count];
        count++;
    }
}

void findLargestValues(int *keys, double *values, int count) {
    int maxKey = keys[0];
    double maxValue = values[0];

    for (int i = 1; i < count; i++) {
        if (keys[i] > maxKey) {
            maxKey = keys[i];
        }
        if (values[i] > maxValue) {
            maxValue = values[i];
        }
    }

    printf("Largest integer key: %d\n", maxKey);
    printf("Largest floating-point value: %.2f\n", maxValue);
}

void cleanup(long *offsets, int *keys, double *values, Record *records) {
    free(offsets);
    free(keys);
    free(values);
    free(records);
}

int main() {
    long *offsets;
    int *keys;
    double *values;
    Record *records;

    initializeArrays(&offsets, &keys, &values, &records);

    populateRecords(offsets, keys, values, records, 50);

    FILE *jsonStream = fopen("data.json", "r");
    if (jsonStream != NULL) {
        readData(&offsets, &keys, &values, &records, jsonStream);
        fclose(jsonStream);
    }

    findLargestValues(keys, values, 50);

    cleanup(offsets, keys, values, records);

    return 0;
}
