typedef struct {
    UserSessionState state;
    SecurityContext *context;
} NetworkEventLog_t;

typedef struct {
    NetworkEventLog_t **logs;
    size_t count;
    pthread_mutex_t lock;
} SessionManager_t;

void init_session_manager(SessionManager_t *manager) {
    manager->logs = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_session_manager(SessionManager_t *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->logs[i]->context);
        free(manager->logs[i]);
    }
    free(manager->logs);
    pthread_mutex_destroy(&manager->lock);
}

void add_session_state(SessionManager_t *manager, UserSessionState state) {
    pthread_mutex_lock(&manager->lock);
    NetworkEventLog_t *new_log = malloc(sizeof(NetworkEventLog_t));
    new_log->state = state;
    new_log->context = malloc(sizeof(SecurityContext)); // Assume SecurityContext is defined elsewhere
    // Initialize context with necessary data
    manager->logs = realloc(manager->logs, (manager->count + 1) * sizeof(NetworkEventLog_t *));
    manager->logs[manager->count++] = new_log;
    pthread_mutex_unlock(&manager->lock);
}

void update_session_state(SessionManager_t *manager, UserSessionState state, int id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->logs[i]->state.id == id) {
            manager->logs[i]->state = state;
            // Update context with new data
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

void iterate_session_logs(SessionManager_t *manager, void (*process_context)(SecurityContext *)) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        process_context(manager->logs[i]->context);
    }
    pthread_mutex_unlock(&manager->lock);
}

void handle_http_put(SessionManager_t *manager, int id, UserSessionState new_state) {
    update_session_state(manager, new_state, id);
}

NetworkEventLog_t* handle_http_delete(SessionManager_t *manager, int id) {
    NetworkEventLog_t *new_log = malloc(sizeof(NetworkEventLog_t));
    new_log->state.id = id;
    new_log->context = malloc(sizeof(SecurityContext)); // Initialize with default values
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->logs[i]->state.id == id) {
            free(manager->logs[i]->context);
            free(manager->logs[i]);
            memmove(manager->logs + i, manager->logs + i + 1, (manager->count - i - 1) * sizeof(NetworkEventLog_t *));
            --manager->count;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return new_log;
}
