        records[i].value = min_value + ((double)rand() / RAND_MAX) * (max_value - min_value);
    }

    log_message("Records initialized successfully");
    return records;
}

void free_records(record* records, int num_records) {
    if (records) {
        free(records);
        log_message("Records memory freed");
    }
}

int main() {
    int num_records = 1000;
    record* my_records = initialize_records(num_records, 0, 1000000, -1000, 1000, 0.0, 100.0);

    if (my_records) {
        // Use the records here
        free_records(my_records, num_records);
    }

    return 0;
}
```

This code snippet demonstrates how to dynamically allocate memory for and initialize arrays of different data types in C, handle potential errors during memory allocation, and ensure that all allocated memory is properly freed upon completion. It also includes a simple logging mechanism to track the initialization and cleanup processes.']

