use std::io::{self, Read};
use std::net::TcpStream;
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Instant, Duration};

#[derive(Debug)]
struct Record {
    offset: i64,
    key: u32,
    value: f64,
}

fn read_records_from_stdin() -> Vec<Record> {
    let mut buffer = String::new();
    io::stdin().read_to_string(&mut buffer).unwrap();
    buffer.lines()
        .map(|line| {
            let parts: Vec<&str> = line.split_whitespace().collect();
            Record {
                offset: parts[0].parse().unwrap(),
                key: parts[1].parse().unwrap(),
                value: parts[2].parse().unwrap(),
            }
        })
        .collect()
}

fn read_records_from_api(url: &str) -> Vec<Record> {
    let mut response = TcpStream::connect(url).unwrap();
    let mut buffer = String::new();
    response.read_to_string(&mut buffer).unwrap();
    buffer.lines()
        .map(|line| {
            let parts: Vec<&str> = line.split_whitespace().collect();
            Record {
                offset: parts[0].parse().unwrap(),
                key: parts[1].parse().unwrap(),
                value: parts[2].parse().unwrap(),
            }
        })
        .collect()
}

fn assign_unique_keys(records: &mut [Record]) -> HashMap<u32, u32> {
    let mut key_map = HashMap::new();
    let mut next_key = 1;
    for record in records.iter_mut() {
        if !key_map.contains_key(&record.key) {
            key_map.insert(record.key, next_key);
            record.key = next_key;
            next_key += 1;
        }
    }
    key_map
}

fn validate_offsets(records: &[Record], min_offset: i64, max_offset: i64) -> bool {
    records.iter().all(|record| record.offset >= min_offset && record.offset <= max_offset)
}

struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<usize>,
}

impl UnionFind {
    fn new(size: usize) -> Self {
        UnionFind {
            parent: (0..size).collect(),
            rank: vec![1; size],
        }
    }

    fn find(&mut self, u: usize) -> usize {
        if self.parent[u] != u {
            self.parent[u] = self.find(self.parent[u]);
        }
        self.parent[u]
    }

    fn union(&mut self, u: usize, v: usize) {
        let pu = self.find(u);
        let pv = self.find(v);
        if pu == pv {
            return;
        }
        if self.rank[pu] < self.rank[pv] {
            self.parent[pu] = pv;
        } else if self.rank[pu] > self.rank[pv] {
            self.parent[pv] = pu;
        } else {
            self.parent[pv] = pu;
            self.rank[pu] += 1;
        }
    }

    fn is_disjoint(&mut self, u: usize, v: usize) -> bool {
        self.find(u) != self.find(v)
    }
}

fn process_records(records: Vec<Record>, min_offset: i64, max_offset: i64) {
    let mut records = records;
    if !validate_offsets(&records, min_offset, max_offset) {
        eprintln!("Error: Invalid offsets");
        return;
    }

    let key_map = assign_unique_keys(&mut records);
    let mut uf = UnionFind::new(records.len());

    for record in &records {
        let pu = uf.find(key_map[&record.key] as usize);
        for other_record in &records {
            if other_record != record && uf.is_disjoint(pu, key_map[&other_record.key] as usize) {
                // Perform disjointness test and record time
                let start_time = Instant::now();
                uf.union(pu, key_map[&other_record.key] as usize);
                let duration = start_time.elapsed();
                println!("Disjointness test took: {:?}", duration);
            }
        }
    }
}

fn create_directory_and_set_env_var(dir_name: &str) {
    if std::env::var("MY_DIR").is_err() {
        fs::create_dir(dir_name).unwrap();
        std::env::set_var("MY_DIR", dir_name);
    } else {
        let path = std::env::var("MY_DIR").unwrap();
        println!("Using existing directory: {}", path);
    }
}

fn main() {
    let records_from_stdin = read_records_from_stdin();
    let records_from_api = read_records_from_api("http://example.com/api/data");
    let combined_records = [records_from_stdin, records_from_api].concat();

    create_directory_and_set_env_var("my_data_dir");

    process_records(combined_records, 0, 1_000_000);
}
