    if (*pool == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < count; i++) {
        (*pool)[i].value = min_value + rand() % (max_value - min_value + 1);
    }
}

void perform_service(record *pool, int count) {
    for (int i = 0; i < count; i++) {
        // Simulate service operation
        printf("Processing record with value: %d\n", pool[i].value);
        // Delay to mimic real-world service behavior
        sleep(rand() % 5 + 1); // Random delay between 1 and 5 seconds
    }
}

void shutdown_records(record *pool, int count) {
    for (int i = 0; i < count; i++) {
        // Simulate sending termination message to remote monitoring service
        printf("Sending termination message for record with value: %d\n", pool[i].value);
    }
    free(pool);
}

void manage_records(int min_value, int max_value, int count) {
    srand(time(NULL)); // Seed the random number generator

    record *pool;
    initialize_records(&pool, min_value, max_value, count);

    perform_service(pool, count);

    shutdown_records(pool, count);
}
