public class PageSectionController : ControllerBase
{
    private readonly IPageSectionService _pageSectionService;
    private readonly ILogger<PageSectionController> _logger;
    private readonly ICmsIntegrationService _cmsIntegrationService;
    private readonly ICacheService _cacheService;
    private readonly ILanguageService _languageService;

    public PageSectionController(IPageSectionService pageSectionService, ILogger<PageSectionController> logger, ICmsIntegrationService cmsIntegrationService, ICacheService cacheService, ILanguageService languageService)
    {
        _pageSectionService = pageSectionService;
        _logger = logger;
        _cmsIntegrationService = cmsIntegrationService;
        _cacheService = cacheService;
        _languageService = languageService;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdatePageSection([FromBody] PageSectionUpdateRequest request)
    {
        if (!ModelState.IsValid)
        {
            return BadRequest(ModelState);
        }

        int retries = 0;
        while (retries < 3)
        {
            try
            {
                await _pageSectionService.UpdateElementHtml(request.SectionId, request.ElementId, request.HtmlContent);
                _logger.LogInformation($"Page section updated successfully at {DateTime.UtcNow}");
                _cmsIntegrationService.PropagateChanges();
                _cacheService.InvalidateCache(request.ElementId);
                return Ok(new { Refresh = true });
            }
            catch (Exception ex)
            {
                retries++;
                if (retries == 3)
                {
                    _logger.LogError(ex, "Failed to update page section after multiple attempts");
                    return StatusCode(500, "Internal Server Error");
                }
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, retries)));
            }
        }

        return StatusCode(500, "Internal Server Error");
    }
}

public class PageSectionUpdateRequest
{
    public int SectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
}
