#include <thread>
#include <mutex>
#include <random>

struct AttackRecord {
    int lastAttackTime;
    int cooldownTimer;
};

class GameCharacter {
public:
    GameCharacter(int id, int minCooldown, int maxCooldown)
        : id(id), minCooldown(minCooldown), maxCooldown(maxCooldown) {
        attackRecords.resize(10); // Assuming each character has 10 attacks
        initializeAttackRecords();
    }

    void performAttack() {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto& record : attackRecords) {
            if (record.lastAttackTime + record.cooldownTimer <= currentSimulationTime) {
                record.lastAttackTime = currentSimulationTime;
                std::cout << "Character " << id << " performs attack at time: " << currentSimulationTime << std::endl;
                return;
            }
        }
    }

private:
    int id;
    int minCooldown;
    int maxCooldown;
    std::vector<AttackRecord> attackRecords;
    std::mutex mutex;
    static int currentSimulationTime;

    void initializeAttackRecords() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(minCooldown, maxCooldown);

        for (auto& record : attackRecords) {
            record.lastAttackTime = -dis(gen); // Initialize with a negative value
            record.cooldownTimer = dis(gen);
        }
    }

    static void simulateCombat(int numCharacters, int simulationDuration) {
        std::vector<std::thread> threads;
        for (int i = 0; i < numCharacters; ++i) {
            threads.emplace_back([i]() {
                GameCharacter character(i, 1, 5); // Example cooldown range
                while (GameCharacter::currentSimulationTime < simulationDuration) {
                    character.performAttack();
                    std::this_thread::sleep_for(std::chrono::milliseconds(100)); // Simulate time passing
                }
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }
    }
};

int GameCharacter::currentSimulationTime = 0;

int main() {
    int numCharacters = 5;
    int simulationDuration = 1000; // 1 second

    GameCharacter::simulateCombat(numCharacters, simulationDuration);

    return 0;
}
