#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_CONCURRENT_REQUESTS 100
#define DNS_CACHE_SIZE 1024
#define CACHE_EXPIRY_TIME 3600

typedef struct {
    char hostname[256];
    struct in_addr ip_address;
    time_t expiry_time;
} DnsCacheEntry;

DnsCacheEntry dns_cache[DNS_CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* resolve_dns(void* arg) {
    char* hostname = (char*)arg;
    struct in_addr ip_address;
    time_t current_time = time(NULL);

    // Check DNS cache
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_count; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0 && dns_cache[i].expiry_time > current_time) {
            ip_address = dns_cache[i].ip_address;
            pthread_mutex_unlock(&cache_lock);
            printf("Resolved %s to %s from cache\n", hostname, inet_ntoa(ip_address));
            return NULL;
        }
    }
    pthread_mutex_unlock(&cache_lock);

    // Perform DNS resolution
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        ip_address.s_addr = ipv4->sin_addr.s_addr;
        break;
    }
    freeaddrinfo(res);

    if (p == NULL) {
        fprintf(stderr, "Failed to resolve %s\n", hostname);
        return NULL;
    }

    // Cache the result
    pthread_mutex_lock(&cache_lock);
    if (cache_count < DNS_CACHE_SIZE) {
        dns_cache[cache_count].hostname = strdup(hostname);
        dns_cache[cache_count].ip_address = ip_address;
        dns_cache[cache_count].expiry_time = current_time + CACHE_EXPIRY_TIME;
        cache_count++;
    }
    pthread_mutex_unlock(&cache_lock);

    printf("Resolved %s to %s\n", hostname, inet_ntoa(ip_address));
    return NULL;
}

int main() {
    char hostnames[][256] = {"google.com", "example.com", "nonexistentdomain1234567890.com"};
    pthread_t threads[MAX_CONCURRENT_REQUESTS];

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS && i < sizeof(hostnames) / sizeof(hostnames[0]); i++) {
        if (pthread_create(&threads[i], NULL, resolve_dns, hostnames[i]) != 0) {
            perror("Failed to create thread");
            break;
        }
    }

    for (int i = 0; i < MAX_CONCURRENT_REQUESTS && i < sizeof(hostnames) / sizeof(hostnames[0]); i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
