#include <stdio.h>
#include <stdlib.h>

#define MAX_STREAMS 100
#define MAX_ELEMENTS 1000

typedef struct {
    int* elements;
    size_t count;
} DataStream;

void read_stream(DataStream* stream) {
    int num;
    while (scanf("%d", &num) == 1 && stream->count < MAX_ELEMENTS) {
        stream->elements[stream->count++] = num;
    }
}

int find_largest(const DataStream* stream) {
    if (stream->count == 0) return -1; // No integers found
    int largest = stream->elements[0];
    for (size_t i = 1; i < stream->count; ++i) {
        if (stream->elements[i] > largest) {
            largest = stream->elements[i];
        }
    }
    return largest;
}

double calculate_average(const DataStream* stream) {
    if (stream->count == 0) return -1.0; // No integers found
    double sum = 0;
    for (size_t i = 0; i < stream->count; ++i) {
        sum += stream->elements[i];
    }
    return sum / stream->count;
}

void process_stream(DataStream* stream) {
    int largest = find_largest(stream);
    if (largest == -1) {
        printf("No integers found.\n");
    } else {
        printf("Largest integer: %d\n", largest);
    }

    double average = calculate_average(stream);
    if (average == -1.0) {
        printf("Average cannot be determined.\n");
    } else {
        printf("Average: %.2f\n", average);
    }
}

int main() {
    DataStream streams[MAX_STREAMS];
    for (size_t i = 0; i < MAX_STREAMS; ++i) {
        streams[i].elements = malloc(MAX_ELEMENTS * sizeof(int));
        if (!streams[i].elements) {
            fprintf(stderr, "Memory allocation failed.\n");
            return EXIT_FAILURE;
        }
        streams[i].count = 0;
    }

    for (size_t i = 0; i < MAX_STREAMS; ++i) {
        printf("Enter integers for stream %zu (up to %d elements):\n", i, MAX_ELEMENTS);
        read_stream(&streams[i]);
    }

    for (size_t i = 0; i < MAX_STREAMS; ++i) {
        process_stream(&streams[i]);
        free(streams[i].elements);
    }

    return EXIT_SUCCESS;
}
