#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_RECORDS 5000
#define MAX_SEMAPHORES 5000

typedef struct {
    int value;
} Record;

Record* records[MAX_RECORDS];
sem_t semaphores[MAX_SEMAPHORES];

int allocate_record(int value) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i] == NULL) {
            records[i] = malloc(sizeof(Record));
            if (records[i] == NULL) {
                return -1; // Memory allocation failed
            }
            records[i]->value = value;
            sem_init(&semaphores[i], 0, 1); // Initialize semaphore for record access
            return i;
        }
    }
    return -2; // No available slots
}

void free_record(int index) {
    if (index >= 0 && index < MAX_RECORDS && records[index] != NULL) {
        sem_destroy(&semaphores[index]);
        free(records[index]);
        records[index] = NULL;
    }
}

int get_record_value(int index) {
    int value = -1;
    if (index >= 0 && index < MAX_RECORDS && records[index] != NULL) {
        sem_wait(&semaphores[index]); // Acquire semaphore for record access
        value = records[index]->value;
        sem_post(&semaphores[index]); // Release semaphore
    }
    return value;
}

void set_record_value(int index, int value) {
    if (index >= 0 && index < MAX_RECORDS && records[index] != NULL) {
        sem_wait(&semaphores[index]); // Acquire semaphore for record access
        records[index]->value = value;
        sem_post(&semaphores[index]); // Release semaphore
    }
}

int main() {
    int result = allocate_record(42);
    if (result >= 0) {
        printf("Record allocated at index %d with value %d\n", result, get_record_value(result));
        set_record_value(result, 99);
        printf("Updated record value to %d\n", get_record_value(result));
        free_record(result);
    } else {
        printf("Failed to allocate record: Error code %d\n", result);
    }
    return 0;
}
```

