using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class CryptoUtility
{
    private readonly Aes _aes;
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public CryptoUtility(string passphrase, byte[] salt)
    {
        if (string.IsNullOrEmpty(passphrase) || salt == null || salt.Length < 16)
            throw new ArgumentException("Invalid passphrase or salt.");

        var keyDerivation = new Rfc2898DeriveBytes(passphrase, salt, 10000);
        _key = keyDerivation.GetBytes(32); // AES-256
        _iv = GenerateRandomIV();

        _aes = Aes.Create();
        _aes.Mode = CipherMode.CBC;
        _aes.Padding = PaddingMode.PKCS7;
    }

    private byte[] GenerateRandomIV()
    {
        using (var rng = RandomNumberGenerator.Create())
        {
            var iv = new byte[16];
            rng.GetBytes(iv);
            return iv;
        }
    }

    public byte[] Encrypt(byte[] data)
    {
        _aes.Key = _key;
        _aes.IV = _iv;

        using (var encryptor = _aes.CreateEncryptor(_key, _iv))
        using (var ms = new MemoryStream())
        using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
        {
            cs.Write(data, 0, data.Length);
            cs.FlushFinalBlock();
            return ms.ToArray();
        }
    }

    public byte[] Decrypt(byte[] encryptedData)
    {
        _aes.Key = _key;
        _aes.IV = _iv;

        using (var decryptor = _aes.CreateDecryptor(_key, _iv))
        using (var ms = new MemoryStream(encryptedData))
        using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
        {
            var decryptedData = new byte[encryptedData.Length];
            int bytesRead = cs.Read(decryptedData, 0, decryptedData.Length);
            return decryptedData;
        }
    }

    public void Dispose()
    {
        _aes.Dispose();
    }
}
