#include <openssl/sha.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>

void ProcessAndEncryptData() {
    // Initialize OpenSSL EVP library
    OpenSSL_add_cipher(EVP_aes_256_cbc());
    OpenSSL_add_cipher(EVP_camellia_128_ecb());
    OpenSSL_add_digest(EVP_md5());
    OpenSSL_add_digest(EVP_sha1());
    OpenSSL_add_digest_alias("sha", "SHA");

    // Initialize semaphore with initial value
    sem_t *sem = sem_open("/my_semaphore", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return;
    }

    // Load and deserialize data from binary file
    FILE *file = fopen("data.bin", "rb");
    if (!file) {
        perror("Failed to open file");
        sem_close(sem);
        sem_unlink("/my_semaphore");
        return;
    }
    // Assuming a custom structure 'DataStruct' for deserialization
    DataStruct data;
    size_t bytesRead = fread(&data, sizeof(DataStruct), 1, file);
    fclose(file);

    if (bytesRead != 1) {
        perror("Failed to read data from file");
        sem_close(sem);
        sem_unlink("/my_semaphore");
        return;
    }

    // Encrypt the data
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        perror("Failed to create cipher context");
        sem_close(sem);
        sem_unlink("/my_semaphore");
        return;
    }
    unsigned char key[32], iv[16];
    if (RAND_bytes(key, sizeof(key)) != 1 || RAND_bytes(iv, sizeof(iv)) != 1) {
        perror("Failed to generate random bytes for key and IV");
        EVP_CIPHER_CTX_free(ctx);
        sem_close(sem);
        sem_unlink("/my_semaphore");
        return;
    }
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        perror("Failed to initialize encryption context");
        EVP_CIPHER_CTX_free(ctx);
        sem_close(sem);
        sem_unlink("/my_semaphore");
        return;
    }

    // Perform the encryption
    unsigned char encryptedData[1024];
    int len, ciphertext_len;
    if (!EVP_EncryptUpdate(ctx, encryptedData, &len, (unsigned char *)&data, sizeof(DataStruct))) {
        perror("Failed to encrypt data");
        EVP_CIPHER_CTX_free(ctx);
        sem_close(sem);
        sem_unlink("/my_semaphore");
        return;
    }
    ciphertext_len = len;

    if (!EVP_EncryptFinal_ex(ctx, encryptedData + len, &len)) {
        perror("Failed to finalize encryption");
        EVP_CIPHER_CTX_free(ctx);
        sem_close(sem);
        sem_unlink("/my_semaphore");
        return;
    }
    ciphertext_len += len;

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
    sem_close(sem);
    sem_unlink("/my_semaphore");

