const int BUFFER_SIZE = 100;
std::vector<std::string> commandBuffer(BUFFER_SIZE);
int bufferIndex = 0;

void logCommand(const std::string& command) {
    static std::ofstream logFile("session_log.txt", std::ios::app);
    if (!logFile.is_open()) {
        std::cerr << "Failed to open log file." << std::endl;
        return;
    }
    time_t now = time(0);
    char* dt = ctime(&now);
    logFile << "[" << dt << "] " << command << std::endl;
}

void processUserInput() {
    static std::unordered_map<std::string, int> commandFrequency;
    while (true) {
        std::cout << "Enter command: ";
        std::string input;
        std::cin >> input;

        if (input == "logout") {
            for (const auto& pair : commandFrequency) {
                std::cout << pair.first << ": " << pair.second << std::endl;
            }
            break;
        }

        if (input != "execute" && input != "query" && input != "modify") {
            std::cerr << "Invalid command. Please use 'execute', 'query', or 'modify'." << std::endl;
            continue;
        }

        logCommand(input);
        commandBuffer[bufferIndex] = input;
        bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;

        if (commandFrequency.find(input) == commandFrequency.end()) {
            commandFrequency[input] = 0;
        }
        commandFrequency[input]++;
    }
}
