#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int find(int *parent, int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void unionSet(int *parent, int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset)
        parent[xset] = yset;
}

int areDisjoint(int *parent, int x, int y) {
    return find(parent, x) != find(parent, y);
}

void logMessage(const char *message) {
    printf("%s\n", message);
}

record* initializeRecords(int size) {
    record *records = (record*)malloc(size * sizeof(record));
    if (!records) {
        logMessage("Memory allocation failed for records");
        return NULL;
    }
    srand(time(0));
    for (int i = 0; i < size; ++i)
        records[i].value = rand() % 1000; // Random value between 0 and 999
    return records;
}

void freeRecords(record *records, int size) {
    if (records) {
        free(records);
        logMessage("Records memory freed");
    }
}

int* initializeIntKeys(int size) {
    int *keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        logMessage("Memory allocation failed for keys");
        return NULL;
    }
    return keys;
}

void freeIntKeys(int *keys, int size) {
    if (keys) {
        free(keys);
        logMessage("Keys memory freed");
    }
}

int findLargestKey(int *keys, int size) {
    int max = keys[0];
    for (int i = 1; i < size; ++i)
        if (keys[i] > max)
            max = keys[i];
    return max;
}

void checkDisjointPairs(int *parent, int *keys, int size) {
    clock_t start, end;
    double cpu_time_used;
    for (int i = 0; i < size; ++i) {
        for (int j = i + 1; j < size; ++j) {
            start = clock();
            if (areDisjoint(parent, keys[i], keys[j])) {
                printf("Pair (%d, %d) is disjoint\n", keys[i], keys[j]);
            }
            end = clock();
            cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;
            printf("Time taken: %.2f ms\n", cpu_time_used * 1000);
        }
    }
}

int main() {
    int size;
    logMessage("Enter the number of elements:");
    scanf("%d", &size);

    int *keys = initializeIntKeys(size);
    if (!keys)
        return 1;

    record *records = initializeRecords(size);
    if (!records) {
        freeIntKeys(keys, size);
        return 1;
    }

    logMessage("Enter the integers:");
    for (int i = 0; i < size; ++i)
        scanf("%d", &keys[i]);

    int largestKey = findLargestKey(keys, size);
    printf("Largest key: %d\n", largestKey);

    int *parent = (int*)calloc(size, sizeof(int));
    if (!parent) {
        logMessage("Memory allocation failed for parent array");
        freeIntKeys(keys, size);
        freeRecords(records, size);
        return 1;
    }

    for (int i = 0; i < size; ++i)
        unionSet(parent, keys[i], keys[(i + 1) % size]);

    checkDisjointPairs(parent, keys, size);

    freeIntKeys(keys, size);
    freeRecords(records, size);
    free(parent);

    return 0;
}
