import os
import time

class LogEntry:
    def __init__(self, message, timestamp, node_id):
        self.message = message
        self.timestamp = timestamp
        self.node_id = node_id

def read_log_entries():
    entries = []
    while True:
        line = input()
        if not line:
            break
        parts = line.split(',')
        if len(parts) == 3:
            message, timestamp, node_id = parts
            entries.append(LogEntry(message, int(timestamp), int(node_id)))
    return entries

def find_earliest_latest(entries):
    earliest = min(entries, key=lambda x: x.timestamp)
    latest = max(entries, key=lambda x: x.timestamp)
    print(f"Earliest Log Entry: {earliest.message} at {earliest.timestamp}")
    print(f"Latest Log Entry: {latest.message} at {latest.timestamp}")

def count_unique_messages(entries):
    unique_messages = set()
    for entry in entries:
        unique_messages.add(entry.message)
    return len(unique_messages)

def create_directory_and_set_env_var(directory_name):
    if os.getenv('LOG_DIR'):
        print(f"Environment variable LOG_DIR already set to {os.getenv('LOG_DIR')}")
    else:
        try:
            os.makedirs(directory_name, exist_ok=True)
            os.environ['LOG_DIR'] = directory_name
            print(f"Created directory and set environment variable LOG_DIR to {directory_name}")
        except Exception as e:
            print(f"Failed to create directory or set environment variable: {e}")

def main():
    entries = read_log_entries()
    find_earliest_latest(entries)

    start_time = time.time()
    unique_count = count_unique_messages(entries)
    end_time = time.time()
    print(f"Number of unique log messages: {unique_count}")
    print(f"Time taken to calculate unique message count: {end_time - start_time} seconds")

    create_directory_and_set_env_var("log_directory")

if __name__ == "__main__":
    main()
```

