#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LABELS 1000
#define RECORD_POOL_SIZE 10000

typedef struct {
    float value;
    char label;
    float weight;
} Record;

typedef struct {
    Record *records;
    int size;
    int capacity;
    pthread_mutex_t lock;
} RecordPool;

RecordPool record_pool = {NULL, 0, RECORD_POOL_SIZE, PTHREAD_MUTEX_INITIALIZER};

void init_record_pool() {
    record_pool.records = (Record *)malloc(record_pool.capacity * sizeof(Record));
    if (!record_pool.records) {
        fprintf(stderr, "Failed to allocate memory for record pool\n");
        exit(EXIT_FAILURE);
    }
}

Record *allocate_record(float value, char label, float weight) {
    pthread_mutex_lock(&record_pool.lock);
    if (record_pool.size >= record_pool.capacity) {
        Record *new_records = (Record *)realloc(record_pool.records, record_pool.capacity * 2 * sizeof(Record));
        if (!new_records) {
            fprintf(stderr, "Failed to reallocate memory for record pool\n");
            pthread_mutex_unlock(&record_pool.lock);
            exit(EXIT_FAILURE);
        }
        record_pool.records = new_records;
        record_pool.capacity *= 2;
    }
    Record *record = &record_pool.records[record_pool.size++];
    record->value = value;
    record->label = label;
    record->weight = weight;
    pthread_mutex_unlock(&record_pool.lock);
    return record;
}

void free_record_pool() {
    pthread_mutex_lock(&record_pool.lock);
    free(record_pool.records);
    record_pool.records = NULL;
    record_pool.size = 0;
    record_pool.capacity = RECORD_POOL_SIZE;
    pthread_mutex_unlock(&record_pool.lock);
}

int main() {
    init_record_pool();

    // Example usage
    Record *record1 = allocate_record(1.5, 'A', 0.3);
    Record *record2 = allocate_record(2.5, 'B', 0.4);

    printf("Record 1: Value=%f, Label=%c, Weight=%f\n", record1->value, record1->label, record1->weight);
    printf("Record 2: Value=%f, Label=%c, Weight=%f\n", record2->value, record2->label, record2->weight);

    free_record_pool();
    return 0;
}
```

