import hashlib
import json
import requests
from concurrent.futures import ThreadPoolExecutor

def fetch_data(source_url):
    try:
        response = requests.get(source_url)
        response.raise_for_status()
        return response.json()
    except requests.RequestException as e:
        print(f"Failed to fetch data from {source_url}: {e}")
        return None

def replace_placeholders(template, data):
    for key, value in data.items():
        template = template.replace(f"${key}", str(value))
    return template

def validate_checksum(file_path, expected_checksum):
    with open(file_path, 'rb') as file:
        file_data = file.read()
        actual_checksum = hashlib.md5(file_data).hexdigest()
        return actual_checksum == expected_checksum

def update_config(template_path, json_payload, data_sources):
    with open(template_path, 'r') as file:
        template = file.read()

    updated_templates = []
    for source in data_sources:
        data = fetch_data(source)
        if data:
            updated_template = replace_placeholders(template, data)
            updated_templates.append(updated_template)

    return updated_templates

def main(config_file_path, json_payload):
    with open(json_payload, 'r') as file:
        payload = json.load(file)

    template_path = payload.get('template_path')
    expected_checksum = payload.get('expected_checksum')
    data_sources = payload.get('data_sources', [])

    if not validate_checksum(template_path, expected_checksum):
        print("Checksum validation failed. Aborting update.")
        return

    updated_templates = update_config(template_path, json_payload, data_sources)

    for template in updated_templates:
        # Simulate writing to a network device
        print(f"Updated configuration: {template}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 3:
        print("Usage: python script.py <config_file_path> <json_payload>")
    else:
        main(sys.argv[1], sys.argv[2])
