    if (count <= 0 || min_value >= max_value) {
        return NULL;
    }

    srand(time(NULL));
    Transaction* transactions = malloc(count * sizeof(Transaction));
    if (!transactions) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        transactions[i].value = min_value + (double)rand() / RAND_MAX * (max_value - min_value);
        transactions[i].id = malloc(13); // Assuming a maximum ID length of 12 characters
        if (!transactions[i].id) {
            fprintf(stderr, "Memory allocation failed for transaction %d\n", i);
            free(transactions);
            return NULL;
        }
        snprintf(transactions[i].id, 13, "TXN%d", i);

        transactions[i].point.x = (float)rand() / RAND_MAX * 100.0f - 50.0f; // Random float between -50 and 50
        transactions[i].point.y = (float)rand() / RAND_MAX * 100.0f - 50.0f;
    }

    return transactions;
}

void free_transactions(Transaction* transactions, int count) {
    if (!transactions) {
        return;
    }

    for (int i = 0; i < count; ++i) {
        free(transactions[i].id);
    }
    free(transactions);
}

