#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256

typedef struct sensorData {
    int timeStamp;
    int sensorId;
    float temperature;
    struct sensorData *next;
} SensorData;

typedef struct eventLog {
    int eventId;
    int logTime;
    char status[100];
    struct eventLog *next;
} EventLog;

SensorData* createSensorNode(int timeStamp, int sensorId, float temperature) {
    SensorData* newNode = (SensorData*)malloc(sizeof(SensorData));
    if (newNode == NULL) {
        perror("Failed to allocate memory for sensor node");
        exit(EXIT_FAILURE);
    }
    newNode->timeStamp = timeStamp;
    newNode->sensorId = sensorId;
    newNode->temperature = temperature;
    newNode->next = NULL;
    return newNode;
}

EventLog* createEventNode(int eventId, int logTime, const char* status) {
    EventLog* newNode = (EventLog*)malloc(sizeof(EventLog));
    if (newNode == NULL) {
        perror("Failed to allocate memory for event node");
        exit(EXIT_FAILURE);
    }
    newNode->eventId = eventId;
    newNode->logTime = logTime;
    strncpy(newNode->status, status, sizeof(newNode->status) - 1);
    newNode->next = NULL;
    return newNode;
}

void insertSensorData(SensorData** head, int timeStamp, int sensorId, float temperature) {
    SensorData* newNode = createSensorNode(timeStamp, sensorId, temperature);
    if (*head == NULL) {
        *head = newNode;
    } else {
        SensorData* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void insertEventLog(EventLog** head, int eventId, int logTime, const char* status) {
    EventLog* newNode = createEventNode(eventId, logTime, status);
    if (*head == NULL) {
        *head = newNode;
    } else {
        EventLog* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void freeSensorList(SensorData** head) {
    SensorData* current = *head;
    SensorData* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

void freeEventList(EventLog** head) {
    EventLog* current = *head;
    EventLog* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int parseFile(const char* filename, SensorData** sensorHead, EventLog** eventHead) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return -1;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        // Assuming the format is: sensorId,timeStamp,temperature,eventId,logTime,status
