#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays(long** offsets, int** keys, Record** records, int num_records) {
    *offsets = safe_malloc(num_records * sizeof(long));
    *keys = safe_malloc(num_records * sizeof(int));
    *records = safe_malloc(num_records * sizeof(Record));

    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = i * 10;
        (*keys)[i] = rand() % 100;
        (*records)[i].value = rand() % 100;
    }
}

void free_arrays(long* offsets, int* keys, Record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int find_largest_key(int* keys, int num_keys) {
    int largest = keys[0];
    for (int i = 1; i < num_keys; i++) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }
    return largest;
}

void union_find_init(int* parent, int size) {
    for (int i = 0; i < size; i++) {
        parent[i] = i;
    }
}

int find(int* parent, int i) {
    if (parent[i] != i) {
        parent[i] = find(parent, parent[i]);
    }
    return parent[i];
}

void union_sets(int* parent, int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);
    if (rootX != rootY) {
        parent[rootX] = rootY;
    }
}

int count_disjoint_pairs(int* keys, int num_keys, int* parent) {
    int disjoint_count = 0;
    for (int i = 0; i < num_keys - 1; i++) {
        clock_t start = clock();
        if (find(parent, keys[i]) != find(parent, keys[i + 1])) {
            disjoint_count++;
        }
        clock_t end = clock();
        printf("Disjoint pair check %d took %ld milliseconds\n", i, (end - start) * 1000 / CLOCKS_PER_SEC);
    }
    return disjoint_count;
}

int main() {
    srand(time(NULL));
    int num_records = MAX_RECORDS;
    long* offsets;
    int* keys;
    Record* records;

    initialize_arrays(&offsets, &keys, &records, num_records);

    int largest_key = find_largest_key(keys, num_records);
    printf("Largest key: %d\n", largest_key);

    int* parent = safe_malloc(num_records * sizeof(int));
    union_find_init(parent, num_records);

    count_disjoint_pairs(keys, num_records, parent);

    free_arrays(offsets, keys, records);
    free(parent);

    return 0;
}
