#define MAX_RECORD_SIZE 1024

typedef struct {
    int value;
} record;

void log_message(const char* message) {
    printf("%s\n", message);
}

record* initialize_records(int num_records, int range_start, int range_end) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (range_end - range_start + 1) + range_start;
    }
    return records;
}

void free_records(record* records, int num_records) {
    if (records) {
        free(records);
        log_message("Records memory freed");
    }
}

int find_largest(int* array, int size) {
    if (!array || size <= 0) {
        log_message("Invalid input for finding largest value");
        return -1;
    }
    int max_value = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }
    return max_value;
}

void read_input(int* input_array, int* input_size) {
    *input_size = 0;
    while (scanf("%d", &input_array[*input_size]) == 1) {
        (*input_size)++;
        if (*input_size >= MAX_RECORD_SIZE) {
            log_message("Input array size exceeded");
            break;
        }
    }
}

int main() {
    int num_records, range_start, range_end;
    printf("Enter number of records: ");
    scanf("%d", &num_records);
    printf("Enter range start and end for random values: ");
    scanf("%d %d", &range_start, &range_end);

    record* records = initialize_records(num_records, range_start, range_end);
    if (!records) {
        return 1;
    }

    int input_size;
    int* input_array = (int*)malloc(MAX_RECORD_SIZE * sizeof(int));
    if (!input_array) {
        log_message("Memory allocation failed for input array");
        free_records(records, num_records);
        return 1;
    }
    read_input(input_array, &input_size);

    int largest_value = find_largest(input_array, input_size);
    printf("Largest value in input array: %d\n", largest_value);

    free(input_array);
    free_records(records, num_records);

    log_message("Program completed successfully");
    return 0;
}
