#define MAX_INTERFACES 1000
#define MAX_LINE_LENGTH 256

typedef struct {
    char name[32];
    char ip[16];
    char subnet_mask[16];
    char gateway[16];
    int value;
} NetworkInterface;

NetworkInterface* network_interfaces[MAX_INTERFACES];
int interface_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* parse_config_file(void* arg) {
    const char* filename = (const char*)arg;
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        NetworkInterface* interface = malloc(sizeof(NetworkInterface));
        if (!interface) {
            fprintf(stderr, "Memory allocation failed\n");
            continue;
        }
        pthread_mutex_lock(&mutex);
        network_interfaces[interface_count++] = interface;
        pthread_mutex_unlock(&mutex);

        // Parse and validate the line here
        // Example: sscanf(line, "%31s %15s %15s %15s", interface->name, interface->ip, interface->subnet_mask, interface->gateway);
        // Initialize value with a random number within a specified range
        interface->value = rand() % 1000;
    }

    fclose(file);
    return NULL;
}

void find_highest_value_interface() {
    if (interface_count == 0) {
        printf("No valid interfaces found.\n");
        return;
    }

    NetworkInterface* highest_interface = network_interfaces[0];
    for (int i = 1; i < interface_count; i++) {
        if (network_interfaces[i]->value > highest_interface->value) {
            highest_interface = network_interfaces[i];
        }
    }

    printf("Interface with the highest value: %s\n", highest_interface->name);
}

int main() {
    pthread_t thread;
    const char* filename = "config.txt";

    if (pthread_create(&thread, NULL, parse_config_file, (void*)filename) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    find_highest_value_interface();

    // Free allocated memory
    for (int i = 0; i < interface_count; i++) {
        free(network_interfaces[i]);
    }

    return EXIT_SUCCESS;
}
