#include <string.h>

typedef struct {
    UserSessionState session_state;
    SecurityContext *security_context;
} NetworkEventLog_t;

typedef struct {
    NetworkEventLog_t **logs;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SessionLog_t;

void init_session_log(SessionLog_t *log) {
    log->logs = NULL;
    log->count = 0;
    log->capacity = 0;
    pthread_mutex_init(&log->lock, NULL);
}

void free_session_log(SessionLog_t *log) {
    for (size_t i = 0; i < log->count; ++i) {
        free(log->logs[i]->security_context);
        free(log->logs[i]);
    }
    free(log->logs);
    pthread_mutex_destroy(&log->lock);
}

void add_session_state(SessionLog_t *log, UserSessionState state) {
    pthread_mutex_lock(&log->lock);
    if (log->count == log->capacity) {
        size_t new_capacity = log->capacity ? log->capacity * 2 : 1;
        NetworkEventLog_t **new_logs = realloc(log->logs, new_capacity * sizeof(NetworkEventLog_t *));
        if (!new_logs) {
            pthread_mutex_unlock(&log->lock);
            return; // Handle memory allocation failure
        }
        log->logs = new_logs;
        log->capacity = new_capacity;
    }
    NetworkEventLog_t *new_log = malloc(sizeof(NetworkEventLog_t));
    if (!new_log) {
        pthread_mutex_unlock(&log->lock);
        return; // Handle memory allocation failure
    }
    new_log->session_state = state;
    new_log->security_context = allocate_security_context(state); // Assume this function exists
    log->logs[log->count++] = new_log;
    pthread_mutex_unlock(&log->lock);
}

void update_session_state(SessionLog_t *log, UserSessionState state) {
    pthread_mutex_lock(&log->lock);
    for (size_t i = 0; i < log->count; ++i) {
        if (log->logs[i]->session_state == state) {
            free(log->logs[i]->security_context);
            log->logs[i]->security_context = allocate_security_context(state); // Assume this function exists
            break;
        }
    }
    pthread_mutex_unlock(&log->lock);
}

void process_session_logs(SessionLog_t *log, void (*process_func)(SecurityContext *)) {
    pthread_mutex_lock(&log->lock);
    for (size_t i = 0; i < log->count; ++i) {
        process_func(log->logs[i]->security_context);
    }
    pthread_mutex_unlock(&log->lock);
}

void purge_inactive_sessions(SessionLog_t *log, time_t expiration_time) {
    pthread_mutex_lock(&log->lock);
    for (size_t i = 0; i < log->count;) {
        if (log->logs[i]->session_state.last_activity < expiration_time) {
            free(log->logs[i]->security_context);
            free(log->logs[i]);
            memmove(&log->logs[i], &log->logs[i + 1], (log->count - i - 1) * sizeof(NetworkEventLog_t *));
            --log->count;
        } else {
            ++i;
        }
    }
    pthread_mutex_unlock(&log->lock);
}

void monitor_memory_usage(SessionLog_t *log, size_t threshold) {
