#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    long offset;
    int key;
    double value;
    char name[50];
    bool active;
} record;

typedef struct {
    int parent[MAX_RECORDS];
    int rank[MAX_RECORDS];
} UnionFind;

void initUnionFind(UnionFind *uf, int n) {
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void unionSet(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int countDisjointSets(UnionFind *uf, int n) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (uf->parent[i] == i)
            count++;
    }
    return count;
}

record* initializeRecords(int *numRecords, long offsetRange, int keyRange, double valueRange, char **userNames) {
    record *records = (record *)malloc(*numRecords * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    UnionFind uf;
    initUnionFind(&uf, *numRecords);

    srand(time(NULL));

    for (int i = 0; i < *numRecords; i++) {
        records[i].offset = rand() % offsetRange;
        records[i].key = rand() % keyRange;
        records[i].value = ((double)rand() / RAND_MAX) * valueRange;
        strncpy(records[i].name, userNames[rand() % 5], sizeof(records[i].name));
        records[i].active = (rand() % 2 == 0);

        int parentKey = find(&uf, records[i].key);
        if (parentKey != records[i].key) {
            unionSet(&uf, records[i].key, parentKey);
        }
    }

    *numRecords = countDisjointSets(&uf, *numRecords);

    return records;
}

void freeRecords(record *records, int numRecords) {
    free(records);
}

int main() {
    int numRecords = 100;
    long offsetRange = 10000;
    int keyRange = 500;
    double valueRange = 100.0;
    char *userNames[] = {"Alice", "Bob", "Charlie", "David", "Eve"};

    record *records = initializeRecords(&numRecords, offsetRange, keyRange, valueRange, userNames);

    printf("Number of disjoint sets: %d\n", numRecords);

    freeRecords(records, numRecords);

    return 0;
}
