#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_GROUPS 1024
#define INITIAL_CAPACITY 16

typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    int *keys;
    Record **records;
    int size;
    int capacity;
} HashTable;

typedef struct {
    int parent[MAX_GROUPS];
    int rank[MAX_GROUPS];
} UnionFind;

HashTable* create_hash_table() {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->keys = (int*)calloc(INITIAL_CAPACITY, sizeof(int));
    ht->records = (Record**)calloc(INITIAL_CAPACITY, sizeof(Record*));
    ht->size = 0;
    ht->capacity = INITIAL_CAPACITY;
    return ht;
}

void resize_hash_table(HashTable *ht) {
    int new_capacity = ht->capacity * 2;
    int *new_keys = (int*)realloc(ht->keys, new_capacity * sizeof(int));
    Record **new_records = (Record**)realloc(ht->records, new_capacity * sizeof(Record*));

    if (new_keys == NULL || new_records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    ht->keys = new_keys;
    ht->records = new_records;
    ht->capacity = new_capacity;
}

void insert_hash_table(HashTable *ht, int key, Record *record) {
    if (ht->size == ht->capacity) {
        resize_hash_table(ht);
    }
    ht->keys[ht->size] = key;
    ht->records[ht->size++] = record;
}

int find(UnionFind *uf, int i) {
    if (uf->parent[i] != i) {
        uf->parent[i] = find(uf, uf->parent[i]);
    }
    return uf->parent[i];
}

void union_sets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int largest_key(HashTable *ht) {
    int max_key = INT_MIN;
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] > max_key) {
            max_key = ht->keys[i];
        }
    }
    return max_key;
}

void free_hash_table(HashTable *ht) {
    free(ht->keys);
    for (int i = 0; i < ht->size; i++) {
        free(ht->records[i]);
    }
    free(ht->records);
    free(ht);
}

void process_dataset(int size, long *offsets, int *keys, Record *records, int *groups) {
    HashTable *ht = create_hash_table();
    UnionFind uf;

    for (int i = 0; i < MAX_GROUPS; i++) {
        uf.parent[i] = i;
        uf.rank[i] = 0;
    }

    clock_t start, end;
    double cpu_time_used;

    start = clock();
    for (int i = 0; i < size; i++) {
        Record *record = (Record*)malloc(sizeof(Record));
        record->key = keys[i];
        record->value = rand() % 1000 + 1;
        insert_hash_table(ht, keys[i], record);
        union_sets(&uf, groups[i], find(&uf, groups[i]));
    }
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Record processing time: %f seconds\n", cpu_time_used);

    int max_key = largest_key(ht);
    printf("Largest key in dataset: %d\n", max_key);

    free_hash_table(ht);
}

int main() {
    srand(time(NULL));
    int size = 10000;
    long *offsets = (long*)malloc(size * sizeof(long));
    int *keys = (int*)malloc(size * sizeof(int));
    Record *records = (Record*)malloc(size * sizeof(Record));
    int *groups = (int*)malloc(size * sizeof(int));

    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % MAX_GROUPS + 1;
        groups[i] = rand() % MAX_GROUPS + 1;
    }

    process_dataset(size, offsets, keys, records, groups);

    free(offsets);
    free(keys);
    free(records);
    free(groups);

    return 0;
}
