typedef struct {
    float value;
    char label[MAX_LABEL_LENGTH];
    float weight;
} Record;

typedef struct {
    Record *records;
    int size;
    int capacity;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool;

void init_memory_pool() {
    pool.records = (Record *)malloc(MAX_RECORDS * sizeof(Record));
    if (!pool.records) {
        fprintf(stderr, "Failed to allocate memory for record pool\n");
        exit(EXIT_FAILURE);
    }
    pool.size = 0;
    pool.capacity = MAX_RECORDS;
    pthread_mutex_init(&pool.lock, NULL);
}

void free_memory_pool() {
    pthread_mutex_lock(&pool.lock);
    free(pool.records);
    pthread_mutex_unlock(&pool.lock);
    pthread_mutex_destroy(&pool.lock);
}

int add_record(float value, const char *label, float weight) {
    pthread_mutex_lock(&pool.lock);
    if (pool.size >= pool.capacity) {
        fprintf(stderr, "Memory pool is full\n");
        pthread_mutex_unlock(&pool.lock);
        return -1;
    }
    Record *record = &pool.records[pool.size++];
    record->value = value;
    strncpy(record->label, label, MAX_LABEL_LENGTH - 1);
    record->label[MAX_LABEL_LENGTH - 1] = '\0';
    record->weight = weight;
    pthread_mutex_unlock(&pool.lock);
    return 0;
}

void cleanup_labels() {
    pthread_mutex_lock(&pool.lock);
    for (int i = 0; i < pool.size; ++i) {
        if (pool.records[i].weight == 0.0f) {
            // Remove unused label
            pool.records[i] = pool.records[--pool.size];
        }
    }
    pthread_mutex_unlock(&pool.lock);
}

void *process_batch(void *batch_data) {
    // Process batch of records
    return NULL;
}

int main() {
    init_memory_pool();

    // Example usage
    add_record(1.0f, "Label1", 0.5f);
    add_record(2.0f, "Label2", 0.3f);

    cleanup_labels();

    free_memory_pool();
    return 0;
}
