#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1000

typedef struct {
    int value;
} record;

int allocate_memory(long *offsets, int *keys, record **records, long offsets_size, int keys_size) {
    if (offsets_size + keys_size > MAX_SIZE) {
        fprintf(stderr, "Error: Total size exceeds maximum limit.\n");
        return -1;
    }

    offsets = (long *)calloc(offsets_size, sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets.\n");
        return -1;
    }

    keys = (int *)malloc(keys_size * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Error: Failed to allocate memory for keys.\n");
        return -1;
    }

    *records = (record *)calloc(offsets_size + keys_size, sizeof(record));
    if (!*records) {
        free(keys);
        free(offsets);
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        return -1;
    }

    srand(time(NULL));
    for (int i = 0; i < offsets_size + keys_size; i++) {
        (*records)[i].value = rand() % 1000; // Random value between 0 and 999
    }

    return offsets_size + keys_size;
}

int main() {
    long offsets_size, keys_size;
    printf("Enter the size of the offsets array: ");
    scanf("%ld", &offsets_size);
    printf("Enter the size of the keys array: ");
    scanf("%d", &keys_size);

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;

    int total_records = allocate_memory(offsets, keys, &records, offsets_size, keys_size);

    if (total_records != -1) {
        printf("Successfully allocated %d records.\n", total_records);
        // Free allocated memory
        free(records);
        free(keys);
        free(offsets);
    }

    return 0;
}
