#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void initialize_data(long *offsets, int *keys, record **records, int num_records, long min_offset, long max_offset, int min_key, int max_key, int unique_values) {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_offset - min_offset + 1) + min_offset;
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
        records[i] = malloc(sizeof(record));
        if (unique_values) {
            int unique_value;
            do {
                unique_value = rand() % (max_key - min_key + 1) + min_key;
            } while (find_unique_value(records, num_records, unique_value));
            records[i]->value = unique_value;
        } else {
            records[i]->value = rand() % (max_key - min_key + 1) + min_key;
        }
    }
}

int find_unique_value(record **records, int num_records, int value) {
    for (int i = 0; i < num_records; i++) {
        if (records[i]->value == value) {
            return 1;
        }
    }
    return 0;
}

void serialize_data(long *offsets, int *keys, record **records, int num_records, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(offsets, sizeof(long), num_records, file);
    fwrite(keys, sizeof(int), num_records, file);

    for (int i = 0; i < num_records; i++) {
        fwrite(records[i], sizeof(record), 1, file);
    }

    fclose(file);
}

void deserialize_data(long **offsets, int **keys, record ***records, int *num_records, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }

    fread(num_records, sizeof(int), 1, file);
    *offsets = malloc(*num_records * sizeof(long));
    *keys = malloc(*num_records * sizeof(int));
    *records = malloc(*num_records * sizeof(record *));

    fread(*offsets, sizeof(long), *num_records, file);
    fread(*keys, sizeof(int), *num_records, file);

    for (int i = 0; i < *num_records; i++) {
        (*records)[i] = malloc(sizeof(record));
        fread((*records)[i], sizeof(record), 1, file);
    }

    fclose(file);
}

void free_data(long *offsets, int *keys, record **records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}
