from elasticsearch import Elasticsearch
from elasticsearch_dsl import Search, Q
from functools import lru_cache
import time

class DocumentRetrievalService:
    def __init__(self, es_host='localhost', es_port=9200):
        self.es = Elasticsearch([{'host': es_host, 'port': es_port}])

    @lru_cache(maxsize=128)
    def search_documents(self, query, page=1, size=10, fields=None, boost=None):
        s = Search(using=self.es, index="documents")

        if query:
            q = Q("multi_match", query=query, fields=fields or ["content"])
            if boost:
                for field, b in boost.items():
                    q &= Q("function_score", query=q, functions=[Q("field_value_factor", field=field, factor=b)])
            s = s.query(q)

        s = s.from_(page * size - size).size(size)

        response = s.execute()
        return response

    def paginate_documents(self, query, page=1, size=10):
        try:
            result = self.search_documents(query, page, size)
            return {
                'total': result.hits.total.value,
                'page': page,
                'size': size,
                'results': [hit.to_dict() for hit in result]
            }
        except Exception as e:
            print(f"Error during pagination: {e}")
            return {'error': str(e)}

    def handle_edge_cases(self, query):
        if not query.strip():
            return {'message': 'Empty query provided'}

        try:
            return self.paginate_documents(query)
        except Exception as e:
            return {'error': str(e)}
```

