#include <string.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    int size;
} data_structure;

data_structure* create_data_structure(int size, int key_range) {
    data_structure* ds = (data_structure*)malloc(sizeof(data_structure));
    if (!ds) return NULL;

    ds->size = size;
    ds->offsets = (long*)malloc(size * sizeof(long));
    ds->keys = (int*)malloc(size * sizeof(int));
    ds->records = (record**)malloc(size * sizeof(record*));

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        ds->offsets[i] = rand() % 1000L;
        ds->keys[i] = rand() % key_range;
        ds->records[i] = (record*)malloc(sizeof(record));
        if (!ds->records[i]) {
            for (int j = 0; j < i; j++) free(ds->records[j]);
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            free(ds);
            return NULL;
        }
        ds->records[i]->value = rand() % 100;
    }

    return ds;
}

void update_data_structure(data_structure* ds, int index, int new_value) {
    if (index >= 0 && index < ds->size) {
        ds->records[index]->value = new_value;
    }
}

void delete_data_structure(data_structure* ds) {
    for (int i = 0; i < ds->size; i++) free(ds->records[i]);
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}

