<?php

class ResourceAPI {
    private $db;
    private $logger;

    public function __construct($db, $logger) {
        $this->db = $db;
        $this->logger = $logger;
    }

    public function updateResource($id, $data) {
        try {
            $this->db->beginTransaction();
            // Update resource logic here
            $updatedResource = $this->db->update('resources', $data, ['id' => $id]);
            $this->db->commit();
            $this->logger->log("Updated resource with ID: $id");
            return $updatedResource;
        } catch (\Exception $e) {
            $this->db->rollBack();
            $this->logger->error("Failed to update resource with ID: $id. Error: " . $e->getMessage());
            throw new \Exception("Failed to update resource.");
        }
    }

    public function deleteResource($id) {
        try {
            $this->db->beginTransaction();
            // Delete resource logic here
            $deleted = $this->db->delete('resources', ['id' => $id]);
            $this->db->commit();
            $this->logger->log("Deleted resource with ID: $id");
            return ['id' => $id, 'status' => 'deleted'];
        } catch (\Exception $e) {
            $this->db->rollBack();
            $this->logger->error("Failed to delete resource with ID: $id. Error: " . $e->getMessage());
            throw new \Exception("Failed to delete resource.");
        }
    }

    public function generateRandomString($length, $characters) {
        return substr(str_shuffle(str_repeat($characters, ceil($length / strlen($characters)))), 1, $length);
    }

    public function hashPassword($password) {
        return password_hash($password, PASSWORD_DEFAULT);
    }

    // Add more methods as needed for the API
}

// Usage example:
