    int thread_count = 0;

    for (int i = 0; i < size; i++) {
        if (thread_count >= MAX_CONCURRENT_OPERATIONS) {
            // Wait for some threads to finish
            for (int j = 0; j < MAX_CONCURRENT_OPERATIONS; j++) {
                pthread_join(threads[j], NULL);
                thread_count--;
