        int result = pthread_create(&threads[thread_count++], NULL, read_data_thread, records[i]);
        if (result != 0) {
            perror("Failed to create thread");
            free_records(records, i + 1);
            return EXIT_FAILURE;
        }
    }

    // Wait for all threads to finish
    while (thread_count > 0) {
        pthread_join(threads[--thread_count], NULL);
    }

    log_memory_usage();
    free_records(records, size);

    return EXIT_SUCCESS;
