#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef enum {
    TEMPERATURE,
    HUMIDITY,
    PRESSURE
} measurementType;

typedef struct {
    double value;
    char identifier;
    int timestamp;
    measurementType type;
} dataPoint;

typedef struct {
    dataPoint* points;
    size_t capacity;
    size_t size;
} sensorDataCollection;

void logMessage(const char* message) {
    printf("%s\n", message);
}

sensorDataCollection* initializeSensorDataCollection(size_t initialCapacity) {
    sensorDataCollection* collection = (sensorDataCollection*)malloc(sizeof(sensorDataCollection));
    if (collection == NULL) {
        logMessage("Failed to allocate memory for sensor data collection.");
        return NULL;
    }
    collection->points = (dataPoint*)calloc(initialCapacity, sizeof(dataPoint));
    if (collection->points == NULL) {
        logMessage("Failed to allocate memory for data points.");
        free(collection);
        return NULL;
    }
    collection->capacity = initialCapacity;
    collection->size = 0;
    logMessage("Sensor data collection initialized successfully.");
    return collection;
}

void addDataPoint(sensorDataCollection* collection, double value, char identifier, measurementType type) {
    if (collection->size >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        dataPoint* newPoints = (dataPoint*)realloc(collection->points, newCapacity * sizeof(dataPoint));
        if (newPoints == NULL) {
            logMessage("Failed to reallocate memory for data points.");
            return;
        }
        collection->points = newPoints;
        collection->capacity = newCapacity;
    }
    collection->points[collection->size].value = value;
    collection->points[collection->size].identifier = identifier;
    collection->points[collection->size].timestamp = (int)time(NULL);
    collection->points[collection->size].type = type;
    collection->size++;
}

void cleanupSensorDataCollection(sensorDataCollection* collection) {
    if (collection != NULL) {
        free(collection->points);
        free(collection);
        logMessage("Sensor data collection cleaned up successfully.");
    }
}
