    if (count > MAX_DATA_POINTS) {
        fprintf(stderr, "Error: Exceeds maximum allowed data points.\n");
        return NULL;
    }

    data_point* points = malloc(count * sizeof(data_point));
    if (!points) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        points[i].value = min_value + (double)rand() / RAND_MAX * (max_value - min_value);
        points[i].description = malloc(100 * sizeof(char)); // Assuming max description length
        if (!points[i].description) {
            fprintf(stderr, "Error: Memory allocation failed for description.\n");
            free(points); // Free previously allocated memory
            return NULL;
        }
        snprintf(points[i].description, 100, "Point %d", i);
    }

    return points;
}

