    if (count == 0) {
        printf("No data points available.\n");
        return;
    }

    double max_value = points[0].value;
    for (int i = 1; i < count; ++i) {
        if (points[i].value > max_value) {
            max_value = points[i].value;
        }
    }
    printf("Largest value: %f\n", max_value);
}

void free_data_points(data_point* points, int count) {
    for (int i = 0; i < count; ++i) {
        free(points[i].description);
    }
    free(points);
