import os
import time

class PacketEntry:
    def __init__(self, header, timestamp, node_id):
        self.header = header
        self.timestamp = timestamp
        self.node_id = node_id

def initialize_packet_entries(num_entries):
    return [None] * num_entries

def allocate_resources(packet_entries):
    try:
        for i in range(len(packet_entries)):
            packet_entries[i] = PacketEntry(f"Header_{i}", time.time(), f"Node_{i}")
        return True
    except MemoryError:
        print("Memory allocation failed")
        return False

def find_earliest_latest_packets(packet_entries):
    if not packet_entries:
        return None, None

    earliest = min(packet_entries, key=lambda x: x.timestamp)
    latest = max(packet_entries, key=lambda x: x.timestamp)

    return earliest, latest

def count_unique_source_ips(packet_entries):
    source_ips = set()
    for entry in packet_entries:
        # Assuming the header contains the source IP address
        source_ip = entry.header.split()[0]
        source_ips.add(source_ip)
    return len(source_ips)

def create_directory_and_set_env_var(directory_name):
    if os.environ.get('MONITORING_DIR'):
        print(f"Environment variable MONITORING_DIR already set to {os.environ['MONITORING_DIR']}")
    else:
        os.makedirs(directory_name, exist_ok=True)
        os.environ['MONITORING_DIR'] = directory_name
        print(f"Created directory {directory_name} and set environment variable MONITORING_DIR")

def evaluate_data_storage_strategies(packet_entries):
    start_time = time.time()
    unique_ips = count_unique_source_ips(packet_entries)
    end_time = time.time()
    print(f"Number of unique source IPs: {unique_ips}, Time taken: {end_time - start_time} seconds")

# Example usage
num_entries = 1000
packet_entries = initialize_packet_entries(num_entries)
if allocate_resources(packet_entries):
    earliest, latest = find_earliest_latest_packets(packet_entries)
    print(f"Earliest packet: {earliest.header}, Timestamp: {earliest.timestamp}")
    print(f"Latest packet: {latest.header}, Timestamp: {latest.timestamp}")

    unique_ips_count = count_unique_source_ips(packet_entries)
    print(f"Number of unique source IPs: {unique_ips_count}")

    create_directory_and_set_env_var("monitoring_data")

    evaluate_data_storage_strategies(packet_entries)
