void printDisjointPairs(int* keys, int size) {
    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < size - 1; i++) {
        for (int j = i + 1; j < size; j++) {
            start = clock();
            // Perform disjointness test using Union-Find
            end = clock();
            cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
            printf("Disjoint pair (%d, %d): Time taken %.2f ms\n", keys[i], keys[j], cpu_time_used * 1000);
        }
    }
}

int main() {
    int size;
    printf("Enter the number of elements: ");
    scanf("%d", &size);

    if (size > MAX_MEMORY_THRESHOLD / sizeof(int)) {
        fprintf(stderr, "Memory allocation exceeds threshold\n");
        return EXIT_FAILURE;
    }

    int* keys = malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        return EXIT_FAILURE;
    }

    printf("Enter the elements:\n");
    for (int i = 0; i < size; i++) {
        scanf("%d", &keys[i]);
    }

    int largest = findLargest(keys, size);
    printf("Largest element: %d\n", largest);

    printDisjointPairs(keys, size);

    free(keys);

    return EXIT_SUCCESS;
}
