#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_records(record** records, int* keys, long* offsets, int num_records, int key_range, int value_range) {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % key_range;
        offsets[i] = rand();
        records[i]->value = rand() % value_range;
    }
}

void resize_records(record** records, int* keys, long* offsets, int* current_size, int new_size) {
    record* new_records = (record*)allocate_memory(new_size * sizeof(record));
    int* new_keys = (int*)allocate_memory(new_size * sizeof(int));
    long* new_offsets = (long*)allocate_memory(new_size * sizeof(long));

    for (int i = 0; i < *current_size && i < new_size; i++) {
        new_records[i] = records[i];
        new_keys[i] = keys[i];
        new_offsets[i] = offsets[i];
    }

    free(records);
    free(keys);
    free(offsets);

    *records = new_records;
    *keys = new_keys;
    *offsets = new_offsets;
    *current_size = new_size;
}

void sort_records(record** records, int* keys, int num_records, int (*compare)(const void*, const void*)) {
    qsort(records, num_records, sizeof(record), compare);
}

int main() {
    int num_records = 1000;
    record* records = (record*)allocate_memory(num_records * sizeof(record));
    int* keys = (int*)allocate_memory(num_records * sizeof(int));
    long* offsets = (long*)allocate_memory(num_records * sizeof(long));

    initialize_records(&records, keys, offsets, num_records, 100, 1000);

    // Example comparison function for ascending order
    int compare_keys(const void* a, const void* b) {
        return (*(int*)a - *(int*)b);
    }

    sort_records(&records, keys, num_records, compare_keys);

    free(records);
    free(keys);
    free(offsets);

    return 0;
}
