        points[i].value = min_value + (double)rand() / RAND_MAX * (max_value - min_value);
        scanf(" %c", &points[i].indicator); // Read character indicator
    }
    return points;
}

void free_data_points(data_point *points, int size) {
    if (points != NULL) {
        free(points);
        log_message("Memory freed.");
    }
}

int find(int parent[], int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void union_set(int parent[], int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset) {
        parent[xset] = yset;
    }
}

int count_disjoint_pairs(data_point *points, int size) {
    int *parent = (int*)calloc(size, sizeof(int));
    for (int i = 0; i < size; ++i)
        parent[i] = -1;

    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < size; ++i) {
        start = clock();
        for (int j = i + 1; j < size; ++j) {
            if (points[i].indicator == points[j].indicator) {
                union_set(parent, i, j);
            }
        }
        end = clock();
        cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;
        printf("Disjoint pair check %d took %.2f milliseconds\n", i, cpu_time_used * 1000);
    }

    int disjoint_pairs = 0;
    for (int i = 0; i < size; ++i) {
        if (parent[i] == -1)
            disjoint_pairs++;
    }
    free(parent);
    return disjoint_pairs;
}

int main() {
    int size, min_value, max_value;
    printf("Enter the number of data points: ");
    scanf("%d", &size);
    printf("Enter the minimum and maximum values for random doubles: ");
    scanf("%lf %lf", &min_value, &max_value);

    data_point *points = initialize_data_points(size, min_value, max_value);
    if (points != NULL) {
        int disjoint_pairs = count_disjoint_pairs(points, size);
        printf("Number of disjoint pairs: %d\n", disjoint_pairs);
        free_data_points(points, size);
    }

    return 0;
}
