typedef struct Record {
    int key;
    long offset;
    struct Record* next;
} Record;

typedef struct RecordCollection {
    Record** records;
    size_t capacity;
    size_t size;
    long minOffset;
    long maxOffset;
} RecordCollection;

RecordCollection* createRecordCollection(size_t initialCapacity, long minOffset, long maxOffset) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)calloc(initialCapacity, sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initialCapacity;
    collection->size = 0;
    collection->minOffset = minOffset;
    collection->maxOffset = maxOffset;

    return collection;
}

int insertRecord(RecordCollection* collection, int key, long offset) {
    if (key < 0 || offset < collection->minOffset || offset > collection->maxOffset) return -1;

    Record** records = collection->records;
    size_t capacity = collection->capacity;
    size_t size = collection->size;

    if (size == capacity) {
        capacity *= 2;
        Record** newRecords = (Record**)realloc(records, capacity * sizeof(Record*));
        if (!newRecords) return -1;
        records = newRecords;
        collection->records = records;
        collection->capacity = capacity;
    }

    for (size_t i = 0; i < size; ++i) {
        if (records[i]->key == key || records[i]->offset == offset) return -1;
    }

    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (!newRecord) return -1;

    newRecord->key = key;
    newRecord->offset = offset;
    newRecord->next = NULL;

    records[size] = newRecord;
    collection->size++;

    return 0;
}

void iterateRecordsReverse(RecordCollection* collection) {
    Record** records = collection->records;
    size_t size = collection->size;

    for (int i = size - 1; i >= 0; --i) {
        printf("Key: %d, Offset: %ld\n", records[i]->key, records[i]->offset);
    }
}

void cleanupRecordCollection(RecordCollection* collection) {
    Record** records = collection->records;
    size_t size = collection->size;

    for (size_t i = 0; i < size; ++i) {
        free(records[i]);
    }

    free(records);
    free(collection);
}
