#include <pthread.h>

#define MAX_RECORD_SIZE 1024 * 1024 // Maximum size constraint in bytes

typedef struct {
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    if (collection) {
        free(collection->records);
        pthread_mutex_destroy(&collection->mutex);
        free(collection);
    }
}

int add_record(RecordCollection* collection, int key_range_start, int key_range_end) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Allocation failure
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record* record = &collection->records[collection->size];
    record->offset = collection->size * sizeof(Record);
    record->key = key_range_start + rand() % (key_range_end - key_range_start + 1);
    record->timestamp = time(NULL) + (double)rand() / RAND_MAX;

    collection->size++;
    pthread_mutex_unlock(&collection->mutex);

    return 0;
}

Record* get_record_by_offset(RecordCollection* collection, long offset) {
    if (offset < 0 || offset >= collection->size * sizeof(Record)) return NULL;

    return &collection->records[offset / sizeof(Record)];
}

int update_record(RecordCollection* collection, long offset, int new_key) {
    Record* record = get_record_by_offset(collection, offset);
    if (!record) return -1; // Invalid offset

    pthread_mutex_lock(&collection->mutex);

    record->key = new_key;

    pthread_mutex_unlock(&collection->mutex);

    return 0;
}
