const { Kafka } = require('kafkajs');
const axios = require('axios');

class DataProcessor {
  constructor(config) {
    this.config = config;
    this.kafka = new Kafka(config.kafka);
    this.consumer = this.kafka.consumer({ groupId: 'data-processor' });
    this.producer = this.kafka.producer();
    this.state = { paused: false, lastProcessedId: null };
    this.retryQueue = [];
  }

  async init() {
    await this.consumer.connect();
    await this.consumer.subscribe({ topic: this.config.topic });
    await this.consumer.run({
      eachMessage: async ({ message }) => {
        if (this.state.paused) return;
        try {
          const data = JSON.parse(message.value.toString());
          await this.processData(data);
          this.state.lastProcessedId = data.id;
        } catch (error) {
          console.error('Error processing data:', error);
          this.retryQueue.push({ message, attempts: 0 });
        }
      },
    });

    setInterval(async () => {
      while (this.retryQueue.length > 0) {
        const { message, attempts } = this.retryQueue.shift();
        try {
          await this.processData(JSON.parse(message.value.toString()));
          this.state.lastProcessedId = JSON.parse(message.value.toString()).id;
        } catch (error) {
          if (attempts < this.config.maxRetries) {
            this.retryQueue.push({ message, attempts: attempts + 1 });
            setTimeout(() => this.retryQueue.push({ message, attempts }), this.calculateRetryDelay(attempts));
          }
        }
      }
    }, this.config.retryInterval);
  }

  async processData(data) {
    try {
      const transformedData = await this.transformData(data);
      await this.storeData(transformedData);
      await this.notifyStateChange();
    } catch (error) {
      console.error('Error processing data:', error);
    }
  }

  async transformData(data) {
    // Implement data transformation logic here
    return data;
  }

  async storeData(data) {
    // Implement data storage logic here
  }

  async notifyStateChange() {
    try {
      await this.producer.connect();
      await this.producer.send({
        topic: 'state-changes',
        messages: [
          { value: JSON.stringify(this.state) },
        ],
      });
      await this.producer.disconnect();
    } catch (error) {
      console.error('Error notifying state change:', error);
    }
  }

  calculateRetryDelay(attempts) {
    const baseDelay = Math.pow(2, attempts) * 100;
    return baseDelay + Math.floor(Math.random() * 50); // Jitter
  }

  pauseProcessing() {
    this.state.paused = true;
  }

  resumeProcessing() {
    this.state.paused = false;
  }
}

module.exports = DataProcessor;
