    manager->records = (Record*)malloc(memory_quota * sizeof(Record));
    if (!manager->offsets || !manager->keys || !manager->records) {
        fprintf(stderr, "Failed to allocate memory for arrays\n");
        free(manager);
        return NULL;
    }
    manager->allocated_records = memory_quota;
    manager->used_records = 0;
    manager->memory_quota = memory_quota;
    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    if (manager) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager);
    }
}

int add_record(MemoryManager* manager, long offset, int key, int value) {
    if (manager->used_records >= manager->allocated_records) {
        fprintf(stderr, "Memory quota exceeded\n");
        return -1;
    }
    manager->offsets[manager->used_records] = offset;
    manager->keys[manager->used_records] = key;
    manager->records[manager->used_records].value = value;
    manager->used_records++;
    return 0;
}

int get_record_value(MemoryManager* manager, int key) {
