typedef struct Record {
    long offset;
    int key;
    char status;
} Record;

typedef struct KeySet {
    int* keys;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} KeySet;

Record** create_records(size_t initial_capacity, size_t max_capacity) {
    // Allocate memory for records
    Record** records = (Record**)malloc(initial_capacity * sizeof(Record*));
    if (!records) {
        return NULL; // Handle memory allocation failure
    }

    // Initialize records to NULL
    for (size_t i = 0; i < initial_capacity; ++i) {
        records[i] = NULL;
    }

    return records;
}

KeySet* create_key_set(size_t capacity) {
    KeySet* key_set = (KeySet*)malloc(sizeof(KeySet));
    if (!key_set) {
        return NULL; // Handle memory allocation failure
    }

    key_set->keys = (int*)calloc(capacity, sizeof(int));
    if (!key_set->keys) {
        free(key_set);
        return NULL; // Handle memory allocation failure
    }

    key_set->capacity = capacity;
    key_set->size = 0;
    pthread_mutex_init(&key_set->lock, NULL);

    return key_set;
}

int insert_record(Record** records, KeySet* key_set, long offset, int key, char status) {
    if (key_set->size >= key_set->capacity) {
        // Resize the key set
        size_t new_capacity = key_set->capacity * 2;
        int* new_keys = (int*)realloc(key_set->keys, new_capacity * sizeof(int));
        if (!new_keys) {
            return -1; // Handle memory allocation failure
        }
        key_set->keys = new_keys;
        key_set->capacity = new_capacity;
    }

    pthread_mutex_lock(&key_set->lock);
    for (size_t i = 0; i < key_set->size; ++i) {
        if (key_set->keys[i] == key) {
            pthread_mutex_unlock(&key_set->lock);
            return -1; // Duplicate key
        }
    }
    key_set->keys[key_set->size++] = key;
    pthread_mutex_unlock(&key_set->lock);

    // Allocate memory for the new record
    records[offset % 1024] = (Record*)malloc(sizeof(Record));
    if (!records[offset % 1024]) {
        return -1; // Handle memory allocation failure
    }

    records[offset % 1024]->offset = offset;
    records[offset % 1024]->key = key;
    records[offset % 1024]->status = status;

    return 0;
}

void free_records(Record** records, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        if (records[i]) {
            free(records[i]);
        }
    }
    free(records);
}

void destroy_key_set(KeySet* key_set) {
    pthread_mutex_destroy(&key_set->lock);
    free(key_set->keys);
    free(key_set);
}
