function mergeAndAnalyzeChunks(chunks) {
    const startTime = performance.now();

    let totalLength = 0;
    chunks.forEach(chunk => {
        if (chunk instanceof Buffer) {
            totalLength += chunk.length;
        } else {
            throw new Error('Invalid chunk type');
        }
    });

    const mergedBuffer = Buffer.allocUnsafe(totalLength);
    let offset = 0;

    chunks.forEach(chunk => {
        chunk.copy(mergedBuffer, offset);
        offset += chunk.length;
    });

    const disjointPairs = identifyDisjointPairs(mergedBuffer);

    const endTime = performance.now();
    console.log(`Chunk processing time: ${endTime - startTime} ms`);

    return { mergedBuffer, disjointPairs };
}

function identifyDisjointPairs(buffer) {
    // Implement a custom Union-Find data structure to track disjoint pairs
    // This is a simplified example and should be optimized for large-scale data
    const parent = new Array(buffer.length).fill(0);
    for (let i = 0; i < buffer.length; i++) {
        parent[i] = i;
    }

    function find(x) {
        if (parent[x] !== x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    function union(x, y) {
        const rootX = find(x);
        const rootY = find(y);
        if (rootX !== rootY) {
            parent[rootX] = rootY;
        }
    }

    for (let i = 0; i < buffer.length - 1; i++) {
        if (buffer[i] !== buffer[i + 1]) {
            union(i, i + 1);
        }
    }

    const disjointPairs = new Set();
    for (let i = 0; i < parent.length; i++) {
        if (parent[i] === i) {
            disjointPairs.add(i);
        }
    }

    return disjointPairs;
}
