void manage_memory(int num_elements, const char* user_string, long seed) {
    if (num_elements <= 0 || strlen(user_string) > INT_MAX) {
        fprintf(stderr, "Invalid input size or string length.\n");
        return;
    }

    // Allocate memory for long offsets and int keys arrays
    long* offsets = malloc(num_elements * sizeof(long));
    int* keys = malloc(num_elements * sizeof(int));

    if (offsets == NULL || keys == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Allocate memory for record structures array
    record* records = malloc(num_elements * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize random seed
    srand(seed);

    // Initialize each record structure
    for (int i = 0; i < num_elements; i++) {
        records[i].value = rand() % INT_MAX;
        records[i].str = malloc(strlen(user_string) + 1);
        if (records[i].str == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            for (int j = 0; j < i; j++) {
                free(records[j].str);
            }
            free(offsets);
            free(keys);
            free(records);
            return;
        }
        strcpy(records[i].str, user_string);
    }

    // Free allocated memory
    for (int i = 0; i < num_elements; i++) {
        free(records[i].str);
    }
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int num_elements = 1000000;
    const char* user_string = "example";
    long seed = time(NULL);

    manage_memory(num_elements, user_string, seed);

    return 0;
}
