#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_OFFSETS 10000

typedef struct {
    int key;
    long *offset;
} Record;

int allocate_memory(long **long_offsets, int **int_keys, Record **records, int n) {
    size_t total_size = sizeof(long) * MAX_OFFSETS + sizeof(int) * n + sizeof(Record) * n;
    void *memory = malloc(total_size);
    if (!memory) return -1;

    *long_offsets = (long *)memory;
    *int_keys = (int *)(*long_offsets + MAX_OFFSETS);
    *records = (Record *)(*int_keys + n);

    for (int i = 0; i < MAX_OFFSETS; ++i) {
        (*long_offsets)[i] = 0;
    }
    for (int i = 0; i < n; ++i) {
        (*int_keys)[i] = 0;
        (*records)[i].key = 0;
        (*records)[i].offset = NULL;
    }

    return 0;
}

void initialize_records(Record *records, int n, long *long_offsets, int *int_keys) {
    srand(time(NULL));
    for (int i = 0; i < n;) {
        int key = rand() % MAX_OFFSETS;
        if (!int_keys[key]) {
            records[i].key = key;
            records[i].offset = &long_offsets[key];
            int_keys[key] = 1;
            ++i;
        }
    }

    for (int i = 0; i < n; ++i) {
        records[i].key = rand() % MAX_OFFSETS;
        while (records[i].key == records[(i + 1) % n].key) {
            records[i].key = rand() % MAX_OFFSETS;
        }
    }

    for (int i = 0; i < n; ++i) {
        records[i].offset = &long_offsets[records[i].key];
    }
}

void swap_fields(Record *records, int n) {
    for (int i = 0; i < n; ++i) {
        long temp = *records[i].offset;
        *records[i].offset = records[i].key;
        records[i].key = temp;
    }
}

void free_memory(long **long_offsets, int **int_keys, Record **records) {
    free(*long_offsets);
    free(*int_keys);
    free(*records);
}

int main() {
    long *long_offsets;
    int *int_keys;
    Record *records;
    int n = 5000;

    if (allocate_memory(&long_offsets, &int_keys, &records, n) != 0) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    initialize_records(records, n, long_offsets, int_keys);
    swap_fields(records, n);

    free_memory(&long_offsets, &int_keys, &records);

    return 0;
}
