    new_chunk->next = NULL;
    return new_chunk;
}

void insert_file_chunk(file_chunk **head, uint64_t offset, size_t size) {
    file_chunk *new_chunk = create_file_chunk(offset, size);
    if (*head == NULL) {
        *head = new_chunk;
    } else {
        file_chunk *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_chunk;
    }
}

void iterate_reverse_file_chunks(file_chunk *head) {
    if (head == NULL) return;

    // Find the last node
    file_chunk *last = head;
    while (last->next != NULL) {
        last = last->next;
    }

    // Iterate from the last node to the first
    while (last != NULL) {
        printf("Offset: %llu, Size: %zu\n", last->offset, last->size);
        last = last->prev;  // Assuming prev pointer is maintained for reverse iteration
    }
}

void free_file_chunks(file_chunk *head) {
    file_chunk *current = head;
    while (current != NULL) {
        file_chunk *next = current->next;
        free(current);
        current = next;
    }
}
