typedef struct {
    int key;
    char *message;
    size_t length;
    int updated;
} LogRecord;

LogRecord* createLoggingRecords(int numRecords, size_t maxMessageLength, int seed, int minValue, int maxValue) {
    srand(seed);
    LogRecord *records = (LogRecord *)malloc(numRecords * sizeof(LogRecord));
    if (!records) return NULL;

    for (int i = 0; i < numRecords; ++i) {
        records[i].key = rand() % (maxValue - minValue + 1) + minValue;
        while (i > 0 && records[i].key == records[i - 1].key) {
            records[i].key = rand() % (maxValue - minValue + 1) + minValue;
        }
        records[i].message = (char *)calloc(maxMessageLength, sizeof(char));
        if (!records[i].message) {
            for (int j = 0; j < i; ++j) free(records[j].message);
            free(records);
            return NULL;
        }
        records[i].length = rand() % maxMessageLength + 1;
        for (size_t j = 0; j < records[i].length; ++j) {
            records[i].message[j] = 'A' + rand() % ('Z' - 'A' + 1);
        }
        records[i].message[records[i].length] = '\0';
        records[i].updated = 0;
    }

    return records;
}

void freeLoggingRecords(LogRecord *records, int numRecords) {
    for (int i = 0; i < numRecords; ++i) {
        free(records[i].message);
    }
    free(records);
}
