from flask import Flask, request, jsonify
import hashlib
import redis
import subprocess
import time
import logging

app = Flask(__name__)
redis_client = redis.StrictRedis(host='localhost', port=6379, db=0)
logging.basicConfig(level=logging.INFO)

def generate_script_identifier(script_name):
    return hashlib.sha256(script_name.encode()).hexdigest()

def execute_script(script_path):
    try:
        start_time = time.time()
        result = subprocess.run(['python', script_path], capture_output=True, text=True, timeout=30)
        duration = time.time() - start_time
        if result.returncode == 0:
            logging.info(f"Script executed successfully in {duration:.2f} seconds")
            return result.stdout, None
        else:
            logging.error(f"Script execution failed with error: {result.stderr}")
            return None, result.stderr
    except subprocess.TimeoutExpired:
        logging.error("Script execution timed out")
        return None, "Timeout"
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
        return None, str(e)

@app.route('/execute_script', methods=['POST'])
def execute():
    data = request.json
    script_name = data.get('script_name')
    if not script_name:
        return jsonify({"error": "Script name is required"}), 400

    script_identifier = generate_script_identifier(script_name)
    cached_result = redis_client.get(script_identifier)
    if cached_result:
        logging.info("Returning cached result")
        return jsonify({"result": cached_result.decode()}), 200

    script_path = f"./scripts/{script_name}.py"
    result, error = execute_script(script_path)
    if result is not None:
        redis_client.setex(script_identifier, 3600, result)  # Cache for 1 hour
        return jsonify({"result": result}), 200
    else:
        return jsonify({"error": error}), 500

if __name__ == '__main__':
    app.run(debug=True)
