#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NODES 1000
#define MEM_LIMIT 1024 * 1024 // 1MB

typedef struct Node {
    char* id;
    struct Node** neighbors;
    int neighbor_count;
    int max_neighbors;
} Node;

typedef struct Graph {
    Node* nodes[MAX_NODES];
    int node_count;
    int max_nodes;
    pthread_mutex_t lock;
} Graph;

Graph* create_graph() {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    if (!graph) return NULL;

    graph->node_count = 0;
    graph->max_nodes = MAX_NODES;
    pthread_mutex_init(&graph->lock, NULL);

    for (int i = 0; i < MAX_NODES; i++) {
        graph->nodes[i] = NULL;
    }

    return graph;
}

Node* create_node(const char* id) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->id = strdup(id);
    node->neighbors = (Node**)malloc(MAX_NODES * sizeof(Node*));
    if (!node->neighbors) {
        free(node->id);
        free(node);
        return NULL;
    }

    node->neighbor_count = 0;
    node->max_neighbors = MAX_NODES;

    return node;
}

void add_node(Graph* graph, Node* node) {
    pthread_mutex_lock(&graph->lock);
    if (graph->node_count < graph->max_nodes) {
        graph->nodes[graph->node_count++] = node;
    }
    pthread_mutex_unlock(&graph->lock);
}

void add_edge(Graph* graph, const char* src_id, const char* dest_id) {
    pthread_mutex_lock(&graph->lock);
    for (int i = 0; i < graph->node_count; i++) {
        if (strcmp(graph->nodes[i]->id, src_id) == 0) {
            Node* src_node = graph->nodes[i];
            for (int j = 0; j < graph->node_count; j++) {
                if (strcmp(graph->nodes[j]->id, dest_id) == 0) {
                    Node* dest_node = graph->nodes[j];
                    if (src_node->neighbor_count < src_node->max_neighbors) {
                        src_node->neighbors[src_node->neighbor_count++] = dest_node;
                    }
                    break;
                }
            }
            break;
        }
    }
    pthread_mutex_unlock(&graph->lock);
}

void delete_graph(Graph* graph) {
    pthread_mutex_lock(&graph->lock);
    for (int i = 0; i < graph->node_count; i++) {
        free(graph->nodes[i]->id);
        free(graph->nodes[i]->neighbors);
        free(graph->nodes[i]);
    }
    pthread_mutex_unlock(&graph->lock);

    pthread_mutex_destroy(&graph->lock);
    free(graph);
}

int main() {
    Graph* graph = create_graph();
    Node* node1 = create_node("A");
    Node* node2 = create_node("B");

    add_node(graph, node1);
    add_node(graph, node2);

    add_edge(graph, "A", "B");

    delete_graph(graph);

    return 0;
}
