#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    int id;
    double value;
    char* name;
} Record;

typedef struct node {
    Record data;
    struct node* next;
} Node;

typedef struct memory_manager {
    Node** offset_map;
    int* key_map;
    Record* record_pool;
    int pool_size;
    int pool_index;
    pthread_mutex_t lock;
} MemoryManager;

MemoryManager* create_memory_manager(int pool_size) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) {
        fprintf(stderr, "Failed to allocate memory for MemoryManager\n");
        return NULL;
    }
    manager->offset_map = (Node**)calloc(pool_size, sizeof(Node*));
    if (!manager->offset_map) {
        fprintf(stderr, "Failed to allocate memory for offset map\n");
        free(manager);
        return NULL;
    }
    manager->key_map = (int*)malloc(pool_size * sizeof(int));
    if (!manager->key_map) {
        fprintf(stderr, "Failed to allocate memory for key map\n");
        free(manager->offset_map);
        free(manager);
        return NULL;
    }
    manager->record_pool = (Record*)calloc(pool_size, sizeof(Record));
    if (!manager->record_pool) {
        fprintf(stderr, "Failed to allocate memory for record pool\n");
        free(manager->key_map);
        free(manager->offset_map);
        free(manager);
        return NULL;
    }
    manager->pool_size = pool_size;
    manager->pool_index = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    for (int i = 0; i < manager->pool_index; i++) {
        free(manager->record_pool[i].name);
    }
    free(manager->offset_map);
    free(manager->key_map);
    free(manager->record_pool);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

Node* create_node(Record data) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Failed to allocate memory for Node\n");
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    return node;
}

void destroy_node(Node* node) {
    free(node);
}

int add_record(MemoryManager* manager, Record data) {
    pthread_mutex_lock(&manager->lock);
    if (manager->pool_index >= manager->pool_size) {
        fprintf(stderr, "Memory pool is full\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    int index = manager->pool_index++;
    manager->record_pool[index] = data;
    Node* node = create_node(data);
    if (!node) {
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    manager->offset_map[index] = node;
    manager->key_map[data.id] = index;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_record(MemoryManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);
    if (id < 0 || id >= manager->pool_size || !manager->key_map[id]) {
        fprintf(stderr, "Invalid record ID\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    int index = manager->key_map[id];
    Node* node = manager->offset_map[index];
    if (!node) {
        fprintf(stderr, "Record not found\n");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    manager->offset_map[index] = NULL;
    manager->key_map[id] = 0;
    destroy_node(node);
    manager->pool_index--;
    for (int i = index; i < manager->pool_index; i++) {
        manager->record_pool[i] = manager->record_pool[i + 1];
        manager->offset_map[i] = manager->offset_map[i + 1];
        manager->key_map[manager->record_pool[i].id] = i;
    }
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

Record* get_record(MemoryManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);
    if (id < 0 || id >= manager->pool_size || !manager->key_map[id]) {
        fprintf(stderr, "Invalid record ID\n");
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }
    int index = manager->key_map[id];
    Node* node = manager->offset_map[index];
    if (!node) {
        fprintf(stderr, "Record not found\n");
        pthread_mutex_unlock(&manager->lock);
        return NULL;
    }
    Record* data = &manager->record_pool[index];
    pthread_mutex_unlock(&manager->lock);
    return data;
}
