#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 100000

typedef struct {
    int value;
} record;

int validate_input(int num_offsets, int num_records) {
    if (num_offsets < 0 || num_records < 0) {
        fprintf(stderr, "Error: Negative input values are not allowed.\n");
        return -1;
    }
    return 0;
}

int* initialize_offsets(int num_offsets, long factor) {
    int* offsets = (int*)malloc(num_offsets * sizeof(int));
    if (!offsets) {
        fprintf(stderr, "Error: Memory allocation failed for offsets array.\n");
        return NULL;
    }
    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = i * factor;
    }
    return offsets;
}

record* initialize_records(int num_records, int min_value, int max_value) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Number of records exceeds maximum allowed.\n");
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed for records array.\n");
        return NULL;
    }

    srand(time(NULL));
    int values[MAX_RECORDS] = {0};
    int count = 0;

    while (count < num_records) {
        int random_value = min_value + rand() % (max_value - min_value + 1);
        if (!values[random_value]) {
            records[count].value = random_value;
            values[random_value] = 1;
            ++count;
        }
    }

    return records;
}

void free_memory(int* offsets, record* records) {
    free(offsets);
    free(records);
}

int main() {
    int num_offsets = 100;
    long factor = 100;
    int min_value = 100;
    int max_value = 1000;

    if (validate_input(num_offsets, num_records) != 0) {
        return -1;
    }

    int* offsets = initialize_offsets(num_offsets, factor);
    record* records = initialize_records(num_records, min_value, max_value);

    if (!offsets || !records) {
        free_memory(offsets, records);
        return -1;
    }

    // Process data here...

    free_memory(offsets, records);
    return 0;
}
