import java.util.concurrent.*;
import java.util.logging.*;

public class ServiceManager {
    private static final Logger logger = Logger.getLogger(ServiceManager.class.getName());
    private ExecutorService executor;
    private BlockingQueue<Runnable> taskQueue;
    private int maxInstances;
    private int currentInstances;

    public ServiceManager(int initialInstances, int maxInstances) {
        this.maxInstances = maxInstances;
        this.currentInstances = initialInstances;
        this.taskQueue = new LinkedBlockingQueue<>();
        this.executor = Executors.newFixedThreadPool(initialInstances);
    }

    public void startService(Runnable task) {
        if (currentInstances < maxInstances) {
            currentInstances++;
            executor.execute(task);
            logger.info("Service started. Current instances: " + currentInstances);
        } else {
            logger.warning("Max instances reached. Unable to start service.");
        }
    }

    public void stopService(Runnable task) {
        if (currentInstances > 0) {
            currentInstances--;
            executor.remove(task);
            logger.info("Service stopped. Current instances: " + currentInstances);
        } else {
            logger.warning("No active instances to stop.");
        }
    }

    public void scaleService(int targetInstances) {
        if (targetInstances > maxInstances || targetInstances < 0) {
            logger.warning("Invalid target instances. Must be between 0 and maxInstances.");
            return;
        }

        while (currentInstances < targetInstances) {
            startService(() -> {
                // Service logic here
                logger.info("Running service task");
            });
        }

        while (currentInstances > targetInstances) {
            stopService(executor.getQueue().poll());
        }
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }
        logger.info("Service manager shut down.");
    }

    public static void main(String[] args) {
        ServiceManager serviceManager = new ServiceManager(2, 5);
        serviceManager.scaleService(3);

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            serviceManager.shutdown();
        }));
    }
}
