    if (!double_arr) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Populate double array
    for (int i = 0; i < num_records; ++i) {
        *records[i].dbl_ptr = records[i].value * 0.1;
    }

    // Step 5: Error handling and memory management
    if (!long_arr || !int_keys || !double_arr) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    // Free allocated memory
    for (int i = 0; i < num_records; ++i) {
        free(records[i].str);
        free(records[i].dbl_ptr);
    }
    free(records);
    free(double_arr);

    printf("Memory management completed successfully.\n");
}

int main() {
    manage_memory();
    return 0;
