#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* str;
} record;

void allocate_memory(long** long_offsets, int** int_keys, record** records, int size) {
    *long_offsets = (long*)malloc(size * sizeof(long));
    *int_keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));

    if (*long_offsets == NULL || *int_keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
}

void initialize_records(record* records, int size, const char* str, int seed) {
    srand(seed);

    for (int i = 0; i < size; i++) {
        records[i].value = rand() % 1000;
        records[i].str = strdup(str);
        if (records[i].str == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
}

void free_memory(long* long_offsets, int* int_keys, record* records, int size) {
