void read_input(int** int_keys, int* size) {
    printf("Enter the number of elements: ");
    scanf("%d", size);

    if (*size <= 0) {
        fprintf(stderr, "Invalid input size\n");
        exit(1);
    }

    *int_keys = (int*)malloc(*size * sizeof(int));

    if (*int_keys == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    printf("Enter the elements:\n");
    for (int i = 0; i < *size; i++) {
        scanf("%d", &(*int_keys)[i]);
    }
}

void find_largest_integer(int* int_keys, int size) {
    if (size == 0) {
        printf("No elements to process\n");
        return;
    }

    int largest = int_keys[0];

    for (int i = 1; i < size; i++) {
        if (int_keys[i] > largest) {
            largest = int_keys[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

void calculate_disjoint_pairs(int* int_keys, int size) {
    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < size - 1; i++) {
        for (int j = i + 1; j < size; j++) {
            start = clock();
            // Perform disjoint pair check using Union-Find
            // ...
            end = clock();
            cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
            printf("Disjoint pair (%d, %d) took %.3f milliseconds\n", int_keys[i], int_keys[j], cpu_time_used * 1000);
        }
    }
}

int main() {
    long* long_offsets;
    int* int_keys;
    record* records;
    int size;

    allocate_memory(&long_offsets, &int_keys, &records, 10000000); // Adjust size as needed
    initialize_records(records, 10000000, "example", time(NULL)); // Adjust size and seed as needed

    read_input(&int_keys, &size);
    find_largest_integer(int_keys, size);

    calculate_disjoint_pairs(int_keys, size);

    free_memory(long_offsets, int_keys, records, 10000000); // Adjust size as needed

    return 0;
}
