#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000

typedef struct {
    int key;
    long *value;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool pool;

void init_memory_pool() {
    memset(pool.records, 0, sizeof(pool.records));
    pthread_mutex_init(&pool.lock, NULL);
}

Record* allocate_record(long *value) {
    pthread_mutex_lock(&pool.lock);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (!pool.records[i].key) {
            pool.records[i].key = rand();
            pool.records[i].value = value;
            pthread_mutex_unlock(&pool.lock);
            return &pool.records[i];
        }
    }
    pthread_mutex_unlock(&pool.lock);
    return NULL;
}

void free_record(Record *record) {
    pthread_mutex_lock(&pool.lock);
    record->key = 0;
    record->value = NULL;
    pthread_mutex_unlock(&pool.lock);
}

void* allocate_memory(size_t size) {
    return malloc(size);
}

void deallocate_memory(void *ptr, size_t size) {
    free(ptr);
}

int main() {
    init_memory_pool();

    long offsets[10000] = {0};
    int keys[5000];
    for (int i = 0; i < 5000; i++) {
        keys[i] = rand();
    }

    Record *records = allocate_record(offsets);
    if (!records) {
        return -1;
    }

    // Set record values and swap fields
    for (int i = 0; i < 5000; i++) {
        records->key = keys[i];
        records->value = &offsets[keys[i]];
        // Swap fields
        long temp = *records->value;
        *records->value = records->key;
        records->key = temp;
    }

    free_record(records);

    return 0;
}
