#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define LONG_ARRAY_SIZE 10000

typedef struct {
    int key;
    long *offset;
} Record;

void* custom_alloc(size_t size) {
    // Implement a simple custom allocator here
    return malloc(size);
}

void custom_free(void* ptr) {
    free(ptr);
}

void manage_memory(int n) {
    long *long_array = (long*)custom_alloc(LONG_ARRAY_SIZE * sizeof(long));
    int *int_array = (int*)custom_alloc(n * sizeof(int));
    Record *record_array = (Record*)custom_alloc(n * sizeof(Record));

    // Initialize arrays
    memset(long_array, 0, LONG_ARRAY_SIZE * sizeof(long));
    memset(int_array, 0, n * sizeof(int));
    for (int i = 0; i < n; i++) {
        record_array[i].key = 0;
        record_array[i].offset = NULL;
    }

    // Allocate memory for records
    for (int i = 0; i < n; i++) {
        record_array[i].offset = (long*)custom_alloc(sizeof(long));
        *record_array[i].offset = 0;
    }

    // Set random values for records with unique keys
    srand(time(NULL));
    int used_keys[n];
    memset(used_keys, 0, n * sizeof(int));
    for (int i = 0; i < n; i++) {
        int key;
        do {
            key = rand() % n;
        } while (used_keys[key]);
        used_keys[key] = 1;
        record_array[i].key = key;
        *record_array[i].offset = rand();
    }

    // Swap long and int fields in records
    for (int i = 0; i < n; i++) {
        long temp = *record_array[i].offset;
        *record_array[i].offset = record_array[i].key;
        record_array[i].key = temp;
    }

    // Free allocated memory
    custom_free(long_array);
    custom_free(int_array);
    for (int i = 0; i < n; i++) {
        custom_free(record_array[i].offset);
    }
    custom_free(record_array);
}

int main() {
    int n = 1000;
    manage_memory(n);
    return 0;
}
