record* create_records(int num_records, int min_value, int max_value, int* hash_table_size) {
    // Allocate memory for records
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL; // Handle allocation failure
    }

    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for hash table
    *hash_table_size = num_records;
    int* hash_table = (int*)calloc(*hash_table_size, sizeof(int));
    if (!hash_table) {
        free(records);
        return NULL; // Handle allocation failure
    }

    // Initialize records with random values and unique keys
    for (int i = 0; i < num_records; ++i) {
        int value;
        do {
            value = rand() % (max_value - min_value + 1) + min_value;
        } while (hash_table[value - min_value] != 0);
        hash_table[value - min_value] = 1;

        records[i].offset = i * sizeof(record); // Example offset calculation
        records[i].key = value;
        records[i].value = value; // Assigning the same value for simplicity
    }

    return records;
}

void free_records(record* records, int num_records, int hash_table_size) {
    if (records) {
        free(records);
    }
    if (hash_table_size > 0) {
        free(hash_table);
    }
}
