    bool isReady;
} DataStructure;

void initializeDataStructure(DataStructure* ds, size_t size, long* offsetValues, int* keyValues) {
    ds->offsets = (long*)malloc(size * sizeof(long));
    if (!ds->offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(EXIT_FAILURE);
    }

    ds->keys = (int*)malloc(size * sizeof(int));
    if (!ds->keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(ds->offsets);
        exit(EXIT_FAILURE);
    }

    ds->records = (Record*)malloc(size * sizeof(Record));
    if (!ds->records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(ds->offsets);
        free(ds->keys);
        exit(EXIT_FAILURE);
    }

    ds->count = size;
    ds->isReady = false;

    for (size_t i = 0; i < size; ++i) {
        ds->offsets[i] = offsetValues[i];
        ds->keys[i] = keyValues[i];
        ds->records[i].value = calculateRecordValue(offsetValues[i], keyValues[i]);
        ds->records[i].isValid = true;
    }

    validateDataStructure(ds);
}

int calculateRecordValue(long offset, int key) {
    // Custom algorithm to combine offset and key values
    return (offset * 31 + key) % 1000; // Example algorithm
}

void validateDataStructure(DataStructure* ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        if (!ds->records[i].isValid) {
            fprintf(stderr, "Invalid record found at index %zu\n", i);
            // Handle invalid records gracefully
        }
    }
}

void resetDataStructure(DataStructure* ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    ds->offsets = NULL;
    ds->keys = NULL;
    ds->records = NULL;
    ds->count = 0;
    ds->isReady = false;
}

