<?php

class UserService {
    private $identityService;
    private $auditLogService;
    private $notificationService;
    private $rateLimiter;
    private $circuitBreaker;
    private $requestQueue;

    public function __construct(
        IdentityService $identityService,
        AuditLogService $auditLogService,
        NotificationService $notificationService,
        RateLimiter $rateLimiter,
        CircuitBreaker $circuitBreaker,
        RequestQueue $requestQueue
    ) {
        $this->identityService = $identityService;
        $this->auditLogService = $auditLogService;
        $this->notificationService = $notificationService;
        $this->rateLimiter = $rateLimiter;
        $this->circuitBreaker = $circuitBreaker;
        $this->requestQueue = $requestQueue;
    }

    public function updatePassword($userId, $oldPassword, $newPassword, $role) {
        if (!$this->rateLimiter->allowRequest($_SERVER['REMOTE_ADDR'])) {
            return ['status' => 'error', 'message' => 'Too many requests. Please try again later.', 'code' => 429];
        }

        if ($this->circuitBreaker->isOpen()) {
            return ['status' => 'error', 'message' => 'Service unavailable. Please try again later.', 'code' => 503];
        }

        $this->requestQueue->enqueue(function() use ($userId, $oldPassword, $newPassword, $role) {
            if (!$this->identityService->validateOldPassword($userId, $oldPassword)) {
                return ['status' => 'error', 'message' => 'Invalid old password.', 'code' => 403];
            }

            if (!$this->identityService->isPasswordComplexEnough($newPassword)) {
                return ['status' => 'error', 'message' => 'New password does not meet complexity requirements.', 'code' => 400];
            }

            if (!$this->identityService->validateFirstFactorAuthentication()) {
                return ['status' => 'error', 'message' => 'First factor authentication failed.', 'code' => 401];
            }

            if (!$this->identityService->validateSecondFactorAuthentication()) {
                return ['status' => 'error', 'message' => 'Second factor authentication failed.', 'code' => 401];
            }

            try {
                $this->circuitBreaker->attempt(function() use ($userId, $newPassword, $role) {
                    $this->identityService->updateUserPassword($userId, $newPassword);
                    $this->identityService->updateUserRole($userId, $role);
                });
            } catch (\Exception $e) {
                return ['status' => 'error', 'message' => 'Failed to update user.', 'code' => 500];
            }

            $this->auditLogService->logPasswordUpdateAttempt($userId, $_SERVER['REMOTE_ADDR'], true);

            try {
                $this->notificationService->sendConfirmationMessage($userId, 'password_update');
            } catch (\Exception $e) {
                // Log notification failure but continue with the operation
                error_log('Notification failed: ' . $e->getMessage());
            }

            return ['status' => 'success', 'message' => 'Password updated successfully.', 'code' => 200];
        });
    }
}
