typedef enum {
    TYPE_A,
    TYPE_B,
    TYPE_C,
    TYPE_D
} RecordType;

typedef struct {
    int key;
    char buffer[256];
    size_t length;
    bool modified;
    RecordType type;
    long offset;
    int another_key;
} Record;

typedef struct {
    Record* records;
    size_t count;
} RecordStorage;

RecordStorage* initialize_and_manage_records(size_t num_records, long* offsets, int* keys, int seed) {
    if (num_records == 0 || offsets == NULL || keys == NULL) {
        return NULL;
    }

    RecordStorage* storage = (RecordStorage*)malloc(sizeof(RecordStorage));
    if (storage == NULL) {
        return NULL;
    }

    storage->records = (Record*)calloc(num_records, sizeof(Record));
    if (storage->records == NULL) {
        free(storage);
        return NULL;
    }

    srand(seed);

    for (size_t i = 0; i < num_records; ++i) {
        Record* record = &storage->records[i];
        record->key = keys[i];
        record->length = strlen(record->buffer);
        record->modified = false;
        record->type = (RecordType)(rand() % TYPE_D + 1);
        record->offset = offsets[i];
        record->another_key = rand();
    }

    storage->count = num_records;

    return storage;
}

void free_record_storage(RecordStorage* storage) {
    if (storage != NULL) {
        free(storage->records);
        free(storage);
    }
}
