    if (*offsets == NULL) {
        // Handle out-of-memory condition
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }

    *keys = (int*)aligned_alloc(64, max_size * sizeof(int));
    if (*keys == NULL) {
