        free(*offsets);
        fprintf(stderr, "Failed to allocate memory for keys\n");
        exit(EXIT_FAILURE);
    }

    *records = (record**)malloc(max_size * sizeof(record*));
    if (*records == NULL) {
        // Handle out-of-memory condition
        free(*offsets);
        free(*keys);
        fprintf(stderr, "Failed to allocate memory for records pointers\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (size_t i = 0; i < max_size; ++i) {
        (*records)[i] = (record*)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            // Handle out-of-memory condition
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            fprintf(stderr, "Failed to allocate memory for record %zu\n", i);
            exit(EXIT_FAILURE);
        }

        (*offsets)[i] = (long)i;
        (*keys)[i] = (int)i;
        (*records)[i]->value = rand() % 100; // Random value between 0 and 99
        (*records)[i]->buffer = (char*)malloc(256); // Example buffer size
        if ((*records)[i]->buffer == NULL) {
            // Handle out-of-memory condition
            for (size_t j = 0; j <= i; ++j) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            fprintf(stderr, "Failed to allocate memory for buffer in record %zu\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Initialize records with random values and buffers
    for (size_t i = 0; i < max_size; ++i) {
        (*records)[i]->value = rand() % 100;
        snprintf((*records)[i]->buffer, 256, "Record %zu", i);
    }
}

void free_memory(long* offsets, int* keys, record** records, size_t max_size) {
    for (size_t i = 0; i < max_size; ++i) {
        if (records[i] != NULL) {
            free(records[i]->buffer);
            free(records[i]);
        }
    }
    free(offsets);
    free(keys);
    free(records);
}
