        free(*offsets);
        // Handle allocation failure
        return;
    }

    *records = (Record*)aligned_alloc(64, max_records * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        // Handle allocation failure
        return;
