    srand(time(NULL));
    for (size_t i = 0; i < max_records; ++i) {
        (*records)[i].value = rand() % 1000; // Random value between 0 and 999
    }

    *list_head = NULL;
    for (size_t i = 0; i < initial_list_size; ++i) {
        LinkedListNode* new_node = (LinkedListNode*)aligned_alloc(64, sizeof(LinkedListNode));
        if (new_node == NULL) {
            // Handle allocation failure
            continue;
        }
        new_node->data.value = rand() % 1000; // Random value between 0 and 999
        new_node->next = *list_head;
        *list_head = new_node;
    }

    // Additional memory management and initialization code here
}

void free_memory(long* offsets, int* keys, Record* records, LinkedListNode* list_head) {
    free(offsets);
    free(keys);
    free(records);

    while (list_head != NULL) {
        LinkedListNode* temp = list_head;
        list_head = list_head->next;
        free(temp);
    }
