typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    // Add secondary index here
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    // Initialize secondary index here

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->records[i]->key);
        free(manager->records[i]);
    }

    free(manager->records);
    pthread_mutex_destroy(&manager->mutex);

    // Destroy secondary index here

    free(manager);
}

void resize_record_manager(RecordManager* manager, size_t new_capacity) {
    if (!manager || new_capacity <= manager->capacity) return;

    Record** new_records = (Record**)realloc(manager->records, new_capacity * sizeof(Record*));
    if (!new_records) return;

    manager->records = new_records;
    manager->capacity = new_capacity;
}

void add_record(RecordManager* manager, const char* key, int value) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity) {
        resize_record_manager(manager, manager->capacity * 2);
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    record->value = value;
    record->key = strdup(key);
    if (!record->key) {
        free(record);
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    manager->records[manager->size++] = record;

    // Add to secondary index here

    pthread_mutex_unlock(&manager->mutex);
}

Record* get_record(RecordManager* manager, const char* key) {
    pthread_mutex_lock(&manager->mutex);

    // Lookup in secondary index here

    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

void remove_record(RecordManager* manager, const char* key) {
    pthread_mutex_lock(&manager->mutex);

    // Remove from secondary index here

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->records[i]->key, key) == 0) {
            free(manager->records[i]->key);
            free(manager->records[i]);
            memmove(&manager->records[i], &manager->records[i + 1], (manager->size - i - 1) * sizeof(Record*));
            --manager->size;
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}
