typedef struct Node {
    long id;
    double* values;
    struct ChildNode* children;
    int child_count;
} Node;

typedef struct ChildNode {
    char buffer[256];
    int priority;
    struct ChildNode* next;
} ChildNode;

Node* create_node(int value_count, int max_children) {
    Node* node = (Node*)aligned_alloc(16, sizeof(Node));
    if (!node) return NULL;

    node->id = rand();
    node->values = (double*)aligned_alloc(32, value_count * sizeof(double));
    if (!node->values) {
        free(node);
        return NULL;
    }

    for (int i = 0; i < value_count; ++i) {
        node->values[i] = ((double)rand() / RAND_MAX) * 100.0 - 50.0;
    }

    node->children = (ChildNode*)aligned_alloc(64, max_children * sizeof(ChildNode));
    if (!node->children) {
        free(node->values);
        free(node);
        return NULL;
    }
    memset(node->children, 0, max_children * sizeof(ChildNode));

    node->child_count = 0;

    return node;
}

void destroy_node(Node* node) {
    for (int i = 0; i < node->child_count; ++i) {
        ChildNode* child = &node->children[i];
        free(child->buffer);
    }
    free(node->values);
    free(node->children);
    free(node);
}

void add_child(Node* parent, const char* buffer, int priority) {
    if (parent->child_count >= max_children) return;

    ChildNode* child = &parent->children[parent->child_count++];
    child->priority = priority;
    strncpy(child->buffer, buffer, sizeof(child->buffer));
}

// Additional functions for tree operations like insert, delete, search can be implemented here
