void log_message(const char* message) {
    time_t now = time(NULL);
    printf("[%s] %s\n", ctime(&now), message);
}

record* create_records(int size, int min_val, int max_val) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % (max_val - min_val + 1) + min_val;
    }
    return records;
}

void free_records(record* records, int size) {
    if (records) {
        free(records);
        log_message("Records memory freed");
    }
}

int find_largest(int* keys, int size) {
    if (size == 0) {
        log_message("No valid integers provided");
        return -1;
    }
    int largest = keys[0];
    for (int i = 1; i < size; ++i) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }
    return largest;
}

void process_input(int* keys, int key_size, record* records, int record_size) {
    int input;
    while (scanf("%d", &input) == 1) {
        if (input >= records[0].value && input <= records[record_size - 1].value) {
            for (int i = 0; i < key_size; ++i) {
                if (keys[i] == 0) {
                    keys[i] = input;
                    break;
                }
            }
        } else {
            log_message("Invalid input: integer out of range");
        }
    }
}

void print_largest(int* keys, int size) {
    int largest = find_largest(keys, size);
    if (largest != -1) {
        printf("Largest valid integer: %d\n", largest);
    }
}

int main(int argc, char* argv[]) {
    if (argc < 5) {
        fprintf(stderr, "Usage: %s <long_array_size> <int_array_size> <record_array_size> <min_val> <max_val>\n", argv[0]);
        return 1;
    }

    int long_array_size = atoi(argv[1]);
    int int_array_size = atoi(argv[2]);
    int record_array_size = atoi(argv[3]);
    int min_val = atoi(argv[4]);
    int max_val = atoi(argv[5]);

    if (min_val > max_val) {
        fprintf(stderr, "Error: Min value must be less than or equal to max value\n");
        return 1;
    }

    record* records = create_records(record_array_size, min_val, max_val);
    if (!records) {
        return 1;
    }

    int* keys = (int*)calloc(int_array_size, sizeof(int));
    if (!keys) {
        log_message("Memory allocation failed for keys");
        free_records(records, record_array_size);
        return 1;
    }

    process_input(keys, int_array_size, records, record_array_size);

    print_largest(keys, int_array_size);

    free(keys);
    free_records(records, record_array_size);

    return 0;
}
