#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000000

typedef struct {
    long offset;
    int key;
    struct record *data;
} Record;

typedef struct {
    int id;
    int parent;
} UnionFindNode;

typedef struct {
    UnionFindNode *nodes;
    int size;
} UnionFind;

void* memory_pool[MAX_RECORDS];
int pool_index = 0;

Record* allocate_record(long offset, int key) {
    if (pool_index >= MAX_RECORDS) {
        fprintf(stderr, "Memory pool exhausted\n");
        exit(1);
    }
    Record *record = (Record*)memory_pool[pool_index++];
    record->offset = offset;
    record->key = key;
    record->data = (struct record*)malloc(sizeof(struct record));
    if (!record->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return record;
}

void free_record(Record *record) {
    free(record->data);
    memory_pool[--pool_index] = record;
}

UnionFind* create_union_find(int size) {
    UnionFind *uf = (UnionFind*)malloc(sizeof(UnionFind));
    uf->nodes = (UnionFindNode*)malloc(size * sizeof(UnionFindNode));
    if (!uf || !uf->nodes) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < size; i++) {
        uf->nodes[i].id = i;
        uf->nodes[i].parent = i;
    }
    uf->size = size;
    return uf;
}

void destroy_union_find(UnionFind *uf) {
    free(uf->nodes);
    free(uf);
}

int find(UnionFind *uf, int id) {
    if (uf->nodes[id].parent != id) {
        uf->nodes[id].parent = find(uf, uf->nodes[id].parent);
    }
    return uf->nodes[id].parent;
}

void union_sets(UnionFind *uf, int id1, int id2) {
    int root1 = find(uf, id1);
    int root2 = find(uf, id2);
    if (root1 != root2) {
        uf->nodes[root2].parent = root1;
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments for sizes and ranges
    long offset_min, offset_max, key_min, key_max;
    // Allocate memory for arrays using a memory pool strategy
    Record **records = (Record**)malloc(MAX_RECORDS * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    int record_count = 0;

    // Read integers from standard input and store valid integers in the 'int' key array
    char line[256];
    while (fgets(line, sizeof(line), stdin)) {
        long offset;
        int key;
        if (sscanf(line, "%ld %d", &offset, &key) == 2 &&
            offset >= offset_min && offset <= offset_max &&
            key >= key_min && key <= key_max) {
            records[record_count++] = allocate_record(offset, key);
        }
    }

    // Create a custom hash table to manage group identifiers
    UnionFind *uf = create_union_find(record_count);

    // Implement a Union-Find data structure to efficiently identify disjoint pairs of keys
    for (int i = 0; i < record_count; i++) {
        for (int j = i + 1; j < record_count; j++) {
            if (records[i]->key != records[j]->key) {
                union_sets(uf, records[i]->key, records[j]->key);
            }
        }
    }

    // Free all allocated memory
    for (int i = 0; i < record_count; i++) {
        free_record(records[i]);
    }
    free(records);
    destroy_union_find(uf);

    return 0;
}
