#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000000

typedef struct {
    long offset;
    int key;
    struct record *data;
} Record;

typedef struct {
    int id;
    int parent;
} UnionFindNode;

typedef struct {
    UnionFindNode *nodes;
    int size;
} UnionFind;

void initializeUnionFind(UnionFind *uf, int size) {
    uf->nodes = (UnionFindNode *)malloc(size * sizeof(UnionFindNode));
    uf->size = size;
    for (int i = 0; i < size; i++) {
        uf->nodes[i].id = i;
        uf->nodes[i].parent = i;
    }
}

int find(UnionFind *uf, int id) {
    if (uf->nodes[id].parent != id) {
        uf->nodes[id].parent = find(uf, uf->nodes[id].parent);
    }
    return uf->nodes[id].parent;
}

void unionSets(UnionFind *uf, int id1, int id2) {
    int root1 = find(uf, id1);
    int root2 = find(uf, id2);
    if (root1 != root2) {
        uf->nodes[root2].parent = root1;
    }
}

void processRecords(int numRecords, Record *records, UnionFind *uf) {
    for (int i = 0; i < numRecords; i++) {
        int key = records[i].key;
        unionSets(uf, key, records[i].data->value);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <num_records> <offset_range> <key_range>\n", argv[0]);
        return 1;
    }

    int numRecords = atoi(argv[1]);
    long offsetRange = atol(argv[2]);
    int keyRange = atoi(argv[3]);

    if (numRecords > MAX_RECORDS || offsetRange <= 0 || keyRange <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return 1;
    }

    Record *records = (Record *)malloc(numRecords * sizeof(Record));
    UnionFind uf;

    initializeUnionFind(&uf, keyRange);

    clock_t start = clock();
    processRecords(numRecords, records, &uf);
    clock_t end = clock();

    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
    printf("Time taken: %f seconds\n", time_taken);

    free(records);
    free(uf.nodes);

    return 0;
}
