#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_REPORTS 1000
#define MAX_DATA_ENTRIES 50

typedef struct {
    long timestamp;
    int status_code;
    char* description;
} DataEntry;

typedef struct {
    DataEntry data[MAX_DATA_ENTRIES];
    int count;
} ReportData;

typedef struct Node {
    ReportData report_data;
    struct Node* next;
} ListNode;

typedef struct {
    ReportData reports[MAX_REPORTS];
    int count;
} ArrayStorage;

typedef struct {
    ListNode* head;
    int count;
} LinkedListStorage;

typedef struct {
    int category_id;
    union {
        ArrayStorage array_storage;
        LinkedListStorage linked_list_storage;
    } storage;
} CategoryStorage;

CategoryStorage* create_category_storage(int category_id, int max_size) {
    CategoryStorage* storage = (CategoryStorage*)malloc(sizeof(CategoryStorage));
    if (!storage) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    storage->category_id = category_id;
    switch (category_id) {
        case 1:
            // Initialize linked list storage
            storage->storage.linked_list_storage.head = NULL;
            storage->storage.linked_list_storage.count = 0;
            break;
        case 2:
            // Initialize array storage
            storage->storage.array_storage.count = 0;
            break;
        default:
            fprintf(stderr, "Unsupported category ID\n");
            free(storage);
            return NULL;
    }
    return storage;
}

void add_report(CategoryStorage* storage, ReportData report_data) {
    switch (storage->category_id) {
        case 1: {
            ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
            if (!new_node) {
                fprintf(stderr, "Memory allocation failed\n");
                return;
            }
            new_node->report_data = report_data;
            new_node->next = storage->storage.linked_list_storage.head;
            storage->storage.linked_list_storage.head = new_node;
            storage->storage.linked_list_storage.count++;
            break;
        }
        case 2:
            if (storage->storage.array_storage.count < MAX_REPORTS) {
                storage->storage.array_storage.reports[storage->storage.array_storage.count++] = report_data;
            } else {
                fprintf(stderr, "Category 2 storage limit reached\n");
            }
            break;
        default:
            fprintf(stderr, "Unsupported category ID\n");
            break;
    }
}

void free_category_storage(CategoryStorage* storage) {
    if (storage->category_id == 1) {
        ListNode* current = storage->storage.linked_list_storage.head;
        while (current) {
            ListNode* next = current->next;
            free(current);
            current = next;
        }
    }
    free(storage);
}

int main() {
    srand(time(NULL));
    CategoryStorage* category_1 = create_category_storage(1, 0);
    CategoryStorage* category_2 = create_category_storage(2, 50);

    for (int i = 0; i < 10; i++) {
        ReportData report_data;
        report_data.timestamp = time(NULL);
        report_data.status_code = rand() % 100 + 1;
        char description[100];
        snprintf(description, sizeof(description), "Status %d", report_data.status_code);
        report_data.description = strdup(description);

        add_report(category_1, report_data);
        add_report(category_2, report_data);
    }

    free_category_storage(category_1);
    free_category_storage(category_2);

    return 0;
}
