#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 10000
#define MAX_CONDITION_VARIABLES 10000

typedef struct {
    time_t timestamp;
    int status_flag;
    char metadata[256];
} Event;

typedef struct {
    pthread_mutex_t lock;
    Event events[MAX_EVENTS];
    int count;
} EventCollection;

typedef struct {
    pthread_cond_t condition_variables[MAX_CONDITION_VARIABLES];
    int count;
} ConditionVariableCollection;

EventCollection event_collection;
ConditionVariableCollection condition_variable_collection;

void init_collections() {
    pthread_mutex_init(&event_collection.lock, NULL);
    pthread_mutex_init(&condition_variable_collection.lock, NULL);
    event_collection.count = 0;
    condition_variable_collection.count = 0;
}

int add_event(time_t timestamp, int status_flag, const char* metadata) {
    pthread_mutex_lock(&event_collection.lock);
    if (event_collection.count >= MAX_EVENTS) {
        pthread_mutex_unlock(&event_collection.lock);
        return -1; // Error: Event collection is full
    }
    event_collection.events[event_collection.count].timestamp = timestamp;
    event_collection.events[event_collection.count].status_flag = status_flag;
    strncpy(event_collection.events[event_collection.count].metadata, metadata, sizeof(event_collection.events[event_collection.count].metadata) - 1);
    event_collection.count++;
    pthread_mutex_unlock(&event_collection.lock);
    return 0; // Success
}

int add_condition_variable() {
    pthread_mutex_lock(&condition_variable_collection.lock);
    if (condition_variable_collection.count >= MAX_CONDITION_VARIABLES) {
        pthread_mutex_unlock(&condition_variable_collection.lock);
        return -1; // Error: Condition variable collection is full
    }
    int index = condition_variable_collection.count;
    pthread_cond_init(&condition_variable_collection.condition_variables[index], NULL);
    condition_variable_collection.count++;
    pthread_mutex_unlock(&condition_variable_collection.lock);
    return index; // Success
}

void cleanup_events() {
    pthread_mutex_lock(&event_collection.lock);
    event_collection.count = 0;
    pthread_mutex_unlock(&event_collection.lock);
}

int main() {
    init_collections();

    time_t current_time = time(NULL);
    add_event(current_time, 1, "Event metadata");

    int condition_variable_index = add_condition_variable();
    if (condition_variable_index != -1) {
        pthread_cond_signal(&condition_variable_collection.condition_variables[condition_variable_index]);
    }

    cleanup_events();

    return 0;
}
```

This code provides a basic structure for managing dynamic collections of 'event' structures and condition variables in C. It includes functions to initialize the collections, add events and condition variables, and clean up unused events. The code uses mutexes for thread safety and initializes condition variables using pthread_cond_init. Note that this is a simplified example and does not include all the features and optimizations described in the task requirements.']

