#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define MAX_RECORDS 1000

typedef struct {
    int value;
    long offset;
    int key;
    double weight;
} record;

typedef struct {
    record *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dynamic_array;

void init_dynamic_array(dynamic_array *array) {
    array->capacity = INITIAL_CAPACITY;
    array->size = 0;
    array->data = (record *)malloc(array->capacity * sizeof(record));
    if (!array->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&array->lock, NULL);
}

void resize_dynamic_array(dynamic_array *array) {
    size_t new_capacity = array->capacity * 2;
    record *new_data = (record *)realloc(array->data, new_capacity * sizeof(record));
    if (!new_data) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->data = new_data;
    array->capacity = new_capacity;
}

void add_record(dynamic_array *array, int value, long offset, int key, double weight) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        resize_dynamic_array(array);
    }
    array->data[array->size].value = value;
    array->data[array->size].offset = offset;
    array->data[array->size].key = key;
    array->data[array->size].weight = weight;
    array->size++;
    pthread_mutex_unlock(&array->lock);
}

void cleanup_dynamic_array(dynamic_array *array) {
    pthread_mutex_lock(&array->lock);
    free(array->data);
    array->data = NULL;
    array->capacity = 0;
    array->size = 0;
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

int main() {
    dynamic_array my_array;
    init_dynamic_array(&my_array);

    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        add_record(&my_array, rand(), rand(), rand(), ((double)rand()) / RAND_MAX);
    }

    cleanup_dynamic_array(&my_array);
    return 0;
}
