public class ContentController : ControllerBase
{
    private readonly IContentService _contentService;
    private readonly ILogger<ContentController> _logger;
    private readonly ICacheService _cacheService;

    public ContentController(IContentService contentService, ILogger<ContentController> logger, ICacheService cacheService)
    {
        _contentService = contentService;
        _logger = logger;
        _cacheService = cacheService;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElementWithSecureContent([FromBody] UpdateRequest request)
    {
        if (!ModelState.IsValid)
            return BadRequest(ModelState);

        try
        {
            var result = await _contentService.UpdateElementAsync(request.SectionId, request.ElementId, request.HtmlContent);
            if (result.Success)
            {
                _logger.LogInformation("Update successful: {Timestamp}", DateTime.UtcNow);
                return Ok(new UpdateResponse { Success = true, Metadata = result.Metadata });
            }
            else
            {
                _logger.LogError("Update failed after retries: {Attempts}", result.Attempts);
                return StatusCode(500, new UpdateResponse { Success = false, Error = "Failed to update element" });
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred during the update process.");
            return StatusCode(500, new UpdateResponse { Success = false, Error = "Internal server error" });
        }
    }
}

public class UpdateRequest
{
    public string SectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
}

public class UpdateResponse
{
    public bool Success { get; set; }
    public string Error { get; set; }
    public object Metadata { get; set; }
}
