            log_error("Failed to allocate memory for record");
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand() % (max - min + 1) + min;
    }
}

void shutdown_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    if (output_file) {
        fclose(output_file);
    }
}

void *service_operation(void *arg) {
    int delay = rand() % 10 + 1; // Random delay between 1 and 10 seconds
    sleep(delay);
    pthread_mutex_lock(&lock);
    log_event("Service operation completed");
    pthread_mutex_unlock(&lock);
    return NULL;
}

void parse_command_line(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "cso:h")) != -1) {
        switch (opt) {
            case 'c':
                count_non_empty = 1;
                break;
            case 's':
                skip_comments = 1;
                break;
            case 'o':
                output_file = fopen(optarg, "w");
                if (!output_file) {
                    log_error("Failed to open output file");
                    exit(EXIT_FAILURE);
                }
                break;
            case 'h':
                printf("Usage: %s [-c] [-s] [-o output_file]\n", argv[0]);
                exit(EXIT_SUCCESS);
            default:
                fprintf(stderr, "Invalid option: %c\n", optopt);
                exit(EXIT_FAILURE);
        }
    }
}

int main(int argc, char *argv[]) {
    parse_command_line(argc, argv);

    initialize_records(min_value, max_value);

    FILE *input_file = fopen("input.txt", "r");
    if (!input_file) {
        log_error("Failed to open input file");
        exit(EXIT_FAILURE);
    }

    while (fgets(buffer, sizeof(buffer), input_file)) {
        record_count++;
        // Process each line based on command line options
    }

    fclose(input_file);

    pthread_t thread;
    pthread_create(&thread, NULL, service_operation, NULL);
    pthread_join(thread, NULL);

    shutdown_records();

    return 0;
}
