#define MAX_RETRIES 5

typedef struct {
    int value;
} record;

double generateRandomDouble(double min, double max) {
    return min + (rand() / (RAND_MAX / (max - min)));
}

int initializeData(long* offsets, int* keys, record** records, int size, int rangeMin, int rangeMax, double dataRangeMin, double dataRangeMax) {
    srand(time(NULL));

    for (int i = 0; i < MAX_RETRIES; ++i) {
        offsets = (long*)malloc(size * sizeof(long));
        keys = (int*)malloc(size * sizeof(int));
        records = (record**)malloc(size * sizeof(record*));

        if (!offsets || !keys || !records) {
            printf("Memory allocation failed. Retrying...\n");
            free(offsets);
            free(keys);
            free(records);
            continue;
        }

        for (int j = 0; j < size; ++j) {
            offsets[j] = rand();
            keys[j] = rand() % rangeMax + rangeMin;

            records[j] = (record*)malloc(sizeof(record));
            if (!records[j]) {
                printf("Memory allocation failed. Cleaning up and retrying...\n");
                for (int k = 0; k < j; ++k) {
                    free(records[k]);
                }
                free(offsets);
                free(keys);
                free(records);
                continue;
            }

            records[j]->value = rand() % rangeMax + rangeMin;

            double checksum = generateRandomDouble(dataRangeMin, dataRangeMax);
            // Simulate data transmission and corruption
            if (rand() % 2 == 0) {
                checksum += 1.0; // Introduce corruption
            }
            records[j]->value = (int)(checksum * 100); // Store as integer for simplicity
        }

        printf("Initialization successful.\n");
        return 0;
    }

    printf("Memory allocation failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

void cleanup(long* offsets, int* keys, record** records, int size) {
    for (int i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    printf("Cleanup successful.\n");
}

int main() {
    long* offsets;
    int* keys;
    record** records;
    int size = 1000;
    int rangeMin = 0, rangeMax = 100;
    double dataRangeMin = 0.0, dataRangeMax = 1.0;

    if (initializeData(offsets, keys, records, size, rangeMin, rangeMax, dataRangeMin, dataRangeMax) == 0) {
        // Use the initialized data here
        cleanup(offsets, keys, records, size);
    }

    return 0;
}
