import threading
import time
import json
from queue import Queue

class TaskManager:
    def __init__(self, config):
        self.config = config
        self.logger = None
        self.task_queue = Queue()
        self.lock = threading.Lock()

    def initialize_service(self):
        with self.lock:
            if not self.logger:
                self.logger = Logger(self.config['log_file'])
            # Initialize other resources here

    def execute_tasks(self, label, f, config=None):
        task_config = config or {}
        retries = task_config.get('retries', 2)
        retry_delay = task_config.get('retry_delay', 1)
        max_load = self.config.get('max_load', float('inf'))

        while True:
            if threading.active_count() > max_load:
                time.sleep(0.1)  # Adjust sleep duration based on load
                continue

            try:
                result = f()
                print(f"Task {label} completed successfully")
                self.logger.log(label, 'success', result)
                break
            except Exception as e:
                retries -= 1
                if retries > 0:
                    time.sleep(retry_delay)
                else:
                    print(f"Task {label} failed after {retries + 1} attempts")
                    self.logger.log(label, 'failure', str(e))
                    break

    def send_results(self):
        while True:
            results = []
            while not self.task_queue.empty():
                label, result = self.task_queue.get()
                results.append({'task': label, 'result': result})
                self.task_queue.task_done()

            if results:
                json_data = json.dumps(results)
                # Send JSON data to monitoring service
                print(f"Sending results: {json_data}")

            time.sleep(self.config['update_interval'])

class Logger:
    def __init__(self, file_name):
        self.file_name = file_name

    def log(self, task, status, message):
        with open(self.file_name, 'a') as file:
            timestamp = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())
            file.write(f"{timestamp} - {task} - {status} - {message}\n")

# Example usage
def example_task():
    # Simulate a task that might fail
    if random.choice([True, False]):
        raise Exception("Task failed")
    return "Task completed"

config = {
    'log_file': 'service.log',
    'max_load': 5,
    'update_interval': 10
}

task_manager = TaskManager(config)
task_manager.initialize_service()
threading.Thread(target=task_manager.send_results).start()

for i in range(10):
    threading.Thread(target=task_manager.execute_tasks, args=('Task' + str(i), example_task)).start()
