#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    long offset;
    int key;
    float value;
    char buffer[20];
} Record;

Record* create_record_collection(int *size) {
    Record *collection = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (!collection) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    *size = MAX_RECORDS;
    return collection;
}

void initialize_records(Record *collection, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        collection[i].offset = i * sizeof(Record);
        collection[i].key = rand() % 1000;
        collection[i].value = (float)(rand() % 100) / 10.0f;
        snprintf(collection[i].buffer, sizeof(collection[i].buffer), "%.2f", collection[i].value);
    }
}

void serialize_records(Record *collection, int size, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fwrite(collection, sizeof(Record), size, file);
    fclose(file);
}

void deserialize_records(Record **collection, int *size, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }
    fseek(file, 0, SEEK_END);
    long size_in_bytes = ftell(file);
    fclose(file);

    *size = size_in_bytes / sizeof(Record);
    *collection = (Record*)realloc(*collection, (*size) * sizeof(Record));
    if (!*collection) {
        fprintf(stderr, "Memory reallocation failed\n");
        return;
    }

    FILE *file2 = fopen(filename, "rb");
    fread(*collection, sizeof(Record), *size, file2);
    fclose(file2);
}

void free_record_collection(Record *collection) {
    free(collection);
}
