#define MAX_RECORDS 1000

typedef struct {
    char identifier;
    long offset;
    int key;
    float value;
    double timestamp;
} record;

double generate_timestamp(double min, double max) {
    return min + (rand() / (RAND_MAX / (max - min)));
}

void populate_record(record *rec, char id, long off, int k, float v, double ts) {
    rec->identifier = id;
    rec->offset = off;
    rec->key = k;
    rec->value = v;
    rec->timestamp = ts;
}

int main() {
    srand(time(NULL));

    record *records = (record *)malloc(MAX_RECORDS * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    float values[MAX_RECORDS];

    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = rand() % 1000000L;
        keys[i] = rand() % 1000;
        values[i] = (float)(rand() / (RAND_MAX / 100.0));

        double ts = generate_timestamp(1633072800, 1645168800); // Example timestamp range
        populate_record(&records[i], 'A' + i % 26, offsets[i], keys[i], values[i], ts);
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        printf("Record %d: Identifier=%c, Offset=%ld, Key=%d, Value=%.2f, Timestamp=%.2f\n",
               i, records[i].identifier, records[i].offset, records[i].key,
               records[i].value, records[i].timestamp);
    }

    free(records);

    return 0;
