void initialize_and_cleanup(int num_records, long* offsets, int* keys, record** records) {
    // Allocate memory for arrays and records
    offsets = (long*)malloc(num_records * sizeof(long));
    keys = (int*)malloc(num_records * sizeof(int));
    *records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !*records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(*records);
        return;
    }

    // Initialize arrays and records
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i * 100L;
        keys[i] = rand() % 1000;
        (*records)[i].value = rand() % 10000;
    }

    // Log initialization
    printf("Initialization complete\n");

    // Cleanup
    free(offsets);
    free(keys);
    free(*records);

    printf("Cleanup complete\n");
}

int main() {
    int num_records = 1000;
    long* offsets;
    int* keys;
    record* records;

    initialize_and_cleanup(num_records, offsets, keys, &records);

    return 0;
}
