import time
import requests
from retrying import retry
from sqlalchemy import create_engine, Column, Integer, String, Float, DateTime
from sqlalchemy.ext.declarative import declarative_base
from sqlalchemy.orm import sessionmaker

Base = declarative_base()

class SensorData(Base):
    __tablename__ = 'sensor_data'
    id = Column(Integer, primary_key=True)
    timestamp = Column(DateTime, index=True)
    value = Column(Float)

def create_db_engine():
    return create_engine('sqlite:///sensor_data.db', echo=False)

def get_session(engine):
    Session = sessionmaker(bind=engine)
    return Session()

@retry(stop_max_attempt_number=5, wait_fixed=2000)
def fetch_sensor_data(sensor_url):
    response = requests.get(sensor_url)
    response.raise_for_status()
    return response.json()

def process_and_store_data(sensor_url, db_engine):
    session = get_session(db_engine)
    try:
        data = fetch_sensor_data(sensor_url)
        for entry in data:
            sensor_entry = SensorData(timestamp=entry['timestamp'], value=entry['value'])
            session.add(sensor_entry)
        session.commit()
    except requests.exceptions.RequestException as e:
        print(f"Error fetching data: {e}")
        session.rollback()
    finally:
        session.close()

def health_check(db_engine):
    try:
        engine = create_db_engine()
        connection = engine.connect()
        result = connection.execute("SELECT 1")
        if result.scalar() == 1:
            return "Healthy"
        else:
            return "Unhealthy"
    except Exception as e:
        print(f"Health check failed: {e}")
        return "Unhealthy"

def main():
    sensor_url = 'http://example.com/sensor_data'
    db_engine = create_db_engine()

    while True:
        process_and_store_data(sensor_url, db_engine)
        time.sleep(10)  # Adjust the interval based on your requirements

if __name__ == "__main__":
    main()
```

This code provides a basic structure for processing real-time sensor data streams and aggregating them into a time-series database. It includes error handling, retry mechanisms, and a health check endpoint. The `process_and_store_data` function fetches data from a sensor URL, processes it, and stores it in a SQLite database. The `health_check` function provides a simple way to monitor the operational status of the system.']

