#define DEFAULT_RECORD_COUNT 1000
#define MIN_INT_VALUE -1000
#define MAX_INT_VALUE 1000
#define MIN_LONG_VALUE -1000000L
#define MAX_LONG_VALUE 1000000L
#define MIN_DOUBLE_VALUE -1.0
#define MAX_DOUBLE_VALUE 1.0

typedef struct {
    int i;
    long l;
    double d;
} record;

void* initialize_records(void* arg) {
    int count = *(int*)arg;
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < count; i++) {
        records[i].i = rand() % (MAX_INT_VALUE - MIN_INT_VALUE + 1) + MIN_INT_VALUE;
        records[i].l = rand() % (MAX_LONG_VALUE - MIN_LONG_VALUE + 1) + MIN_LONG_VALUE;
        records[i].d = ((double)rand() / RAND_MAX) * (MAX_DOUBLE_VALUE - MIN_DOUBLE_VALUE) + MIN_DOUBLE_VALUE;
    }

    pthread_exit(records);
}

void cleanup_records(void* arg) {
    record* records = (record*)arg;
    free(records);
}

int main(int argc, char* argv[]) {
    int count = DEFAULT_RECORD_COUNT;

    if (argc > 1) {
        count = atoi(argv[1]);
    }

    pthread_t thread;
    void* result;

    if (pthread_create(&thread, NULL, initialize_records, &count) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, &result) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    record* records = (record*)result;

    // Use the records...

    cleanup_records(records);

    return EXIT_SUCCESS;
}
