function refreshRecordFields(resourceId, url, fieldNames) {
    var records = [];
    // Initialize records array with initial state

    function fetchFieldData(field) {
        return $http.get(url + '/' + resourceId + '/' + field)
            .then(function(response) {
                return response.data;
            })
            .catch(function(error) {
                console.error('Failed to fetch data for field:', field, error);
                throw error;
            });
    }

    function updateRecordField(record, field, data) {
        record[field] = data;
    }

    function validateRecord(record) {
        // Validate record integrity
        if (record.offset < 0 || record.key < 0 || !record.isValid) {
            console.warn('Invalid record found:', record);
            return false;
        }
        return true;
    }

    function resetRecords() {
        records = [];
        // Reset records array to initial state
    }

    function logStatus(message) {
        console.log(message);
    }

    function handleMemoryError(error) {
        console.error('Memory allocation failed:', error);
        process.exit(1);
    }

    function retryWithExponentialBackoff(attempt, maxAttempts, delay) {
        if (attempt >= maxAttempts) {
            throw new Error('Max attempts reached');
        }
        return $timeout(function() {
            return fetchFieldData(fieldNames[attempt]);
        }, delay * Math.pow(2, attempt));
    }

    function processRecords() {
        var promises = fieldNames.map(fetchFieldData);
        $q.all(promises)
            .then(function(data) {
                records.forEach(function(record, index) {
                    updateRecordField(record, fieldNames[index], data[index]);
                });
                records.forEach(validateRecord);
                logStatus('Records updated successfully');
            })
            .catch(function(error) {
                console.error('Error processing records:', error);
            });
    }

    try {
        processRecords();
    } catch (error) {
        handleMemoryError(error);
    }
}
