#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
    double measurement;
} data_record;

typedef struct {
    data_record* records;
    size_t capacity;
    size_t size;
    size_t max_size;
} dynamic_collection;

void log_event(const char* event, int key) {
    // Implement logging mechanism here
    printf("%s: Key = %d\n", event, key);
}

int add_record(dynamic_collection* collection, int key, long offset, double measurement) {
    if (collection->size >= collection->max_size) {
        log_event("Error", key);
        return -1; // Error: Collection is full
    }

    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity ? collection->capacity * 2 : 1;
        data_record* new_records = realloc(collection->records, new_capacity * sizeof(data_record));
        if (!new_records) {
            log_event("Memory allocation failed", key);
            return -1; // Error: Memory allocation failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->size].key = key;
    collection->records[collection->size].offset = offset;
    collection->records[collection->size].measurement = measurement;
    collection->size++;
    log_event("Added", key);
    return 0; // Success
}

int remove_record(dynamic_collection* collection, int key) {
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            memmove(&collection->records[i], &collection->records[i + 1], (collection->size - i - 1) * sizeof(data_record));
            collection->size--;
            log_event("Removed", key);
            return 0; // Success
        }
    }
    log_event("Error", key);
    return -1; // Error: Key not found
}

data_record* get_record(dynamic_collection* collection, int key) {
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            return &collection->records[i];
        }
    }
    log_event("Error", key);
    return NULL; // Error: Key not found
}

void init_collection(dynamic_collection* collection, size_t initial_capacity, size_t max_size) {
    collection->records = malloc(initial_capacity * sizeof(data_record));
    if (!collection->records) {
        log_event("Memory allocation failed", 0);
        exit(EXIT_FAILURE); // Exit on memory allocation failure
    }
    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->max_size = max_size;
}

void free_collection(dynamic_collection* collection) {
    free(collection->records);
}
