#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2

typedef struct {
    int key;
    long offset;
    double measurement;
    char* data_ptr;
} data_record;

typedef struct {
    data_record* records;
    size_t capacity;
    size_t size;
    void (*free_data)(void*);
} data_pool;

data_pool* create_data_pool(void (*free_data_func)(void*)) {
    data_pool* pool = (data_pool*)malloc(sizeof(data_pool));
    if (!pool) {
        perror("Failed to allocate memory for data pool");
        return NULL;
    }
    pool->records = (data_record*)calloc(INITIAL_CAPACITY, sizeof(data_record));
    if (!pool->records) {
        perror("Failed to allocate memory for records");
        free(pool);
        return NULL;
    }
    pool->capacity = INITIAL_CAPACITY;
    pool->size = 0;
    pool->free_data = free_data_func;
    return pool;
}

void destroy_data_pool(data_pool* pool) {
    if (!pool) return;

    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->records[i].data_ptr) {
            pool->free_data(pool->records[i].data_ptr);
        }
    }

    free(pool->records);
    free(pool);
}

void resize_data_pool(data_pool* pool, size_t new_capacity) {
    data_record* new_records = (data_record*)realloc(pool->records, new_capacity * sizeof(data_record));
    if (!new_records) {
        perror("Failed to reallocate memory for records");
        return;
    }
    pool->records = new_records;
    pool->capacity = new_capacity;
}

int add_data_record(data_pool* pool, int key, long offset, double measurement, void* data_ptr) {
    if (pool->size >= pool->capacity) {
        resize_data_pool(pool, pool->capacity * GROWTH_FACTOR);
    }

    pool->records[pool->size].key = key;
    pool->records[pool->size].offset = offset;
    pool->records[pool->size].measurement = measurement;
    pool->records[pool->size].data_ptr = data_ptr;

    ++pool->size;
    return 0;
}

void* get_data_record(data_pool* pool, int key) {
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->records[i].key == key) {
            return pool->records[i].data_ptr;
        }
    }
    return NULL;
}

void reclaim_unused_data(data_pool* pool, void (*is_used)(void*, int)) {
    for (size_t i = 0; i < pool->size; ++i) {
        if (!is_used(pool->records[i].data_ptr, pool->records[i].key)) {
            pool->free_data(pool->records[i].data_ptr);
            pool->records[i].data_ptr = NULL;
        }
    }
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}
