            *result = collection->records[i];
            log_event("Record retrieved");
            return 0;
        }
    }
    log_event("Record not found");
    return -1;
}

int resolve_dns(const char *hostname, u_char *ip_address, int timeout) {
    struct timeval start_time, current_time;
    gettimeofday(&start_time, NULL);
    while (1) {
        struct hostent *host = gethostbyname(hostname);
        if (host) {
            memcpy(ip_address, host->h_addr_list[0], sizeof(u_char) * 4);
            log_event("DNS resolution successful");
            return 0;
        }
        gettimeofday(&current_time, NULL);
        if ((current_time.tv_sec - start_time.tv_sec) > timeout) {
            log_event("DNS resolution timed out");
            return -1;
        }
        sleep(RETRY_DELAY);
    }
}

void free_collection(dynamic_collection *collection) {
    free(collection->records);
}
