typedef struct {
    char identifier;
    long offset;
    int key;
    float value;
    double timestamp;
} record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* create_records(int size) {
    record* records = (record*)safe_malloc(size * sizeof(record));
    for (int i = 0; i < size; i++) {
        records[i].identifier = 'A' + rand() % 26;
        records[i].offset = rand();
        records[i].key = rand() % 1000;
        records[i].value = (float)rand() / RAND_MAX * 100.0f;
        records[i].timestamp = time(NULL);
    }
    return records;
}

void print_largest_key(int* keys, int size) {
    if (size == 0) {
        printf("No valid integers provided\n");
        return;
    }
    int max_key = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > max_key) {
            max_key = keys[i];
        }
    }
    printf("Largest key: %d\n", max_key);
}

void free_records(record* records, int size) {
    free(records);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int size = atoi(argv[1]);
    if (size <= 0) {
        fprintf(stderr, "Invalid size\n");
        return EXIT_FAILURE;
    }

    record* records = create_records(size);
    print_largest_key(records, size);

    free_records(records, size);

    return EXIT_SUCCESS;
}
