        records[i].filename[MAX_FILENAME_LENGTH - 1] = '\0';
    }

    return records;
}

void free_records(Record *records, int count) {
    if (records) {
        free(records);
        log_message("Records memory freed");
    }
}

int find_max_value(const Record *records, int count) {
    int max_value = records[0].value;
    for (int i = 1; i < count; ++i) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }
    return max_value;
}

const char* find_longest_filename(const Record *records, int count) {
    const char *longest_filename = records[0].filename;
    for (int i = 1; i < count; ++i) {
        if (strlen(records[i].filename) > strlen(longest_filename)) {
            longest_filename = records[i].filename;
        }
    }
    return longest_filename;
}

