    if (!records) {
        return;
    }

    int max_value = find_max_value(records, count);
    const char *longest_filename = find_longest_filename(records, count);

    log_message("Maximum value: %d", max_value);
    log_message("Longest filename: %s", longest_filename);

    free_records(records, count);
}

int main() {
    process_input();
    return 0;
