    for (int i = 0; i < size; i++) {
        (*records)[i].key = keys[i];
        (*records)[i].offset = rand() % 1000L; // Random offset
        (*records)[i].value = (double)rand() / RAND_MAX * 100.0; // Random double value
    }
}

int findMaxKey(int *keys, int size) {
    int max = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > max) {
            max = keys[i];
        }
    }
    return max;
}

double calculateAverage(int *keys, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += keys[i];
    }
    return sum / size;
}

void freeRecords(Record **records, int size) {
    free(*records);
    *records = NULL;
}

int main() {
    int size;
    printf("Enter the number of records: ");
    scanf("%d", &size);

    int *keys = (int *)malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        return 1;
    }

    Record *records = NULL;

    // Populate keys array with integers from standard input
    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &keys[i]);
    }

    records = (Record *)malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(keys);
        return 1;
    }

    populateRecords(&records, keys, size);

    int maxKey = findMaxKey(keys, size);
    double average = calculateAverage(keys, size);

    printf("Largest key: %d\n", maxKey);
