#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ENTRIES 1000

typedef struct record {
    int value;
    char filename[256];
} Record;

typedef struct node {
    long offset;
    int key;
    Record *record;
    struct node *next;
} Node;

typedef struct entry {
    double value;
    Node *head;
} Entry;

Entry* initialize_entries(int size) {
    if (size <= 0 || size > MAX_ENTRIES) {
        fprintf(stderr, "Invalid array size\n");
        return NULL;
    }

    Entry *entries = malloc(size * sizeof(Entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        entries[i].value = 0.0;
        entries[i].head = NULL;
    }

    return entries;
}

void free_entries(Entry *entries, int size) {
    if (!entries) {
        return;
    }

    for (int i = 0; i < size; i++) {
        Node *current = entries[i].head;
        while (current) {
            Node *next = current->next;
            free(current->record);
            free(current);
            current = next;
        }
    }

    free(entries);
}

void populate_entries(Entry *entries, int size) {
    for (int i = 0; i < size; i++) {
        entries[i].value = rand() / (double)RAND_MAX * 100.0; // Random value between 0 and 100
        Node *current = NULL;
        for (int j = 0; j < 5; j++) { // Example: Each entry has 5 nodes
            Node *new_node = malloc(sizeof(Node));
            if (!new_node) {
                fprintf(stderr, "Memory allocation failed\n");
                return;
            }
            new_node->offset = rand() % 1000L; // Random offset
            new_node->key = rand() % 100; // Random key
            new_node->record = malloc(sizeof(Record));
            if (!new_node->record) {
                fprintf(stderr, "Memory allocation failed\n");
                return;
            }
            new_node->record->value = rand() % 100; // Random record value
            strcpy(new_node->record->filename, "file"); // Example filename
            new_node->next = NULL;

            if (!entries[i].head) {
                entries[i].head = new_node;
            } else {
                current->next = new_node;
            }
            current = new_node;
        }
    }
}

void read_input(Entry *entries, int size) {
    for (int i = 0; i < size; i++) {
        scanf("%lf", &entries[i].value);
        Node *current = entries[i].head;
        while (current) {
            scanf("%ld %d %s", &current->offset, &current->key, current->record->filename);
            current = current->next;
        }
    }
}

int find_largest_integer(Entry *entries, int size) {
    int max_value = INT_MIN;
    for (int i = 0; i < size; i++) {
        Node *current = entries[i].head;
        while (current) {
            if (current->record->value > max_value) {
                max_value = current->record->value;
            }
            current = current->next;
        }
    }
    return max_value;
}

void print_longest_filename(Entry *entries, int size) {
    int max_length = 0;
    char longest_filename[256];
    for (int i = 0; i < size; i++) {
        Node *current = entries[i].head;
        while (current) {
            if (strlen(current->record->filename) > max_length) {
                max_length = strlen(current->record->filename);
                strcpy(longest_filename, current->record->filename);
            }
            current = current->next;
        }
    }
    printf("Longest filename: %s\n", longest_filename);
}

int main() {
    int size;
    scanf("%d", &size);

    Entry *entries = initialize_entries(size);
    if (!entries) {
        return 1;
    }

    populate_entries(entries, size);
    read_input(entries, size);

    printf("Largest integer: %d\n", find_largest_integer(entries, size));
    print_longest_filename(entries, size);

    free_entries(entries, size);

    return 0;
}
