#define MAX_SHAPES 100

typedef struct {
    char type[20];
    float properties;
    float area;
} Shape;

typedef struct {
    float x, y;
} Point;

void log_message(const char *message) {
    printf("LOG: %s\n", message);
}

float calculate_area(Shape shape) {
    if (strcmp(shape.type, "circle") == 0) {
        return M_PI * shape.properties * shape.properties;
    } else if (strcmp(shape.type, "triangle") == 0) {
        // Assuming equilateral triangle for simplicity
        return sqrt(3) / 4 * shape.properties * shape.properties;
    } else if (strcmp(shape.type, "square") == 0) {
        return shape.properties * shape.properties;
    }
    return -1; // Error case
}

void read_shapes(Shape shapes[], int *count) {
    char line[256];
    while (fgets(line, sizeof(line), stdin)) {
        if (*count >= MAX_SHAPES) break;
        Shape shape;
        sscanf(line, "%[^,],%f,%f", shape.type, &shape.properties, &shapes[*count].area);
        shapes[*count] = shape;
        (*count)++;
    }
}

void initialize_shapes(Shape shapes[], int count) {
    for (int i = 0; i < count; i++) {
        shapes[i].area = calculate_area(shapes[i]);
    }
}

void cleanup_shapes(Shape shapes[], int count) {
    // No need to free memory as it's static
}

int main() {
    Shape shapes[MAX_SHAPES];
    int count = 0;

    log_message("Reading shapes from standard input...");
    read_shapes(shapes, &count);

    log_message("Initializing shapes...");
    initialize_shapes(shapes, count);

    log_message("Printing areas of shapes:");
    for (int i = 0; i < count; i++) {
        printf("%s area: %.2f\n", shapes[i].type, shapes[i].area);
    }

    log_message("Cleaning up...");
    cleanup_shapes(shapes, count);

    return 0;
}
