#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

typedef enum { INT, LONG, FLOAT, DOUBLE, CHAR_PTR } DataType;

typedef struct {
    int key;
    union {
        long l_val;
        float f_val;
        double d_val;
        char* str_ptr;
    };
    DataType type;
} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        Record* record = collection->records[i];
        if (record->type == CHAR_PTR && record->str_ptr) free(record->str_ptr);
        free(record);
    }

    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(RecordCollection* collection, int key, void* value, DataType type) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failed
    }

    record->key = key;
    record->type = type;
    switch (type) {
        case INT:
            record->l_val = *(long*)value;
            break;
        case LONG:
            record->l_val = *(long*)value;
            break;
        case FLOAT:
            record->f_val = *(float*)value;
            break;
        case DOUBLE:
            record->d_val = *(double*)value;
            break;
        case CHAR_PTR:
            record->str_ptr = strdup((char*)value);
            if (!record->str_ptr) {
                free(record);
                pthread_mutex_unlock(&collection->lock);
                return -1; // Memory allocation failed
            }
            break;
    }

    collection->records[collection->size++] = record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

// Additional functions for serialization, error handling, and other features would be implemented here.
