using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;

public struct ImageInfo
{
    public int Width { get; set; }
    public int Height { get; set; }
    public string ColorType { get; set; }
    public bool HasTransparency { get; set; }
}

public class ImageProcessor
{
    public (ImageInfo, byte[]) ProcessImageAsset(string imagePath, int maxWidth, int maxHeight)
    {
        try
        {
            using (var image = Image.FromFile(imagePath))
            {
                var originalWidth = image.Width;
                var originalHeight = image.Height;

                // Calculate new dimensions while maintaining aspect ratio
                var widthRatio = (double)maxWidth / originalWidth;
                var heightRatio = (double)maxHeight / originalHeight;
                var scaleRatio = Math.Min(widthRatio, heightRatio);
                var newWidth = (int)(originalWidth * scaleRatio);
                var newHeight = (int)(originalHeight * scaleRatio);

                // Determine color type and transparency
                var colorType = image.PixelFormat.ToString();
                var hasTransparency = image.PixelFormat.HasFlag(PixelFormat.Format32bppArgb) || image.PixelFormat.HasFlag(PixelFormat.Format64bppArgb);

                // Resize the image
                using (var resizedImage = new Bitmap(newWidth, newHeight))
                {
                    using (var graphics = Graphics.FromImage(resizedImage))
                    {
                        graphics.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;
                        graphics.DrawImage(image, 0, 0, newWidth, newHeight);
                    }

                    // Convert to byte array
                    var imageBytes = resizedImage.ToByteArray();

                    // Ensure the image does not exceed 1MB in size
                    if (imageBytes.Length > 1 * 1024 * 1024)
                    {
                        throw new Exception("Resized image exceeds 1MB limit.");
                    }

                    return (new ImageInfo { Width = newWidth, Height = newHeight, ColorType = colorType, HasTransparency = hasTransparency }, imageBytes);
                }
            }
        }
        catch (Exception ex)
        {
            // Handle potential errors gracefully
            Console.WriteLine($"Error processing image: {ex.Message}");
            throw;
        }
    }

    private byte[] ToByteArray(this Image image)
    {
        using (var ms = new MemoryStream())
        {
            image.Save(ms, image.RawFormat);
            return ms.ToArray();
        }
    }
}
