char* generateRandomString(int length) {
    static char buffer[1024];
    const size_t charset_length = strlen(CHAR_SET);
    for (int i = 0; i < length; ++i) {
        buffer[i] = CHAR_SET[rand() % charset_length];
    }
    buffer[length] = '\0';
    return buffer;
}

unsigned long hashPassword(const char *password) {
    unsigned long hash = 5381;
    int c;
    while ((c = *password++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % HASH_SIZE;
}

Record* createRecords(int numRecords, int keyRangeMin, int keyRangeMax, long offsetRangeMin, long offsetRangeMax) {
    if (numRecords > MAX_RECORDS || numRecords <= 0) {
        fprintf(stderr, "Invalid number of records.\n");
        return NULL;
    }

    Record *records = malloc(numRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < numRecords; ++i) {
        records[i].key = rand() % (keyRangeMax - keyRangeMin + 1) + keyRangeMin;
        records[i].offset = malloc(sizeof(long));
        if (!records[i].offset) {
            fprintf(stderr, "Memory allocation failed for offset at record %d.\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j].offset);
            }
            free(records);
            return NULL;
        }
        *records[i].offset = rand() % (offsetRangeMax - offsetRangeMin + 1) + offsetRangeMin;
    }

    return records;
}

void freeRecords(Record *records, int numRecords) {
    for (int i = 0; i < numRecords; ++i) {
        free(records[i].offset);
    }
    free(records);
}

int main() {
