    printf("Enter the number of records: ");
    scanf("%d", &numRecords);

    Record *records = createRecords(numRecords, MIN_KEY, MAX_KEY, MIN_OFFSET, MAX_OFFSET);
    if (records) {
        // Use the records here
        freeRecords(records, numRecords);
    }

    return 0;
}
