#define MAX_RECORDS 10000

typedef struct {
    int key;
    long *offset;
} record;

void* allocate_and_initialize_arrays(void* arg) {
    int size = *(int*)arg;
    if (size <= 0 || size > MAX_RECORDS) {
        fprintf(stderr, "Invalid array size\n");
        return NULL;
    }

    long *offsets = malloc(size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    int *keys = malloc(size * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        return NULL;
    }

    record *records = malloc(size * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(keys);
        free(offsets);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 1000; // Random int value between 0 and 999
        records[i].key = keys[i];
        records[i].offset = &offsets[i];
    }

    // Simulate concurrent access by multiple threads
    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);
    for (int i = 0; i < size; i++) {
        pthread_mutex_lock(&mutex);
        // Perform operations on records
        pthread_mutex_unlock(&mutex);
    }
    pthread_mutex_destroy(&mutex);

    free(records);
    free(keys);
    free(offsets);

    return NULL;
}

void modify_filename_extension(const char *filename, const char *extension) {
    if (!filename || !*filename || !extension || !*extension) {
        fprintf(stderr, "Invalid filename or extension\n");
        return;
    }

    size_t len = strlen(filename);
    char new_filename[len + 10]; // Assuming max extension length is 9
    strcpy(new_filename, filename);

    char *dot_pos = strrchr(new_filename, '.');
    if (dot_pos) {
        *dot_pos = '\0';
    }

    strcat(new_filename, "_");
    for (int i = 0; i < strlen(extension); i++) {
        new_filename[strlen(new_filename)] = extension[i];
    }
    strcat(new_filename, ".txt");

    // Handle file name collisions and perform file system operations
    FILE *file = fopen(new_filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fclose(file);
}

void log_message(const char *message, int level) {
    // Implement logging mechanism here
    printf("[%d] %s\n", level, message);
}

int main() {
    int size = 5000; // Example array size
    pthread_t thread;
    if (pthread_create(&thread, NULL, allocate_and_initialize_arrays, &size) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    pthread_join(thread, NULL);

    const char *filename = "example.txt";
    const char *extension = "123456789"; // Example extension
    modify_filename_extension(filename, extension);

    log_message("Function execution completed", 0);

    return 0;
}
