typedef struct {
    char* str;
    unsigned int flag;
    double value;
} Record;

Record* create_records(int count, int min_flag, int max_flag, double start_value) {
    if (count <= 0 || min_flag >= max_flag) {
        return NULL;
    }

    Record* records = malloc(count * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < count; ++i) {
        // Generate unique alphanumeric string
        char temp[16];
        sprintf(temp, "%c%d", 'A' + rand() % 26, i);
        records[i].str = strdup(temp);

        // Initialize flag with random value within the specified range
        records[i].flag = min_flag + rand() % (max_flag - min_flag + 1);

        // Assign unique double value based on a starting reference point
        records[i].value = start_value + i * 0.1;
    }

    return records;
}

void free_records(Record* records, int count) {
    if (!records) {
        return;
    }

    for (int i = 0; i < count; ++i) {
        free(records[i].str);
    }

    free(records);
}

int main() {
    int count = 10;
    int min_flag = 1;
    int max_flag = 100;
    double start_value = 0.0;

    Record* records = create_records(count, min_flag, max_flag, start_value);
    if (records) {
        for (int i = 0; i < count; ++i) {
            printf("Record %d: str=%s, flag=%u, value=%.2f\n", i, records[i].str, records[i].flag, records[i].value);
        }
        free_records(records, count);
    }

    return 0;
}
