}

Record* initialize_records(int num_records, int min_val, int max_val, size_t record_size) {
    if (num_records <= 0 || min_val > max_val || record_size < sizeof(Record)) {
        log_memory_event("Invalid input parameters");
        return NULL;
    }

    Record* records = safe_malloc(num_records * record_size);
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; i++) {
