                snprintf(records[i].value.s, 10, "%d", rand() % (max_val - min_val + 1) + min_val);
                break;
        }
        pthread_mutex_unlock(&mutex);
    }

    return records;
}

void free_records(Record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].type == 3) {
            safe_free(records[i].value.s);
        }
    }
    safe_free(records);
}
