#include <time.h>

void executeTaskWithConstraints(const char* command, int timeout) {
    if (timeout <= 0) {
        std::cerr << "Invalid timeout value" << std::endl;
        return;
    }

    pid_t pid = fork();
    if (pid == -1) {
        std::cerr << "Failed to fork process" << std::endl;
        return;
    } else if (pid == 0) {
        // Child process
        alarm(timeout);
        execlp(command, command, nullptr);
        _exit(EXIT_FAILURE); // In case of failure
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFSIGNALED(status) && WTERMSIG(status) == SIGALRM) {
            std::cerr << "Command execution exceeded timeout" << std::endl;
        }
    }

    static time_t lastTaskTime = 0;
    time_t currentTime = time(nullptr);

    if (currentTime - lastTaskTime >= 9) {
        srand(time(nullptr));
        int taskId = rand() % 2 + 1; // Randomly select task ID 1 or 2
        std::cout << "Executing task: " << taskId << std::endl;
        lastTaskTime = currentTime;
    } else {
        std::cout << "Cooldown period not yet expired" << std::endl;
    }
}

int main() {
    executeTaskWithConstraints("sleep", 5);
    return 0;
}
