void logError(const char* message);

// Global variables
bool actionCooldown = false;
time_t lastActionTime = 0;
pthread_mutex_t cooldownMutex;

int main() {
    // Initialize mutex for thread safety
    pthread_mutex_init(&cooldownMutex, NULL);

    // Example usage of the function
    executeCommandWithDynamicTimeoutAndCooloff("ls -l", 10);

    // Clean up
    pthread_mutex_destroy(&cooldownMutex);
    return 0;
}

void* executeCommand(void* arg) {
    char* command = (char*)arg;
    pid_t pid = fork();

    if (pid == -1) {
        logError("Failed to fork process");
        return NULL;
    } else if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command, NULL);
        logError("Command execution failed");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        time_t startTime = time(NULL);

        while (waitpid(pid, &status, WNOHANG) == 0 && difftime(time(NULL), startTime) < timeout) {
            sleep(1); // Check every second
        }

        if (WIFEXITED(status)) {
            std::cout << "Command executed successfully" << std::endl;
        } else if (WIFSIGNALED(status)) {
            std::cout << "Command terminated by signal: " << WTERMSIG(status) << std::endl;
        }
    }

    return NULL;
}

void handleTimeout(int signum) {
    // Custom timeout handler
    // Adjust timeout based on system metrics here
}

void selectRandomAction() {
    pthread_mutex_lock(&cooldownMutex);
    if (!actionCooldown) {
        int action = rand() % 3 + 1; // Randomly select an action (1, 2, or 3)
        std::cout << "Selected action: " << action << std::endl;
        lastActionTime = time(NULL);
        actionCooldown = true;
    }
    pthread_mutex_unlock(&cooldownMutex);

    // Set a timer for the cooldown period
    alarm(10);
}

void logError(const char* message) {
    std::cerr << "Error: " << message << std::endl;
}
