#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <cstdlib>
#include <cstring>
#include <unistd.h>
#include <sys/wait.h>

std::mutex mtx;
std::condition_variable cv;
bool pauseExecution = false;

void executeTaskWithDynamicTimeoutAndPriority(const std::string& command, int priority) {
    std::unique_lock<std::mutex> lock(mtx);
    while (pauseExecution) {
        cv.wait(lock);
    }

    pid_t pid = fork();
    if (pid == -1) {
        std::cerr << "Failed to fork process" << std::endl;
        return;
    } else if (pid == 0) {
        // Child process
        execl("/bin/sh", "sh", "-c", command.c_str(), nullptr);
        _exit(127); // Command not found or execution failed
    }

    int status = 0;
    time_t startTime = time(nullptr);
    while (waitpid(pid, &status, WNOHANG) == 0 && difftime(time(nullptr), startTime) < priority * 5) {
        if (pauseExecution) {
            cv.wait(lock);
        }
    }

    if (WIFEXITED(status)) {
        std::cout << "Command exited with status: " << WEXITSTATUS(status) << std::endl;
    } else if (WIFSIGNALED(status)) {
        std::cout << "Command terminated by signal: " << WTERMSIG(status) << std::endl;
    }

    // Select a task randomly based on priority
    int selectedTask = rand() % 3; // Simplified for example purposes

    // Simulate task execution with cooldown
    static int cooldown = 0;
    if (selectedTask == 0) {
        std::cout << "Executing high-priority task" << std::endl;
        sleep(cooldown);
        if (cooldown < 15) {
            cooldown++;
        }
    } else if (selectedTask == 1) {
        std::cout << "Executing medium-priority task" << std::endl;
        sleep(cooldown + 2); // Higher cooldown for medium priority
    } else {
        std::cout << "Executing low-priority task" << std::endl;
        sleep(cooldown + 4); // Highest cooldown for low priority
    }
}

void pauseTaskExecution() {
    std::unique_lock<std::mutex> lock(mtx);
    pauseExecution = true;
}

void resumeTaskExecution() {
    std::unique_lock<std::mutex> lock(mtx);
    pauseExecution = false;
    cv.notify_all();
}
