#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    TYPE_LONG,
    TYPE_FLOAT,
    TYPE_DOUBLE,
    TYPE_CHAR_PTR
} DataType;

typedef struct Record {
    int key;
    union {
        long l_val;
        float f_val;
        double d_val;
        char* c_ptr;
    } value;
    DataType type;
} Record;

typedef struct RecordCollection {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        Record* record = collection->records[i];
        if (record->type == TYPE_CHAR_PTR && record->value.c_ptr) {
            free(record->value.c_ptr);
        }
        free(record);
    }

    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(RecordCollection* collection, int key, void* value, DataType type) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record** new_records = (Record**)realloc(collection->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        pthread_mutex_unlock(&collection->lock);
        return -1;
    }

    record->key = key;
    record->type = type;

    switch (type) {
        case TYPE_LONG:
            record->value.l_val = *(long*)value;
            break;
        case TYPE_FLOAT:
            record->value.f_val = *(float*)value;
            break;
        case TYPE_DOUBLE:
            record->value.d_val = *(double*)value;
            break;
        case TYPE_CHAR_PTR:
            record->value.c_ptr = strdup((char*)value);
            if (!record->value.c_ptr) {
                free(record);
                pthread_mutex_unlock(&collection->lock);
                return -1;
            }
            break;
    }

    collection->records[collection->size++] = record;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

Record* get_record(RecordCollection* collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        Record* record = collection->records[i];
        if (record->key == key) {
            pthread_mutex_unlock(&collection->lock);
            return record;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void evict_records(RecordCollection* collection, size_t max_size) {
    pthread_mutex_lock(&collection->lock);

    while (collection->size > max_size) {
        for (size_t i = 0; i < collection->size; ++i) {
            Record* record = collection->records[i];
            if (record->type == TYPE_CHAR_PTR && record->value.c_ptr) {
                free(record->value.c_ptr);
            }
            free(record);
            memmove(&collection->records[i], &collection->records[i + 1], (collection->size - i - 1) * sizeof(Record*));
            --collection->size;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}
