#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long* offset;
} Record;

Record* manageDynamicArrays(int n, int m, int p, int minValue, int maxValue) {
    if (n <= 0 || m <= 0 || p <= 0 || minValue > maxValue) {
        return NULL; // Invalid input
    }

    long* offsets = malloc(n * sizeof(long));
    if (!offsets) {
        return NULL; // Memory allocation failed
    }

    int* keys = malloc(m * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL; // Memory allocation failed
    }

    Record* records = malloc(p * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    int usedOffsets[n];
    for (int i = 0; i < n; ++i) {
        usedOffsets[i] = 0;
    }

    for (int i = 0; i < p; ++i) {
        int value = rand() % (maxValue - minValue + 1) + minValue;
        records[i].value = value;

        int offsetIndex;
        do {
            offsetIndex = rand() % n;
        } while (usedOffsets[offsetIndex]);

        usedOffsets[offsetIndex] = 1;
        offsets[offsetIndex] = i; // Store index as offset
        records[i].offset = &offsets[offsetIndex];
    }

    return records;
}
