typedef struct record {
    int value;
    char* buffer;
    pthread_mutex_t ref_count_lock;
    int ref_count;
    struct record* next_record;
} Record;

typedef struct flexible_storage {
    long* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t storage_lock;
} FlexibleStorage;

FlexibleStorage* create_flexible_storage(size_t initial_capacity) {
    FlexibleStorage* storage = (FlexibleStorage*)malloc(sizeof(FlexibleStorage));
    storage->offsets = (long*)malloc(initial_capacity * sizeof(long));
    storage->keys = (int*)malloc(initial_capacity * sizeof(int));
    storage->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    storage->capacity = initial_capacity;
    storage->size = 0;
    pthread_mutex_init(&storage->storage_lock, NULL);
    return storage;
}

void destroy_flexible_storage(FlexibleStorage* storage) {
    for (size_t i = 0; i < storage->size; ++i) {
        Record* record = storage->records[i];
        free(record->buffer);
        pthread_mutex_destroy(&record->ref_count_lock);
        free(record);
    }
    free(storage->offsets);
    free(storage->keys);
    free(storage->records);
    pthread_mutex_destroy(&storage->storage_lock);
    free(storage);
}

void add_record(FlexibleStorage* storage, int key, int value, const char* buffer) {
    pthread_mutex_lock(&storage->storage_lock);
    if (storage->size == storage->capacity) {
        size_t new_capacity = storage->capacity * 2;
        long* new_offsets = (long*)realloc(storage->offsets, new_capacity * sizeof(long));
        int* new_keys = (int*)realloc(storage->keys, new_capacity * sizeof(int));
        Record** new_records = (Record**)realloc(storage->records, new_capacity * sizeof(Record*));
        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&storage->storage_lock);
            return;
        }
        storage->offsets = new_offsets;
        storage->keys = new_keys;
        storage->records = new_records;
        storage->capacity = new_capacity;
    }

    Record* record = (Record*)malloc(sizeof(Record));
    record->value = value;
    record->buffer = strdup(buffer);
    pthread_mutex_init(&record->ref_count_lock, NULL);
    record->ref_count = 1;
    record->next_record = NULL;

    storage->offsets[storage->size] = (long)record;
    storage->keys[storage->size] = key;
    storage->records[storage->size++] = record;
    pthread_mutex_unlock(&storage->storage_lock);
}

