    void (*callback)(void);
} EncryptedPasswordData;

typedef struct {
    char *title;
    int active;
} Connection;

int decodeBase64(const char *input, char **output) {
    // Dummy implementation for decoding Base64
    *output = strdup(input); // Simplified for example purposes
    return 0; // Success
}

void tripleDesDecrypt(const char *key, const char *iv, const char *encryptedData, char **decryptedData) {
    // Dummy implementation for Triple DES decryption
    *decryptedData = strdup(encryptedData); // Simplified for example purposes
}

int checkConnection(Connection *conn) {
    if (conn->title == NULL || strlen(conn->title) == 0) return -1; // Invalid title
    if (!conn->active) return -2; // Connection not active
    return 0; // Success
}

void retryWithExponentialBackoff(int (*operation)(void), int maxRetries, int initialDelay) {
    for (int i = 0; i <= maxRetries; i++) {
        if (operation() == 0) break;
        sleep(initialDelay * (1 << i));
    }
}

int processEncryptedPassword(EncryptedPasswordData *data) {
    char *decodedPassword = NULL;
    char *decryptedPassword = NULL;

    int result = decodeBase64(data->base64_password, &decodedPassword);
    if (result != 0 || decodedPassword == NULL || strlen(decodedPassword) == 0) {
        free(decodedPassword);
        return -1; // Decoding failed or empty password
    }

    Connection *conn = data->connection;
    result = checkConnection(conn);
    if (result != 0) {
        free(decodedPassword);
        return result; // Invalid connection
    }

    if (data->callback == NULL) {
        free(decodedPassword);
        return -3; // Callback function is NULL
    }

    retryWithExponentialBackoff(
        [key, iv, decodedPassword]() -> int {
            tripleDesDecrypt(key, iv, decodedPassword, &decryptedPassword);
            return decryptedPassword != NULL ? 0 : -4; // Decryption failed
        },
        MAX_RETRIES,
        1
    );

    if (decryptedPassword == NULL) {
        free(decodedPassword);
        return -4; // Decryption failed after retries
    }

    data->callback(); // Execute callback function

    free(decodedPassword);
    free(decryptedPassword);

    return 0; // Success
}
