#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define the record structure with type union
typedef struct {
    int type;
    union {
        int i_val;
        float f_val;
        double d_val;
        char* s_val;
        void* v_val;
    } data;
} Record;

// Define the pipeline structure
typedef struct {
    size_t num_records;
    Record** records;
    pthread_mutex_t lock;
} Pipeline;

// Function to initialize the pipeline
Pipeline* init_pipeline(size_t num_records) {
    if (num_records == 0) {
        fprintf(stderr, "Error: Number of records must be greater than zero.\n");
        return NULL;
    }

    Pipeline* pipeline = (Pipeline*)malloc(sizeof(Pipeline));
    if (!pipeline) {
        perror("Failed to allocate memory for pipeline.");
        return NULL;
    }

    pipeline->num_records = num_records;
    pipeline->records = (Record**)calloc(num_records, sizeof(Record*));
    if (!pipeline->records) {
        perror("Failed to allocate memory for records.");
        free(pipeline);
        return NULL;
    }

    pthread_mutex_init(&pipeline->lock, NULL);

    return pipeline;
}

// Function to add a record to the pipeline
void add_record(Pipeline* pipeline, Record* record, size_t index) {
    if (index >= pipeline->num_records) {
        fprintf(stderr, "Error: Index out of bounds.\n");
        return;
    }

    pthread_mutex_lock(&pipeline->lock);
    pipeline->records[index] = record;
    pthread_mutex_unlock(&pipeline->lock);
}

// Function to free the pipeline and its records
void free_pipeline(Pipeline* pipeline) {
    if (pipeline) {
        for (size_t i = 0; i < pipeline->num_records; ++i) {
            Record* record = pipeline->records[i];
            if (record) {
                switch (record->type) {
                    case 's':
                        free(record->data.s_val);
                        break;
                    case 'v':
                        free(record->data.v_val);
                        break;
                    default:
                        // No additional cleanup needed for other types
                        break;
                }
                free(record);
            }
        }
        free(pipeline->records);
        pthread_mutex_destroy(&pipeline->lock);
        free(pipeline);
    }
}

// Example usage
int main() {
    Pipeline* pipeline = init_pipeline(10);
    if (pipeline) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->type = 'i';
        record->data.i_val = 42;

        add_record(pipeline, record, 0);

        free_pipeline(pipeline);
    }

    return 0;
}
```

This code snippet provides a basic structure for initializing and managing a flexible data processing pipeline in C. It includes functions to initialize the pipeline, add records, and free the pipeline. The `Record` structure uses a union to handle different data types dynamically. The pipeline is protected by a mutex for thread-safe access. This example does not include all the features requested (e.g., serialization, external storage, garbage collection), but it serves as a starting point for further development.']

