} Transaction;

typedef struct {
    Transaction *transactions;
    int count;
    pthread_mutex_t lock;
} TransactionManager;

TransactionManager *tm_init() {
    TransactionManager *manager = (TransactionManager *)malloc(sizeof(TransactionManager));
    if (!manager) {
        perror("Failed to allocate memory for TransactionManager");
        return NULL;
    }
    manager->transactions = (Transaction *)calloc(MAX_TRANSACTIONS, sizeof(Transaction));
    if (!manager->transactions) {
