Record* createRecords(int count, RecordType types[], Identifier ids[], Metadata metas[], void** offsets) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        records[i].type = types[i];
        records[i].id = ids[i];
        records[i].meta = metas[i];
        records[i].offsetPtr = offsets[i];

        if (types[i] == STRING_TYPE && !ids[i].stringId) {
            fprintf(stderr, "String identifier cannot be NULL\n");
            free(records);
            return NULL;
        }
    }

    return records;
}

void freeRecords(Record* records, int count) {
    for (int i = 0; i < count; i++) {
        if (records[i].type == STRING_TYPE && records[i].id.stringId) {
            free(records[i].id.stringId);
        }
    }
    free(records);
}

