import java.io.*;
import java.util.concurrent.*;
import java.time.*;

public class ServiceManager {
    private ScheduledExecutorService scheduler;
    private ExecutorService executor;
    private int interval;
    private int retryCount;
    private long logRetentionDays;

    public ServiceManager(int interval, int retryCount, long logRetentionDays) {
        this.interval = interval;
        this.retryCount = retryCount;
        this.logRetentionDays = logRetentionDays;
        scheduler = Executors.newScheduledThreadPool(1);
        executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    }

    public void startService() {
        scheduler.scheduleAtFixedRate(this::runService, 0, interval, TimeUnit.SECONDS);
    }

    private void runService() {
        for (int i = 0; i < retryCount; i++) {
            try {
                // Simulate service operation
                System.out.println("Service started at " + LocalDateTime.now());
                executor.submit(() -> performServiceOperation());
                break;
            } catch (Exception e) {
                if (i == retryCount - 1) {
                    logError(e);
                    sendFailureMessage();
                }
            }
        }
    }

    private void performServiceOperation() {
        // Simulate service operation
        System.out.println("Performing service operation at " + LocalDateTime.now());
        Thread.sleep(500); // Simulate work
    }

    private void logError(Exception e) {
        String logMessage = "Error: " + e.getMessage() + " at " + LocalDateTime.now();
        System.err.println(logMessage);
        compressLogs();
    }

    private void sendFailureMessage() {
        try {
            // Send failure message to external messaging system
            System.out.println("Sending failure message at " + LocalDateTime.now());
        } catch (Exception e) {
            // Fallback mechanism for secondary messaging system
            System.err.println("Failed to send message, using fallback: " + e.getMessage());
        }
    }

    private void compressLogs() {
        try {
            // Compress logs periodically
            System.out.println("Compressing logs at " + LocalDateTime.now());
        } catch (Exception e) {
            System.err.println("Error compressing logs: " + e.getMessage());
        }
    }

    public void stopService() {
        scheduler.shutdown();
        executor.shutdown();
        try {
            if (!scheduler.awaitTermination(60, TimeUnit.SECONDS)) {
                scheduler.shutdownNow();
            }
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            scheduler.shutdownNow();
            executor.shutdownNow();
        }
    }

    public static void main(String[] args) {
        ServiceManager serviceManager = new ServiceManager(10, 3, 7);
        serviceManager.startService();

        // Simulate stopping the service after some time
        try {
            Thread.sleep(60000); // Run for 1 minute
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        serviceManager.stopService();
    }
}
