#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTION_ID_LENGTH 10

typedef struct {
    time_t timestamp;
    double amount;
    char status;
    char id[MAX_TRANSACTION_ID_LENGTH];
} Transaction;

typedef struct {
    Transaction* transactions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TransactionManager;

TransactionManager* create_transaction_manager(size_t initial_capacity) {
    TransactionManager* manager = (TransactionManager*)malloc(sizeof(TransactionManager));
    if (!manager) return NULL;

    manager->transactions = (Transaction*)calloc(initial_capacity, sizeof(Transaction));
    if (!manager->transactions) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_transaction_manager(TransactionManager* manager) {
    if (manager) {
        free(manager->transactions);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}

int add_transaction(TransactionManager* manager, Transaction transaction) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Transaction* new_transactions = (Transaction*)realloc(manager->transactions, new_capacity * sizeof(Transaction));
        if (!new_transactions) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->transactions = new_transactions;
        manager->capacity = new_capacity;
    }

    manager->transactions[manager->size++] = transaction;
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

int sort_transactions(TransactionManager* manager) {
    pthread_mutex_lock(&manager->lock);
    qsort(manager->transactions, manager->size, sizeof(Transaction), [](const void* a, const void* b) {
        return ((Transaction*)a)->timestamp - ((Transaction*)b)->timestamp;
    });
    pthread_mutex_unlock(&manager->lock);

    return 0;
}

void log_transaction_manager_state(TransactionManager* manager) {
    printf("Transaction Manager State:\n");
    printf("Capacity: %zu\n", manager->capacity);
    printf("Size: %zu\n", manager->size);
}
