#include <openssl/evp.h>

typedef struct {
    const char *name;
    void (*impl)(void);
    int params;
} Algorithm;

Algorithm* get_available_algorithms(int *count) {
    EVP_MD **mds = EVP_get_digest_methods();
    EVP_CIPHER **ciphers = EVP_get_cipher_methods();

    *count = EVP_MD_count() + EVP_CIPHER_count();
    Algorithm *algorithms = (Algorithm *)malloc(*count * sizeof(Algorithm));

    int i = 0;
    for (; mds[i] != NULL; i++) {
        algorithms[i].name = EVP_MD_name(mds[i]);
        algorithms[i].impl = (void (*)(void))EVP_MD_get_digest(mds[i]);
        algorithms[i].params = EVP_MD_size(mds[i]);
    }

    for (int j = 0; ciphers[j] != NULL; j++) {
        algorithms[i + j].name = EVP_CIPHER_name(ciphers[j]);
        algorithms[i + j].impl = (void (*)(void))EVP_CIPHER_get_cipher(ciphers[j]);
        algorithms[i + j].params = EVP_CIPHER_block_size(ciphers[j]);
    }

    return algorithms;
}

void free_algorithms(Algorithm *algorithms, int count) {
    free(algorithms);
}

int main() {
    int count;
    Algorithm *algorithms = get_available_algorithms(&count);

    for (int i = 0; i < count; i++) {
        printf("Name: %s\n", algorithms[i].name);
        printf("Implementation: %p\n", algorithms[i].impl);
        printf("Parameters: %d\n", algorithms[i].params);
    }

    free_algorithms(algorithms, count);

    return 0;
}
