# Python code for managing a scalable distributed logging system

class LogEntry:
    def __init__(self, message, timestamp, metadata):
        self.message = message
        self.timestamp = timestamp
        self.metadata = metadata

def initialize_logs(num_entries):
    try:
        logs = [LogEntry(None, None, None) for _ in range(num_entries)]
        return logs
    except MemoryError:
        print("Memory allocation failed")
        return None

def read_logs(logs):
    import sys
    for i, line in enumerate(sys.stdin):
        message, timestamp, metadata = line.strip().split(',')
        logs[i] = LogEntry(message, int(timestamp), metadata)

def find_earliest_latest(logs):
    earliest = min(logs, key=lambda x: x.timestamp)
    latest = max(logs, key=lambda x: x.timestamp)
    print(f"Earliest log: {earliest.message}, Timestamp: {earliest.timestamp}")
    print(f"Latest log: {latest.message}, Timestamp: {latest.timestamp}")

def count_unique_messages(logs):
    import time
    start_time = time.time()
    unique_messages = set(entry.message for entry in logs)
    end_time = time.time()
    print(f"Number of unique messages: {len(unique_messages)}")
    print(f"Time taken to calculate: {end_time - start_time} seconds")

def cleanup_logs(logs):
