#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    char* name;
    int age;
    double salary;
} Person;

typedef struct {
    Person* persons;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PersonCollection;

PersonCollection* create_person_collection() {
    PersonCollection* collection = (PersonCollection*)malloc(sizeof(PersonCollection));
    if (!collection) return NULL;

    collection->persons = (Person*)malloc(INITIAL_CAPACITY * sizeof(Person));
    if (!collection->persons) {
        free(collection);
        return NULL;
    }

    collection->count = 0;
    collection->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_person_collection(PersonCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        free(collection->persons[i].name);
    }
    free(collection->persons);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_person(PersonCollection* collection, const char* name, int age, double salary) {
    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * GROWTH_FACTOR;
        Person* new_persons = (Person*)realloc(collection->persons, new_capacity * sizeof(Person));
        if (!new_persons) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->persons = new_persons;
        collection->capacity = new_capacity;
    }

    Person* person = &collection->persons[collection->count++];
    person->name = strdup(name);
    if (!person->name) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failed
    }
    person->age = age;
    person->salary = salary;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int remove_person(PersonCollection* collection, const char* name) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->persons[i].name, name) == 0) {
            free(collection->persons[i].name);
            for (size_t j = i; j < collection->count - 1; ++j) {
                collection->persons[j] = collection->persons[j + 1];
            }
            --collection->count;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Person not found
}

int update_person(PersonCollection* collection, const char* name, int age, double salary) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->persons[i].name, name) == 0) {
            free(collection->persons[i].name);
            collection->persons[i].name = strdup(name);
            if (!collection->persons[i].name) {
                pthread_mutex_unlock(&collection->lock);
                return -1; // Memory allocation failed
            }
            collection->persons[i].age = age;
            collection->persons[i].salary = salary;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Person not found
}

void print_person_collection(const PersonCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        printf("Name: %s, Age: %d, Salary: %.2f\n", collection->persons[i].name, collection->persons[i].age, collection->persons[i].salary);
    }
}
