#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define POOL_SIZE 1024

typedef struct {
    double value;
    char* name;
} record;

char pool[POOL_SIZE];
int pool_index = 0;

record* create_records(int num_records) {
    if (num_records <= 0) return NULL;

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        if (pool_index >= POOL_SIZE) {
            fprintf(stderr, "Character pool exhausted\n");
            free(records);
            return NULL;
        }

        records[i].value = i * 1.1;
        records[i].name = &pool[pool_index];
        int name_length = snprintf(pool + pool_index, POOL_SIZE - pool_index, "Name%d", i);
        if (name_length < 0 || name_length >= POOL_SIZE - pool_index) {
            fprintf(stderr, "Error formatting name\n");
            free(records);
            return NULL;
        }
        pool_index += name_length + 1; // Add space for null terminator
    }

    return records;
}

void destroy_records(record* records, int num_records) {
    if (records) {
        free(records);
    }
}

int main() {
    record* my_records = create_records(5);
    if (my_records) {
        for (int i = 0; i < 5; ++i) {
            printf("Record %d: Value = %.1f, Name = %s\n", i, my_records[i].value, my_records[i].name);
        }
        destroy_records(my_records, 5);
    }

    return 0;
}
