import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class JwtValidator {

    private static final Logger logger = LoggerFactory.getLogger(JwtValidator.class);
    private static final String SECRET_KEY = "yourSecretKey";
    private static final int MAX_VALIDATION_ATTEMPTS = 10;

    public Response validateJwt(String jwt, String expectedIssuer, String expectedAudience) {
        if (jwt == null || jwt.isEmpty()) {
            return new ErrorResponse("Invalid JWT");
        }

        try {
            Claims claims = Jwts.parser()
                    .setSigningKey(SECRET_KEY)
                    .parseClaimsJws(jwt)
                    .getBody();

            if (claims.getIssuedAt().getTime() > System.currentTimeMillis()) {
                return new ErrorResponse("Token has expired");
            }

            if (!expectedIssuer.equals(claims.getIssuer())) {
                return new ErrorResponse("Invalid issuer");
            }

            if (!expectedAudience.equals(claims.getAudience())) {
                return new ErrorResponse("Invalid audience");
            }

            // Perform additional checks for user permissions
            if (!hasRequiredPermissions(claims)) {
                return new ErrorResponse("Insufficient permissions");
            }

            return new SuccessResponse(claims);
        } catch (Exception e) {
            logger.error("JWT validation failed: {}", e.getMessage());
            return new ErrorResponse("Invalid authentication");
        }
    }

    private boolean hasRequiredPermissions(Claims claims) {
        // Implement permission checks based on user claims
        return true; // Placeholder for actual permission logic
    }

    public static class Response {
        private final Object data;
        private final String message;

        public Response(Object data, String message) {
            this.data = data;
            this.message = message;
        }

        public boolean isSuccess() {
            return data != null;
        }

        public Object getData() {
            return data;
        }

        public String getMessage() {
            return message;
        }
    }

    public static class SuccessResponse extends Response {
        public SuccessResponse(Object data) {
            super(data, "Access granted");
        }
    }

    public static class ErrorResponse extends Response {
        public ErrorResponse(String message) {
            super(null, message);
        }
    }
}
