#include <string.h>
#include <pthread.h>

typedef struct {
    char* name;
    int age;
    double salary;
} Person;

typedef struct Node {
    Person person;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addPerson(const char* name, int age, double salary) {
    pthread_mutex_lock(&lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Failed to allocate memory for new person");
        pthread_mutex_unlock(&lock);
        return;
    }
    newNode->person.name = strdup(name);
    newNode->person.age = age;
    newNode->person.salary = salary;
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&lock);
}

void removePerson(const char* name) {
    pthread_mutex_lock(&lock);
    Node* current = head;
    Node* previous = NULL;
    while (current != NULL) {
        if (strcmp(current->person.name, name) == 0) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current->person.name);
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void updatePersonSalary(const char* name, double newSalary) {
    pthread_mutex_lock(&lock);
    Node* current = head;
    while (current != NULL) {
        if (strcmp(current->person.name, name) == 0) {
            current->person.salary = newSalary;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void printAllPersons() {
    pthread_mutex_lock(&lock);
    Node* current = head;
    while (current != NULL) {
        printf("Name: %s, Age: %d, Salary: %.2f\n", current->person.name, current->person.age, current->person.salary);
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void* updateFromExternalSource(void* arg) {
    // Implement logic to fetch data from external source
    // Update persons in the list based on fetched data
    return NULL;
}
