    bool isConnected() const { return true; }
    double getPerformanceScore() const { return 95.0; }
};

void processFileAndData(std::vector<int>& data, std::string& filename, int& increment, bool useDigits, std::shared_ptr<DataSource> dataSource) {
    if (!dataSource->isConnected() || dataSource->getPerformanceScore() < 80.0) {
        // Log error
        return;
    }

    auto it = std::find(data.begin(), data.end(), 1); // Assuming the first argument is always 1 for simplicity
    if (it != data.end()) {
        increment += 10;
        size_t digitCount = std::count_if(filename.begin(), filename.end(), ::isdigit);
        std::string newExtension = useDigits ? std::to_string(digitCount) : std::to_string(filename.length());
        filename.replace(filename.find_last_of('.'), std::string::npos, "." + newExtension);
    } else {
        increment -= 5;
        size_t uppercaseCount = std::count_if(filename.begin(), filename.end(), ::isupper);
        filename += std::to_string(uppercaseCount);
    }
}
