public class SqlQueryProcessor
{
    private readonly Dictionary<string, string> _connectionStrings;
    private readonly Dictionary<string, object> _defaultParameters;
    private readonly PerformanceOptimizationConfig _performanceConfig;
    private readonly ILoggerService _logger;

    public SqlQueryProcessor(Dictionary<string, string> connectionStrings, Dictionary<string, object> defaultParameters, PerformanceOptimizationConfig performanceConfig, ILoggerService logger)
    {
        _connectionStrings = connectionStrings;
        _defaultParameters = defaultParameters;
        _performanceConfig = performanceConfig;
        _logger = logger;
    }

    public async Task<Dictionary<string, IDataReader>> ProcessQueriesAsync(List<string> sqlCommands)
    {
        var results = new Dictionary<string, IDataReader>();

        foreach (var command in sqlCommands)
        {
            if (!IsWhitelisted(command))
            {
                _logger.LogWarning($"Command '{command}' is not whitelisted.");
                continue;
            }

            var databaseName = GetDatabaseFromCommand(command);
            if (!_connectionStrings.ContainsKey(databaseName))
            {
                _logger.LogError($"No connection string found for database: {databaseName}");
                continue;
            }

            using (var connection = new SqlConnection(_connectionStrings[databaseName]))
            {
                await connection.OpenAsync();

                var commandText = ReplaceParameters(command, _defaultParameters);
                using (var commandObj = new SqlCommand(commandText, connection))
                {
                    if (_performanceConfig.MaxCpuUsage > 0)
                    {
                        var cpuMonitor = new CpuUsageMonitor(_performanceConfig.MaxCpuUsage);
                        await Task.Run(async () =>
                        {
                            try
                            {
                                await cpuMonitor.StartAsync();
                                using (var reader = await commandObj.ExecuteReaderAsync())
                                {
                                    results[databaseName] = reader;
                                }
                            }
                            finally
                            {
                                await cpuMonitor.StopAsync();
                            }
                        });
                    }
                    else
                    {
                        using (var reader = await commandObj.ExecuteReaderAsync())
                        {
                            results[databaseName] = reader;
                        }
                    }
                }
            }
        }

        return results;
    }

    private bool IsWhitelisted(string command)
    {
