    {
        foreach (var param in parameters)
        {
            command = command.Replace($"@{param.Key}", param.Value.ToString());
        }
        return command;
    }
}

public class PerformanceOptimizationConfig
{
    public int MaxCpuUsage { get; set; }
}

public interface ILoggerService
{
    void LogWarning(string message);
    void LogError(string message);
}

public class CpuUsageMonitor
{
    private readonly int _maxCpuUsage;
    private Stopwatch _stopwatch;

    public CpuUsageMonitor(int maxCpuUsage)
    {
        _maxCpuUsage = maxCpuUsage;
    }

    public async Task StartAsync()
    {
        _stopwatch = new Stopwatch();
        _stopwatch.Start();

        while (_stopwatch.Elapsed.TotalMilliseconds < 1000) // Monitor for 1 second
        {
            var cpuUsage = await GetCpuUsageAsync();
            if (cpuUsage > _maxCpuUsage)
            {
                throw new InvalidOperationException("CPU usage exceeded the allowed limit.");
            }
            await Task.Delay(10); // Check every 10 milliseconds
        }

        _stopwatch.Stop();
    }

    public async Task StopAsync()
    {
        _stopwatch.Stop();
    }

    private static async Task<double> GetCpuUsageAsync()
