    private XDocument config;
    private Dictionary<string, InputDevice> inputDevices;
    private GraphicsEngine graphicsEngine;
    private PhysicsSimulation physicsSimulation;
    private NetworkModule networkModule;

    public GameEnvironment(string configFilePath)
    {
        config = XDocument.Load(configFilePath);
        InitializeInputDevices();
        InitializeGraphicsEngine();
        InitializePhysicsSimulation();
        InitializeNetworkModule();
    }

    private void InitializeInputDevices()
    {
        inputDevices = new Dictionary<string, InputDevice>();
        foreach (var device in config.Descendants("InputDevice"))
        {
            string type = device.Attribute("type").Value;
            switch (type)
            {
                case "Keyboard":
                    inputDevices[type] = new Keyboard();
                    break;
                case "Mouse":
                    inputDevices[type] = new Mouse();
                    break;
                case "Gamepad":
                    inputDevices[type] = new Gamepad();
                    break;
