#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_REPORTS 1000
#define MAX_DATA_ENTRIES 50

typedef struct {
    long timestamp;
    int status_code;
    char description[256];
} DataEntry;

typedef struct {
    long timestamp;
    int category_id;
    DataEntry data[MAX_DATA_ENTRIES];
} Report;

Report* reports[MAX_REPORTS];
int report_count = 0;

void initializeReports() {
    for (int i = 0; i < MAX_REPORTS; i++) {
        reports[i] = NULL;
    }
}

Report* createReport(int category_id) {
    if (report_count >= MAX_REPORTS) {
        return NULL;
    }
    Report* report = (Report*)malloc(sizeof(Report));
    if (!report) {
        return NULL;
    }
    report->timestamp = time(NULL);
    report->category_id = category_id;
    for (int i = 0; i < MAX_DATA_ENTRIES; i++) {
        report->data[i].timestamp = 0;
        report->data[i].status_code = 0;
        memset(report->data[i].description, 0, sizeof(report->data[i].description));
    }
    reports[report_count++] = report;
    return report;
}

void freeReport(Report* report) {
    if (report) {
        free(report);
    }
}

int main() {
    initializeReports();

    // Example usage
    Report* new_report = createReport(1);
    if (new_report) {
        printf("Report created successfully.\n");
        freeReport(new_report);
    } else {
        printf("Failed to create report.\n");
    }

    return 0;
}
