    if (size == 0) return -1; // Handle empty input
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

void initializeRecords(Record** records, int* keys, int size, int rangeStart, int rangeEnd) {
    *records = (Record*)malloc(size * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; i++) {
        (*records)[i].offset = rand() % rangeEnd + rangeStart;
        (*records)[i].key = keys[i];
        (*records)[i].value = rand() % rangeEnd + rangeStart;
        snprintf((*records)[i].scriptContent, sizeof((*records)[i].scriptContent), "console.log(%d);", (*records)[i].key);
    }
}

void freeRecords(Record* records, int size) {
    free(records);
}

int main() {
    int keys[MAX_SCRIPTS];
    int size;
    printf("Enter the number of scripts (max %d): ", MAX_SCRIPTS);
    scanf("%d", &size);

    if (size <= 0 || size > MAX_SCRIPTS) {
        fprintf(stderr, "Invalid input\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < size; i++) {
        printf("Enter key %d: ", i + 1);
        scanf("%d", &keys[i]);
    }

    int largestKey = findLargestInteger(keys, size);
    printf("Largest integer: %d\n", largestKey);

