#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_SIZE 1024 * 1024 // Maximum memory size in bytes
#define RECORD_SIZE sizeof(record)
#define KEY_RANGE 1000

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t allocated_size;
    pthread_mutex_t lock;
} data_structures;

data_structures ds = {NULL, NULL, NULL, 0, PTHREAD_MUTEX_INITIALIZER};

int allocate_memory(size_t num_records) {
    if (num_records * RECORD_SIZE > MAX_SIZE - ds.allocated_size) {
        return -1; // Not enough memory
    }

    ds.offsets = realloc(ds.offsets, num_records * sizeof(long));
    ds.keys = realloc(ds.keys, num_records * sizeof(int));
    ds.records = realloc(ds.records, num_records * RECORD_SIZE);

    if (!ds.offsets || !ds.keys || !ds.records) {
        return -2; // Memory allocation failed
    }

    ds.allocated_size += num_records * RECORD_SIZE;

    for (size_t i = 0; i < num_records; ++i) {
        ds.offsets[i] = rand();
        ds.keys[i] = rand() % KEY_RANGE;
        ds.records[i].value = rand() % KEY_RANGE;
    }

    return 0; // Success
}

void log_time(const char* message) {
    time_t now = time(NULL);
    printf("%s: %ld\n", message, now);
}

int initialize_data_structures(size_t num_records) {
    pthread_mutex_lock(&ds.lock);

    if (allocate_memory(num_records) != 0) {
        pthread_mutex_unlock(&ds.lock);
        return -1; // Initialization failed
    }

    log_time("Initialization started");
    // Perform initialization tasks here
    log_time("Initialization ended");

    pthread_mutex_unlock(&ds.lock);
    return 0; // Success
}

int main() {
    srand(time(NULL));

    if (initialize_data_structures(100) != 0) {
        printf("Failed to initialize data structures\n");
    }

    free(ds.offsets);
    free(ds.keys);
    free(ds.records);

    return 0;
}
