use reqwest::{Client, Error, Method, RequestBuilder};
use std::time::Duration;
use tokio::sync::Mutex;

#[derive(Clone)]
struct HttpClient {
    client: Client,
    log_service_url: String,
}

impl HttpClient {
    fn new(tls_version: &str, log_service_url: String) -> Result<Self, Error> {
        let mut builder = reqwest::ClientBuilder::new();

        if tls_version == "1.2" {
            builder = builder.tls_min_version(reqwest::tls::Version::TLSv1_2);
        } else if tls_version == "1.3" {
            builder = builder.tls_min_version(reqwest::tls::Version::TLSv1_3);
        }

        let client = builder
            .pool_max_idle_per_host(5)
            .timeout(Duration::from_secs(10))
            .build()?;

        Ok(HttpClient {
            client,
            log_service_url,
        })
    }

    async fn send_request(
        &self,
        method: Method,
        url: String,
        headers: Option<header::HeaderMap>,
        body: Option<reqwest::Body>,
    ) -> Result<String, Error> {
        let mut request = self.client.request(method, url);

        if let Some(headers) = headers {
            request = request.headers(headers);
        }

        if let Some(body) = body {
            request = request.body(body);
        }

        let response = request.send().await?;
        let text = response.text().await?;

        // Log the request and response
        self.log_request_response(&method, &url, headers.as_ref(), &text).await?;

        Ok(text)
    }

    async fn log_request_response(
        &self,
        method: &Method,
        url: &str,
        headers: Option<&header::HeaderMap>,
        body: &str,
    ) -> Result<(), Error> {
        let mut log_data = String::new();
        log_data.push_str(&format!("Request Method: {}\n", method));
        log_data.push_str(&format!("URL: {}\n", url));
        if let Some(headers) = headers {
            for (key, value) in headers.iter() {
                log_data.push_str(&format!("Header: {} - {}\n", key, value.to_str().unwrap()));
            }
        }
        log_data.push_str(&format!("Body: {}\n", body));

        self.client.post(&self.log_service_url).body(log_data).send().await?;

        Ok(())
    }

    async fn get(&self, url: String) -> Result<String, Error> {
        self.send_request(Method::GET, url, None, None).await
    }

    async fn post(
        &self,
        url: String,
        headers: Option<header::HeaderMap>,
        body: Option<reqwest::Body>,
    ) -> Result<String, Error> {
        self.send_request(Method::POST, url, headers, body).await
    }
}

#[tokio::main]
async fn main() -> Result<(), Error> {
    let client = HttpClient::new("1.2", "http://example.com/log".to_string())?;

    // Example GET request
    let response = client.get("http://example.com/api/data".to_string()).await?;
    println!("GET Response: {}", response);

    // Example POST request
    let headers = Some(header::HeaderMap::from_iter(vec![
        (header::CONTENT_TYPE, header::HeaderValue::from_static("application/json")),
    ]));
    let body = Some(reqwest::Body::from(r#"{"key":"value"}"#));
    let response = client.post("http://example.com/api/submit".to_string(), headers, body).await?;
    println!("POST Response: {}", response);

    Ok(())
}
