import asyncio
import logging
from typing import Dict, Any, Optional

class FileHandler:
    def __init__(self, file_path: str):
        self.file_path = file_path
        self.lock = asyncio.Lock()

    async def read_file(self) -> str:
        async with self.lock:
            try:
                with open(self.file_path, 'r') as file:
                    return await asyncio.to_thread(file.read)
            except IOError as e:
                logging.error(f"Failed to read file: {e}")
                raise

    async def write_file(self, data: str) -> None:
        async with self.lock:
            try:
                with open(self.file_path, 'w') as file:
                    await asyncio.to_thread(file.write, data)
            except IOError as e:
                logging.error(f"Failed to write file: {e}")
                raise

class DataProcessor:
    @staticmethod
    def processUserInput(input_data: str, config: Dict[str, Any]) -> str:
        if config.get('sanitize_input'):
            input_data = input_data.strip()
            input_data = ''.join(e for e in input_data if e.isalnum() or e.isspace())
        if config.get('max_length') is not None and len(input_data) > config['max_length']:
            input_data = input_data[:config['max_length']]
        allowed_chars = set(config.get('allowed_characters', ''))
        input_data = ''.join(e for e in input_data if e in allowed_chars)
        return input_data

# Example usage
async def main():
    file_handler = FileHandler('example.txt')
    data_processor = DataProcessor()

    # Read from file
    try:
        content = await file_handler.read_file()
        processed_content = data_processor.processUserInput(content, {
            'sanitize_input': True,
            'max_length': 100,
            'allowed_characters': 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
        })
        print(processed_content)
    except Exception as e:
        logging.error(f"Error processing input: {e}")

    # Write to file
    try:
        await file_handler.write_file("Hello, World!")
    except Exception as e:
        logging.error(f"Error writing to file: {e}")

asyncio.run(main())
