StateSequence* create_state_sequence(FSA* fsa, State** states, int num_states, int last_state_id) {
    StateSequence* sequence = (StateSequence*)malloc(sizeof(StateSequence));
    if (sequence == NULL) {
        return NULL; // Handle memory allocation failure
    }
    pthread_mutex_init(&sequence->lock, NULL);
    sequence->head = create_state(last_state_id);
    if (sequence->head == NULL) {
        free(sequence);
        return NULL; // Handle memory allocation failure
    }

    State* current_state = sequence->head;
    for (int i = num_states - 1; i >= 0; i--) {
        if (!validate_transition(fsa, states[i]->id, current_state->id)) {
            free(sequence->head);
            pthread_mutex_destroy(&sequence->lock);
            free(sequence);
            return NULL; // Handle invalid transition
        }
        State* new_state = create_state(states[i]->id);
        if (new_state == NULL) {
            free(sequence->head);
            pthread_mutex_destroy(&sequence->lock);
            free(sequence);
            return NULL; // Handle memory allocation failure
        }
        new_state->next = current_state;
        current_state = new_state;
    }

    sequence->head = current_state;

    return sequence;
}

