#include <vector>
#include <cmath>
#include <algorithm>

class KDTreeNode {
public:
    std::vector<double> point;
    int axis;
    KDTreeNode* left;
    KDTreeNode* right;

    KDTreeNode(const std::vector<double>& p, int a) : point(p), axis(a), left(nullptr), right(nullptr) {}
};

class KDTree {
private:
    KDTreeNode* root;
    int featureSize;
    int leafNodeCapacity;
    int maxDepth;
    int currentDepth;

    KDTreeNode* buildTree(const std::vector<std::vector<double>>& points, int depth = 0);
    KDTreeNode* insert(KDTreeNode* node, const std::vector<double>& point, int depth);
    void nearestNeighborSearch(KDTreeNode* node, const std::vector<double>& target, double& minDist, std::vector<double>& closestPoint) const;
    void resizeTree();

public:
    KDTree(int featureSize, int leafNodeCapacity, int maxDepth)
        : root(nullptr), featureSize(featureSize), leafNodeCapacity(leafNodeCapacity), maxDepth(maxDepth), currentDepth(0) {}

    ~KDTree() {
        deleteTree(root);
    }

    void insert(const std::vector<double>& point) {
        if (root == nullptr) {
            root = new KDTreeNode(point, 0);
        } else {
            root = insert(root, point, 0);
        }
        currentDepth++;
        resizeTree();
    }

    void nearestNeighbor(const std::vector<double>& target, double& minDist, std::vector<double>& closestPoint) const {
        if (root != nullptr) {
            nearestNeighborSearch(root, target, minDist, closestPoint);
        }
    }

private:
    void deleteTree(KDTreeNode* node) {
        if (node != nullptr) {
            deleteTree(node->left);
            deleteTree(node->right);
            delete node;
        }
    }
};
