typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    int totalRecords;
    bool dataReady;
} DataStructure;

DataStructure* initializeData(long* offsetValues, int* keyValues, int size) {
    if (size <= 0) {
        fprintf(stderr, "Error: Invalid size for initialization.\n");
        return NULL;
    }

    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    ds->offsets = (long*)malloc(size * sizeof(long));
    ds->keys = (int*)malloc(size * sizeof(int));
    ds->records = (Record*)malloc(size * sizeof(Record));
    if (!ds->offsets || !ds->keys || !ds->records) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(ds);
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        ds->offsets[i] = offsetValues[i];
        ds->keys[i] = keyValues[i];
        ds->records[i].value = calculateRecordValue(offsetValues[i], keyValues[i]);
        ds->records[i].isValid = true;
    }

    ds->totalRecords = size;
    ds->dataReady = true;

    return ds;
}

int calculateRecordValue(long offset, int key) {
    // Custom algorithm to combine offset and key values
    return (offset * 31 + key) % 1000; // Example: Simple hash function
}

void validateData(DataStructure* ds) {
    for (int i = 0; i < ds->totalRecords; i++) {
        if (!ds->records[i].isValid) {
            fprintf(stderr, "Invalid record found at index %d.\n", i);
            // Optionally reduce performance or handle the error as needed
        }
    }
}

void freeData(DataStructure* ds) {
    if (ds) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
    }
}
