import java.io.*;
import java.net.URL;
import java.util.*;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import org.apache.commons.compress.compressors.gzip.GZIPInputStream;
import org.apache.commons.compress.compressors.deflate.DeflateCompressorInputStream;

public class ConfigLoader {
    private static final String AES_KEY = "your_aes_key_here";
    private static final int CACHE_SIZE = 100;
    private static Map<String, String> cache = new LinkedHashMap<>(CACHE_SIZE, 0.75f, true) {
        protected boolean removeEldestEntry(Map.Entry eldest) {
            return size() > CACHE_SIZE;
        }
    };

    public static String loadConfig(String configUrl) throws Exception {
        if (cache.containsKey(configUrl)) {
            return cache.get(configUrl);
        }

        URL url = new URL(configUrl);
        InputStream inputStream = url.openStream();
        try {
            if (configUrl.endsWith(".gz")) {
                inputStream = new GZIPInputStream(inputStream);
            } else if (configUrl.endsWith(".deflate")) {
                inputStream = new DeflateCompressorInputStream(inputStream);
            }

            String config = readConfigFromStream(inputStream);
            cache.put(configUrl, decrypt(config));
            return config;
        } finally {
            inputStream.close();
        }
    }

    private static String readConfigFromStream(InputStream inputStream) throws IOException {
        StringBuilder sb = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line).append("\n");
            }
        }
        return sb.toString();
    }

    private static String decrypt(String encryptedConfig) throws Exception {
        SecretKeySpec secretKey = new SecretKeySpec(AES_KEY.getBytes(), "AES");
        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.DECRYPT_MODE, secretKey);
        byte[] decodedBytes = Base64.getDecoder().decode(encryptedConfig);
        return new String(cipher.doFinal(decodedBytes));
    }

    public static void main(String[] args) {
        try {
            String config = loadConfig("https://example.com/config.properties.gz");
            System.out.println(config);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
