#define MAX_MEMORY_LIMIT 1024 * 1024 // 1MB limit for demonstration

typedef struct {
    int value;
} Record;

typedef struct {
    time_t timestamp;
    Record records[2];
} Event;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_structures() {
    time_t start_time, end_time;
    double total_memory_used = 0;

    // Log start time
    time(&start_time);

    long* offset_values = allocate_memory(5 * sizeof(long));
    int* keys = allocate_memory(5 * sizeof(int));

    Record** records = (Record**)allocate_memory(2 * sizeof(Record*));
    for (int i = 0; i < 2; i++) {
        records[i] = allocate_memory(sizeof(Record));
        records[i]->value = rand() % 100 + 1;
        total_memory_used += sizeof(Record);
    }

    Event* event = allocate_memory(sizeof(Event));
    time(&event->timestamp);

    // Log end time
    time(&end_time);

    double average_record_size = total_memory_used / 2;

    printf("Memory usage: %.2f bytes\n", total_memory_used);
    printf("Average record size: %.2f bytes\n", average_record_size);
    printf("Total memory limit: %d bytes\n", MAX_MEMORY_LIMIT);
    printf("Memory used: %.2f%%\n", (total_memory_used / MAX_MEMORY_LIMIT) * 100);

    if (total_memory_used > MAX_MEMORY_LIMIT) {
        fprintf(stderr, "Memory usage exceeds limit\n");
    }

    // Free allocated memory
    free(offset_values);
    free(keys);
    for (int i = 0; i < 2; i++) {
        free(records[i]);
    }
    free(records);
    free(event);
}

int main() {
    srand(time(NULL));
    initialize_structures();
    return 0;
}
