    std::string logDirectory = configManager.getConfigValue("log_directory");
    if (logDirectory.empty()) {
        logDirectory = "/default/log/directory";
    }

    // Process log entries from the specified log file
    std::ifstream logFile(logDirectory + "/large_log_file.log");
    std::string line;
    while (std::getline(logFile, line)) {
        logProcessor.processLogEntry(line);
    }

    // Generate and output the summary report
    logProcessor.generateSummaryReport();

    return 0;
}
