    private readonly IAsyncCryptoTransform _chacha20Transformer;
    private readonly SHA256 _sha256Hasher;
    private readonly RSACryptoServiceProvider _rsaProvider;

    public CryptoUtility()
    {
        // Initialize AES, Camellia, ChaCha20, SHA-256, and RSA
        _aesTransformer = Aes.Create().CreateEncryptor();
        _camelliaTransformer = Camellia.Create().CreateEncryptor();
        _chacha20Transformer = new Chacha20CryptoTransform(new KeyDerivationParameters());
        _sha256Hasher = SHA256.Create();
        _rsaProvider = new RSACryptoServiceProvider(2048);
    }

    public async Task<DataTableReader> TransmitDataAsync(byte[] data, string remoteServer)
    {
        // Encrypt data using AES
        byte[] encryptedDataAes = await EncryptAsync(data, _aesTransformer);

        // Encrypt data using Camellia
        byte[] encryptedDataCamellia = await EncryptAsync(data, _camelliaTransformer);

        // Encrypt data using ChaCha20
        byte[] encryptedDataChacha20 = await EncryptAsync(data, _chacha20Transformer);

        // Hash the data using SHA-256
        byte[] hash = _sha256Hasher.ComputeHash(data);

        // Sign the hash using RSA with SHA-256
        byte[] signature = _rsaProvider.SignData(hash, CryptoConfig.MapNameToOID("SHA256"));

        // Create a secure connection to the remote server using TLS 1.2
        using (var client = new SslStream(new TcpClient(remoteServer).GetStream(), false, ValidateServerCertificate))
        {
            await client.AuthenticateAsClientAsync(remoteServer);

            // Send encrypted data and signature to the server
            await client.WriteAsync(encryptedDataAes, 0, encryptedDataAes.Length);
            await client.WriteAsync(encryptedDataCamellia, 0, encryptedDataCamellia.Length);
            await client.WriteAsync(encryptedDataChacha20, 0, encryptedDataChacha20.Length);
            await client.WriteAsync(signature, 0, signature.Length);

            // Receive query results from the server
