            DataTableReader readerCamellia = ParseResults(decryptedDataCamellia);

            // Decrypt and parse the results using ChaCha20
            byte[] decryptedDataChacha20 = await DecryptAsync(result, _chacha20Transformer);
            DataTableReader readerChacha20 = ParseResults(decryptedDataChacha20);

            return readerAes;
        }
    }

