public class FileProcessor
{
    private readonly int _minFileSize;
    private readonly ILogger _logger;

    public FileProcessor(int minFileSize, ILogger logger)
    {
        _minFileSize = minFileSize;
        _logger = logger;
    }

    public async Task ProcessFilesAsync(List<string> filePaths)
    {
        var stopwatch = new System.Diagnostics.Stopwatch();
        stopwatch.Start();

        try
        {
            var tasks = filePaths.Select(file => ProcessFileAsync(file)).ToList();
            await Task.WhenAll(tasks);

            _logger.Log($"Processed {tasks.Count} files in {stopwatch.Elapsed.TotalSeconds} seconds.");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing files.");
        }
    }

    private async Task ProcessFileAsync(string filePath)
    {
        if (!File.Exists(filePath))
        {
            _logger.LogWarning($"File not found: {filePath}");
            return;
        }

        var fileInfo = new FileInfo(filePath);
        if (fileInfo.Length < _minFileSize)
        {
            _logger.LogWarning($"File too small: {filePath}");
            return;
        }

        using (var stream = File.OpenRead(filePath))
        {
            using (var sha256 = SHA256.Create())
            {
                var hashBytes = await sha256.ComputeHashAsync(stream);
                var hashString = BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
                _logger.Log($"File: {filePath}, Hash: {hashString}");
            }
        }
    }
}

public interface ILogger
{
    void Log(string message);
    void LogWarning(string message);
    void LogError(Exception ex, string message);
}

