const express = require('express');
const mysql = require('mysql2/promise');
const redis = require('redis');
const bluebird = require('bluebird');

// Configure MySQL connection pool
const dbConfig = {
  host: 'localhost',
  user: 'your_user',
  password: 'your_password',
  database: 'your_database'
};

const pool = mysql.createPool(dbConfig);

// Configure Redis client with Bluebird for promise support
redis.Promise = bluebird;
const redisClient = redis.createClient();

async function executeQuery(query, params) {
  const connection = await pool.getConnection();
  try {
    return await connection.query(query, params);
  } finally {
    connection.release();
  }
}

async function updateCache(orderId, orderDetails) {
  await redisClient.set(`order:${orderId}`, JSON.stringify(orderDetails));
}

async function invalidateCache(orderId) {
  await redisClient.del(`order:${orderId}`);
}

async function getLatestOrders(filterOptions = {}) {
  const { startDate, endDate, customerId, productCategory } = filterOptions;
  let query = 'SELECT o.id, o.order_date, c.name AS customer_name, p.name AS product_name FROM orders o JOIN customers c ON o.customer_id = c.id JOIN order_items oi ON o.id = oi.order_id JOIN products p ON oi.product_id = p.id';
  const params = [];

  if (startDate) {
    query += ' WHERE o.order_date >= ?';
    params.push(startDate);
  }

  if (endDate) {
    if (params.length > 0) query += ' AND ';
    query += 'o.order_date <= ?';
    params.push(endDate);
  }

  if (customerId) {
    if (params.length > 0) query += ' AND ';
    query += 'c.id = ?';
    params.push(customerId);
  }

  if (productCategory) {
    if (params.length > 0) query += ' AND ';
    query += 'p.category = ?';
    params.push(productCategory);
  }

  query += ' ORDER BY o.order_date DESC LIMIT 100';

  const [rows] = await executeQuery(query, params);

  for (const row of rows) {
    const cachedOrder = await redisClient.get(`order:${row.id}`);
    if (!cachedOrder) {
      await updateCache(row.id, row);
    }
  }

  return rows;
}

async function handleRequest(req, res) {
  try {
    const filterOptions = req.query;
    const orders = await getLatestOrders(filterOptions);
    res.json(orders);
  } catch (error) {
    console.error(error);
    res.status(500).json({ error: 'Internal Server Error' });
  }
}

const app = express();
app.get('/orders', handleRequest);

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

This code snippet provides a basic implementation of the described functionality using Express.js for the web application framework and MySQL with Redis for caching. It includes functions to execute parameterized SQL queries, update and invalidate cache, retrieve latest orders with filtering options, handle requests, and manage database connections. The actual implementation may require additional error handling, logging, and optimization based on specific requirements and constraints."]

