import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

public class UserAuthenticationService {
    private ConcurrentHashMap<String, String> userProfiles = new ConcurrentHashMap<>();
    private AtomicInteger successfulAuthentications = new AtomicInteger(0);
    private AtomicInteger failedAttempts = new AtomicInteger(0);
    private AtomicLong totalRequestTime = new AtomicLong(0);

    public void generateUserProfiles(int numberOfUsers) {
        for (int i = 0; i < numberOfUsers; i++) {
            String username = "user" + i;
            String email = "user" + i + "@example.com";
            String role = Math.random() > 0.5 ? "admin" : "user";
            userProfiles.put(username, role);
        }
    }

    public boolean authenticateUser(String username, String password) {
        long startTime = System.nanoTime();
        try {
            // Simulate authentication with an external identity provider
            Thread.sleep(100); // Simulating network delay
            if (password.equals("correctPassword") && userProfiles.containsKey(username)) {
                successfulAuthentications.incrementAndGet();
                totalRequestTime.addAndGet(System.nanoTime() - startTime);
                return true;
            } else {
                failedAttempts.incrementAndGet();
                totalRequestTime.addAndGet(System.nanoTime() - startTime);
                return false;
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return false;
        }
    }

    public void logStatistics() {
        int totalRequests = successfulAuthentications.get() + failedAttempts.get();
        double averageTimePerRequest = totalRequestTime.get() / (double) totalRequests / 1_000_000.0;
        System.out.println("Total Successful Authentications: " + successfulAuthentications.get());
        System.out.println("Total Failed Attempts: " + failedAttempts.get());
        System.out.printf("Average Time per Request: %.2f ms%n", averageTimePerRequest);
    }

    public static void main(String[] args) {
        UserAuthenticationService authService = new UserAuthenticationService();
        authService.generateUserProfiles(1000);

        // Simulate concurrent user requests
        for (int i = 0; i < 1000; i++) {
            new Thread(() -> {
                boolean isAuthenticated = authService.authenticateUser("user" + (i % 1000), "correctPassword");
                if (!isAuthenticated) {
                    System.out.println("Authentication failed for user: user" + (i % 1000));
                }
            }).start();
        }

        // Log statistics after some time
        try {
            Thread.sleep(5000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        authService.logStatistics();
    }
}
