use tokio::net::{TcpListener, TcpStream};
use tokio::sync::mpsc;
use tokio::task;
use std::env;
use log::{info, error, debug};
use serde_json::json;

mod args_parser;
mod service_manager;
mod async_tasks;
mod logger;
mod metrics_collector;
mod config_manager;

#[tokio::main]
async fn main() {
    // Initialize logging
    logger::init();

    // Parse command line arguments
    let args = args_parser::parse_args(env::args().collect()).unwrap();

    // Configure service state and start managing services
    let (tx, mut rx) = mpsc::channel(32);
    let manager = service_manager::ServiceManager::new(args, tx.clone());
    task::spawn(async move {
        manager.run().await;
    });

    // Set up TCP listener for incoming connections
    let listener = TcpListener::bind("0.0.0.0:8080").await.unwrap();
    info!("Server listening on port 8080");

    loop {
        match listener.accept().await {
            Ok((stream, addr)) => {
                debug!("New connection from {:?}", addr);
                task::spawn(async move {
                    handle_connection(stream).await;
                });
            }
            Err(e) => error!("Failed to accept incoming connection: {}", e),
        }
    }
}

async fn handle_connection(mut stream: TcpStream) {
    // Handle client requests and delegate tasks
    while let Ok(data) = stream.readable().await {
        match tokio::io::read(&mut stream, &mut [0; 1024]).await {
            Ok(n) if n == 0 => break,
            Ok(_) => async_tasks::handle_task(data).await,
            Err(e) => error!("Failed to read from connection: {}", e),
        }
    }
}
