use std::fs::{self, DirBuilder};
use std::env;
use std::path::Path;
use std::time::{Duration, Instant};
use std::sync::{Arc, Mutex};
use tokio::task;

#[derive(Debug)]
enum Error {
    ConfigError(String),
    IoError(std::io::Error),
    Timeout,
    PermissionError(String),
}

async fn create_directory(
    config: &Config,
    parent_dir: &Path,
    timeout_duration: Duration,
) -> Result<(), Error> {
    let start_time = Instant::now();
    let mut retries = 0;
    const MAX_RETRIES: u32 = 5;

    loop {
        if retries >= MAX_RETRIES {
            return Err(Error::Timeout);
        }

        match create_directory_inner(config, parent_dir) {
            Ok(_) => break,
            Err(Error::IoError(e)) if e.kind() == std::io::ErrorKind::WouldBlock => {
                tokio::time::sleep(Duration::from_millis(100)).await;
                retries += 1;
            }
            Err(e) => return Err(e),
        }
    }

    let end_time = Instant::now();
    log_operation(start_time, end_time, true, None);
    Ok(())
}

async fn create_directory_inner(config: &Config, parent_dir: &Path) -> Result<(), Error> {
    let new_dir_name = config.get_new_directory_name()?;
    let env_var_name = config.get_env_variable_name()?;
    let permission_mask = config.get_permission_mask()?;

    if !parent_dir.exists() || !parent_dir.is_dir() {
        return Err(Error::IoError(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            "Parent directory does not exist or is not a directory",
        )));
    }

    let new_dir_path = parent_dir.join(&new_dir_name);
    if new_dir_path.exists() {
        return Err(Error::IoError(std::io::Error::new(
            std::io::ErrorKind::AlreadyExists,
            "Directory already exists",
        )));
    }

    DirBuilder::new()
        .mode(permission_mask)
        .create(&new_dir_path)?;

    env::set_var(env_var_name, new_dir_path.to_str().unwrap());

    Ok(())
}

