import yaml
import json
import os
import sys
from typing import Any, Dict, Optional

class ConfigManager:
    def __init__(self):
        self.config = {}
        self.registered_types = {}

    def register_type(self, type_name: str, validator):
        self.registered_types[type_name] = validator

    def load_from_yaml(self, file_path: str):
        with open(file_path, 'r') as file:
            data = yaml.safe_load(file)
            self.update_config(data)

    def load_from_json(self, file_path: str):
        with open(file_path, 'r') as file:
            data = json.load(file)
            self.update_config(data)

    def load_from_env(self):
        for key, value in os.environ.items():
            if key.startswith('APP_'):
                self.config[key] = value

    def load_from_args(self):
        for i in range(1, len(sys.argv), 2):
            key = sys.argv[i]
            value = sys.argv[i + 1]
            self.config[key] = value

    def load_from_api(self, url: str):
        # Implement API loading logic here
        pass

    def update_config(self, new_data: Dict[str, Any]):
        for key, value in new_data.items():
            if isinstance(value, dict):
                if key not in self.config:
                    self.config[key] = {}
                self.update_config(value)
            else:
                self.config[key] = self.validate_value(key, value)

    def validate_value(self, key: str, value: Any) -> Any:
        type_name = type(value).__name__
        validator = self.registered_types.get(type_name)
        if validator and not validator(value):
            raise ValueError(f"Invalid value for {key}: {value}")
        return value

    def get_config(self, key: str) -> Optional[Any]:
        return self.config.get(key)

# Example usage
config_manager = ConfigManager()
config_manager.register_type('int', lambda x: isinstance(x, int))
config_manager.load_from_yaml('config.yaml')
config_manager.load_from_json('config.json')
config_manager.load_from_env()
config_manager.load_from_args()
value = config_manager.get_config('database_url')
print(value)
