#define MAX_MEMORY_BUDGET 1024 * 1024 // 1 MB

typedef struct {
    int value;
} record;

typedef struct {
    time_t timestamp;
} timestamp;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void log_allocation(time_t start_time, time_t end_time, size_t size) {
    printf("Allocation took %ld seconds and used %zu bytes\n", difftime(end_time, start_time), size);
}

record* create_record(int value) {
    record* rec = allocate_memory(sizeof(record));
    rec->value = value;
    return rec;
}

timestamp* get_current_timestamp() {
    timestamp* ts = allocate_memory(sizeof(timestamp));
    time(&ts->timestamp);
    return ts;
}

void initialize_complex_structure(long* offsets, int* keys, record** records1, record** records2, timestamp** timestamps) {
    time_t start_time = time(NULL);

    // Allocate memory for arrays
    size_t num_elements = 10; // Example number of elements

    offsets = allocate_memory(num_elements * sizeof(long));
    keys = allocate_memory(num_elements * sizeof(int));

    record* temp_records1[num_elements];
    record* temp_records2[num_elements];

    timestamps = allocate_memory(num_elements * sizeof(timestamp*));

    for (size_t i = 0; i < num_elements; ++i) {
        offsets[i] = i * 8; // Example offset calculation
        keys[i] = i;

        temp_records1[i] = create_record(i);
        temp_records2[i] = create_record(i + 1);

        timestamps[i] = get_current_timestamp();
    }

    records1 = allocate_memory(num_elements * sizeof(record*));
    records2 = allocate_memory(num_elements * sizeof(record*));

    for (size_t i = 0; i < num_elements; ++i) {
        records1[i] = temp_records1[i];
        records2[i] = temp_records2[i];
    }

    time_t end_time = time(NULL);
    log_allocation(start_time, end_time, num_elements * sizeof(record*) + num_elements * sizeof(timestamp*));
}

int main() {
    long* offsets;
    int* keys;
    record** records1;
    record** records2;
    timestamp** timestamps;

    initialize_complex_structure(offsets, keys, records1, records2, timestamps);

    // Free allocated memory
    for (size_t i = 0; i < 10; ++i) {
        free(records1[i]);
        free(records2[i]);
        free(timestamps[i]);
    }
    free(offsets);
    free(keys);
    free(records1);
    free(records2);
    free(timestamps);

    return 0;
}
