import os
import json
from threading import Lock

class DatabaseConnectionPool:
    def __init__(self, max_pool_size, connection_timeout):
        self.max_pool_size = max_pool_size
        self.connection_timeout = connection_timeout
        self.pool = []
        self.lock = Lock()

    def allocate_connection(self):
        with self.lock:
            if len(self.pool) < self.max_pool_size:
                # Simulate connection allocation
                new_connection = f"Connection-{len(self.pool)}"
                self.pool.append(new_connection)
                return new_connection
            else:
                raise Exception("Connection pool is full")

    def release_connection(self, connection):
        with self.lock:
            if connection in self.pool:
                self.pool.remove(connection)

def configureDatabaseConnection():
    config_file = "db_config.json"
    env_var_name = "DB_CONFIG_PATH"

    if os.getenv(env_var_name):
        config_path = os.getenv(env_var_name)
    else:
        with open(config_file, 'w') as f:
            json.dump({"max_pool_size": 10, "connection_timeout": 30}, f)
        config_path = os.path.abspath(config_file)
        os.environ[env_var_name] = config_path

    with open(config_path, 'r') as f:
        config = json.load(f)

    pool = DatabaseConnectionPool(config['max_pool_size'], config['connection_timeout'])

    # Simulate query execution
    for _ in range(5):
        connection = pool.allocate_connection()
        print(f"Executing query on {connection}")
        pool.release_connection(connection)

def create_config_file(file_name, env_var_name):
    if os.getenv(env_var_name):
        config_path = os.getenv(env_var_name)
    else:
        with open(file_name, 'w') as f:
            json.dump({"max_pool_size": 10, "connection_timeout": 30}, f)
        config_path = os.path.abspath(file_name)
        os.environ[env_var_name] = config_path

# Example usage
create_config_file("db_config.json", "DB_CONFIG_PATH")
configureDatabaseConnection()
