#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PACKET_SIZE 1024
#define PAYLOAD_RANGE_MIN 1
#define PAYLOAD_RANGE_MAX 256

typedef struct {
    char source_ip[16];
    char destination_ip[16];
    int protocol_type;
    int packet_length;
    unsigned char payload[MAX_PACKET_SIZE];
} NetworkPacket;

unsigned short compute_checksum(unsigned char *data, int length) {
    unsigned int sum = 0;
    while (length--) {
        sum += *data++;
    }
    return (sum >> 16) + (sum & 0xFFFF);
}

int validate_payload_size(int size) {
    if (size < PAYLOAD_RANGE_MIN || size > PAYLOAD_RANGE_MAX) {
        fprintf(stderr, "Invalid payload size. Must be between %d and %d.\n", PAYLOAD_RANGE_MIN, PAYLOAD_RANGE_MAX);
        return 0;
    }
    return 1;
}

int initialize_network_packet(NetworkPacket *packet) {
    if (!packet) {
        fprintf(stderr, "Error: Invalid packet pointer.\n");
        return -1;
    }

    printf("Enter source IP (e.g., 192.168.1.1): ");
    fgets(packet->source_ip, sizeof(packet->source_ip), stdin);
    packet->source_ip[strcspn(packet->source_ip, "\n")] = '\0';

    printf("Enter destination IP (e.g., 192.168.1.2): ");
    fgets(packet->destination_ip, sizeof(packet->destination_ip), stdin);
    packet->destination_ip[strcspn(packet->destination_ip, "\n")] = '\0';

    printf("Enter protocol type: ");
    scanf("%d", &packet->protocol_type);

    int payload_size;
    do {
        printf("Enter packet length (max %d): ", MAX_PACKET_SIZE);
        scanf("%d", &payload_size);
    } while (!validate_payload_size(payload_size));

    packet->packet_length = payload_size;

    srand(time(NULL));
    for (int i = 0; i < payload_size; i++) {
        packet->payload[i] = rand() % 256;
    }

    packet->payload[payload_size] = '\0'; // Null-terminate the payload

    return 0;
}

void free_network_packet(NetworkPacket *packet) {
    if (packet) {
        free(packet);
    }
}

int main() {
    NetworkPacket *packet = (NetworkPacket *)malloc(sizeof(NetworkPacket));
    if (!packet) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1;
    }

    printf("Initializing network packet...\n");
    if (initialize_network_packet(packet) != 0) {
        free_network_packet(packet);
        return -1;
    }

    printf("Network packet initialized successfully.\n");

    // Perform checksum validation
    unsigned short computed_checksum = compute_checksum(packet->payload, packet->packet_length);
    printf("Computed Checksum: %d\n", computed_checksum);

    // Free allocated memory
    free_network_packet(packet);

    return 0;
}
