#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_TASKS 1000
#define TASK_ID_SIZE 20

typedef struct {
    char timestamp[20];
    char task_id[TASK_ID_SIZE];
    int priority;
    int execution_time;
} Task;

typedef struct {
    int parent[MAX_TASKS];
    int rank[MAX_TASKS];
} UnionFind;

void initializeUnionFind(UnionFind *uf, int n) {
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void unionSets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int countDisjointSets(UnionFind *uf, int n) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        if (uf->parent[i] == i)
            count++;
    }
    return count;
}

void readTasksFromService(Task tasks[], int *taskCount, UnionFind *uf) {
    // Simulate reading from a remote service
    FILE *file = fopen("tasks.txt", "r");
    if (!file) {
        fprintf(stderr, "Failed to open file\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        Task task;
        sscanf(line, "%s %s %d %d", task.timestamp, task.task_id, &task.priority, &task.execution_time);
        tasks[*taskCount] = task;
        (*taskCount)++;
        unionSets(uf, atoi(task.task_id), atoi(task.task_id));
    }

    fclose(file);
}

int main() {
    Task tasks[MAX_TASKS];
    int taskCount = 0;
    UnionFind uf;

    initializeUnionFind(&uf, MAX_TASKS);

    readTasksFromService(tasks, &taskCount, &uf);

    printf("Number of disjoint sets: %d\n", countDisjointSets(&uf, taskCount));

    return 0;
}
