#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

u_char* resolve_dns(const char* hostname) {
    struct addrinfo hints, *res, *p;
    u_char ip[INET6_ADDRSTRLEN];
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char* ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ip, sizeof ip);
        printf("  %s: %s\n", ipver, ip);

        freeaddrinfo(res); // all done with this structure
        return (u_char*)ip;
    }

    return NULL;
}

record* allocate_records(int count) {
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % 1000; // Random value between 0 and 999
    }
    return records;
}

void free_records(record* records, int count) {
    free(records);
}

int main() {
    const char* hostname = "example.com";
    u_char* ip_address = resolve_dns(hostname);
    if (ip_address) {
        printf("IP Address: %s\n", ip_address);
    } else {
        printf("Failed to resolve DNS for %s\n", hostname);
    }

    int count = 5;
    record* records = allocate_records(count);
    if (records) {
        printf("Records allocated and initialized:\n");
        for (int i = 0; i < count; i++) {
            printf("Record %d: %d\n", i, records[i].value);
        }
        free_records(records, count);
    }

    return 0;
}
