typedef struct {
    int value;
} record;

void allocate_and_initialize(int length, int min_value, int max_value) {
    if (length <= 0 || min_value >= max_value) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
    }

    long* offset_array = (long*)malloc(length * sizeof(long));
    int* key_array = (int*)malloc(length * sizeof(int));
    record* records = (record*)malloc(length * sizeof(record));

    if (!offset_array || !key_array || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    srand(time(NULL));
    int current_value = 0;

    for (int i = 0; i < length; ++i) {
        key_array[i] = i + 1;
        current_value += key_array[i];
        offset_array[i] = current_value;

        int random_value;
        do {
            random_value = min_value + rand() % (max_value - min_value + 1);
        } while (random_value == records[0].value); // Assuming the first record is already set

        records[i].value = random_value;
    }

    // Free allocated memory
    free(offset_array);
    free(key_array);
    free(records);
}

int main() {
    int length = 10;
    int min_value = 10;
    int max_value = 100;

    allocate_and_initialize(length, min_value, max_value);

    return 0;
}
