    struct in_addr gateway;
} NetworkInterface;

int parse_config_file(const char* filename, NetworkInterface** interfaces, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1; // File not found

    *count = 0;
    while (*count < MAX_INTERFACES && fgets(buffer, sizeof(buffer), file)) {
        // Parse each line for interface settings
        NetworkInterface iface;
        if (sscanf(buffer, "%s %s %s %s", iface.interface_name, ip_str, subnet_mask_str, gateway_str) == 4) {
