            if (!inet_pton(AF_INET, subnet_mask_str, &iface.subnet_mask)) return -3; // Invalid subnet mask
            if (!inet_pton(AF_INET, gateway_str, &iface.gateway)) return -4; // Invalid gateway

            (*interfaces)[*count] = iface;
            (*count)++;
        }
    }

    fclose(file);
    return 0;
}

int find_highest_priority_interface(NetworkInterface* interfaces, int count) {
    if (count == 0) return -1; // No valid interfaces found
    int highest_index = 0;
    for (int i = 1; i < count; i++) {
        if (memcmp(&interfaces[i].ip_address.s_addr, &interfaces[highest_index].ip_address.s_addr, sizeof(uint32_t)) > 0) {
            highest_index = i;
        }
    }
    return highest_index;
}

void initialize_records(record* records, int count, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

