    u_char ip_address[4];
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    struct sockaddr_in* ipv4 = (struct sockaddr_in*)res->ai_addr;
    memcpy(ip_address, &(ipv4->sin_addr), sizeof(u_char)*4);

    freeaddrinfo(res);
    return ip_address;
}

int main() {
    NetworkInterface* interfaces = malloc(MAX_INTERFACES * sizeof(NetworkInterface));
    int count;

    if (parse_config_file("network.conf", &interfaces, &count) != 0) {
        fprintf(stderr, "Failed to parse configuration file.\n");
        free(interfaces);
        return -1;
    }

    int highest_index = find_highest_priority_interface(interfaces, count);
    if (highest_index == -1) {
        printf("No valid interfaces found.\n");
    } else {
        printf("Highest priority interface: %s\n", interfaces[highest_index].interface_name);
