#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define LOAD_FACTOR 0.75

typedef struct {
    int *keys;
    int *values;
    int size;
    int capacity;
} RecordSet;

RecordSet* create_record_set() {
    RecordSet *set = (RecordSet*)malloc(sizeof(RecordSet));
    if (!set) {
        fprintf(stderr, "Memory allocation failed for RecordSet\n");
        exit(EXIT_FAILURE);
    }
    set->keys = (int*)malloc(INITIAL_CAPACITY * sizeof(int));
    set->values = (int*)malloc(INITIAL_CAPACITY * sizeof(int));
    if (!set->keys || !set->values) {
        fprintf(stderr, "Memory allocation failed for keys or values\n");
        free(set);
        exit(EXIT_FAILURE);
    }
    set->size = 0;
    set->capacity = INITIAL_CAPACITY;
    return set;
}

void resize_record_set(RecordSet *set) {
    int new_capacity = set->capacity * 2;
    int *new_keys = (int*)realloc(set->keys, new_capacity * sizeof(int));
    int *new_values = (int*)realloc(set->values, new_capacity * sizeof(int));
    if (!new_keys || !new_values) {
        fprintf(stderr, "Memory reallocation failed\n");
        free(new_keys);
        free(new_values);
        exit(EXIT_FAILURE);
    }
    set->keys = new_keys;
    set->values = new_values;
    set->capacity = new_capacity;
}

void add_record(RecordSet *set, int key) {
    if (set->size >= set->capacity * LOAD_FACTOR) {
        resize_record_set(set);
    }
    set->keys[set->size] = key;
    set->values[set->size++] = rand() % 100; // Random value between 0 and 99
}

void free_record_set(RecordSet *set) {
    free(set->keys);
    free(set->values);
    free(set);
}

int main() {
    srand(time(NULL));
    RecordSet *record_set = create_record_set();

    int key;
    while (scanf("%d", &key) != EOF) {
        add_record(record_set, key);
    }

    // Perform operations on record_set...

    free_record_set(record_set);
    return 0;
}
