#define MAX_RECORDS 100000

typedef struct {
    int value;
} record;

void* manage_memory(void* arg) {
    int num_records = *(int*)arg;
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return NULL;
    }

    int* keys = (int*)calloc(num_records, sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        free(offsets);
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1000;
    }

    // Simulate some operations
    for (int i = 0; i < num_records; i++) {
        offsets[i] = keys[i];
    }

    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

void* reset_records(void* arg) {
    int num_records = *(int*)arg;
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return NULL;
    }

    srand(time(NULL) + 1);
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1000;
    }

    free(records);

    return NULL;
}

void* monitor_memory(void* arg) {
    int num_records = *(int*)arg;
    long total_memory = (num_records * sizeof(long)) + (num_records * sizeof(int)) + (num_records * sizeof(record));
    printf("Total memory usage: %ld bytes\n", total_memory);

    return NULL;
}

int main() {
    int num_records;
    printf("Enter the number of records (1-%d): ", MAX_RECORDS);
    scanf("%d", &num_records);

    if (num_records <= 0 || num_records > MAX_RECORDS) {
        fprintf(stderr, "Invalid input. Please enter a positive integer within the range.\n");
        return 1;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, manage_memory, &num_records) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread_id, NULL);

    pthread_t reset_thread_id;
    if (pthread_create(&reset_thread_id, NULL, reset_records, &num_records) != 0) {
        fprintf(stderr, "Failed to create reset thread\n");
        return 1;
    }

    pthread_join(reset_thread_id, NULL);

    pthread_t monitor_thread_id;
    if (pthread_create(&monitor_thread_id, NULL, monitor_memory, &num_records) != 0) {
        fprintf(stderr, "Failed to create monitor thread\n");
        return 1;
    }

    pthread_join(monitor_thread_id, NULL);

    return 0;
}
