#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 1024

typedef struct {
    int value;
    char filename[256];
} Record;

typedef struct {
    long offset;
    int key;
    Record record;
} Element;

typedef struct {
    int* parent;
    int* rank;
    size_t capacity;
    size_t size;
} UnionFind;

UnionFind* create_union_find(size_t initial_capacity) {
    UnionFind* uf = (UnionFind*)malloc(sizeof(UnionFind));
    if (!uf) {
        fprintf(stderr, "Memory allocation failed for Union-Find structure.\n");
        return NULL;
    }
    uf->parent = (int*)calloc(initial_capacity, sizeof(int));
    uf->rank = (int*)calloc(initial_capacity, sizeof(int));
    if (!uf->parent || !uf->rank) {
        fprintf(stderr, "Memory allocation failed for Union-Find arrays.\n");
        free(uf);
        return NULL;
    }
    uf->capacity = initial_capacity;
    uf->size = 0;
    for (size_t i = 0; i < initial_capacity; ++i) {
        uf->parent[i] = i;
    }
    return uf;
}

void destroy_union_find(UnionFind* uf) {
    free(uf->parent);
    free(uf->rank);
    free(uf);
}

int find(UnionFind* uf, int x) {
    if (uf->parent[x] != x) {
        uf->parent[x] = find(uf, uf->parent[x]);
    }
    return uf->parent[x];
}

void union_sets(UnionFind* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);
    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int main() {
    size_t capacity = INITIAL_CAPACITY;
    Element* elements = (Element*)malloc(capacity * sizeof(Element));
    if (!elements) {
        fprintf(stderr, "Memory allocation failed for elements array.\n");
        return 1;
    }

    UnionFind* uf = create_union_find(capacity);
    if (!uf) {
        free(elements);
        return 1;
    }

    int max_key = INT_MIN;
    size_t longest_filename_length = 0;

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        long offset;
        int key;
        Record record;
        if (sscanf(buffer, "%ld %d %s", &offset, &key, record.filename) != 3) {
            fprintf(stderr, "Invalid input format.\n");
            continue;
        }

        if (key > max_key) {
            max_key = key;
        }
        if (strlen(record.filename) > longest_filename_length) {
            longest_filename_length = strlen(record.filename);
        }

        if (uf->size >= capacity) {
            size_t new_capacity = capacity * 2;
            Element* new_elements = (Element*)realloc(elements, new_capacity * sizeof(Element));
            if (!new_elements) {
                fprintf(stderr, "Memory reallocation failed for elements array.\n");
                destroy_union_find(uf);
                free(elements);
                return 1;
            }
            elements = new_elements;
            capacity = new_capacity;

            int* new_parent = (int*)realloc(uf->parent, new_capacity * sizeof(int));
            if (!new_parent) {
                fprintf(stderr, "Memory reallocation failed for Union-Find parent array.\n");
                destroy_union_find(uf);
                free(elements);
                return 1;
            }
            uf->parent = new_parent;

            int* new_rank = (int*)realloc(uf->rank, new_capacity * sizeof(int));
            if (!new_rank) {
                fprintf(stderr, "Memory reallocation failed for Union-Find rank array.\n");
                destroy_union_find(uf);
                free(elements);
                return 1;
            }
            uf->rank = new_rank;

            for (size_t i = capacity / 2; i < new_capacity; ++i) {
                uf->parent[i] = i;
            }

            capacity = new_capacity;
        }

        elements[uf->size].offset = offset;
        elements[uf->size].key = key;
        elements[uf->size].record = record;
        uf->size++;
    }

    printf("Longest filename length: %zu\n", longest_filename_length);
