#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_KEYS 1000
#define VALUE_RANGE 1000

typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    Record *records;
    int size;
    int capacity;
    pthread_mutex_t lock;
} DynamicSet;

DynamicSet* create_dynamic_set() {
    DynamicSet *set = (DynamicSet*)malloc(sizeof(DynamicSet));
    if (!set) {
        perror("Failed to allocate memory for dynamic set");
        exit(EXIT_FAILURE);
    }
    set->records = NULL;
    set->size = 0;
    set->capacity = 0;
    pthread_mutex_init(&set->lock, NULL);
    return set;
}

void destroy_dynamic_set(DynamicSet *set) {
    if (set->records) {
        free(set->records);
    }
    pthread_mutex_destroy(&set->lock);
    free(set);
}

void resize_dynamic_set(DynamicSet *set, int new_capacity) {
    Record *new_records = (Record*)realloc(set->records, new_capacity * sizeof(Record));
    if (!new_records) {
        perror("Failed to reallocate memory for dynamic set");
        exit(EXIT_FAILURE);
    }
    set->records = new_records;
    set->capacity = new_capacity;
}

void add_record(DynamicSet *set, int key, int value) {
    pthread_mutex_lock(&set->lock);
    if (set->size == set->capacity) {
        resize_dynamic_set(set, set->capacity ? set->capacity * 2 : 1);
    }
    set->records[set->size].key = key;
    set->records[set->size].value = value;
    set->size++;
    pthread_mutex_unlock(&set->lock);
}

void* initialize_values(void *arg) {
    DynamicSet *set = (DynamicSet*)arg;
    srand(time(NULL));
    for (int i = 0; i < set->size; i++) {
        set->records[i].value = rand() % VALUE_RANGE;
    }
    return NULL;
}

void initialize_dynamic_set(DynamicSet *set) {
    int key;
    while (scanf("%d", &key) != EOF) {
        add_record(set, key, 0);
    }
    pthread_t thread;
    if (pthread_create(&thread, NULL, initialize_values, set) != 0) {
        perror("Failed to create thread for value initialization");
        exit(EXIT_FAILURE);
    }
    pthread_join(thread, NULL);
}

int main() {
    DynamicSet *set = create_dynamic_set();
    initialize_dynamic_set(set);

    // Perform operations on the dynamic set...

    destroy_dynamic_set(set);
    return 0;
}
