    }
}

// Caching mechanism to minimize redundant computations
typedef struct {
    double input;
    double result;
} cacheEntry;

cacheEntry* cache = NULL;
int cacheSize = 0;

double getCachedResult(double input) {
    for (int i = 0; i < cacheSize; ++i) {
        if (cache[i].input == input) {
            return cache[i].result;
        }
    }
    return -1.0; // Cache miss
}

void addToCache(double input, double result) {
    if (cacheSize >= 100) { // Example size limit for simplicity
        free(cache);
        cache = NULL;
        cacheSize = 0;
    }
    cache = realloc(cache, (cacheSize + 1) * sizeof(cacheEntry));
    cache[cacheSize].input = input;
    cache[cacheSize].result = result;
    ++cacheSize;
}

double computeWithCache(double x, double amplitude, double frequency) {
    double cachedResult = getCachedResult(x);
    if (cachedResult != -1.0) {
        return cachedResult;
    }
    double result = sinusoidalWave(x, amplitude, frequency);
    addToCache(x, result);
    return result;
}

