#include <time.h>

#define MAX_ELEMENTS 10000000

typedef struct {
    int value;
} record;

int find(int *parent, int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void unionSet(int *parent, int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset)
        parent[xset] = yset;
}

int areDisjoint(int *parent, int x, int y) {
    return find(parent, x) != find(parent, y);
}

void processNetworkStream() {
    int *keys = (int *)malloc(MAX_ELEMENTS * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys array\n");
        return;
    }

    record *records = (record *)malloc(MAX_ELEMENTS * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records array\n");
        free(keys);
        return;
    }

    int parent[MAX_ELEMENTS];
    for (int i = 0; i < MAX_ELEMENTS; i++)
        parent[i] = -1;

    // Simulate reading from network stream
    int count = 0;
    while (count < MAX_ELEMENTS) {
        keys[count++] = rand() % MAX_ELEMENTS;
    }

    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < count - 1; i++) {
        start = clock();
        if (areDisjoint(parent, keys[i], keys[i + 1])) {
            unionSet(parent, keys[i], keys[i + 1]);
        }
        end = clock();
        cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
        printf("Time taken for disjointness test %d: %.2f ms\n", i, cpu_time_used * 1000);
    }

    free(keys);
    free(records);
}

int main() {
    srand(time(0));
    processNetworkStream();
    return 0;
}
