#define MAX_RECORDS 1000

typedef struct {
    double temperature;
    char timestamp[20];
    char unit[5];
} TemperatureRecord;

typedef struct {
    TemperatureRecord record;
    double averageTemperature;
} Weather;

double calculateAverage(Weather *weatherArray, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += weatherArray[i].record.temperature;
    }
    return sum / count;
}

void* processTemperature(void* arg) {
    Weather *weatherArray = (Weather*)arg;
    int count = 0;

    while (1) {
        TemperatureRecord record;
        if (scanf("%lf %s %s", &record.temperature, record.timestamp, record.unit) != 3) {
            break; // End of input
        }

        weatherArray[count].record = record;
        weatherArray[count].averageTemperature = calculateAverage(weatherArray, count + 1);
        count++;
    }

    return NULL;
}

void printMaxTemperature(Weather *weatherArray, int count) {
    double maxTemp = -999.0;
    char maxTimestamp[20];
    char maxUnit[5];

    for (int i = 0; i < count; i++) {
        if (weatherArray[i].record.temperature > maxTemp) {
            maxTemp = weatherArray[i].record.temperature;
            strcpy(maxTimestamp, weatherArray[i].record.timestamp);
            strcpy(maxUnit, weatherArray[i].record.unit);
        }
    }

    printf("Max Temperature: %.2f %s at %s\n", maxTemp, maxUnit, maxTimestamp);
}

int main() {
    Weather *weatherArray = (Weather*)malloc(MAX_RECORDS * sizeof(Weather));
    if (!weatherArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, processTemperature, weatherArray) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        free(weatherArray);
        return 1;
    }

    pthread_join(thread, NULL);

    int count = 0;
    while (weatherArray[count].record.temperature != -999.0) {
        count++;
    }

    printMaxTemperature(weatherArray, count);

    free(weatherArray);
    return 0;
}
