#define MAX_SIZE 1024

typedef struct node {
    double value;
    struct node* next;
} Node;

typedef struct entry {
    char* str;
    int value;
    struct entry* next;
} Entry;

int manage_memory(double** weights, char*** names, Node** nodes, Entry** entries) {
    int weight_size, name_size;
    printf("Enter the size of the double array: ");
    scanf("%d", &weight_size);
    if (weight_size > MAX_SIZE) {
        fprintf(stderr, "Size exceeds maximum limit.\n");
        return -1;
    }

    *weights = (double*)calloc(weight_size, sizeof(double));
    if (*weights == NULL) {
        fprintf(stderr, "Memory allocation failed for weights.\n");
        return -1;
    }

    printf("Enter the size of the char array: ");
    scanf("%d", &name_size);
    if (name_size > MAX_SIZE || name_size * 64 > MAX_SIZE) {
        fprintf(stderr, "Size exceeds maximum limit.\n");
        free(*weights);
        return -1;
    }

    *names = (char**)calloc(name_size, sizeof(char*));
    if (*names == NULL) {
        fprintf(stderr, "Memory allocation failed for names.\n");
        free(*weights);
        return -1;
    }

    int total_nodes = weight_size + name_size;
    *nodes = (Node*)malloc(total_nodes * sizeof(Node));
    if (*nodes == NULL) {
        fprintf(stderr, "Memory allocation failed for nodes.\n");
        free(*weights);
        free(*names);
        return -1;
    }

    *entries = (Entry*)malloc(name_size * sizeof(Entry));
    if (*entries == NULL) {
        fprintf(stderr, "Memory allocation failed for entries.\n");
        free(*weights);
        free(*names);
        free(*nodes);
        return -1;
    }

    // Initialize nodes
    double total_weight = 0.0;
    for (int i = 0; i < weight_size; ++i) {
        printf("Enter weight %d: ", i + 1);
        scanf("%lf", &(*weights)[i]);
        total_weight += (*weights)[i];
    }
    double average_weight = total_weight / weight_size;
    for (int i = 0; i < total_nodes; ++i) {
        (*nodes)[i].value = round(average_weight * 100) / 100;
        (*nodes)[i].next = NULL;
    }

    // Initialize names and entries
    char buffer[65];
    for (int i = 0; i < name_size; ++i) {
        printf("Enter name %d: ", i + 1);
        scanf("%s", buffer);
        (*names)[i] = (char*)malloc(65 * sizeof(char));
        if ((*names)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for name %d.\n", i + 1);
            // Cleanup previously allocated memory
            free(*weights);
            free(*names);
            free(*nodes);
            free(*entries);
            return -1;
        }
        strcpy((*names)[i], buffer);

        (*entries)[i].str = (char*)malloc(65 * sizeof(char));
        if ((*entries)[i].str == NULL) {
            fprintf(stderr, "Memory allocation failed for entry %d string.\n", i + 1);
            // Cleanup previously allocated memory
            free(*weights);
            free(*names);
            free(*nodes);
            free(*entries);
            return -1;
        }
        strcpy((*entries)[i].str, buffer);

        (*entries)[i].value = i + 1;
        (*entries)[i].next = NULL;

        if (i > 0) {
            (*entries)[i - 1].next = &(*entries)[i];
        }
    }

    return total_nodes + name_size;
}

void print_linked_list(Entry* head) {
    Entry* current = head;
    while (current != NULL) {
        printf("String: %s, Value: %d\n", current->str, current->value);
        current = current->next;
    }
}

int main() {
    double* weights = NULL;
    char** names = NULL;
    Node* nodes = NULL;
    Entry* entries = NULL;

    int total_allocated = manage_memory(&weights, &names, &nodes, &entries);
    if (total_allocated >= 0) {
        printf("Total nodes and entries allocated: %d\n", total_allocated);

        // Print linked list for debugging
        print_linked_list(entries);

        // Cleanup
        free(weights);
        for (int i = 0; i < name_size; ++i) {
            free(names[i]);
            free(entries[i].str);
        }
        free(names);
        free(nodes);
        free(entries);
    }

    return 0;
}
