// C function to parse binary sensor data

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int id;
    float value;
} SensorReading;

int parseSensorData(const char* filePath, SensorReading** readings) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        perror("Failed to open sensor data file");
        return -1; // File loading error
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    *readings = (SensorReading*)malloc(fileSize / sizeof(SensorReading));
    if (!*readings) {
        perror("Failed to allocate memory for sensor readings");
        fclose(file);
        return -2; // Memory allocation failure
    }

    size_t bytesRead = fread(*readings, sizeof(SensorReading), fileSize / sizeof(SensorReading), file);
    fclose(file);

    if (bytesRead != fileSize / sizeof(SensorReading)) {
        free(*readings);
        perror("Failed to read all sensor data");
        return -3; // Partial read error
    }

    return bytesRead;
}

// Example usage:
int main() {
    SensorReading* readings = NULL;
    int count = parseSensorData("sensor_data.bin", &readings);

    if (count >= 0) {
        printf("Parsed %d sensor readings\n", count);
        // Process the readings
        free(readings);
    }

    return 0;
}
