#define MAX_RECORDS 1000
#define MAX_INPUT_SIZE 256

typedef struct {
    int value;
} record;

void* process_data(void* arg) {
    // Thread-local storage for per-thread data
    static pthread_key_t key;
    if (pthread_once(&key_init, init_thread_local_storage) != 0) {
        perror("Failed to initialize thread-local storage");
        return NULL;
    }

    int* offsets = (int*)pthread_getspecific(key);
    record* records = (record*)malloc(sizeof(record) * MAX_RECORDS);
    if (!records) {
        perror("Memory allocation failed for records");
        return NULL;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i].value = rand() % 1000;
    }

    // Read integers from input and store in offsets array
    char input[MAX_INPUT_SIZE];
    if (fgets(input, sizeof(input), stdin)) {
        int count = sscanf(input, "%d", &offsets[0]);
        for (int i = 1; i < count && i < MAX_RECORDS; ++i) {
            offsets[i] = offsets[i - 1] + rand() % 10;
        }
    }

    // Find and print the largest integer
    int max_value = records[offsets[0]].value;
    for (int i = 1; i < count && i < MAX_RECORDS; ++i) {
        if (records[offsets[i]].value > max_value) {
            max_value = records[offsets[i]].value;
        }
    }
    printf("Largest integer: %d\n", max_value);

    // Free allocated memory
    free(records);
    return NULL;
}

void init_thread_local_storage() {
    pthread_key_create(&key, free_thread_local_storage);
}

void free_thread_local_storage(void* ptr) {
    free(ptr);
}

int main(int argc, char* argv[]) {
    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, process_data, NULL) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    return EXIT_SUCCESS;
}
