const fs = require('fs');
const path = require('path');

async function readFilesByExtension(directory, extension) {
  const files = await fs.promises.readdir(directory);
  const filePromises = files.filter(file => path.extname(file).toLowerCase() === `.${extension}`)
    .map(file => fs.promises.readFile(path.join(directory, file), 'utf8'));

  return Promise.all(filePromises);
}

readFilesByExtension('/path/to/directory', 'txt')
  .then(contents => {
    console.log('File contents:', contents);
  })
  .catch(error => {
    console.error('Error reading files:', error);
  });
