#define MAX_TRANSACTIONS 1000
#define DEFAULT_TIMEFRAME 60
#define DEFAULT_REJECT_LIMIT 1000.0

typedef struct {
    double amount;
    time_t timestamp;
} transaction;

void log_message(const char *message) {
    printf("%s\n", message);
}

int read_transactions(int sockfd, transaction **transactions, int *count, int timeframe, double reject_limit) {
    // Simulate reading transactions from a network socket
    // This is a placeholder for actual network communication code
    // For demonstration purposes, we'll generate random transactions
    srand(time(NULL));
    *count = 0;
    while (*count < MAX_TRANSACTIONS && *count < timeframe) {
        transaction t;
        t.amount = (double)(rand() % 1000);
        t.timestamp = time(NULL) - timeframe + *count;
        if (t.amount > reject_limit) continue;
        transactions[*count] = malloc(sizeof(transaction));
        memcpy(transactions[*count], &t, sizeof(transaction));
        (*count)++;
    }
    return *count;
}

void print_total_amount(transaction **transactions, int count, time_t start_time, time_t end_time) {
    double total = 0.0;
    for (int i = 0; i < count; i++) {
        if (transactions[i]->timestamp >= start_time && transactions[i]->timestamp <= end_time) {
            total += transactions[i]->amount;
        }
    }
    printf("Total amount processed between %ld and %ld: %.2f\n", start_time, end_time, total);
}

int main(int argc, char *argv[]) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        log_message("Error opening socket");
        return -1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(8080);
    inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        log_message("Error connecting to server");
        close(sockfd);
        return -1;
    }

    int timeframe = DEFAULT_TIMEFRAME;
    double reject_limit = DEFAULT_REJECT_LIMIT;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            timeframe = atoi(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-r") == 0 && i + 1 < argc) {
            reject_limit = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [-t timeframe] [-r reject_limit]\n", argv[0]);
            return 0;
        }
    }

    transaction *transactions[MAX_TRANSACTIONS];
    int count = read_transactions(sockfd, transactions, &count, timeframe, reject_limit);

    time_t start_time = time(NULL) - timeframe;
    print_total_amount(transactions, count, start_time, time(NULL));

    for (int i = 0; i < count; i++) {
        free(transactions[i]);
    }

    close(sockfd);
    return 0;
}
