// Define necessary structures
typedef struct {
    int identifier;
    double value;
    char label;
} item;

typedef struct {
    char source_path[256];
    time_t timestamp;
} metadata;

typedef struct record {
    int key;
    double measurement;
    char status;
    item* data_item;
    metadata* meta_data;
} record;

// Function to dynamically allocate memory and initialize arrays
void initialize_and_process(char* file_path) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    // Get file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    // Allocate memory for arrays
    long* offsets = (long*)malloc(file_size * sizeof(long));
    int* keys = (int*)malloc(file_size / sizeof(int));
    record* records = (record*)malloc(file_size / sizeof(record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        fclose(file);
        return;
    }

    // Read data from file
    size_t bytes_read = fread(offsets, sizeof(long), file_size / sizeof(long), file);
    if (bytes_read != file_size / sizeof(long)) {
        fprintf(stderr, "Failed to read all data: %zu bytes read\n", bytes_read);
        free(offsets);
        free(keys);
        free(records);
        fclose(file);
        return;
    }

    // Initialize records
    for (size_t i = 0; i < file_size / sizeof(record); ++i) {
        keys[i] = offsets[i];
        records[i].key = keys[i];
        records[i].measurement = 0.0;
        records[i].status = 'A';
        records[i].data_item = (item*)malloc(sizeof(item));
        records[i].meta_data = (metadata*)malloc(sizeof(metadata));

        if (!records[i].data_item || !records[i].meta_data) {
            perror("Memory allocation failed for record data");
            free(offsets);
            free(keys);
            for (size_t j = 0; j < i; ++j) {
                free(records[j].data_item);
                free(records[j].meta_data);
            }
            free(records);
            fclose(file);
            return;
        }

        records[i].data_item->identifier = i;
        records[i].data_item->value = 0.0;
        records[i].data_item->label = 'X';
        records[i].meta_data->source_path[0] = '\0';
        records[i].meta_data->timestamp = time(NULL);
    }

    // Process data (example: calculate disjoint pairs)
    clock_t start, end;
    double cpu_time_used;

    for (size_t i = 0; i < file_size / sizeof(record); ++i) {
        start = clock();
        // Perform disjointness test
        // ...
        end = clock();
        cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;
        printf("Disjointness test %zu took %.3f seconds\n", i, cpu_time_used);
    }

    // Clean up
    for (size_t i = 0; i < file_size / sizeof(record); ++i) {
        free(records[i].data_item);
        free(records[i].meta_data);
    }
    free(offsets);
    free(keys);
    free(records);
    fclose(file);
}

int main() {
    initialize_and_process("large_dataset.bin");
    return 0;
}
