#define MAX_ENTRIES 1000

typedef struct {
    double value;
    int id;
    char status;
} entry;

void log_message(const char *message) {
    printf("%s\n", message);
}

entry* read_entries(int *count) {
    entry *entries = (entry*)malloc(MAX_ENTRIES * sizeof(entry));
    if (!entries) {
        log_message("Memory allocation failed for entries");
        return NULL;
    }
    *count = 0;

    double value;
    char status;
    while (scanf("%lf %c", &value, &status) == 2 && *count < MAX_ENTRIES) {
        entries[*count].value = value;
        entries[*count].id = *count;
        entries[*count].status = status;
        (*count)++;
    }

    return entries;
}

void free_entries(entry *entries, int count) {
    if (entries) {
        free(entries);
        log_message("Entries memory freed");
    }
}

void sort_entries(entry *entries, int count) {
    // Implement sorting algorithm here
    // Example: QuickSort or MergeSort for efficiency
}

int find(int parent[], int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void union_sets(int parent[], int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);

    if (xset != yset) {
        parent[xset] = yset;
        log_message("Union operation completed");
    }
}

int count_disjoint_sets(char *status, int count) {
    int *parent = (int*)calloc(count, sizeof(int));
    if (!parent) {
        log_message("Memory allocation failed for parent array");
        return -1;
    }

    for (int i = 0; i < count; i++)
        parent[i] = -1;

    for (int i = 0; i < count; i++) {
        int x = find(parent, i);
        if (status[x] == 'A') {
            union_sets(parent, i, (i + 1) % count);
        }
    }

    int disjoint_sets = 0;
    for (int i = 0; i < count; i++)
        if (parent[i] == -1)
            disjoint_sets++;

    free(parent);
    log_message("Disjoint sets counted");

    return disjoint_sets;
}

int main() {
    entry *entries;
    int count;

    entries = read_entries(&count);
    if (!entries) {
        return 1;
    }

    sort_entries(entries, count);

    char status[MAX_ENTRIES];
    for (int i = 0; i < count; i++)
        status[i] = entries[i].status;

    int disjoint_sets = count_disjoint_sets(status, count);
    printf("Number of disjoint sets: %d\n", disjoint_sets);

    free_entries(entries, count);

