#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define RESIZE_FACTOR 2

typedef struct Record {
    int key;
    int value;
} Record;

typedef struct HashTable {
    Record **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable *create_hash_table() {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    table->buckets = (Record **)calloc(table->capacity, sizeof(Record *));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void resize_hash_table(HashTable *table) {
    size_t new_capacity = table->capacity * RESIZE_FACTOR;
    Record **new_buckets = (Record **)calloc(new_capacity, sizeof(Record *));

    for (size_t i = 0; i < table->capacity; ++i) {
        Record *record = table->buckets[i];
        if (record != NULL) {
            size_t index = record->key % new_capacity;
            while (new_buckets[index] != NULL) {
                index = (index + 1) % new_capacity;
            }
            new_buckets[index] = record;
        }
    }

    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

void insert_record(HashTable *table, int key, int value) {
    pthread_mutex_lock(&table->lock);
    size_t index = key % table->capacity;

    while (table->buckets[index] != NULL && table->buckets[index]->key != key) {
        index = (index + 1) % table->capacity;
    }

    if (table->buckets[index] == NULL) {
        table->buckets[index] = (Record *)malloc(sizeof(Record));
        table->buckets[index]->key = key;
        table->buckets[index]->value = value;
        table->size++;
    } else {
        table->buckets[index]->value = value;
    }

    if (table->size >= table->capacity * 0.75) {
        resize_hash_table(table);
    }
    pthread_mutex_unlock(&table->lock);
}

int lookup_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = key % table->capacity;

    while (table->buckets[index] != NULL && table->buckets[index]->key != key) {
        index = (index + 1) % table->capacity;
    }

    if (table->buckets[index] == NULL) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Key not found
    } else {
        int value = table->buckets[index]->value;
        pthread_mutex_unlock(&table->lock);
        return value;
    }
}

void iterate_records(HashTable *table, void (*operation)(int key, int value)) {
    pthread_mutex_lock(&table->lock);
    for (size_t i = 0; i < table->capacity; ++i) {
        Record *record = table->buckets[i];
        if (record != NULL) {
            operation(record->key, record->value);
        }
    }
    pthread_mutex_unlock(&table->lock);
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Record *record = table->buckets[i];
        if (record != NULL) {
            free(record);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
