#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_HOSTNAMES 100
#define CONFIG_FILE "config.txt"

typedef struct {
    int value;
} record;

void initialize_resources(long *offsets, int *keys, record **records, int num_records, int seed) {
    srand(seed);
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand() % 1000;
    }
}

void resolve_dns(char **hostnames, u_char *ip_addresses, int num_hostnames) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    for (int i = 0; i < num_hostnames; i++) {
        if ((status = getaddrinfo(hostnames[i], NULL, &hints, &res)) != 0) {
            fprintf(stderr, "DNS resolution failed for %s: %s\n", hostnames[i], gai_strerror(status));
            exit(EXIT_FAILURE);
        }

        p = res;
        while (p != NULL) {
            if (p->ai_family == AF_INET) { // IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                ip_addresses[i] = *(u_char *)&ipv4->sin_addr.s_addr;
                break;
            }
            p = p->ai_next;
        }

        freeaddrinfo(res);
    }
}

void fetch_config(int *seed, int *memory_budget) {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) {
        fprintf(stderr, "Failed to open config file\n");
        exit(EXIT_FAILURE);
    }

    fscanf(file, "%d %d", seed, memory_budget);

    fclose(file);
}

int main() {
    int num_records;
    long *offsets;
    int *keys;
    record **records;
    char *hostnames[MAX_HOSTNAMES];
    u_char ip_addresses[MAX_HOSTNAMES];
    int seed, memory_budget;

    fetch_config(&seed, &memory_budget);

    // Simulate fetching number of records from external service
    num_records = 50;

    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    records = malloc(num_records * sizeof(record *));
    hostnames[0] = "example.com"; // Example hostname

    initialize_resources(offsets, keys, records, num_records, seed);
    resolve_dns(hostnames, ip_addresses, 1);

    for (int i = 0; i < num_records; i++) {
        printf("Offset: %ld, Key: %d, Record Value: %d\n", offsets[i], keys[i], records[i]->value);
    }

    // Free allocated memory
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
```

