#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    TASK_STATUS_PENDING,
    TASK_STATUS_IN_PROGRESS,
    TASK_STATUS_COMPLETED
} TaskStatus;

typedef struct Task {
    int id;
    int priority;
    TaskStatus status;
    // Add any other attributes as needed
} Task;

typedef struct TaskCollection {
    Task** tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TaskCollection;

TaskCollection* create_task_collection(size_t initial_capacity) {
    TaskCollection* collection = (TaskCollection*)malloc(sizeof(TaskCollection));
    if (!collection) return NULL;

    collection->tasks = (Task**)calloc(initial_capacity, sizeof(Task*));
    if (!collection->tasks) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_task_collection(TaskCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        free(collection->tasks[i]);
    }
    free(collection->tasks);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_task(TaskCollection* collection, Task* task) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Task** new_tasks = (Task**)realloc(collection->tasks, new_capacity * sizeof(Task*));
        if (!new_tasks) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->tasks = new_tasks;
        collection->capacity = new_capacity;
    }

    collection->tasks[collection->size++] = task;

    pthread_mutex_unlock(&collection->lock);
    return 0;
}

Task* get_task_by_id(TaskCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->tasks[i]->id == id) {
            Task* task = collection->tasks[i];
            pthread_mutex_unlock(&collection->lock);
            return task;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

int update_task_status(TaskCollection* collection, int id, TaskStatus new_status) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->tasks[i]->id == id) {
            collection->tasks[i]->status = new_status;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Task not found
}

int remove_task(TaskCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; ++i) {
        if (collection->tasks[i]->id == id) {
            free(collection->tasks[i]);
            for (size_t j = i; j < collection->size - 1; ++j) {
                collection->tasks[j] = collection->tasks[j + 1];
            }
            --collection->size;
            pthread_mutex_unlock(&collection->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Task not found
}
