#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024

typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DataStructure;

DataStructure* create_data_structure() {
    DataStructure *ds = (DataStructure*)malloc(sizeof(DataStructure));
    ds->records = (Record*)calloc(INITIAL_CAPACITY, sizeof(Record));
    ds->capacity = INITIAL_CAPACITY;
    ds->size = 0;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void insert_or_update(DataStructure *ds, int key, int value) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->records[i].key == key) {
            ds->records[i].value = value;
            pthread_mutex_unlock(&ds->lock);
            return;
        }
    }
    if (ds->size >= ds->capacity) {
        // Resize the data structure
        ds->capacity *= 2;
        ds->records = (Record*)realloc(ds->records, ds->capacity * sizeof(Record));
    }
    ds->records[ds->size].key = key;
    ds->records[ds->size].value = value;
    ++ds->size;
    pthread_mutex_unlock(&ds->lock);
}

int lookup(DataStructure *ds, int key) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->records[i].key == key) {
            int value = ds->records[i].value;
            pthread_mutex_unlock(&ds->lock);
            return value;
        }
    }
    pthread_mutex_unlock(&ds->lock);
    return -1; // Key not found
}

void delete_record(DataStructure *ds, int key) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->records[i].key == key) {
            for (size_t j = i; j < ds->size - 1; ++j) {
                ds->records[j] = ds->records[j + 1];
            }
            --ds->size;
            pthread_mutex_unlock(&ds->lock);
            return;
        }
    }
    pthread_mutex_unlock(&ds->lock);
}

void destroy_data_structure(DataStructure *ds) {
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}
