int networkInitialize(const char *hostname, long **offsets, int **keys, Record **records, int num_records, int range_start, int range_end) {
    struct addrinfo hints, *res, *p;
    int status;
    long *temp_offsets = malloc(num_records * sizeof(long));
    int *temp_keys = malloc(num_records * sizeof(int));
    Record *temp_records = malloc(num_records * sizeof(Record));

    if (temp_offsets == NULL || temp_keys == NULL || temp_records == NULL) {
        free(temp_offsets);
        free(temp_keys);
        free(temp_records);
        return -1; // Memory allocation failed
    }

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        free(temp_offsets);
        free(temp_keys);
        free(temp_records);
        return -2; // DNS resolution failed
    }

    p = res;
    while (p != NULL) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        temp_offsets[0] = ntohl(ipv4->sin_addr.s_addr);
        break;
    }
    freeaddrinfo(res);

    for (int i = 0; i < num_records; i++) {
        temp_keys[i] = rand() % (range_end - range_start + 1) + range_start;
        temp_records[i].value = rand() % (range_end - range_start + 1) + range_start;
    }

    *offsets = temp_offsets;
    *keys = temp_keys;
    *records = temp_records;

    return 0; // Success
}
