#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MIN_VALUE 1
#define MAX_VALUE 100

typedef struct {
    int value;
} record;

void* initialize_service(void* arg) {
    long* offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    int* keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    if (!keys) {
        free(offsets);
        perror("Failed to allocate memory for keys");
        return NULL;
    }

    record* records = (record*)malloc(MAX_RECORDS * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        perror("Failed to allocate memory for records");
        return NULL;
    }

    pthread_mutex_t mutex;
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        free(offsets);
        free(keys);
        free(records);
        perror("Failed to initialize mutex");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        records[i].value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;

        if (pthread_mutex_lock(&mutex) != 0) {
            free(offsets);
            free(keys);
            free(records);
            pthread_mutex_destroy(&mutex);
            perror("Failed to lock mutex");
            return NULL;
        }

        // Simulate partial startup
        if (rand() % 2 == 0) {
            printf("Partial startup at record %d\n", i);
            pthread_mutex_unlock(&mutex);
            continue;
        }

        pthread_mutex_unlock(&mutex);
    }

    // Simulate service shutdown with random delay
    sleep(rand() % 5 + 1);

    free(offsets);
    free(keys);
    free(records);
    pthread_mutex_destroy(&mutex);

    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, initialize_service, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
