[ApiController]
[Route("api/[controller]")]
public class ContentController : ControllerBase
{
    private readonly IContentService _contentService;
    private readonly ILogger<ContentController> _logger;
    private readonly ITranslationService _translationService;
    private readonly IMemoryCache _cache;

    public ContentController(IContentService contentService, ILogger<ContentController> logger, ITranslationService translationService, IMemoryCache cache)
    {
        _contentService = contentService;
        _logger = logger;
        _translationService = translationService;
        _cache = cache;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdateElementWithEnhancedContent([FromBody] ContentUpdateRequest request)
    {
        if (!ModelState.IsValid)
            return BadRequest(ModelState);

        try
        {
            var updatedContent = await RetryOnFailure(() => _contentService.UpdateElement(request.SectionId, request.ElementId, request.HtmlContent), 5);
            if (updatedContent == null)
                return StatusCode(500, "Failed to update content after retries.");

            _cache.Set($"element_{request.ElementId}", updatedContent, TimeSpan.FromMinutes(10));

            _logger.LogInformation("Content updated successfully at {Timestamp}: SectionId={SectionId}, ElementId={ElementId}", DateTime.UtcNow, request.SectionId, request.ElementId);

            return Ok(updatedContent);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating content: {Message}", ex.Message);
            return StatusCode(500, "Internal server error.");
        }
    }

    private async Task<T> RetryOnFailure<T>(Func<Task<T>> action, int maxRetries)
    {
        for (int attempt = 1; attempt <= maxRetries; attempt++)
        {
            try
            {
                return await action();
            }
            catch (Exception ex) when (attempt < maxRetries)
            {
                _logger.LogWarning(ex, "Attempt {Attempt} failed. Retrying...", attempt);
                await Task.Delay(100 * attempt); // Exponential backoff
            }
        }

        throw new Exception("Operation failed after maximum retries.");
    }
}

public class ContentUpdateRequest
{
    public string SectionId { get; set; }
    public string ElementId { get; set; }
    public string HtmlContent { get; set; }
}

public interface IContentService
{
    Task<string> UpdateElement(string sectionId, string elementId, string htmlContent);
}

public class ContentService : IContentService
{
    private readonly ILogger<ContentService> _logger;

    public ContentService(ILogger<ContentService> logger)
    {
        _logger = logger;
    }

    public async Task<string> UpdateElement(string sectionId, string elementId, string htmlContent)
    {
        // Simulate content update logic
        await Task.Delay(100); // Simulate network latency

        if (string.IsNullOrEmpty(sectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrEmpty(htmlContent))
            throw new ArgumentException("Invalid input parameters.");

        _logger.LogInformation("Updating element {ElementId} in section {SectionId}", elementId, sectionId);

        return htmlContent; // Return updated content
    }
}

public interface ITranslationService
{
    Task<string> TranslateHtml(string htmlContent, string targetLanguage);
}

public class TranslationService : ITranslationService
{
    private readonly ILogger<TranslationService> _logger;

    public TranslationService(ILogger<TranslationService> logger)
    {
        _logger = logger;
    }

    public async Task<string> TranslateHtml(string htmlContent, string targetLanguage)
    {
        // Simulate translation logic
        await Task.Delay(50); // Simulate network latency

        if (string.IsNullOrEmpty(htmlContent) || string.IsNullOrEmpty(targetLanguage))
            throw new ArgumentException("Invalid input parameters.");

        _logger.LogInformation("Translating HTML content to {TargetLanguage}", targetLanguage);

        return htmlContent; // Return translated content
    }
}
