#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define KEY_RANGE 10000
#define OFFSET_RANGE 100000

typedef struct {
    int value;
    int* key_ptr;
    size_t offset_index;
} record;

int generate_unique_key(int* keys, int used_keys, int range) {
    int key;
    do {
        key = rand() % range;
    } while (key < used_keys);
    return key;
}

int generate_unique_value(record* records, int used_records, int range) {
    int value;
    do {
        value = rand() % range;
    } while (find_record_by_value(records, used_records, value) != -1);
    return value;
}

int find_record_by_value(record* records, int count, int value) {
    for (int i = 0; i < count; ++i) {
        if (records[i].value == value) {
            return i;
        }
    }
    return -1;
}

record* create_records(int num_records, int key_range, int offset_range, int value_range) {
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    int* keys = malloc(key_range * sizeof(int));
    if (!keys) {
        free(records);
        perror("Failed to allocate memory for keys");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].value = generate_unique_value(records, i, value_range);
        records[i].key_ptr = &keys[generate_unique_key(keys, i, key_range)];
        records[i].offset_index = rand() % offset_range;
    }

    free(keys);
    return records;
}

void serialize_records(record* records, int num_records, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    fwrite(records, sizeof(record), num_records, file);
    fclose(file);
}

int main() {
    record* records = create_records(MAX_RECORDS, KEY_RANGE, OFFSET_RANGE, 1000000);
    if (records) {
        serialize_records(records, MAX_RECORDS, "records.bin");
        free(records);
    }
    return 0;
}
