#include <string.h>
#include <sys/stat.h>

typedef struct {
    char* filename;
    off_t size;
    struct stat metadata;
} entry;

entry* create_entry_array(const char* directories[], int num_directories, int* out_count) {
    // Calculate the total number of entries needed
    *out_count = 0;
    for (int i = 0; i < num_directories; ++i) {
        DIR* dir = opendir(directories[i]);
        if (dir == NULL) {
            fprintf(stderr, "Failed to open directory: %s\n", directories[i]);
            continue;
        }
        struct dirent* ent;
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;
            (*out_count)++;
        }
        closedir(dir);
    }

    // Allocate memory for the entry array
    entry* entries = malloc(*out_count * sizeof(entry));
    if (entries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize each entry with file names and metadata
    int index = 0;
    for (int i = 0; i < num_directories; ++i) {
        DIR* dir = opendir(directories[i]);
        if (dir == NULL) {
            fprintf(stderr, "Failed to open directory: %s\n", directories[i]);
            continue;
        }
        struct dirent* ent;
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;

            entries[index].filename = malloc(strlen(directories[i]) + strlen(ent->d_name) + 2);
            if (entries[index].filename == NULL) {
                fprintf(stderr, "Memory allocation failed\n");
                for (int j = 0; j < index; ++j) {
                    free(entries[j].filename);
                }
                free(entries);
                return NULL;
            }

            snprintf(entries[index].filename, strlen(directories[i]) + strlen(ent->d_name) + 2, "%s/%s", directories[i], ent->d_name);

            if (stat(entries[index].filename, &entries[index].metadata) != 0) {
                fprintf(stderr, "Failed to get metadata for file: %s\n", entries[index].filename);
                free(entries[index].filename);
                index--;
                continue;
            }

            entries[index].size = entries[index].metadata.st_size;

            index++;
        }
        closedir(dir);
    }

    return entries;
}

void free_entry_array(entry* entries, int count) {
    for (int i = 0; i < count; ++i) {
        free(entries[i].filename);
    }
    free(entries);
}
