#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct data_entry {
    float precision;
    unsigned long timestamp;
    struct data_entry *next;
    double value;
    char *identifier;
    size_t length;
} data_entry;

typedef struct dataset {
    data_entry **entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dataset;

int create_dataset(dataset *ds, size_t initial_capacity) {
    ds->entries = (data_entry **)malloc(initial_capacity * sizeof(data_entry *));
    if (!ds->entries) return -1; // Memory allocation failed
    memset(ds->entries, 0, initial_capacity * sizeof(data_entry *));
    ds->capacity = initial_capacity;
    ds->size = 0;
    pthread_mutex_init(&ds->lock, NULL);
    return 0;
}

void destroy_dataset(dataset *ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        data_entry *entry = ds->entries[i];
        while (entry) {
            data_entry *next = entry->next;
            free(entry->identifier);
            free(entry);
            entry = next;
        }
    }
    pthread_mutex_destroy(&ds->lock);
    free(ds->entries);
}

int add_entry(dataset *ds, float precision, unsigned long timestamp, double value, const char *identifier) {
    pthread_mutex_lock(&ds->lock);
    while (1) {
        int found_collision = 0;
        for (size_t i = 0; i < ds->size; ++i) {
            data_entry *entry = ds->entries[i];
            while (entry) {
                if (entry->precision == precision && entry->timestamp == timestamp) {
                    found_collision = 1;
                    break;
                }
                entry = entry->next;
            }
            if (found_collision) break;
        }
        if (!found_collision) break;

        // Retry with new values
        precision = (float)(rand() / (RAND_MAX + 1.0));
        timestamp = rand();
    }

    data_entry *new_entry = (data_entry *)malloc(sizeof(data_entry));
    if (!new_entry) {
        pthread_mutex_unlock(&ds->lock);
        return -1; // Memory allocation failed
    }
    new_entry->precision = precision;
    new_entry->timestamp = timestamp;
    new_entry->value = value;
    new_entry->identifier = strdup(identifier);
    new_entry->length = strlen(identifier);
    new_entry->next = NULL;

    if (ds->size == ds->capacity) {
        size_t new_capacity = ds->capacity * 2;
        data_entry **new_entries = (data_entry **)realloc(ds->entries, new_capacity * sizeof(data_entry *));
        if (!new_entries) {
            free(new_entry);
            pthread_mutex_unlock(&ds->lock);
            return -1; // Memory allocation failed
        }
        memset(new_entries + ds->capacity, 0, (new_capacity - ds->capacity) * sizeof(data_entry *));
        ds->entries = new_entries;
        ds->capacity = new_capacity;
    }

    size_t hash = timestamp % ds->capacity;
    data_entry **bucket = &ds->entries[hash];
    while (*bucket) bucket = &(*bucket)->next;

    *bucket = new_entry;
    ++ds->size;
    pthread_mutex_unlock(&ds->lock);
    return 0;
}

int serialize_dataset(dataset *ds, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1; // File opening failed

    size_t total_size = sizeof(size_t); // For the number of entries
    for (size_t i = 0; i < ds->size; ++i) {
        data_entry *entry = ds->entries[i];
        while (entry) {
            total_size += sizeof(float) + sizeof(unsigned long) + sizeof(double) + sizeof(size_t) + entry->length;
            entry = entry->next;
        }
    }

    if (fseek(file, 0, SEEK_SET) != 0 || fwrite(&ds->size, sizeof(size_t), 1, file) != 1) {
        fclose(file);
        return -2; // Write error
    }

    for (size_t i = 0; i < ds->size; ++i) {
        data_entry *entry = ds->entries[i];
        while (entry) {
            if (fwrite(&entry->precision, sizeof(float), 1, file) != 1 ||
                fwrite(&entry->timestamp, sizeof(unsigned long), 1, file) != 1 ||
                fwrite(&entry->value, sizeof(double), 1, file) != 1 ||
                fwrite(&entry->length, sizeof(size_t), 1, file) != 1 ||
                fwrite(entry->identifier, entry->length, 1, file) != 1) {
                fclose(file);
                return -3; // Write error
            }
            entry = entry->next;
        }
    }

    fclose(file);
    return 0;
}
