#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    int* keyPtr;
    int offsetIndex;
} Record;

int generateRandom(int min, int max) {
    return rand() % (max - min + 1) + min;
}

int allocateMemory(long** offsets, int** keys, Record*** records, long numRecords, int keyRange, int valueRange) {
    *offsets = (long*)malloc(numRecords * sizeof(long));
    *keys = (int*)malloc(numRecords * sizeof(int));
    *records = (Record**)malloc(numRecords * sizeof(Record*));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        return -1; // Memory allocation failed
    }

    srand(time(NULL));

    for (long i = 0; i < numRecords; ++i) {
        long offset;
        int key, value;

        do {
            offset = generateRandom(0, numRecords * sizeof(long));
        } while (offset == (*offsets)[i - 1] && i > 0);

        do {
            key = generateRandom(0, keyRange);
        } while (i > 0 && key == (*keys)[i - 1]);

        do {
            value = generateRandom(0, valueRange);
        } while (i > 0 && value == (*records)[i - 1]->value);

        (*offsets)[i] = offset;
        (*keys)[i] = key;

        Record* record = (Record*)malloc(sizeof(Record));
        if (record == NULL) {
            return -2; // Memory allocation failed for record
        }

        record->value = value;
        record->keyPtr = &(*keys)[i];
        record->offsetIndex = i;

        (*records)[i] = record;
    }

    return 0; // Success
}

void freeMemory(long* offsets, int* keys, Record** records, long numRecords) {
    for (long i = 0; i < numRecords; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long numRecords = 1000;
    int keyRange = 1000;
    int valueRange = 1000;

    long* offsets;
    int* keys;
    Record** records;

    int result = allocateMemory(&offsets, &keys, &records, numRecords, keyRange, valueRange);

    if (result == 0) {
        printf("Successfully created %ld records.\n", numRecords);
        // Perform further operations with the records
        freeMemory(offsets, keys, records, numRecords);
    } else if (result == -1) {
        printf("Failed to allocate memory for offsets or keys.\n");
    } else if (result == -2) {
        printf("Failed to allocate memory for record.\n");
    }

    return 0;
}
