#include <thread>
#include <mutex>
#include <random>
#include <chrono>
#include <atomic>

struct AttackRecord {
    int value;
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    bool status;
};

class GameServer {
public:
    GameServer(size_t playerCount, int minValue, int maxValue, std::chrono::seconds cooldown)
        : playerCount(playerCount), minValue(minValue), maxValue(maxValue), cooldown(cooldown) {
        srand(time(0));
        attackRecords.resize(playerCount);
        for (size_t i = 0; i < playerCount; ++i) {
            attackRecords[i].resize(10); // Assuming each player has a maximum of 10 attack records
            std::fill(attackRecords[i].begin(), attackRecords[i].end(), AttackRecord{0, {}, false});
        }
    }

    bool performAttack(size_t playerId, int value) {
        if (playerId >= playerCount || value < minValue || value > maxValue) {
            return false;
        }

        std::lock_guard<std::mutex> lock(mutexes[playerId]);
        auto& records = attackRecords[playerId];
        for (auto& record : records) {
            if (!record.status && std::chrono::system_clock::now() - record.timestamp >= cooldown) {
                record.value = value;
                record.timestamp = std::chrono::system_clock::now();
                record.status = true;
                return true;
            }
        }

        return false; // No available slot for attack
    }

private:
    size_t playerCount;
    int minValue;
    int maxValue;
    std::chrono::seconds cooldown;
    std::vector<std::vector<AttackRecord>> attackRecords;
    std::vector<std::mutex> mutexes(playerCount);
};

int main() {
    GameServer server(100, 1, 100, std::chrono::seconds(5));

    std::thread t1([&server]() { for (int i = 0; i < 10; ++i) server.performAttack(0, rand()); });
    std::thread t2([&server]() { for (int i = 0; i < 10; ++i) server.performAttack(1, rand()); });

    t1.join();
    t2.join();

    return 0;
}
