#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int key;
    double value;
    char* userID;
} Record;

typedef struct {
    int* keys;
    long* offsets;
    int size;
} DataInput;

typedef struct {
    int parent;
    int rank;
} UnionFindNode;

Record* createRecords(DataInput* input, long* offsets, int numThreads) {
    // Allocate memory for records
    Record* records = (Record*)malloc(input->size * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    // Initialize Union-Find structure
    UnionFindNode* uf = (UnionFindNode*)calloc(input->size, sizeof(UnionFindNode));
    if (!uf) {
        perror("Failed to allocate memory for Union-Find structure");
        free(records);
        return NULL;
    }

    // Populate records with data from input and offsets
    for (int i = 0; i < input->size; ++i) {
        records[i].key = input->keys[i];
        records[i].value = input->offsets[i] * 1.0 / numThreads; // Simplified value calculation
        records[i].userID = fetchUserID(input->keys[i]); // Asynchronous user ID fetching
    }

    // Calculate number of disjoint pairs using Union-Find
    for (int i = 0; i < input->size; ++i) {
        int root = find(uf, i);
        if (root != i) {
            unionSets(uf, root, i);
        }
    }

    // Free allocated memory
    free(uf);

    return records;
}

char* fetchUserID(int key) {
    // Simulated asynchronous user ID fetching
    static char userID[10];
    sprintf(userID, "user%d", key);
    return userID;
}

int find(UnionFindNode* uf, int i) {
    if (uf[i].parent != i) {
        uf[i].parent = find(uf, uf[i].parent); // Path compression
    }
    return uf[i].parent;
}

void unionSets(UnionFindNode* uf, int i, int j) {
    int rootI = find(uf, i);
    int rootJ = find(uf, j);

    if (rootI != rootJ) {
        if (uf[rootI].rank > uf[rootJ].rank) {
            uf[rootJ].parent = rootI;
        } else if (uf[rootI].rank < uf[rootJ].rank) {
            uf[rootI].parent = rootJ;
        } else {
            uf[rootJ].parent = rootI;
            uf[rootI].rank++;
        }
    }
}

void freeRecords(Record* records, int size) {
    for (int i = 0; i < size; ++i) {
        free(records[i].userID);
    }
    free(records);
}
