} transaction;

void log_message(const char* message) {
    printf("LOG: %s\n", message);
}

float* allocate_float_array(int size) {
    float* array = (float*)malloc(size * sizeof(float));
    if (!array) {
        log_message("Failed to allocate memory for float array");
        exit(1);
    }
    return array;
}

item* allocate_item_array(int size) {
    item* array = (item*)malloc(size * sizeof(item));
    if (!array) {
        log_message("Failed to allocate memory for item array");
        exit(1);
    }
    return array;
}

transaction* allocate_transaction_array(int size) {
    transaction* array = (transaction*)malloc(size * sizeof(transaction));
    if (!array) {
        log_message("Failed to allocate memory for transaction array");
        exit(1);
    }
    return array;
}

void initialize_float_array(float* array, int size, float min_val, float max_val) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        array[i] = min_val + (float)(rand()) / ((float)RAND_MAX / (max_val - min_val));
    }
}

void initialize_item_array(item* array, int size, const char* prefix) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        array[i].value = rand() % 100;
        array[i].name = (char*)malloc(20 * sizeof(char));
        snprintf(array[i].name, 20, "%s%d", prefix, i);
    }
}

void initialize_transaction_array(transaction* array, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        array[i].amount = rand() % 100;
        array[i].description = (char*)malloc(50 * sizeof(char));
        snprintf(array[i].description, 50, "Transaction %d", i);
        initialize_item_array(&array[i].item_info, 1, "Item");
    }
}

void free_float_array(float* array, int size) {
    for (int i = 0; i < size; ++i) {
        free(array + i);
    }
    free(array);
}

void free_item_array(item* array, int size) {
    for (int i = 0; i < size; ++i) {
        free(array[i].name);
    }
    free(array);
}

void free_transaction_array(transaction* array, int size) {
    for (int i = 0; i < size; ++i) {
        free(array[i].description);
        free_item_array(&array[i].item_info, 1);
    }
    free(array);
}

float calculate_sum(float* array, int size) {
    float sum = 0;
    for (int i = 0; i < size; ++i) {
        sum += array[i];
    }
    return sum;
}

float calculate_average(float* array, int size) {
    if (size == 0) return 0;
    return calculate_sum(array, size) / size;
}

int find_longest_string(char** strings, int size) {
    int max_length = 0;
    for (int i = 0; i < size; ++i) {
        if (strings[i] && strlen(strings[i]) > max_length) {
            max_length = strlen(strings[i]);
        }
    }
    return max_length;
}

