    initialize_item_array(item_array, size, "Item");
    initialize_transaction_array(transaction_array, size);

    read_input_data(float_array, item_array, transaction_array, size);

    float sum = calculate_sum(float_array, size);
    float average = calculate_average(float_array, size);
    int longest_string_length = find_longest_string((char**)&transaction_array->description, size);

    printf("Sum of floats: %f\n", sum);
    printf("Average of floats: %f\n", average);
    printf("Longest string length: %d\n", longest_string_length);

    free_float_array(float_array, size);
    free_item_array(item_array, size);
    free_transaction_array(transaction_array, size);

    return 0;
}
