#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct {
    int key;
    long offset;
    int value;
    char status;
    double timestamp;
} Record;

Record data_store[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* background_cleanup(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        // Implement cleanup logic here
        pthread_mutex_unlock(&mutex);
        sleep(60); // Adjust frequency as needed
    }
    return NULL;
}

int add_record(int key, long offset, int value, char status, double timestamp) {
    pthread_mutex_lock(&mutex);
    if (record_count >= MAX_RECORDS) {
        pthread_mutex_unlock(&mutex);
        return -1; // Error: Data store is full
    }
    data_store[record_count].key = key;
    data_store[record_count].offset = offset;
    data_store[record_count].value = value;
    data_store[record_count].status = status;
    data_store[record_count].timestamp = timestamp;
    record_count++;
    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

Record* get_record(int key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        if (data_store[i].key == key) {
            Record* result = &data_store[i];
            pthread_mutex_unlock(&mutex);
            return result;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL; // Record not found
}

int remove_record(int key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        if (data_store[i].key == key) {
            for (int j = i; j < record_count - 1; j++) {
                data_store[j] = data_store[j + 1];
            }
            record_count--;
            pthread_mutex_unlock(&mutex);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&mutex);
    return -1; // Record not found
}

int main() {
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, background_cleanup, NULL);

    // Example usage
    add_record(1, 12345, 42, 'A', time(NULL));
    Record* record = get_record(1);
    if (record != NULL) {
        printf("Record found: key=%d, value=%d\n", record->key, record->value);
    }
    remove_record(1);

    pthread_join(cleanup_thread, NULL);
    return 0;
}
