#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000000

typedef struct {
    int id;
    long offset;
    double value;
    char* str;
    int initialized;
} record;

void init_record(record* r, int id, long offset, double value) {
    r->id = id;
    r->offset = offset;
    r->value = value;
    r->str = NULL;
    r->initialized = 0;
}

int allocate_string(record* r, size_t length) {
    r->str = (char*)malloc(length * sizeof(char));
    if (!r->str) return -1;
    strncpy(r->str, "initialized", length);
    r->initialized = 1;
    return 0;
}

void free_record(record* r) {
    if (r->str && r->initialized) {
        free(r->str);
        r->str = NULL;
        r->initialized = 0;
    }
}

int main(int argc, char* argv[]) {
    int num_records = MAX_RECORDS; // Default value
    if (argc > 1) {
        num_records = atoi(argv[1]);
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    srand(time(NULL)); // Seed for random number generation

    clock_t start_time = clock();
    for (int i = 0; i < num_records; ++i) {
        init_record(&records[i], i, rand(), (double)rand() / RAND_MAX);
        if (allocate_string(&records[i], 14) != 0) {
            fprintf(stderr, "Failed to allocate string for record %d\n", i);
            // Free previously allocated records
            for (int j = 0; j < i; ++j) {
                free_record(&records[j]);
            }
            free(records);
            return -1;
        }
    }

    clock_t end_time = clock();
    double elapsed_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;

    printf("Initialization completed in %.2f seconds\n", elapsed_time);

    // Cleanup
    for (int i = 0; i < num_records; ++i) {
        free_record(&records[i]);
    }
    free(records);

    return 0;
}
