    public function updatePasswordAndRole($userId, $oldPassword, $newPassword, $secondFactor, $newRole) {
        // Rate limiting logic
        if (!$this->rateLimitCheck($userId)) {
            return ['status' => 'error', 'message' => 'Too many attempts. Please try again later.'];
        }

        // Multi-factor authentication check
        if (!$this->verifyMFA($userId, $secondFactor)) {
            return ['status' => 'error', 'message' => 'Invalid second factor.'];
        }

        // Role consistency check
        if (!$this->isRoleConsistent($userId, $newRole)) {
            return ['status' => 'error', 'message' => 'New role is not consistent with MFA status.'];
        }

        // Transaction handling and retry logic
        for ($i = 0; $i < 5; $i++) {
            try {
                $this->db->beginTransaction();
                $this->updatePassword($userId, $oldPassword, $newPassword);
                $this->updateRole($userId, $newRole);
                $this->db->commit();
                break;
            } catch (Exception $e) {
                if ($i == 4) throw $e; // Rethrow exception after last retry
                sleep(2 ** $i); // Exponential backoff
