#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    struct record *next;
    char *data;
} Record;

typedef struct memory_pool {
    size_t block_size;
    size_t num_blocks;
    void *blocks;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool *create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool *)malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = malloc(block_size * num_blocks);
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void *allocate_from_pool(MemoryPool *pool) {
    void *block = NULL;
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (*(char *)(((char *)pool->blocks) + i * pool->block_size) == '\0') {
            block = ((char *)pool->blocks) + i * pool->block_size;
            *(char *)block = '1';
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void free_to_pool(MemoryPool *pool, void *block) {
    pthread_mutex_lock(&pool->lock);
    *(char *)block = '\0';
    pthread_mutex_unlock(&pool->lock);
}

Record *create_record(long offset, int key, MemoryPool *pool) {
    Record *rec = (Record *)allocate_from_pool(pool);
    if (!rec) return NULL;
    rec->offset = offset;
    rec->key = key;
    rec->next = NULL;
    rec->data = (char *)allocate_from_pool(pool);
    if (!rec->data) {
        free_to_pool(pool, rec);
        return NULL;
    }
    memset(rec->data, 0, pool->block_size - sizeof(Record));
    return rec;
}

void destroy_record(Record *rec, MemoryPool *pool) {
    free_to_pool(pool, rec->data);
    free_to_pool(pool, rec);
}

void *initialize_datasets(MemoryPool *pool, size_t num_records) {
    Record **datasets = (Record **)malloc(num_records * sizeof(Record *));
    if (!datasets) return NULL;
    for (size_t i = 0; i < num_records; ++i) {
        datasets[i] = create_record(i * 1024, i, pool);
        if (!datasets[i]) {
            for (size_t j = 0; j < i; ++j) {
                destroy_record(datasets[j], pool);
            }
            free(datasets);
            return NULL;
        }
    }
    return datasets;
}

void cleanup_datasets(Record **datasets, size_t num_records, MemoryPool *pool) {
    for (size_t i = 0; i < num_records; ++i) {
        destroy_record(datasets[i], pool);
    }
    free(datasets);
}

int main() {
    MemoryPool *pool = create_memory_pool(sizeof(Record), 1024);
    if (!pool) return -1;

    Record **datasets = (Record **)initialize_datasets(pool, 100);
    if (!datasets) {
        destroy_memory_pool(pool);
        return -1;
    }

    cleanup_datasets(datasets, 100, pool);
    destroy_memory_pool(pool);

    return 0;
}
