#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DATA_SIZE 1000

typedef struct {
    double value;
    float floatValue;
    char* stringValue;
    time_t timestamp;
    int sourceId;
} dataPoint;

void logMessage(const char* message) {
    printf("%s\n", message);
}

dataPoint* initializeData(int size, const char* identifierPrefix) {
    dataPoint* data = (dataPoint*)malloc(size * sizeof(dataPoint));
    if (!data) {
        logMessage("Memory allocation failed");
        return NULL;
    }
    for (int i = 0; i < size; ++i) {
        data[i].value = i * 1.1;
        data[i].floatValue = i * 2.2f;
        data[i].stringValue = (char*)malloc(50 * sizeof(char));
        snprintf(data[i].stringValue, 50, "%s_%d", identifierPrefix, i);
        data[i].timestamp = time(NULL);
        data[i].sourceId = i % 10;
    }
    return data;
}

void cleanupData(dataPoint* data, int size) {
    for (int i = 0; i < size; ++i) {
        free(data[i].stringValue);
    }
    free(data);
}

void readInput(dataPoint* data, int size) {
    for (int i = 0; i < size; ++i) {
        printf("Enter double value for data point %d: ", i);
        scanf("%lf", &data[i].value);
        printf("Enter float value for data point %d: ", i);
        scanf("%f", &data[i].floatValue);
        printf("Enter string value for data point %d: ", i);
        scanf("%s", data[i].stringValue);
    }
}

void computeAndPrintStats(dataPoint* data, int size) {
    double sum = 0;
    int maxLength = 0;
    for (int i = 0; i < size; ++i) {
        sum += data[i].value;
        if (strlen(data[i].stringValue) > maxLength) {
            maxLength = strlen(data[i].stringValue);
        }
    }
    printf("Average double value: %f\n", sum / size);
    printf("Maximum string length: %d\n", maxLength);
}

int main() {
    int size;
    printf("Enter the number of data points: ");
    scanf("%d", &size);

    if (size <= 0 || size > MAX_DATA_SIZE) {
        logMessage("Invalid input size");
        return 1;
    }

    dataPoint* data = initializeData(size, "DP");
    if (!data) {
        return 1;
    }

    readInput(data, size);
    computeAndPrintStats(data, size);

    cleanupData(data, size);

    return 0;
}
