@Service
public class ProductService {

    @Autowired
    private ProductRepository productRepository;

    @Autowired
    private ExternalApiService externalApiService;

    public void processProducts(Long storeId, String category, List<ProductOperation> operations) {
        try {
            // Initialize product list
            List<Product> products = productRepository.findByStoreIdAndCategory(storeId, category);

            // Process each operation
            for (ProductOperation operation : operations) {
                if (operation.isRead()) {
                    Product updatedProduct = externalApiService.fetchUpdatedProduct(operation.getProductId());
                    updateProduct(products, updatedProduct);
                } else {
                    Product updatedProduct = externalApiService.updateProduct(operation.getProductId(), operation.getNewValues());
                    updateProduct(products, updatedProduct);
                }
            }

            // Validate data integrity
            validateDataIntegrity(products);

        } catch (Exception e) {
            System.err.println("Error processing products: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private void updateProduct(List<Product> products, Product updatedProduct) {
        for (int i = 0; i < products.size(); i++) {
            if (products.get(i).getId().equals(updatedProduct.getId())) {
                products.set(i, updatedProduct);
                break;
            }
        }
    }

    private void validateDataIntegrity(List<Product> products) {
        for (Product product : products) {
            if (!isValidProduct(product)) {
                System.err.println("Invalid product found: " + product);
            }
        }
    }

    private boolean isValidProduct(Product product) {
        // Implement validation logic here
        return true;
    }
}

