    size_t num_blocks;
    void* blocks;
    pthread_mutex_t lock;
} memory_pool;

memory_pool* create_memory_pool(size_t block_size, size_t num_blocks) {
    memory_pool* pool = (memory_pool*)malloc(sizeof(memory_pool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = malloc(block_size * num_blocks);
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* allocate_from_pool(memory_pool* pool) {
    void* block = NULL;

    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        if (*(char*)(((char*)pool->blocks) + i * pool->block_size) == '\0') {
            *(char*)(((char*)pool->blocks) + i * pool->block_size) = '1';
            block = ((char*)pool->blocks) + i * pool->block_size;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);

    return block;
}

void deallocate_to_pool(memory_pool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    *(char*)block = '\0';
    pthread_mutex_unlock(&pool->lock);
}

void free_memory_pool(memory_pool* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->blocks);
    free(pool);
}

geometry* create_geometry(double value, const char* name, float x, float y) {
    geometry* geom = (geometry*)allocate_from_pool(geometry_pool);
    if (!geom) return NULL;

    geom->value = value;
    geom->name = strdup(name);
    geom->location.x = x;
    geom->location.y = y;

    return geom;
}

void free_geometry(geometry* geom) {
    deallocate_to_pool(geometry_pool, geom);
    free(geom->name);
}

int validate_input(double value, const char* name, float x, float y) {
    if (value < 0 || strlen(name) == 0 || x != x || y != y) return -1;
    return 0;
