sensor_data* initialize_sensor_data(int num_sensors, int min_index, int max_index) {
    sensor_data* data = (sensor_data*)malloc(num_sensors * sizeof(sensor_data));
    if (data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_sensors; i++) {
        data[i].measurement = ((double)rand() / RAND_MAX) * 100.0 - 50.0; // Random measurement between -50 and 50
        data[i].index = min_index + (i % (max_index - min_index + 1)); // Index based on a specific rule
        if (data[i].measurement > 0) {
            data[i].status_code = 'G'; // Good status for positive measurements
        } else if (data[i].measurement < 0) {
            data[i].status_code = 'B'; // Bad status for negative measurements
        } else {
            data[i].status_code = 'Z'; // Zero status for zero measurement
        }
    }

    return data;
}

void free_sensor_data(sensor_data* data, int num_sensors) {
    if (data != NULL) {
        free(data);
    }
}

int main() {
    int num_sensors = 10;
    sensor_data* sensors = initialize_sensor_data(num_sensors, 1, 10);

    if (sensors != NULL) {
        for (int i = 0; i < num_sensors; i++) {
            printf("Sensor %d: Measurement = %.2f, Index = %d, Status = %c\n",
                   i + 1, sensors[i].measurement, sensors[i].index, sensors[i].status_code);
        }
        free_sensor_data(sensors, num_sensors);
    }

    return 0;
}
