    // Initialize variables
    WeatherData* weatherData = NULL;
    *count = 0;

    // Simulate network latency and data fetching
    struct timeval start, end;
    gettimeofday(&start, NULL);
    sleep(1); // Simulating delay
    gettimeofday(&end, NULL);
    double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_usec - start.tv_usec) / 1000000.0;

    // Load JSON data from URL
    struct json_object* root = json_tokener_parse_file(json_url);
    if (!root) {
        fprintf(stderr, "Failed to parse JSON file\n");
        return NULL;
    }

    // Count the number of weather entries
    struct json_object* array;
    if (json_object_object_get_ex(root, "weather", &array)) {
        *count = json_object_array_length(array);
    } else {
        fprintf(stderr, "No 'weather' key found in JSON\n");
        json_object_put(root);
        return NULL;
    }

    // Allocate memory for weather data
    weatherData = (WeatherData*)malloc(*count * sizeof(WeatherData));
    if (!weatherData) {
        fprintf(stderr, "Memory allocation failed\n");
        json_object_put(root);
        return NULL;
    }

    // Populate weather data from JSON array
    for (int i = 0; i < *count; i++) {
        struct json_object* entry = json_object_array_get_idx(array, i);
        if (!entry) {
            fprintf(stderr, "Failed to get weather entry at index %d\n", i);
            free(weatherData);
            json_object_put(root);
            return NULL;
        }

        double temp;
        float hum;
        char loc[100];

        struct json_object* temp_obj;
        if (json_object_object_get_ex(entry, "temperature", &temp_obj)) {
            temp = json_object_double(temp_obj);
        } else {
            fprintf(stderr, "No 'temperature' key found in weather entry at index %d\n", i);
            free(weatherData);
            json_object_put(root);
            return NULL;
        }

        struct json_object* hum_obj;
        if (json_object_object_get_ex(entry, "humidity", &hum_obj)) {
            hum = json_object_float(hum_obj);
        } else {
            fprintf(stderr, "No 'humidity' key found in weather entry at index %d\n", i);
            free(weatherData);
            json_object_put(root);
            return NULL;
        }

        struct json_object* loc_obj;
        if (json_object_object_get_ex(entry, "location", &loc_obj)) {
            strncpy(loc, json_object_get_string(loc_obj), sizeof(loc) - 1);
        } else {
            fprintf(stderr, "No 'location' key found in weather entry at index %d\n", i);
            free(weatherData);
            json_object_put(root);
            return NULL;
        }

        // Assign values to the structure
        weatherData[i].temperature = temp;
        weatherData[i].humidity = hum;
        strncpy(weatherData[i].location, loc, sizeof(weatherData[i].location) - 1);
    }

    // Free JSON object
    json_object_put(root);

    return weatherData;
}

void free_weather_data(WeatherData* data, int count) {
    if (data) {
        free(data);
    }
}
