use std::process::{Command, Stdio};
use std::time::{Instant, SystemTime};
use std::os::unix::process::StdioExt;
use rustc_driver::{self, Compilation};

fn compile_with_logging() -> Result<(), Box<dyn std::error::Error>> {
    let start_time = Instant::now();
    let mut child = Command::new("rustc")
        .arg("--crate-type=bin")
        .arg("main.rs")
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;

    let stdout = child.stdout.take().unwrap();
    let stderr = child.stderr.take().unwrap();

    let mut reader_stdout = std::io::BufReader::new(stdout);
    let mut reader_stderr = std::io::BufReader::new(stderr);

    let end_time = Instant::now();
    let duration = end_time.duration_since(start_time).as_secs_f64();

    println!("Compilation took {} seconds", duration);

    let status = child.wait()?;

    if !status.success() {
        let mut error_message = String::new();
        reader_stderr.read_to_string(&mut error_message)?;
        eprintln!("Error during compilation:\n{}", error_message);
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    rustc_driver::catch_with_exit_code(|| {
        compile_with_logging()?;
        Ok::<_, Box<dyn std::error::Error>>(())
    })
}
