        mm->offsets[i] = rand();
        mm->keys[i] = rand() % 100; // Random key between 0 and 99
        mm->records[i].offset_ptr = &mm->offsets[i];
        mm->records[i].value = rand() % 100; // Random value between 0 and 99
    }

    return 0; // Success
}

void free_memory(memory_manager *mm) {
    free(mm->offsets);
    free(mm->keys);
    free(mm->records);
}

