use std::process::{Command, Stdio};
use std::time::{Instant, SystemTime};
use rustc_driver::catch_with_exit_code;

fn compile_rust_file(file_path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let start_time = Instant::now();
    let output = Command::new("rustc")
        .arg(file_path)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?
        .wait_with_output()?;

    let end_time = Instant::now();
    let duration = end_time.duration_since(start_time).unwrap();

    if output.status.success() {
        println!("Compilation successful in {:?}", duration);
    } else {
        eprintln!("Compilation failed with error:\n{}", String::from_utf8_lossy(&output.stderr));
    }

    Ok(())
}
