["```javascript
async function customAsyncReduce(arr, initialValue, callback, concurrencyLimit = 1) {
    if (!Array.isArray(arr) || !arr.every(Number.isFinite)) throw new Error('Input must be an array of numbers');
    if (typeof initialValue !== 'number') throw new Error('Initial value must be a number');

    const timeoutPromise = (ms) => new Promise(resolve => setTimeout(resolve, ms));
    let result = initialValue;
    let currentIndex = 0;

    for (let i = 0; i < arr.length; i++) {
        if (i % concurrencyLimit === 0) await Promise.all(Array.from({ length: concurrencyLimit }, (_, j) => timeoutPromise(500)));
        const index = currentIndex++;
        try {
            result = await callback(result, arr[index], index);
            console.log(`Index ${index}: Elapsed time ${Date.now() - startTime}ms, Accumulated value: ${result}`);
        } catch (error) {
            console.error(`Error at index ${index}:`, error);
            if (i < arr.length - 1) i--; // Retry the current element
        }
    }

    return result;
}

// Example usage:
const numbers = Array.from({ length: 10000 }, (_, i) => i + 1);
const startTime = Date.now();

customAsyncReduce(numbers, 0, async (acc, num, index) => {
    await timeoutPromise(5); // Simulate asynchronous operation
    return acc + num;
}, 2)
.then(result => console.log('Final result:', result))
.catch(error => console.error('Error:', error));
```

