#define MAX_RECORDS 1000
#define STRING_POOL_SIZE 50

typedef struct {
    long offset;
    int key;
    double data;
    char* string_ptr;
} Record;

Record** create_database(int num_records) {
    Record** db = (Record**)malloc(num_records * sizeof(Record*));
    if (!db) {
        fprintf(stderr, "Memory allocation failed for database.\n");
        return NULL;
    }

    srand(time(NULL));

    char* string_pool[STRING_POOL_SIZE];
    for (int i = 0; i < STRING_POOL_SIZE; ++i) {
        string_pool[i] = (char*)malloc(20 * sizeof(char));
        if (!string_pool[i]) {
            fprintf(stderr, "Memory allocation failed for string pool.\n");
            return NULL;
        }
        sprintf(string_pool[i], "String%d", i);
    }

    for (int i = 0; i < num_records; ++i) {
        db[i] = (Record*)malloc(sizeof(Record));
        if (!db[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            return NULL;
        }
        db[i]->offset = rand() % 1000000L;
        db[i]->key = rand() % 1000;
        db[i]->data = (double)rand() / RAND_MAX * 100.0;

        int string_index = rand() % STRING_POOL_SIZE;
        db[i]->string_ptr = strdup(string_pool[string_index]);
        if (!db[i]->string_ptr) {
            fprintf(stderr, "Memory allocation failed for string pointer.\n");
            return NULL;
        }
    }

    return db;
}

void free_database(Record** db, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        if (db[i]->string_ptr) {
            free(db[i]->string_ptr);
        }
        free(db[i]);
    }
    free(db);

    // Free string pool
    for (int i = 0; i < STRING_POOL_SIZE; ++i) {
        free(string_pool[i]);
    }
}

int main() {
    int num_records = MAX_RECORDS;
    Record** db = create_database(num_records);
    if (!db) {
        return 1;
    }

    // Use the database...

    free_database(db, num_records);

    return 0;
}
```

