#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays(int size, long** offsets, int** keys, record** records) {
    *offsets = safe_malloc(size * sizeof(long));
    *keys = safe_malloc(size * sizeof(int));
    *records = safe_malloc(size * sizeof(record));

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = i * 10;
        (*keys)[i] = rand() % 1000;
        (*records)[i].value = rand() % (MAX_RECORDS - MIN_RECORDS + 1) + MIN_RECORDS;
    }
}

void find_and_print_largest(int* keys, int size) {
    int largest = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }
    printf("Largest key: %d\n", largest);
}

void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    srand(time(NULL));
    int size;
    printf("Enter the number of elements: ");
    scanf("%d", &size);

    long* offsets;
    int* keys;
    record* records;

    initialize_arrays(size, &offsets, &keys, &records);

    find_and_print_largest(keys, size);

    free_memory(offsets, keys, records);

    return 0;
}
