record* initialize_pipeline(int offset_size, int key_size, int min_value, int max_value) {
    if (offset_size + key_size > MAX_ELEMENTS) {
        return NULL; // Exceeds maximum element limit
    }

    size_t total_memory = sizeof(long) * offset_size + sizeof(int) * key_size + sizeof(record) * (offset_size + key_size);
    if (total_memory > MAX_SYSTEM_MEMORY) {
        return NULL; // Exceeds system memory limit
    }

    long* offsets = malloc(sizeof(long) * offset_size);
    int* keys = malloc(sizeof(int) * key_size);
    record* records = malloc(sizeof(record) * (offset_size + key_size));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = rand() % 1000; // Example initialization
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % 1000; // Example initialization
    }

    for (int i = 0; i < offset_size + key_size; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].key = &keys[i % key_size];
        records[i].active = 1;
    }

    return records;
}
