void initialize_sensor_data(sensor_data **data, size_t count) {
    *data = (sensor_data *)malloc(count * sizeof(sensor_data));
    if (*data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        (*data)[i].measurement = ((double)rand() / RAND_MAX) * 100.0 - 50.0;
        (*data)[i].index = (short)(i % 256);
        (*data)[i].status_code = (*data)[i].measurement > 0 ? 'H' : 'L';
    }
}

void read_binary_file(const char *filename, float **floats, unsigned char **flags, item ***items, size_t *count) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        exit(EXIT_FAILURE);
    }

    fread(count, sizeof(size_t), 1, file);

    *floats = (float *)malloc(*count * sizeof(float));
    *flags = (unsigned char *)malloc(*count * sizeof(unsigned char));
    *items = (item **)malloc(*count * sizeof(item *));

    if (*floats == NULL || *flags == NULL || *items == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < *count; ++i) {
        fread(&(*floats)[i], sizeof(float), 1, file);
        fread(&(*flags)[i], sizeof(unsigned char), 1, file);

        (*items)[i] = (item *)malloc(sizeof(item));
        if ((*items)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            fclose(file);
            exit(EXIT_FAILURE);
        }
        fread((*items)[i], sizeof(item), 1, file);
    }

    fclose(file);
}

void cleanup(sensor_data *data, size_t count, float *floats, unsigned char *flags, item **items) {
    for (size_t i = 0; i < count; ++i) {
        free(items[i]);
    }
    free(data);
    free(floats);
    free(flags);
    free(items);
}

int main() {
    size_t count;
    sensor_data *sensor_data_array;
    float *float_values;
    unsigned char *flag_values;
    item **item_pointers;

    initialize_sensor_data(&sensor_data_array, 100);
    read_binary_file("data.bin", &float_values, &flag_values, &item_pointers, &count);

    // Process the data...

    cleanup(sensor_data_array, 100, float_values, flag_values, item_pointers);

    return 0;
}
