#define MAX_CONCURRENT_UPDATES 10000

typedef struct {
    double temperature;
    int humidity;
    char location[256];
} WeatherData;

WeatherData *weather_data[MAX_CONCURRENT_UPDATES];
int data_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* update_weather(void* arg) {
    // Simulate fetching and updating weather data
    pthread_mutex_lock(&mutex);
    if (data_count < MAX_CONCURRENT_UPDATES) {
        WeatherData *new_data = malloc(sizeof(WeatherData));
        new_data->temperature = 20.5; // Example temperature
        new_data->humidity = 60;      // Example humidity
        strcpy(new_data->location, "New York"); // Example location
        weather_data[data_count++] = new_data;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void free_weather_data() {
    for (int i = 0; i < data_count; i++) {
        free(weather_data[i]);
    }
    data_count = 0;
}

int main() {
    pthread_t threads[MAX_CONCURRENT_UPDATES];

    // Simulate concurrent updates
    for (int i = 0; i < MAX_CONCURRENT_UPDATES; i++) {
        pthread_create(&threads[i], NULL, update_weather, NULL);
    }

    // Wait for all threads to complete
    for (int i = 0; i < MAX_CONCURRENT_UPDATES; i++) {
        pthread_join(threads[i], NULL);
    }

    free_weather_data();
    return 0;
}
