#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_RECORDS 1000
#define DEFAULT_STRING_SIZE 256

typedef struct Record {
    char* string;
    int key;
    double* doubles;
    size_t double_count;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node* head = NULL;
size_t current_records = 0;
size_t max_records = MAX_RECORDS;

void initialize_record(Record* rec, const char* initial_string) {
    rec->string = (char*)malloc(DEFAULT_STRING_SIZE * sizeof(char));
    if (!rec->string) {
        fprintf(stderr, "Memory allocation failed for string.\n");
        exit(EXIT_FAILURE);
    }
    strcpy(rec->string, initial_string ? initial_string : "");
    rec->key = current_records + 1;
    rec->doubles = NULL;
    rec->double_count = 0;
}

void allocate_doubles(Record* rec, size_t count) {
    rec->doubles = (double*)calloc(count, sizeof(double));
    if (!rec->doubles) {
        fprintf(stderr, "Memory allocation failed for doubles array.\n");
        exit(EXIT_FAILURE);
    }
    rec->double_count = count;
}

void append_record(const char* initial_string, size_t double_count) {
    if (current_records >= max_records) {
        fprintf(stderr, "Maximum number of records reached.\n");
        return;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed for new node.\n");
        exit(EXIT_FAILURE);
    }

    initialize_record(&new_node->record, initial_string);
    allocate_doubles(&new_node->record, double_count);

    new_node->next = head;
    head = new_node;
    current_records++;
}

void log_memory_usage() {
    printf("Current records: %zu\n", current_records);
    // Add more logging details as needed
}

void serialize_collection(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return;
    }

    Node* current = head;
    while (current) {
        fwrite(&current->record, sizeof(Record), 1, file);
        fwrite(current->record.doubles, sizeof(double), current->record.double_count, file);
        current = current->next;
    }

    fclose(file);
}

void free_collection() {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current->record.string);
        free(current->record.doubles);
        free(current);
        current = next;
    }
    head = NULL;
    current_records = 0;
}
