#define DEFAULT_STRING_SIZE 1024

typedef struct {
    char* string;
    int key;
    double* array;
    size_t array_size;
} Record;

Record* create_record(size_t array_size) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->string = (char*)calloc(DEFAULT_STRING_SIZE, sizeof(char));
    if (!record->string) {
        free(record);
        return NULL;
    }

    record->key = 0; // Unique sequential number will be assigned later
    record->array_size = array_size;
    record->array = (double*)calloc(array_size, sizeof(double));
    if (!record->array) {
        free(record->string);
        free(record);
        return NULL;
    }

    return record;
}

void populate_record(Record* record, double min_val, double max_val) {
    srand(time(NULL)); // Seed for random number generation
    for (size_t i = 0; i < record->array_size; ++i) {
        record->array[i] = min_val + (max_val - min_val) * ((double)rand() / RAND_MAX);
    }
}

void serialize_record(Record* record, FILE* file) {
    if (!file || !record) return;

    size_t string_len = strlen(record->string);
    fwrite(&string_len, sizeof(size_t), 1, file);
    fwrite(record->string, sizeof(char), string_len, file);

    fwrite(&record->key, sizeof(int), 1, file);
    fwrite(record->array, sizeof(double), record->array_size, file);
}

void deserialize_record(Record* record, FILE* file) {
    if (!file || !record) return;

    size_t string_len;
    fread(&string_len, sizeof(size_t), 1, file);
    record->string = (char*)realloc(record->string, string_len + 1);
    fread(record->string, sizeof(char), string_len, file);
    record->string[string_len] = '\0';

    fread(&record->key, sizeof(int), 1, file);

    if (record->array_size != record->array) {
        free(record->array);
    }
    record->array_size = record->array;
    fread(record->array, sizeof(double), record->array_size, file);
}

void compress_records(const char* input_file, const char* output_file) {
    // Implement compression logic here
}

void* thread_function(void* arg) {
    // Thread function implementation for concurrent access
    return NULL;
}

int main() {
    pthread_t threads[10];
    Record records[10];

    for (int i = 0; i < 10; ++i) {
        records[i] = *create_record(100);
        populate_record(&records[i], 0.0, 1.0);

        if (pthread_create(&threads[i], NULL, thread_function, &records[i])) {
            fprintf(stderr, "Error creating thread %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);

        FILE* file = fopen("records.bin", "ab");
        if (!file) {
            fprintf(stderr, "Error opening file\n");
            return 1;
        }
        serialize_record(&records[i], file);
        fclose(file);
    }

    compress_records("records.bin", "compressed_records.bin");

    for (int i = 0; i < 10; ++i) {
        free(records[i].string);
        free(records[i].array);
    }

    return 0;
}
