typedef struct {
    char* string;
    int key;
    double* doubles;
    size_t doubles_size;
} Record;

Record records[MAX_RECORDS];
size_t record_count = 0;
size_t memory_pool_size = 10 * 1024 * 1024; // 10MB
char* memory_pool = NULL;
size_t memory_pool_offset = 0;

void initialize_record(Record* rec, size_t doubles_size) {
    rec->string = (char*)memory_pool + memory_pool_offset;
    memory_pool_offset += DEFAULT_STRING_SIZE;
    strcpy(rec->string, "");
    rec->key = record_count + 1;
    rec->doubles = (double*)(memory_pool + memory_pool_offset);
    memory_pool_offset += doubles_size * sizeof(double);
    memset(rec->doubles, 0, doubles_size * sizeof(double));
    rec->doubles_size = doubles_size;
}

void add_record(size_t doubles_size) {
    if (record_count >= MAX_RECORDS || memory_pool_offset + doubles_size * sizeof(double) > memory_pool_size) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    initialize_record(&records[record_count], doubles_size);
    record_count++;
}

void serialize_records(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(records, sizeof(Record), record_count, file);
    fclose(file);
}

int main() {
    add_record(10);
    add_record(20);

    serialize_records("records.dat");

    return 0;
}
