#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct entry {
    char* key;
    double value;
} Entry;

typedef struct hash_table {
    size_t capacity;
    size_t size;
    Entry** buckets;
    pthread_mutex_t lock;
} HashTable;

size_t hash_function(const char* key) {
    // Simple hash function for demonstration purposes
    size_t hash = 0;
    while (*key) {
        hash = (hash * 31) + *key++;
    }
    return hash % capacity;
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->capacity = initial_capacity;
    table->size = 0;
    table->buckets = calloc(initial_capacity, sizeof(Entry*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Entry* entry = table->buckets[i];
        while (entry) {
            Entry* next = entry->next;
            free(entry->key);
            free(entry);
            entry = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int insert_entry(HashTable* table, const char* key, double value) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(key);
    Entry* entry = table->buckets[index];

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            // Duplicate key found, update the value
            entry->value = value;
            pthread_mutex_unlock(&table->lock);
            return 1; // Key already exists
        }
        entry = entry->next;
    }

    // Allocate new entry and insert at the beginning of the bucket list
    Entry* new_entry = malloc(sizeof(Entry));
    if (!new_entry) {
        pthread_mutex_unlock(&table->lock);
        return -1; // Memory allocation failed
    }

    new_entry->key = strdup(key);
    new_entry->value = value;
    new_entry->next = table->buckets[index];
    table->buckets[index] = new_entry;

    ++table->size;

    pthread_mutex_unlock(&table->lock);
    return 0; // Key inserted successfully
}

double lookup_entry(HashTable* table, const char* key) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(key);
    Entry* entry = table->buckets[index];

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            double value = entry->value;
            pthread_mutex_unlock(&table->lock);
            return value; // Key found
        }
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->lock);
    return -1.0; // Key not found
}

int delete_entry(HashTable* table, const char* key) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash_function(key);
    Entry** prev = &table->buckets[index];
    Entry* entry = *prev;

    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            *prev = entry->next;
            free(entry->key);
            free(entry);
            --table->size;
            pthread_mutex_unlock(&table->lock);
            return 1; // Key deleted successfully
        }
        prev = &entry->next;
        entry = entry->next;
    }

    pthread_mutex_unlock(&table->lock);
    return 0; // Key not found
}
