#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 16

typedef struct Entry {
    char* key;
    double value;
} Entry;

typedef struct HashTable {
    Entry** buckets;
    size_t capacity;
    size_t size;
} HashTable;

unsigned long hash(const char* key) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Entry**)calloc(INITIAL_CAPACITY, sizeof(Entry*));
    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    return table;
}

void insert_entry(HashTable* table, const char* key, double value) {
    unsigned long index = hash(key) % table->capacity;
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    entry->key = strdup(key);
    entry->value = value;

    while (table->buckets[index] != NULL) {
        if (strcmp(table->buckets[index]->key, key) == 0) {
            free(entry->key);
            free(entry);
            return; // Duplicate key
        }
        index = (index + 1) % table->capacity;
    }

    table->buckets[index] = entry;
    table->size++;
}

Entry* search_entry(HashTable* table, const char* key) {
    unsigned long index = hash(key) % table->capacity;
    while (table->buckets[index] != NULL) {
        if (strcmp(table->buckets[index]->key, key) == 0) {
            return table->buckets[index];
        }
        index = (index + 1) % table->capacity;
    }
    return NULL; // Key not found
}

void iterate_entries(HashTable* table, void (*callback)(const char*, double)) {
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->buckets[i] != NULL) {
            callback(table->buckets[i]->key, table->buckets[i]->value);
        }
    }
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->buckets[i] != NULL) {
            free(table->buckets[i]->key);
            free(table->buckets[i]);
        }
    }
    free(table->buckets);
    free(table);
}
