        if (strlen(records[i]->name) > strlen(longest_name)) {
            longest_name = records[i]->name;
        }
        if (records[i]->status && !true_status) {
            true_status = true;
        }
    }

    printf("Largest integer: %d\n", max_int);
    printf("Largest double: %f\n", max_double);
    printf("Longest name: %s\n", longest_name);
    printf("True status flag: %d\n", true_status);

    if (longest_name) {
        free(longest_name);
    }
}

int main() {
    initialize_records();
    read_input();
    read_external_data_source();
    find_and_print_largest_values();
    free_records();

    return 0;
}
