#include <pthread.h>

typedef struct {
    float value;
    char type;
    unsigned long timestamp;
} Measurement;

typedef struct {
    Measurement *data;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MeasurementCollection;

MeasurementCollection* init_measurement_collection(size_t initial_capacity) {
    MeasurementCollection *collection = (MeasurementCollection*)malloc(sizeof(MeasurementCollection));
    if (!collection) return NULL;

    collection->data = (Measurement*)calloc(initial_capacity, sizeof(Measurement));
    if (!collection->data) {
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_measurement_collection(MeasurementCollection *collection) {
    if (collection) {
        pthread_mutex_lock(&collection->lock);
        free(collection->data);
        pthread_mutex_unlock(&collection->lock);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

int load_measurements_from_file(MeasurementCollection *collection, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1;

    pthread_mutex_lock(&collection->lock);

    while (collection->count < collection->capacity && fscanf(file, "%f %c %lu", 
        &collection->data[collection->count].value, 
        &collection->data[collection->count].type, 
        &collection->data[collection->count].timestamp) == 3) {
        collection->count++;
    }

    pthread_mutex_unlock(&collection->lock);
    fclose(file);

    return 0;
}

int main() {
    MeasurementCollection *collection = init_measurement_collection(1024);
    if (!collection) {
        fprintf(stderr, "Failed to initialize measurement collection.\n");
        return EXIT_FAILURE;
    }

    int result = load_measurements_from_file(collection, "measurements.txt");
    if (result != 0) {
        fprintf(stderr, "Failed to load measurements from file.\n");
        destroy_measurement_collection(collection);
        return EXIT_FAILURE;
    }

    // Process the collection...

    destroy_measurement_collection(collection);
    return EXIT_SUCCESS;
}
