#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <pthread.h>

typedef struct UserProfile {
    unsigned long userId;
    char username[256];
    char** emails;
    int emailCount;
} UserProfile;

typedef struct UserSet {
    UserProfile* profiles;
    int profileCount;
    pthread_mutex_t lock;
} UserSet;

UserSet* initializeUserSet(const char* directory) {
    UserSet* userSet = (UserSet*)malloc(sizeof(UserSet));
    if (!userSet) return NULL;

    userSet->profiles = NULL;
    userSet->profileCount = 0;
    pthread_mutex_init(&userSet->lock, NULL);

    DIR* dir = opendir(directory);
    if (!dir) {
        free(userSet);
        return NULL;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strstr(entry->d_name, ".profile")) {
            UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
            if (!profile) continue;

            // Read user data from file
            FILE* file = fopen(entry->d_name, "r");
            if (!file) {
                free(profile);
                continue;
            }

            fscanf(file, "%lu %255s", &profile->userId, profile->username);

            // Read emails
            int emailCount = 0;
            char** emails = (char**)malloc(10 * sizeof(char*));
            if (!emails) {
                fclose(file);
                free(profile);
                continue;
            }

            while (fscanf(file, "%255s", emails[emailCount]) != EOF) {
                emailCount++;
                if (emailCount % 10 == 0) {
                    emails = realloc(emails, (emailCount + 10) * sizeof(char*));
                }
            }

            emails[emailCount] = NULL;
            profile->emails = emails;
            profile->emailCount = emailCount;

            fclose(file);

            // Add to user set
            userSet->profileCount++;
            userSet->profiles = realloc(userSet->profiles, userSet->profileCount * sizeof(UserProfile));
            if (userSet->profiles) {
                memcpy(&userSet->profiles[userSet->profileCount - 1], profile, sizeof(UserProfile));
            } else {
                free(profile);
            }
        }
    }

    closedir(dir);
    return userSet;
}

void destroyUserSet(UserSet* userSet) {
    if (!userSet) return;

    for (int i = 0; i < userSet->profileCount; i++) {
        UserProfile* profile = &userSet->profiles[i];
        free(profile->emails);
        free(profile);
    }

    free(userSet->profiles);
    pthread_mutex_destroy(&userSet->lock);
    free(userSet);
}

void getUserProfile(UserSet* userSet, unsigned long userId) {
    pthread_mutex_lock(&userSet->lock);
    for (int i = 0; i < userSet->profileCount; i++) {
        if (userSet->profiles[i].userId == userId) {
            // Process profile
            break;
        }
    }
    pthread_mutex_unlock(&userSet->lock);
}
