#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/rsa.h>
#include <openssl/sha.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    double value;
    char* str;
} Record;

void DataHandler() {
    // Initialize OpenSSL
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    // Add AES and Camellia ciphers
    EVP_add_cipher(EVP_aes_256_cbc());
    EVP_add_cipher(EVP_camellia_128_ecb());

    // Add MD5 and SHA digest algorithms
    EVP_add_digest(EVP_md5());
    EVP_add_digest(EVP_sha256());

    // Add RSA with SHA1
    EVP_add_digest_alias("RSA-SHA1", "sha1WithRSAEncryption");

    // Initialize semaphore for multi-threaded environment
    sem_t* sem = sem_open("/my_semaphore", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        return;
    }

    // Load and deserialize data from binary file
    FILE* file = fopen("data.bin", "rb");
    if (!file) {
        perror("Failed to open file");
        sem_close(sem);
        sem_unlink("/my_semaphore");
        return;
    }

    Record* records = NULL;
    size_t num_records = 0;
    while (1) {
        Record record;
        if (fread(&record, sizeof(Record), 1, file) != 1) {
            break;
        }
        records = realloc(records, (num_records + 1) * sizeof(Record));
        records[num_records++] = record;
    }

    fclose(file);

    // Handle potential errors during deserialization
    if (!records) {
        perror("Failed to allocate memory for records");
        sem_close(sem);
        sem_unlink("/my_semaphore");
        return;
    }

    // Secure cryptographic operations
    unsigned char key[32];
    unsigned char iv[16];
    RAND_bytes(key, sizeof(key));
    RAND_bytes(iv, sizeof(iv));

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        perror("Failed to create cipher context");
        free(records);
        sem_close(sem);
        sem_unlink("/my_semaphore");
        return;
    }

    // Encrypt records
    for (size_t i = 0; i < num_records; ++i) {
        EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv);
        if (!EVP_EncryptUpdate(ctx, (unsigned char*)records[i].str, &num_records, (const unsigned char*)records[i].str, strlen(records[i].str))) {
            perror("Failed to encrypt record");
            EVP_CIPHER_CTX_free(ctx);
            free(records);
            sem_close(sem);
            sem_unlink("/my_semaphore");
            return;
        }
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
    free(records);
    sem_close(sem);
    sem_unlink("/my_semaphore");
}
