#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    double measurement;
} data_record;

typedef struct {
    data_record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} dynamic_collection;

dynamic_collection* init_collection(size_t initial_capacity) {
    dynamic_collection *collection = (dynamic_collection*)malloc(sizeof(dynamic_collection));
    if (!collection) {
        perror("Failed to allocate memory for collection");
        return NULL;
    }

    collection->records = (data_record*)calloc(initial_capacity, sizeof(data_record));
    if (!collection->records) {
        perror("Failed to allocate memory for records");
        free(collection);
        return NULL;
    }

    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_collection(dynamic_collection *collection) {
    if (collection->records) {
        free(collection->records);
    }
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_record(dynamic_collection *collection, data_record record) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        data_record *new_records = (data_record*)realloc(collection->records, new_capacity * sizeof(data_record));
        if (!new_records) {
            perror("Failed to reallocate memory for records");
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->size++] = record;

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

void* iterate_collection(void *arg) {
    dynamic_collection *collection = (dynamic_collection*)arg;
    for (size_t i = 0; i < collection->size; ++i) {
        // Process each record
        printf("Offset: %ld, Key: %d, Measurement: %f\n", 
               collection->records[i].offset,
               collection->records[i].key,
               collection->records[i].measurement);
    }
    return NULL;
}

int main() {
    dynamic_collection *collection = init_collection(1024);
    if (!collection) {
        return 1;
    }

    data_record record = {1, 2, 3.14};
    add_record(collection, record);

    pthread_t thread;
    pthread_create(&thread, NULL, iterate_collection, collection);
    pthread_join(thread, NULL);

    destroy_collection(collection);
    return 0;
}
