typedef struct {
    float measurement_value;
    char unit[10];
    unsigned long timestamp;
    int status_code;
} Measurement;

Measurement* read_measurements(const char* filename, const char* mode, int compression_type) {
    FILE* file = fopen(filename, mode);
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Determine the file size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    // Allocate memory for the measurement array
    Measurement* measurements = (Measurement*)malloc(file_size * sizeof(Measurement));
    if (!measurements) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    // Read data from file into the measurement array
    size_t bytes_read = fread(measurements, sizeof(Measurement), file_size / sizeof(Measurement), file);
    if (bytes_read != file_size / sizeof(Measurement)) {
        perror("Failed to read file");
        free(measurements);
        fclose(file);
        return NULL;
    }

    // Close the file
    fclose(file);

    return measurements;
}

int main() {
    const char* filename = "measurements.dat";
    const char* mode = "rb";
    int compression_type = Z_NO_COMPRESSION;

    Measurement* measurements = read_measurements(filename, mode, compression_type);
    if (measurements) {
        // Process the measurements
        free(measurements);
    }

    return 0;
}
