#include <string.h>

#define MAX_INPUT_SIZE 1024

typedef struct {
    int value;
} record;

void log_message(const char *message) {
    printf("%s\n", message);
}

int* read_integers(int *count) {
    char input[MAX_INPUT_SIZE];
    if (fgets(input, sizeof(input), stdin) == NULL) {
        perror("Failed to read input");
        return NULL;
    }

    *count = 0;
    int *keys = malloc(MAX_INPUT_SIZE * sizeof(int));
    if (keys == NULL) {
        perror("Memory allocation failed for keys array");
        return NULL;
    }

    char *token = strtok(input, " ");
    while (token != NULL && *count < MAX_INPUT_SIZE) {
        keys[*count] = atoi(token);
        (*count)++;
        token = strtok(NULL, " ");
    }

    if (*count == 0) {
        free(keys);
        return NULL;
    }

    return keys;
}

void find_and_print_largest(int *keys, int count) {
    if (count == 0) {
        log_message("No integers to process");
        return;
    }

    int largest = keys[0];
    for (int i = 1; i < count; i++) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

void free_memory(int *keys, record *records, int count) {
    free(keys);
    for (int i = 0; i < count; i++) {
        free(records[i].value);
    }
    free(records);
}

int main() {
    int count;
    int *keys = read_integers(&count);
    if (keys == NULL) {
        return EXIT_FAILURE;
    }

    record *records = malloc(count * sizeof(record));
    if (records == NULL) {
        perror("Memory allocation failed for records array");
        free_memory(keys, NULL, count);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < count; i++) {
        records[i].value = malloc(sizeof(int));
        if (records[i].value == NULL) {
            perror("Memory allocation failed for record value");
            free_memory(keys, records, i);
            return EXIT_FAILURE;
        }
        *(records[i].value) = keys[i];
    }

    find_and_print_largest(keys, count);

    free_memory(keys, records, count);
    return EXIT_SUCCESS;
}
