#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ENTRIES 1000

typedef struct node {
    char value;
    struct node *left, *right;
} Node;

typedef struct entry {
    double number;
    char* string;
    Node* tree_node;
} Entry;

Node* createNode(char value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->value = value;
    newNode->left = newNode->right = NULL;
    return newNode;
}

void insertNode(Node** root, char value) {
    if (*root == NULL) {
        *root = createNode(value);
        return;
    }

    if (value < (*root)->value)
        insertNode(&(*root)->left, value);
    else
        insertNode(&(*root)->right, value);
}

void inOrderTraversal(Node* root) {
    if (root != NULL) {
        inOrderTraversal(root->left);
        printf("%c ", root->value);
        inOrderTraversal(root->right);
    }
}

int main() {
    Entry entries[MAX_ENTRIES];
    int count = 0;

    while (scanf("%lf %s", &entries[count].number, entries[count].string) == 2) {
        if (count >= MAX_ENTRIES - 1) {
            fprintf(stderr, "Too many entries\n");
            break;
        }
        entries[count].tree_node = NULL;
        count++;
    }

    Node* root = NULL;
    for (int i = 0; i < count; i++) {
        insertNode(&root, entries[i].string[0]);
    }

    inOrderTraversal(root);
    printf("\n");

    // Free allocated memory
    for (int i = 0; i < count; i++) {
        free(entries[i].string);
    }
    Node* current = root;
    while (current != NULL) {
        Node* temp = current;
        if (current->left == NULL)
            current = current->right;
        else {
            Node* predecessor = current->left;
            while (predecessor->right != NULL && predecessor->right != current)
                predecessor = predecessor->right;

            if (predecessor->right == NULL) {
                predecessor->right = current;
                current = current->left;
            } else {
                predecessor->right = NULL;
                free(temp);
            }
        }
    }

    return 0;
}
