    pthread_mutex_init(&list->lock, NULL);
    logMessage("Transaction list initialized");
    return list;
}

void addTransaction(TransactionList *list, Item **items, int itemCount) {
    pthread_mutex_lock(&list->lock);
    Transaction *newTransaction = (Transaction*)malloc(sizeof(Transaction));
    newTransaction->items = items;
    newTransaction->itemCount = itemCount;
    newTransaction->next = list->head;
    list->head = newTransaction;
    logMessage("Transaction added");
    pthread_mutex_unlock(&list->lock);
}

void serializePeriodically(TransactionList *list, const char *databasePath, int interval) {
    while (1) {
        sleep(interval);
        if (!serializeTransactions(list, databasePath)) {
            logMessage("Serialization failed");
        }
    }
}

void freeTransaction(Transaction *transaction) {
    for (int i = 0; i < transaction->itemCount; i++) {
        free(transaction->items[i]->name);
        free(transaction->items[i]);
    }
    free(transaction->items);
    free(transaction);
}

void freeTransactionList(TransactionList *list) {
    pthread_mutex_lock(&list->lock);
    Transaction *current = list->head;
    while (current != NULL) {
        Transaction *next = current->next;
        freeTransaction(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int main() {
    // Example usage
    TransactionList *transactionList = createTransactionList();
    pthread_t serializeThread;
    pthread_create(&serializeThread, NULL, (void*)serializePeriodically, transactionList, "database.db", 60);

    // Add transactions and handle other operations

    pthread_join(serializeThread, NULL);
    freeTransactionList(transactionList);
    return 0;
}
