typedef struct {
    long offset;
    int key;
    double value;
} dataRecord;

typedef struct {
    dataRecord *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} cache;

cache* createCache(size_t initialCapacity) {
    cache *c = (cache*)malloc(sizeof(cache));
    if (!c) {
        perror("Failed to allocate memory for cache");
        return NULL;
    }
    c->records = (dataRecord*)calloc(initialCapacity, sizeof(dataRecord));
    if (!c->records) {
        perror("Failed to allocate memory for records");
        free(c);
        return NULL;
    }
    c->capacity = initialCapacity;
    c->size = 0;
    pthread_mutex_init(&c->lock, NULL);
    printf("Cache created with capacity %zu\n", initialCapacity);
    return c;
}

void destroyCache(cache *c) {
    if (c) {
        free(c->records);
        pthread_mutex_destroy(&c->lock);
        free(c);
        printf("Cache destroyed\n");
    }
}

int addRecord(cache *c, dataRecord record) {
    pthread_mutex_lock(&c->lock);
    if (c->size >= c->capacity) {
        size_t newCapacity = c->capacity * 2;
        dataRecord *newRecords = (dataRecord*)realloc(c->records, newCapacity * sizeof(dataRecord));
        if (!newRecords) {
            perror("Failed to reallocate memory for records");
            pthread_mutex_unlock(&c->lock);
            return -1;
        }
        c->records = newRecords;
        c->capacity = newCapacity;
    }
    c->records[c->size++] = record;
    pthread_mutex_unlock(&c->lock);
    printf("Record added\n");
    return 0;
}

