void initialize_arrays(size_t offset_size, size_t key_size, int min_val, int max_val) {
    long* offsets = (long*)safe_malloc(offset_size * sizeof(long));
    int* keys = (int*)safe_malloc(key_size * sizeof(int));
    Record* records = (Record*)safe_malloc(key_size * sizeof(Record));

    // Initialize arrays
    for (size_t i = 0; i < key_size; ++i) {
        offsets[i] = i * 10;
        keys[i] = rand() % (max_val - min_val + 1) + min_val;
        records[i].value = keys[i];
    }

    // Log memory events
    log_memory_event("Allocated offsets", offset_size * sizeof(long));
    log_memory_event("Allocated keys", key_size * sizeof(int));
    log_memory_event("Allocated records", key_size * sizeof(Record));

    // Verify integrity of arrays
    for (size_t i = 0; i < key_size; ++i) {
        if (keys[i] < min_val || keys[i] > max_val) {
            fprintf(stderr, "Integrity check failed: Key out of range\n");
            exit(EXIT_FAILURE);
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
}

