#define MAX_INPUT_SIZE 1024

typedef struct node {
    char value;
    struct node *left, *right;
} Node;

typedef struct entry {
    double number;
    char *str;
    Node *node;
    void *external_resource;
} Entry;

typedef struct external_resource {
    // Define the structure of an external resource handle
} ExternalResource;

Node* create_node(char value) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed for node\n");
        exit(EXIT_FAILURE);
    }
    node->value = value;
    node->left = node->right = NULL;
    return node;
}

void insert_node(Node** root, char value) {
    if (*root == NULL) {
        *root = create_node(value);
    } else if (value < (*root)->value) {
        insert_node(&(*root)->left, value);
    } else {
        insert_node(&(*root)->right, value);
    }
}

void in_order_traversal(Node* root) {
    if (root != NULL) {
        in_order_traversal(root->left);
        printf("%c ", root->value);
        in_order_traversal(root->right);
    }
}

int tree_height(Node* node) {
    if (node == NULL)
        return 0;
    else {
        int left_height = tree_height(node->left);
        int right_height = tree_height(node->right);
        if (left_height > right_height)
            return (left_height + 1);
        else
            return (right_height + 1);
    }
}

int count_leaf_nodes(Node* node) {
    if (node == NULL)
        return 0;
    if (node->left == NULL && node->right == NULL)
        return 1;
    else
        return count_leaf_nodes(node->left) + count_leaf_nodes(node->right);
}

void free_tree(Node* root) {
    if (root != NULL) {
        free_tree(root->left);
        free_tree(root->right);
        free(root);
    }
}

int main() {
    Node *root = NULL;
    char input[MAX_INPUT_SIZE];
    double number;
    char str[MAX_INPUT_SIZE];

    printf("Enter a list of numbers and strings (e.g., 1.5 hello): ");
    fgets(input, MAX_INPUT_SIZE, stdin);

    char *token = strtok(input, " ");
    while (token != NULL) {
        if (sscanf(token, "%lf", &number) == 1) {
            // Handle double value
        } else {
            sscanf(token, "%s", str);
            insert_node(&root, str[0]);
        }
        token = strtok(NULL, " ");
    }

    printf("In-order traversal: ");
    in_order_traversal(root);
    printf("\n");

    int height = tree_height(root);
    printf("Height of the tree: %d\n", height);

    int leaf_nodes = count_leaf_nodes(root);
    printf("Number of leaf nodes: %d\n", leaf_nodes);

    free_tree(root);

    return 0;
}
