#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_BATCHES 100
#define MAX_TRANSACTIONS_PER_BATCH 1000
#define BALANCE_LIMIT 10000.0

typedef struct {
    int id;
    double value;
    char description[256];
    double balance;
    int batch_id;
} Transaction;

typedef struct {
    void* memory_pool;
    size_t pool_size;
    size_t used_memory;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0, 0};

void init_memory_pool(size_t initial_size) {
    memory_pool.memory_pool = malloc(initial_size);
    if (memory_pool.memory_pool == NULL) {
        fprintf(stderr, "Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
    memory_pool.pool_size = initial_size;
    memory_pool.used_memory = 0;
}

void* allocate_from_pool(size_t size) {
    if (memory_pool.used_memory + size > memory_pool.pool_size) {
        // Resize the memory pool
        memory_pool.pool_size *= 2;
        memory_pool.memory_pool = realloc(memory_pool.memory_pool, memory_pool.pool_size);
        if (memory_pool.memory_pool == NULL) {
            fprintf(stderr, "Failed to resize memory pool\n");
            exit(EXIT_FAILURE);
        }
    }
    void* ptr = (char*)memory_pool.memory_pool + memory_pool.used_memory;
    memory_pool.used_memory += size;
    return ptr;
}

void free_memory_pool() {
    free(memory_pool.memory_pool);
    memory_pool.memory_pool = NULL;
    memory_pool.pool_size = 0;
    memory_pool.used_memory = 0;
}

Transaction* create_transactions(int batch_id, int num_transactions) {
    Transaction* transactions = (Transaction*)allocate_from_pool(num_transactions * sizeof(Transaction));
    if (transactions == NULL) {
        fprintf(stderr, "Failed to allocate transaction array\n");
        return NULL;
    }
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].id = batch_id * MAX_TRANSACTIONS_PER_BATCH + i;
        transactions[i].value = rand() % 1000.0 / 100.0;
        snprintf(transactions[i].description, sizeof(transactions[i].description), "Transaction %d", transactions[i].id);
        transactions[i].balance = rand() % (int)(BALANCE_LIMIT * 100) / 100.0;
        transactions[i].batch_id = batch_id;
    }
    return transactions;
}

void free_transactions(Transaction* transactions, int num_transactions) {
    // No need to free individual elements as they are part of the memory pool
}

int main() {
    init_memory_pool(1024 * 1024); // Initial size of 1MB

    Transaction* batch1_transactions = create_transactions(1, MAX_TRANSACTIONS_PER_BATCH);
    if (batch1_transactions == NULL) {
        fprintf(stderr, "Failed to create transactions for batch 1\n");
        free_memory_pool();
        return EXIT_FAILURE;
    }

    // Process transactions...

    free_transactions(batch1_transactions, MAX_TRANSACTIONS_PER_BATCH);

    free_memory_pool();

    return EXIT_SUCCESS;
}
