// Function to generate a unique transaction ID
char* generateTransactionID() {
    time_t now = time(NULL);
    srand(now);
    int randomNum = rand();
    char* id = (char*)malloc(20 * sizeof(char));
    sprintf(id, "%ld_%d", now, randomNum);
    return id;
}

// Function to initialize a transaction
Transaction* initTransaction(double amount, float minLat, float maxLat, float minLong, float maxLong) {
    Transaction* trans = (Transaction*)malloc(sizeof(Transaction));
    if (trans == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    trans->amount = amount;
    trans->id = generateTransactionID();
    trans->location.x = minLat + (rand() / (float)RAND_MAX * (maxLat - minLat));
    trans->location.y = minLong + (rand() / (float)RAND_MAX * (maxLong - minLong));

    // Simulate transaction status
    if (amount > 100.0) {
        trans->status = FAILURE;
    } else {
        trans->status = SUCCESS;
    }

    strcpy(trans->metadata.details, "Sample Transaction");
    trans->metadata.count = 1;

    return trans;
}

// Function to free a transaction
void freeTransaction(Transaction* trans) {
    if (trans != NULL) {
        free(trans->id);
        free(trans);
    }
