#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void log_message(const char* message) {
    printf("%s\n", message);
}

int find(int* parent, int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void union_sets(int* parent, int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);

    if (rootX != rootY) {
        parent[rootX] = rootY;
    }
}

int are_disjoint(int* parent, int i, int j) {
    return find(parent, i) != find(parent, j);
}

void process_keys(int* keys, record** records, int size, int min_val, int max_val) {
    int* parent = (int*)malloc(size * sizeof(int));
    if (!parent) {
        log_message("Memory allocation failed for parent array");
        return;
    }

    for (int i = 0; i < size; ++i) {
        parent[i] = -1;
        records[i]->value = rand() % (max_val - min_val + 1) + min_val;
    }

    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < size; ++i) {
        for (int j = i + 1; j < size; ++j) {
            if (are_disjoint(parent, keys[i], keys[j])) {
                start = clock();
                union_sets(parent, keys[i], keys[j]);
                end = clock();
                cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;
                printf("Disjoint pair (%d, %d) took %.3f seconds\n", keys[i], keys[j], cpu_time_used);
            }
        }
    }

    free(parent);
}

int main() {
    int size, min_val, max_val;
    scanf("%d %d %d", &size, &min_val, &max_val);

    if (size <= 0) {
        log_message("Invalid array size");
        return 1;
    }

    record** records = (record**)malloc(size * sizeof(record*));
    int* keys = (int*)malloc(size * sizeof(int));

    if (!records || !keys) {
        log_message("Memory allocation failed for arrays");
        free(records);
        free(keys);
        return 1;
    }

    for (int i = 0; i < size; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            log_message("Memory allocation failed for record");
            for (int j = 0; j < i; ++j)
                free(records[j]);
            free(records);
            free(keys);
            return 1;
        }
    }

    srand(time(0));

    for (int i = 0; i < size; ++i) {
        scanf("%d", &keys[i]);
    }

    process_keys(keys, records, size, min_val, max_val);

    for (int i = 0; i < size; ++i)
        free(records[i]);

    free(records);
    free(keys);

    return 0;
}
