#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct LogRecord {
    int key;
    char *message;
    size_t length;
    bool status;
} LogRecord;

typedef struct LoggingSystem {
    LogRecord **records;
    size_t totalRecords;
    size_t maxMessageLength;
    pthread_mutex_t lock;
} LoggingSystem;

LoggingSystem* create_logging_system(size_t totalRecords, size_t maxMessageLength, int seed) {
    LoggingSystem *system = (LoggingSystem*)malloc(sizeof(LoggingSystem));
    if (!system) return NULL;

    system->totalRecords = totalRecords;
    system->maxMessageLength = maxMessageLength;
    pthread_mutex_init(&system->lock, NULL);

    system->records = (LogRecord**)malloc(totalRecords * sizeof(LogRecord*));
    if (!system->records) {
        free(system);
        return NULL;
    }

    srand(seed);
    for (size_t i = 0; i < totalRecords; ++i) {
        LogRecord *record = (LogRecord*)malloc(sizeof(LogRecord));
        if (!record) {
            // Clean up partially allocated resources
            for (size_t j = 0; j < i; ++j) free(system->records[j]);
            free(system->records);
            pthread_mutex_destroy(&system->lock);
            free(system);
            return NULL;
        }

        record->key = rand() % totalRecords + 1; // Ensure unique keys
        record->message = (char*)malloc((maxMessageLength + 1) * sizeof(char));
        if (!record->message) {
            free(record);
            for (size_t j = 0; j < i; ++j) free(system->records[j]);
            free(system->records);
            pthread_mutex_destroy(&system->lock);
            free(system);
            return NULL;
        }

        record->length = rand() % maxMessageLength + 1;
        for (size_t j = 0; j < record->length; ++j) {
            record->message[j] = 'A' + rand() % ('Z' - 'A' + 1);
        }
        record->message[record->length] = '\0';
        record->status = true;

        system->records[i] = record;
    }

    return system;
}

void destroy_logging_system(LoggingSystem *system) {
    for (size_t i = 0; i < system->totalRecords; ++i) {
        free(system->records[i]->message);
        free(system->records[i]);
    }
    free(system->records);
    pthread_mutex_destroy(&system->lock);
    free(system);
}

// Additional functions for concurrent access, record management, and garbage collection can be implemented here.
