# Define a decorator for API rate limiting
def rate_limit(max_calls, period):
    def decorator(func):
        def wrapper(*args, **kwargs):
            client_ip = args[0].META.get('REMOTE_ADDR')
            key = f"rate_limit:{client_ip}:{func.__name__}"
            calls = cache.get(key, 0)
            if calls >= max_calls:
                return JsonResponse({"error": "Rate limit exceeded"}, status=429)
            cache.set(key, calls + 1, timeout=period)
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Define a function to fetch data from an API
@csrf_exempt
def fetch_data(request):
    api_url = "https://api.example.com/data"
    try:
        response = requests.get(api_url, timeout=5)
        response.raise_for_status()
        data = response.json()
        # Process and transform data as needed
        processed_data = process_data(data)
        return JsonResponse(processed_data)
    except requests.exceptions.RequestException as e:
        # Log the error and retry logic here
        return JsonResponse({"error": str(e)}, status=500)

