int* read_integers(int *count) {
    *count = 0;
    int capacity = 10;
    int *keys = (int *)malloc(capacity * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys array.\n");
        exit(EXIT_FAILURE);
    }

    while (scanf("%d", &keys[*count]) == 1) {
        (*count)++;
        if (*count >= capacity) {
            capacity *= 2;
            int *new_keys = (int *)realloc(keys, capacity * sizeof(int));
            if (!new_keys) {
                fprintf(stderr, "Memory reallocation failed for keys array.\n");
                free(keys);
                exit(EXIT_FAILURE);
            }
            keys = new_keys;
        }
    }

    return keys;
}

