    if (!host) {
        fprintf(stderr, "Failed to resolve hostname: %s\n", strerror(h_errno));
        return NULL;
    }

    u_char *ip_address = (u_char *)malloc(16); // IPv4 address length
    if (!ip_address) {
        fprintf(stderr, "Memory allocation failed for IP address.\n");
        free(host);
        exit(EXIT_FAILURE);
    }

    memcpy(ip_address, host->h_addr_list[0], 4);
    return ip_address;
}

void cleanup(int *keys, record **records, int count) {
    if (keys) free(keys);
    if (records) {
        for (int i = 0; i < count; i++) {
            if (records[i]) free(records[i]);
        }
        free(records);
    }
}

