        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < count; i++) {
        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            cleanup(keys, records, i);
            exit(EXIT_FAILURE);
        }
        records[i]->value = keys[i];
