#define MAX_KEY 65535
#define MIN_OFFSET 0
#define MAX_OFFSET 1000000

typedef struct {
    int key;
    long offset;
} record;

record* records[MAX_RECORDS];
int record_count = 0;

void log_init() {
    printf("Initialization started.\n");
}

void log_cleanup() {
    printf("Cleanup completed.\n");
}

void free_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    record_count = 0;
}

record* create_record(int key, long offset) {
    if (key < 1 || key > MAX_KEY || offset < MIN_OFFSET || offset > MAX_OFFSET) {
        return NULL;
    }
    for (int i = 0; i < record_count; i++) {
        if (records[i]->key == key) {
            return NULL;
        }
    }
    record* new_record = malloc(sizeof(record));
    if (!new_record) {
        return NULL;
    }
    new_record->key = key;
    new_record->offset = offset;
    records[record_count++] = new_record;
    return new_record;
}

int main() {
    log_init();

    int sockfd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        log_cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to connect to server");
        close(sockfd);
        log_cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        char buffer[1024];
        ssize_t bytes_read = read(sockfd, buffer, sizeof(buffer));
        if (bytes_read <= 0) {
            break;
        }
        for (int i = 0; i < bytes_read; i++) {
            int key = buffer[i] & 0xFF;
            long offset = (buffer[i] >> 8) | ((buffer[i] >> 16) << 8);
            record* new_record = create_record(key, offset);
            if (!new_record) {
                perror("Failed to create record");
                free_records();
                close(sockfd);
                log_cleanup();
                return EXIT_FAILURE;
            }
        }
    }

    free_records();
    close(sockfd);
    log_cleanup();

    return EXIT_SUCCESS;
}
