typedef struct {
    int value;
    int* key_ptr;
} record;

record* create_records(int num_records, int min_value, int max_value) {
    if (num_records <= 0 || min_value > max_value) {
        return NULL;
    }

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
        records[i].key_ptr = NULL;
    }

    return records;
}

void free_records(record* records, int num_records) {
    if (!records || num_records <= 0) {
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        free(records[i].key_ptr);
    }
    free(records);
}
