#define MAX_STRING_LENGTH 100
#define RANDOM_RANGE_MIN 0
#define RANDOM_RANGE_MAX 100

typedef enum {
    STATUS_OK,
    STATUS_ERROR
} status;

typedef union {
    int i;
    double d;
} data;

typedef struct node {
    int id;
    struct node* next;
} node;

typedef struct record {
    long offset;
    int key;
    char str[MAX_STRING_LENGTH];
    node* ptr;
    status stat;
    data val;
} record;

record* create_records(int initial_capacity, int max_string_length) {
    record* records = (record*)malloc(initial_capacity * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < initial_capacity; i++) {
        records[i].offset = i;
        records[i].key = i;

        // Initialize string with random ASCII characters
        for (int j = 0; j < max_string_length - 1; j++) {
            records[i].str[j] = 'A' + rand() % ('Z' - 'A' + 1);
        }
        records[i].str[max_string_length - 1] = '\0';

        // Initialize pointer to a new node with unique ID
        records[i].ptr = (node*)malloc(sizeof(node));
        if (!records[i].ptr) {
            fprintf(stderr, "Memory allocation failed for node\n");
            free(records);
            return NULL;
        }
        records[i].ptr->id = i;
        records[i].ptr->next = NULL;

        // Initialize status and value based on random choice
        int choice = rand() % 2;
        if (choice == 0) {
            records[i].stat = STATUS_OK;
            records[i].val.i = RANDOM_RANGE_MIN + rand() % (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN + 1);
        } else {
            records[i].stat = STATUS_ERROR;
            records[i].val.d = RANDOM_RANGE_MIN + ((double)rand() / RAND_MAX) * (RANDOM_RANGE_MAX - RANDOM_RANGE_MIN);
        }
    }

    return records;
}

void free_records(record* records, int capacity) {
    for (int i = 0; i < capacity; i++) {
        free(records[i].ptr);
    }
    free(records);
}

int main() {
    record* myRecords = create_records(10, MAX_STRING_LENGTH);
    if (myRecords) {
        // Use the records...
        free_records(myRecords, 10);
    }
    return 0;
}
