#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int age;
    int frequency;
    double weighted_sum;
} Transaction;

typedef struct {
    Transaction* transactions;
    size_t count;
    pthread_mutex_t lock;
} TransactionQueue;

void init_transaction_queue(TransactionQueue* queue, size_t initial_size) {
    queue->transactions = (Transaction*)malloc(initial_size * sizeof(Transaction));
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueue_transaction(TransactionQueue* queue, Transaction transaction) {
    pthread_mutex_lock(&queue->lock);
    if (queue->count >= initial_size) {
        // Resize the queue
        queue->transactions = realloc(queue->transactions, queue->count * 2 * sizeof(Transaction));
    }
    queue->transactions[queue->count++] = transaction;
    pthread_mutex_unlock(&queue->lock);
}

void process_transactions(TransactionQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    for (size_t i = 0; i < queue->count; ++i) {
        Transaction* transaction = &queue->transactions[i];
        // Apply filtering criteria
        if (transaction->age > 18 && transaction->frequency > 3 && transaction->weighted_sum > 1000.0) {
            // Process the transaction
            printf("Processing transaction: Age=%d, Frequency=%d, Weighted Sum=%.2f\n", 
                   transaction->age, transaction->frequency, transaction->weighted_sum);
        }
    }
    pthread_mutex_unlock(&queue->lock);
}

void destroy_transaction_queue(TransactionQueue* queue) {
    free(queue->transactions);
    pthread_mutex_destroy(&queue->lock);
}
```

This code provides a basic structure for managing and processing financial transactions in a thread-safe manner. It includes functions to initialize, enqueue, process, and destroy a transaction queue. The `process_transactions` function demonstrates how to apply filtering criteria to each transaction. This example focuses on the core functionality without delving into external analytics engines or advanced optimizations like cache efficiency or memory fragmentation management.']

