#include <stdlib.h>
#include <time.h>

typedef struct {
    long* offsets;
    int* keys;
    int** records;
} Records;

Records* initialize_records(int numOffsets, int numKeys, int numRecords, int minKey, int maxKey, int minValue, int maxValue, unsigned int seed) {
    if (numKeys > (maxKey - minKey + 1)) {
        fprintf(stderr, "Error: Not enough unique keys in the specified range.\n");
        return NULL;
    }

    Records* records = malloc(sizeof(Records));
    if (!records) {
        perror("Failed to allocate memory for Records structure.");
        return NULL;
    }

    records->offsets = malloc(numOffsets * sizeof(long));
    if (!records->offsets) {
        fprintf(stderr, "Error: Failed to allocate memory for OffsetArray.\n");
        free(records);
        return NULL;
    }

    records->keys = malloc(numKeys * sizeof(int));
    if (!records->keys) {
        fprintf(stderr, "Error: Failed to allocate memory for KeyArray.\n");
        free(records->offsets);
        free(records);
        return NULL;
    }

    records->records = malloc(numRecords * sizeof(int*));
    if (!records->records) {
        fprintf(stderr, "Error: Failed to allocate memory for RecordArray.\n");
        free(records->keys);
        free(records->offsets);
        free(records);
        return NULL;
    }

    srand(seed);

    // Populate KeyArray with unique keys
    for (int i = 0; i < numKeys; ++i) {
        records->keys[i] = minKey + rand() % (maxKey - minKey + 1);
    }

    // Validate KeyArray for duplicates and out-of-range values
    for (int i = 0; i < numKeys; ++i) {
        for (int j = i + 1; j < numKeys; ++j) {
            if (records->keys[i] == records->keys[j]) {
                fprintf(stderr, "Error: Duplicate key found in KeyArray.\n");
                free(records->records);
                free(records->keys);
                free(records->offsets);
                free(records);
                return NULL;
            }
        }
    }

    // Populate RecordArray with unique random values
    for (int i = 0; i < numRecords; ++i) {
        int value;
        do {
            value = minValue + rand() % (maxValue - minValue + 1);
        } while (find_value(records->records, records->numRecords, value));
        records->records[i] = malloc(sizeof(int));
        *records->records[i] = value;
    }

    // Validate RecordArray for duplicates
    for (int i = 0; i < numRecords - 1; ++i) {
        for (int j = i + 1; j < numRecords; ++j) {
            if (*records->records[i] == *records->records[j]) {
                fprintf(stderr, "Error: Duplicate value found in RecordArray.\n");
                free_records(records);
                return NULL;
            }
        }
    }

    return records;
}

int find_value(int** array, int size, int value) {
    for (int i = 0; i < size; ++i) {
        if (*array[i] == value) {
            return 1;
        }
    }
    return 0;
}

void free_records(Records* records) {
    for (int i = 0; i < records->numRecords; ++i) {
        free(records->records[i]);
    }
    free(records->records);
    free(records->keys);
    free(records->offsets);
    free(records);
}
