const blueslip = require('blueslip');
const async = require('async');

function traverseDOM(label, f, config, sharedState) {
    const { maxDepth, allowedAttributes, restrictedAttributes, metadata } = config;
    let result = [];

    function traverse(node, depth) {
        if (depth > maxDepth || !node) return;

        if (restrictedAttributes.some(attr => node.hasAttribute(attr))) {
            blueslip.warn(`Restricted attribute found: ${attr}`);
            return;
        }

        const { className, id } = node;
        if (f(className, id, metadata)) {
            let str = `${label},`;
            if (className) {
                if (className.length > 100) return;
                str += `class:${className}`;
            }
            if (id) {
                if (id.length > 100) return;
                str += `,id:${id}`;
            }
            result.push(str);
        }

        async.eachOfLimit(node.childNodes, 10, (childNode, index, callback) => {
            traverse(childNode, depth + 1);
            callback();
        }, () => {});
    }

    traverse(document.body, 0);

    return result;
}
