int allocate_memory(long num_offsets, int seed, long **offsets, int **keys, record ***records, long *total_count, int *sum) {
    srand(seed);

    // Allocate memory for offsets
    *offsets = (long *)calloc(num_offsets, sizeof(long));
    if (*offsets == NULL) return -1;

    // Allocate memory for keys
    *keys = (int *)calloc(num_offsets, sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    // Initialize offsets and keys
    for (long i = 0; i < num_offsets; i++) {
        (*offsets)[i] = 0;
        (*keys)[i] = i + 1;
    }

    // Allocate memory for records
    *records = (record **)calloc(num_offsets, sizeof(record *));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    // Initialize records with random values
    int used_values[1001] = {0};
    for (long i = 0; i < num_offsets; i++) {
        int value;
        do {
            value = rand() % 1001;
        } while (used_values[value]);
        used_values[value] = 1;
        (*records)[i] = (record *)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            for (long j = 0; j < i; j++) free((*records)[j]);
            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }
        (*records)[i]->value = value;
    }

    // Initialize total count and sum
    *total_count = num_offsets;
    *sum = 0;
    for (long i = 0; i < num_offsets; i++) {
        *sum += (*records)[i]->value;
    }

    return 0;
}

int main() {
    long num_offsets = 10;
    int seed = time(NULL);
    long *offsets;
    int *keys;
    record **records;
    long total_count;
    int sum;

    if (allocate_memory(num_offsets, seed, &offsets, &keys, &records, &total_count, &sum) == 0) {
        printf("Total count: %ld\n", total_count);
        printf("Sum of values: %d\n", sum);

        // Free allocated memory
        for (long i = 0; i < num_offsets; i++) free(records[i]);
        free(offsets);
        free(keys);
        free(records);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
