} Records;

Records* createRecords(int numOffsets, int numKeys, int minKey, int maxKey, int minValue, int maxValue, int seed, int logEnabled) {
    if (numKeys > (maxKey - minKey + 1)) {
        if (logEnabled) printf("Error: Requested number of keys exceeds available range.\n");
        return NULL;
    }

    Records* records = (Records*)malloc(sizeof(Records));
    if (!records) {
        if (logEnabled) printf("Error: Insufficient memory for Records structure.\n");
        return NULL;
    }

    // Allocate and initialize OffsetArray
    records->offsetArray.offsets = (int*)calloc(numOffsets, sizeof(int));
    records->offsetArray.numOffsets = numOffsets;

    // Allocate and initialize KeyArray
    records->keyArray.keys = (int*)malloc(numKeys * sizeof(int));
    if (!records->keyArray.keys) {
        free(records->offsetArray.offsets);
        free(records);
        if (logEnabled) printf("Error: Insufficient memory for KeyArray.\n");
        return NULL;
    }
    srand(seed);
    int* keySet = (int*)calloc(numKeys, sizeof(int));
    for (int i = 0; i < numKeys; ++i) {
        int key;
        do {
            key = minKey + rand() % (maxKey - minKey + 1);
        } while (keySet[key - minKey]);
        records->keyArray.keys[i] = key;
        keySet[key - minKey] = 1;
    }
    free(keySet);

    // Allocate and initialize RecordArray
    records->recordArray.records = (int*)malloc(numRecords * sizeof(int));
    if (!records->recordArray.records) {
        free(records->keyArray.keys);
        free(records->offsetArray.offsets);
        free(records);
        if (logEnabled) printf("Error: Insufficient memory for RecordArray.\n");
        return NULL;
    }
    srand(seed); // Reinitialize seed for reproducibility
    int* recordSet = (int*)calloc(numRecords, sizeof(int));
    for (int i = 0; i < numRecords; ++i) {
        int value;
        do {
            value = minValue + rand() % (maxValue - minValue + 1);
        } while (recordSet[value - minValue]);
        records->recordArray.records[i] = value;
        recordSet[value - minValue] = 1;
    }
    free(recordSet);

    return records;
}

void validateRecords(Records* records, int logEnabled) {
    // Implement validation logic here
    if (logEnabled) printf("Validation complete.\n");
}

void cleanupRecords(Records* records) {
    free(records->recordArray.records);
    free(records->keyArray.keys);
    free(records->offsetArray.offsets);
    free(records);
}

int main() {
    int numOffsets = 10;
    int numKeys = 5;
    int minKey = 1;
    int maxKey = 20;
    int minValue = -100;
    int maxValue = 100;
    int seed = 42;
    int logEnabled = 1;

    Records* records = createRecords(numOffsets, numKeys, minKey, maxKey, minValue, maxValue, seed, logEnabled);
    if (records) {
        validateRecords(records, logEnabled);
        cleanupRecords(records);
    }

    return 0;
}
