    size_t numEvents;
    size_t numMetaData;
} DataBundle;

DataBundle* initializeDataBundle(size_t numTimestamps, size_t numEvents, size_t numMetaData) {
    DataBundle* bundle = (DataBundle*)malloc(sizeof(DataBundle));
    if (!bundle) {
        perror("Failed to allocate memory for DataBundle");
        return NULL;
    }

    bundle->TimestampArray = (time_t*)calloc(numTimestamps, sizeof(time_t));
    bundle->EventArray = (EventType*)calloc(numEvents, sizeof(EventType));
    bundle->MetaDataArray = (char**)malloc(numMetaData * sizeof(char*));

    if (!bundle->TimestampArray || !bundle->EventArray || !bundle->MetaDataArray) {
        perror("Failed to allocate memory for arrays");
        free(bundle);
        return NULL;
    }

    // Initialize TimestampArray with current time
    for (size_t i = 0; i < numTimestamps; ++i) {
        bundle->TimestampArray[i] = time(NULL);
    }

    // Populate EventArray with unique event types
    EventType validEvents[] = {EVENT_TYPE_A, EVENT_TYPE_B}; // Add more valid events as needed
    size_t validEventCount = sizeof(validEvents) / sizeof(validEvents[0]);
    for (size_t i = 0; i < numEvents; ++i) {
        bundle->EventArray[i] = validEvents[i % validEventCount];
    }

    // Populate MetaDataArray with unique metadata strings
    const char* metaTexts[] = {"Metadata A", "Metadata B", "Metadata C"}; // Add more metadata texts as needed
    size_t metaTextCount = sizeof(metaTexts) / sizeof(metaTexts[0]);
    for (size_t i = 0; i < numMetaData; ++i) {
        bundle->MetaDataArray[i] = strdup(metaTexts[i % metaTextCount]);
    }

    // Validate EventArray and MetaDataArray
    for (size_t i = 1; i < numEvents; ++i) {
        if (bundle->EventArray[i] == bundle->EventArray[i - 1]) {
            fprintf(stderr, "Duplicate event type detected\n");
            break;
        }
    }

    for (size_t i = 1; i < numMetaData; ++i) {
        for (size_t j = 0; j < i; ++j) {
            if (strcmp(bundle->MetaDataArray[i], bundle->MetaDataArray[j]) == 0) {
                fprintf(stderr, "Duplicate metadata string detected\n");
                break;
            }
        }
    }

    return bundle;
}

int main() {
    DataBundle* bundle = initializeDataBundle(10, 5, 3);
    if (bundle) {
        // Use the bundle as needed
        free(bundle->TimestampArray);
        free(bundle->EventArray);
        for (size_t i = 0; i < bundle->numMetaData; ++i) {
            free(bundle->MetaDataArray[i]);
        }
        free(bundle->MetaDataArray);
        free(bundle);
    }

    return 0;
}
