#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_USERNAME_LENGTH 50

typedef struct Date {
    int day;
    int month;
    int year;
} Date;

typedef struct UserProfile {
    char username[MAX_USERNAME_LENGTH];
    int age;
    double score;
    Date creationDate;
    struct UserProfile* next;
} UserProfile;

typedef struct {
    UserProfile* head;
    int count;
} UserProfileList;

void logMessage(const char* message) {
    printf("%s\n", message);
}

UserProfile* createProfile(const char* username, int age, double score, const Date* date) {
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    if (profile == NULL) {
        logMessage("Memory allocation failed for user profile.");
        return NULL;
    }
    strncpy(profile->username, username, MAX_USERNAME_LENGTH);
    profile->age = age;
    profile->score = score;
    profile->creationDate = *date;
    profile->next = NULL;
    return profile;
}

void freeProfile(UserProfile* profile) {
    if (profile != NULL) {
        free(profile);
    }
}

int addProfile(UserProfileList* list, UserProfile* profile) {
    if (list == NULL || profile == NULL) {
        logMessage("Invalid input for adding a user profile.");
        return -1;
    }
    if (list->head == NULL) {
        list->head = profile;
    } else {
        UserProfile* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = profile;
    }
    list->count++;
    return 0;
}

void freeProfileList(UserProfileList* list) {
    if (list == NULL) {
        logMessage("Invalid input for freeing user profiles.");
        return;
    }
    UserProfile* current = list->head;
    while (current != NULL) {
        UserProfile* next = current->next;
        freeProfile(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

int readProfilesFromFile(const char* filename, UserProfileList* list) {
    if (filename == NULL || list == NULL) {
        logMessage("Invalid input for reading user profiles.");
        return -1;
    }
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        logMessage("Failed to open the file for reading.");
        return -1;
    }

    char username[MAX_USERNAME_LENGTH];
    int age;
    double score;
    Date date;

    while (fscanf(file, "%s %d %lf %d %d %d", username, &age, &score, &date.day, &date.month, &date.year) == 6) {
        if (strlen(username) > MAX_USERNAME_LENGTH - 1 || age < 13 || age > 99 || score < 0) {
            logMessage("Invalid user data encountered.");
            continue;
        }
        UserProfile* profile = createProfile(username, age, score, &date);
        if (profile != NULL && addProfile(list, profile) != 0) {
            freeProfile(profile);
        }
    }

    fclose(file);
    return 0;
}

double calculateAverageScore(UserProfileList* list) {
    if (list == NULL || list->count == 0) {
        logMessage("Invalid input for calculating average score.");
        return -1.0;
    }
    double total = 0.0;
    UserProfile* current = list->head;
    while (current != NULL) {
        total += current->score;
        current = current->next;
    }
    return total / list->count;
}

int main() {
    UserProfileList userList;
    userList.head = NULL;
    userList.count = 0;

    if (readProfilesFromFile("user_profiles.txt", &userList) != 0) {
        logMessage("Failed to read user profiles.");
    } else {
        double averageScore = calculateAverageScore(&userList);
        logMessage("Average Score: %.2f", averageScore);
    }

    freeProfileList(&userList);

    return 0;
}
