    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        *error_code = 1;
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = values[i];
    }

    *error_code = 0;
    return records;
}

void free_records(record* records, int size) {
    if (records) {
        free(records);
    }
}

int find_largest_int(int array[], int size) {
    int max_value = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }
    return max_value;
}

double find_largest_double(double array[], int size) {
    double max_value = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max_value) {
            max_value = array[i];
        }
    }
    return max_value;
}

