    printf("Enter %d long offsets:\n", MAX_RECORDS);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        scanf("%ld", &offsets[i]);
    }

    printf("Enter %d int keys:\n", MAX_RECORDS);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        scanf("%d", &keys[i]);
    }

    printf("Enter %d double values:\n", MAX_RECORDS);
    for (int i = 0; i < MAX_RECORDS; ++i) {
        scanf("%lf", &values[i]);
    }
}

void main() {
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    double values[MAX_RECORDS];

    read_input(offsets, keys, values);

    record* records;
    int error_code;
    records = initialize_records(offsets, keys, values, MAX_RECORDS, &error_code);
    if (error_code) {
        log_message("Memory allocation failed.");
        return;
    }

    int largest_int = find_largest_int(keys, MAX_RECORDS);
    double largest_double = find_largest_double(values, MAX_RECORDS);

    printf("Largest integer key: %d\n", largest_int);
    printf("Largest double value: %.2f\n", largest_double);

    free_records(records, MAX_RECORDS);
}
