#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct {
    long offset;
    int key;
} Record;

int find(int *parent, int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void unionSet(int *parent, int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset)
        parent[xset] = yset;
}

int areDisjoint(int *parent, int x, int y) {
    return find(parent, x) != find(parent, y);
}

void initializeRecords(Record **records, int *maxKey, int seed) {
    srand(seed);
    *records = (Record *)malloc(MAX_RECORDS * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < MAX_RECORDS; i++) {
        int key;
        do {
            key = rand() % (*maxKey + 1);
        } while (key == (*records)[i].key);
        (*records)[i].key = key;
        (*records)[i].offset = hashFunction(key); // Assume hashFunction is defined elsewhere
    }
}

void freeRecords(Record *records) {
    free(records);
}

int main() {
    int maxKey, seed;
    printf("Enter the maximum key value and seed: ");
    scanf("%d %d", &maxKey, &seed);

    Record *records;
    initializeRecords(&records, &maxKey, seed);

    // Example usage of find and unionSet
    int parent[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS; i++)
        parent[i] = -1;

    clock_t start, end;
    double cpu_time_used;

    start = clock();
    for (int i = 0; i < MAX_RECORDS - 1; i++) {
        unionSet(parent, records[i].key, records[i + 1].key);
    }
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken for union operations: %f seconds\n", cpu_time_used);

    // Example usage of areDisjoint
    start = clock();
    int disjointPairs = 0;
    for (int i = 0; i < MAX_RECORDS - 1; i++) {
        if (areDisjoint(parent, records[i].key, records[i + 1].key)) {
            disjointPairs++;
        }
    }
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Number of disjoint pairs: %d\n", disjointPairs);
    printf("Time taken for disjointness checks: %f seconds\n", cpu_time_used);

    freeRecords(records);
    return 0;
}
