#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1024

typedef struct {
    int id;
    double value;
    char *str;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int count;
    pthread_mutex_t lock;
} DataStore;

DataStore ds;

void init_data_store() {
    memset(&ds, 0, sizeof(ds));
    pthread_mutex_init(&ds.lock, NULL);
}

Record* add_record(int id, double value, const char *str) {
    pthread_mutex_lock(&ds.lock);
    if (ds.count >= MAX_RECORDS) {
        pthread_mutex_unlock(&ds.lock);
        return NULL;
    }
    Record *new_record = &ds.records[ds.count++];
    new_record->id = id;
    new_record->value = value;
    new_record->str = strdup(str);
    pthread_mutex_unlock(&ds.lock);
    return new_record;
}

Record* get_record(int id) {
    pthread_mutex_lock(&ds.lock);
    for (int i = 0; i < ds.count; i++) {
        if (ds.records[i].id == id) {
            Record *record = &ds.records[i];
            pthread_mutex_unlock(&ds.lock);
            return record;
        }
    }
    pthread_mutex_unlock(&ds.lock);
    return NULL;
}

int update_record(int id, double value, const char *str) {
    pthread_mutex_lock(&ds.lock);
    for (int i = 0; i < ds.count; i++) {
        if (ds.records[i].id == id) {
            free(ds.records[i].str);
            ds.records[i].value = value;
            ds.records[i].str = strdup(str);
            pthread_mutex_unlock(&ds.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&ds.lock);
    return -1;
}

int delete_record(int id) {
    pthread_mutex_lock(&ds.lock);
    for (int i = 0; i < ds.count; i++) {
        if (ds.records[i].id == id) {
            free(ds.records[i].str);
            for (; i < ds.count - 1; i++) {
                ds.records[i] = ds.records[i + 1];
            }
            ds.count--;
            pthread_mutex_unlock(&ds.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&ds.lock);
    return -1;
}

void cleanup_data_store() {
    for (int i = 0; i < ds.count; i++) {
        free(ds.records[i].str);
    }
    pthread_mutex_destroy(&ds.lock);
}
