Entry** create_entries(int max_entries, int* error_code) {
    Entry** entries = (Entry**)malloc(max_entries * sizeof(Entry*));
    if (!entries) {
        *error_code = -1; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < max_entries; i++) {
        entries[i] = (Entry*)malloc(sizeof(Entry));
        if (!entries[i]) {
            *error_code = -2; // Memory allocation failed
            for (int j = 0; j < i; j++) {
                free(entries[j]);
            }
            free(entries);
            return NULL;
        }

        entries[i]->id = i + 1;
        entries[i]->value = 0.0f;
        entries[i]->name = NULL;
    }

    *error_code = 0; // Success
    return entries;
}

void initialize_entries(Entry** entries, int max_entries) {
    for (int i = 0; i < max_entries; i++) {
        // Simulate fetching data from an external API or configuration file
        char buffer[100];
        snprintf(buffer, sizeof(buffer), "Name%d", i + 1);
        entries[i]->name = strdup(buffer);
        entries[i]->value = (float)(i + 1) * 1.1f;

        // Validate float value against a predefined range
        if (entries[i]->value < 0.0f || entries[i]->value > 100.0f) {
            printf("Error: Invalid value for entry %d\n", i + 1);
            free(entries[i]->name);
            entries[i]->name = NULL;
        }
    }
}

void log_entries(Entry** entries, int max_entries) {
    for (int i = 0; i < max_entries; i++) {
        if (entries[i] && entries[i]->name) {
            printf("Entry %d: ID=%d, Value=%.2f, Name=%s\n", i + 1, entries[i]->id, entries[i]->value, entries[i]->name);
        }
    }
}

void free_entries(Entry** entries, int max_entries) {
    for (int i = 0; i < max_entries; i++) {
        if (entries[i]) {
            free(entries[i]->name);
            free(entries[i]);
        }
    }
    free(entries);
}

int main() {
    int max_entries = 10;
    int error_code;

    Entry** entries = create_entries(max_entries, &error_code);
    if (error_code != 0) {
        printf("Error: Failed to allocate memory for entries\n");
        return 1;
    }

    initialize_entries(entries, max_entries);

    log_entries(entries, max_entries);

    free_entries(entries, max_entries);

    return 0;
}
