#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Record {
    int id;
    double value;
    char* str;
} Record;

typedef struct DataStore {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DataStore;

DataStore* create_data_store(size_t initial_capacity) {
    DataStore* ds = (DataStore*)malloc(sizeof(DataStore));
    ds->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    ds->capacity = initial_capacity;
    ds->size = 0;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void destroy_data_store(DataStore* ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        free(ds->records[i]->str);
        free(ds->records[i]);
    }
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

void add_record(DataStore* ds, int id, double value, const char* str) {
    pthread_mutex_lock(&ds->lock);
    if (ds->size == ds->capacity) {
        ds->capacity *= 2;
        ds->records = (Record**)realloc(ds->records, ds->capacity * sizeof(Record*));
    }
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->id = id;
    new_record->value = value;
    new_record->str = strdup(str);
    ds->records[ds->size++] = new_record;
    pthread_mutex_unlock(&ds->lock);
}

Record* get_record(DataStore* ds, int id) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->records[i]->id == id) {
            Record* record = ds->records[i];
            pthread_mutex_unlock(&ds->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&ds->lock);
    return NULL;
}

void update_record(DataStore* ds, int id, double value, const char* str) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->records[i]->id == id) {
            free(ds->records[i]->str);
            ds->records[i]->value = value;
            ds->records[i]->str = strdup(str);
            break;
        }
    }
    pthread_mutex_unlock(&ds->lock);
}

void delete_record(DataStore* ds, int id) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->records[i]->id == id) {
            free(ds->records[i]->str);
            free(ds->records[i]);
            for (size_t j = i; j < ds->size - 1; ++j) {
                ds->records[j] = ds->records[j + 1];
            }
            --ds->size;
            break;
        }
    }
    pthread_mutex_unlock(&ds->lock);
}
