    if (num_records <= 0) {
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].id = i + 1;
        records[i].value = 3.14 * i;

        // Simulate fetching data from an external API
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "Record %d", i);
        records[i].name = strdup(buffer);
        if (!records[i].name) {
            perror("Failed to allocate memory for record name");
            // Free previously allocated records
            for (int j = 0; j < i; ++j) {
                free(records[j].name);
            }
            free(records);
            return NULL;
        }
    }

    return records;
}

void free_records(record* records, int num_records) {
    if (!records || num_records <= 0) {
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        free(records[i].name);
    }

    free(records);
}

