    union max_value max_val;
    max_val.max_int = INT_MIN;
    max_val.max_double = -DBL_MAX;

    for (int i = 0; i < size; i++) {
        if (int_array[i] > max_val.max_int) {
            max_val.max_int = int_array[i];
        }
        if (double_array[i] > max_val.max_double) {
            max_val.max_double = double_array[i];
        }
    }

    return max_val;
}

void retry_logic(int* int_array, double* double_array, int size) {
    union max_value max_val = find_max(int_array, double_array, size);
    printf("Max integer: %d\n", max_val.max_int);
    printf("Max double: %f\n", max_val.max_double);
}

