    int int_array[10];
    double double_array[10];

    for (int i = 0; i < 10; i++) {
        scanf("%d", &int_array[i]);
        scanf("%lf", &double_array[i]);
    }

    retry_logic(int_array, double_array, 10);

    return 0;
}
