use std::collections::{HashMap, HashSet};
use std::fs;
use std::env;
use std::time::{Instant, Duration};
use rand::{Rng, thread_rng};

#[derive(Debug)]
struct Record {
    key: i32,
    offset: i64,
    value: f64,
    identifier: String,
}

fn initialize_records() -> Result<(), Box<dyn std::error::Error>> {
    let mut rng = thread_rng();
    let num_records = 100; // Example size
    let key_range = (1, 100);
    let offset_range = (-1000, 1000);
    let value_range = (0.0, 100.0);

    let mut keys: HashSet<i32> = HashSet::new();
    let mut offsets: HashSet<i64> = HashSet::new();
    let mut values: HashSet<f64> = HashSet::new();
    let mut identifiers: HashSet<String> = HashSet::new();

    while keys.len() < num_records {
        let key = rng.gen_range(key_range.0..=key_range.1);
        if !keys.contains(&key) {
            keys.insert(key);
        }
    }

    while offsets.len() < num_records {
        let offset = rng.gen_range(offset_range.0..=offset_range.1);
        if !offsets.contains(&offset) {
            offsets.insert(offset);
        }
    }

    while values.len() < num_records {
        let value = rng.gen_range(value_range.0..=value_range.1);
        if !values.contains(&value) {
            values.insert(value);
        }
    }

    for _ in 0..num_records {
        let identifier = format!("record_{}", rng.gen_range(0, num_records));
        identifiers.insert(identifier.clone());
    }

    let records: Vec<Record> = keys.iter()
        .zip(offsets.iter())
        .zip(values.iter())
        .zip(identifiers.iter())
        .map(|(((key, offset), value), identifier)| Record {
            key: *key,
            offset: *offset,
            value: *value,
            identifier: identifier.clone(),
        })
        .collect();

    for record in records {
        println!("{:?}", record);
    }

    Ok(())
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    initialize_records()?;
    let dir_name = "new_directory";
    fs::create_dir(dir_name)?;
    env::set_var("NEW_DIR_PATH", dir_name);

    // Simulate fetching data from an external API
    let start_time = Instant::now();
    // Replace with actual API call
    thread::sleep(Duration::from_secs(2));
    let elapsed_time = start_time.elapsed().as_millis();

    println!("Time taken to fetch data: {} ms", elapsed_time);

    Ok(())
}
```

