using System;
using UnityEngine;

public class DataProcessor : IDisposable
{
    private int _minValue;
    private int _maxValue;
    private int[] _inputIntegers;
    private bool _disposed = false;

    public DataProcessor(int minValue, int maxValue)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        Log("DataProcessor initialized with range: " + minValue + " to " + maxValue);
    }

    ~DataProcessor()
    {
        Dispose(false);
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }

    protected virtual void Dispose(bool disposing)
    {
        if (!_disposed)
        {
            if (disposing)
            {
                // Free any other managed objects here.
            }

            // Free any unmanaged objects here.

            _disposed = true;
            Log("DataProcessor disposed");
        }
    }

    public float GetRandomFloat()
    {
        long startTime = DateTime.Now.Ticks;
        float randomValue = UnityEngine.Random.Range(_minValue, _maxValue);
        long endTime = DateTime.Now.Ticks;
        Log("GetRandomFloat took " + (endTime - startTime) / 10000.0 + " ms");
        return randomValue;
    }

    public int GetRandomInt()
    {
        long startTime = DateTime.Now.Ticks;
        int randomValue = UnityEngine.Random.Range(_minValue, _maxValue);
        long endTime = DateTime.Now.Ticks;
        Log("GetRandomInt took " + (endTime - startTime) / 10000.0 + " ms");
        return randomValue;
    }

    public void ReadInputIntegers()
    {
        try
        {
            Console.WriteLine("Enter integers separated by spaces:");
            string input = Console.ReadLine();
            _inputIntegers = Array.ConvertAll(input.Split(' '), int.Parse);
            Log("Read " + _inputIntegers.Length + " integers");
        }
        catch (FormatException)
        {
            Log("Invalid input format. Please enter integers.");
        }
        catch (OutOfMemoryException)
        {
            Log("Out of memory error while reading integers.");
        }
    }

    public int FindLargestInteger()
    {
        if (_inputIntegers == null || _inputIntegers.Length == 0)
        {
            throw new InvalidOperationException("No integers have been read yet.");
        }

        int largest = int.MinValue;
        foreach (int num in _inputIntegers)
        {
            if (num > largest)
            {
                largest = num;
            }
        }
        Log("Largest integer found: " + largest);
        return largest;
    }

    public override string ToString()
    {
        return $"Current range: {_minValue} to {_maxValue}";
    }

    private void Log(string message)
    {
        Console.WriteLine(message);
    }
}
