typedef struct {
    int value;
} record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays(long** offsets, int** keys, record** records, int n) {
    *offsets = safe_malloc(n * sizeof(long));
    *keys = safe_malloc(n * sizeof(int));
    *records = safe_malloc(n * sizeof(record));

    for (int i = 0; i < n; i++) {
        (*offsets)[i] = i;
        (*keys)[i] = rand() % 1000; // Random value within range
        (*records)[i].value = rand() % 1000; // Random value within range
    }
}

void free_arrays(long* offsets, int* keys, record* records, int n) {
    free(offsets);
    free(keys);
    free(records);
}

int find(int* parent, int i) {
    if (parent[i] != i)
        parent[i] = find(parent, parent[i]);
    return parent[i];
}

void union_sets(int* parent, int x, int y) {
    int rootX = find(parent, x);
    int rootY = find(parent, y);
    if (rootX != rootY)
        parent[rootX] = rootY;
}

int count_disjoint_pairs(int* keys, int n) {
    int* parent = safe_malloc(n * sizeof(int));
    for (int i = 0; i < n; i++)
        parent[i] = i;

    clock_t start, end;
    double cpu_time_used;

    start = clock();
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (find(parent, keys[i]) != find(parent, keys[j])) {
                union_sets(parent, keys[i], keys[j]);
                printf("Disjoint pair found between %d and %d\n", keys[i], keys[j]);
            }
        }
    }
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken for disjointness tests: %.2f seconds\n", cpu_time_used);

    free(parent);
    return 0; // Placeholder return value
}

int main() {
    srand(time(NULL));
    int n;
    printf("Enter the number of elements: ");
    scanf("%d", &n);

    long* offsets;
    int* keys;
    record* records;

    initialize_arrays(&offsets, &keys, &records, n);

    // Read input and store in keys array
    for (int i = 0; i < n; i++) {
        scanf("%d", &keys[i]);
    }

    count_disjoint_pairs(keys, n);

    free_arrays(offsets, keys, records, n);
    return 0;
}
