#define MAX_RECORDS 10000000
#define MAX_STRING_LENGTH 256

typedef struct {
    int value;
    char *str;
} record;

typedef struct {
    int parent;
    int rank;
} UnionFindNode;

record* records[MAX_RECORDS];
int keys[MAX_RECORDS];
long offsets[MAX_RECORDS];
UnionFindNode uf[MAX_RECORDS];

void initialize(int n) {
    for (int i = 0; i < n; i++) {
        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        records[i]->str = malloc(MAX_STRING_LENGTH * sizeof(char));
        if (!records[i]->str) {
            fprintf(stderr, "Memory allocation failed\n");
            free(records[i]);
            exit(1);
        }
        keys[i] = 0;
        offsets[i] = 0;
        uf[i].parent = i;
        uf[i].rank = 0;
    }
}

void unionFindMakeSet(int x) {
    uf[x].parent = x;
    uf[x].rank = 0;
}

int unionFindFind(int x) {
    if (uf[x].parent != x)
        uf[x].parent = unionFindFind(uf[x].parent);
    return uf[x].parent;
}

void unionFindUnion(int x, int y) {
    int rootX = unionFindFind(x);
    int rootY = unionFindFind(y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank)
            uf[rootY].parent = rootX;
        else if (uf[rootX].rank < uf[rootY].rank)
            uf[rootX].parent = rootY;
        else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

void printLargest(int n) {
    int largest = keys[0];
    for (int i = 1; i < n; i++) {
        if (keys[i] > largest)
            largest = keys[i];
    }
    printf("Largest integer: %d\n", largest);
}

void cleanup(int n) {
    for (int i = 0; i < n; i++) {
        free(records[i]->str);
        free(records[i]);
    }
}

int main() {
    int n;
    scanf("%d", &n);

    initialize(n);

    for (int i = 0; i < n; i++) {
        unionFindMakeSet(i);
        scanf("%d %s", &keys[i], records[i]->str);
    }

    clock_t start, end;
    double cpu_time_used;

    for (int i = 1; i < n; i++) {
        start = clock();
        unionFindUnion(0, i);
        end = clock();
        cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC * 1000;
        printf("Time taken for union operation %d: %.2f ms\n", i, cpu_time_used);
    }

    printLargest(n);

    cleanup(n);

    return 0;
}
