        return i;
    return find(parent, parent[i]);
}

void unionSet(int *parent, int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset)
        parent[xset] = yset;
}

int areDisjoint(int *parent, int x, int y) {
    return find(parent, x) != find(parent, y);
}

Record* createRecords(int n, int keyRange, long seed, int valueRange) {
    srand(seed);
    Record *records = (Record*)malloc(n * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    int *parent = (int*)calloc(n, sizeof(int));
    for (int i = 0; i < n; ++i) {
        records[i].key = rand() % keyRange + 1;
        while (find(parent, records[i].key - 1) != -1)
            records[i].key = rand() % keyRange + 1;
        records[i].offset = hash(records[i].key);
        unionSet(parent, records[i].key - 1, records[i].offset);
        records[i].key = rand() % valueRange + 1;
    }
    free(parent);
    return records;
}

