#define MAX_OFFSETS 1000
#define MAX_KEYS 500
#define MAX_DATA_POINTS 10000

typedef struct {
    long offset;
} offset_collection;

typedef struct {
    int key;
    struct record *record;
} key_record;

typedef struct {
    double value;
    char *string;
} data_point;

void initialize_offsets(offset_collection *offsets, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        offsets[i].offset = rand() % 1000000L;
    }
}

void insert_key_record(key_record **records, int *count, int key, double value, const char *str) {
    (*count)++;
    *records = realloc(*records, (*count) * sizeof(key_record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    (*records)[*count - 1].key = key;
    (*records)[*count - 1].record = malloc(sizeof(struct record));
    if ((*records)[*count - 1].record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    (*records)[*count - 1].record->value = value;
    (*records)[*count - 1].record->string = strdup(str);
}

void free_key_records(key_record *records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i].record->string);
        free(records[i].record);
    }
    free(records);
}

void read_data_points(data_point **points, int *count) {
    double value;
    char str[256];
    while (scanf("%lf %s", &value, str) == 2) {
        (*count)++;
        *points = realloc(*points, (*count) * sizeof(data_point));
        if (*points == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        (*points)[*count - 1].value = value;
        (*points)[*count - 1].string = strdup(str);
    }
}

void free_data_points(data_point *points, int count) {
    for (int i = 0; i < count; i++) {
        free(points[i].string);
    }
    free(points);
}

void sort_data_points(data_point *points, int count) {
    qsort(points, count, sizeof(data_point), [](const void *a, const void *b) {
        return ((data_point *)b)->value - ((data_point *)a)->value;
    });
}

int filter_data_points(const data_point *points, int count, const char *substring) {
    for (int i = 0; i < count; i++) {
        if (strstr(points[i].string, substring)) {
            printf("Value: %f, String: %s\n", points[i].value, points[i].string);
        }
    }
    return 0;
}

int main() {
    offset_collection offsets[MAX_OFFSETS];
    key_record *key_records = NULL;
    int key_count = 0;
    data_point *data_points = NULL;
    int data_count = 0;

    initialize_offsets(offsets, MAX_OFFSETS);
    insert_key_record(&key_records, &key_count, 1, 3.14, "pi");
    insert_key_record(&key_records, &key_count, 2, 2.718, "e");

    read_data_points(&data_points, &data_count);

    sort_data_points(data_points, data_count);
    filter_data_points(data_points, data_count, "pi");

    free_key_records(key_records, key_count);
    free_data_points(data_points, data_count);

    return 0;
}
