        if (entries[i]->value < 0 || entries[i]->value > 100) {
            fprintf(stderr, "Invalid value for entry %d: %.2f\n", i, entries[i]->value);
            free(entries[i]);
            // Free previously allocated entries
            for (int j = 0; j < i; j++) {
                free(entries[j]);
