#include <string.h>
#include <time.h>

#define MAX_PREFIX_LENGTH 10
#define MAX_RANDOM_CHARS 20

typedef struct {
    double value;
    char* string;
} DataStruct;

DataStruct* allocateMemory(size_t limit, size_t* count) {
    // Simulate system dependencies and external data sources
    srand(time(NULL));
    const char* prefixes[] = {"Prefix1", "Prefix2", "Prefix3"};
    int prefixCount = sizeof(prefixes) / sizeof(prefixes[0]);

    DataStruct* array = (DataStruct*)malloc(limit);
    if (!array) {
        return NULL;
    }

    *count = limit / sizeof(DataStruct);
    for (size_t i = 0; i < *count; ++i) {
        size_t prefixLength = rand() % MAX_PREFIX_LENGTH + 1;
        size_t randomChars = rand() % MAX_RANDOM_CHARS + 1;

        array[i].value = (double)i;
        array[i].string = (char*)malloc(prefixLength + randomChars + 1);
        if (!array[i].string) {
            // Handle memory allocation failure
            for (size_t j = 0; j < i; ++j) {
                free(array[j].string);
            }
            free(array);
            return NULL;
        }

        strncpy(array[i].string, prefixes[rand() % prefixCount], prefixLength);
        for (size_t j = 0; j < randomChars; ++j) {
            array[i].string[prefixLength + j] = 'A' + rand() % 62;
        }
        array[i].string[prefixLength + randomChars] = '\0';
    }

    return array;
}

void updateValues(DataStruct* array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        // Simulate periodic updates
        array[i].value += 1.0;
