#define MAX_PROFILES 5000
#define USERNAME_PREFIX "USER-"
#define MAX_USERNAME_LENGTH 20

typedef struct {
    double score;
    char* username;
    size_t username_length;
} UserProfile;

UserProfile* create_user_profiles(size_t count, int* success_count, int* failure_count) {
    if (count > MAX_PROFILES) {
        *failure_count = 1;
        return NULL;
    }

    UserProfile* profiles = malloc(count * sizeof(UserProfile));
    if (!profiles) {
        *failure_count = 1;
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < count; ++i) {
        size_t username_length = strlen(USERNAME_PREFIX) + rand() % (MAX_USERNAME_LENGTH - strlen(USERNAME_PREFIX));
        profiles[i].username = malloc(username_length * sizeof(char));
        if (!profiles[i].username) {
            for (size_t j = 0; j < i; ++j) {
                free(profiles[j].username);
            }
            free(profiles);
            *failure_count = 1;
            return NULL;
        }

        snprintf(profiles[i].username, username_length, "%s%.*s", USERNAME_PREFIX, (int)(username_length - strlen(USERNAME_PREFIX)), "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789");
        profiles[i].username_length = username_length;
        profiles[i].score = ((double)rand() / RAND_MAX) * 100.0; // Random score between 0 and 100
    }

    *success_count = count;
    return profiles;
}

void copy_user_profiles(UserProfile* source, UserProfile* destination, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        destination[i].score = source[i].score;
        destination[i].username_length = source[i].username_length;
        destination[i].username = malloc(source[i].username_length * sizeof(char));
        if (!destination[i].username) {
            // Handle memory allocation failure
            continue;
        }
        strcpy(destination[i].username, source[i].username);
    }
}

void free_user_profiles(UserProfile* profiles, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free(profiles[i].username);
    }
    free(profiles);
}

// Example usage
int main() {
    int success_count, failure_count;
    UserProfile* profiles = create_user_profiles(10, &success_count, &failure_count);
    if (profiles) {
        printf("Successfully created %d user profiles.\n", success_count);

        UserProfile* copied_profiles = malloc(success_count * sizeof(UserProfile));
        if (copied_profiles) {
            copy_user_profiles(profiles, copied_profiles, success_count);

            // Perform operations on copied_profiles

            free(copied_profiles);
        } else {
            printf("Failed to allocate memory for copied profiles.\n");
        }

        free_user_profiles(profiles, success_count);
    } else {
        printf("Failed to create user profiles.\n");
    }

    return 0;
}
