#include <string.h>
#include <time.h>

#define MAX_PREFIX_LENGTH 10
#define MAX_RANDOM_CHARS 20
#define MAX_MEMORY_LIMIT 1024 * 1024 // 1MB

typedef struct {
    double value;
    char* string;
} DataStruct;

DataStruct* allocate_memory(int initial_count, int* count) {
    DataStruct* data = (DataStruct*)malloc(initial_count * sizeof(DataStruct));
    if (!data) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    *count = initial_count;
    return data;
}

void free_memory(DataStruct** data, int* count) {
    for (int i = 0; i < *count; i++) {
        free((*data)[i].string);
    }
    free(*data);
    *data = NULL;
    *count = 0;
}

char* generate_random_string(const char* prefix, int max_length) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    int length = rand() % (max_length - strlen(prefix)) + strlen(prefix);
    char* result = (char*)malloc((length + 1) * sizeof(char));
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    strcpy(result, prefix);
    for (int i = strlen(prefix); i < length; i++) {
        result[i] = charset[rand() % (sizeof(charset) - 1)];
    }
    result[length] = '\0';
    return result;
}

void update_data(DataStruct* data, int count, const char* prefix, int max_length) {
    for (int i = 0; i < count; i++) {
        free(data[i].string);
        data[i].value = rand() / (double)RAND_MAX;
        data[i].string = generate_random_string(prefix, max_length);
    }
}

void log_memory_usage(int memory_used, int total_limit) {
    printf("Memory Usage: %d/%d\n", memory_used, total_limit);
}

int main() {
    srand(time(NULL));
    DataStruct* data = NULL;
    int count = 0;

    // Allocate initial memory
    data = allocate_memory(10, &count);
    if (!data) return 1;

    // Simulate fetching prefix and random numbers from an external API
    const char* prefix = "prefix_";
    int max_length = MAX_PREFIX_LENGTH + MAX_RANDOM_CHARS;

    // Update data periodically
    for (int i = 0; i < 5; i++) {
        update_data(data, count, prefix, max_length);
        log_memory_usage(i * sizeof(DataStruct) + strlen(prefix) * count, MAX_MEMORY_LIMIT);

        // Check memory usage and reallocate if necessary
        int total_size = i * sizeof(DataStruct) + strlen(prefix) * count;
        if (total_size > MAX_MEMORY_LIMIT / 2) {
            DataStruct* new_data = allocate_memory(count * 2, &count);
            if (!new_data) break;
            memcpy(new_data, data, total_size);
            free_memory(&data, &count);
            data = new_data;
        }
    }

    // Free allocated memory
    free_memory(&data, &count);

    return 0;
}
