#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void log_message(const char* message) {
    printf("%s\n", message);
}

int find(int parent[], int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void union_sets(int parent[], int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset)
        parent[xset] = yset;
}

int count_disjoint_pairs(int keys[], int n) {
    int* parent = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++)
        parent[i] = -1;

    clock_t start, end;
    double cpu_time_used;

    start = clock();
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (keys[i] != keys[j])
                union_sets(parent, i, j);
        }
    }
    end = clock();

    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken for disjointness test: %f seconds\n", cpu_time_used);

    int count = 0;
    for (int i = 0; i < n; i++)
        if (parent[i] == -1)
            count++;

    free(parent);
    return count;
}

void process_input() {
    int* keys = NULL;
    long* offsets = NULL;
    record* records = NULL;
    int n, key_range, offset_range;

    log_message("Reading input...");
    scanf("%d %d %d", &n, &key_range, &offset_range);

    keys = (int*)malloc(n * sizeof(int));
    offsets = (long*)malloc(n * sizeof(long));
    records = (record*)malloc(n * sizeof(record));

    if (!keys || !offsets || !records) {
        log_message("Memory allocation failed.");
        return;
    }

    for (int i = 0; i < n; i++) {
        scanf("%d", &keys[i]);
        offsets[i] = rand() % offset_range;
        records[i].value = rand() % key_range;
    }

    int max_key = *max_element(keys, keys + n);
    log_message("Largest integer in the array: %d\n", max_key);

    int disjoint_pairs = count_disjoint_pairs(keys, n);
    log_message("Number of disjoint pairs: %d\n", disjoint_pairs);

    free(keys);
    free(offsets);
    free(records);
}

int main() {
    srand(time(0));
    process_input();
    return 0;
}
