#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    struct record *record;
} DataStructure;

typedef struct record {
    int value;
} Record;

typedef struct cache_entry {
    int key;
    Record *record;
    struct cache_entry *next;
} CacheEntry;

typedef struct {
    CacheEntry **buckets;
    size_t size;
} Cache;

DataStructure* initialize_data_structure(long offset, int key) {
    DataStructure *ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) {
        perror("Failed to allocate memory for data structure");
        return NULL;
    }
    ds->offset = offset;
    ds->key = key;
    ds->record = (Record*)malloc(sizeof(Record));
    if (!ds->record) {
        perror("Failed to allocate memory for record");
        free(ds);
        return NULL;
    }
    ds->record->value = rand() % 100; // Random value between 0 and 99
    return ds;
}

void initialize_cache(Cache *cache, size_t size) {
    cache->buckets = (CacheEntry**)calloc(size, sizeof(CacheEntry*));
    if (!cache->buckets) {
        perror("Failed to allocate memory for cache buckets");
        exit(EXIT_FAILURE);
    }
    cache->size = size;
}

void insert_cache(Cache *cache, int key, Record *record) {
    size_t index = (size_t)key % cache->size;
    CacheEntry *entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    if (!entry) {
        perror("Failed to allocate memory for cache entry");
        return;
    }
    entry->key = key;
    entry->record = record;
    entry->next = cache->buckets[index];
    cache->buckets[index] = entry;
}

Record* get_from_cache(Cache *cache, int key) {
    size_t index = (size_t)key % cache->size;
    CacheEntry *entry = cache->buckets[index];
    while (entry) {
        if (entry->key == key) {
            return entry->record;
        }
        entry = entry->next;
    }
    return NULL;
}

void free_data_structure(DataStructure *ds) {
    free(ds->record);
    free(ds);
}

void free_cache(Cache *cache) {
    for (size_t i = 0; i < cache->size; ++i) {
        CacheEntry *entry = cache->buckets[i];
        while (entry) {
            CacheEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(cache->buckets);
}

int compare_records(const void *a, const void *b) {
    Record *record_a = ((DataStructure*)a)->record;
    Record *record_b = ((DataStructure*)b)->record;
    return record_a->value - record_b->value; // Ascending order
}

void sort_data_structures(DataStructure **ds_array, size_t count, int (*compare)(const void *, const void *)) {
    qsort(ds_array, count, sizeof(DataStructure*), compare);
}

int main() {
    srand(time(NULL));
    DataStructure *ds_array[10];
    Cache cache;
    initialize_cache(&cache, 10);

    for (size_t i = 0; i < 10; ++i) {
        ds_array[i] = initialize_data_structure(i, i);
        if (!ds_array[i]) {
            fprintf(stderr, "Failed to initialize data structure %zu\n", i);
            return EXIT_FAILURE;
        }
        insert_cache(&cache, i, ds_array[i]->record);
    }

    sort_data_structures(ds_array, 10, compare_records);

    for (size_t i = 0; i < 10; ++i) {
        Record *record = get_from_cache(&cache, i);
        if (!record) {
            fprintf(stderr, "Failed to retrieve record %zu from cache\n", i);
            return EXIT_FAILURE;
        }
        printf("Record %zu: Value = %d\n", i, record->value);
    }

    for (size_t i = 0; i < 10; ++i) {
        free_data_structure(ds_array[i]);
    }
    free_cache(&cache);

    return EXIT_SUCCESS;
}
