#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_REPORTS 1000

typedef struct {
    long timestamp;
    int status_code;
    char* description;
    int category_id;
} report;

report* reports[MAX_REPORTS];
int report_count = 0;

void initialize_report(int max_size) {
    for (int i = 0; i < max_size; i++) {
        reports[i] = NULL;
    }
}

void add_report(long timestamp, int status_code, const char* description, int category_id) {
    if (report_count >= MAX_REPORTS) {
        printf("Report limit reached.\n");
        return;
    }

    report* new_report = (report*)malloc(sizeof(report));
    if (!new_report) {
        printf("Memory allocation failed for report.\n");
        return;
    }

    new_report->timestamp = timestamp;
    new_report->status_code = status_code;
    new_report->description = strdup(description);
    new_report->category_id = category_id;

    reports[report_count++] = new_report;
}

int find_largest_timestamp() {
    if (report_count == 0) {
        return -1; // No reports
    }

    int largest_index = 0;
    for (int i = 1; i < report_count; i++) {
        if (reports[i]->timestamp > reports[largest_index]->timestamp) {
            largest_index = i;
        }
    }

    return reports[largest_index]->timestamp;
}

void cleanup_reports() {
    for (int i = 0; i < report_count; i++) {
        free(reports[i]->description);
        free(reports[i]);
    }
    report_count = 0;
}

int main() {
    initialize_report(MAX_REPORTS);

    // Example usage
    add_report(1633072800, 200, "System started", 1);
    add_report(1633072900, 500, "Error occurred", 2);

    int largest_timestamp = find_largest_timestamp();
    printf("Largest timestamp: %ld\n", largest_timestamp);

    cleanup_reports();

    return 0;
}
```

