#include <string.h>
#include <time.h>

#define MAX_REPORTS 1000
#define CATEGORY_1_MAX_SIZE 500
#define CATEGORY_2_MAX_SIZE 300

typedef struct {
    long timestamp;
    int status_code;
    char* description;
    int category_id;
} report;

typedef struct node {
    int data;
    struct node* next;
} node;

node* create_node(int data) {
    node* new_node = (node*)malloc(sizeof(node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(node** head, int data) {
    node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

int find_largest(int* arr, int size) {
    if (size == 0) {
        fprintf(stderr, "Array is empty\n");
        exit(1);
    }
    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

void free_report(report* r) {
    free(r->description);
    free(r);
}

void log_init() {
    printf("Initialization phase\n");
}

void log_cleanup() {
    printf("Cleanup phase\n");
}

int main() {
    report* reports = (report*)malloc(MAX_REPORTS * sizeof(report));
    if (reports == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    node* category_1_head = NULL;
    int category_2_array[MAX_CATEGORY_2_MAX_SIZE];
    int category_2_size = 0;

    log_init();

    // Read input and populate reports
    int num_reports;
    scanf("%d", &num_reports);
    for (int i = 0; i < num_reports; i++) {
        reports[i].timestamp = time(NULL);
        scanf("%d %s %d", &reports[i].status_code, reports[i].description, &reports[i].category_id);

        if (reports[i].category_id == 1) {
            insert_node(&category_1_head, reports[i].status_code);
        } else if (reports[i].category_id == 2 && category_2_size < MAX_CATEGORY_2_MAX_SIZE) {
            category_2_array[category_2_size++] = reports[i].status_code;
        }
    }

    // Find largest integer
    int largest = find_largest(reports, num_reports);
    printf("Largest integer: %d\n", largest);

    // Free dynamically allocated memory
    for (int i = 0; i < num_reports; i++) {
        free_report(&reports[i]);
    }
    free(reports);

    log_cleanup();

    return 0;
}
