Record* initialize_record(int num_elements, int range_start, int range_end) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    record->offsets = (long *)malloc(num_elements * sizeof(long));
    record->keys = (int *)malloc(num_elements * sizeof(int));
    record->values = (double *)malloc(num_elements * sizeof(double));

    if (!record->offsets || !record->keys || !record->values) {
        fprintf(stderr, "Memory allocation failed\n");
        free(record);
        return NULL;
    }

    // Initialize offsets and values with dummy data
    for (int i = 0; i < num_elements; i++) {
        record->offsets[i] = i * 10L;
        record->values[i] = i * 0.5;
    }

    // Set random value within the specified range
    srand(time(NULL));
    record->record_value = rand() % (range_end - range_start + 1) + range_start;

    return record;
}

void free_record(Record *record) {
    if (record) {
        free(record->offsets);
        free(record->keys);
        free(record->values);
        free(record);
    }
}

int main() {
    int num_elements = 10;
    Record *record = initialize_record(num_elements, 1, 100);

    if (record) {
        // Use the record
        printf("Record value: %d\n", record->record_value);

        free_record(record);
    }

    return 0;
}
