#include <openssl/evp.h>
#include <openssl/rand.h>

void initialize_aes_cipher(const char *password, unsigned char *key, unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    // Set key and IV length
    int key_len = 32; // AES-256 key length
    int iv_len = 16;  // AES block size

    // Generate key using SHA-1 hash of the password
    unsigned char sha1_key[SHA_DIGEST_LENGTH];
    SHA1((unsigned char *)password, strlen(password), sha1_key);
    memcpy(key, sha1_key, key_len);

    // Initialize IV with random values
    if (!RAND_bytes(iv, iv_len)) {
        fprintf(stderr, "Failed to generate random IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Set up the cipher context for AES-256-CBC encryption
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        fprintf(stderr, "Failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
}
