#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_EMAILS 10

typedef struct {
    int userID;
    char username[50];
    char emails[MAX_EMAILS][50];
} UserProfile;

typedef union {
    int intValue;
    float floatValue;
    double doubleValue;
    char* stringValue;
} RecordData;

typedef struct {
    RecordData data;
    int type; // 1 for int, 2 for float, 3 for double, 4 for char*
} Record;

int dynamicResourceManager(int numRecords, int minRange, int maxRange, int memorySize) {
    if (numRecords <= 0 || minRange > maxRange || memorySize <= 0) {
        return -1; // Invalid input
    }

    UserProfile* users = (UserProfile*)malloc(numRecords * sizeof(UserProfile));
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));

    if (!users || !records) {
        free(users);
        free(records);
        return -2; // Memory allocation failed
    }

    int emailCount = 0;
    for (int i = 0; i < numRecords; i++) {
        users[i].userID = i + 1;
        snprintf(users[i].username, sizeof(users[i].username), "user%d", i + 1);
        // Simulate reading emails from a distributed directory
        if (rand() % 2 == 0) {
            snprintf(users[i].emails[emailCount], sizeof(users[i].emails[emailCount]), "email%d@example.com", emailCount + 1);
            emailCount++;
        }
    }

    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            free(users);
            free(records);
            return -2; // Memory allocation failed
        }
        records[i]->type = rand() % 4 + 1; // Randomly choose data type
        switch (records[i]->type) {
            case 1:
                records[i]->data.intValue = rand() % (maxRange - minRange + 1) + minRange;
                break;
            case 2:
                records[i]->data.floatValue = ((float)(rand() % (maxRange - minRange + 1) + minRange)) / 10.0f;
                break;
            case 3:
                records[i]->data.doubleValue = ((double)(rand() % (maxRange - minRange + 1) + minRange)) / 100.0;
                break;
            case 4:
                records[i]->data.stringValue = (char*)malloc(20 * sizeof(char));
                snprintf(records[i]->data.stringValue, 20, "Value%d", rand() % 10);
                break;
        }
    }

    // Simulate database connection pool management
    int* offsets = (int*)malloc(numRecords * sizeof(int));
    int* keys = (int*)malloc(numRecords * sizeof(int));

    if (!offsets || !keys) {
        // Free previously allocated memory
        for (int i = 0; i < numRecords; i++) {
            free(records[i]);
        }
        free(users);
        free(records);
        free(offsets);
        free(keys);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < numRecords; i++) {
        offsets[i] = i * sizeof(int);
        keys[i] = rand() % numRecords;
    }

    // Simulate data persistence and logging
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        // Free previously allocated memory
        for (int i = 0; i < numRecords; i++) {
            free(records[i]);
        }
        free(users);
        free(records);
        free(offsets);
        free(keys);
        return -3; // File opening failed
    }

    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i]->data, sizeof(RecordData), 1, file);
    }
    fclose(file);

    // Free allocated memory
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }
    free(users);
    free(records);
    free(offsets);
    free(keys);

    return emailCount;
}
