    if (*offsets <= 0 || *keys <= 0) {
        fprintf(stderr, "Offset and key counts must be positive integers.\n");
        return -1;
    }
    srand(seed);
    return 0;
}

int allocate_memory(int offsets, int keys, Offset** offset_arr, Key** key_arr, Record** record_arr) {
    *offset_arr = (Offset*)malloc(offsets * sizeof(Offset));
    if (*offset_arr == NULL) {
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        return -1;
    }
    *key_arr = (Key*)malloc(keys * sizeof(Key));
    if (*key_arr == NULL) {
        free(*offset_arr);
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return -1;
    }
    int total_records = offsets + keys;
    *record_arr = (Record*)malloc(total_records * sizeof(Record));
    if (*record_arr == NULL) {
        free(*offset_arr);
        free(*key_arr);
        fprintf(stderr, "Memory allocation failed for records.\n");
        return -1;
    }
    return 0;
}

void initialize_records(int offsets, int keys, Record* record_arr) {
    int used_values[101] = {0};
    for (int i = 0; i < offsets + keys; ++i) {
        int value;
        do {
            value = rand() % 101;
        } while (used_values[value]);
        used_values[value] = 1;
        record_arr[i].data = value;
        if (i < offsets) {
            record_arr[i].offset_ptr = NULL;
        } else {
            record_arr[i].offset_ptr = &record_arr[0].offset_ptr[i - offsets];
        }
    }
}

void print_records(int offsets, int keys, Record* record_arr) {
    for (int i = 0; i < offsets + keys; ++i) {
        printf("Record %d: Data = %d", i, record_arr[i].data);
        if (record_arr[i].offset_ptr != NULL) {
            printf(", Offset Value = %ld\n", record_arr[i].offset_ptr->value);
        } else {
            printf("\n");
        }
    }
}

int main(int argc, char* argv[]) {
    int offsets, keys;
    if (validate_input(argc, argv, &offsets, &keys) != 0) {
        return -1;
    }

    Offset* offset_arr = NULL;
    Key* key_arr = NULL;
    Record* record_arr = NULL;

    if (allocate_memory(offsets, keys, &offset_arr, &key_arr, &record_arr) != 0) {
        return -1;
    }

    initialize_records(offsets, keys, record_arr);

    print_records(offsets, keys, record_arr);

    free(record_arr);
    free(key_arr);
    free(offset_arr);

    return 0;
}
