#define MAX_ENTRIES 1000

typedef struct {
    unsigned int id;
    char* str;
    double value;
} entry;

entry* init_entries(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    entry* entries = (entry*)malloc(MAX_ENTRIES * sizeof(entry));
    if (!entries) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    srand(time(NULL));
    int id_count = 0;

    while (fscanf(file, "%s %lf", entries[id_count].str, &entries[id_count].value) == 2) {
        entries[id_count].id = rand() % MAX_ENTRIES;
        for (int i = 0; i < id_count; ++i) {
            if (entries[i].id == entries[id_count].id) {
                --id_count;
                break;
            }
        }
        if (id_count >= MAX_ENTRIES - 1) {
            fprintf(stderr, "Too many unique IDs\n");
            free(entries);
            fclose(file);
            return NULL;
        }
        ++id_count;
    }

    *count = id_count;
    fclose(file);
    return entries;
}

void find_max_string_and_value(entry* entries, int count) {
    char* max_str = entries[0].str;
    double max_val = entries[0].value;

    for (int i = 1; i < count; ++i) {
        if (strlen(entries[i].str) > strlen(max_str)) {
            max_str = entries[i].str;
        }
        if (entries[i].value > max_val) {
            max_val = entries[i].value;
        }
    }

    printf("Longest string: %s\n", max_str);
    printf("Highest value: %.2f\n", max_val);
}

void cleanup_entries(entry* entries, int count) {
    for (int i = 0; i < count; ++i) {
        free(entries[i].str);
    }
    free(entries);
}
