#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define a structure for bitmap resources
typedef struct {
    char* key;
    int offset;
    int value;
} BitmapResource;

// Define a structure for themes
typedef struct {
    char* themeName;
    BitmapResource** bitmaps;
    int numBitmaps;
} Theme;

// Define a structure for the library
typedef struct {
    Theme** themes;
    int numThemes;
    pthread_mutex_t mutex;
} BitmapLibrary;

// Function to initialize the bitmap library
BitmapLibrary* initBitmapLibrary() {
    BitmapLibrary* lib = (BitmapLibrary*)malloc(sizeof(BitmapLibrary));
    lib->themes = NULL;
    lib->numThemes = 0;
    pthread_mutex_init(&lib->mutex, NULL);
    return lib;
}

// Function to add a theme to the library
void addTheme(BitmapLibrary* lib, Theme* theme) {
    pthread_mutex_lock(&lib->mutex);
    lib->themes = realloc(lib->themes, (lib->numThemes + 1) * sizeof(Theme*));
    lib->themes[lib->numThemes] = theme;
    lib->numThemes++;
    pthread_mutex_unlock(&lib->mutex);
}

// Function to remove a theme from the library
void removeTheme(BitmapLibrary* lib, char* themeName) {
    pthread_mutex_lock(&lib->mutex);
    for (int i = 0; i < lib->numThemes; i++) {
        if (strcmp(lib->themes[i]->themeName, themeName) == 0) {
            free(lib->themes[i]);
            for (int j = i; j < lib->numThemes - 1; j++) {
                lib->themes[j] = lib->themes[j + 1];
            }
            lib->numThemes--;
            break;
        }
    }
    pthread_mutex_unlock(&lib->mutex);
}

// Function to preview a bitmap resource
void previewBitmap(BitmapLibrary* lib, char* themeName, int index) {
    pthread_mutex_lock(&lib->mutex);
    for (int i = 0; i < lib->numThemes; i++) {
        if (strcmp(lib->themes[i]->themeName, themeName) == 0) {
            if (index >= 0 && index < lib->themes[i]->numBitmaps) {
                BitmapResource* bitmap = lib->themes[i]->bitmaps[index];
                printf("Previewing bitmap: %s, Offset: %d, Value: %d\n", bitmap->key, bitmap->offset, bitmap->value);
            }
            break;
        }
    }
    pthread_mutex_unlock(&lib->mutex);
}

// Function to clean up the library
void cleanupBitmapLibrary(BitmapLibrary* lib) {
    pthread_mutex_lock(&lib->mutex);
    for (int i = 0; i < lib->numThemes; i++) {
        free(lib->themes[i]);
    }
    free(lib->themes);
    pthread_mutex_destroy(&lib->mutex);
    free(lib);
}
