#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct data_node {
    int counter;
    struct data_node* next;
} data_node;

typedef struct hash_table {
    size_t size;
    data_node** buckets;
} hash_table;

hash_table* create_hash_table(size_t size) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    if (!table) {
        fprintf(stderr, "Memory allocation failed for hash table\n");
        return NULL;
    }
    table->size = size;
    table->buckets = (data_node**)calloc(size, sizeof(data_node*));
    if (!table->buckets) {
        fprintf(stderr, "Memory allocation failed for buckets\n");
        free(table);
        return NULL;
    }
    return table;
}

void destroy_hash_table(hash_table* table) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        data_node* node = table->buckets[i];
        while (node) {
            data_node* next = node->next;
            free(node);
            node = next;
        }
    }

    free(table->buckets);
    free(table);
}

unsigned long hash_function(const char* key, size_t size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % size;
}

int insert_into_hash_table(hash_table* table, const char* key, data_node* value) {
    if (!table || !key || !value) return -1;

    unsigned long index = hash_function(key, table->size);
    value->next = table->buckets[index];
    table->buckets[index] = value;
    return 0;
}

data_node* find_in_hash_table(hash_table* table, const char* key) {
    if (!table || !key) return NULL;

    unsigned long index = hash_function(key, table->size);
    data_node* node = table->buckets[index];
    while (node) {
        if (strcmp(node->key, key) == 0) {
            return node;
        }
        node = node->next;
    }
    return NULL;
}

int main() {
    hash_table* table = create_hash_table(100);
    if (!table) return -1;

    data_node* newNode = (data_node*)malloc(sizeof(data_node));
    if (!newNode) {
        destroy_hash_table(table);
        fprintf(stderr, "Memory allocation failed for new node\n");
        return -1;
    }
    newNode->counter = 0;
    newNode->next = NULL;

    insert_into_hash_table(table, "exampleKey", newNode);

    data_node* foundNode = find_in_hash_table(table, "exampleKey");
    if (foundNode) {
        printf("Found node with key: exampleKey\n");
    } else {
        printf("Node not found\n");
    }

    destroy_hash_table(table);
    free(newNode);

    return 0;
}
