typedef struct {
    float x;
    float y;
} Point;

typedef struct {
    double value;
    char* id;
    Point point;
} Transaction;

typedef struct {
    int size;
    int capacity;
    Transaction* transactions;
} TransactionPool;

Transaction* create_transaction(double min_value, double max_value) {
    Transaction* transaction = (Transaction*)malloc(sizeof(Transaction));
    if (!transaction) {
        fprintf(stderr, "Memory allocation failed for transaction\n");
        return NULL;
    }
    transaction->value = min_value + (double)(rand() / (RAND_MAX / (max_value - min_value)));
    transaction->id = (char*)malloc(20 * sizeof(char));
    if (!transaction->id) {
        fprintf(stderr, "Memory allocation failed for transaction ID\n");
        free(transaction);
        return NULL;
    }
    snprintf(transaction->id, 20, "%ld", time(NULL)); // Simple thread-safe mechanism
    transaction->point.x = (float)(rand() / (RAND_MAX / 100.0));
    transaction->point.y = (float)(rand() / (RAND_MAX / 100.0));
    return transaction;
}

void free_transaction(Transaction* transaction) {
    if (transaction) {
        free(transaction->id);
        free(transaction);
    }
}

TransactionPool* create_transaction_pool(int initial_capacity) {
    TransactionPool* pool = (TransactionPool*)malloc(sizeof(TransactionPool));
    if (!pool) {
        fprintf(stderr, "Memory allocation failed for transaction pool\n");
        return NULL;
    }
    pool->size = 0;
    pool->capacity = initial_capacity;
    pool->transactions = (Transaction**)malloc(initial_capacity * sizeof(Transaction*));
    if (!pool->transactions) {
        fprintf(stderr, "Memory allocation failed for transaction array\n");
        free(pool);
        return NULL;
    }
    return pool;
}

void add_transaction_to_pool(TransactionPool* pool, Transaction* transaction) {
    if (pool->size >= pool->capacity) {
        pool->capacity *= 2;
        pool->transactions = (Transaction**)realloc(pool->transactions, pool->capacity * sizeof(Transaction*));
        if (!pool->transactions) {
            fprintf(stderr, "Memory reallocation failed for transaction array\n");
            return;
        }
    }
    pool->transactions[pool->size++] = transaction;
}

void free_transaction_pool(TransactionPool* pool) {
    if (pool) {
        for (int i = 0; i < pool->size; i++) {
            free_transaction(pool->transactions[i]);
        }
        free(pool->transactions);
        free(pool);
    }
}

typedef struct {
    int value;
} Record;

Record* create_record(int min_value, int max_value) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation failed for record\n");
        return NULL;
    }
    record->value = min_value + rand() % (max_value - min_value);
    return record;
}

void free_record(Record* record) {
    if (record) {
        free(record);
    }
}
