    if (!manager) return NULL;

    manager->records = (record**)calloc(initial_capacity, sizeof(record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_record_manager(record_manager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->records[i]->label);
        free(manager->records[i]);
    }
    free(manager->records);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_record(record_manager* manager, int key, const char* label, int value_range_min, int value_range_max) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        record** new_records = (record**)realloc(manager->records, new_capacity * sizeof(record*));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return; // Handle error
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    record* new_record = (record*)malloc(sizeof(record));
    if (!new_record) {
        pthread_mutex_unlock(&manager->lock);
        return; // Handle error
    }

    new_record->key = key;
    new_record->value = value_range_min + rand() % (value_range_max - value_range_min + 1);
    new_record->label = strdup(label);
    if (!new_record->label) {
        free(new_record);
        pthread_mutex_unlock(&manager->lock);
        return; // Handle error
    }

    manager->records[manager->size++] = new_record;

    pthread_mutex_unlock(&manager->lock);
}

void remove_record(record_manager* manager, int key) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i]->key == key) {
            free(manager->records[i]->label);
            free(manager->records[i]);
            memmove(&manager->records[i], &manager->records[i + 1], (manager->size - i - 1) * sizeof(record*));
            --manager->size;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void log_memory_usage(record_manager* manager) {
