#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct node {
    char* str;
    int weight;
    struct node* next;
} Node;

typedef struct hash_table {
    Node** buckets;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;

    table->buckets = (Node**)calloc(initial_size, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->size = initial_size;
    table->count = 0;
    pthread_mutex_init(&table->lock, NULL);

    printf("Hash table initialized with size %zu\n", initial_size);
    return table;
}

void destroy_hash_table(HashTable* table) {
    if (!table) return;

    for (size_t i = 0; i < table->size; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next = node->next;
            free(node->str);
            free(node);
            node = next;
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);

    printf("Hash table destroyed\n");
}

void insert_node(HashTable* table, const char* str, int weight) {
    if (!table || !str) return;

    pthread_mutex_lock(&table->lock);

    size_t hash = 0;
    for (size_t i = 0; str[i]; ++i) {
        hash = (hash * 31 + str[i]) % table->size;
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return;
    }

    new_node->str = strdup(str);
    new_node->weight = weight;
    new_node->next = table->buckets[hash];
    table->buckets[hash] = new_node;

    ++table->count;

    if (table->count >= table->size) {
        // Resize the hash table
        size_t new_size = table->size * 2;
        Node** new_buckets = (Node**)calloc(new_size, sizeof(Node*));
        if (!new_buckets) {
            pthread_mutex_unlock(&table->lock);
            return;
        }

        for (size_t i = 0; i < table->size; ++i) {
            Node* node = table->buckets[i];
            while (node) {
                Node* next = node->next;
                size_t new_hash = 0;
                for (size_t j = 0; node->str[j]; ++j) {
                    new_hash = (new_hash * 31 + node->str[j]) % new_size;
                }
                node->next = new_buckets[new_hash];
                new_buckets[new_hash] = node;
                node = next;
            }
        }

        free(table->buckets);
        table->buckets = new_buckets;
        table->size = new_size;

        printf("Hash table resized to size %zu\n", new_size);
    }

    pthread_mutex_unlock(&table->lock);
}

int main() {
    HashTable* table = create_hash_table(10);

    insert_node(table, "apple", 5);
    insert_node(table, "banana", 3);
    insert_node(table, "cherry", 7);

    destroy_hash_table(table);

    return 0;
}
