#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    float value;
    int* array;
    char* buffer;
} Record;

Record* allocate_records(int num_records) {
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return records;
}

void free_records(Record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].array);
        free(records[i].buffer);
    }
    free(records);
}

void initialize_record(Record* record, float value, int array_size, const char* buffer) {
    record->value = value;
    record->array = (int*)malloc(array_size * sizeof(int));
    if (!record->array) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < array_size; ++i) {
        record->array[i] = i;
    }
    record->buffer = strdup(buffer);
    if (!record->buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void process_files(Record* records, int num_records, const char* file_names[], int num_files) {
    for (int i = 0; i < num_files; ++i) {
        FILE* file = fopen(file_names[i], "r");
        if (!file) {
            fprintf(stderr, "Failed to open file: %s\n", file_names[i]);
            continue;
        }
        int record_index = 0;
        while (record_index < num_records && fscanf(file, "%f", &records[record_index].value) == 1) {
            // Process the value and initialize other fields as needed
            initialize_record(&records[record_index], records[record_index].value, 10, "example_buffer");
            record_index++;
        }
        fclose(file);
    }
}

int main() {
    int num_records = 1000;
    Record* records = allocate_records(num_records);

    const char* file_names[] = {"file1.txt", "file2.txt"};
    int num_files = sizeof(file_names) / sizeof(file_names[0]);

    process_files(records, num_records, file_names, num_files);

    free_records(records, num_records);

    return 0;
}
