#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_STRING_LENGTH 64

typedef struct {
    int key;
    short field;
    char *str;
} Record;

int generate_unique_key(int min, int max, int *used_keys, int used_count) {
    srand(time(NULL));
    int key;
    do {
        key = rand() % (max - min + 1) + min;
    } while (key < min || key > max || (used_count && memchr(used_keys, key, used_count * sizeof(int)) != NULL));
    return key;
}

Record* initialize_records(int num_records, int min_key, int max_key, const char *default_str) {
    if (num_records <= 0 || min_key >= max_key) {
        fprintf(stderr, "Invalid input parameters.\n");
        return NULL;
    }

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return NULL;
    }

    int *used_keys = calloc(num_records, sizeof(int));
    if (!used_keys) {
        fprintf(stderr, "Memory allocation failed for used keys.\n");
        free(records);
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].key = generate_unique_key(min_key, max_key, used_keys, i);
        records[i].field = rand() % SHRT_MAX;
        records[i].str = malloc(MAX_STRING_LENGTH * sizeof(char));
        if (!records[i].str) {
            fprintf(stderr, "Memory allocation failed for string at index %d.\n", i);
            for (int j = 0; j < i; ++j) {
                free(records[j].str);
            }
            free(used_keys);
            free(records);
            return NULL;
        }
        strncpy(records[i].str, default_str, MAX_STRING_LENGTH - 1);
        records[i].str[MAX_STRING_LENGTH - 1] = '\0';
    }

    free(used_keys);
    return records;
}

void free_records(Record *records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].str);
    }
    free(records);
}

int main() {
    int num_records = 10;
    int min_key = 1;
    int max_key = 100;
    const char *default_str = "DefaultString";

    Record *records = initialize_records(num_records, min_key, max_key, default_str);
    if (records) {
        for (int i = 0; i < num_records; ++i) {
            printf("Record %d: Key=%d, Field=%hd, Str='%s'\n", i, records[i].key, records[i].field, records[i].str);
        }
        free_records(records, num_records);
    }

    return 0;
}
