int buffer_index = 0;
pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    int key;
    int present;
} hash_table_entry;

hash_table_entry hash_table[MAX_ITEMS];
int hash_table_size = MAX_ITEMS;
pthread_mutex_t hash_lock = PTHREAD_MUTEX_INITIALIZER;

void* initialize_items(void* arg) {
    FILE* file = fopen("data.csv", "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        item new_item;
        sscanf(line, "%lf,%[^,],%ld", &new_item.value, new_item.id, &new_item.offset);

        pthread_mutex_lock(&item_lock);
        if (item_count < MAX_ITEMS) {
            items[item_count++] = new_item;
        }
        pthread_mutex_unlock(&item_lock);

        pthread_mutex_lock(&hash_lock);
        int hash_index = new_item.id[0] % hash_table_size;
        while (hash_table[hash_index].present) {
            hash_index = (hash_index + 1) % hash_table_size;
        }
        hash_table[hash_index].key = atoi(new_item.id);
        hash_table[hash_index].present = 1;
        pthread_mutex_unlock(&hash_lock);
    }

    fclose(file);
    return NULL;
}

void* process_results(void* arg) {
    // Implement asynchronous callback processing logic here
    return NULL;
}

