    char status[20];
    time_t timestamp;
    char metadata[100];
} Record;

typedef struct {
    Record *records;
    size_t count;
    pthread_mutex_t lock;
} RecordCollection;

int generate_metadata(const char *seed, char *metadata) {
    // Simulate fetching metadata from an external data source
    snprintf(metadata, sizeof(metadata), "Metadata for seed: %s", seed);
    return 0; // Return 0 on success
}

void initialize_record(Record *record, int value, const char *status, time_t timestamp, const char *metadata) {
    record->value = value;
    strncpy(record->status, status, sizeof(record->status));
    record->timestamp = timestamp;
    strncpy(record->metadata, metadata, sizeof(record->metadata));
}

int create_record_collection(size_t initial_size, RecordCollection **collection) {
    *collection = (RecordCollection *)malloc(sizeof(RecordCollection));
    if (*collection == NULL) {
        return -1; // Memory allocation failed
    }
    (*collection)->records = (Record *)calloc(initial_size, sizeof(Record));
    if ((*collection)->records == NULL) {
        free(*collection);
        return -2; // Memory allocation failed
    }
    (*collection)->count = initial_size;
    pthread_mutex_init(&(*collection)->lock, NULL);
    return 0; // Success
}

void destroy_record_collection(RecordCollection *collection) {
    if (collection != NULL) {
        free(collection->records);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

int add_record(RecordCollection *collection, int value, const char *status, const char *seed) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= MAX_RECORDS) {
        pthread_mutex_unlock(&collection->lock);
        return -3; // Collection is full
    }
    Record *new_record = &collection->records[collection->count];
    time_t timestamp = time(NULL);
    char metadata[100];
    if (generate_metadata(seed, metadata) != 0) {
        pthread_mutex_unlock(&collection->lock);
        return -4; // Failed to generate metadata
    }
    initialize_record(new_record, value, status, timestamp, metadata);
    collection->count++;
    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

int main() {
    RecordCollection *collection;
    if (create_record_collection(100, &collection) != 0) {
        fprintf(stderr, "Failed to create record collection\n");
        return 1;
    }
    if (add_record(collection, 42, "Active", "seed123") != 0) {
        fprintf(stderr, "Failed to add record\n");
    }
    destroy_record_collection(collection);
    return 0;
}
