#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* str;
} record;

void manage_memory(long num_elements, int key_count, const char* user_string, unsigned seed) {
    if (num_elements <= 0 || key_count <= 0 || user_string == NULL) {
        fprintf(stderr, "Invalid input sizes.\n");
        return;
    }

    long max_size = 10 * 1000 * 1000; // 10 million elements
    if (num_elements > max_size) {
        fprintf(stderr, "Exceeds maximum allowed elements.\n");
        return;
    }

    size_t string_length = strlen(user_string);
    if (string_length == 0 || string_length >= INT_MAX) {
        fprintf(stderr, "Invalid user string length.\n");
        return;
    }

    long total_memory_needed = num_elements * sizeof(long) + key_count * sizeof(int) + key_count * (sizeof(record) + string_length + 1);
    if (total_memory_needed > 2 * 1024 * 1024 * 1024) {
        fprintf(stderr, "Total memory exceeds 2GB limit.\n");
        return;
    }

    long* long_array = (long*)malloc(num_elements * sizeof(long));
    int* key_array = (int*)malloc(key_count * sizeof(int));
    record* record_array = (record*)malloc(key_count * sizeof(record));

    if (long_array == NULL || key_array == NULL || record_array == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(long_array);
        free(key_array);
        free(record_array);
        return;
    }

    srand(seed);
    for (int i = 0; i < num_elements; ++i) {
        long_array[i] = rand();
    }

    for (int i = 0; i < key_count; ++i) {
        key_array[i] = i;
        record_array[i].value = rand() % 1000;
        record_array[i].str = (char*)malloc((string_length + 1) * sizeof(char));
        if (record_array[i].str == NULL) {
            fprintf(stderr, "Memory allocation failed for string.\n");
            free(long_array);
            free(key_array);
            for (int j = 0; j < i; ++j) {
                free(record_array[j].str);
            }
            free(record_array);
            return;
        }
        strncpy(record_array[i].str, user_string, string_length + 1);
    }

    // Simulate data processing
    for (int i = 0; i < key_count; ++i) {
        printf("Record %d: Value = %d, String = %s\n", i, record_array[i].value, record_array[i].str);
    }

    // Free allocated memory
    free(long_array);
    free(key_array);
    for (int i = 0; i < key_count; ++i) {
        free(record_array[i].str);
    }
    free(record_array);

    printf("Memory management completed successfully.\n");
}

int main() {
    long num_elements = 5 * 1000 * 1000; // Example input
    int key_count = 2 * 1000 * 1000;
    const char* user_string = "ExampleString";
    unsigned seed = time(NULL);

    manage_memory(num_elements, key_count, user_string, seed);

    return 0;
}
