typedef struct {
    event_type type;
    char* str;
    float value;
} event;

void manage_memory(int num_ints, int seed, const char* user_str) {
    if (num_ints <= 0 || strlen(user_str) > 256) {
        fprintf(stderr, "Invalid input size or string length.\n");
        return;
    }

    long* long_array = malloc(num_ints * sizeof(long));
    int* key_array = malloc(num_ints * sizeof(int));
    record* record_array = malloc(num_ints * sizeof(record));
    event* event_array = malloc(num_ints * sizeof(event));

    if (!long_array || !key_array || !record_array || !event_array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    srand(seed);
    for (int i = 0; i < num_ints; i++) {
        long_array[i] = rand() % 1000000;
        key_array[i] = i;

        record_array[i].value = rand() % 1000;
        record_array[i].str = malloc(256 * sizeof(char));
        strncpy(record_array[i].str, user_str, 255);
        record_array[i].str[255] = '\0';
        record_array[i].timestamp = (double)rand() / RAND_MAX;

        event_array[i].type = (event_type)(rand() % 2);
        event_array[i].str = malloc(256 * sizeof(char));
        strncpy(event_array[i].str, user_str, 255);
        event_array[i].str[255] = '\0';
        event_array[i].value = (float)rand() / RAND_MAX;
    }

    // Simulate data processing pipeline
    for (int i = 0; i < num_ints; i++) {
        printf("Processing record %d: value=%d, str='%s', timestamp=%.2f\n", 
               i, record_array[i].value, record_array[i].str, record_array[i].timestamp);
        printf("Processing event %d: type=%d, str='%s', value=%.2f\n", 
               i, event_array[i].type, event_array[i].str, event_array[i].value);
    }

    // Free allocated memory
    for (int i = 0; i < num_ints; i++) {
        free(record_array[i].str);
        free(event_array[i].str);
    }
    free(long_array);
    free(key_array);
    free(record_array);
    free(event_array);

    printf("Memory management completed.\n");
}

int main() {
    int num_ints = 1000000;
    int seed = 42;
    const char* user_str = "example_string";

    manage_memory(num_ints, seed, user_str);

    return 0;
}
