void* allocateMemory(size_t numRecords, size_t maxKeyValue) {
    // Calculate initial allocation sizes based on estimates
    size_t offsetSize = numRecords * sizeof(long);
    size_t keySize = numRecords * sizeof(int);
    size_t recordSize = numRecords * sizeof(Record);

    // Allocate memory for each array
    long* offsets = (long*)malloc(offsetSize);
    int* keys = (int*)malloc(keySize);
    Record* records = (Record*)malloc(recordSize);

    if (!offsets || !keys || !records) {
        // Handle memory allocation failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize arrays
    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = 0; // Example initialization
        keys[i] = rand() % maxKeyValue; // Random key within the specified range
        records[i].intValue = rand(); // Random int value
        records[i].floatValue = (float)rand() / RAND_MAX; // Random float value
        memset(records[i].charArray, 0, sizeof(records[i].charArray)); // Null-terminate char array
    }

    // Return a pointer to the allocated memory block
    return offsets;
}

void freeMemory(void* memoryBlock) {
    if (memoryBlock) {
        free(memoryBlock);
    }
}
