#include <stdlib.h>
#include <time.h>

typedef struct data {
    double value;
} Data;

typedef struct dependency {
    struct entry *entry;
    struct dependency *next;
} Dependency;

typedef struct entry {
    Data *data;
    int index;
    Dependency *dependencies;
} Entry;

Entry** initialize_entries(int num_entries, double min_value, double max_value) {
    if (num_entries <= 0 || min_value > max_value) {
        return NULL;
    }

    srand(time(NULL));
    Entry **entries = (Entry **)malloc(num_entries * sizeof(Entry *));
    if (!entries) {
        return NULL;
    }

    for (int i = 0; i < num_entries; ++i) {
        entries[i] = (Entry *)malloc(sizeof(Entry));
        if (!entries[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) {
                free(entries[j]);
            }
            free(entries);
            return NULL;
        }

        entries[i]->data = (Data *)malloc(sizeof(Data));
        if (!entries[i]->data) {
            // Free previously allocated memory on failure
            for (int j = 0; j <= i; ++j) {
                free(entries[j]->data);
                free(entries[j]);
            }
            free(entries);
            return NULL;
        }

        entries[i]->index = i;
        entries[i]->data->value = min_value + (double)(rand() / (RAND_MAX / (max_value - min_value)));
        entries[i]->dependencies = NULL;

        // Initialize dependencies (example: each entry depends on the next one)
        if (i < num_entries - 1) {
            Dependency *dep = (Dependency *)malloc(sizeof(Dependency));
            if (!dep) {
                // Free previously allocated memory on failure
                for (int j = 0; j <= i; ++j) {
                    free(entries[j]->data);
                    free(entries[j]);
                }
                free(entries);
                return NULL;
            }

            dep->entry = entries[i + 1];
            dep->next = entries[i]->dependencies;
            entries[i]->dependencies = dep;
        }
    }

    return entries;
}
