typedef enum {
    RECORD_TYPE_0,
    RECORD_TYPE_1
} RecordType;

typedef struct {
    int status;
    time_t timestamp;
    void* metadata;
} Record;

Record* create_record(RecordType type, const char* initial_metadata) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        perror("Failed to allocate memory for record");
        return NULL;
    }

    record->status = 0; // Default status
    time(&record->timestamp);

    switch (type) {
        case RECORD_TYPE_0:
            record->metadata = strdup(initial_metadata);
            if (!record->metadata) {
                perror("Failed to allocate memory for metadata");
                free(record);
                return NULL;
            }
            break;
        case RECORD_TYPE_1:
            // Assuming JSON object is a null-terminated string
            record->metadata = strdup(initial_metadata);
            if (!record->metadata) {
                perror("Failed to allocate memory for metadata");
                free(record);
                return NULL;
            }
            break;
        default:
            fprintf(stderr, "Invalid record type\n");
            free(record);
            return NULL;
    }

    return record;
}

void free_record(Record* record) {
    if (record->metadata) {
        free(record->metadata);
    }
    free(record);
}

int main() {
    Record* rec0 = create_record(RECORD_TYPE_0, "Initial metadata for type 0");
    if (rec0) {
        printf("Record created successfully\n");
        free_record(rec0);
    }

    Record* rec1 = create_record(RECORD_TYPE_1, "{\"key\": \"value\"}");
    if (rec1) {
        printf("Record created successfully\n");
        free_record(rec1);
    }

    return 0;
}
