typedef struct sensor_data {
    long timestamp;
    double measurement;
    Point* point;
} SensorData;

SensorData* initialize_sensor_data(int count, double* measurements, Point** points) {
    if (count <= 0 || measurements == NULL || points == NULL) {
        return NULL;
    }

    SensorData* sensor_array = (SensorData*)malloc(count * sizeof(SensorData));
    if (sensor_array == NULL) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < count; i++) {
        sensor_array[i].timestamp = time(NULL); // Get current timestamp
        sensor_array[i].measurement = measurements[i];
        sensor_array[i].point = points[i];

        if (sensor_array[i].point == NULL) {
            free(sensor_array);
            return NULL; // Memory allocation failed for point
        }
    }

    return sensor_array;
}

void cleanup_sensor_data(SensorData* sensor_array, int count) {
    if (sensor_array != NULL) {
        for (int i = 0; i < count; i++) {
            free(sensor_array[i].point); // Free each point
        }
        free(sensor_array); // Free the array of SensorData
    }
}
