    for (int i = 0; i < num_elements; i++) {
        records[i].value = rand() % 1000000;
        size_t str_len = strlen(str);
        if (str_len > 256) {
            str_len = 256;
        }
        records[i].str = custom_malloc(str_len + 1);
        strncpy(records[i].str, str, str_len);
        records[i].str[str_len] = '\0';
    }

    return records;
}

void free_records(record* records, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        free(records[i].str);
    }
    free(records);
}

