void initialize_arrays(long** timestamps, float** readings, Event** events, size_t initial_size) {
    *timestamps = allocate_memory(initial_size * sizeof(long));
    *readings = allocate_memory(initial_size * sizeof(float));
    *events = allocate_memory(initial_size * sizeof(Event));

    srand(time(NULL));
    for (size_t i = 0; i < initial_size; ++i) {
        (*timestamps)[i] = rand();
        (*readings)[i] = ((float)rand() / RAND_MAX) * 100.0f;
        (*events)[i].intensity = ((double)rand() / RAND_MAX) * 1000.0;
    }
}

void cleanup_arrays(long* timestamps, float* readings, Event* events, size_t size) {
    free_memory(timestamps);
    free_memory(readings);
    free_memory(events);
}

