#include <string.h>
#include <time.h>
#include <openssl/md5.h>

typedef struct {
    int value;
    int *key;
} record;

char* generate_md5(const char *str) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)str, strlen(str), (unsigned char*)&digest);    

    char *md5_str = malloc(33);
    for(int i = 0; i < 16; ++i)
        sprintf(&md5_str[i*2], "%02x", (unsigned int)digest[i]);

    return md5_str;
}

record* initialize_records(long *offsets, int *keys, int num_records, int range_start, int range_end) {
    record *records = malloc(num_records * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (range_end - range_start + 1) + range_start;
        records[i].key = &keys[i];
    }

    return records;
}

void free_resources(long *offsets, int *keys, record *records, int num_records) {
    free(offsets);
    free(keys);
    for (int i = 0; i < num_records; ++i)
        free(records[i].key); // Assuming keys are dynamically allocated
    free(records);
}

int main() {
    const char *input_string = "example_string";
    char *md5_result = generate_md5(input_string);
    printf("MD5: %s\n", md5_result);

    long offsets[] = {10, 20, 30};
    int keys[] = {1, 2, 3};
    record *records = initialize_records(offsets, keys, 3, 100, 200);

    // Use records...

    free_resources(offsets, keys, records, 3);
    free(md5_result);

    return 0;
}
