#include <string.h>
#include <json-c/json.h>

typedef struct Setting {
    char* name;
    int type;
    void* value;
    struct Setting* next;
} Setting;

Setting* create_setting(const char* name, int type, void* value) {
    Setting* new_setting = (Setting*)malloc(sizeof(Setting));
    if (!new_setting) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    new_setting->name = strdup(name);
    new_setting->type = type;
    new_setting->value = value;
    new_setting->next = NULL;
    return new_setting;
}

void free_setting(Setting* setting) {
    if (setting) {
        free(setting->name);
        free(setting->value);
        free(setting);
    }
}

int parse_json_to_settings() {
    json_object* root;
    const char* input = "{\"name\":\"example\", \"type\":1, \"value\":42}";
    root = json_tokener_parse(input);

    if (!root) {
        fprintf(stderr, "Failed to parse JSON\n");
        return -1;
    }

    json_object* name_obj;
    json_object* type_obj;
    json_object* value_obj;

    if (json_object_object_get_ex(root, "name", &name_obj) &&
        json_object_object_get_ex(root, "type", &type_obj) &&
        json_object_object_get_ex(root, "value", &value_obj)) {

        const char* name = json_object_get_string(name_obj);
        int type = json_object_get_int(type_obj);
        void* value;

        switch (type) {
            case 1:
                value = malloc(sizeof(int));
                if (!value) {
                    fprintf(stderr, "Memory allocation failed\n");
                    json_object_put(root);
                    return -1;
                }
                *(int*)value = json_object_get_int(value_obj);
                break;
            // Add more cases for other types
            default:
                fprintf(stderr, "Unsupported type\n");
                json_object_put(root);
                return -1;
        }

        Setting* new_setting = create_setting(name, type, value);
        if (!new_setting) {
            free(value);
            json_object_put(root);
            return -1;
        }

        // Insert into linked list
        // ...

        json_object_put(root);
    } else {
        fprintf(stderr, "Missing required fields in JSON\n");
        json_object_put(root);
        return -1;
    }

    return 0;
}

int main() {
    if (parse_json_to_settings() != 0) {
        fprintf(stderr, "Failed to parse settings\n");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
