import java.io.File;
import java.util.HashMap;
import java.util.Map;

public class ThemeCache {
    private Map<String, File> cacheMap = new HashMap<>();
    private long maxMemory;
    private long usedMemory;
    private String defaultThemeDir;
    private List<String> allowedDirs;

    public ThemeCache(long maxMemory, List<String> allowedDirs) {
        this.maxMemory = maxMemory;
        this.allowedDirs = allowedDirs;
        this.usedMemory = 0;
        this.defaultThemeDir = getDefaultThemeDirectory();
    }

    private String getDefaultThemeDirectory() {
        // Logic to determine the default theme directory based on storage and device settings
        return "/default_theme_dir";
    }

    public void setDefaultThemeDir(String dir) {
        if (allowedDirs.contains(dir)) {
            this.defaultThemeDir = dir;
        } else {
            throw new IllegalArgumentException("Invalid theme directory");
        }
    }

    public File getTheme(String themeName) {
        File cachedFile = cacheMap.get(themeName);
        if (cachedFile != null && cachedFile.exists()) {
            return cachedFile;
        } else {
            // Logic to fetch and cache the theme
            File newFile = fetchAndCacheTheme(themeName);
            return newFile;
        }
    }

    private File fetchAndCacheTheme(String themeName) {
        // Logic to fetch the theme from a remote source or local storage
        File file = new File(defaultThemeDir, themeName);
        if (file.exists()) {
            cacheMap.put(themeName, file);
            usedMemory += file.length();
            evictIfNecessary();
        }
        return file;
    }

    private void evictIfNecessary() {
        while (usedMemory > maxMemory) {
            // Logic to evict the least recently used or least frequently used theme
            String keyToRemove = findLeastUsedKey();
            File fileToRemove = cacheMap.remove(keyToRemove);
            if (fileToRemove != null) {
                usedMemory -= fileToRemove.length();
            }
        }
    }

    private String findLeastUsedKey() {
        // Logic to find the key with the least usage
        return "least_used_key";
    }

    public void invalidateCache() {
        cacheMap.clear();
        usedMemory = 0;
    }

    public void logCacheOperation(String operation) {
        // Logic to log cache operations
        System.out.println("Cache Operation: " + operation);
    }
}
