class KDTreeNode {
public:
    std::vector<T> data;
    KDTreeNode* left;
    KDTreeNode* right;

    KDTreeNode(const std::vector<T>& point) : data(point), left(nullptr), right(nullptr) {}
};

template<typename T>
class KDTree {
private:
    KDTreeNode<T>* root;
    int featureSize;
    int maxDepth;
    int leafNodeCapacity;
    std::mutex treeMutex;

    KDTreeNode<T>* buildKDTree(const std::vector<std::vector<T>>& points, int depth = 0) {
        if (points.empty()) return nullptr;

        int axis = depth % featureSize;
        std::sort(points.begin(), points.end(), [axis](const std::vector<T>& a, const std::vector<T>& b) {
            return a[axis] < b[axis];
        });

        int medianIndex = points.size() / 2;
        KDTreeNode<T>* node = new KDTreeNode<T>(points[medianIndex]);

        std::vector<std::vector<T>> leftPoints(points.begin(), points.begin() + medianIndex);
        std::vector<std::vector<T>> rightPoints(points.begin() + medianIndex + 1, points.end());

        node->left = buildKDTree(leftPoints, depth + 1);
        node->right = buildKDTree(rightPoints, depth + 1);

        return node;
    }

public:
    KDTree(int featureSize, int maxDepth, int leafNodeCapacity)
        : root(nullptr), featureSize(featureSize), maxDepth(maxDepth), leafNodeCapacity(leafNodeCapacity) {}

    void insert(const std::vector<T>& point) {
