#define MAX_ELEMENTS 10000000

typedef struct {
    int value;
} record;

int find(int *parent, int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void unionSet(int *parent, int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset)
        parent[xset] = yset;
}

int customHash(int key) {
    return abs(key % MAX_ELEMENTS);
}

void processInput() {
    int *offsets = (int *)malloc(MAX_ELEMENTS * sizeof(int));
    int *keys = (int *)malloc(MAX_ELEMENTS * sizeof(int));
    record *records = (record *)malloc(MAX_ELEMENTS * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize arrays
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        offsets[i] = i;
        keys[i] = rand() % 1000000; // Example input generation
        records[i].value = keys[i];
    }

    int *parent = (int *)calloc(MAX_ELEMENTS, sizeof(int));
    if (!parent) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    clock_t start = clock();
    for (int i = 0; i < MAX_ELEMENTS - 1; i++) {
        unionSet(parent, keys[i], keys[i + 1]);
    }
    clock_t end = clock();

    printf("Time taken to find disjoint pairs: %f seconds\n", ((double)(end - start)) / CLOCKS_PER_SEC);

    // Find and print the largest integer
    int maxKey = INT_MIN;
    for (int i = 0; i < MAX_ELEMENTS; i++) {
        if (keys[i] > maxKey)
            maxKey = keys[i];
    }
    printf("Largest key: %d\n", maxKey);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(parent);
}

int main() {
    processInput();
    return 0;
}
