typedef struct {
    int value;
} record;

void log_message(const char *message) {
    printf("%s\n", message);
}

int* allocate_and_initialize_int_array(int size, int min_value, int max_value) {
    int* array = (int*)malloc(size * sizeof(int));
    if (array == NULL) {
        log_message("Memory allocation failed for int array");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        array[i] = rand() % (max_value - min_value + 1) + min_value;
    }
    return array;
}

long* allocate_and_initialize_long_array(int size, long min_offset, long max_offset) {
    long* array = (long*)malloc(size * sizeof(long));
    if (array == NULL) {
        log_message("Memory allocation failed for long array");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        array[i] = rand() % (max_offset - min_offset + 1) + min_offset;
    }
    return array;
}

record* allocate_and_initialize_record_array(int size) {
    record* records = (record*)malloc(size * sizeof(record));
    if (records == NULL) {
        log_message("Memory allocation failed for record array");
        return NULL;
    }
    for (int i = 0; i < size; i++) {
        records[i].value = rand();
    }
    return records;
}

void free_all_memory(int* int_array, long* long_array, record* record_array) {
    if (int_array != NULL) free(int_array);
    if (long_array != NULL) free(long_array);
    if (record_array != NULL) free(record_array);
}

unsigned char* decrypt_ciphertext(const unsigned char* ciphertext, size_t ciphertext_len,
                                 const unsigned char* key, const unsigned char* iv) {
    unsigned char* plaintext = (unsigned char*)malloc(ciphertext_len + AES_BLOCK_SIZE);
    if (plaintext == NULL) {
        log_message("Memory allocation failed for plaintext");
        return NULL;
    }

    AES_KEY aes_key;
    if (AES_set_decrypt_key(key, 128, &aes_key) != 0) {
        log_message("Failed to set AES decryption key");
        free(plaintext);
        return NULL;
    }

    int decrypted_len = 0;
    if (AES_cbc_encrypt(ciphertext, plaintext, ciphertext_len, &aes_key, iv, AES_DECRYPT) != 0) {
        log_message("Decryption failed");
        free(plaintext);
        return NULL;
    }

    // Resize the plaintext buffer to the actual length
    unsigned char* resized_plaintext = (unsigned char*)realloc(plaintext, decrypted_len);
    if (resized_plaintext == NULL) {
        log_message("Memory reallocation failed for plaintext");
        free(plaintext);
        return NULL;
    }

    return resized_plaintext;
}

int main() {
    int size = 1000;
    int* int_array = allocate_and_initialize_int_array(size, 0, 100);
    long* long_array = allocate_and_initialize_long_array(size, 0L, 1000L);
    record* record_array = allocate_and_initialize_record_array(size);

    if (int_array != NULL && long_array != NULL && record_array != NULL) {
        log_message("Initialization successful");
        // Perform operations with the arrays
        free_all_memory(int_array, long_array, record_array);
        log_message("Memory freed successfully");
    }

    unsigned char key[AES_BLOCK_SIZE] = {0}; // Initialize with actual key
    unsigned char iv[AES_BLOCK_SIZE] = {0};  // Initialize with actual IV
    const unsigned char* ciphertext = (const unsigned char*)"..."; // Initialize with actual ciphertext
    size_t ciphertext_len = strlen((char*)ciphertext);

    unsigned char* decrypted_plaintext = decrypt_ciphertext(ciphertext, ciphertext_len, key, iv);
    if (decrypted_plaintext != NULL) {
        log_message("Decryption successful");
        free(decrypted_plaintext);
        log_message("Memory freed successfully for decrypted plaintext");
    }

    return 0;
}
