#define MAX_ELEMENTS 1000
#define SYSTEM_LIMIT (1 * 1024 * 1024) // 1 MB

typedef struct {
    int key;
} record;

record* allocate_and_initialize_records(int offset_size, int key_size) {
    if (offset_size + key_size > MAX_ELEMENTS) {
        return NULL; // Exceeds maximum threshold
    }

    size_t total_size = sizeof(record) * (offset_size + key_size);
    if (total_size > SYSTEM_LIMIT) {
        return NULL; // Exceeds system limit
    }

    record* records = (record*)malloc(total_size);
    if (!records) {
        return NULL; // Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < offset_size + key_size; i++) {
        records[i].key = rand() % (offset_size + key_size); // Random initialization within range
    }

    return records;
}
