    uf->records = (Record*)malloc(initialCapacity * sizeof(Record));
    uf->size = 0;
    uf->capacity = initialCapacity;
}

void resizeUnionFind(UnionFind* uf) {
    int newCapacity = uf->capacity * 2;
    uf->keys = (int*)realloc(uf->keys, newCapacity * sizeof(int));
    uf->records = (Record*)realloc(uf->records, newCapacity * sizeof(Record));
    uf->capacity = newCapacity;
}

void addEntry(UnionFind* uf, long offset, int key, Record record) {
    if (uf->size == uf->capacity) {
        resizeUnionFind(uf);
    }
    uf->keys[uf->size] = key;
    uf->records[uf->size] = record;
    uf->size++;
