#define MAX_RECORDS 1000
#define PREFIX_LENGTH 5
#define KEY_RANGE 100

typedef struct {
    int key;
    char value[256];
} Record;

Record* records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_prefix(char *prefix) {
    // Simulate fetching a prefix from an external data source
    snprintf(prefix, PREFIX_LENGTH, "PFX%03d", rand() % 1000);
}

void* allocate_records(void* arg) {
    int limit = *(int*)arg;
    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_mutex_lock(&mutex);
        if (record_count >= limit) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        Record* new_record = malloc(sizeof(Record));
        if (!new_record) {
            printf("Memory allocation failed\n");
            pthread_mutex_unlock(&mutex);
            continue;
        }
        generate_prefix(new_record->value);
        new_record->key = rand() % KEY_RANGE;
        records[record_count++] = new_record;
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

void free_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    record_count = 0;
}

int main() {
    int limit = 500;
    pthread_t thread;

    if (pthread_create(&thread, NULL, allocate_records, &limit) != 0) {
        printf("Thread creation failed\n");
        return 1;
    }

    pthread_join(thread, NULL);

    free_records();

    return 0;
}
