#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_ENTRIES 1000
#define DEFAULT_SEVERITY "INFO"
#define ID_LENGTH 16

typedef enum {
    ERROR,
    WARNING,
    INFO,
    DEBUG
} Severity;

typedef struct LogEntry {
    char id[ID_LENGTH];
    time_t timestamp;
    Severity severity;
    char message[256];
} LogEntry;

typedef struct LoggingSystem {
    LogEntry *entries;
    int count;
    int capacity;
    pthread_mutex_t lock;
} LoggingSystem;

void init_logging_system(LoggingSystem *sys, int initial_capacity) {
    sys->entries = (LogEntry *)malloc(initial_capacity * sizeof(LogEntry));
    if (!sys->entries) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    sys->count = 0;
    sys->capacity = initial_capacity;
    pthread_mutex_init(&sys->lock, NULL);
}

void destroy_logging_system(LoggingSystem *sys) {
    free(sys->entries);
    pthread_mutex_destroy(&sys->lock);
}

int add_log_entry(LoggingSystem *sys, const char *message, Severity severity) {
    pthread_mutex_lock(&sys->lock);

    if (sys->count >= sys->capacity) {
        int new_capacity = sys->capacity * 2;
        LogEntry *new_entries = (LogEntry *)realloc(sys->entries, new_capacity * sizeof(LogEntry));
        if (!new_entries) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&sys->lock);
            return -1;
        }
        sys->entries = new_entries;
        sys->capacity = new_capacity;
    }

    LogEntry *entry = &sys->entries[sys->count];
    generate_unique_id(entry->id); // Assume this function generates a unique ID
    entry->timestamp = time(NULL);
    entry->severity = severity;
    snprintf(entry->message, sizeof(entry->message), "%s", message);

    sys->count++;
    pthread_mutex_unlock(&sys->lock);
    return 0;
}

void generate_unique_id(char *id) {
    // Assume this function generates a unique ID
    for (int i = 0; i < ID_LENGTH - 1; i++) {
        id[i] = 'A' + rand() % 26;
    }
    id[ID_LENGTH - 1] = '\0';
}

// Example usage
int main() {
    LoggingSystem sys;
    init_logging_system(&sys, MAX_LOG_ENTRIES);

    add_log_entry(&sys, "This is an info message", INFO);
    add_log_entry(&sys, "This is a warning message", WARNING);

    destroy_logging_system(&sys);
    return 0;
}
```

