int initialize_data_structures(long **offsets, int **keys, Record **records, int num_records, int range_start, int range_end, int max_memory_size) {
    srand(time(NULL));

    *offsets = (long *)malloc(num_records * sizeof(long));
    if (*offsets == NULL) {
        log_message("Memory allocation failed for offsets");
        return -1;
    }

    *keys = (int *)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        log_message("Memory allocation failed for keys");
        free(*offsets);
        return -1;
    }

    *records = (Record *)malloc(num_records * sizeof(Record));
    if (*records == NULL) {
        log_message("Memory allocation failed for records");
        free(*offsets);
        free(*keys);
        return -1;
    }

    long total_memory_used = num_records * (sizeof(long) + sizeof(int) + sizeof(Record));
    if (total_memory_used > max_memory_size) {
        log_message("Exceeded maximum memory size limit");
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    for (int i = 0; i < num_records; i++) {
        (*offsets)[i] = rand() % (range_end - range_start + 1) + range_start;
        (*keys)[i] = rand() % (range_end - range_start + 1) + range_start;
        (*records)[i].value = rand() % (range_end - range_start + 1) + range_start;
        (*records)[i].next = NULL;
    }

    log_message("Data structures initialized successfully");
    return 0;
}

void cleanup_data_structures(long *offsets, int *keys, Record *records) {
    free(offsets);
    free(keys);
    Record *current = records;
    while (current != NULL) {
        Record *next = current->next;
        free(current);
        current = next;
    }
    log_message("Data structures cleaned up successfully");
}

int main() {
    long *offsets;
    int *keys;
    Record *records;

    int num_records = 1000;
    int range_start = 0;
    int range_end = 10000;
    int max_memory_size = 1024 * 1024; // 1MB

    if (initialize_data_structures(&offsets, &keys, &records, num_records, range_start, range_end, max_memory_size) == 0) {
        cleanup_data_structures(offsets, keys, records);
    }

    return 0;
}
