typedef struct {
    int* keys;
    record** records;
    long* offsets;
    int size;
    int capacity;
} data_struct;

data_struct* init_data_struct(int initial_capacity) {
    data_struct* ds = (data_struct*)malloc(sizeof(data_struct));
    if (!ds) return NULL;

    ds->keys = (int*)calloc(initial_capacity, sizeof(int));
    ds->records = (record**)calloc(initial_capacity, sizeof(record*));
    ds->offsets = (long*)calloc(initial_capacity, sizeof(long));
    ds->size = 0;
    ds->capacity = initial_capacity;

    if (!ds->keys || !ds->records || !ds->offsets) {
        free(ds);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < initial_capacity; ++i) {
        ds->keys[i] = rand() % 1000;
        ds->records[i] = (record*)malloc(sizeof(record));
        if (!ds->records[i]) {
            free(ds);
            return NULL;
        }
        ds->records[i]->value = rand() % 1000;
    }

    printf("Data structure initialized with capacity: %d\n", initial_capacity);
    return ds;
}

void free_data_struct(data_struct* ds) {
    if (!ds) return;

    for (int i = 0; i < ds->size; ++i) {
        free(ds->records[i]);
    }

    free(ds->keys);
    free(ds->records);
    free(ds->offsets);
    free(ds);

    printf("Data structure freed.\n");
}

void find_largest_key(data_struct* ds) {
    if (!ds || ds->size == 0) return;

    int largest = ds->keys[0];
    for (int i = 1; i < ds->size; ++i) {
        if (ds->keys[i] > largest) {
            largest = ds->keys[i];
        }
    }

    printf("Largest key: %d\n", largest);
}

void check_disjoint_pairs(data_struct* ds) {
    if (!ds || ds->size < 2) return;

    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < ds->size - 1; ++i) {
        for (int j = i + 1; j < ds->size; ++j) {
            start = clock();
            // Perform disjoint pair check using Union-Find
            end = clock();
            cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;
            printf("Disjoint pair (%d, %d) checked in %.3f ms\n", ds->keys[i], ds->keys[j], cpu_time_used * 1000);
        }
    }
}

int main() {
    int initial_capacity = 1000;
    data_struct* ds = init_data_struct(initial_capacity);

    if (ds) {
        find_largest_key(ds);
        check_disjoint_pairs(ds);
        free_data_struct(ds);
    }

    return 0;
}
