#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int key;
    float data;
} Record;

typedef struct {
    long offset;
    int key;
    float value;
    Record record;
} DataStruct;

typedef struct {
    DataStruct *data;
    size_t capacity;
    size_t size;
    sem_t mutex;
    sem_t available;
} DataPool;

DataPool* create_data_pool(size_t initial_capacity) {
    DataPool *pool = (DataPool*)malloc(sizeof(DataPool));
    if (!pool) return NULL;

    pool->data = (DataStruct*)calloc(initial_capacity, sizeof(DataStruct));
    if (!pool->data) {
        free(pool);
        return NULL;
    }

    pool->capacity = initial_capacity;
    pool->size = 0;
    sem_init(&pool->mutex, 0, 1);
    sem_init(&pool->available, 0, initial_capacity);

    return pool;
}

void destroy_data_pool(DataPool *pool) {
    if (pool) {
        free(pool->data);
        sem_destroy(&pool->mutex);
        sem_destroy(&pool->available);
        free(pool);
    }
}

int add_to_pool(DataPool *pool, long offset, int key, float value, Record record) {
    sem_wait(&pool->available);
    sem_wait(&pool->mutex);

    if (pool->size >= pool->capacity) {
        sem_post(&pool->mutex);
        sem_post(&pool->available);
        return -1; // Pool is full
    }

    pool->data[pool->size].offset = offset;
    pool->data[pool->size].key = key;
    pool->data[pool->size].value = value;
    pool->data[pool->size].record = record;
    pool->size++;

    sem_post(&pool->mutex);
    sem_post(&pool->available);

    return 0;
}

void* data_stream_processor(void *arg) {
    DataPool *pool = (DataPool*)arg;

    while (1) {
        // Simulate reading from external source
        long offset = read_from_external_source();
        int key = get_next_key();
        float value = get_next_value();
        Record record = {get_record_int(), get_record_float()};

        if (add_to_pool(pool, offset, key, value, record) != 0) {
            // Handle error
            break;
        }

        // Process data from pool as needed
    }

    return NULL;
}

int main() {
    DataPool *pool = create_data_pool(1024);
    if (!pool) {
        fprintf(stderr, "Failed to create data pool\n");
        return 1;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, data_stream_processor, pool) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        destroy_data_pool(pool);
        return 1;
    }

    // Wait for the thread to finish
    pthread_join(thread_id, NULL);

    destroy_data_pool(pool);
    return 0;
}
```

This code provides a basic structure for managing multiple arrays and structures containing 'long' offset values, 'int' keys, 'float' data values, and 'record' structures within a constrained environment. It includes functions to create and destroy the data pool, add data to the pool, and process data from an external source in a separate thread. The code uses semaphores for synchronization and memory management strategies like dynamic allocation and deallocation.']

