typedef struct {
    int intValue;
    long offsetValue;
} record;

char* processAndHashData(int batchSize, const char* sourceData, int randomSeed, int debugMode) {
    // Initialize variables
    record* records = (record*)malloc(batchSize * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX sha256;

    // Seed the random number generator
    srand(randomSeed);

    // Generate records and compute hash
    for (int i = 0; i < batchSize; i++) {
        records[i].intValue = rand();
        records[i].offsetValue = i * sizeof(record);
        SHA256_Update(&sha256, &records[i], sizeof(record));
    }

    // Finalize the hash computation
    SHA256_Final(hash, &sha256);

    // Convert hash to hexadecimal string
    char* hexHash = (char*)malloc(SHA256_DIGEST_LENGTH * 2 + 1);
    if (!hexHash) {
        fprintf(stderr, "Memory allocation failed\n");
        free(records);
        return NULL;
    }

    for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
        sprintf(hexHash + i * 2, "%02x", hash[i]);
    }
    hexHash[SHA256_DIGEST_LENGTH * 2] = '\0';

    // Free allocated memory
    free(records);

    return hexHash;
}
