#include <time.h>

typedef struct Transaction {
    int id;
    double amount;
    struct Transaction* next;
} Transaction;

Transaction* create_transaction(int id, double amount) {
    Transaction* new_transaction = (Transaction*)malloc(sizeof(Transaction));
    if (new_transaction == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_transaction->id = id;
    new_transaction->amount = amount;
    new_transaction->next = NULL;
    return new_transaction;
}

void add_transaction(Transaction** head, int id, double amount) {
    Transaction* new_transaction = create_transaction(id, amount);
    if (*head == NULL) {
        *head = new_transaction;
    } else {
        Transaction* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_transaction;
    }
}

void free_transactions(Transaction** head) {
    Transaction* current = *head;
    while (current != NULL) {
        Transaction* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    srand(time(NULL));
    int num_transactions = 1000;
    Transaction* transactions = NULL;

    for (int i = 0; i < num_transactions; i++) {
        double amount = ((double)rand() / RAND_MAX) * 1000.0 - 500.0; // Random amount between -500 and 500
        add_transaction(&transactions, i + 1, amount);
    }

    free_transactions(&transactions);

    return 0;
}
