    long* offsets = malloc(sizeof(long) * 100);

    // Initialize records with random values
    for (int i = 0; i < 100; i++) {
        records[i].value = rand() % 1000;
    }

    // Load the module using require function
    void* module = require(moduleName);
    if (!module) {
        fprintf(stderr, "Failed to load module: %s\n", moduleName);
        return NULL;
    }

    // Execute tests in parallel
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, f, records);
    }

    // Wait for all threads to complete
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
