#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    int ref_count;
} Record;

typedef struct node {
    int key;
    Record *record;
    struct node *next;
} Node;

typedef struct hash_table {
    Node **buckets;
    size_t size;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;
    ht->size = size;
    ht->buckets = (Node**)calloc(size, sizeof(Node*));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }
    return ht;
}

void destroy_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Node *node = ht->buckets[i];
        while (node) {
            Node *next = node->next;
            free(node);
            node = next;
        }
    }
    free(ht->buckets);
    free(ht);
}

Record* create_record(int value) {
    Record *rec = (Record*)malloc(sizeof(Record));
    if (!rec) return NULL;
    rec->value = value;
    rec->ref_count = 1;
    return rec;
}

void destroy_record(Record *rec) {
    free(rec);
}

Node* create_node(int key, Record *record) {
    Node *node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->key = key;
    node->record = record;
    node->next = NULL;
    return node;
}

void destroy_node(Node *node) {
    free(node);
}

int hash_function(int key, size_t size) {
    return abs(key) % size;
}

void insert_record(HashTable *ht, int key, Record *record) {
    size_t index = hash_function(key, ht->size);
    Node *new_node = create_node(key, record);
    if (!new_node) return;

    new_node->next = ht->buckets[index];
    ht->buckets[index] = new_node;
}

Record* get_record(HashTable *ht, int key) {
    size_t index = hash_function(key, ht->size);
    Node *node = ht->buckets[index];
    while (node) {
        if (node->key == key) {
            node->record->ref_count++;
            return node->record;
        }
        node = node->next;
    }
    return NULL;
}

void release_record(HashTable *ht, int key) {
    size_t index = hash_function(key, ht->size);
    Node *node = ht->buckets[index];
    while (node) {
        if (node->key == key) {
            node->record->ref_count--;
            if (node->record->ref_count == 0) {
                destroy_record(node->record);
                Node *prev = NULL;
                while (ht->buckets[index] != node) {
                    prev = ht->buckets[index];
                    ht->buckets[index] = ht->buckets[index]->next;
                }
                if (prev) {
                    prev->next = node->next;
                } else {
                    ht->buckets[index] = node->next;
                }
                destroy_node(node);
            }
            return;
        }
        node = node->next;
    }
}

int main() {
    srand(time(NULL));
    HashTable *ht = create_hash_table(100);
    if (!ht) {
        fprintf(stderr, "Failed to create hash table\n");
        return 1;
    }

    for (int i = 0; i < 50; ++i) {
        Record *rec = create_record(rand() % 100);
        if (!rec) {
            fprintf(stderr, "Failed to create record\n");
            destroy_hash_table(ht);
            return 1;
        }
        insert_record(ht, i, rec);
    }

    for (int i = 0; i < 50; ++i) {
        Record *rec = get_record(ht, i);
        if (!rec) {
            fprintf(stderr, "Failed to get record\n");
            destroy_hash_table(ht);
            return 1;
        }
        printf("Record %d: Value=%d, RefCount=%d\n", i, rec->value, rec->ref_count);
    }

    for (int i = 0; i < 50; ++i) {
        release_record(ht, i);
    }

    destroy_hash_table(ht);
    return 0;
}
