typedef struct Task {
    char priority;
    int due_date;
    double duration;
    struct Task* next;
} Task;

typedef struct TaskScheduler {
    Task* head;
    pthread_mutex_t lock;
    // Add other necessary fields for task scheduling
} TaskScheduler;

void init_task_scheduler(TaskScheduler* scheduler) {
    scheduler->head = NULL;
    pthread_mutex_init(&scheduler->lock, NULL);
}

void insert_task(TaskScheduler* scheduler, char priority, int due_date, double duration) {
    pthread_mutex_lock(&scheduler->lock);
    Task* new_task = (Task*)malloc(sizeof(Task));
    new_task->priority = priority;
    new_task->due_date = due_date;
    new_task->duration = duration;
    new_task->next = NULL;

    if (scheduler->head == NULL || scheduler->head->due_date > due_date) {
        new_task->next = scheduler->head;
        scheduler->head = new_task;
    } else {
        Task* current = scheduler->head;
        while (current->next != NULL && current->next->due_date <= due_date) {
            current = current->next;
        }
        new_task->next = current->next;
        current->next = new_task;
    }
    pthread_mutex_unlock(&scheduler->lock);
}

void* task_scheduler_thread(void* arg) {
    TaskScheduler* scheduler = (TaskScheduler*)arg;
    // Implement the main scheduling logic here
    return NULL;
}

int main() {
    TaskScheduler scheduler;
    init_task_scheduler(&scheduler);

    insert_task(&scheduler, 'A', 10, 2.5);
    insert_task(&scheduler, 'B', 5, 3.0);
    insert_task(&scheduler, 'C', 15, 1.5);

    pthread_t thread;
    pthread_create(&thread, NULL, task_scheduler_thread, &scheduler);
    pthread_join(thread, NULL);

    return 0;
}
```

