public class ServiceManager {
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private boolean isRunning = false;
    private int currentLoad = 0;
    private int retryCount = 0;
    private static final int MAX_RETRIES = 5;
    private static final long RETRY_DELAY = 2000; // milliseconds

    public void startService() {
        if (!isRunning) {
            isRunning = true;
            scheduler.scheduleAtFixedRate(this::runService, 0, calculateInterval(), TimeUnit.MILLISECONDS);
        }
    }

    public void stopService() {
        if (isRunning) {
            isRunning = false;
            scheduler.shutdown();
            sendMessageToMessagingSystem("Service stopped", currentLoad);
        }
    }

    private void runService() {
        try {
            // Simulate service operation
            currentLoad++;
            System.out.println("Service running, load: " + currentLoad);

            if (currentLoad > 10) {
                throw new RuntimeException("High load detected");
            }
        } catch (Exception e) {
            handleFailure(e);
        }
    }

    private void handleFailure(Exception e) {
        retryCount++;
        if (retryCount <= MAX_RETRIES) {
            System.out.println("Service failed, retrying in " + RETRY_DELAY + "ms: " + e.getMessage());
            scheduler.schedule(this::runService, RETRY_DELAY, TimeUnit.MILLISECONDS);
        } else {
            System.err.println("Max retries reached, giving up: " + e.getMessage());
        }
    }

    private long calculateInterval() {
        // Simple dynamic scheduling algorithm
        if (currentLoad > 5) {
            return 1000; // Reduce interval for high load
        } else {
            return 2000; // Increase interval for low load
        }
    }

    private void sendMessageToMessagingSystem(String status, int metrics) {
        try {
            // Simulate message sending
            System.out.println("Message sent to messaging system: " + status + ", Metrics: " + metrics);
        } catch (Exception e) {
            handleFallback(e);
        }
    }

    private void handleFallback(Exception e) {
        System.err.println("Failed to send message, falling back: " + e.getMessage());
        // Implement fallback mechanism here
    }

    public static void main(String[] args) {
        ServiceManager serviceManager = new ServiceManager();
        serviceManager.startService();

        // Simulate stopping the service after 10 seconds
        try {
            Thread.sleep(10000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        serviceManager.stopService();
    }
}
