#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int value;
} Record;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    FILE* log_file;
} DynamicDataStructure;

DynamicDataStructure* create_dynamic_data_structure() {
    DynamicDataStructure* dds = (DynamicDataStructure*)malloc(sizeof(DynamicDataStructure));
    if (!dds) {
        perror("Failed to allocate memory for DynamicDataStructure");
        return NULL;
    }
    dds->offsets = (long*)calloc(INITIAL_CAPACITY, sizeof(long));
    dds->keys = (int*)calloc(INITIAL_CAPACITY, sizeof(int));
    dds->records = (Record**)calloc(INITIAL_CAPACITY, sizeof(Record*));
    if (!dds->offsets || !dds->keys || !dds->records) {
        perror("Failed to allocate memory for arrays");
        free(dds);
        return NULL;
    }
    dds->capacity = INITIAL_CAPACITY;
    dds->size = 0;
    pthread_mutex_init(&dds->lock, NULL);
    dds->log_file = fopen("memory_usage.log", "w");
    if (!dds->log_file) {
        perror("Failed to open log file");
        free(dds->offsets);
        free(dds->keys);
        free(dds->records);
        pthread_mutex_destroy(&dds->lock);
        free(dds);
        return NULL;
    }
    fprintf(dds->log_file, "Initial capacity: %zu\n", INITIAL_CAPACITY);
    return dds;
}

void destroy_dynamic_data_structure(DynamicDataStructure* dds) {
    for (size_t i = 0; i < dds->size; ++i) {
        free(dds->records[i]);
    }
    free(dds->offsets);
    free(dds->keys);
    free(dds->records);
    pthread_mutex_destroy(&dds->lock);
    fclose(dds->log_file);
    free(dds);
}

void* insert_record(void* arg) {
    DynamicDataStructure* dds = (DynamicDataStructure*)arg;
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        perror("Failed to allocate memory for new record");
        return NULL;
    }
    pthread_mutex_lock(&dds->lock);
    if (dds->size == dds->capacity) {
        size_t new_capacity = dds->capacity * 2;
        long* new_offsets = (long*)realloc(dds->offsets, new_capacity * sizeof(long));
        int* new_keys = (int*)realloc(dds->keys, new_capacity * sizeof(int));
        Record** new_records = (Record**)realloc(dds->records, new_capacity * sizeof(Record*));
        if (!new_offsets || !new_keys || !new_records) {
            perror("Failed to reallocate memory for arrays");
            free(new_record);
            pthread_mutex_unlock(&dds->lock);
            return NULL;
        }
        dds->offsets = new_offsets;
        dds->keys = new_keys;
        dds->records = new_records;
        dds->capacity = new_capacity;
    }
    dds->offsets[dds->size] = 0; // Placeholder for actual offset
    dds->keys[dds->size] = rand() % 1000; // Placeholder for actual key
    dds->records[dds->size++] = new_record;
    fprintf(dds->log_file, "Inserted record at index: %zu\n", dds->size - 1);
    pthread_mutex_unlock(&dds->lock);
    return NULL;
}

// Additional functions for deletion, retrieval, serialization, and error handling can be implemented similarly.
