#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define TABLE_SIZE 1024

typedef struct Record {
    int key;
    float value;
    long offset;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record *buckets[TABLE_SIZE];
} HashTable;

HashTable* createHashTable() {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;
    for (int i = 0; i < TABLE_SIZE; i++) table->buckets[i] = NULL;
    return table;
}

unsigned int hashFunction(int key) {
    return abs(key % TABLE_SIZE);
}

Record* createRecord(int key, float value, long offset) {
    Record *record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->value = value;
    record->offset = offset;
    record->next = NULL;
    return record;
}

int insertRecord(HashTable *table, int key, float value, long offset) {
    unsigned int index = hashFunction(key);
    Record *newRecord = createRecord(key, value, offset);
    if (!newRecord) return -1;

    newRecord->next = table->buckets[index];
    table->buckets[index] = newRecord;
    return 0;
}

void freeHashTable(HashTable *table) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Record *current = table->buckets[i];
        while (current) {
            Record *temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(table);
}

// Example usage
int main() {
    HashTable *table = createHashTable();
    if (!table) {
        fprintf(stderr, "Failed to allocate memory for hash table.\n");
        return 1;
    }

    // Insert records
    insertRecord(table, 10, 3.14f, 12345);
    insertRecord(table, 20, 2.71f, 67890);

    // Free the hash table when done
    freeHashTable(table);

    return 0;
}
