#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

#define MAX_RECORDS 1024

typedef struct {
    long offset;
    int key;
    double measurement;
    char status;
} Record;

typedef struct {
    Record records[MAX_RECORDS];
    int count;
    pthread_mutex_t lock;
} DataStorage;

DataStorage storage;

void init_storage() {
    memset(&storage, 0, sizeof(storage));
    pthread_mutex_init(&storage.lock, NULL);
}

void insert_record(Record record) {
    pthread_mutex_lock(&storage.lock);
    if (storage.count < MAX_RECORDS) {
        storage.records[storage.count++] = record;
    }
    pthread_mutex_unlock(&storage.lock);
}

Record* get_record(int key) {
    pthread_mutex_lock(&storage.lock);
    for (int i = 0; i < storage.count; i++) {
        if (storage.records[i].key == key) {
            pthread_mutex_unlock(&storage.lock);
            return &storage.records[i];
        }
    }
    pthread_mutex_unlock(&storage.lock);
    return NULL;
}

void* garbage_collection(void* arg) {
    while (1) {
        // Perform garbage collection logic here
        sleep(60); // Simulate periodic execution
    }
    return NULL;
}

int main() {
    init_storage();
    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collection, NULL);

    Record new_record = {12345, 1, 3.14, 'A'};
    insert_record(new_record);

    Record* retrieved_record = get_record(1);
    if (retrieved_record != NULL) {
        printf("Retrieved record: offset=%ld, key=%d, measurement=%.2f, status=%c\n",
               retrieved_record->offset, retrieved_record->key,
               retrieved_record->measurement, retrieved_record->status);
    }

    pthread_join(gc_thread, NULL);
    return 0;
}
