void* safe_malloc(size_t size, const char* file, int line) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed at %s:%d\n", file, line);
        exit(EXIT_FAILURE);
    }
    log_memory_usage(size);
    return ptr;
}

Record* create_records(int count, long offset_range, int key_range, double measurement_range, char status_range) {
    Record* records = (Record*)safe_malloc(count * sizeof(Record), __FILE__, __LINE__);

    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].offset = rand() % offset_range;
        records[i].key = rand() % key_range;
        records[i].measurement = ((double)rand() / RAND_MAX) * measurement_range;
        records[i].status = status_range[rand() % (status_range - 'A' + 1)];
    }

    return records;
}

void free_records(Record* records, int count) {
    log_memory_usage(-count * sizeof(Record));
    free(records);
}

int main() {
    int count = 1000;
    Record* records = create_records(count, 1000000L, 1000, 100.0, 'A' + 25);

    // Use the records...

    free_records(records, count);
    return 0;
}
