#include <stdlib.h>
#include <stdio.h>
#include <time.h>

#define MAX_RECORD_SIZE 1024

typedef struct {
    int value;
} record;

int allocate_memory(long *offsets, int keys[], record **records, long num_offsets, int num_keys, int num_records, size_t memory_limit) {
    size_t total_size = sizeof(long) * num_offsets + sizeof(int) * num_keys + sizeof(record) * num_records * MAX_RECORD_SIZE;

    if (total_size > memory_limit) {
        fprintf(stderr, "Error: Memory limit exceeded.\n");
        return -1; // Error code for memory limit exceeded
    }

    offsets = malloc(sizeof(long) * num_offsets);
    keys = malloc(sizeof(int) * num_keys);
    *records = malloc(sizeof(record) * num_records * MAX_RECORD_SIZE);

    if (!offsets || !keys || !*records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(offsets);
        free(keys);
        free(*records);
        return -2; // Error code for memory allocation failure
    }

    srand(time(NULL));
    for (int i = 0; i < num_records * MAX_RECORD_SIZE; i++) {
        (*records)[i].value = rand() % 1001;
    }

    return 0; // Success
}

// Example usage:
int main() {
    long offsets[5];
    int keys[3] = {1, 2, 3};
    record *records;
    size_t memory_limit = 1024 * 1024; // 1 MB

    if (allocate_memory(offsets, keys, &records, 5, 3, 100, memory_limit) == 0) {
        printf("Memory allocation successful.\n");
        // Use the allocated arrays here
        free(records);
    }

    return 0;
}
```

