void manage_records(int size, bool check_duplicates, void (*filter_func)(record)) {
    if (size <= 0) {
        fprintf(stderr, "Error: Size must be greater than zero.\n");
        return;
    }

    long *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));
    record *records = malloc(size * sizeof(record));
    bool *status_flags = malloc(size * sizeof(bool));

    if (!offsets || !keys || !records || !status_flags) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % MAX_MEMORY_LIMIT;
        keys[i] = rand() % 1000; // Example range for keys
        records[i].value = rand() % 1000; // Example range for record values

        if (check_duplicates) {
            bool duplicate = false;
            for (int j = 0; j < i; j++) {
                if (records[j].value == records[i].value) {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate) {
                fprintf(stderr, "Error: Duplicate value detected.\n");
                free(offsets);
                free(keys);
                free(records);
                free(status_flags);
                return;
            }
        }

        status_flags[i] = validate_record(records[i]);
    }

    // Apply filtering
    int filtered_size = 0;
    for (int i = 0; i < size; i++) {
        if (filter_func(records[i])) {
            filtered_size++;
        }
    }

    long *filtered_offsets = malloc(filtered_size * sizeof(long));
    int *filtered_keys = malloc(filtered_size * sizeof(int));
    record *filtered_records = malloc(filtered_size * sizeof(record));
    bool *filtered_status_flags = malloc(filtered_size * sizeof(bool));

    if (!filtered_offsets || !filtered_keys || !filtered_records || !filtered_status_flags) {
        fprintf(stderr, "Error: Memory allocation failed for filtered records.\n");
        free(offsets);
        free(keys);
        free(records);
        free(status_flags);
        return;
    }

    int index = 0;
    for (int i = 0; i < size; i++) {
        if (filter_func(records[i])) {
            filtered_offsets[index] = offsets[i];
            filtered_keys[index] = keys[i];
            filtered_records[index] = records[i];
            filtered_status_flags[index] = status_flags[i];
            index++;
        }
    }

    // Free original arrays
    free(offsets);
    free(keys);
    free(records);
    free(status_flags);

    // Use the filtered arrays as needed

    // Free filtered arrays when done
    free(filtered_offsets);
    free(filtered_keys);
    free(filtered_records);
    free(filtered_status_flags);
}

