#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct RecordCollection {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection *collection) {
    if (collection) {
        pthread_mutex_lock(&collection->lock);
        free(collection->records);
        pthread_mutex_unlock(&collection->lock);
        pthread_mutex_destroy(&collection->lock);
        free(collection);
    }
}

int add_record(RecordCollection *collection, long offset, int key_range_start, int key_range_end) {
    if (!collection || collection->size >= collection->capacity) return -1;

    pthread_mutex_lock(&collection->lock);

    Record *record = &collection->records[collection->size];
    record->offset = offset;
    record->key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
    record->timestamp = time(NULL);

    collection->size++;
    pthread_mutex_unlock(&collection->lock);

    return 0;
}

Record* get_record_by_offset(RecordCollection *collection, long offset) {
    if (!collection || offset < 0) return NULL;

    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].offset == offset) {
            Record *record = &collection->records[i];
            pthread_mutex_unlock(&collection->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&collection->lock);

    return NULL;
}

int resize_record_collection(RecordCollection *collection, size_t new_capacity) {
    if (!collection || new_capacity <= collection->capacity) return -1;

    Record *new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
    if (!new_records) return -1;

    collection->records = new_records;
    collection->capacity = new_capacity;

    return 0;
}
