double random_double(double min, double max) {
    return min + (max - min) * ((double)rand() / RAND_MAX);
}

void initialize_arrays(int num_doubles, int num_shorts, int num_points, int num_geometries, double range_min, double range_max) {
    srand(time(NULL));

    double* doubles = (double*)malloc(num_doubles * sizeof(double));
    short* shorts = (short*)malloc(num_shorts * sizeof(short));
    point* points = (point*)malloc(num_points * sizeof(point));
    geometry* geometries = (geometry*)malloc(num_geometries * sizeof(geometry));

    if (!doubles || !shorts || !points || !geometries) {
        // Handle memory allocation failure
        return;
    }

    for (int i = 0; i < num_doubles; ++i) {
        doubles[i] = random_double(range_min, range_max);
    }

    for (int i = 0; i < num_shorts; ++i) {
        shorts[i] = (short)(random_double(range_min, range_max));
    }

    int grid_size = (int)sqrt(num_points);
    for (int i = 0; i < num_points; ++i) {
        points[i].x = (float)((i % grid_size) * (range_max - range_min) / grid_size + range_min);
        points[i].y = (float)((i / grid_size) * (range_max - range_min) / grid_size + range_min);
    }

    for (int i = 0; i < num_geometries; ++i) {
        geometries[i].value = random_double(range_min, range_max);
        geometries[i].coord = &points[i % num_points];
    }

    // Log initialization process
    printf("Arrays initialized successfully.\n");

    // Free allocated memory
    free(doubles);
    free(shorts);
    free(points);
    free(geometries);

    // Log cleanup process
    printf("Memory freed successfully.\n");
}
