#include <iostream>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <string>
#include <chrono>
#include <memory>
#include <vector>

class PriorityMessageQueue {
public:
    struct Message {
        std::string payload;
        int priority;
        std::chrono::system_clock::time_point timestamp;

        Message(std::string p, int pri) : payload(p), priority(pri), timestamp(std::chrono::system_clock::now()) {}
    };

private:
    using Queue = std::priority_queue<Message, std::vector<Message>, std::greater<Message>>;
    Queue queue;
    mutable std::mutex mutex;
    std::condition_variable cond_var;

public:
    PriorityMessageQueue() {
        std::cout << "PriorityMessageQueue initialized." << std::endl;
    }

    ~PriorityMessageQueue() {
        std::unique_lock<std::mutex> lock(mutex);
        queue = Queue(); // Clear the queue
        lock.unlock();
        std::cout << "PriorityMessageQueue cleaned up." << std::endl;
    }

    void push(const Message& msg) {
        std::lock_guard<std::mutex> lock(mutex);
        queue.push(msg);
        cond_var.notify_one();
    }

    bool try_pop(Message& msg, std::chrono::milliseconds timeout = std::chrono::milliseconds(0)) {
        std::unique_lock<std::mutex> lock(mutex);
        if (timeout.count() == 0) {
            cond_var.wait(lock, [this] { return !queue.empty(); });
        } else {
            if (!cond_var.wait_for(lock, timeout, [this] { return !queue.empty(); })) {
                return false;
            }
        }
        msg = queue.top();
        queue.pop();
        return true;
    }

    size_t size() const {
        std::lock_guard<std::mutex> lock(mutex);
        return queue.size();
    }
};

int main() {
    PriorityMessageQueue pq;

    // Example usage
    pq.push({"Hello", 1});
    pq.push({"World", 2});

    Message msg;
    if (pq.try_pop(msg)) {
        std::cout << "Popped message: " << msg.payload << ", Priority: " << msg.priority << std::endl;
    }

    return 0;
}
```

This code provides a basic implementation of a priority message queue in C++. It uses a `std::priority_queue` to store messages based on their priority, with the highest-priority message at the front. The class is thread-safe and supports concurrent access using a mutex and condition variable. Messages are pushed onto the queue, and the next highest-priority message can be popped off. The example usage in the `main` function demonstrates how to use the class.']

