#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NODES 1024

typedef struct {
    int id;
    void* data_records;
    int key_offsets[10];
    int access_frequency;
} IndexNode;

IndexNode index_nodes[MAX_NODES];
int node_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned int consistent_hash(const char* key, unsigned int nodes) {
    unsigned int hash = 2166136261u;
    for (const char* p = key; *p != '\0'; ++p) {
        hash ^= (unsigned char)*p;
        hash *= 16777619u;
    }
    return hash % nodes;
}

int initialize_index_node(const char* key, void* data_records) {
    pthread_mutex_lock(&mutex);
    if (node_count >= MAX_NODES) {
        pthread_mutex_unlock(&mutex);
        return -1; // Maximum number of nodes reached
    }

    unsigned int node_id = consistent_hash(key, MAX_NODES);
    while (index_nodes[node_id].id != 0) {
        node_id = (node_id + 1) % MAX_NODES;
    }

    index_nodes[node_id].id = node_id;
    index_nodes[node_id].data_records = data_records;
    memset(index_nodes[node_id].key_offsets, 0, sizeof(index_nodes[node_id].key_offsets));
    index_nodes[node_id].access_frequency = 0;

    pthread_mutex_unlock(&mutex);
    return node_id;
}

void update_access_frequency(int node_id) {
    pthread_mutex_lock(&mutex);
    if (node_id >= 0 && node_id < MAX_NODES && index_nodes[node_id].id != 0) {
        index_nodes[node_id].access_frequency++;
    }
    pthread_mutex_unlock(&mutex);
}

void cleanup_index_node(int node_id) {
    pthread_mutex_lock(&mutex);
    if (node_id >= 0 && node_id < MAX_NODES && index_nodes[node_id].id == node_id) {
        memset(&index_nodes[node_id], 0, sizeof(IndexNode));
    }
    pthread_mutex_unlock(&mutex);
}

void log_activity(const char* message) {
    printf("%s\n", message);
}
