    if (!arrays) return NULL;

    arrays->offsets = calloc(initial_size, sizeof(long));
    arrays->keys = calloc(initial_size, sizeof(int));
    arrays->records = calloc(initial_size, sizeof(record));
    arrays->size = initial_size;
