    if (!arrays->offsets || !arrays->keys || !arrays->records) {
        free(arrays);
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < initial_size; ++i) {
        arrays->offsets[i] = 0;
        arrays->keys[i] = 0;
        arrays->records[i].offset = 0;
        arrays->records[i].key = 0;
        arrays->records[i].value = 0.0;
    }

    return arrays;
}

void destroy_managed_arrays(managed_arrays* arrays) {
