typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    char** labels;
    size_t capacity;
    size_t count;
} DynamicMemoryManager;

DynamicMemoryManager* init_memory_manager(size_t initial_capacity) {
    DynamicMemoryManager* manager = (DynamicMemoryManager*)malloc(sizeof(DynamicMemoryManager));
    if (!manager) return NULL;

    manager->offsets = (long*)calloc(initial_capacity, sizeof(long));
    manager->keys = (int*)calloc(initial_capacity, sizeof(int));
    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    manager->labels = (char**)calloc(initial_capacity, sizeof(char*));
    manager->capacity = initial_capacity;
    manager->count = 0;

    if (!manager->offsets || !manager->keys || !manager->records || !manager->labels) {
        free(manager->offsets);
        free(manager->keys);
        free(manager->records);
        free(manager->labels);
        free(manager);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < initial_capacity; ++i) {
        manager->labels[i] = strdup("default_label");
        if (!manager->labels[i]) {
            // Handle memory allocation failure
            cleanup_memory_manager(manager);
            return NULL;
        }
    }

    return manager;
}

void cleanup_memory_manager(DynamicMemoryManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->labels[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager->labels);
    free(manager);
}

void add_record(DynamicMemoryManager* manager, long offset, int key, double value, const char* label) {
    if (manager->count >= manager->capacity) {
        // Handle capacity exceeded
        return;
    }

    while (1) {
        int unique_key = rand() % 10000; // Example range for uniqueness check
        int is_unique = 1;
        for (size_t i = 0; i < manager->count; ++i) {
            if (manager->records[i].key == unique_key) {
                is_unique = 0;
                break;
            }
        }
        if (is_unique) {
            key = unique_key;
            break;
        }
    }

    manager->offsets[manager->count] = offset;
    manager->keys[manager->count] = key;
    manager->records[manager->count].offset = offset;
    manager->records[manager->count].key = key;
    manager->records[manager->count].value = value;
    manager->labels[manager->count] = strdup(label);
    if (!manager->labels[manager->count]) {
        // Handle memory allocation failure
        return;
    }

    ++manager->count;
}

