#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    char* identifier;
    double value;
} Record;

void log_message(const char* message) {
    // Implement logging logic here
}

Record* initialize_records(int count, const char* identifiers[], double values[]) {
    if (count <= 0 || identifiers == NULL || values == NULL) {
        log_message("Invalid input parameters");
        return NULL;
    }

    Record* records = (Record*)malloc(count * sizeof(Record));
    if (records == NULL) {
        log_message("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        records[i].id = i + 1;
        records[i].identifier = strdup(identifiers[i]);
        records[i].value = values[i];
    }

    log_message("Records initialized successfully");
    return records;
}

void free_records(Record* records, int count) {
    if (records == NULL || count <= 0) {
        log_message("Invalid input parameters");
        return;
    }

    for (int i = 0; i < count; i++) {
        free(records[i].identifier);
    }

    free(records);
    log_message("Records freed successfully");
}

void add_record(Record** records, int* count, const char* identifier, double value) {
    if (records == NULL || *count <= 0 || identifier == NULL) {
        log_message("Invalid input parameters");
        return;
    }

    Record* new_records = (Record*)realloc(*records, (*count + 1) * sizeof(Record));
    if (new_records == NULL) {
        log_message("Memory reallocation failed");
        return;
    }

    *records = new_records;
    (*records)[*count].id = *count + 1;
    (*records)[*count].identifier = strdup(identifier);
    (*records)[*count].value = value;
    (*count)++;
    log_message("Record added successfully");
}

void remove_record(Record** records, int* count, int index) {
    if (records == NULL || *count <= 0 || index < 0 || index >= *count) {
        log_message("Invalid input parameters");
        return;
    }

    free((*records)[index].identifier);
    for (int i = index; i < *count - 1; i++) {
        (*records)[i] = (*records)[i + 1];
    }
    (*count)--;
    log_message("Record removed successfully");
}

void print_records(Record* records, int count) {
    if (records == NULL || count <= 0) {
        log_message("Invalid input parameters");
        return;
    }

    for (int i = 0; i < count; i++) {
        printf("ID: %d, Identifier: %s, Value: %.2f\n", records[i].id, records[i].identifier, records[i].value);
    }
}

int main() {
    const char* identifiers[] = {"A", "B", "C"};
    double values[] = {1.0, 2.0, 3.0};
    int count = sizeof(identifiers) / sizeof(identifiers[0]);

    Record* records = initialize_records(count, identifiers, values);
    if (records != NULL) {
        print_records(records, count);

        add_record(&records, &count, "D", 4.0);
        print_records(records, count);

        remove_record(&records, &count, 1);
        print_records(records, count);

        free_records(records, count);
    }

    return 0;
}
