#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
    double timestamp;
} Record;

typedef struct RecordCollection {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection* create_record_collection(size_t initial_capacity) {
    RecordCollection *collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection *collection) {
    if (collection) {
        pthread_mutex_destroy(&collection->mutex);
        free(collection->records);
        free(collection);
    }
}

int add_record(RecordCollection *collection, long offset, int key_range_start, int key_range_end) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record *new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->mutex);
            return -1; // Memory allocation failed
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    Record *record = &collection->records[collection->size];
    record->offset = offset;
    record->key = key_range_start + rand() % (key_range_end - key_range_start + 1);
    record->timestamp = time(NULL);

    collection->size++;
    pthread_mutex_unlock(&collection->mutex);

    return 0; // Success
}

Record* get_record_by_offset(RecordCollection *collection, long offset) {
    pthread_mutex_lock(&collection->mutex);

    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].offset == offset) {
            Record *record = &collection->records[i];
            pthread_mutex_unlock(&collection->mutex);
            return record;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    return NULL; // Record not found
}

int validate_records(RecordCollection *collection) {
    for (size_t i = 0; i < collection->size - 1; i++) {
        if (collection->records[i].timestamp >= collection->records[i + 1].timestamp) {
            return -1; // Timestamps are not monotonically increasing
        }
    }

    return 0; // Validation successful
}
