    printf("Enter the number of resources: ");
    scanf("%d", &count);

    float* resourceValues = (float*)malloc(count * sizeof(float));
    double* timestamps = (double*)malloc(count * sizeof(double));
    resourceType* types = (resourceType*)malloc(count * sizeof(resourceType));
    metadata* metadatas = (metadata*)malloc(count * sizeof(metadata));

