        printf("Enter metadata flag for resource %d: ", i + 1);
        scanf("%d", &metadatas[i].flag);
    }

    calculateAverage(resourceValues, count);

    for (int i = 0; i < count; i++) {
        char* id = generateUniqueIdentifier(types[i], metadatas[i]);
        char* json = serializeToJson(id);
        printf("Serialized JSON for resource %d: %s\n", i + 1, json);
        free(id);
        free(json);
    }

    // Free allocated memory
    free(resourceValues);
    free(timestamps);
    free(types);
    for (int i = 0; i < count; i++) {
        free(metadatas[i].data);
    }
    free(metadatas);
}

int main() {
    manageResourceLifecycle();
    return 0;
