#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    record** buckets;
    size_t size;
    size_t count;
} hash_table;

hash_table* create_hash_table(size_t initial_size) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    if (!table) {
        return NULL;
    }
    table->buckets = (record**)calloc(initial_size, sizeof(record*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    table->size = initial_size;
    table->count = 0;
    return table;
}

void destroy_hash_table(hash_table* table) {
    for (size_t i = 0; i < table->size; ++i) {
        record* current = table->buckets[i];
        while (current) {
            record* next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    free(table);
}

size_t hash_function(int key, size_t size) {
    return ((size_t)key * 2654435761u) % size;
}

int insert_record(hash_table* table, record* new_record) {
    if (table->count >= table->size / 2) {
        // Resize the hash table
        hash_table* new_table = create_hash_table(table->size * 2);
        if (!new_table) {
            return -1;
        }
        for (size_t i = 0; i < table->size; ++i) {
            record* current = table->buckets[i];
            while (current) {
                record* next = current->next;
                size_t index = hash_function(current->key, new_table->size);
                current->next = new_table->buckets[index];
                new_table->buckets[index] = current;
                current = next;
            }
        }
        destroy_hash_table(table);
        table = new_table;
    }

    size_t index = hash_function(new_record->key, table->size);
    new_record->next = table->buckets[index];
    table->buckets[index] = new_record;
    ++table->count;
    return 0;
}

record* find_record(hash_table* table, int key) {
    size_t index = hash_function(key, table->size);
    record* current = table->buckets[index];
    while (current) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

int initialize_records(size_t array_size, int value_range_start, int value_range_end, hash_table** table_ptr, void (*log_error)(const char*)) {
    *table_ptr = create_hash_table(array_size);
    if (!*table_ptr) {
        log_error("Failed to allocate memory for hash table.");
        return -1;
    }

    srand(time(NULL));
    int values_used[value_range_end - value_range_start + 1];
    for (int i = 0; i < array_size; ++i) {
        record* new_record = (record*)malloc(sizeof(record));
        if (!new_record) {
            log_error("Failed to allocate memory for record.");
            destroy_hash_table(*table_ptr);
            return -1;
        }

        int value;
        do {
            value = rand() % (value_range_end - value_range_start + 1) + value_range_start;
        } while (values_used[value - value_range_start]);

        values_used[value - value_range_start] = 1;

        new_record->offset = i * sizeof(record);
        new_record->key = i;
        new_record->value = value;
        new_record->next = NULL;

        if (insert_record(*table_ptr, new_record) != 0) {
            log_error("Failed to insert record into hash table.");
            free(new_record);
            destroy_hash_table(*table_ptr);
            return -1;
        }
    }

    return 0;
}
