#define MAX_MESSAGE_LENGTH 256

typedef struct {
    unsigned long timestamp;
    char message[MAX_MESSAGE_LENGTH];
} log_entry;

double* allocate_doubles(size_t count) {
    double* array = (double*)malloc(count * sizeof(double));
    if (!array) {
        perror("Failed to allocate memory for doubles");
        return NULL;
    }
    return array;
}

unsigned long* allocate_timestamps(size_t count) {
    unsigned long* array = (unsigned long*)malloc(count * sizeof(unsigned long));
    if (!array) {
        perror("Failed to allocate memory for timestamps");
        return NULL;
    }
    return array;
}

log_entry* allocate_log_entries(size_t count, size_t max_message_length) {
    log_entry* entries = (log_entry*)malloc(count * sizeof(log_entry));
    if (!entries) {
        perror("Failed to allocate memory for log entries");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < count; ++i) {
        entries[i].timestamp = time(NULL);
        size_t message_length = rand() % max_message_length + 1;
        entries[i].message[message_length] = '\0'; // Null-terminate the string
        strncat(entries[i].message, "Random Message", message_length);
    }

    return entries;
}

void free_memory(double* doubles, unsigned long* timestamps, log_entry* entries) {
    if (doubles) free(doubles);
    if (timestamps) free(timestamps);
    if (entries) free(entries);
}

int main() {
    size_t count = 1000; // Number of entries
    double* doubles = allocate_doubles(count);
    unsigned long* timestamps = allocate_timestamps(count);
    log_entry* entries = allocate_log_entries(count, MAX_MESSAGE_LENGTH);

    if (doubles && timestamps && entries) {
        printf("Memory allocation successful.\n");
        // Use the allocated memory here
        free_memory(doubles, timestamps, entries);
        printf("Memory freed successfully.\n");
    } else {
        printf("Memory allocation failed. Exiting...\n");
