    if (numShapes <= 0 || data == NULL) {
        fprintf(stderr, "Invalid input: numShapes must be greater than 0 and data must not be NULL.\n");
        return NULL;
    }

    Shape* shapes = (Shape*)malloc(numShapes * sizeof(Shape));
    if (shapes == NULL) {
        fprintf(stderr, "Memory allocation failed for shapes array.\n");
        return NULL;
    }

    for (int i = 0; i < numShapes; i++) {
        // Example parsing logic for a circle: assume data format is "CIRCLE radius"
        char* token = strtok(data[i], " ");
        if (token == NULL || strcmp(token, "CIRCLE") != 0) {
            fprintf(stderr, "Invalid shape type in data[%d]: %s\n", i, data[i]);
            free(shapes);
            return NULL;
        }

        float radius = atof(strtok(NULL, " "));
        if (radius <= 0) {
            fprintf(stderr, "Invalid radius value in data[%d]: %s\n", i, data[i]);
            free(shapes);
            return NULL;
        }

        shapes[i].type = SHAPE_TYPE_CIRCLE;
        shapes[i].area = 3.14159 * radius * radius;
        shapes[i].perimeter = 2 * 3.14159 * radius;
    }

    return shapes;
}

// Example usage
int main() {
    char* data[] = {"CIRCLE 5", "CIRCLE -3", "CIRCLE 7"};
    int numShapes = sizeof(data) / sizeof(data[0]);

    Shape* shapes = initShapes(numShapes, (char**)data);
    if (shapes != NULL) {
        for (int i = 0; i < numShapes; i++) {
            printf("Shape %d: Type=%s, Area=%.2f, Perimeter=%.2f\n", i,
                   shapes[i].type == SHAPE_TYPE_CIRCLE ? "CIRCLE" : "UNKNOWN",
                   shapes[i].area, shapes[i].perimeter);
        }
        free(shapes);
    }

    return 0;
}
