#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LOG_ENTRIES 1000000
#define MIN_MESSAGE_LENGTH 10
#define MAX_MESSAGE_LENGTH 256
#define MAX_ENV_VARIABLES 100
#define MAX_ENV_VARIABLE_LENGTH 128

typedef struct {
    time_t timestamp;
    char message[MAX_MESSAGE_LENGTH];
    char** env_vars;
} log_entry;

log_entry* create_log_entries(int num_entries, char** env_vars, int env_count) {
    if (num_entries > MAX_LOG_ENTRIES || env_count > MAX_ENV_VARIABLES) {
        fprintf(stderr, "Error: Exceeded maximum allowed entries or environment variables.\n");
        return NULL;
    }

    log_entry* entries = (log_entry*)malloc(num_entries * sizeof(log_entry));
    if (!entries) {
        fprintf(stderr, "Error: Memory allocation failed for log entries.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_entries; ++i) {
        entries[i].timestamp = time(NULL);
        int message_length = MIN_MESSAGE_LENGTH + rand() % (MAX_MESSAGE_LENGTH - MIN_MESSAGE_LENGTH);
        snprintf(entries[i].message, MAX_MESSAGE_LENGTH, "Log entry %d", i);

        entries[i].env_vars = (char**)malloc(env_count * sizeof(char*));
        if (!entries[i].env_vars) {
            fprintf(stderr, "Error: Memory allocation failed for environment variables.\n");
            free_log_entries(entries, i);
            return NULL;
        }

        for (int j = 0; j < env_count; ++j) {
            int var_length = strlen(env_vars[j]);
            if (var_length > MAX_ENV_VARIABLE_LENGTH) {
                fprintf(stderr, "Error: Environment variable exceeds maximum length.\n");
                free_log_entries(entries, i);
                return NULL;
            }

            entries[i].env_vars[j] = (char*)malloc(MAX_ENV_VARIABLE_LENGTH * sizeof(char));
            if (!entries[i].env_vars[j]) {
                fprintf(stderr, "Error: Memory allocation failed for environment variable %d.\n", j);
                free_log_entries(entries, i);
                return NULL;
            }
            strncpy(entries[i].env_vars[j], env_vars[j], MAX_ENV_VARIABLE_LENGTH);
        }
    }

    printf("Log entries created successfully.\n");
    return entries;
}

void free_log_entries(log_entry* entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        if (entries[i].env_vars) {
            for (int j = 0; j < MAX_ENV_VARIABLES; ++j) {
                if (entries[i].env_vars[j]) {
                    free(entries[i].env_vars[j]);
                }
            }
            free(entries[i].env_vars);
        }
    }
    free(entries);
    printf("Log entries freed successfully.\n");
}

int main() {
    char* env_vars[MAX_ENV_VARIABLES] = {"HOME", "USER", "PATH", "LANG"};
    int num_entries = 100;
    log_entry* log_entries = create_log_entries(num_entries, env_vars, 4);

    if (log_entries) {
        free_log_entries(log_entries, num_entries);
    }

    return 0;
}
