#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_EVENTS 10000
#define MIN_PAYLOAD_SIZE 1024
#define MAX_PAYLOAD_SIZE 65536

typedef struct {
    time_t timestamp;
    char source_ip[16];
    char destination_ip[16];
    int protocol_type;
    void* payload;
    size_t payload_size;
} NetworkEvent;

NetworkEvent* create_network_event() {
    NetworkEvent* event = (NetworkEvent*)malloc(sizeof(NetworkEvent));
    if (!event) {
        perror("Failed to allocate memory for network event");
        return NULL;
    }
    memset(event, 0, sizeof(NetworkEvent));
    return event;
}

void free_network_event(NetworkEvent* event) {
    if (event->payload) {
        free(event->payload);
    }
    free(event);
}

NetworkEvent** initialize_network_events(int num_events) {
    NetworkEvent** events = (NetworkEvent**)malloc(num_events * sizeof(NetworkEvent*));
    if (!events) {
        perror("Failed to allocate memory for network event array");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_events; i++) {
        events[i] = create_network_event();
        if (!events[i]) {
            // Handle error: not all events could be created
            for (int j = 0; j < i; j++) {
                free_network_event(events[j]);
            }
            free(events);
            return NULL;
        }

        // Initialize event metadata
        events[i]->timestamp = time(NULL);
        snprintf(events[i]->source_ip, sizeof(events[i]->source_ip), "192.168.%d.%d", rand() % 256, rand() % 256);
        snprintf(events[i]->destination_ip, sizeof(events[i]->destination_ip), "10.0.%d.%d", rand() % 256, rand() % 256);
        events[i]->protocol_type = rand() % 256;

        // Allocate and initialize payload
        size_t payload_size = MIN_PAYLOAD_SIZE + rand() % (MAX_PAYLOAD_SIZE - MIN_PAYLOAD_SIZE);
        events[i]->payload = malloc(payload_size);
        if (!events[i]->payload) {
            perror("Failed to allocate memory for network event payload");
            free_network_event(events[i]);
            for (int j = 0; j < i; j++) {
                free_network_event(events[j]);
            }
            free(events);
            return NULL;
        }
        memset(events[i]->payload, rand() % 256, payload_size);
        events[i]->payload_size = payload_size;
    }

    return events;
}

void cleanup_network_events(NetworkEvent** events, int num_events) {
    for (int i = 0; i < num_events; i++) {
        free_network_event(events[i]);
    }
    free(events);
}
