typedef struct {
    int value;
} record;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

void deallocate_memory(void* ptr) {
    free(ptr);
}

record* create_records(int initial_size, int key_range_start, int key_range_end) {
    record* records = (record*)allocate_memory(initial_size * sizeof(record));
    for (int i = 0; i < initial_size; i++) {
        records[i].value = rand() % (key_range_end - key_range_start + 1) + key_range_start;
    }
    return records;
}

void resize_records(record** records, int* size, int new_size) {
    record* new_records = (record*)allocate_memory(new_size * sizeof(record));
    for (int i = 0; i < *size && i < new_size; i++) {
        new_records[i] = (*records)[i];
    }
    deallocate_memory(*records);
    *records = new_records;
    *size = new_size;
}

void sort_records(record* records, int size, int (*compare)(const void*, const void*)) {
    qsort(records, size, sizeof(record), compare);
}

int compare_records_asc(const void* a, const void* b) {
    return ((record*)a)->value - ((record*)b)->value;
}

int compare_records_desc(const void* a, const void* b) {
    return ((record*)b)->value - ((record*)a)->value;
}

int get_record_count(record* records, int size) {
    return size;
}
