int get_priority(short event_id) {
    // Predefined mapping from event IDs to priority levels
    static int priorities[] = {1, 2, 3, 4, 5}; // Example priorities
    int index = event_id % (sizeof(priorities) / sizeof(priorities[0]));
    return priorities[index];
}

