typedef struct {
    long timestamp;
    int status_code;
    char* description;
} DataEntry;

typedef struct {
    double intensity;
} Event;

typedef struct {
    long timestamp;
    int category_id;
    char* description;
    DataEntry data[MAX_DATA_ENTRIES];
    Event events[MAX_DATA_ENTRIES];
} Report;

Report* create_reports(int num_reports, int max_data_entries, int max_events) {
    Report* reports = (Report*)malloc(num_reports * sizeof(Report));
    if (!reports) {
        fprintf(stderr, "Memory allocation failed for reports\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_reports; i++) {
        reports[i].timestamp = time(NULL);
        reports[i].category_id = rand() % 3 + 1; // Random category ID between 1 and 3
        snprintf(reports[i].description, 256, "Report %d", i);

        for (int j = 0; j < max_data_entries; j++) {
            reports[i].data[j].timestamp = time(NULL);
            reports[i].data[j].status_code = rand() % 100 + 1;
            snprintf(reports[i].data[j].description, 256, "Status %d", j);
        }

        for (int k = 0; k < max_events; k++) {
            reports[i].events[k].intensity = (double)rand() / RAND_MAX * 100;
        }
    }

    return reports;
}

void free_reports(Report* reports, int num_reports) {
    if (!reports) {
        fprintf(stderr, "Attempted to free null reports\n");
        return;
    }

    for (int i = 0; i < num_reports; i++) {
        // Free dynamically allocated strings in data entries
        for (int j = 0; j < MAX_DATA_ENTRIES; j++) {
            free(reports[i].data[j].description);
        }
    }

    free(reports);
}

int main() {
    int num_reports = 10;
    Report* reports = create_reports(num_reports, MAX_DATA_ENTRIES, MAX_EVENTS);

    if (reports) {
        // Process the reports
        free_reports(reports, num_reports);
    }

    return 0;
}
