#include <string.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MAX_STRING_LENGTH 256
#define DOUBLE_LIMIT 1000.0

typedef struct {
    int int_value;
    char* str_value;
    double* dbl_value;
    struct record* next_record;
} record;

record** allocate_records(int num_keys, const char* user_string) {
    if (num_keys <= 0 || num_keys > MAX_RECORDS) {
        FILE* log_file = fopen("error_log.txt", "a");
        fprintf(log_file, "Invalid input size: %d\n", num_keys);
        fclose(log_file);
        return NULL;
    }

    record** records = (record**)malloc(num_keys * sizeof(record*));
    if (!records) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_keys; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->int_value = rand() % 1001;
        records[i]->dbl_value = (double*)malloc(sizeof(double));
        if (!records[i]->dbl_value) {
            // Free previously allocated memory
            for (int j = 0; j <= i; ++j) {
                free(records[j]->dbl_value);
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        *records[i]->dbl_value = records[i]->int_value * 0.1;

        if (strlen(user_string) > MAX_STRING_LENGTH - 4) {
            strncpy(records[i]->str_value, user_string, MAX_STRING_LENGTH - 3);
            records[i]->str_value[MAX_STRING_LENGTH - 3] = '.';
            records[i]->str_value[MAX_STRING_LENGTH - 2] = '.';
            records[i]->str_value[MAX_STRING_LENGTH - 1] = '\0';
        } else {
            strcpy(records[i]->str_value, user_string);
        }

        records[i]->next_record = NULL;
    }

    return records;
}

void free_records(record** records, int num_keys) {
    for (int i = 0; i < num_keys; ++i) {
        free(records[i]->dbl_value);
        free(records[i]);
    }
    free(records);
}
