from concurrent.futures import ThreadPoolExecutor
from third_party_storage_service import ThirdPartyStorageService

class ConfigUpdater:
    def __init__(self, config_path, data_sources):
        self.config_path = config_path
        self.data_sources = data_sources
        self.storage_service = ThirdPartyStorageService()

    def load_config(self):
        with open(self.config_path, 'r') as file:
            return json.load(file)

    def save_config(self, config):
        with open(self.config_path, 'w') as file:
            json.dump(config, file, indent=4)

    def fetch_data_from_source(self, source):
        try:
            # Simulate fetching data from a source
            return source.fetch()
        except Exception as e:
            print(f"Failed to fetch data from {source.name}: {e}")
            return None

    def update_config(self, config, replacements):
        for key, value in replacements.items():
            if key in config:
                config[key] = value
        return config

    def validate_config(self, config):
        # Simulate validation logic
        return True

    def calculate_checksum(self, data):
        return hashlib.md5(data.encode()).hexdigest()

    def log_performance(self, start_time, duration, throughput):
        print(f"Processing time: {duration} seconds")
        print(f"Throughput: {throughput} operations/sec")

    def rollback_config(self, backup_path):
        if os.path.exists(backup_path):
            self.save_config(json.load(open(backup_path)))
            print("Rollback successful.")
        else:
            print("No backup found for rollback.")

    def run_update(self):
        start_time = time.time()
        config = self.load_config()
        backup_path = f"{self.config_path}.bak"
        os.rename(self.config_path, backup_path)

        try:
            replacements = {}
            with ThreadPoolExecutor(max_workers=len(self.data_sources)) as executor:
                future_to_source = {executor.submit(self.fetch_data_from_source, source): source for source in self.data_sources}
                for future in concurrent.futures.as_completed(future_to_source):
                    source = future_to_source[future]
                    data = future.result()
                    if data:
                        replacements.update(data)

            updated_config = self.update_config(config, replacements)
            if not self.validate_config(updated_config):
                raise ValueError("Invalid configuration after update")

            new_checksum = self.calculate_checksum(json.dumps(updated_config))
            old_checksum = self.storage_service.get_checksum(self.config_path)
            if new_checksum != old_checksum:
                raise ValueError("Checksum mismatch after update")

            self.save_config(updated_config)
            print("Configuration updated successfully.")
        except Exception as e:
            print(f"Error during configuration update: {e}")
            self.rollback_config(backup_path)

        duration = time.time() - start_time
        throughput = len(self.data_sources) / duration if duration > 0 else 0
        self.log_performance(start_time, duration, throughput)
        os.remove(backup_path)

# Example usage:
data_sources = [DataSource1(), DataSource2()]  # Replace with actual data source classes
config_updater = ConfigUpdater('path/to/config.json', data_sources)
config_updater.run_update()
