#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_EVENTS 1024

typedef struct {
    float timestamp;
    short event_id;
    int priority;
} event_record;

event_record *event_buffer[MAX_EVENTS];
int buffer_size = 0;
int next_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_event(const char *message) {
    printf("%s\n", message);
}

void *allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        log_event("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void *ptr) {
    free(ptr);
}

event_record *create_event(short event_id) {
    time_t current_time = time(NULL);
    float timestamp = (float)(current_time + event_id); // Simplified timestamp calculation
    int priority = event_id % 5; // Example priority mapping

    event_record *record = allocate_memory(sizeof(event_record));
    record->timestamp = timestamp;
    record->event_id = event_id;
    record->priority = priority;

    return record;
}

void insert_event(short event_id) {
    pthread_mutex_lock(&mutex);
    if (buffer_size < MAX_EVENTS) {
        event_buffer[next_index] = create_event(event_id);
        next_index = (next_index + 1) % MAX_EVENTS;
        buffer_size++;
    } else {
        log_event("Event buffer full, cannot insert new event");
    }
    pthread_mutex_unlock(&mutex);
}

event_record *get_next_event() {
    pthread_mutex_lock(&mutex);
    if (buffer_size > 0) {
        event_record *record = event_buffer[next_index];
        next_index = (next_index + 1) % MAX_EVENTS;
        buffer_size--;
        return record;
    } else {
        pthread_mutex_unlock(&mutex);
        return NULL; // No events available
    }
}

void cleanup_events() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < buffer_size; i++) {
        free_memory(event_buffer[i]);
    }
    buffer_size = 0;
    next_index = 0;
    pthread_mutex_unlock(&mutex);
}

void *monitor_performance(void *arg) {
    while (1) {
        // Simulate performance monitoring
        log_event("Monitoring performance...");
        sleep(5); // Every 5 seconds
    }
    return NULL;
}

int main() {
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_performance, NULL);

    insert_event(1);
    insert_event(2);
    insert_event(3);

    event_record *event = get_next_event();
    if (event) {
        printf("Event ID: %d, Timestamp: %.2f, Priority: %d\n", event->event_id, event->timestamp, event->priority);
        free_memory(event);
    }

    cleanup_events();

    pthread_join(monitor_thread, NULL);

    return 0;
}
