typedef struct {
    uint64_t id;
    char* name;
    float temperature;
} device;

typedef struct {
    device* dev;
    double timestamp;
    bool status;
} sensor;

void log_message(const char* message) {
    // Implement logging mechanism here
}

device* create_device(uint64_t id, const char* name, float temperature) {
    device* d = (device*)malloc(sizeof(device));
    if (d == NULL) {
        log_message("Memory allocation failed for device");
        return NULL;
    }
    d->id = id;
    d->name = strdup(name);
    d->temperature = temperature;
    return d;
}

sensor* create_sensor(device* dev, double timestamp, bool status) {
    sensor* s = (sensor*)malloc(sizeof(sensor));
    if (s == NULL) {
        log_message("Memory allocation failed for sensor");
        free(dev); // Free the device as it was not used
        return NULL;
    }
    s->dev = dev;
    s->timestamp = timestamp;
    s->status = status;
    return s;
}

void initialize_sensors(sensor** sensors, size_t* count) {
    *count = 10; // Example initial count
    sensor* temp_sensors = (sensor*)malloc(*count * sizeof(sensor));
    if (temp_sensors == NULL) {
        log_message("Memory allocation failed for temporary sensors");
        return;
    }

    for (size_t i = 0; i < *count; ++i) {
        device* dev = create_device(i, "Device", (float)i * 1.5);
        if (dev == NULL) {
            // Handle error and free previously allocated devices
            for (size_t j = 0; j < i; ++j) {
                free(temp_sensors[j].dev->name);
                free(temp_sensors[j].dev);
            }
            free(temp_sensors);
            return;
        }

        sensor* s = create_sensor(dev, (double)i * 0.1, true);
        if (s == NULL) {
            // Handle error and free previously allocated devices and sensors
            for (size_t j = 0; j <= i; ++j) {
                free(temp_sensors[j].dev->name);
                free(temp_sensors[j].dev);
                free(temp_sensors[j]);
            }
            free(temp_sensors);
            return;
        }

        temp_sensors[i] = *s;
        free(s); // Free the temporary sensor as it was copied
    }

    *sensors = temp_sensors;
}

void cleanup_sensors(sensor** sensors, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free((*sensors)[i].dev->name);
        free((*sensors)[i].dev);
        free(&(*sensors)[i]);
    }
    free(*sensors);
}

int main() {
    sensor* sensors;
    size_t count;

    initialize_sensors(&sensors, &count);

    // Use the sensors array...

    cleanup_sensors(&sensors, count);

    return 0;
}
