#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    long offset;
    int key;
    double data;
} record;

typedef struct {
    record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} dynamic_array;

void init_dynamic_array(dynamic_array* arr) {
    arr->records = (record*)malloc(INITIAL_CAPACITY * sizeof(record));
    if (!arr->records) {
        perror("Failed to allocate initial memory");
        exit(EXIT_FAILURE);
    }
    arr->capacity = INITIAL_CAPACITY;
    arr->size = 0;
    pthread_mutex_init(&arr->lock, NULL);
}

void resize_dynamic_array(dynamic_array* arr) {
    size_t new_capacity = arr->capacity * 2;
    record* new_records = (record*)realloc(arr->records, new_capacity * sizeof(record));
    if (!new_records) {
        perror("Failed to reallocate memory");
        exit(EXIT_FAILURE);
    }
    arr->records = new_records;
    arr->capacity = new_capacity;
}

void add_record(dynamic_array* arr, record r) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size == arr->capacity) {
        resize_dynamic_array(arr);
    }
    arr->records[arr->size++] = r;
    pthread_mutex_unlock(&arr->lock);
}

void remove_record(dynamic_array* arr, int key) {
    pthread_mutex_lock(&arr->lock);
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->records[i].key == key) {
            for (size_t j = i; j < arr->size - 1; ++j) {
                arr->records[j] = arr->records[j + 1];
            }
            --arr->size;
            break;
        }
    }
    pthread_mutex_unlock(&arr->lock);
}

void free_dynamic_array(dynamic_array* arr) {
    pthread_mutex_lock(&arr->lock);
    free(arr->records);
    pthread_mutex_destroy(&arr->lock);
}
