    if (!nodes) {
        fprintf(stderr, "Memory allocation failed for node array.\n");
        exit(1);
    }
    return nodes;
}

Item** create_item_array(int size) {
    Item** items = (Item**)malloc(size * sizeof(Item*));
    if (!items) {
        fprintf(stderr, "Memory allocation failed for item array.\n");
        exit(1);
    }
    return items;
}

double** create_double_matrix(int rows, int cols) {
    double** matrix = (double**)malloc(rows * sizeof(double*));
    if (!matrix) {
        fprintf(stderr, "Memory allocation failed for double matrix.\n");
        exit(1);
    }
    for (int i = 0; i < rows; ++i) {
        matrix[i] = (double*)malloc(cols * sizeof(double));
        if (!matrix[i]) {
            fprintf(stderr, "Memory allocation failed for row %d of double matrix.\n", i);
            exit(1);
        }
    }
    return matrix;
}

