        nodes[i] = (Node*)malloc(sizeof(Node));
        if (!nodes[i]) {
            fprintf(stderr, "Memory allocation failed for node %d.\n", i);
            exit(1);
        }
        nodes[i]->index = i + 1;
        nodes[i]->str = (char*)malloc(MAX_STRING_LENGTH * sizeof(char));
        if (!nodes[i]->str) {
            fprintf(stderr, "Memory allocation failed for string of node %d.\n", i);
            exit(1);
        }
    }
}

void initialize_item_array(Item** items, int size) {
    for (int i = 0; i < size; ++i) {
        items[i] = (Item*)malloc(sizeof(Item));
        if (!items[i]) {
            fprintf(stderr, "Memory allocation failed for item %d.\n", i);
            exit(1);
        }
        items[i]->priority = i * 2;
        items[i]->node = NULL;
        items[i]->timestamp = time(NULL);
    }
}

void initialize_double_matrix(double** matrix, int rows, int cols) {
    srand(time(NULL));
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            matrix[i][j] = ((double)rand() / RAND_MAX);
        }
    }
}

void free_node_array(Node** nodes, int size) {
    for (int i = 0; i < size; ++i) {
        free(nodes[i]->str);
        free(nodes[i]);
    }
    free(nodes);
}

void free_item_array(Item** items, int size) {
    for (int i = 0; i < size; ++i) {
        free(items[i]);
    }
    free(items);
}

void free_double_matrix(double** matrix, int rows) {
    for (int i = 0; i < rows; ++i) {
        free(matrix[i]);
    }
    free(matrix);
}
