#define MAX_RECORDS 10000000

typedef struct {
    long offset;
    int key;
    double value;
} record;

void log_message(const char* message) {
    printf("%s\n", message);
}

record* initialize_records(int num_records, int min_key, int max_key) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].offset = (long)i * 100; // Example offset calculation
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].value = (double)records[i].offset / records[i].key; // Example value calculation
    }

    log_message("Records initialized successfully");
    return records;
}

void free_records(record* records, int num_records) {
    if (records) {
        free(records);
        log_message("Records memory freed");
    }
}

int find_largest_key(int* keys, int num_keys) {
    if (!keys || num_keys <= 0) {
        log_message("Invalid input for finding largest key");
        return -1;
    }

    int max_key = keys[0];
    for (int i = 1; i < num_keys; ++i) {
        if (keys[i] > max_key) {
            max_key = keys[i];
        }
    }

    log_message("Largest key found");
    return max_key;
}

int main() {
    int num_records, min_key, max_key;
    printf("Enter number of records: ");
    scanf("%d", &num_records);
    printf("Enter minimum and maximum key values: ");
    scanf("%d %d", &min_key, &max_key);

    if (num_records > MAX_RECORDS) {
        log_message("Number of records exceeds maximum limit");
        return 1;
    }

    record* records = initialize_records(num_records, min_key, max_key);
    if (!records) {
        return 1;
    }

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        log_message("Memory allocation failed for keys");
        free_records(records, num_records);
        return 1;
    }

    printf("Enter %d integer keys:\n", num_records);
    for (int i = 0; i < num_records; ++i) {
        scanf("%d", &keys[i]);
    }

    int largest_key = find_largest_key(keys, num_records);
    if (largest_key != -1) {
        printf("Largest key: %d\n", largest_key);
    }

    free(keys);
    free_records(records, num_records);

    return 0;
}
