#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} Record;

void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_memory_pool(int reset) {
    static char pool[1024 * 1024]; // 1MB memory pool
    static int pool_used = 0;

    if (reset) {
        pool_used = 0;
    }

    if (pool_used + size > sizeof(pool)) {
        fprintf(stderr, "Memory pool overflow\n");
        exit(EXIT_FAILURE);
    }

    void* ptr = &pool[pool_used];
    pool_used += size;
    return ptr;
}

void initialize_arrays(int long_size, int int_size, int record_size, int range) {
    long* long_array = (long*)custom_malloc(long_size * sizeof(long));
    int* int_array = (int*)custom_malloc(int_size * sizeof(int));
    Record* record_array = (Record*)initialize_memory_pool(record_size);

    srand(time(NULL));

    for (int i = 0; i < record_size; i++) {
        record_array[i].value = rand() % range;
    }

    printf("Initialization complete\n");
}

void find_and_print_largest(int* int_array, int size) {
    if (size == 0) {
        printf("Array is empty\n");
        return;
    }

    int largest = int_array[0];
    for (int i = 1; i < size; i++) {
        if (int_array[i] > largest) {
            largest = int_array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

void read_input_and_process() {
    int input_size;
    printf("Enter the number of integers to process: ");
    scanf("%d", &input_size);

    int* int_array = (int*)custom_malloc(input_size * sizeof(int));

    for (int i = 0; i < input_size; i++) {
        scanf("%d", &int_array[i]);
    }

    find_and_print_largest(int_array, input_size);

    free(int_array);
}

int main() {
    int long_size = 100;
    int int_size = 200;
    int record_size = 500;
    int range = 1000;

    initialize_arrays(long_size, int_size, record_size, range);

    read_input_and_process();

    printf("Cleanup complete\n");

    return 0;
}
