#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char* name;
    int priority;
} entry;

typedef struct {
    entry** entries;
    size_t capacity;
    size_t count;
    size_t total_size;
    pthread_mutex_t lock;
} memory_manager;

memory_manager* create_memory_manager(size_t initial_capacity) {
    memory_manager* manager = (memory_manager*)malloc(sizeof(memory_manager));
    if (!manager) return NULL;

    manager->entries = (entry**)calloc(initial_capacity, sizeof(entry*));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->total_size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_memory_manager(memory_manager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]->name);
        free(manager->entries[i]);
    }
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_entry(memory_manager* manager, const char* name, int priority) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        entry** new_entries = (entry**)realloc(manager->entries, new_capacity * sizeof(entry*));
        if (!new_entries) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }

    entry* new_entry = (entry*)malloc(sizeof(entry));
    if (!new_entry) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }

    new_entry->name = strdup(name);
    if (!new_entry->name) {
        free(new_entry);
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }
    new_entry->priority = priority;

    manager->entries[manager->count++] = new_entry;
    manager->total_size += sizeof(entry) + strlen(name);

    printf("Added entry: %s, Priority: %d\n", name, priority);
    printf("Total allocated size: %zu bytes\n", manager->total_size);
    printf("Number of entries: %zu\n", manager->count);

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_entry(memory_manager* manager, const char* name) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->entries[i]->name, name) == 0) {
            free(manager->entries[i]->name);
            free(manager->entries[i]);
            memmove(&manager->entries[i], &manager->entries[i + 1], (manager->count - i - 1) * sizeof(entry*));
            manager->count--;
            manager->total_size -= sizeof(entry) + strlen(name);

            printf("Removed entry: %s\n", name);
            printf("Total allocated size: %zu bytes\n", manager->total_size);
            printf("Number of entries: %zu\n", manager->count);

            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Entry not found
}
