typedef struct {
    int value;
} record;

void* initialize_data_structures(int num_records, int num_keys) {
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        return NULL; // Memory allocation failed
    }

    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL; // Memory allocation failed
    }

    record** records = (record**)malloc(num_records * sizeof(record*));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_records; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            free(keys);
            free(offsets);
            return NULL; // Memory allocation failed
        }
    }

    // Initialize records with default values or other logic as needed

    pthread_mutex_t* mutex = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        for (int i = 0; i < num_records; i++) {
            free(records[i]);
        }
        free(keys);
        free(offsets);
        return NULL; // Memory allocation failed
    }

    pthread_mutex_init(mutex, NULL);

    // Return a pointer to the structure containing all data pointers and mutex
    void* result = malloc(sizeof(void*) * (num_records + num_keys + 3));
    if (!result) {
        pthread_mutex_destroy(mutex);
        for (int i = 0; i < num_records; i++) {
            free(records[i]);
        }
        free(keys);
        free(offsets);
        return NULL; // Memory allocation failed
    }

    ((void**)result)[0] = offsets;
    ((void**)result)[1] = keys;
    ((void**)result)[2] = records;
    ((void**)result)[3] = mutex;

    return result;
}

// Example usage:
int main() {
    int num_records = 1000;
    int num_keys = 500;

    void* data_structures = initialize_data_structures(num_records, num_keys);
    if (!data_structures) {
        // Handle error
        return 1;
    }

    // Use the data structures...

    // Clean up
    long* offsets = (long*)(((void**)data_structures)[0]);
    int* keys = (int*)(((void**)data_structures)[1]);
    record** records = (record**)(((void**)data_structures)[2]);
    pthread_mutex_t* mutex = (pthread_mutex_t*)(((void**)data_structures)[3]);

    for (int i = 0; i < num_records; i++) {
        free(records[i]);
