    log_entry** entries;
    size_t capacity;
    size_t count;
    time_t last_timestamp;
    pthread_mutex_t lock;
} log_manager;

log_manager* create_log_manager(size_t initial_capacity) {
    log_manager* manager = (log_manager*)malloc(sizeof(log_manager));
    if (!manager) return NULL;

    manager->entries = (log_entry**)calloc(initial_capacity, sizeof(log_entry*));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->last_timestamp = time(NULL);
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_log_manager(log_manager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->entries[i]->message);
        free(manager->entries[i]);
    }
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void log_entry_add(log_manager* manager, const char* message, severity_level level) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        log_entry** new_entries = (log_entry**)realloc(manager->entries, new_capacity * sizeof(log_entry*));
        if (!new_entries) {
            pthread_mutex_unlock(&manager->lock);
            return; // Handle memory allocation failure
        }
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }

    log_entry* entry = (log_entry*)malloc(sizeof(log_entry));
    if (!entry) {
        pthread_mutex_unlock(&manager->lock);
        return; // Handle memory allocation failure
    }

    entry->message = strdup(message);
    entry->timestamp = time(NULL);
    entry->level = level;

    manager->entries[manager->count++] = entry;
    manager->last_timestamp = entry->timestamp;

    pthread_mutex_unlock(&manager->lock);
}

void log_manager_stats(log_manager* manager) {
    printf("Total Allocated Size: %zu bytes\n", manager->capacity * sizeof(log_entry*) + manager->count * sizeof(log_entry));
    printf("Number of Entries: %zu\n", manager->count);
    printf("Most Recent Entry Timestamp: %s", ctime(&manager->last_timestamp));
}

