#include <string.h>
#include <pthread.h>

typedef struct entry {
    char* name;
    int priority;
    void* payload;
} entry;

typedef struct memory_manager {
    entry** entries;
    size_t capacity;
    size_t size;
    size_t total_allocated_size;
    size_t average_payload_size;
    pthread_mutex_t lock;
} memory_manager;

memory_manager* create_memory_manager(size_t initial_capacity) {
    memory_manager* manager = (memory_manager*)malloc(sizeof(memory_manager));
    if (!manager) return NULL;

    manager->entries = (entry**)calloc(initial_capacity, sizeof(entry*));
    if (!manager->entries) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->total_allocated_size = 0;
    manager->average_payload_size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_memory_manager(memory_manager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->entries[i]->name);
        if (manager->entries[i]->payload) {
            free(manager->entries[i]->payload);
        }
        free(manager->entries[i]);
    }

    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_entry(memory_manager* manager, const char* name, int priority, void* payload, size_t payload_size) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        entry** new_entries = (entry**)realloc(manager->entries, new_capacity * sizeof(entry*));
        if (!new_entries) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->entries = new_entries;
        manager->capacity = new_capacity;
    }

    entry* new_entry = (entry*)malloc(sizeof(entry));
    if (!new_entry) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Memory allocation failed
    }

    new_entry->name = strdup(name);
    new_entry->priority = priority;
    new_entry->payload = payload ? malloc(payload_size) : NULL;

    if (new_entry->payload) {
        memcpy(new_entry->payload, payload, payload_size);
        manager->total_allocated_size += payload_size;
    }

    manager->entries[manager->size++] = new_entry;
    manager->average_payload_size = manager->total_allocated_size / manager->size;

    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void remove_entry(memory_manager* manager, const char* name) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->entries[i]->name, name) == 0) {
            free(manager->entries[i]->name);
            if (manager->entries[i]->payload) {
                free(manager->entries[i]->payload);
                manager->total_allocated_size -= strlen((char*)manager->entries[i]->payload);
            }
            free(manager->entries[i]);
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->entries[j] = manager->entries[j + 1];
            }
            --manager->size;
            manager->average_payload_size = manager->total_allocated_size / manager->size;
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void log_memory_usage(memory_manager* manager) {
    printf("Total Allocated Size: %zu bytes\n", manager->total_allocated_size);
    printf("Number of Entries: %zu\n", manager->size);
    printf("Average Payload Size: %zu bytes\n", manager->average_payload_size);
}
