#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    long offset;
    int key;
} Record;

typedef struct MemoryPool {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->records = (Record*)malloc(initial_capacity * sizeof(Record));
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

int add_record(MemoryPool* pool, long offset, int key) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Record* new_records = (Record*)realloc(pool->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&pool->lock);
            return -1; // Memory allocation failed
        }
        pool->records = new_records;
        pool->capacity = new_capacity;
    }
    pool->records[pool->size].offset = offset;
    pool->records[pool->size].key = key;
    pool->size++;
    pthread_mutex_unlock(&pool->lock);
    return 0; // Success
}

Record* get_record(MemoryPool* pool, long offset) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size; i++) {
        if (pool->records[i].offset == offset) {
            Record* record = &pool->records[i];
            pthread_mutex_unlock(&pool->lock);
            return record;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL; // Record not found
}

void shrink_memory_pool(MemoryPool* pool, size_t new_capacity) {
    if (new_capacity < pool->size) {
        return; // New capacity must be greater than or equal to current size
    }
    pthread_mutex_lock(&pool->lock);
    Record* new_records = (Record*)realloc(pool->records, new_capacity * sizeof(Record));
    if (new_records) {
        pool->records = new_records;
        pool->capacity = new_capacity;
    }
    pthread_mutex_unlock(&pool->lock);
}
