typedef struct Node {
    int key;
    double value;
    struct Node* next;
} Node;

Node* insert(Node* head, int key, double value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        perror("Memory allocation failed");
        return head;
    }
    newNode->key = key;
    newNode->value = value;
    newNode->next = NULL;

    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);
    pthread_mutex_lock(&lock);

    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && current->key < key) {
        previous = current;
        current = current->next;
    }

    if (previous == NULL) {
        newNode->next = head;
        head = newNode;
    } else {
        newNode->next = current;
        previous->next = newNode;
    }

    pthread_mutex_unlock(&lock);
    pthread_mutex_destroy(&lock);

    return head;
}

int main() {
    Node* head = NULL;

    // Example usage
    head = insert(head, 3, 3.14);
    head = insert(head, 1, 2.71);
    head = insert(head, 2, 1.62);

    // Print the list
    Node* current = head;
    while (current != NULL) {
        printf("Key: %d, Value: %.2f\n", current->key, current->value);
        current = current->next;
    }

    return 0;
}
