void init_task_list(TaskList *list) {
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_task_list(TaskList *list) {
    pthread_mutex_destroy(&list->lock);
}

int add_task(TaskList *list, int id, int priority, const char *status) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_TASKS) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->tasks[list->count].id = id;
    list->tasks[list->count].priority = priority;
    strcpy(list->tasks[list->count].status, status);
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_task(TaskList *list, int id, int new_priority, const char *new_status) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; i++) {
        if (list->tasks[i].id == id) {
            list->tasks[i].priority = new_priority;
            strcpy(list->tasks[i].status, new_status);
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Task not found
}

int find_task_by_id(TaskList *list, int id) {
