    if (log != NULL) {
        fprintf(log, "%s\n", message);
        fclose(log);
    }
}

record* initialize_records(int num_records) {
    record *records = malloc(num_records * sizeof(record));
    if (records == NULL) {
        log_message("Memory allocation failed for records.");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1000;
    }
    log_message("Records initialized successfully.");
    return records;
}

void free_records(record *records, int num_records) {
    if (records != NULL) {
        free(records);
        log_message("Records freed successfully.");
    }
}

int find_largest(int *keys, int size) {
