#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    int id;
    char* str;
} Data;

typedef struct {
    double* doubles;
    char** strings;
    Data** data;
    size_t count;
    pthread_mutex_t mutex;
} MemoryManager;

MemoryManager* create_memory_manager() {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->doubles = NULL;
    manager->strings = NULL;
    manager->data = NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void free_memory_manager(MemoryManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->doubles[i]);
        free(manager->strings[i]);
        free(manager->data[i]->str);
        free(manager->data[i]);
    }

    free(manager->doubles);
    free(manager->strings);
    free(manager->data);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int read_csv(MemoryManager* manager, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    // Read the number of entries
    size_t count;
    fscanf(file, "%zu", &count);

    // Resize arrays to hold the data
    manager->doubles = (double*)realloc(manager->doubles, count * sizeof(double));
    manager->strings = (char**)realloc(manager->strings, count * sizeof(char*));
    manager->data = (Data**)realloc(manager->data, count * sizeof(Data*));

    if (!manager->doubles || !manager->strings || !manager->data) {
        fclose(file);
        return -1;
    }

    manager->count = count;

    // Read each entry
    for (size_t i = 0; i < count; ++i) {
        double value;
        int id;
        char str[256];

        if (fscanf(file, "%lf,%d,%255s", &value, &id, str) != 3) {
            fclose(file);
            return -1;
        }

        manager->doubles[i] = value;
        manager->strings[i] = strdup(str);

        Data* data = (Data*)malloc(sizeof(Data));
        if (!data) {
            fclose(file);
            return -1;
        }

        data->value = value;
        data->id = id;
        data->str = strdup(str);

        manager->data[i] = data;
    }

    fclose(file);
    return 0;
}

void* thread_function(void* arg) {
    MemoryManager* manager = (MemoryManager*)arg;
    pthread_mutex_lock(&manager->mutex);

    // Perform operations on the memory manager
    for (size_t i = 0; i < manager->count; ++i) {
        printf("Double: %f, ID: %d, String: %s\n", manager->doubles[i], manager->data[i]->id, manager->strings[i]);
    }

    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

int main() {
    MemoryManager* manager = create_memory_manager();
    if (!manager) {
        fprintf(stderr, "Failed to create memory manager\n");
        return 1;
    }

    if (read_csv(manager, "data.csv") != 0) {
        fprintf(stderr, "Failed to read CSV file\n");
        free_memory_manager(manager);
        return 1;
    }

    pthread_t threads[4];
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, manager) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            free_memory_manager(manager);
            return 1;
        }
    }

    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
    }

    free_memory_manager(manager);
    return 0;
}
