    if (n <= 0) {
        return NULL;
    }

    Record* records = malloc(n * sizeof(Record));
    if (!records) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; ++i) {
        records[i].offset = (long)i * buffer_size;
        records[i].key = i % INT_MAX; // Handle potential integer overflow
        records[i].value = min_val + ((double)(rand()) / RAND_MAX) * (max_val - min_val);
    }

    if (compare_func) {
        qsort(records, n, sizeof(Record), compare_func);
    }

    return records;
}

void free_records(Record* records) {
    free(records);
}
