typedef struct {
    double value;
} DoubleRecord;

typedef struct {
    char* str;
} CharRecord;

typedef struct {
    double d;
    int i;
    char* s;
} CustomData;

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    int parent;
    int rank;
} UnionFindNode;

void* process_data(void* arg) {
    // Function to process data from CSV and user input
    return NULL;
}

int find(UnionFindNode uf[], int i) {
    if (uf[i].parent != i)
        uf[i].parent = find(uf, uf[i].parent);
    return uf[i].parent;
}

void union_sets(UnionFindNode uf[], int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank)
            uf[rootY].parent = rootX;
        else if (uf[rootX].rank < uf[rootY].rank)
            uf[rootX].parent = rootY;
        else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

int main() {
    int num_records;
    printf("Enter the number of records: ");
    scanf("%d", &num_records);

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    DoubleRecord* double_records = (DoubleRecord*)malloc(num_records * sizeof(DoubleRecord));
    CharRecord* char_records = (CharRecord*)malloc(num_records * sizeof(CharRecord));
    CustomData* custom_data = (CustomData*)malloc(num_records * sizeof(CustomData));

    UnionFindNode* uf = (UnionFindNode*)malloc(num_records * sizeof(UnionFindNode));
    for (int i = 0; i < num_records; i++) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].key = rand() % num_records;
        records[i].offset = rand();
        double_records[i].value = (double)rand() / RAND_MAX;
        char_records[i].str = (char*)malloc(20 * sizeof(char));
        snprintf(char_records[i].str, 20, "String%d", i);
        custom_data[i].d = (double)rand() / RAND_MAX;
        custom_data[i].i = rand() % num_records;
        custom_data[i].s = (char*)malloc(20 * sizeof(char));
        snprintf(custom_data[i].s, 20, "Custom%d", i);
    }

    int max_key = -1;
    for (int i = 0; i < num_records; i++) {
        if (records[i].key > max_key)
            max_key = records[i].key;
    }

    // Simulate external data source integration
    // ...

    clock_t start, end;
    double cpu_time_used;

    start = clock();
    for (int i = 0; i < num_records - 1; i++) {
        union_sets(uf, records[i].key, records[i + 1].key);
    }
    end = clock();

    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Time taken for disjointness tests: %f seconds\n", cpu_time_used);

    // Free allocated memory
    free(records);
    free(double_records);
    for (int i = 0; i < num_records; i++) {
        free(char_records[i].str);
        free(custom_data[i].s);
    }
    free(char_records);
    free(custom_data);
    free(uf);

    return 0;
}
