#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct {
    int socket_descriptor;
    int timeout;
} Connection;

int establishTcpConnectionAndInitialize(const char* server_ip, int port) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);

    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(sock);
        return -1;
    }

    double* timestamps = malloc(10 * sizeof(double));
    char* status_codes = malloc(10 * sizeof(char));
    Connection* connections = malloc(10 * sizeof(Connection));

    if (!timestamps || !status_codes || !connections) {
        perror("Memory allocation failed");
        close(sock);
        free(timestamps);
        free(status_codes);
        free(connections);
        return -1;
    }

    for (int i = 0; i < 10; i++) {
        connections[i].socket_descriptor = sock;
        connections[i].timeout = 5; // Default timeout
    }

    // Simulate network event logging
    printf("Logging connection attempt to %s:%d\n", server_ip, port);

    close(sock);
    free(timestamps);
    free(status_codes);
    free(connections);

    return 0;
}

// JavaScript part using Promises and reduce()
const networkEvents = [
    { type: 'connect', data: '192.168.1.1' },
    { type: 'disconnect', data: '192.168.1.2' }
];

function asyncAggregate(events, initialValue, callback) {
    return events.reduce((acc, event) => {
        return new Promise((resolve, reject) => {
            try {
                const result = callback(acc, event);
                resolve(result);
            } catch (error) {
                reject(error);
            }
        });
    }, initialValue);
}

async function processEvents() {
    try {
        const finalValue = await asyncAggregate(networkEvents, 0, (acc, event) => {
            if (event.type === 'connect') {
                return acc + 1;
            } else if (event.type === 'disconnect') {
                return acc - 1;
            }
            return acc;
        });
        console.log('Final aggregated value:', finalValue);
    } catch (error) {
        console.error('Error processing events:', error);
    }
}

processEvents();
```

This code snippet includes a C function `establishTcpConnectionAndInitialize` that handles TCP connection establishment, memory allocation, and error handling. It also demonstrates an asynchronous aggregation operation using JavaScript's `reduce()` method with promises to process network events efficiently.']

