#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CACHE_SIZE 1024

typedef struct {
    int type;
    union {
        int intValue;
        float floatValue;
        double doubleValue;
        char* stringValue;
    } value;
} Record;

typedef struct {
    Record data[MAX_CACHE_SIZE];
    int size;
    pthread_mutex_t lock;
} Cache;

Cache cache;

void initCache() {
    pthread_mutex_init(&cache.lock, NULL);
    cache.size = 0;
}

int addToCache(Record record) {
    pthread_mutex_lock(&cache.lock);
    if (cache.size >= MAX_CACHE_SIZE) {
        pthread_mutex_unlock(&cache.lock);
        return -1; // Cache full
    }
    cache.data[cache.size++] = record;
    pthread_mutex_unlock(&cache.lock);
    return 0;
}

Record* getFromCache(int index) {
    pthread_mutex_lock(&cache.lock);
    if (index < 0 || index >= cache.size) {
        pthread_mutex_unlock(&cache.lock);
        return NULL; // Invalid index
    }
    Record* record = &cache.data[index];
    pthread_mutex_unlock(&cache.lock);
    return record;
}

void processTransactionData(char* directory, int numTransactions, long* timestamps, int* accountIds, char** descriptions, Record* records) {
    initCache();
    for (int i = 0; i < numTransactions; i++) {
        Record record;
        // Populate record based on transaction data
        addToCache(record);
    }
    // Additional processing logic here
}

void cleanup() {
    pthread_mutex_destroy(&cache.lock);
}
