        "json" => write_json(&log_entries)?,
        "csv" => write_csv(&log_entries)?,
        _ => error!("Unsupported output format"),
    }

    Ok(())
}

fn generate_random_message(max_length: usize) -> String {
    let mut rng = rand::thread_rng();
    (0..rng.gen_range(1, max_length + 1))
        .map(|_| (b'a' + rng.gen::<u8>() % 26) as char)
        .collect()
}

fn write_json(log_entries: &Arc<Mutex<Vec<LogEntry>>>) -> Result<(), Box<dyn std::error::Error>> {
    let entries = log_entries.lock().unwrap();
    let json_data = serde_json::to_string_pretty(entries)?;
    File::create("report.json")?.write_all(json_data.as_bytes())?;
    Ok(())
}

fn write_csv(log_entries: &Arc<Mutex<Vec<LogEntry>>>) -> Result<(), Box<dyn std::error::Error>> {
    let entries = log_entries.lock().unwrap();
    let mut writer = BufWriter::new(File::create("report.csv")?);
    for entry in entries {
        writeln!(writer, "{},{}", entry.timestamp.elapsed().as_secs(), entry.message)?;
    }
    Ok(())
}
