#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    int parent;
    int rank;
} UnionFindNode;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays(long** offsets, int** keys, record** records, int n) {
    *offsets = safe_malloc(n * sizeof(long));
    *keys = safe_malloc(n * sizeof(int));
    *records = safe_malloc(n * sizeof(record));

    for (int i = 0; i < n; ++i) {
        (*offsets)[i] = 0;
        (*keys)[i] = rand() % 1000; // Example range
        (*records)[i].value = rand() % 1000; // Example range
    }
}

void initialize_union_find(UnionFindNode* uf, int n) {
    for (int i = 0; i < n; ++i) {
        uf[i].parent = i;
        uf[i].rank = 0;
    }
}

int find(UnionFindNode* uf, int x) {
    if (uf[x].parent != x) {
        uf[x].parent = find(uf, uf[x].parent);
    }
    return uf[x].parent;
}

void union_sets(UnionFindNode* uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf[rootX].rank > uf[rootY].rank) {
            uf[rootY].parent = rootX;
        } else if (uf[rootX].rank < uf[rootY].rank) {
            uf[rootX].parent = rootY;
        } else {
            uf[rootY].parent = rootX;
            uf[rootX].rank++;
        }
    }
}

void free_arrays(long* offsets, int* keys, record* records, UnionFindNode* uf) {
    free(offsets);
    free(keys);
    free(records);
    free(uf);
}

int main() {
    srand(time(NULL));
    int n;
    printf("Enter the number of elements: ");
    scanf("%d", &n);

    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;
    UnionFindNode* uf = safe_malloc(n * sizeof(UnionFindNode));

    initialize_arrays(&offsets, &keys, &records, n);
    initialize_union_find(uf, n);

    clock_t start, end;
    double cpu_time_used;

    for (int i = 0; i < n - 1; ++i) {
        start = clock();
        union_sets(uf, keys[i], keys[i + 1]);
        end = clock();
        cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
        printf("Union operation %d took %.2f milliseconds\n", i, cpu_time_used * 1000);
    }

    free_arrays(offsets, keys, records, uf);

    return 0;
}
