void initialize_records() {
    records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (records == NULL) {
        log_message("Memory allocation failed for records.");
        exit(EXIT_FAILURE);
    }
    record_count = 0;
}

void add_record(int value, const char* flag_str) {
    if (record_count >= MAX_RECORDS) {
        log_message("Maximum number of records reached.");
        return;
    }

    Record* new_record = &records[record_count];
    new_record->flag = atoi(flag_str);
    new_record->offset = record_count * sizeof(Record);

    record_count++;
}

void print_max_record() {
    if (record_count == 0) {
        log_message("No records to display.");
        return;
    }

    int max_value = records[0].flag;
    int max_index = 0;

    for (int i = 1; i < record_count; i++) {
        if (records[i].flag > max_value) {
            max_value = records[i].flag;
            max_index = i;
        }
    }

    printf("Record with highest value: Flag=%d, Offset=%ld\n", records[max_index].flag, records[max_index].offset);
}

void cleanup_records() {
    free(records);
    log_message("Records memory freed.");
}

