typedef struct {
    double value;
    float floatValue;
    time_t timestamp;
} Measurement;

typedef struct {
    double value;
} Record;

double calculateAverage(double *data, size_t count) {
    double sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += data[i];
    }
    return sum / count;
}

float calculateStandardDeviation(float *data, size_t count) {
    float mean = calculateAverage((double *)data, count);
    float variance = 0.0;
    for (size_t i = 0; i < count; ++i) {
        variance += (data[i] - mean) * (data[i] - mean);
    }
    return sqrt(variance / count);
}

void* safeMalloc(size_t size, const char* description) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory for %s\n", description);
        exit(EXIT_FAILURE);
    }
    return ptr;
}

