record* create_records(int count, int min_value, int max_value) {
    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        log_message("Memory allocation failed for records");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].measurement = ((double)rand()) / RAND_MAX * 100.0;
        records[i].string = (char*)malloc(256);
        if (!records[i].string) {
            log_message("Memory allocation failed for string");
            free_records(records, i);
            return NULL;
        }
        snprintf(records[i].string, 256, "Record %d", i);
    }
    return records;
}

void free_records(record* records, int count) {
    for (int i = 0; i < count; ++i) {
        free(records[i].string);
    }
    free(records);
}

double calculate_average(double* measurements, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; ++i) {
        sum += measurements[i];
    }
    return sum / count;
}

void find_largest_integer(int* integers, int count, int* largest) {
    *largest = integers[0];
    for (int i = 1; i < count; ++i) {
        if (integers[i] > *largest) {
            *largest = integers[i];
        }
    }
}

void process_input(record* records, double* measurements, int* integers, char** strings, int record_count, int input_count) {
    for (int i = 0; i < input_count; ++i) {
        scanf("%d %s", &integers[i], strings[i]);
        records[record_count + i].value = integers[i];
        records[record_count + i].measurement = measurements[record_count + i];
        records[record_count + i].string = strdup(strings[i]);
    }
}

void print_results(int largest, double average) {
    printf("Largest integer: %d\n", largest);
    printf("Average measurement: %.2f\n", average);
}

int main() {
    int record_count = 500;
    int input_count = 100;

    long* offsets = (long*)malloc(record_count * sizeof(long));
    int* keys = (int*)malloc(record_count * sizeof(int));
    double* measurements = (double*)malloc(record_count * sizeof(double));

    if (!offsets || !keys || !measurements) {
        log_message("Memory allocation failed for arrays");
        return 1;
    }

    record* records = create_records(record_count, 0, 1000);
    if (!records) {
        free(offsets);
        free(keys);
        free(measurements);
        return 1;
    }

    double average = calculate_average(measurements, record_count);

    int largest;
    find_largest_integer(records[record_count].value, record_count + input_count, &largest);

    char** strings = (char**)malloc(input_count * sizeof(char*));
    if (!strings) {
        log_message("Memory allocation failed for strings");
        free_records(records, record_count);
        free(offsets);
        free(keys);
        free(measurements);
        return 1;
    }

    int* integers = (int*)malloc(input_count * sizeof(int));
    if (!integers) {
        log_message("Memory allocation failed for integers");
        free(strings);
        free_records(records, record_count);
        free(offsets);
        free(keys);
        free(measurements);
        return 1;
    }

    process_input(records, measurements, integers, strings, record_count, input_count);

    print_results(largest, average);

    free(strings);
    free(integers);
    free_records(records, record_count);
    free(offsets);
    free(keys);
    free(measurements);

    return 0;
}
