#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define NUM_DOUBLE 100
#define NUM_FLOAT 200

typedef struct {
    double value;
} DoubleRecord;

typedef struct {
    float value;
    time_t timestamp;
} Measurement;

typedef struct {
    pthread_mutex_t mutex;
    DoubleRecord doubles[NUM_DOUBLE];
    float floats[NUM_FLOAT];
    Measurement measurements[NUM_DOUBLE];
    DoubleRecord records[NUM_DOUBLE];
    time_t timestamps[NUM_DOUBLE];
} DataStructures;

void* initialize_data_structures(void* arg) {
    DataStructures* ds = (DataStructures*)arg;
    pthread_mutex_init(&ds->mutex, NULL);

    for (int i = 0; i < NUM_DOUBLE; i++) {
        ds->doubles[i].value = 0.0;
        ds->records[i].value = ((double)rand() / RAND_MAX) * 100.0;
        time(&ds->timestamps[i]);
    }

    for (int i = 0; i < NUM_FLOAT; i++) {
        ds->floats[i] = 0.0f;
        Measurement m;
        m.value = ((float)rand() / RAND_MAX) * 100.0f;
        time(&m.timestamp);
        ds->measurements[i] = m;
    }

    return NULL;
}

void cleanup_data_structures(DataStructures* ds) {
    pthread_mutex_destroy(&ds->mutex);
    // Free any dynamically allocated memory here
}

double compute_average(double* values, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }
    return sum / count;
}

float compute_standard_deviation(float* values, int count) {
    float mean = compute_average(values, count);
    float variance = 0.0f;
    for (int i = 0; i < count; i++) {
        variance += (values[i] - mean) * (values[i] - mean);
    }
    return sqrt(variance / count);
}

void* read_input(void* arg) {
    DataStructures* ds = (DataStructures*)arg;
    double double_value;
    float float_value;

    while (1) {
        printf("Enter a double value (or 'q' to quit): ");
        if (scanf("%lf", &double_value) != 1) {
            break;
        }
        pthread_mutex_lock(&ds->mutex);
        ds->doubles[0].value = double_value;
        pthread_mutex_unlock(&ds->mutex);

        printf("Enter a float value: ");
        scanf("%f", &float_value);
        pthread_mutex_lock(&ds->mutex);
        ds->floats[0] = float_value;
        pthread_mutex_unlock(&ds->mutex);
    }

    return NULL;
}

void* compute_statistics(void* arg) {
    DataStructures* ds = (DataStructures*)arg;

    while (1) {
        pthread_mutex_lock(&ds->mutex);
        double average_double = compute_average(ds->doubles, NUM_DOUBLE);
        float standard_deviation_float = compute_standard_deviation(ds->floats, NUM_FLOAT);
        printf("Average Double: %f\n", average_double);
        printf("Standard Deviation Float: %f\n", standard_deviation_float);
        pthread_mutex_unlock(&ds->mutex);

        sleep(1); // Simulate periodic computation
    }

    return NULL;
}

int main() {
    DataStructures ds;

    pthread_t init_thread, read_thread, compute_thread;

    srand(time(NULL));

    if (pthread_create(&init_thread, NULL, initialize_data_structures, &ds) != 0) {
        perror("Failed to create initialization thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(init_thread, NULL) != 0) {
        perror("Failed to join initialization thread");
        return EXIT_FAILURE;
    }

    if (pthread_create(&read_thread, NULL, read_input, &ds) != 0) {
        perror("Failed to create input reading thread");
        cleanup_data_structures(&ds);
        return EXIT_FAILURE;
    }

    if (pthread_create(&compute_thread, NULL, compute_statistics, &ds) != 0) {
        perror("Failed to create statistics computation thread");
        pthread_join(read_thread, NULL);
        cleanup_data_structures(&ds);
        return EXIT_FAILURE;
    }

    pthread_join(read_thread, NULL);
    pthread_join(compute_thread, NULL);

    cleanup_data_structures(&ds);

    return EXIT_SUCCESS;
}
