#define MAX_URL_LENGTH 256

typedef struct {
    int id;
    char url[MAX_URL_LENGTH];
    struct {
        int priority;
        char description[128];
        float weight;
    } data;
} Item;

Item* create_data_structure(int initial_size) {
    return (Item*)malloc(initial_size * sizeof(Item));
}

void initialize_item(Item* item, int id, const char* url_template, int base_priority, const char* base_description, float base_weight) {
    item->id = id;
    snprintf(item->url, MAX_URL_LENGTH, url_template, id);
    item->data.priority = base_priority + (id % 10); // Simple priority calculation
    strncpy(item->data.description, base_description, sizeof(item->data.description));
    item->data.weight = base_weight + (id * 0.1f); // Incremental weight calculation
}

void resize_data_structure(Item** data, int old_size, int new_size) {
    *data = realloc(*data, new_size * sizeof(Item));
}

int main() {
    srand(time(NULL));

    const char* url_template = "http://example.com/resource?id=%d";
    const char* base_description = "Resource Description";

    Item* data = create_data_structure(10);
    for (int i = 0; i < 10; i++) {
        initialize_item(&data[i], rand() % 100, url_template, 5, base_description, 1.0f);
    }

    // Simulate resizing
    resize_data_structure(&data, 10, 20);

    for (int i = 10; i < 20; i++) {
        initialize_item(&data[i], rand() % 100, url_template, 5, base_description, 1.0f);
    }

    // Clean up
    free(data);

    return 0;
}
