#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int hash(int key, int size) {
    return abs(key % size);
}

int is_key_unique(int *keys, int size, int key) {
    for (int i = 0; i < size; i++) {
        if (keys[i] == key) {
            return 0;
        }
    }
    return 1;
}

record* create_records(int pool_size, int record_count, int value_range_start, int value_range_end) {
    srand(42); // Fixed seed for reproducibility
    record *records = (record *)pool_alloc(pool_size, sizeof(record) * record_count);
    if (!records) return NULL;

    int *keys = (int *)pool_alloc(pool_size, sizeof(int) * record_count);
    if (!keys) {
        pool_free(records);
        return NULL;
    }

    for (int i = 0; i < record_count; i++) {
        int key;
        do {
            key = rand() % value_range_end + value_range_start;
        } while (!is_key_unique(keys, i, key));

        keys[i] = key;
        records[i].value = key;

        // Simulate hash table insertion
        int index = hash(key, record_count);
        while (keys[index] != -1) {
            index = (index + 1) % record_count;
        }
        keys[index] = key;
    }

    pool_free(keys);
    return records;
}
