#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    EVENT_TYPE_ERROR,
    EVENT_TYPE_WARNING,
    EVENT_TYPE_INFO
} EventType;

typedef struct Event {
    unsigned long timestamp;
    EventType type;
    int priority;
} Event;

typedef struct EventLog {
    Event* events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventLog;

EventLog* create_event_log(size_t initial_capacity) {
    EventLog* log = (EventLog*)malloc(sizeof(EventLog));
    if (!log) return NULL;

    log->events = (Event*)calloc(initial_capacity, sizeof(Event));
    if (!log->events) {
        free(log);
        return NULL;
    }

    log->capacity = initial_capacity;
    log->count = 0;
    pthread_mutex_init(&log->lock, NULL);

    return log;
}

void destroy_event_log(EventLog* log) {
    pthread_mutex_lock(&log->lock);
    free(log->events);
    pthread_mutex_unlock(&log->lock);
    pthread_mutex_destroy(&log->lock);
    free(log);
}

int add_event(EventLog* log, unsigned long timestamp, EventType type, int priority) {
    if (timestamp == 0 || priority < 0) return -1; // Invalid input

    pthread_mutex_lock(&log->lock);

    if (log->count >= log->capacity) {
        size_t new_capacity = log->capacity * 2;
        Event* new_events = (Event*)realloc(log->events, new_capacity * sizeof(Event));
        if (!new_events) {
            pthread_mutex_unlock(&log->lock);
            return -1; // Memory allocation failed
        }
        log->events = new_events;
        log->capacity = new_capacity;
    }

    log->events[log->count].timestamp = timestamp;
    log->events[log->count].type = type;
    log->events[log->count].priority = priority;
    log->count++;

    pthread_mutex_unlock(&log->lock);
    return 0;
}

void log_event(EventLog* log, unsigned long timestamp, EventType type, int priority) {
    if (add_event(log, timestamp, type, priority) == -1) {
        printf("Failed to add event: Invalid input or memory allocation failed.\n");
    }
}

// Unit tests and logging system implementation would go here
```

This code provides a basic structure for managing an event log with dynamic resizing and thread safety. The `EventLog` struct contains an array of `Event` structs, a capacity to track the allocated size, a count to track the number of events, and a mutex for synchronization. The `create_event_log` function initializes the log, `destroy_event_log` cleans up resources, `add_event` adds new events with validation, and `log_event` provides a convenient interface for adding events while handling errors.

For unit tests, you would typically write separate functions that call these methods with various inputs to ensure they behave as expected. For logging, you could implement different verbosity levels by checking a global variable or function parameter and printing messages accordingly.']

