record* create_record_array(int num_records, size_t max_size, long initial_offset, int initial_key) {
    srand(time(NULL)); // Seed the random number generator
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    size_t total_size = 0;
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = initial_offset + rand() % 1000; // Random offset within a range
        records[i].key = initial_key + rand() % 100; // Random key within a range

        size_t str_size = rand() % 100 + 1; // Random string length between 1 and 100 characters
        if (total_size + sizeof(record) + str_size > max_size) {
            free(records); // Free allocated memory before returning NULL
            return NULL; // Exceeds maximum size limit
        }

        records[i].str = (char*)malloc(str_size);
        if (!records[i].str) {
            for (int j = 0; j < i; ++j) {
                free(records[j].str); // Free previously allocated strings
            }
            free(records); // Free the record array
            return NULL; // Memory allocation failed for string
        }

        memset(records[i].str, 'a' + rand() % 26, str_size - 1); // Fill string with random characters
        records[i].str[str_size - 1] = '\0'; // Null-terminate the string

        total_size += sizeof(record) + str_size;
    }

    return records; // Return the initialized record array
}

void free_record_array(record* records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        free(records[i].str); // Free each string
    }
    free(records); // Free the record array
}
