#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 50000
#define MAX_RESIZE 100000
#define PADDING_SIZE (8 - sizeof(long) - sizeof(int)) % 8

typedef struct {
    long offset;
    int key;
    char padding[PADDING_SIZE];
} Record;

typedef struct {
    Record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordArray;

int initialize_record_array(RecordArray *array, size_t initial_capacity) {
    array->capacity = initial_capacity;
    array->size = 0;
    array->records = (Record *)malloc(initial_capacity * sizeof(Record));
    if (!array->records) return -1; // Memory allocation failed
    pthread_mutex_init(&array->mutex, NULL);
    return 0;
}

int resize_record_array(RecordArray *array, size_t new_capacity) {
    Record *new_records = (Record *)realloc(array->records, new_capacity * sizeof(Record));
    if (!new_records) return -1; // Memory allocation failed
    array->records = new_records;
    array->capacity = new_capacity;
    return 0;
}

int initialize_records(RecordArray *array) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->size; ++i) {
        array->records[i].offset = i * sizeof(Record);
        do {
            array->records[i].key = rand() % 100000;
        } while (i > 0 && array->records[i - 1].key == array->records[i].key);
    }
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int serialize_records(RecordArray *array, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return -1; // File opening failed
    size_t written = fwrite(array->records, sizeof(Record), array->size, file);
    fclose(file);
    if (written != array->size) return -1; // Serialization failed
    return 0;
}

void free_record_array(RecordArray *array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->records);
}

int main() {
    RecordArray array;
    srand(time(NULL));
    int result = initialize_record_array(&array, MAX_RECORDS);
    if (result != 0) {
        printf("Failed to initialize record array\n");
        return -1;
    }
    result = resize_record_array(&array, MAX_RESIZE);
    if (result != 0) {
        printf("Failed to resize record array\n");
        free_record_array(&array);
        return -1;
    }
    result = initialize_records(&array);
    if (result != 0) {
        printf("Failed to initialize records\n");
        free_record_array(&array);
        return -1;
    }
    result = serialize_records(&array, "records.bin");
    if (result != 0) {
        printf("Failed to serialize records\n");
        free_record_array(&array);
        return -1;
    }
    free_record_array(&array);
    return 0;
}
