#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define KEY_RANGE 65536

typedef struct {
    int value;
    long offset;
} record;

typedef struct hash_node {
    int key;
    record *rec;
    struct hash_node *next;
} hash_node;

typedef struct {
    hash_node **buckets;
    size_t size;
    pthread_mutex_t lock;
} hash_table;

hash_table *create_hash_table(size_t size) {
    hash_table *ht = (hash_table *)malloc(sizeof(hash_table));
    ht->buckets = (hash_node **)calloc(size, sizeof(hash_node *));
    ht->size = size;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(hash_table *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        hash_node *node = ht->buckets[i];
        while (node != NULL) {
            hash_node *next = node->next;
            free(node);
            node = next;
        }
    }
    pthread_mutex_destroy(&ht->lock);
    free(ht->buckets);
    free(ht);
}

hash_node *create_hash_node(int key, record *rec) {
    hash_node *node = (hash_node *)malloc(sizeof(hash_node));
    node->key = key;
    node->rec = rec;
    node->next = NULL;
    return node;
}

void insert_into_hash_table(hash_table *ht, int key, record *rec) {
    pthread_mutex_lock(&ht->lock);
    size_t index = key % ht->size;
    hash_node *node = create_hash_node(key, rec);
    node->next = ht->buckets[index];
    ht->buckets[index] = node;
    pthread_mutex_unlock(&ht->lock);
}

record *lookup_in_hash_table(hash_table *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = key % ht->size;
    hash_node *node = ht->buckets[index];
    while (node != NULL) {
        if (node->key == key) {
            pthread_mutex_unlock(&ht->lock);
            return node->rec;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

void *initialize_data_structures(void *arg) {
    hash_table *ht = create_hash_table(KEY_RANGE);
    long *offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    int *keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    record *records = (record *)malloc(MAX_RECORDS * sizeof(record));

    // Initialize data structures and hash table
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        keys[i] = rand() % KEY_RANGE;
        offsets[i] = i * sizeof(long);
        records[i].value = rand();
        records[i].offset = offsets[i];

        record *rec = &records[i];
        if (lookup_in_hash_table(ht, keys[i]) != NULL) {
            // Handle duplicate key
            free(rec);
            continue;
        }
        insert_into_hash_table(ht, keys[i], rec);
    }

    // Clean up and return
    destroy_hash_table(ht);
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    pthread_t thread;
    srand(42); // Seed for reproducibility

    if (pthread_create(&thread, NULL, initialize_data_structures, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
