int hash_function(int key, int size) {
    return abs(key % size);
}

record* create_record_pool(int max_records, int range_start, int range_end) {
    srand(42); // Fixed seed for reproducibility
    int table_size = max_records * 2; // Assuming load factor of 0.5
    record** hash_table = (record**)malloc(table_size * sizeof(record*));
    for (int i = 0; i < table_size; i++) {
        hash_table[i] = NULL;
    }

    record* pool = (record*)malloc(max_records * sizeof(record));
    int pool_index = 0;

    while (pool_index < max_records) {
        int key = rand() % range_end + range_start;
        int index = hash_function(key, table_size);
        if (hash_table[index] == NULL) {
            hash_table[index] = &pool[pool_index];
            pool[pool_index].value = rand() % range_end + range_start;
            pool[pool_index].timestamp = time(NULL);
            pool_index++;
        }
    }

    free(hash_table);
    return pool;
}

int main() {
    int max_records = 100000;
    int range_start = 0;
    int range_end = 1000;

    record* records = create_record_pool(max_records, range_start, range_end);

    // Use the records array as needed

    free(records);
    return 0;
}
```

This code snippet demonstrates how to dynamically allocate memory for and initialize three arrays: one for 'long' offset values (not explicitly shown), another for 'int' keys, and a third for 'record' structures containing 'int' values and a timestamp field. The function `create_record_pool` ensures that no two records share the same key using a custom hash table for efficient uniqueness checks. Each 'record' includes a timestamp to track access times. Initialize all fields in the 'record' structures with random values within a specified range, using a pseudo-random number generator seeded from a fixed integer for reproducibility.

The code also includes a simple `main` function that demonstrates how to use the `create_record_pool` function. The memory allocation is done through dynamic memory management functions like `malloc` and `free`."]

