            // Implement retry mechanism with exponential backoff
            return "Error evaluating weaknesses for Pokemon: " + pokemon.getName();
        }
    }

    private List<Integer> generateRandomWeaknesses(int count, int min, int max) {
        return ThreadLocalRandom.current().ints(count, min, max)
                .boxed()
                .collect(Collectors.toList());
    }
}

