['```c
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    TASK_PENDING,
    TASK_RUNNING,
    TASK_COMPLETED
} TaskState;

typedef struct Task {
    int id;
    void (*callback)(void*);
    int priority;
    int timeout;
    TaskState state;
    struct Task* next;
} Task;

typedef struct TaskList {
    Task* head;
    pthread_mutex_t lock;
} TaskList;

TaskList* create_task_list() {
    TaskList* list = (TaskList*)malloc(sizeof(TaskList));
    if (list) {
        list->head = NULL;
        pthread_mutex_init(&list->lock, NULL);
    }
    return list;
}

void destroy_task_list(TaskList* list) {
    pthread_mutex_lock(&list->lock);
    Task* current = list->head;
    while (current) {
        Task* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void add_task(TaskList* list, int id, void (*callback)(void*), int priority, int timeout) {
    Task* new_task = (Task*)malloc(sizeof(Task));
    if (new_task) {
        new_task->id = id;
        new_task->callback = callback;
        new_task->priority = priority;
        new_task->timeout = timeout;
        new_task->state = TASK_PENDING;
        new_task->next = NULL;

        pthread_mutex_lock(&list->lock);
        if (!list->head) {
            list->head = new_task;
        } else {
            Task* current = list->head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_task;
        }
        pthread_mutex_unlock(&list->lock);
    }
}

void remove_task(TaskList* list, int id) {
    pthread_mutex_lock(&list->lock);
    Task* current = list->head;
    Task* prev = NULL;

    while (current) {
        if (current->id == id) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void execute_tasks(TaskList* list) {
    pthread_mutex_lock(&list->lock);
    Task* current = list->head;
    while (current) {
        if (current->state == TASK_PENDING) {
            current->state = TASK_RUNNING;
            current->callback(current);
            current->state = TASK_COMPLETED;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}
