#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef enum {
    EVENT_TYPE_A,
    EVENT_TYPE_B,
    EVENT_TYPE_C
} EventType;

typedef struct Event {
    long timestamp;
    EventType type;
    int priority;
} Event;

typedef struct EventLog {
    Event* events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventLog;

EventLog* create_event_log(size_t initial_capacity) {
    EventLog* log = (EventLog*)malloc(sizeof(EventLog));
    if (!log) return NULL;

    log->events = (Event*)calloc(initial_capacity, sizeof(Event));
    if (!log->events) {
        free(log);
        return NULL;
    }

    log->capacity = initial_capacity;
    log->count = 0;
    pthread_mutex_init(&log->lock, NULL);

    return log;
}

void destroy_event_log(EventLog* log) {
    if (log) {
        pthread_mutex_destroy(&log->lock);
        free(log->events);
        free(log);
    }
}

int add_event(EventLog* log, Event event) {
    pthread_mutex_lock(&log->lock);
    if (log->count >= log->capacity) {
        size_t new_capacity = log->capacity * 2;
        Event* new_events = (Event*)realloc(log->events, new_capacity * sizeof(Event));
        if (!new_events) {
            pthread_mutex_unlock(&log->lock);
            return -1; // Memory allocation failed
        }
        log->events = new_events;
        log->capacity = new_capacity;
    }

    log->events[log->count++] = event;
    pthread_mutex_unlock(&log->lock);

    return 0;
}

// Additional functions for managing the event log, such as retrieving events,
// sorting them, or filtering based on certain criteria.

int main() {
    EventLog* log = create_event_log(10);
    if (!log) {
        fprintf(stderr, "Failed to create event log\n");
        return 1;
    }

    Event event = {123456789, EVENT_TYPE_A, 5};
    if (add_event(log, event) != 0) {
        fprintf(stderr, "Failed to add event\n");
        destroy_event_log(log);
        return 1;
    }

    // Additional operations with the event log...

    destroy_event_log(log);
    return 0;
}
```

