#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* create_records(int num_records, int min_value, int max_value, int allow_duplicates) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) return NULL;

    srand(time(NULL));

    for (int i = 0; i < num_records; ) {
        int random_value = rand() % (max_value - min_value + 1) + min_value;
        if (allow_duplicates || !find_record(records, i, random_value)) {
            records[i].value = random_value;
            i++;
        }
    }

    return records;
}

int find_record(record* records, int num_records, int value) {
    for (int i = 0; i < num_records; i++) {
        if (records[i].value == value) return 1;
    }
    return 0;
}

void free_records(record* records) {
    free(records);
}
