const fs = require('fs').promises;
const path = require('path');

async function readFilesAndProcess(directory, extension) {
  try {
    const files = await fs.readdir(directory);
    const filteredFiles = files.filter(file => path.extname(file).toLowerCase() === `.${extension}`);

    if (filteredFiles.length === 0) {
      return [];
    }

    const fileContents = await Promise.all(filteredFiles.map(async file => {
      const filePath = path.join(directory, file);
      const content = await fs.readFile(filePath, 'utf8');
      return content;
    }));

    // Process the contents as needed
    // ...

    return fileContents;
  } catch (error) {
    console.error('Error reading files:', error);
    return [];
  }
}

// Example usage:
readFilesAndProcess('/path/to/directory', 'txt')
  .then(contents => {
    console.log('File contents:', contents);
  });
```

