                Message=message,
                MessageAttributes={
                    'Priority': {
                        'DataType': 'String',
                        'StringValue': str(preferences['priority'])
                    }
                }
            )
            return response
        else:
            print(f"Notification disabled for user {user_id}")
    except (BotoCoreError, ClientError) as e:
        print(f"Failed to send notification: {e}")
        raise

@cached(cache)
def get_user_preferences(user_id):
    # Simulate fetching user preferences from a database
    return {
        'enabled': True,
        'topic_arn': 'arn:aws:sns:us-east-1:123456789012:MyTopic',
        'priority': 5
    }

