#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_INPUT_SIZE 1000

typedef struct {
    int key;
    long offset;
} Record;

void log_operation(const char* operation, time_t timestamp) {
    printf("[%ld] %s\n", timestamp, operation);
}

Record* initialize_inventory(int* keys, int size, long min_offset, long max_offset) {
    if (size > MAX_INPUT_SIZE) {
        fprintf(stderr, "Error: Input size exceeds maximum allowed.\n");
        return NULL;
    }

    Record* inventory = malloc(size * sizeof(Record));
    if (!inventory) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator once

    for (int i = 0; i < size; ++i) {
        inventory[i].key = keys[i];
        inventory[i].offset = min_offset + rand() % (max_offset - min_offset + 1);
    }

    log_operation("Inventory initialized", time(NULL));
    return inventory;
}

void free_inventory(Record* inventory, int size) {
    if (inventory) {
        free(inventory);
        log_operation("Inventory freed", time(NULL));
    }
}

Record* find_max_offset_record(Record* inventory, int size) {
    if (!inventory || size <= 0) {
        return NULL;
    }

    Record* max_record = &inventory[0];
    for (int i = 1; i < size; ++i) {
        if (inventory[i].offset > max_record->offset) {
            max_record = &inventory[i];
        }
    }

    return max_record;
}

int main() {
    int keys[MAX_INPUT_SIZE];
    int size;

    printf("Enter the number of records: ");
    scanf("%d", &size);

    if (size <= 0 || size > MAX_INPUT_SIZE) {
        fprintf(stderr, "Error: Invalid input size.\n");
        return EXIT_FAILURE;
    }

    printf("Enter %d keys:\n", size);
    for (int i = 0; i < size; ++i) {
        scanf("%d", &keys[i]);
    }

    Record* inventory = initialize_inventory(keys, size, 1000, 9999);
    if (!inventory) {
        return EXIT_FAILURE;
    }

    Record* max_record = find_max_offset_record(inventory, size);
    if (max_record) {
        printf("Record with maximum offset: Key=%d, Offset=%ld\n", max_record->key, max_record->offset);
    } else {
        fprintf(stderr, "Error: Failed to find record with maximum offset.\n");
    }

    free_inventory(inventory, size);

    return EXIT_SUCCESS;
}
