    int key;
    double value;
    char metadata[256];
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* read_data(void* arg) {
    pthread_mutex_lock(&mutex);
    while (1) {
        long offset;
        int key;
        double value;
        char metadata[256];

        if (scanf("%ld %d %lf %[^\n]", &offset, &key, &value, metadata) != 4) {
            break;
        }

        if (record_count >= MAX_RECORDS) {
            printf("Error: Maximum records reached.\n");
            break;
        }

        records[record_count].offset = offset;
        records[record_count].key = key;
        records[record_count].value = value;
        strcpy(records[record_count].metadata, metadata);
        record_count++;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* process_data(void* arg) {
    for (int i = 0; i < record_count; i++) {
        // Process each record here
        printf("Offset: %ld, Key: %d, Value: %f, Metadata: %s\n",
               records[i].offset, records[i].key, records[i].value, records[i].metadata);
    }
    return NULL;
}

int main() {
    pthread_t read_thread, process_thread;

    if (pthread_create(&read_thread, NULL, read_data, NULL) != 0) {
        perror("Failed to create read thread");
        return EXIT_FAILURE;
    }

    if (pthread_create(&process_thread, NULL, process_data, NULL) != 0) {
        perror("Failed to create process thread");
        pthread_join(read_thread, NULL);
        return EXIT_FAILURE;
    }

    pthread_join(read_thread, NULL);
    pthread_join(process_thread, NULL);

    printf("Total records processed: %d\n", record_count);

    return EXIT_SUCCESS;
}
```

This code provides a basic structure for managing and processing a dynamic dataset with concurrent access. It uses threads to read data from standard input and process it concurrently. The use of mutexes ensures thread safety when accessing shared resources. The code includes logging through print statements, which can be replaced with a more sophisticated logging mechanism as needed.']

