#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    int *keys;
    int *records;
    size_t capacity;
    size_t size;
} DataStructure;

void* initialize_data_structure(size_t initial_capacity) {
    DataStructure *ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) {
        perror("Failed to allocate memory for data structure");
        return NULL;
    }
    ds->keys = (int*)calloc(initial_capacity, sizeof(int));
    ds->records = (int*)calloc(initial_capacity, sizeof(int));
    if (!ds->keys || !ds->records) {
        perror("Failed to allocate memory for keys or records");
        free(ds);
        return NULL;
    }
    ds->capacity = initial_capacity;
    ds->size = 0;
    return ds;
}

void resize_data_structure(DataStructure *ds, size_t new_capacity) {
    int *new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
    int *new_records = (int*)realloc(ds->records, new_capacity * sizeof(int));
    if (!new_keys || !new_records) {
        perror("Failed to reallocate memory for keys or records");
        free(new_keys);
        free(new_records);
        return;
    }
    ds->keys = new_keys;
    ds->records = new_records;
    ds->capacity = new_capacity;
}

void insert_or_update(DataStructure *ds, int key, int value) {
    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->keys[i] == key) {
            ds->records[i] = value;
            return;
        }
    }
    if (ds->size >= ds->capacity) {
        resize_data_structure(ds, ds->capacity * GROWTH_FACTOR);
    }
    ds->keys[ds->size] = key;
    ds->records[ds->size++] = value;
}

void free_data_structure(DataStructure *ds) {
    free(ds->keys);
    free(ds->records);
    free(ds);
}

int main() {
    DataStructure *ds = initialize_data_structure(INITIAL_CAPACITY);
    if (!ds) {
        return EXIT_FAILURE;
    }

    int key, value;
    while (scanf("%d %d", &key, &value) == 2) {
        insert_or_update(ds, key, value);
    }

    free_data_structure(ds);
    return EXIT_SUCCESS;
}
