#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

#define KEY_LENGTH 32
#define IV_LENGTH 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[KEY_LENGTH];
    unsigned char iv[IV_LENGTH];
} CipherContext;

CipherContext* init_cipher_context(const char *password) {
    CipherContext *ctx = (CipherContext*)malloc(sizeof(CipherContext));
    if (!ctx) return NULL;

    // Derive key using SHA-256
    SHA256_CTX sha256;
    SHA256_Init(&sha256);
    SHA256_Update(&sha256, password, strlen(password));
    SHA256_Final(ctx->key, &sha256);

    // Initialize IV with random bytes
    if (!RAND_bytes(ctx->iv, IV_LENGTH)) {
        free(ctx);
        return NULL;
    }

    // Create cipher context
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx);
        return NULL;
    }

    // Initialize cipher context for encryption
    if (1 != EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher_context(CipherContext *ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        free(ctx);
    }
}
