#include <string.h>
#include <pthread.h>

typedef struct Node {
    char* name;
    int priority;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} NodeCollection;

void initNodeCollection(NodeCollection* collection) {
    collection->head = NULL;
    pthread_mutex_init(&collection->lock, NULL);
}

void insertNode(NodeCollection* collection, const char* name, int priority) {
    pthread_mutex_lock(&collection->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->name = strdup(name);
    newNode->priority = priority;
    newNode->next = collection->head;
    collection->head = newNode;
    pthread_mutex_unlock(&collection->lock);
}

Node* getNodeByPriority(NodeCollection* collection, int priority) {
    pthread_mutex_lock(&collection->lock);
    Node* current = collection->head;
    while (current != NULL) {
        if (current->priority == priority) {
            pthread_mutex_unlock(&collection->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&collection->lock);
    return NULL;
}

void freeNodeCollection(NodeCollection* collection) {
    Node* current = collection->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->name);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&collection->lock);
}
