#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    long id;
    double* data;
    struct Node** children;
    int child_count;
    pthread_mutex_t lock;
} Node;

Node* create_node(long id, int data_size, int max_children) {
    Node* node = (Node*)aligned_alloc(64, sizeof(Node));
    if (!node) return NULL;

    node->id = id;
    node->data = (double*)aligned_alloc(64, data_size * sizeof(double));
    if (!node->data) {
        free(node);
        return NULL;
    }

    for (int i = 0; i < data_size; i++) {
        node->data[i] = ((double)rand() / RAND_MAX) * 100.0 - 50.0;
    }

    node->children = (Node**)aligned_alloc(64, max_children * sizeof(Node*));
    if (!node->children) {
        free(node->data);
        free(node);
        return NULL;
    }
    memset(node->children, 0, max_children * sizeof(Node*));

    node->child_count = 0;
    pthread_mutex_init(&node->lock, NULL);

    return node;
}

void destroy_node(Node* node) {
    if (node) {
        for (int i = 0; i < node->child_count; i++) {
            destroy_node(node->children[i]);
        }
        free(node->data);
        free(node->children);
        pthread_mutex_destroy(&node->lock);
        free(node);
    }
}

void add_child(Node* parent, Node* child) {
    if (parent && child) {
        pthread_mutex_lock(&parent->lock);
        if (parent->child_count < max_children) {
            parent->children[parent->child_count++] = child;
        }
        pthread_mutex_unlock(&parent->lock);
    }
}

void remove_child(Node* parent, Node* child) {
    if (parent && child) {
        pthread_mutex_lock(&parent->lock);
        for (int i = 0; i < parent->child_count; i++) {
            if (parent->children[i] == child) {
                parent->children[i] = NULL;
                break;
            }
        }
        pthread_mutex_unlock(&parent->lock);
    }
}

// Additional functions for tree operations like search, insert, delete can be implemented here
