#include <memory>
#include <mutex>

class Task {
public:
    std::string title;
    double duration;
    std::shared_ptr<Task> next;

    Task(std::string t, double d) : title(t), duration(d), next(nullptr) {}
};

class TaskManager {
private:
    std::vector<std::shared_ptr<Task>> tasks;
    std::mutex mtx;

public:
    void initialize() {
        // Initialize the task collection
    }

    bool addTask(const std::string& title, double duration) {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& task : tasks) {
            if (task->title == title || task->duration == duration) {
                return false; // Duplicate or overlapping task
            }
        }
        tasks.push_back(std::make_shared<Task>(title, duration));
        return true;
    }

    std::vector<std::shared_ptr<Task>> getTasksByDuration(double minDuration, double maxDuration) {
        std::lock_guard<std::mutex> lock(mtx);
        std::vector<std::shared_ptr<Task>> result;
        for (const auto& task : tasks) {
            if (task->duration >= minDuration && task->duration <= maxDuration) {
                result.push_back(task);
            }
        }
        return result;
    }

    ~TaskManager() {
        // Ensure all allocated resources are properly released
    }
};
