#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    void (*log)(const char*, ...);
} DataStore;

DataStore* create_data_store(size_t initial_capacity, void (*log_func)(const char*, ...)) {
    DataStore* store = (DataStore*)malloc(sizeof(DataStore));
    if (!store) {
        log_func("Failed to allocate memory for DataStore");
        return NULL;
    }
    store->records = (Record*)malloc(initial_capacity * sizeof(Record));
    if (!store->records) {
        log_func("Failed to allocate memory for records");
        free(store);
        return NULL;
    }
    store->capacity = initial_capacity;
    store->size = 0;
    store->log = log_func;
    store->log("DataStore created with capacity %zu", initial_capacity);
    return store;
}

void destroy_data_store(DataStore* store) {
    if (store->records) {
        free(store->records);
        store->records = NULL;
    }
    free(store);
    store->log("DataStore destroyed");
}

int add_record(DataStore* store, int key, long offset) {
    if (store->size >= store->capacity) {
        size_t new_capacity = store->capacity * 2;
        Record* new_records = (Record*)realloc(store->records, new_capacity * sizeof(Record));
        if (!new_records) {
            store->log("Failed to reallocate memory for records");
            return -1;
        }
        store->records = new_records;
        store->capacity = new_capacity;
    }
    store->records[store->size].key = key;
    store->records[store->size].offset = offset;
    store->size++;
    store->log("Record added with key %d and offset %ld", key, offset);
    return 0;
}

int get_record(DataStore* store, int key, long* offset) {
    for (size_t i = 0; i < store->size; i++) {
        if (store->records[i].key == key) {
            *offset = store->records[i].offset;
            store->log("Record with key %d found at offset %ld", key, *offset);
            return 0;
        }
    }
    store->log("Record with key %d not found", key);
    return -1;
}

void sort_records(DataStore* store, int (*compare)(const void*, const void*)) {
    qsort(store->records, store->size, sizeof(Record), compare);
    store->log("Records sorted");
}

int main() {
    void log(const char* format, ...) {
        va_list args;
        va_start(args, format);
        vprintf(format, args);
        va_end(args);
    }

    DataStore* store = create_data_store(10, log);
    if (store) {
        add_record(store, 5, 12345);
        add_record(store, 3, 67890);
        long offset;
        get_record(store, 5, &offset);
        sort_records(store, (int (*)(const void*, const void*))strcmp);
        destroy_data_store(store);
    }
    return 0;
}
