#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_SIZE 10
#define GROWTH_FACTOR 2

typedef struct {
    int *offsets;
    int *keys;
    int **records;
    int size;
    int capacity;
} DataStructure;

void log_message(const char *message) {
    printf("%s\n", message);
}

int initialize_data_structure(DataStructure *ds, int initial_size) {
    ds->size = 0;
    ds->capacity = initial_size;
    ds->offsets = (int *)malloc(initial_size * sizeof(int));
    ds->keys = (int *)malloc(initial_size * sizeof(int));
    ds->records = (int **)malloc(initial_size * sizeof(int *));

    if (!ds->offsets || !ds->keys || !ds->records) {
        log_message("Memory allocation failed");
        return -1;
    }

    for (int i = 0; i < initial_size; i++) {
        ds->records[i] = NULL;
    }

    return 0;
}

void free_data_structure(DataStructure *ds) {
    for (int i = 0; i < ds->size; i++) {
        if (ds->records[i]) {
            free(ds->records[i]);
        }
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
}

void resize_data_structure(DataStructure *ds) {
    int new_capacity = ds->capacity * GROWTH_FACTOR;
    int *new_offsets = (int *)realloc(ds->offsets, new_capacity * sizeof(int));
    int *new_keys = (int *)realloc(ds->keys, new_capacity * sizeof(int));
    int **new_records = (int **)realloc(ds->records, new_capacity * sizeof(int *));

    if (!new_offsets || !new_keys || !new_records) {
        log_message("Memory reallocation failed");
        return;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    memset(ds->records + ds->capacity, 0, (new_capacity - ds->capacity) * sizeof(int *));
    ds->capacity = new_capacity;
}

int add_record(DataStructure *ds, int key, int value) {
    if (ds->size >= ds->capacity) {
        resize_data_structure(ds);
    }

    for (int i = 0; i < ds->size; i++) {
        if (ds->keys[i] == key) {
            // Handle duplicate key based on user preference
            return -1;
        }
    }

    ds->keys[ds->size] = key;
    ds->records[ds->size] = (int *)malloc(sizeof(int));
    *ds->records[ds->size] = value;
    ds->offsets[ds->size] = ds->size;
    ds->size++;

    return 0;
}

void *process_input(void *arg) {
    DataStructure *ds = (DataStructure *)arg;
    int input;

    while (scanf("%d", &input) != EOF) {
        if (input < 0 || input > 100) { // Predefined valid range
            log_message("Invalid input");
            continue;
        }

        add_record(ds, input, input);
    }

    return NULL;
}

int main() {
    DataStructure ds;
    pthread_t thread;

    if (initialize_data_structure(&ds, INITIAL_SIZE) != 0) {
        return -1;
    }

    log_message("Data structure initialized");

    if (pthread_create(&thread, NULL, process_input, &ds) != 0) {
        log_message("Thread creation failed");
        free_data_structure(&ds);
        return -1;
    }

    pthread_join(thread, NULL);

    log_message("Processing complete");

    free_data_structure(&ds);

    return 0;
}
```

This code provides a basic implementation of the described functionality. It includes error handling for memory allocation failures and demonstrates how to dynamically resize the data structure as needed. The `process_input` function reads integers from standard input, validates them against a predefined range, and adds them to the data structure. The main function initializes the data structure, creates a thread to process input, waits for the thread to complete, and then frees all allocated memory.

Please note that this code is a simplified example and does not include advanced features such as multi-threading, distributed storage, or comprehensive logging. It also lacks detailed error handling and performance optimizations. For a production environment, you would need to expand upon this foundation with additional features and improvements.']

