using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;

public struct ProcessedRecord
{
    public int IntValue;
    public float FloatValue;
    public char[] CharArray;
}

public class DataProcessor
{
    private const int InitialCapacity = 1024;
    private const int GrowthFactor = 2;
    private const int MaxRecordsPerChunk = 512;

    private ProcessedRecord[] _records;
    private int _count;
    private int _capacity;
    private byte[] _key;
    private byte[] _iv;

    public DataProcessor(byte[] key, byte[] iv)
    {
        _key = key;
        _iv = iv;
        _records = new ProcessedRecord[InitialCapacity];
        _capacity = InitialCapacity;
        _count = 0;
    }

    public void HandleDataProcessing(List<byte[]> encryptedRecords)
    {
        foreach (var record in encryptedRecords)
        {
            if (_count >= _capacity)
            {
                Resize(_capacity * GrowthFactor);
            }

            ProcessedRecord processedRecord = DecryptAndInitialize(record);
            _records[_count++] = processedRecord;
        }
    }

    private ProcessedRecord DecryptAndInitialize(byte[] encryptedData)
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = _key;
            aesAlg.IV = _iv;
            aesAlg.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    byte[] decryptedBytes = new byte[encryptedData.Length];
                    int bytesRead = csDecrypt.Read(decryptedBytes, 0, decryptedBytes.Length);

                    ProcessedRecord record;
                    record.IntValue = BitConverter.ToInt32(decryptedBytes, 0);
                    record.FloatValue = BitConverter.ToSingle(decryptedBytes, 4);
                    record.CharArray = new char[16];
                    Array.Copy(decryptedBytes, 8, record.CharArray, 0, Math.Min(16, bytesRead - 8));

                    return record;
                }
            }
        }
    }

    private void Resize(int newCapacity)
    {
        ProcessedRecord[] newRecords = new ProcessedRecord[newCapacity];
        Array.Copy(_records, newRecords, _count);
        _records = newRecords;
        _capacity = newCapacity;
    }

    public void ReleaseMemory()
    {
        _records = null;
        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();
    }
}
