    srand(seed);
    record* records = (record*)malloc(count * sizeof(record));
    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
        records[i].value = ((double)rand() / RAND_MAX) * (max_value - min_value) + min_value;
        records[i].status = (rand() < status_prob * RAND_MAX) ? 'A' : 'I';
    }

    return records;
}

void free_records(record* records, int count) {
    if (records != NULL) {
        free(records);
    }
}

int validate_records(record* records, int count, int min_key, int max_key, double min_value, double max_value) {
    for (int i = 0; i < count; i++) {
        if (records[i].key < min_key || records[i].key > max_key ||
            records[i].value < min_value || records[i].value > max_value ||
            (records[i].status != 'A' && records[i].status != 'I')) {
            return 0;
        }
    }
    return 1;
}

int main() {
    int count = 1000;
    int min_key = 1, max_key = 100;
    double min_value = 0.0, max_value = 100.0;
    double status_prob = 0.5;
    unsigned long seed = time(NULL);

    record* records = initialize_records(count, min_key, max_key, min_value, max_value, status_prob, seed);
    if (records != NULL) {
        if (validate_records(records, count, min_key, max_key, min_value, max_value)) {
            printf("Records initialized and validated successfully\n");
        } else {
            printf("Validation failed\n");
        }
        free_records(records, count);
    }

    return 0;
}
