char* renderPaginatedContent(unsigned long currentPageIndex, unsigned long totalPages) {
    // Allocate memory for page indices array
    unsigned long* pageIndices = (unsigned long*)malloc(totalPages * sizeof(unsigned long));
    if (!pageIndices) {
        perror("Failed to allocate memory for page indices");
        return NULL;
    }

    // Initialize page indices
    for (unsigned long i = 0; i < totalPages; ++i) {
        pageIndices[i] = i + 1;
    }

    // Allocate memory for content snippets array
    char** contentSnippets = (char**)malloc(totalPages * sizeof(char*));
    if (!contentSnippets) {
        perror("Failed to allocate memory for content snippets");
        free(pageIndices);
        return NULL;
    }

    // Initialize content snippets (simulated data)
    for (unsigned long i = 0; i < totalPages; ++i) {
        contentSnippets[i] = (char*)malloc(100 * sizeof(char));
        if (!contentSnippets[i]) {
            perror("Failed to allocate memory for content snippet");
            for (unsigned long j = 0; j < i; ++j) {
                free(contentSnippets[j]);
            }
            free(contentSnippets);
            free(pageIndices);
            return NULL;
        }
        snprintf(contentSnippets[i], 100, "Snippet %lu", i + 1);
    }

    // Allocate memory for PageElement array
    PageElement* pageElements = (PageElement*)malloc(totalPages * sizeof(PageElement));
    if (!pageElements) {
        perror("Failed to allocate memory for PageElement array");
        for (unsigned long i = 0; i < totalPages; ++i) {
            free(contentSnippets[i]);
        }
        free(contentSnippets);
        free(pageIndices);
        return NULL;
    }

    // Initialize PageElement structures
    for (unsigned long i = 0; i < totalPages; ++i) {
        pageElements[i].contentSnippet = contentSnippets[i];
        pageElements[i].index = pageIndices[i];
        pageElements[i].isLastPage = (i == totalPages - 1);
    }

    // Render HTML section
    char* htmlSection = (char*)malloc(1024 * sizeof(char));
    if (!htmlSection) {
        perror("Failed to allocate memory for HTML section");
        for (unsigned long i = 0; i < totalPages; ++i) {
            free(contentSnippets[i]);
        }
        free(contentSnippets);
        free(pageIndices);
        free(pageElements);
        return NULL;
    }

    snprintf(htmlSection, 1024, "<div>");
    for (unsigned long i = 0; i < totalPages; ++i) {
        if (pageElements[i].index == currentPageIndex + 1) {
            snprintf(htmlSection + strlen(htmlSection), 1024 - strlen(htmlSection), "<p><strong>%s</strong></p>", pageElements[i].contentSnippet);
        } else {
            snprintf(htmlSection + strlen(htmlSection), 1024 - strlen(htmlSection), "<p><a href=\"/page/%lu\">%s</a></p>", pageElements[i].index, pageElements[i].contentSnippet);
        }
    }
    if (!pageElements[currentPageIndex].isLastPage) {
        snprintf(htmlSection + strlen(htmlSection), 1024 - strlen(htmlSection), "<p><a href=\"/page/%lu\">Next</a></p>", currentPageIndex + 2);
    }
    strcat(htmlSection, "</div>");

    // Free allocated memory
    for (unsigned long i = 0; i < totalPages; ++i) {
        free(contentSnippets[i]);
    }
    free(contentSnippets);
    free(pageIndices);
    free(pageElements);

    return htmlSection;
}
