typedef struct {
    int key;
    double value;
    char* identifier;
} structured_data;

void initialize_arrays(long* offsets, int* keys, double* values, int size) {
    for (int i = 0; i < size; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 1000;
        values[i] = ((double)rand()) / RAND_MAX * 100.0;
    }
}

void initialize_structured_data(structured_data* data, int size) {
    for (int i = 0; i < size; i++) {
        data[i].key = rand() % 1000;
        data[i].value = ((double)rand()) / RAND_MAX * 100.0;
        data[i].identifier = malloc(20 * sizeof(char));
        sprintf(data[i].identifier, "ID%d", i);
    }
}

void cleanup_structured_data(structured_data* data, int size) {
    for (int i = 0; i < size; i++) {
        free(data[i].identifier);
    }
}

void initialize_data(long** offsets, int** keys, double** values, structured_data** data, int size, int mode) {
    *offsets = malloc(size * sizeof(long));
    *keys = malloc(size * sizeof(int));
    *values = malloc(size * sizeof(double));
    *data = malloc(size * sizeof(structured_data));

    if (*offsets == NULL || *keys == NULL || *values == NULL || *data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    initialize_arrays(*offsets, *keys, *values, size);
    initialize_structured_data(*data, size);

    printf("Initialization complete\n");
}

void cleanup_data(long* offsets, int* keys, double* values, structured_data* data, int size) {
    free(offsets);
    free(keys);
    free(values);
    cleanup_structured_data(data, size);
    free(data);

    printf("Cleanup complete\n");
