#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 1024
#define BUDGET 1024 * 1024 // 1MB

typedef struct Connection {
    int fd;
    char ip[INET_ADDRSTRLEN];
    int port;
    int status;
    struct Connection* next;
} Connection;

Connection* connections[MAX_CONNECTIONS] = {NULL};
int connection_count = 0;
int memory_budget = BUDGET;

void* allocate_memory(size_t size) {
    if (memory_budget < size) {
        fprintf(stderr, "Memory allocation failed: budget exceeded\n");
        return NULL;
    }
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed: out of memory\n");
        return NULL;
    }
    memory_budget -= size;
    return ptr;
}

void free_memory(void* ptr, size_t size) {
    free(ptr);
    memory_budget += size;
}

Connection* create_connection(int fd, const char* ip, int port) {
    if (connection_count >= MAX_CONNECTIONS) {
        fprintf(stderr, "Cannot create new connection: maximum limit reached\n");
        return NULL;
    }
    Connection* conn = allocate_memory(sizeof(Connection));
    if (!conn) {
        return NULL;
    }
    conn->fd = fd;
    strcpy(conn->ip, ip);
    conn->port = port;
    conn->status = 0; // Assuming initial status is 0 (active)
    conn->next = connections[connection_count % MAX_CONNECTIONS];
    connections[connection_count % MAX_CONNECTIONS] = conn;
    connection_count++;
    return conn;
}

void destroy_connection(Connection* conn) {
    if (!conn) {
        return;
    }
    close(conn->fd);
    free_memory(conn, sizeof(Connection));
    connection_count--;
}

void cleanup_connections() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        Connection* current = connections[i];
        while (current) {
            Connection* next = current->next;
            if (current->status == 0) { // Assuming status 0 means active
                destroy_connection(current);
            }
            current = next;
        }
    }
}

void print_connections() {
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        Connection* current = connections[i];
        while (current) {
            printf("FD: %d, IP: %s, Port: %d, Status: %d\n", current->fd, current->ip, current->port, current->status);
            current = current->next;
        }
    }
}

int main() {
    // Simulate network events
    for (int i = 0; i < 10; i++) {
        int fd = socket(AF_INET, SOCK_STREAM, 0);
        if (fd == -1) {
            perror("socket");
            continue;
        }
        struct sockaddr_in addr;
        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        inet_pton(AF_INET, "127.0.0.1", &addr.sin_addr);
        addr.sin_port = htons(8080 + i);
        if (connect(fd, (struct sockaddr*)&addr, sizeof(addr)) == -1) {
            perror("connect");
            close(fd);
            continue;
        }
        create_connection(fd, "127.0.0.1", 8080 + i);
    }

    // Periodic cleanup
    for (int i = 0; i < 5; i++) {
        sleep(1);
        cleanup_connections();
    }

    print_connections();

    return 0;
}
