Record* create_record(int max_size, int seed) {
    static size_t total_allocated = 0;
    static size_t record_count = 0;
    static const size_t max_records = max_size / sizeof(Record);

    if (record_count >= max_records) {
        fprintf(stderr, "Error: Maximum number of records reached.\n");
        return NULL;
    }

    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    total_allocated += sizeof(Record);
    record_count++;

    srand(seed + record_count);

    new_record->buffer = malloc(MAX_RECORD_SIZE);
    if (!new_record->buffer) {
        free(new_record);
        fprintf(stderr, "Error: Buffer allocation failed.\n");
        return NULL;
    }

    total_allocated += MAX_RECORD_SIZE;

    new_record->value = rand() % 100; // Random integer value between 0 and 99
    time(&new_record->timestamp);

    for (int i = 0; i < MAX_RECORD_SIZE - 1; i++) {
        new_record->buffer[i] = 'A' + rand() % 26; // Random ASCII character
    }
    new_record->buffer[MAX_RECORD_SIZE - 1] = '\0';

    return new_record;
}

void free_record(Record* record) {
    if (record) {
        free(record->buffer);
        free(record);
    }
