#include <stdlib.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 10000

typedef struct {
    float x;
    float y;
} point;

typedef enum {
    SUCCESS,
    FAILURE,
    PENDING
} status;

typedef struct transaction {
    double value;
    point location;
    status outcome;
    struct transaction *next;
} transaction;

transaction *transactions[MAX_TRANSACTIONS];
pthread_mutex_t transactions_lock = PTHREAD_MUTEX_INITIALIZER;

void init_memory_management() {
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        transactions[i] = NULL;
    }
}

transaction* create_transaction(double value, point location, status outcome) {
    transaction *new_transaction = malloc(sizeof(transaction));
    if (new_transaction == NULL) {
        return NULL;
    }
    new_transaction->value = value;
    new_transaction->location = location;
    new_transaction->outcome = outcome;
    new_transaction->next = NULL;
    return new_transaction;
}

void add_transaction(double value, point location, status outcome) {
    pthread_mutex_lock(&transactions_lock);
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        if (transactions[i] == NULL) {
            transactions[i] = create_transaction(value, location, outcome);
            break;
        }
    }
    pthread_mutex_unlock(&transactions_lock);
}

transaction* get_transaction(int index) {
    pthread_mutex_lock(&transactions_lock);
    transaction *result = transactions[index];
    pthread_mutex_unlock(&transactions_lock);
    return result;
}

void delete_transaction(int index) {
    pthread_mutex_lock(&transactions_lock);
    if (transactions[index] != NULL) {
        free(transactions[index]);
        transactions[index] = NULL;
    }
    pthread_mutex_unlock(&transactions_lock);
}

void clear_unused_transactions() {
    pthread_mutex_lock(&transactions_lock);
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        if (transactions[i] != NULL) {
            free(transactions[i]);
            transactions[i] = NULL;
        }
    }
    pthread_mutex_unlock(&transactions_lock);
}
