#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct point {
    double latitude;
    double longitude;
} Point;

typedef enum status {
    PENDING,
    COMPLETED,
    FAILED
} Status;

typedef struct transaction {
    char id[20];
    double amount;
    Point location;
    Status status;
    struct transaction *next;
} Transaction;

typedef struct {
    Transaction *head;
    pthread_mutex_t lock;
} TransactionManager;

void init_transaction_manager(TransactionManager *manager) {
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
}

Transaction* create_transaction(const char *id, double amount, Point location, Status status) {
    Transaction *new_transaction = (Transaction*)malloc(sizeof(Transaction));
    if (new_transaction == NULL) return NULL;

    snprintf(new_transaction->id, sizeof(new_transaction->id), "%s", id);
    new_transaction->amount = amount;
    new_transaction->location = location;
    new_transaction->status = status;
    new_transaction->next = NULL;

    return new_transaction;
}

void add_transaction(TransactionManager *manager, Transaction *transaction) {
    pthread_mutex_lock(&manager->lock);
    transaction->next = manager->head;
    manager->head = transaction;
    pthread_mutex_unlock(&manager->lock);
}

Transaction* get_transaction(TransactionManager *manager, const char *id) {
    pthread_mutex_lock(&manager->lock);
    Transaction *current = manager->head;
    while (current != NULL) {
        if (strcmp(current->id, id) == 0) {
            pthread_mutex_unlock(&manager->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void delete_transaction(TransactionManager *manager, const char *id) {
    pthread_mutex_lock(&manager->lock);
    Transaction *current = manager->head;
    Transaction *prev = NULL;

    while (current != NULL) {
        if (strcmp(current->id, id) == 0) {
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void cleanup_transactions(TransactionManager *manager) {
    pthread_mutex_lock(&manager->lock);
    Transaction *current = manager->head;
    while (current != NULL) {
        if (/* condition for unused transaction */) {
            Transaction *temp = current;
            current = current->next;
            free(temp);
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

char* format_transaction_id(const char *id, int max_length) {
    if (strlen(id) <= max_length) {
        char *formatted_id = (char*)malloc(max_length + 2); // +1 for null terminator, +1 for slash
        snprintf(formatted_id, max_length + 2, "%s/", id);
        return formatted_id;
    } else {
        return NULL;
    }
}

void destroy_transaction_manager(TransactionManager *manager) {
    pthread_mutex_lock(&manager->lock);
    Transaction *current = manager->head;
    while (current != NULL) {
        Transaction *temp = current;
        current = current->next;
        free(temp);
    }
    manager->head = NULL;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
