#include <string.h>

#define MAX_STRING_LENGTH 100

typedef struct DataEntry {
    double value;
    char buffer[MAX_STRING_LENGTH];
    struct DataEntry* next;
} DataEntry;

DataEntry* createDataEntry(double value, const char* str) {
    DataEntry* entry = (DataEntry*)malloc(sizeof(DataEntry));
    if (entry == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    entry->value = value;
    strncpy(entry->buffer, str, MAX_STRING_LENGTH - 1);
    entry->buffer[MAX_STRING_LENGTH - 1] = '\0';
    entry->next = NULL;
    return entry;
}

void addDataEntry(DataEntry** head, double value, const char* str) {
    DataEntry* newEntry = createDataEntry(value, str);
    if (*head == NULL) {
        *head = newEntry;
    } else {
        DataEntry* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newEntry;
    }
}

void printDataEntries(DataEntry* head) {
    DataEntry* current = head;
    while (current != NULL) {
        printf("Value: %f, String: %s\n", current->value, current->buffer);
        current = current->next;
    }
}

void freeDataEntries(DataEntry** head) {
    DataEntry* current = *head;
    DataEntry* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}
