point* allocate_points(int count) {
    return (point*)malloc(count * sizeof(point));
}

status* allocate_statuses(int count) {
    return (status*)malloc(count * sizeof(status));
}

transaction* allocate_transactions(int count) {
    return (transaction*)malloc(count * sizeof(transaction));
}

customer* allocate_customers(int count) {
    customer* customers = (customer*)malloc(count * sizeof(customer));
    for (int i = 0; i < count; i++) {
        customers[i].name[0] = '\0';
        customers[i].id = -1;
    }
    return customers;
}

void free_all(double* doubles, point* points, status* statuses, transaction* transactions, customer* customers) {
    free(doubles);
    free(points);
    free(statuses);
    free(transactions);
    free(customers);
}

