        if (!records[i]) {
            log_message("Memory allocation failed for record");
            goto cleanup;
        }

        records[i]->value = rand() % (max_value - min_value + 1) + min_value;

        size_t buffer_size = offsets[i];
        if (buffer_size > MAX_BUFFER_SIZE) {
            buffer_size = MAX_BUFFER_SIZE;
        }
        total_size += buffer_size;

        if (total_size > max_total_size) {
            log_message("Total buffer size exceeds maximum limit");
            goto cleanup;
        }

        records[i]->buffer = malloc(buffer_size);
        if (!records[i]->buffer) {
            log_message("Memory allocation failed for buffer");
            goto cleanup;
