#define MAX_RECORDS 1000
#define MAX_KEY_LENGTH 256

typedef struct Record {
    int value;
    char key[MAX_KEY_LENGTH];
    time_t timestamp;
    struct Record *next;
} Record;

typedef struct Database {
    Record **offsets;
    char **keys;
    pthread_mutex_t lock;
    size_t record_count;
    size_t max_records;
    size_t memory_size;
} Database;

Database* create_database(size_t max_records, size_t memory_size) {
    Database *db = (Database*)malloc(sizeof(Database));
    if (!db) return NULL;

    db->offsets = (Record**)calloc(max_records, sizeof(Record*));
    if (!db->offsets) {
        free(db);
        return NULL;
    }

    db->keys = (char**)calloc(max_records, sizeof(char*));
    if (!db->keys) {
        free(db->offsets);
        free(db);
        return NULL;
    }

    pthread_mutex_init(&db->lock, NULL);
    db->record_count = 0;
    db->max_records = max_records;
    db->memory_size = memory_size;

    return db;
}

void destroy_database(Database *db) {
    for (size_t i = 0; i < db->record_count; ++i) {
        Record *current = db->offsets[i];
        while (current) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }

    free(db->keys);
    free(db->offsets);
    pthread_mutex_destroy(&db->lock);
    free(db);
}

int insert_record(Database *db, const char *key, int value) {
    pthread_mutex_lock(&db->lock);

    if (db->record_count >= db->max_records) {
        pthread_mutex_unlock(&db->lock);
        return -1; // Database is full
    }

    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&db->lock);
        return -2; // Memory allocation failed
    }

    new_record->value = value;
    strncpy(new_record->key, key, MAX_KEY_LENGTH);
    new_record->timestamp = time(NULL);
    new_record->next = NULL;

    size_t index = hash_function(key) % db->max_records;
    if (db->offsets[index]) {
        Record *current = db->offsets[index];
        while (current->next) current = current->next;
        current->next = new_record;
    } else {
        db->offsets[index] = new_record;
    }

    db->keys[db->record_count++] = strdup(key);

    pthread_mutex_unlock(&db->lock);
    return 0; // Success
}

int delete_record(Database *db, const char *key) {
    pthread_mutex_lock(&db->lock);

    size_t index = hash_function(key) % db->max_records;
    Record **current_ptr = &db->offsets[index];
    while (*current_ptr) {
        if (strcmp((*current_ptr)->key, key) == 0) {
            Record *to_delete = *current_ptr;
            *current_ptr = to_delete->next;
            free(to_delete);
            pthread_mutex_unlock(&db->lock);
            return 0; // Success
        }
        current_ptr = &(*current_ptr)->next;
    }

    pthread_mutex_unlock(&db->lock);
    return -1; // Record not found
}

Record* retrieve_record(Database *db, const char *key) {
    pthread_mutex_lock(&db->lock);

    size_t index = hash_function(key) % db->max_records;
    Record *current = db->offsets[index];
    while (current) {
        if (strcmp(current->key, key) == 0) {
            pthread_mutex_unlock(&db->lock);
            return current; // Found record
        }
        current = current->next;
    }

    pthread_mutex_unlock(&db->lock);
    return NULL; // Record not found
}

void cleanup_unused_records(Database *db) {
    pthread_mutex_lock(&db->lock);

    for (size_t i = 0; i < db->record_count; ++i) {
        if (is_record_unused(db, db->keys[i])) {
            delete_record(db, db->keys[i]);
        }
    }

    pthread_mutex_unlock(&db->lock);
}

int is_record_unused(Database *db, const char *key) {
