typedef struct {
    int value;
} Record;

void initializeDataset(int offsetRange, int keyRange, int recordCount, int *offsets, int *keys, Record **records) {
    srand(time(NULL));
    for (int i = 0; i < recordCount; i++) {
        offsets[i] = rand() % offsetRange;
        keys[i] = rand() % keyRange;
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand();
    }
}

void serializeDataset(const char *filename, int offsetCount, int keyCount, int *offsets, int *keys, Record **records) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        exit(EXIT_FAILURE);
    }
    fwrite(offsets, sizeof(int), offsetCount, file);
    fwrite(keys, sizeof(int), keyCount, file);
    for (int i = 0; i < keyCount; i++) {
        fwrite(records[i], sizeof(Record), 1, file);
    }
    fclose(file);
}

void deserializeDataset(const char *filename, int *offsets, int *keys, Record **records) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        exit(EXIT_FAILURE);
    }
    fread(offsets, sizeof(int), offsetCount, file);
    fread(keys, sizeof(int), keyCount, file);
    for (int i = 0; i < keyCount; i++) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        fread(records[i], sizeof(Record), 1, file);
    }
    fclose(file);
}

void freeDataset(int recordCount, Record **records) {
    for (int i = 0; i < recordCount; i++) {
        free(records[i]);
    }
}
