#include <pthread.h>

typedef struct record {
    int value;
    char key[256];
    time_t last_update;
    double resource_usage;
    struct record *next;
} Record;

typedef struct event_record_set {
    Record **hash_table;
    size_t hash_size;
    size_t cache_size;
    size_t cache_count;
    pthread_mutex_t lock;
    int operation_counts[3]; // Insertions, deletions, retrievals
} EventRecordSet;

EventRecordSet* create_event_record_set(size_t hash_size, size_t cache_size) {
    EventRecordSet *set = (EventRecordSet*)malloc(sizeof(EventRecordSet));
    set->hash_table = (Record**)calloc(hash_size, sizeof(Record*));
    set->hash_size = hash_size;
    set->cache_size = cache_size;
    set->cache_count = 0;
    pthread_mutex_init(&set->lock, NULL);
    memset(set->operation_counts, 0, sizeof(int) * 3);
    return set;
}

void destroy_event_record_set(EventRecordSet *set) {
    for (size_t i = 0; i < set->hash_size; ++i) {
        Record *current = set->hash_table[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(set->hash_table);
    pthread_mutex_destroy(&set->lock);
    free(set);
}

size_t hash_function(const char *key, size_t hash_size) {
    size_t hash = 0;
    while (*key != '\0') {
        hash = (hash * 31 + *key++) % hash_size;
    }
    return hash;
}

void insert_record(EventRecordSet *set, int value, const char *key, time_t timestamp, double resource_usage) {
    pthread_mutex_lock(&set->lock);
    size_t index = hash_function(key, set->hash_size);
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->value = value;
    strcpy(new_record->key, key);
    new_record->last_update = timestamp;
    new_record->resource_usage = resource_usage;
    new_record->next = set->hash_table[index];
    set->hash_table[index] = new_record;
    set->operation_counts[0]++;
    pthread_mutex_unlock(&set->lock);
}

void delete_record(EventRecordSet *set, const char *key) {
    pthread_mutex_lock(&set->lock);
    size_t index = hash_function(key, set->hash_size);
    Record **current_ptr = &set->hash_table[index];
    while (*current_ptr != NULL) {
        if (strcmp((*current_ptr)->key, key) == 0) {
            Record *temp = *current_ptr;
            *current_ptr = temp->next;
            free(temp);
            set->operation_counts[1]++;
            break;
        }
        current_ptr = &(*current_ptr)->next;
    }
    pthread_mutex_unlock(&set->lock);
}

Record* retrieve_record(EventRecordSet *set, const char *key) {
    pthread_mutex_lock(&set->lock);
    size_t index = hash_function(key, set->hash_size);
    Record *current = set->hash_table[index];
    while (current != NULL) {
        if (strcmp(current->key, key) == 0) {
            set->operation_counts[2]++;
            pthread_mutex_unlock(&set->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&set->lock);
    return NULL;
}

void cleanup_unused_records(EventRecordSet *set) {
    // Implement logic to clean up unused records
}
