#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MAX_KEY_LENGTH 256

typedef struct Record {
    int value;
    char key[MAX_KEY_LENGTH];
    time_t timestamp;
    int priority;
    struct Record *next;
} Record;

typedef struct EventSystem {
    Record **offsets;
    char **keys;
    pthread_mutex_t lock;
    size_t max_records;
    size_t current_records;
    size_t memory_size;
    int max_priority;
    FILE *log_file;
    unsigned long (*random_generator)();
} EventSystem;

EventSystem* create_event_system(size_t max_records, size_t memory_size, int max_priority, unsigned long (*random_generator)()) {
    EventSystem *system = (EventSystem*)malloc(sizeof(EventSystem));
    system->offsets = (Record**)calloc(max_records, sizeof(Record*));
    system->keys = (char**)calloc(max_records, sizeof(char*));
    for (size_t i = 0; i < max_records; ++i) {
        system->keys[i] = (char*)malloc(MAX_KEY_LENGTH * sizeof(char));
    }
    pthread_mutex_init(&system->lock, NULL);
    system->max_records = max_records;
    system->current_records = 0;
    system->memory_size = memory_size;
    system->max_priority = max_priority;
    system->log_file = fopen("event_system.log", "a");
    system->random_generator = random_generator;
    return system;
}

void destroy_event_system(EventSystem *system) {
    for (size_t i = 0; i < system->current_records; ++i) {
        Record *record = system->offsets[i];
        while (record != NULL) {
            Record *next = record->next;
            free(record);
            record = next;
        }
        free(system->keys[i]);
    }
    free(system->offsets);
    for (size_t i = 0; i < system->max_records; ++i) {
        free(system->keys[i]);
    }
    pthread_mutex_destroy(&system->lock);
    fclose(system->log_file);
    free(system);
}

void add_record(EventSystem *system, const char *key, int value, time_t timestamp, int priority) {
    pthread_mutex_lock(&system->lock);
    if (system->current_records < system->max_records) {
        size_t index = system->random_generator() % system->max_records;
        Record *new_record = (Record*)malloc(sizeof(Record));
        new_record->value = value;
        strcpy(new_record->key, key);
        new_record->timestamp = timestamp;
        new_record->priority = priority;
        new_record->next = system->offsets[index];
        system->offsets[index] = new_record;
        if (system->keys[index] == NULL) {
            strcpy(system->keys[index], key);
        }
        ++system->current_records;
    } else {
        fprintf(system->log_file, "Error: Maximum record count reached.\n");
    }
    pthread_mutex_unlock(&system->lock);
}

Record* get_record(EventSystem *system, const char *key) {
    pthread_mutex_lock(&system->lock);
    for (size_t i = 0; i < system->max_records; ++i) {
        if (strcmp(system->keys[i], key) == 0) {
            Record *record = system->offsets[i];
            while (record != NULL) {
                if (strcmp(record->key, key) == 0) {
                    pthread_mutex_unlock(&system->lock);
                    return record;
                }
                record = record->next;
            }
        }
    }
    pthread_mutex_unlock(&system->lock);
    return NULL;
}

void cleanup_unused_records(EventSystem *system) {
    pthread_mutex_lock(&system->lock);
    for (size_t i = 0; i < system->max_records; ++i) {
        Record *record = system->offsets[i];
        while (record != NULL) {
            if (time(NULL) - record->timestamp > 3600) { // Example: Cleanup records older than 1 hour
                Record *next = record->next;
                free(record);
                record = next;
            } else {
                break;
            }
        }
    }
    pthread_mutex_unlock(&system->lock);
}

unsigned long random_generator() {
    static unsigned long seed = time(NULL);
    return (seed = seed * 1103515245 + 12345) % UINT_MAX;
}
