record* initialize_records(int num_records, int key_range_start, int key_range_end, int condition_key) {
    if (num_records <= 0 || key_range_start > key_range_end) {
        return NULL;
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand();
        keys[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;

        if ((condition_key == -1 && keys[i] >= condition_key) || (condition_key != -1 && keys[i] == condition_key)) {
            records[i].value = rand();
            records[i].timestamp = time(NULL);
            records[i].status = 'Y';
        } else {
            records[i].value = 0;
            records[i].timestamp = 0.0;
            records[i].status = 'N';
        }
    }

    return records;
}

