        for (size_t i = 0; i < array->count; ++i) {
            // Free any dynamically allocated resources in SecurityContext
        }
        free(array->records);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

void add_record(DynamicArray_t *array, int value) {
    pthread_mutex_lock(&array->mutex);
    if (array->count == 0) {
        array->records = (Record_t*)realloc(array->records, sizeof(Record_t));
        if (!array->records) {
            perror("Failed to reallocate memory for records");
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->count = 1;
    } else {
        array->records = (Record_t*)realloc(array->records, (array->count + 1) * sizeof(Record_t));
        if (!array->records) {
            perror("Failed to reallocate memory for records");
            pthread_mutex_unlock(&array->mutex);
            return;
        }
        array->count++;
    }
    array->records[array->count - 1].value = value;
    pthread_mutex_unlock(&array->mutex);
}

void initialize_records(DynamicArray_t *array, int min_value, int max_value) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        if (!RAND_int_range(min_value, max_value + 1, &array->records[i].value)) {
            fprintf(stderr, "Failed to generate random value\n");
        }
        // Initialize SecurityContext here
    }
    pthread_mutex_unlock(&array->mutex);
}

void* thread_function(void *arg) {
    DynamicArray_t *array = (DynamicArray_t*)arg;
    for (int i = 0; i < 1000; ++i) {
        add_record(array, rand() % 100);
    }
    return NULL;
}

int main() {
    pthread_t threads[10];
    DynamicArray_t *array = create_dynamic_array(10);

    if (array) {
        initialize_records(array, -100, 100);

        for (int i = 0; i < 10; ++i) {
            pthread_create(&threads[i], NULL, thread_function, array);
        }

        for (int i = 0; i < 10; ++i) {
            pthread_join(threads[i], NULL);
        }

        destroy_dynamic_array(array);
    }

    return 0;
}
