#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 1024
#define MAX_MEMORY_LIMIT 10 * 1024 * 1024 // 10 MB

typedef struct CustomObject {
    char* string;
    int integer;
    float floating_point;
} CustomObject;

typedef struct Node {
    CustomObject object;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    size_t total_memory_used;
    pthread_mutex_t mutex;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->head = NULL;
    list->total_memory_used = 0;
    pthread_mutex_init(&list->mutex, NULL);
    printf("List created\n");
    return list;
}

void destroy_list(List* list) {
    if (!list) {
        return;
    }
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->object.string);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
    printf("List destroyed\n");
}

Node* create_node(const char* string, int integer, float floating_point) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        perror("Failed to allocate memory for node");
        return NULL;
    }
    node->object.string = strdup(string);
    if (!node->object.string) {
        free(node);
        perror("Failed to allocate memory for string");
        return NULL;
    }
    node->object.integer = integer;
    node->object.floating_point = floating_point;
    node->next = NULL;
    return node;
}

void add_to_list(List* list, const char* string, int integer, float floating_point) {
    pthread_mutex_lock(&list->mutex);
    Node* new_node = create_node(string, integer, floating_point);
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    if (list->total_memory_used + strlen(new_node->object.string) > MAX_MEMORY_LIMIT) {
        free(new_node->object.string);
        free(new_node);
        printf("Memory limit exceeded, operation aborted\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    list->total_memory_used += strlen(new_node->object.string);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
}

void* thread_function(void* arg) {
    List* list = (List*)arg;
    add_to_list(list, "example_string", 123, 456.789);
    return NULL;
}

int main() {
    List* list = create_list();
    if (!list) {
        return EXIT_FAILURE;
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, list) != 0) {
            perror("Failed to create thread");
            destroy_list(list);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_list(list);
    return EXIT_SUCCESS;
}
