#define RECORD_SIZE 1024

typedef struct {
    int value;
    char buffer[RECORD_SIZE];
} record;

void log_message(const char* message) {
    printf("%s\n", message);
}

int initialize_components(long** offsets, int** keys, record** records, size_t count, long seed, int key_range, int string_length) {
    srand(seed);

    *offsets = (long*)malloc(count * sizeof(long));
    if (*offsets == NULL) {
        log_message("Failed to allocate memory for offsets");
        return -1;
    }

    *keys = (int*)malloc(count * sizeof(int));
    if (*keys == NULL) {
        log_message("Failed to allocate memory for keys");
        free(*offsets);
        return -1;
    }

    *records = (record*)malloc(count * sizeof(record));
    if (*records == NULL) {
        log_message("Failed to allocate memory for records");
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (size_t i = 0; i < count; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % key_range;

        if (rand() % 2 == 0) {
            snprintf((*records)[i].buffer, RECORD_SIZE, "RandomString%d", rand());
        } else {
            memset((*records)[i].buffer, 'A' + rand() % 26, string_length);
            (*records)[i].buffer[string_length] = '\0';
        }
    }

    log_message("Components initialized successfully");
    return 0;
}

void cleanup_components(long* offsets, int* keys, record* records, size_t count) {
    free(offsets);
    free(keys);
    for (size_t i = 0; i < count; ++i) {
        memset(records[i].buffer, 0, RECORD_SIZE);
    }
    free(records);
    log_message("Components cleaned up successfully");
}

int main() {
    size_t count = 1000;
    long seed = time(NULL);
    int key_range = 100;
    int string_length = 50;

    long* offsets;
    int* keys;
    record* records;

    if (initialize_components(&offsets, &keys, &records, count, seed, key_range, string_length) == 0) {
        // Use the initialized components here
        cleanup_components(offsets, keys, records, count);
    }

    return 0;
}
