#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int key;
    double timestamp;
    char status;
    float weight;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordList;

RecordList* create_record_list(size_t initial_capacity) {
    RecordList* list = (RecordList*)malloc(sizeof(RecordList));
    if (!list) return NULL;

    list->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!list->records) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_record_list(RecordList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->records);
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int insert_record(RecordList* list, int key, double timestamp, char status, float weight) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Record* new_records = (Record*)realloc(list->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failure
        }

        list->records = new_records;
        list->capacity = new_capacity;
    }

    list->records[list->size].key = key;
    list->records[list->size].timestamp = timestamp;
    list->records[list->size].status = status;
    list->records[list->size].weight = weight;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

// Additional functions for update, delete, and logging can be implemented similarly.
```

