#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* initializeRecords(int numRecords, int minVal, int maxVal, int retryAttempts) {
    record* records = (record*)malloc(numRecords * sizeof(record));
    if (!records) {
        // Handle memory allocation failure
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < numRecords; ++i) {
        int attempts = 0;
        while (attempts < retryAttempts) {
            records[i].value = rand() % (maxVal - minVal + 1) + minVal;
            // Check if the value is valid and within the expected range
            if (records[i].value >= minVal && records[i].value <= maxVal) {
                break;
            }
            ++attempts;
        }
        if (attempts == retryAttempts) {
            // Handle failure to fetch a valid value after retries
            records[i].value = minVal; // Fallback to default value
        }
    }

    return records;
}

void resetRecords(record* records, int numRecords, int defaultValue) {
    for (int i = 0; i < numRecords; ++i) {
        records[i].value = defaultValue;
    }
}

void freeRecords(record* records) {
    if (records) {
        free(records);
    }
}
