            freeRecords(records, i);
            return;
        }
        snprintf(records[i].text, MAX_TEXT_LENGTH, "Record %d", i);

        records[i].metadata = metadataType;

        // Validate metadata
        if (!validateMetadata(&records[i])) {
            logError("Invalid metadata for record %d", i);
            freeRecords(records, i + 1);
            return;
        }
    }

    logInfo("Records initialized successfully");
}

void freeRecords(struct Record* records, int size) {
    for (int i = 0; i < size; i++) {
