#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000000

typedef struct {
    int value;
    char* str;
} record;

typedef struct {
    int key;
    record* rec;
    struct node* next;
} node;

typedef struct {
    node** table;
    int size;
} hash_table;

hash_table* create_hash_table(int size) {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    ht->table = (node**)calloc(size, sizeof(node*));
    ht->size = size;
    return ht;
}

void insert_into_hash_table(hash_table* ht, int key, record* rec) {
    int index = abs(key) % ht->size;
    node* new_node = (node*)malloc(sizeof(node));
    new_node->key = key;
    new_node->rec = rec;
    new_node->next = ht->table[index];
    ht->table[index] = new_node;
}

record* find_in_hash_table(hash_table* ht, int key) {
    int index = abs(key) % ht->size;
    node* current = ht->table[index];
    while (current != NULL) {
        if (current->key == key) {
            return current->rec;
        }
        current = current->next;
    }
    return NULL;
}

void free_hash_table(hash_table* ht) {
    for (int i = 0; i < ht->size; i++) {
        node* current = ht->table[i];
        while (current != NULL) {
            node* next = current->next;
            free(current->rec->str);
            free(current->rec);
            free(current);
            current = next;
        }
    }
    free(ht->table);
    free(ht);
}

void initialize_data_store(int range_start, int range_end) {
    srand(time(NULL));
    long* offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    int* keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    record** records = (record**)malloc(MAX_RECORDS * sizeof(record*));
    hash_table* ht = create_hash_table(MAX_RECORDS);

    for (int i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = rand() % MAX_RECORDS;
        keys[i] = rand() % (range_end - range_start + 1) + range_start;

        records[i] = (record*)malloc(sizeof(record));
        records[i]->value = rand() % (range_end - range_start + 1) + range_start;
        records[i]->str = (char*)malloc(20 * sizeof(char)); // Assuming strings are up to 19 characters long
        sprintf(records[i]->str, "%d", records[i]->value);

        insert_into_hash_table(ht, keys[i], records[i]);
    }

    // Example usage of the hash table
    record* found_record = find_in_hash_table(ht, keys[0]);
    if (found_record != NULL) {
        printf("Found record with value: %d and string: %s\n", found_record->value, found_record->str);
    } else {
        printf("Record not found.\n");
    }

    // Free all allocated memory
    free_hash_table(ht);
    free(offsets);
    free(keys);
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(records[i]->str);
        free(records[i]);
    }
    free(records);
}

int main() {
    initialize_data_store(1, 1000);
    return 0;
}
```

This code snippet provides a basic implementation of the described data store management system. It includes functions for creating and managing a hash table, inserting records into the hash table, finding records by key, and freeing all allocated memory. The `initialize_data_store` function demonstrates how to use these components to initialize the data store with random records and perform a lookup.']

