#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000000

typedef struct {
    int value;
} record;

void log_message(const char* message) {
    printf("%s\n", message);
}

record* initialize_records(int count, int min_value, int max_value) {
    if (count > MAX_RECORDS) {
        log_message("Error: Exceeds maximum allowed records.");
        return NULL;
    }

    record* records = malloc(count * sizeof(record));
    if (!records) {
        log_message("Error: Memory allocation failed for records.");
        return NULL;
    }

    srand(time(NULL));
    int* values = malloc(count * sizeof(int));
    if (!values) {
        log_message("Error: Memory allocation failed for values.");
        free(records);
        return NULL;
    }

    // Initialize unique random values within the specified range
    for (int i = 0; i < count; ++i) {
        int value;
        do {
            value = rand() % (max_value - min_value + 1) + min_value;
        } while (is_value_used(values, i, value));
        records[i].value = value;
    }

    free(values);
    return records;
}

void free_records(record* records, int count) {
    if (records) {
        free(records);
    }
}

int is_value_used(int* values, int index, int value) {
    for (int i = 0; i < index; ++i) {
        if (values[i] == value) {
            return 1;
        }
    }
    return 0;
}

void export_to_csv(record* records, int count, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        log_message("Error: Failed to open file for writing.");
        return;
    }

    fprintf(file, "Value\n");
    for (int i = 0; i < count; ++i) {
        fprintf(file, "%d\n", records[i].value);
    }

    fclose(file);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        log_message("Usage: program_name <input_file> [output_file]");
        return 1;
    }

    const char* input_filename = argv[1];
    const char* output_filename = argc > 2 ? argv[2] : NULL;

    FILE* file = fopen(input_filename, "r");
    if (!file) {
        log_message("Error: Failed to open input file.");
        return 1;
    }

    int count;
    fscanf(file, "%d", &count);
    fclose(file);

    record* records = initialize_records(count, 0, 100); // Example range
    if (!records) {
        return 1;
    }

    log_message("Records initialized successfully.");

    if (output_filename) {
        export_to_csv(records, count, output_filename);
        log_message("Data exported to CSV file.");
    }

    free_records(records, count);

    return 0;
}
