using System;
using System.Collections.Concurrent;
using System.IO;
using System.IO.Compression;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class DataService
{
    private readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();
    private readonly HttpClient _httpClient = new HttpClient();
    private const int MaxCacheSize = 1024 * 1024 * 10; // 10 MB

    public async Task<T> GetDataAsync<T>(string key)
    {
        if (_cache.TryGetValue(key, out var cachedData))
        {
            return (T)cachedData;
        }

        try
        {
            var metadata = await GetMetadataAsync(key);
            var data = await DownloadDataAsync(metadata);
            var deserializedData = DeserializeData(data, metadata.CompressionMethod);

            _cache.TryAdd(key, deserializedData);
            EvictCacheIfNecessary();

            return (T)deserializedData;
        }
        catch (Exception ex)
        {
            LogError(ex);
            throw;
        }
    }

    private async Task<Metadata> GetMetadataAsync(string key)
    {
        // Simulate metadata retrieval from an external service
        var response = await _httpClient.GetAsync($"https://metadata-service.com/{key}");
        response.EnsureSuccessStatusCode();
        var content = await response.Content.ReadAsStringAsync();
        return JsonConvert.DeserializeObject<Metadata>(content);
    }

    private async Task<byte[]> DownloadDataAsync(Metadata metadata)
    {
        // Simulate data download from a distributed file system
        var response = await _httpClient.GetAsync(metadata.Url, HttpCompletionOption.ResponseHeadersRead);
        response.EnsureSuccessStatusCode();

        using (var stream = await response.Content.ReadAsStreamAsync())
        {
            return await ReadCompressedStreamAsync(stream, metadata.CompressionMethod);
        }
    }

    private async Task<byte[]> ReadCompressedStreamAsync(Stream compressedStream, CompressionMethod compressionMethod)
    {
        switch (compressionMethod)
        {
            case CompressionMethod.GZip:
                using (var gzipStream = new GZipStream(compressedStream, CompressionMode.Decompress))
                {
                    return await ReadStreamAsync(gzipStream);
                }
            case CompressionMethod.Deflate:
                using (var deflateStream = new DeflateStream(compressedStream, CompressionMode.Decompress))
                {
                    return await ReadStreamAsync(deflateStream);
                }
            default:
                throw new ArgumentException("Unsupported compression method");
        }
    }

    private async Task<byte[]> ReadStreamAsync(Stream stream)
    {
        using (var memoryStream = new MemoryStream())
        {
            await stream.CopyToAsync(memoryStream);
            return memoryStream.ToArray();
        }
    }

    private object DeserializeData(byte[] data, CompressionMethod compressionMethod)
    {
        // Implement deserialization logic based on the data type and compression method
        throw new NotImplementedException();
    }

    private void EvictCacheIfNecessary()
    {
        if (_cache.Count > MaxCacheSize)
        {
            var lruKey = _cache.Keys.OrderBy(k => _cache[k].GetType().Name).First();
            _cache.TryRemove(lruKey, out _);
        }
    }

    private void LogError(Exception ex)
    {
        // Implement logging logic using a robust framework like Serilog or NLog
        Console.WriteLine($"Error: {ex.Message}");
    }
}

public class Metadata
{
    public string Url { get; set; }
    public CompressionMethod CompressionMethod { get; set; }
}
