#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_INTS 5000000
#define MIN_VALID_INT -1000000
#define MAX_VALID_INT 1000000

typedef struct {
    int value;
    char* data;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    FILE* logFile;
} core_components;

void initialize_core_components(core_components* cc, int size) {
    cc->offsets = (long*)malloc(size * sizeof(long));
    cc->keys = (int*)malloc(size * sizeof(int));
    cc->records = (record**)malloc(size * sizeof(record*));
    cc->logFile = fopen("processing_log.txt", "w");
}

void free_core_components(core_components* cc, int size) {
    for (int i = 0; i < size; i++) {
        if (cc->records[i] != NULL) {
            free(cc->records[i]->data);
            free(cc->records[i]);
        }
    }
    free(cc->offsets);
    free(cc->keys);
    free(cc->records);
    fclose(cc->logFile);
}

void read_integers(core_components* cc, int size, char** sources, int source_count) {
    for (int i = 0; i < source_count; i++) {
        FILE* file = fopen(sources[i], "r");
        if (file == NULL) {
            perror("Error opening file");
            continue;
        }
        int value;
        while (fscanf(file, "%d", &value) != EOF) {
            if (value >= MIN_VALID_INT && value <= MAX_VALID_INT) {
                cc->keys[size] = value;
                cc->records[size] = (record*)malloc(sizeof(record));
                cc->records[size]->value = value;
                cc->records[size]->data = (char*)malloc(256 * sizeof(char));
                sprintf(cc->records[size]->data, "Data for %d", value);
                size++;
            }
        }
        fclose(file);
    }
}

int find_largest_integer(core_components* cc, int size) {
    int largest = MIN_VALID_INT - 1;
    for (int i = 0; i < size; i++) {
        if (cc->keys[i] > largest) {
            largest = cc->keys[i];
        }
    }
    return largest;
}

void log_processing_details(core_components* cc, int size, char** sources, int source_count) {
    time_t now = time(NULL);
    fprintf(cc->logFile, "Processing started at %s\n", ctime(&now));
    for (int i = 0; i < source_count; i++) {
        fprintf(cc->logFile, "Source: %s\n", sources[i]);
    }
    int largest = find_largest_integer(cc, size);
    fprintf(cc->logFile, "Largest integer found: %d\n", largest);
    time_t end_time = time(NULL);
    fprintf(cc->logFile, "Processing ended at %s\n", ctime(&end_time));
}

int main(int argc, char** argv) {
    if (argc < 2) {
        printf("Usage: %s <source1> [<source2> ...]\n", argv[0]);
        return 1;
    }
    int size = 0;
    core_components cc;
    initialize_core_components(&cc, MAX_INTS);
    read_integers(&cc, size, &argv[1], argc - 1);
    log_processing_details(&cc, size, &argv[1], argc - 1);
    free_core_components(&cc, size);
    return 0;
}
