import java.io.*;
import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DistributedObjectDeserializer {

    private static final Logger logger = LoggerFactory.getLogger(DistributedObjectDeserializer.class);
    private ExecutorService executorService;
    private BlockingQueue<DeserializationTask> taskQueue;
    private int maxConcurrentThreads;

    public DistributedObjectDeserializer(int maxConcurrentThreads) {
        this.maxConcurrentThreads = maxConcurrentThreads;
        this.taskQueue = new LinkedBlockingQueue<>();
        this.executorService = Executors.newFixedThreadPool(maxConcurrentThreads);
        for (int i = 0; i < maxConcurrentThreads; i++) {
            executorService.submit(new DeserializationWorker());
        }
    }

    public void submitTask(byte[] serializedData) {
        taskQueue.offer(new DeserializationTask(serializedData));
    }

    private class DeserializationWorker implements Runnable {
        @Override
        public void run() {
            while (true) {
                try {
                    DeserializationTask task = taskQueue.take();
                    Object deserializedObject = deserialize(task.getSerializedData());
                    logger.info("Deserialized object: {}", deserializedObject);
                    // Further processing of the deserialized object
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }

        private Object deserialize(byte[] serializedData) throws IOException, ClassNotFoundException {
            ByteArrayInputStream bis = new ByteArrayInputStream(serializedData);
            ObjectInputStream ois = new ObjectInputStream(bis);
            return ois.readObject();
        }
    }

    private static class DeserializationTask {
        private byte[] serializedData;

        public DeserializationTask(byte[] serializedData) {
            this.serializedData = serializedData;
        }

        public byte[] getSerializedData() {
            return serializedData;
        }
    }

