#define MAX_NAME_LENGTH 100
#define MAX_EMAIL_LENGTH 256

typedef struct {
    char name[MAX_NAME_LENGTH];
    int age;
    char email[MAX_EMAIL_LENGTH];
} UserProfile;

typedef struct {
    UserProfile* profiles;
    size_t capacity;
    size_t count;
} UserProfileCollection;

int validate_profile(const UserProfile* profile) {
    if (profile->name[0] == '\0' || profile->age <= 0 || strchr(profile->email, '@') == NULL) {
        return 0;
    }
    return 1;
}

void add_or_update_profile(UserProfileCollection* collection, const UserProfile* new_profile) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->profiles[i].email, new_profile->email) == 0) {
            // Update existing profile
            strcpy(collection->profiles[i].name, new_profile->name);
            collection->profiles[i].age = new_profile->age;
            return;
        }
    }
    // Add new profile
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        UserProfile* new_profiles = realloc(collection->profiles, new_capacity * sizeof(UserProfile));
        if (!new_profiles) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        collection->profiles = new_profiles;
        collection->capacity = new_capacity;
    }
    strcpy(collection->profiles[collection->count].name, new_profile->name);
    collection->profiles[collection->count].age = new_profile->age;
    strcpy(collection->profiles[collection->count].email, new_profile->email);
    ++collection->count;
}

UserProfile* get_profile_by_email(const UserProfileCollection* collection, const char* email) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->profiles[i].email, email) == 0) {
            return &collection->profiles[i];
        }
    }
    return NULL;
}

UserProfile* get_profile_by_name(const UserProfileCollection* collection, const char* name) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (strcmp(collection->profiles[i].name, name) == 0) {
            return &collection->profiles[i];
        }
    }
    return NULL;
}

void free_user_profile_collection(UserProfileCollection* collection) {
    free(collection->profiles);
    collection->profiles = NULL;
    collection->capacity = 0;
    collection->count = 0;
}
