#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_SENSORS 1000
#define MAX_DATA_POINTS 1000000000
#define CACHE_SIZE 1000

typedef struct {
    double temperature;
    int humidity;
    double windSpeed;
} weatherRecord;

typedef struct {
    weatherRecord *data;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} WeatherCache;

WeatherCache cache = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

void init_cache() {
    cache.data = (weatherRecord *)malloc(CACHE_SIZE * sizeof(weatherRecord));
    if (!cache.data) {
        fprintf(stderr, "Failed to allocate memory for cache\n");
        exit(EXIT_FAILURE);
    }
    cache.capacity = CACHE_SIZE;
}

void free_cache() {
    pthread_mutex_lock(&cache.lock);
    free(cache.data);
    cache.data = NULL;
    cache.count = 0;
    cache.capacity = 0;
    pthread_mutex_unlock(&cache.lock);
}

int add_to_cache(weatherRecord record) {
    pthread_mutex_lock(&cache.lock);
    if (cache.count >= cache.capacity) {
        // Evict least recently used item
        memmove(cache.data, cache.data + 1, (cache.capacity - 1) * sizeof(weatherRecord));
        cache.count--;
    }
    cache.data[cache.count++] = record;
    pthread_mutex_unlock(&cache.lock);
    return 0;
}

int main(int argc, char *argv[]) {
    // Initialize cache
    init_cache();

    // Example usage: Add records to the cache
    weatherRecord new_record = {25.3, 60, 10.2};
    add_to_cache(new_record);

    // Free cache when done
    free_cache();

    return 0;
}
```

This code snippet provides a basic structure for managing a cache of `weatherRecord` structures in C. It includes functions to initialize and free the cache, as well as add records to the cache with a simple eviction policy (least recently used). The use of mutexes ensures thread safety when accessing shared resources. This example can be expanded with additional features such as data validation, JSON export, and more sophisticated caching policies as required by the full task description.']

