#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_KEYS 500
#define MAX_OFFSETS 2000
#define MAX_FLOATS 300
#define MAX_STRINGS 400
#define MAX_NODES 500
#define MAX_STATUS 2
#define MAX_UNION_DATA 600

typedef struct {
    int value;
} Record;

typedef struct node {
    // Define the structure of a node
} Node;

typedef enum {
    STATUS_INT,
    STATUS_DOUBLE
} Status;

typedef union {
    int i;
    double d;
} UnionData;

void* manage_memory(void* arg) {
    long* offsets = (long*)malloc(MAX_OFFSETS * sizeof(long));
    if (!offsets) {
        // Handle memory allocation failure
        return NULL;
    }

    int* keys = (int*)malloc(MAX_KEYS * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    Record* records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL;
    }

    float* floats = (float*)malloc(MAX_FLOATS * sizeof(float));
    if (!floats) {
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    char** strings = (char**)malloc(MAX_STRINGS * sizeof(char*));
    for (int i = 0; i < MAX_STRINGS; i++) {
        strings[i] = (char*)malloc(256 * sizeof(char)); // Assuming max string length of 255
        if (!strings[i]) {
            for (int j = 0; j < i; j++) {
                free(strings[j]);
            }
            free(floats);
            free(records);
            free(keys);
            free(offsets);
            return NULL;
        }
    }

    Node** nodes = (Node**)malloc(MAX_NODES * sizeof(Node*));
    if (!nodes) {
        for (int i = 0; i < MAX_STRINGS; i++) {
            free(strings[i]);
        }
        free(floats);
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    Status* statuses = (Status*)malloc(MAX_STATUS * sizeof(Status));
    if (!statuses) {
        for (int i = 0; i < MAX_STRINGS; i++) {
            free(strings[i]);
        }
        free(nodes);
        free(floats);
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    UnionData* union_data = (UnionData*)malloc(MAX_UNION_DATA * sizeof(UnionData));
    if (!union_data) {
        free(statuses);
        for (int i = 0; i < MAX_STRINGS; i++) {
            free(strings[i]);
        }
        free(nodes);
        free(floats);
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    // Initialize arrays with random values and unique keys/offsets
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].value = rand() % 1000;
        offsets[i] = rand() % MAX_OFFSETS;
        keys[i] = rand() % MAX_KEYS;
    }

    // Initialize other arrays with random values
    for (int i = 0; i < MAX_FLOATS; i++) {
        floats[i] = ((float)rand()) / RAND_MAX * 100.0f;
    }

    for (int i = 0; i < MAX_STRINGS; i++) {
        snprintf(strings[i], 256, "String%d", rand() % 100);
    }

    for (int i = 0; i < MAX_NODES; i++) {
        nodes[i] = NULL; // Initialize to NULL or allocate memory
    }

    for (int i = 0; i < MAX_STATUS; i++) {
        statuses[i] = rand() % MAX_STATUS == 0 ? STATUS_INT : STATUS_DOUBLE;
    }

    for (int i = 0; i < MAX_UNION_DATA; i++) {
        if (statuses[i / 2] == STATUS_INT) {
            union_data[i].i = rand() % 1000;
        } else {
            union_data[i].d = ((double)rand()) / RAND_MAX * 100.0;
        }
    }

    // Free allocated memory
    for (int i = 0; i < MAX_STRINGS; i++) {
        free(strings[i]);
    }
    free(union_data);
    free(statuses);
    free(nodes);
    free(floats);
    free(records);
    free(keys);
    free(offsets);

    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, manage_memory, NULL) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    if (pthread_join(thread, NULL) != 0) {
        perror("Failed to join thread");
        return 1;
    }

    return 0;
}
