    *double_arr = (double*)malloc(n * sizeof(double));
    *string_arr = (char**)malloc(n * sizeof(char*));
    *point_arr = (point*)malloc(n * sizeof(point));
    *complex_arr = (complex_struct*)malloc(m * sizeof(complex_struct));

    if (*double_arr == NULL || *string_arr == NULL || *point_arr == NULL || *complex_arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < n; i++) {
        (*double_arr)[i] = 0.0;
        (*string_arr)[i] = (char*)malloc((len + 1) * sizeof(char));
        if ((*string_arr)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }
        snprintf((*string_arr)[i], len + 1, "String%d", i);
        (*point_arr)[i].x = 0.0f;
        (*point_arr)[i].y = 0.0f;
    }

    // Initialize complex array
    srand(time(NULL));
    for (int i = 0; i < m; i++) {
        (*complex_arr)[i].value = min_val + (max_val - min_val) * ((double)rand() / RAND_MAX);
        snprintf((*complex_arr)[i].label, sizeof((*complex_arr)[i].label), "Label%d", i);
    }

    return NULL;
}

void free_memory(double* double_arr, char** string_arr, point* point_arr, complex_struct* complex_arr, int n, int m) {
