        free(string_arr[i]);
    }
    free(double_arr);
    free(string_arr);
    free(point_arr);
    free(complex_arr);
}

void log_memory_event(const char* event_type, size_t size) {
    // Log memory event using external logging library
    printf("%s: %zu bytes\n", event_type, size);
}

int main() {
    int n = 10;
    int m = 5;
    int len = 20;
    double min_val = -1.0;
    double max_val = 1.0;

    double* double_arr;
    char** string_arr;
    point* point_arr;
    complex_struct* complex_arr;

    allocate_and_initialize(&double_arr, &string_arr, &point_arr, &complex_arr, n, m, len, min_val, max_val);

    // Use the allocated arrays...

    free_memory(double_arr, string_arr, point_arr, complex_arr, n, m);

    return 0;
}
