        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &items);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if(response_code == 200) {
                // Process the received data and populate items array
            } else {
                fprintf(stderr, "API returned non-OK status code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();

    *out_count = batch_size; // Adjust based on actual number of items fetched
