#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_REPORTS 1000
#define MAX_ENTRIES 100
#define MIN_STATUS 1
#define MAX_STATUS 100

typedef struct {
    long timestamp;
    int status_code;
    char *description;
} report;

typedef struct {
    report *reports;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} report_pool;

void init_report_pool(report_pool *pool, size_t initial_capacity) {
    pool->reports = malloc(initial_capacity * sizeof(report));
    if (pool->reports == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->count = 0;
    pool->capacity = initial_capacity;
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_report_pool(report_pool *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->reports[i].description);
    }
    free(pool->reports);
    pthread_mutex_destroy(&pool->lock);
}

report* allocate_report(report_pool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == pool->capacity) {
        size_t new_capacity = pool->capacity ? pool->capacity * 2 : 1;
        report *new_reports = realloc(pool->reports, new_capacity * sizeof(report));
        if (new_reports == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        pool->reports = new_reports;
        pool->capacity = new_capacity;
    }
    pthread_mutex_unlock(&pool->lock);

    report *new_report = &pool->reports[pool->count++];
    new_report->timestamp = time(NULL);
    new_report->status_code = rand() % (MAX_STATUS - MIN_STATUS + 1) + MIN_STATUS;
    new_report->description = malloc(256); // Assuming a maximum description length of 255 characters
    if (new_report->description == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    snprintf(new_report->description, 256, "Status %d", new_report->status_code);

    return new_report;
}

void free_report(report *report) {
    free(report->description);
}

int main() {
    srand(time(NULL));
    report_pool pool;
    init_report_pool(&pool, MAX_REPORTS);

    // Example usage
    for (size_t i = 0; i < 5; ++i) {
        report *new_report = allocate_report(&pool);
        printf("Report %zu: Timestamp=%ld, Status=%d, Description=%s\n", i, new_report->timestamp, new_report->status_code, new_report->description);
    }

    destroy_report_pool(&pool);

    return 0;
}
