    array->keys = (int*)calloc(initial_capacity, sizeof(int));
    array->records = (record**)calloc(initial_capacity, sizeof(record*));
    if (!array->offsets || !array->keys || !array->records) {
        fprintf(stderr, "Memory allocation failed for dynamic array components\n");
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    array->db_connection = NULL;
    printf("Dynamic array initialized with capacity %zu\n", initial_capacity);
    return array;
}

void destroy_dynamic_array(dynamic_array *array) {
    if (array->offsets) free(array->offsets);
    if (array->keys) free(array->keys);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->records[i]) free(array->records[i]);
    }
    if (array->records) free(array->records);
    if (array->db_connection) fclose(array->db_connection);
    printf("Dynamic array destroyed\n");
    free(array);
}

void resize_dynamic_array(dynamic_array *array, size_t new_capacity) {
    long *new_offsets = (long*)realloc(array->offsets, new_capacity * sizeof(long));
    int *new_keys = (int*)realloc(array->keys, new_capacity * sizeof(int));
    record **new_records = (record**)realloc(array->records, new_capacity * sizeof(record*));
    if (!new_offsets || !new_keys || !new_records) {
        fprintf(stderr, "Memory reallocation failed for dynamic array components\n");
        return;
    }
    array->offsets = new_offsets;
    array->keys = new_keys;
    array->records = new_records;
    array->capacity = new_capacity;
    printf("Dynamic array resized to capacity %zu\n", new_capacity);
}

void add_record(dynamic_array *array, long offset, int key) {
    if (array->size >= array->capacity) {
        resize_dynamic_array(array, array->capacity * 2);
    }
    array->offsets[array->size] = offset;
    array->keys[array->size] = key;
    array->records[array->size] = (record*)malloc(sizeof(record));
    if (!array->records[array->size]) {
        fprintf(stderr, "Memory allocation failed for record\n");
        return;
    }
    array->records[array->size]->value = rand() % 100; // Random value between 0 and 99
    ++array->size;
}

void persist_to_database(dynamic_array *array) {
    if (!array->db_connection) {
        array->db_connection = fopen("database.db", "w");
        if (!array->db_connection) {
            fprintf(stderr, "Failed to open database connection\n");
            return;
        }
    }
    for (size_t i = 0; i < array->size; ++i) {
        fprintf(array->db_connection, "%ld %d %d\n", array->offsets[i], array->keys[i], array->records[i]->value);
    }
}

void verify_records(dynamic_array *array) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->offsets[i] < 0 || array->keys[i] < 0 || array->records[i]->value < 0) {
            fprintf(stderr, "Record at index %zu is invalid\n", i);
        }
    }
}

int main() {
    srand(time(NULL));
    dynamic_array *array = create_dynamic_array(10);
    if (!array) return 1;

    for (size_t i = 0; i < 20; ++i) {
        add_record(array, i * 100, i);
    }

    verify_records(array);
    persist_to_database(array);

    destroy_dynamic_array(array);
    return 0;
}
