#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    float value;
    char status;
} record;

typedef struct {
    record* records;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} dynamic_collection;

void init_collection(dynamic_collection* collection, size_t initial_capacity) {
    collection->records = (record*)malloc(initial_capacity * sizeof(record));
    if (!collection->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
}

void add_record(dynamic_collection* collection, record new_record) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        record* new_records = (record*)realloc(collection->records, new_capacity * sizeof(record));
        if (!new_records) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    collection->records[collection->count++] = new_record;
    pthread_mutex_unlock(&collection->lock);
}

void free_collection(dynamic_collection* collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->records);
    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;
    pthread_mutex_destroy(&collection->lock);
}

// Additional functions for fetching data from file and network API, handling discrepancies, etc.
