            users[i].emails[j] = (char*)malloc(50 * sizeof(char));
            snprintf(users[i].emails[j], 50, "email%d@domain.com", i * 3 + j);
        }

        pool.records[i] = (Record*)malloc(sizeof(Record));
        pool.records[i]->data.intValue = rand() % (maxRange - minRange + 1) + minRange;
