#include <pthread.h>
#include <semaphore.h>

#define MAX_RECORDS 50000
#define MAX_VALUE 1000

typedef struct {
    int value;
} Record;

Record* records[MAX_RECORDS];
sem_t semaphores[MAX_RECORDS];

int allocate_records() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            perror("Failed to allocate memory for record");
            return -1;
        }
        sem_init(&semaphores[i], 0, 1);
    }
    return 0;
}

void populate_records() {
    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i]->value = rand() % (MAX_VALUE + 1);
    }
}

void* thread_function(void* arg) {
    int index = *(int*)arg;
    sem_wait(&semaphores[index]);
    printf("Thread %d: Record value = %d\n", index, records[index]->value);
    sem_post(&semaphores[index]);
    return NULL;
}

int main() {
    if (allocate_records() != 0) {
        fprintf(stderr, "Failed to allocate records\n");
        return EXIT_FAILURE;
    }

    populate_records();

    pthread_t threads[MAX_RECORDS];
    int indices[MAX_RECORDS];

    for (int i = 0; i < MAX_RECORDS; i++) {
        indices[i] = i;
        if (pthread_create(&threads[i], NULL, thread_function, &indices[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        sem_destroy(&semaphores[i]);
        free(records[i]);
    }

    return EXIT_SUCCESS;
}
