#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int key;
    struct Node* next;
} Node;

Node* createNode(int key) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->key = key;
    newNode->next = NULL;
    return newNode;
}

void insertOrUpdateNode(Node** head, int key) {
    Node* current = *head;
    while (current != NULL) {
        if (current->key == key) {
            // Update existing node
            printf("Updating node with key %d\n", key);
            return;
        }
        if (current->next == NULL || current->next->key > key) {
            Node* newNode = createNode(key);
            newNode->next = current->next;
            current->next = newNode;
            return;
        }
        current = current->next;
    }
    // Insert at the end
    Node* newNode = createNode(key);
    if (*head == NULL) {
        *head = newNode;
    } else {
        current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

void printList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%d -> ", current->key);
        current = current->next;
    }
    printf("NULL\n");
}

int main() {
    Node* head = NULL;

    insertOrUpdateNode(&head, 5);
    insertOrUpdateNode(&head, 3);
    insertOrUpdateNode(&head, 7);
    insertOrUpdateNode(&head, 4);
    insertOrUpdateNode(&head, 2);

    printList(head);

    return 0;
}
