#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    int key;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

Node* create_node(int key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->key = key;
    new_node->next = NULL;
    return new_node;
}

void insert(LinkedList* list, int key) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->key < key) {
        previous = current;
        current = current->next;
    }

    if (current != NULL && current->key == key) {
        // Update existing node
        free(current);
        current = create_node(key);
        if (previous == NULL) {
            list->head = current;
        } else {
            previous->next = current;
        }
    } else {
        Node* new_node = create_node(key);
        if (previous == NULL) {
            new_node->next = list->head;
            list->head = new_node;
        } else {
            new_node->next = current;
            previous->next = new_node;
        }
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_node(LinkedList* list, int key) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->key < key) {
        previous = current;
        current = current->next;
    }

    if (current != NULL && current->key == key) {
        if (previous == NULL) {
            list->head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current);
    }

    pthread_mutex_unlock(&list->lock);
}

void traverse(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;

    while (current != NULL) {
        printf("%d ", current->key);
        current = current->next;
    }
    printf("\n");

    pthread_mutex_unlock(&list->lock);
}

void check_integrity(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    int prev_key = -1;

    while (current != NULL) {
        if (current->key <= prev_key) {
            printf("Integrity check failed: Duplicate or out-of-order key found\n");
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev_key = current->key;
        current = current->next;
    }

    printf("Integrity check passed: List is in order and contains unique keys\n");

    pthread_mutex_unlock(&list->lock);
}

int main() {
    LinkedList list;
    pthread_mutex_init(&list.lock, NULL);
    list.head = NULL;

    insert(&list, 5);
    insert(&list, 3);
    insert(&list, 7);
    traverse(&list);

    remove_node(&list, 3);
    traverse(&list);

    check_integrity(&list);

    pthread_mutex_destroy(&list.lock);
    return 0;
}
