#include <time.h>

typedef struct {
    int value;
} record;

void manage_resources(long *offsets, int *keys, record **records, long budget, int range_start, int range_end) {
    srand(time(NULL));
    for (int i = 0; i < budget / sizeof(record); i++) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 1000;
        records[i] = malloc(sizeof(record));
        if (records[i]) {
            records[i]->value = rand() % range_end + range_start;
        } else {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
    }
}

int main() {
    long budget = 1024 * sizeof(record); // Example budget
    int range_start = 0;
    int range_end = 100;

    long *offsets = malloc(budget);
    int *keys = malloc(budget);
    record **records = malloc(budget / sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    manage_resources(offsets, keys, records, budget, range_start, range_end);

    // Free allocated memory
    for (int i = 0; i < budget / sizeof(record); i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
