#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef enum {
    ACTIVE,
    INACTIVE,
    EXPIRED
} Status;

typedef struct entry {
    time_t timestamp;
    Status status;
    struct entry *prev, *next;
} Entry;

typedef struct {
    Entry *head, *tail;
    size_t count;
} LinkedList;

void initList(LinkedList *list) {
    list->head = list->tail = NULL;
    list->count = 0;
}

Entry* createEntry(time_t timestamp, Status status) {
    Entry *newEntry = (Entry*)malloc(sizeof(Entry));
    newEntry->timestamp = timestamp;
    newEntry->status = status;
    newEntry->prev = newEntry->next = NULL;
    return newEntry;
}

void insertEntry(LinkedList *list, time_t timestamp, Status status) {
    Entry *newEntry = createEntry(timestamp, status);
    if (list->head == NULL) {
        list->head = list->tail = newEntry;
    } else {
        Entry *current = list->head;
        while (current != NULL && current->timestamp < timestamp) {
            current = current->next;
        }
        if (current == NULL) {
            list->tail->next = newEntry;
            newEntry->prev = list->tail;
            list->tail = newEntry;
        } else if (current->timestamp == timestamp) {
            current->status = status;
            free(newEntry);
        } else {
            newEntry->next = current;
            newEntry->prev = current->prev;
            if (current->prev != NULL) {
                current->prev->next = newEntry;
            } else {
                list->head = newEntry;
            }
            current->prev = newEntry;
        }
    }
    list->count++;
}

void printList(LinkedList *list) {
    Entry *current = list->head;
    while (current != NULL) {
        printf("Timestamp: %ld, Status: %d\n", current->timestamp, current->status);
        current = current->next;
    }
}

Entry* findEntryByTimestamp(LinkedList *list, time_t timestamp) {
    Entry *current = list->head;
    while (current != NULL && current->timestamp < timestamp) {
        current = current->next;
    }
    if (current != NULL && current->timestamp == timestamp) {
        return current;
    }
    return NULL;
}

void freeList(LinkedList *list) {
    Entry *current = list->head;
    while (current != NULL) {
        Entry *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = list->tail = NULL;
    list->count = 0;
}
