        // Implement logic to read integers from standard input and print the largest one
    }

    private static void calculateDisjointPairs(Record[] records) {
        UnionFind unionFind = new UnionFind(MAX_KEYS);
        long startTime, endTime;
        for (int i = 0; i < MAX_KEYS - 1; i++) {
            startTime = System.currentTimeMillis();
            boolean disjoint = unionFind.find(records[i].getKey()) != unionFind.find(records[i + 1].getKey());
            endTime = System.currentTimeMillis();
            System.out.println("Disjoint check between " + records[i].getKey() + " and " + records[i + 1].getKey() + ": " + (disjoint ? "Yes" : "No") + " (" + (endTime - startTime) + " ms)");
        }
    }

    private static void deleteDirectory(File dir) {
        File[] files = dir.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    deleteDirectory(file);
                } else {
                    file.delete();
                }
            }
        }
        dir.delete();
    }

