import io.netty.channel.*;
import io.netty.buffer.*;

public class DataProcessor {
    private static final int MAX_KEYS = 10000;
    private static final int MAX_OFFSETS = 10000;

    public static void main(String[] args) throws Exception {
        // Initialize data structures
        int[] keys = new int[MAX_KEYS];
        long[] offsets = new long[MAX_OFFSETS];
        Record[] records = new Record[MAX_KEYS];

        // Populate records with random values
        populateRecords(records);

        // Find and print the largest integer in the array
        findAndPrintLargestInteger(records);

        // Calculate disjoint pairs using Union-Find
        calculateDisjointPairs(keys);
    }

    private static void populateRecords(Record[] records) {
        Random rand = new Random();
        Set<Integer> keySet = new HashSet<>();
        while (keySet.size() < MAX_KEYS) {
            int key = rand.nextInt(MAX_KEYS * 10);
            if (!keySet.contains(key)) {
                keySet.add(key);
                records[key] = new Record(key, rand.nextLong());
            }
        }
    }

    private static void findAndPrintLargestInteger(Record[] records) {
        OptionalInt maxKey = Arrays.stream(records)
                                   .mapToInt(record -> record.getKey())
                                   .max();
        if (maxKey.isPresent()) {
            System.out.println("Largest integer: " + maxKey.getAsInt());
        }
    }

    private static void calculateDisjointPairs(int[] keys) throws Exception {
        UnionFind uf = new UnionFind(keys.length);
        long startTime, endTime;
        for (int i = 0; i < keys.length - 1; i++) {
            startTime = System.currentTimeMillis();
            boolean disjoint = uf.find(keys[i]) != uf.find(keys[i + 1]);
            endTime = System.currentTimeMillis();
            System.out.println("Disjoint pair check between " + keys[i] + " and " + keys[i + 1] + ": " + (disjoint ? "Yes" : "No") + " (" + (endTime - startTime) + " ms)");
        }
    }

    static class Record {
        private int key;
        private long offset;

        public Record(int key, long offset) {
            this.key = key;
            this.offset = offset;
        }

        public int getKey() {
            return key;
        }

        public long getOffset() {
            return offset;
        }
    }

    static class UnionFind {
        private int[] parent;

        public UnionFind(int size) {
            parent = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX != rootY) {
                parent[rootX] = rootY;
            }
        }
    }
}
