#include <stdio.h>
#include <stdlib.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 5000

typedef struct {
    long offset;
    int key;
    int value;
} SemaphoreRecord;

SemaphoreRecord* semaphore_records[MAX_SEMAPHORES];
sem_t* semaphores[MAX_SEMAPHORES];

int create_semaphore(int index, long offset, int key, int initial_value) {
    if (index < 0 || index >= MAX_SEMAPHORES) return -1;

    semaphore_records[index] = (SemaphoreRecord*)malloc(sizeof(SemaphoreRecord));
    if (!semaphore_records[index]) return -1;

    semaphore_records[index]->offset = offset;
    semaphore_records[index]->key = key;
    semaphore_records[index]->value = initial_value;

    semaphores[index] = sem_open("/semaphore_key", O_CREAT, 0644, initial_value);
    if (semaphores[index] == SEM_FAILED) {
        free(semaphore_records[index]);
        return -1;
    }

    return 0;
}

int delete_semaphore(int index) {
    if (index < 0 || index >= MAX_SEMAPHORES) return -1;

    sem_close(semaphores[index]);
    sem_unlink("/semaphore_key");

    free(semaphore_records[index]);
    semaphore_records[index] = NULL;
    semaphores[index] = NULL;

    return 0;
}

int acquire_semaphore(int index) {
    if (index < 0 || index >= MAX_SEMAPHORES) return -1;

    return sem_wait(semaphores[index]);
}

int release_semaphore(int index) {
    if (index < 0 || index >= MAX_SEMAPHORES) return -1;

    return sem_post(semaphores[index]);
}
