typedef struct record {
    int value;
    char* str_value;
} Record;

typedef struct node {
    Record data;
    struct node* next;
} Node;

Node* create_node(int value, const char* str_value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        // Handle allocation failure
        return NULL;
    }
    new_node->data.value = value;
    new_node->data.str_value = strdup(str_value);
    new_node->next = NULL;
    return new_node;
}

void free_record(Record* record) {
    free(record->str_value);
}

void free_node(Node* node) {
    if (node) {
        free_record(&node->data);
        free(node);
    }
}

Node* create_linked_list(int count, int range_start, int range_end) {
    Node* head = NULL;
    Node** current = &head;

    for (int i = 0; i < count; ++i) {
        int value = rand() % (range_end - range_start + 1) + range_start;
        char str_value[20];
        snprintf(str_value, sizeof(str_value), "%d", value);

        Node* new_node = create_node(value, str_value);
        if (!new_node) {
            // Handle allocation failure
            free_linked_list(head);
            return NULL;
        }

        *current = new_node;
        current = &(*current)->next;
    }

    return head;
}

void free_linked_list(Node* head) {
    Node* temp;
    while (head) {
        temp = head;
        head = head->next;
        free_node(temp);
    }
}

int main() {
    srand(time(NULL));

    int count = 10;
    int range_start = 1;
    int range_end = 100;

    Node* list = create_linked_list(count, range_start, range_end);

