        // Process the linked list
        Node* current = list;
        while (current) {
            printf("Value: %d, String Value: %s\n", current->data.value, current->data.str_value);
            current = current->next;
        }

        free_linked_list(list);
    } else {
        // Handle allocation failure
        fprintf(stderr, "Failed to allocate memory for linked list.\n");
    }

    return 0;
}
