Record** create_and_initialize_records(int size_limit, int key_range_start, int key_range_end, int* external_keys, int external_key_count, int* num_initialized) {
    if (size_limit <= 0 || key_range_end < key_range_start) {
        *num_initialized = 0;
        return NULL;
    }

    Record** records = (Record**)malloc(size_limit * sizeof(Record*));
    if (!records) {
        *num_initialized = 0;
        return NULL;
    }

    int* keys = (int*)calloc(key_range_end - key_range_start + 1, sizeof(int));
    if (!keys) {
        free(records);
        *num_initialized = 0;
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < external_key_count; ++i) {
        int key = external_keys[i];
        if (key >= key_range_start && key <= key_range_end) {
            keys[key - key_range_start] = 1;
        }
    }

    *num_initialized = 0;

    for (int i = 0; i < size_limit && *num_initialized < size_limit; ++i) {
        int key;
        do {
            key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        } while (keys[key - key_range_start]);

        keys[key - key_range_start] = 1;

        records[*num_initialized] = (Record*)malloc(sizeof(Record));
        if (!records[*num_initialized]) {
            break;
        }

        records[*num_initialized]->value = key;
        records[*num_initialized]->offset = (long*)malloc(sizeof(long));
        if (!records[*num_initialized]->offset) {
            free(records[*num_initialized]);
            break;
        }
        *records[*num_initialized]->offset = i;

        (*num_initialized)++;
    }

    for (int i = 0; i < key_range_end - key_range_start + 1; ++i) {
        if (keys[i]) {
            keys[i] = 0;
        }
    }

    free(keys);

    return records;
}

void free_records(Record** records, int size_limit) {
    for (int i = 0; i < size_limit; ++i) {
        if (records[i]) {
            free(records[i]->offset);
            free(records[i]);
        }
    }
    free(records);
}
