    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* generate_records(int numRecords, int minValue, int maxValue, unsigned int seed) {
    record* records = allocate_memory(numRecords * sizeof(record));
    srand(seed);

    for (int i = 0; i < numRecords; ++i) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }

    return records;
}

long* create_offsets(int numOffsets) {
    long* offsets = allocate_memory(numOffsets * sizeof(long));
    for (int i = 0; i < numOffsets; ++i) {
        offsets[i] = 0;
    }
    return offsets;
}

int* create_keys(int numKeys) {
    int* keys = allocate_memory(numKeys * sizeof(int));
    for (int i = 0; i < numKeys; ++i) {
        keys[i] = 0;
    }
    return keys;
}

void* allocate_resources(int numOffsets, int numKeys, int numRecords, int minValue, int maxValue, unsigned int seed) {
    size_t total_size = numOffsets * sizeof(long) + numKeys * sizeof(int) + numRecords * sizeof(record);
    if (total_size > MAX_MEMORY) {
        fprintf(stderr, "Total memory required exceeds the limit\n");
        return NULL;
    }

    long* offsets = create_offsets(numOffsets);
    int* keys = create_keys(numKeys);
    record* records = generate_records(numRecords, minValue, maxValue, seed);

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

