#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct EventRecord {
    int key;
    char* log_message;
    time_t timestamp;
    struct EventRecord* next;
} EventRecord;

typedef struct EventList {
    EventRecord* head;
    pthread_mutex_t lock;
} EventList;

void init_event_list(EventList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void add_event_record(EventList* list, int key, const char* log_message) {
    pthread_mutex_lock(&list->lock);
    EventRecord* new_record = (EventRecord*)malloc(sizeof(EventRecord));
    if (new_record == NULL) {
        // Log allocation failure
        return;
    }
    new_record->key = key;
    new_record->log_message = strdup(log_message);
    new_record->timestamp = time(NULL);
    new_record->next = list->head;
    list->head = new_record;
    pthread_mutex_unlock(&list->lock);
}

void remove_old_records(EventList* list, time_t threshold) {
    pthread_mutex_lock(&list->lock);
    EventRecord* current = list->head;
    EventRecord* prev = NULL;
    while (current != NULL) {
        if (difftime(time(NULL), current->timestamp) > threshold) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->log_message);
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void cleanup_event_list(EventList* list) {
    pthread_mutex_lock(&list->lock);
    EventRecord* current = list->head;
    while (current != NULL) {
        EventRecord* next = current->next;
        free(current->log_message);
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int main() {
    EventList event_list;
    init_event_list(&event_list);

    add_event_record(&event_list, 1, "Event 1");
    add_event_record(&event_list, 2, "Event 2");

    remove_old_records(&event_list, 3600); // Remove records older than 1 hour

    cleanup_event_list(&event_list);

    return 0;
}
