#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define BUFFER_SIZE 256

typedef struct Record {
    int value;
    char *buffer;
    struct Record *next;
} Record;

typedef struct LinkedList {
    Record *head;
    pthread_mutex_t lock;
} LinkedList;

void initialize_records(LinkedList *list, int max_size, int batch_size, FILE *log_file, int enable_logging) {
    srand(time(NULL));
    for (int i = 0; i < max_size; i += batch_size) {
        pthread_mutex_lock(&list->lock);
        Record *current = list->head;
        for (int j = 0; j < batch_size && current != NULL; ++j, current = current->next) {
            if (enable_logging) {
                fprintf(log_file, "Allocating record %d\n", i + j);
            }
            current->value = rand() % max_size;
            for (int k = 0; k < BUFFER_SIZE - 1; ++k) {
                current->buffer[k] = 'a' + rand() % 26;
            }
            current->buffer[BUFFER_SIZE - 1] = '\0';
        }
        pthread_mutex_unlock(&list->lock);
    }
}

void print_records(LinkedList *list) {
    Record *current = list->head;
    while (current != NULL) {
        printf("Value: %d, Buffer: %s\n", current->value, current->buffer);
        current = current->next;
    }
}

void free_records(LinkedList *list) {
    Record *current = list->head;
    while (current != NULL) {
        Record *temp = current;
        current = current->next;
        free(temp->buffer);
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}

int main() {
    LinkedList list;
    list.head = (Record *)malloc(MAX_RECORDS * sizeof(Record));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        list.head[i].buffer = (char *)malloc(BUFFER_SIZE * sizeof(char));
        list.head[i].next = (i == MAX_RECORDS - 1) ? NULL : &list.head[i + 1];
    }
    pthread_mutex_init(&list.lock, NULL);

    FILE *log_file = fopen("allocation_log.txt", "a");
    initialize_records(&list, MAX_RECORDS, 100, log_file, 1);
    print_records(&list);
    free_records(&list);
    fclose(log_file);

    return 0;
}
