    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Read the number of records
    fscanf(file, "%d", num_records);

    // Allocate memory for arrays
    long* offsets = (long*)malloc(*num_records * sizeof(long));
    int* keys = (int*)malloc(*num_records * sizeof(int));
    record* records = (record*)malloc(*num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        fclose(file);
        free(offsets);
        free(keys);
        return NULL;
    }

    // Read the data from file
    for (int i = 0; i < *num_records; ++i) {
        fscanf(file, "%ld,%d,%d", &offsets[i], &keys[i], &records[i].value);
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    fclose(file);
    free(offsets);
    free(keys);

    return records;
}

void update_records(record* records, int num_records, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void free_records(record* records, int num_records) {
    free(records);
}

int main() {
    const char* filename = "data.csv";
    int num_records;

    record* records = read_and_init_records(filename, &num_records);
    if (!records) {
        return 1;
    }

    update_records(records, num_records, 10, 100);

    // Process the records...

    free_records(records, num_records);

    return 0;
}
