typedef struct {
    int priority;
    int sender_id;
    char payload[256];
} message;

message queue[MAX_MESSAGES];
int front = -1, rear = -1;
pthread_mutex_t mutex;
sem_t empty, full;

void init_queue() {
    pthread_mutex_init(&mutex, NULL);
    sem_init(&empty, 0, MAX_MESSAGES);
    sem_init(&full, 0, 0);
}

void enqueue(message msg) {
    sem_wait(&empty);
    pthread_mutex_lock(&mutex);
    if (front == -1)
        front = rear = 0;
    else
        rear = (rear + 1) % MAX_MESSAGES;
    queue[rear] = msg;
    pthread_mutex_unlock(&mutex);
    sem_post(&full);
}

message dequeue() {
    message msg;
    sem_wait(&full);
    pthread_mutex_lock(&mutex);
    msg = queue[front];
    if (front == rear)
        front = rear = -1;
    else
        front = (front + 1) % MAX_MESSAGES;
    pthread_mutex_unlock(&mutex);
    sem_post(&empty);
    return msg;
}

