#include <pthread.h>

typedef struct {
    long offset;
    int key;
} record;

typedef struct node {
    record data;
    struct node* next;
} node;

typedef struct {
    node* head;
    size_t count;
    pthread_mutex_t lock;
} concurrent_array;

concurrent_array* create_concurrent_array() {
    concurrent_array* array = (concurrent_array*)malloc(sizeof(concurrent_array));
    if (!array) return NULL;
    array->head = NULL;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_concurrent_array(concurrent_array* array) {
    node* current = array->head;
    while (current) {
        node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int insert_record(concurrent_array* array, long offset, int key) {
    pthread_mutex_lock(&array->lock);
    node* new_node = (node*)malloc(sizeof(node));
    if (!new_node) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Out of memory
    }
    new_node->data.offset = offset;
    new_node->data.key = key;
    new_node->next = array->head;
    array->head = new_node;
    array->count++;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void update_keys(concurrent_array* array, int (*transform)(int)) {
    pthread_mutex_lock(&array->lock);
    node* current = array->head;
    while (current) {
        current->data.key = transform(current->data.key);
        current = current->next;
    }
    pthread_mutex_unlock(&array->lock);
}

void iterate_and_update(concurrent_array* array, int (*transform)(int)) {
    update_keys(array, transform);
}
