#define PRIME_NUMBER 103
#define SQUARE_NUMBER 25
#define FIBONACCI_NUMBER 34

typedef struct {
    int value;
} record;

int is_prime(int num) {
    if (num <= 1) return 0;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) return 0;
    }
    return 1;
}

int is_perfect_square(int num) {
    int root = sqrt(num);
    return root * root == num;
}

int is_fibonacci(int num) {
    int a = 0, b = 1;
    if (num == a || num == b) return 1;
    int c = a + b;
    while (c <= num) {
        if (c == num) return 1;
        a = b;
        b = c;
        c = a + b;
    }
    return 0;
}

long* allocate_offsets() {
    long* offsets = (long*)malloc(PRIME_NUMBER * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        exit(1);
    }
    // Initialize offsets
    for (int i = 0; i < PRIME_NUMBER; i++) {
        offsets[i] = rand() % 1000;
    }
    return offsets;
}

int* allocate_keys() {
    int* keys = (int*)malloc(SQUARE_NUMBER * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        exit(1);
    }
    // Initialize keys
    for (int i = 0; i < SQUARE_NUMBER; i++) {
        keys[i] = i;
    }
    return keys;
}

record* allocate_records() {
    record* records = (record*)malloc(FIBONACCI_NUMBER * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records\n");
        exit(1);
    }
    // Initialize records with random values
    srand(time(NULL));
    int prev_value = rand() % 100;
    for (int i = 0; i < FIBONACCI_NUMBER; i++) {
        int value;
        do {
            value = rand() % 100;
        } while (value == prev_value);
        records[i].value = value;
        prev_value = value;
    }
    return records;
}

void free_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long* offsets = allocate_offsets();
    int* keys = allocate_keys();
    record* records = allocate_records();

    // Use the allocated memory here

    free_memory(offsets, keys, records);

    return 0;
}
