#define MAX_RECORDS 10000000
#define MAX_STRING_LENGTH 64

typedef struct {
    int key;
    short field;
    char* value;
} Record;

Record* InitializeRecordsAndWebsites(int num_records, int min_value, int max_value, const char* default_string) {
    FILE* config_file = fopen("web.config", "r");
    if (config_file == NULL) {
        return NULL;
    }
    fclose(config_file);

    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (records == NULL) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ) {
        int key = rand() % (max_value - min_value + 1) + min_value;
        int is_duplicate = 0;

        // Check for duplicate keys
        for (int j = 0; j < i; j++) {
            if (records[j].key == key) {
                is_duplicate = 1;
                break;
            }
        }

        if (!is_duplicate) {
            records[i].key = key;
            records[i].field = rand() % SHRT_MAX;
            records[i].value = (char*)malloc(MAX_STRING_LENGTH * sizeof(char));
            if (records[i].value == NULL) {
                for (int j = 0; j < i; j++) {
                    free(records[j].value);
                }
                free(records);
                return NULL;
            }
            strncpy(records[i].value, default_string, MAX_STRING_LENGTH - 1);
            records[i].value[MAX_STRING_LENGTH - 1] = '\0';
            i++;
        }
    }

    return records;
}

void FreeRecords(Record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(records[i].value);
    }
    free(records);
}
