char* InitializeDirectoryEnvironment(const char* parent_dir, const char* config_file) {
    pthread_mutex_lock(&records_lock);
    if (record_count >= MAX_RECORDS) {
        pthread_mutex_unlock(&records_lock);
        return NULL;
    }
    Record* new_record = &records[record_count++];
    pthread_mutex_unlock(&records_lock);

    // Check if environment variable is already set
    char* env_var_value = getenv("MY_DIR_ENV");
    if (env_var_value != NULL) {
        return strdup(env_var_value);
    }

    // Create a unique directory name
    char dir_name[256];
    snprintf(dir_name, sizeof(dir_name), "%s/my_dir_%d", parent_dir, getpid());

    // Check if the directory already exists
    DIR* dir = opendir(dir_name);
    if (dir != NULL) {
        closedir(dir);
        return NULL;
    }

    // Create the new directory
    if (mkdir(dir_name, 0755) != 0) {
        return NULL;
    }

    // Set the environment variable
    setenv("MY_DIR_ENV", dir_name, 1);

    // Check for config.properties file
    char config_path[256];
    snprintf(config_path, sizeof(config_path), "%s/config.properties", dir_name);
    FILE* config_file_handle = fopen(config_path, "r");
    if (config_file_handle == NULL) {
        rmdir(dir_name);
        unsetenv("MY_DIR_ENV");
        return NULL;
    }
    fclose(config_file_handle);

    // Populate records with random values
    pthread_mutex_lock(&records_lock);
    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % 1000;
    }
    pthread_mutex_unlock(&records_lock);

    return strdup(dir_name);
}
