import threading
import time
import random
import logging
from typing import Union

# Define a union type for record values
RecordValue = Union[int, float, double, str]

class Record:
    def __init__(self, value: RecordValue):
        self.value = value

class ConnectionPool:
    def __init__(self, max_connections: int):
        self.max_connections = max_connections
        self.connections = []

    def get_connection(self):
        if len(self.connections) < self.max_connections:
            return True
        return False

    def release_connection(self):
        pass

class RecordArray:
    def __init__(self, size: int):
        self.records = [Record(0) for _ in range(size)]

    def get_record(self, index: int):
        return self.records[index]

    def set_record(self, index: int, value: RecordValue):
        self.records[index].value = value

def dataHandler(num_records: int, min_value: int, max_value: int, memory_size: int) -> None:
    logging.basicConfig(level=logging.DEBUG)
    logger = logging.getLogger(__name__)

    if num_records <= 0 or min_value > max_value or memory_size <= 0:
        raise ValueError("Invalid input parameters")

    connection_pool = ConnectionPool(num_records)
    record_array = RecordArray(num_records)

    def worker(record_index: int):
        while True:
            if connection_pool.get_connection():
                try:
                    # Simulate database operation
                    time.sleep(random.uniform(0.1, 0.5))
                    record_value = random.randint(min_value, max_value)
                    record_array.set_record(record_index, record_value)
                finally:
                    connection_pool.release_connection()

    threads = []
    for i in range(num_records):
        thread = threading.Thread(target=worker, args=(i,))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

# Example usage
dataHandler(10, 1, 100, 1024 * 1024)  # Initialize with 10 records, values between 1 and 100, and 1MB memory size
