import threading
from datetime import datetime

class ConnectionEntry:
    def __init__(self, connection_id, db_connection, query_history, timestamp, metadata):
        self.connection_id = connection_id
        self.db_connection = db_connection
        self.query_history = query_history
        self.timestamp = timestamp
        self.metadata = metadata

def databaseConnectionManager():
    # Initialize connection pool and other necessary structures
    connection_pool = []
    lock = threading.Lock()

    def allocate_connection(query):
        with lock:
            for entry in connection_pool:
                if not entry.query_history or (entry.query_history[-1] != query and datetime.now() - entry.timestamp > timedelta(seconds=60)):
                    entry.query_history.append(query)
                    entry.timestamp = datetime.now()
                    return entry
            new_entry = ConnectionEntry(len(connection_pool), None, [query], datetime.now(), {})
            connection_pool.append(new_entry)
            return new_entry

    def find_earliest_latest():
        with lock:
            if not connection_pool:
                return None, None
            earliest = min(connection_pool, key=lambda x: x.timestamp)
            latest = max(connection_pool, key=lambda x: x.timestamp)
            return earliest, latest

    # Example usage
    query = "SELECT * FROM users"
    entry = allocate_connection(query)
    print(f"Allocated connection for query: {query}, Connection ID: {entry.connection_id}")

    earliest, latest = find_earliest_latest()
    if earliest and latest:
        print(f"Earliest connection timestamp: {earliest.timestamp}, Latest connection timestamp: {latest.timestamp}")
