typedef struct record {
    long offset;
    int key;
    double value;
} Record;

Record** allocate_records(int num_records, int key_start, int key_end, unsigned int seed) {
    if (num_records <= 0 || key_start >= key_end) {
        return NULL;
    }

    Record** records = (Record**)malloc(num_records * sizeof(Record*));
    if (!records) {
        return NULL;
    }

    srand(seed);
    for (int i = 0; i < num_records; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->offset = i;
        records[i]->key = key_start + rand() % (key_end - key_start);
        records[i]->value = ((double)rand()) / RAND_MAX;
    }

    return records;
}

void free_records(Record** records, int num_records) {
    if (!records) {
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        free(records[i]);
    }
    free(records);
}

int main() {
    int num_records = 1000;
    int key_start = 1;
    int key_end = 100;
    unsigned int seed = time(NULL);

    Record** records = allocate_records(num_records, key_start, key_end, seed);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Use the records...

    free_records(records, num_records);

    return EXIT_SUCCESS;
}
