void populateRecords(Record **records, long *offsets, int numRecords, int keySize) {
    if (numRecords > keySize) {
        fprintf(stderr, "Error: Number of records exceeds the size of the key array.\n");
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        (*records)[i].value = rand() % 1000 + 1; // Random value between 1 and 1000
        offsets[i] = i * sizeof(Record); // Assuming each record is of size Record
    }
}

int main() {
    int numRecords, keySize;
    printf("Enter the number of records: ");
    scanf("%d", &numRecords);
    printf("Enter the size of the key array: ");
    scanf("%d", &keySize);

    if (numRecords <= 0 || keySize <= 0) {
        fprintf(stderr, "Error: Invalid input. Number of records and key size must be positive.\n");
        return 1;
    }

    Record *records = malloc(numRecords * sizeof(Record));
    long *offsets = malloc(keySize * sizeof(long));

    if (records == NULL || offsets == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(records);
        free(offsets);
        return 1;
    }

    populateRecords(&records, offsets, numRecords, keySize);

    // Print records and offsets for verification
    printf("Records:\n");
    for (int i = 0; i < numRecords; i++) {
        printf("Record %d: Value = %d\n", i, records[i].value);
