typedef struct {
    int value;
} record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void initialize_arrays(long** offsets, int** keys, record** records, int** input_values, int** unique_ids, size_t size) {
    *offsets = safe_malloc(size * sizeof(long));
    *keys = safe_malloc(size * sizeof(int));
    *records = safe_malloc(size * sizeof(record));
    *input_values = safe_malloc(size * sizeof(int));
    *unique_ids = safe_malloc(size * sizeof(int));

    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = i * 10;
        (*records)[i].value = rand() % 100;
    }
}

void populate_arrays(int** keys, int** input_values, int** unique_ids, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        scanf("%d", &(*keys)[i]);
        (*input_values)[i] = (*keys)[i];
        (*unique_ids)[i] = rand() % 1000;
    }
}

void free_arrays(long* offsets, int* keys, record* records, int* input_values, int* unique_ids) {
    free(offsets);
    free(keys);
    free(records);
    free(input_values);
    free(unique_ids);
}

int find(int* parent, int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void union_set(int* parent, int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset)
        parent[xset] = yset;
}

int count_disjoint_pairs(int* keys, size_t size) {
    int* parent = safe_malloc(size * sizeof(int));
    for (size_t i = 0; i < size; ++i)
        parent[i] = -1;

    clock_t start, end;
    double cpu_time_used;

    for (size_t i = 0; i < size; ++i) {
        for (size_t j = i + 1; j < size; ++j) {
            if (keys[i] != keys[j]) {
                start = clock();
                union_set(parent, i, j);
                end = clock();
                cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
                printf("Disjoint pair (%d, %d) took %.3f ms\n", keys[i], keys[j], cpu_time_used * 1000);
            }
        }
    }

    int disjoint_pairs = 0;
    for (size_t i = 0; i < size; ++i)
        if (parent[i] == -1)
            disjoint_pairs++;

    free(parent);
    return disjoint_pairs;
}

int main() {
    srand(time(NULL));
    size_t size = 5;

    long* offsets;
    int* keys;
    record* records;
    int* input_values;
    int* unique_ids;

    initialize_arrays(&offsets, &keys, &records, &input_values, &unique_ids, size);
    populate_arrays(&keys, &input_values, &unique_ids, size);

    printf("Number of disjoint pairs: %d\n", count_disjoint_pairs(keys, size));

    free_arrays(offsets, keys, records, input_values, unique_ids);

    return 0;
}
