    Record* records = (Record*)malloc(size * sizeof(Record));
    if (records == NULL) {
        *error_code = -2; // Error: Memory allocation failed
        return NULL;
    }

    *error_code = 0; // Success
    return records;
}

void initialize_records(Record* records, int size, int* error_code) {
    if (records == NULL || size <= 0) {
        *error_code = -1; // Error: Invalid input
        return;
    }

    for (int i = 0; i < size; i++) {
        records[i].offset = i * sizeof(Record);
        records[i].key = i;
        records[i].value = (float)i / 2.0f;
    }

    *error_code = 0; // Success
}

void free_records(Record* records) {
    if (records != NULL) {
        free(records);
    }
}

int main() {
    int size = 1000000; // Example size
    int error_code;

    Record* records = create_records(size, &error_code);
    if (error_code != 0) {
        printf("Error creating records: %d\n", error_code);
        return 1;
    }

    initialize_records(records, size, &error_code);
    if (error_code != 0) {
        printf("Error initializing records: %d\n", error_code);
        free_records(records);
        return 1;
    }

    // Use the records...

