#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NODES 1000

typedef struct entry {
    double value;
    char *str;
    char ch;
    struct node *ptr;
} Entry;

typedef struct node {
    int key;
    struct node *left, *right;
} Node;

Node* newNode(int item) {
    Node *temp = (Node *)malloc(sizeof(Node));
    if (!temp) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    temp->key = item;
    temp->left = temp->right = NULL;
    return temp;
}

void insert(Node **root_ref, int key) {
    Node *new_node = newNode(key);
    if (*root_ref == NULL) {
        *root_ref = new_node;
        return;
    }
    Node *current = *root_ref;
    while (1) {
        if (key < current->key) {
            if (current->left == NULL) {
                current->left = new_node;
                break;
            } else {
                current = current->left;
            }
        } else if (key > current->key) {
            if (current->right == NULL) {
                current->right = new_node;
                break;
            } else {
                current = current->right;
            }
        } else {
            fprintf(stderr, "Duplicate key not allowed\n");
            free(new_node);
            return;
        }
    }
}

void inOrder(Node *root) {
    if (root != NULL) {
        inOrder(root->left);
        printf("%c ", root->key);
        inOrder(root->right);
    }
}

void freeTree(Node *node) {
    if (node == NULL)
        return;
    freeTree(node->left);
    freeTree(node->right);
    free(node);
}

int main() {
    long offsets[MAX_NODES];
    int keys[MAX_NODES];
    double values[MAX_NODES];
    Entry entries[MAX_NODES];
    Node *root = NULL;

    // Read input and populate arrays
    for (int i = 0; i < MAX_NODES; i++) {
        scanf("%ld %d %lf", &offsets[i], &keys[i], &values[i]);
        entries[i].value = values[i];
        entries[i].str = NULL;
        entries[i].ch = 'A' + i % 26;
        entries[i].ptr = NULL;
        insert(&root, keys[i]);
    }

    // Perform in-order traversal
    printf("In-order traversal: ");
    inOrder(root);
    printf("\n");

    // Free allocated memory
    freeTree(root);

    return 0;
}
