#define NUM_SENSORS 100
#define MAX_IDENTIFIER_LENGTH 20

typedef struct {
    float x;
    float y;
} point;

typedef struct {
    time_t timestamp;
    double reading;
    char* identifier;
} sensor_data;

sensor_data* initialize_sensor_data(int num_sensors) {
    sensor_data* data = (sensor_data*)malloc(num_sensors * sizeof(sensor_data));
    if (!data) return NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_sensors; i++) {
        data[i].timestamp = time(NULL);
        data[i].reading = ((double)rand() / RAND_MAX) * 100.0 - 50.0; // Random value between -50 and 50
        data[i].identifier = (char*)malloc(MAX_IDENTIFIER_LENGTH * sizeof(char));
        if (!data[i].identifier) {
            for (int j = 0; j < i; j++) free(data[j].identifier);
            free(data);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        snprintf(data[i].identifier, MAX_IDENTIFIER_LENGTH, "sensor%d", i);
    }

    pthread_mutex_unlock(&mutex);
    return data;
}

void cleanup_sensor_data(sensor_data* data, int num_sensors) {
    if (!data) return;

    for (int i = 0; i < num_sensors; i++) {
        free(data[i].identifier);
    }
    free(data);
}

int main() {
    srand(time(NULL));
    sensor_data* sensors = initialize_sensor_data(NUM_SENSORS);

    if (sensors) {
        // Use the sensor data here
        cleanup_sensor_data(sensors, NUM_SENSORS);
    }

    return 0;
}
