    data->measurements = (double *)calloc(numSensors, sizeof(double));
    data->intensities = (float *)calloc(numSensors, sizeof(float));
    data->statusCodes = (char *)calloc(numSensors, sizeof(char));

    record *records = (record *)malloc(sizeof(record) * numRecords);
    for (int i = 0; i < numRecords; i++) {
        records[i].value = rand() % 100;
    }

    data->records = records;

    return data;
}

void freeSensorData(sensorData *data, int numRecords) {
    free(data->measurements);
    free(data->intensities);
    free(data->statusCodes);
    free(data->records);
