void log_memory_allocation(void* ptr, size_t size) {
    printf("Allocated %zu bytes at address %p\n", size, ptr);
}

record* initialize_records(int num_records, int min_value, int max_value, int max_key_length) {
    if (num_records <= 0 || min_value > max_value || max_key_length <= 0) {
        return NULL;
    }

    record* records = (record*)malloc(num_records * sizeof(record));
    if (!records) {
        log_memory_allocation(records, num_records * sizeof(record));
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;

        char* key = (char*)malloc((max_key_length + 1) * sizeof(char));
        if (!key) {
            log_memory_allocation(key, (max_key_length + 1) * sizeof(char));

            // Free previously allocated records
            for (int j = 0; j < i; ++j) {
                free(records[j].key);
            }
            free(records);

            return NULL;
        }

        records[i].key = key;

        // Generate a random string key
        for (int j = 0; j < max_key_length; ++j) {
            records[i].key[j] = 'a' + rand() % 26;
        }
        records[i].key[max_key_length] = '\0';
    }

    log_memory_allocation(records, num_records * sizeof(record));
    return records;
}

void free_records(record* records, int num_records) {
    if (records) {
        for (int i = 0; i < num_records; ++i) {
            free(records[i].key);
        }
        free(records);
    }
}
