#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    long offset;
    int key;
    double value;
} Record;

Record** create_records(int count, int seed) {
    if (count <= 0 || seed == 0) {
        return NULL;
    }

    srand(seed);
    Record** records = (Record**)malloc(count * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for record pointers.\n");
        return NULL;
    }

    long offset = 0;
    for (int i = 0; i < count; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            // Free previously allocated records
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->offset = offset++;
        records[i]->key = rand() % count + 1; // Ensure unique values within the range [1, count]
        records[i]->value = (double)rand() / RAND_MAX;
    }

    return records;
}

void free_records(Record** records, int count) {
    if (!records || count <= 0) {
        return;
    }

    for (int i = 0; i < count; ++i) {
        free(records[i]);
    }
    free(records);
}

int main() {
    int count = 10;
    int seed = time(NULL);

    Record** records = create_records(count, seed);
    if (!records) {
        fprintf(stderr, "Failed to create records.\n");
        return EXIT_FAILURE;
    }

    // Use the records...

    free_records(records, count);

    return EXIT_SUCCESS;
}
