#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000000
#define CACHE_SIZE 100

typedef struct {
    int identifier;
    double value;
    char label;
} item;

typedef struct {
    char source_path[256];
    time_t timestamp;
} metadata;

typedef struct {
    long offset;
    int key;
    float precision;
    unsigned char flag;
    item *data;
    metadata meta;
} record;

record cache[CACHE_SIZE];
int cache_index = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void* read_records(void* arg) {
    FILE *file = (FILE*)arg;
    record records[MAX_RECORDS];
    int count = 0;

    while (fread(&records[count], sizeof(record), 1, file)) {
        if (count >= MAX_RECORDS - 1) break;

        // Generate random values for the record fields
        records[count].offset = rand() % 1000000;
        records[count].key = rand() % 1000;
        records[count].precision = ((float)rand()) / RAND_MAX * 10.0f;
        records[count].flag = (unsigned char)(rand() % 256);

        // Allocate memory for the item and metadata
        records[count].data = malloc(sizeof(item));
        records[count].meta.source_path[0] = '\0';
        records[count].meta.timestamp = time(NULL);

        if (!records[count].data) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        // Generate random values for the item fields
        records[count].data->identifier = rand() % 100;
        records[count].data->value = ((double)rand()) / RAND_MAX * 100.0;
        records[count].data->label = 'A' + (rand() % 26);

        // Determine the status flag based on predefined conditions
        if (records[count].precision > 5.0f) {
            records[count].flag |= 0x01;
        }

        count++;
    }

    // Cache the records for efficient access
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < count; i++) {
        cache[cache_index] = records[i];
        cache_index = (cache_index + 1) % CACHE_SIZE;
    }
    pthread_mutex_unlock(&cache_lock);

    fclose(file);
    return NULL;
}

int main() {
    srand(time(NULL));
    FILE *file = fopen("large_binary_file.bin", "rb");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    pthread_t thread;
    pthread_create(&thread, NULL, read_records, file);

    // Wait for the thread to finish
    pthread_join(thread, NULL);

    // Access cached records
    for (int i = 0; i < CACHE_SIZE; i++) {
        printf("Offset: %ld, Key: %d, Precision: %.2f, Flag: %d\n",
               cache[i].offset, cache[i].key, cache[i].precision, cache[i].flag);
        free(cache[i].data);
    }

    fclose(file);
    return 0;
}
