Record* initialize_records(int range, int *record_count) {
    FILE *file = fopen("data.bin", "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    int record_size = sizeof(long) + sizeof(int) + sizeof(float) + sizeof(unsigned char) + sizeof(Item*);
    *record_count = file_size / record_size;

    Record *records = (Record*)malloc(*record_count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        fclose(file);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < *record_count; i++) {
        records[i].value = rand() % range;
    }

    fclose(file);
    return records;
}

void free_records(Record *records, int record_count) {
    if (records) {
        free(records);
    }
}

int main() {
    int range = 1000;
    int record_count;

    Record *records = initialize_records(range, &record_count);
    if (!records) {
        return EXIT_FAILURE;
    }

    // Process records...

    free_records(records, record_count);

    return EXIT_SUCCESS;
}
