typedef struct node {
    time_t timestamp;
    char *key;
    struct node **children;
    int num_children;
    pthread_mutex_t lock;
} Node;

Node** create_node_array(int num_nodes, time_t min_age, time_t max_age, size_t max_key_len) {
    Node** nodes = (Node**)malloc(num_nodes * sizeof(Node*));
    if (!nodes) {
        perror("Failed to allocate memory for node array");
        return NULL;
    }

    char **key_pool = (char**)malloc(num_nodes * max_key_len);
    if (!key_pool) {
        perror("Failed to allocate memory for key pool");
        free(nodes);
        return NULL;
    }

    pthread_mutex_t global_lock;
    pthread_mutex_init(&global_lock, NULL);

    for (int i = 0; i < num_nodes; ++i) {
        nodes[i] = (Node*)malloc(sizeof(Node));
        if (!nodes[i]) {
            perror("Failed to allocate memory for node");
            free(key_pool);
            for (int j = 0; j < i; ++j) {
                free(nodes[j]);
            }
            free(nodes);
            return NULL;
        }

        nodes[i]->timestamp = min_age + rand() % (max_age - min_age + 1);
        nodes[i]->key = key_pool[i];
        strcpy(key_pool[i], "path_to_file");

        nodes[i]->children = (Node**)malloc(0 * sizeof(Node*));
        if (!nodes[i]->children) {
            perror("Failed to allocate memory for children array");
            free(nodes[i]);
            free(key_pool);
            for (int j = 0; j < i; ++j) {
                free(nodes[j]);
            }
            free(nodes);
            return NULL;
        }

        nodes[i]->num_children = 0;
        pthread_mutex_init(&nodes[i]->lock, NULL);

        // Log allocation details
        printf("Allocated %zu bytes at address %p\n", sizeof(Node), (void*)nodes[i]);
    }

    // Compact memory for file path strings periodically
    // ...

    return nodes;
}

// Function to free allocated memory and clean up resources
void free_node_array(Node** nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; ++i) {
        pthread_mutex_destroy(&nodes[i]->lock);
        free(nodes[i]->children);
        free(nodes[i]);
    }
    free(nodes);
}

// Example usage
int main() {
    srand(time(NULL));
    Node** nodes = create_node_array(10, 1633072800, 1635751200, 256);
    if (nodes) {
        free_node_array(nodes, 10);
    }
    return 0;
}
