#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int priority;
    char* command;
    time_t timestamp;
} task;

typedef struct {
    task** tasks;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} task_list;

task_list* create_task_list(size_t initial_capacity) {
    task_list* list = (task_list*)malloc(sizeof(task_list));
    if (!list) return NULL;

    list->tasks = (task**)calloc(initial_capacity, sizeof(task*));
    if (!list->tasks) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_task_list(task_list* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->tasks[i]->command);
        free(list->tasks[i]);
    }
    free(list->tasks);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_task(task_list* list, int priority, const char* command) {
    pthread_mutex_lock(&list->mutex);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity * 2;
        task** new_tasks = (task**)realloc(list->tasks, new_capacity * sizeof(task*));
        if (!new_tasks) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Out of memory
        }
        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }

    task* new_task = (task*)malloc(sizeof(task));
    if (!new_task) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Out of memory
    }

    new_task->priority = priority;
    new_task->command = strdup(command);
    new_task->timestamp = time(NULL);

    list->tasks[list->size++] = new_task;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_task(task_list* list, size_t index) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->size) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Invalid index
    }

    free(list->tasks[index]->command);
    free(list->tasks[index]);

    for (size_t i = index; i < list->size - 1; ++i) {
        list->tasks[i] = list->tasks[i + 1];
    }
    --list->size;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int update_task(task_list* list, size_t index, int new_priority, const char* new_command) {
    pthread_mutex_lock(&list->mutex);

    if (index >= list->size) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Invalid index
    }

    free(list->tasks[index]->command);
    list->tasks[index]->priority = new_priority;
    list->tasks[index]->command = strdup(new_command);
    list->tasks[index]->timestamp = time(NULL);

    pthread_mutex_unlock(&list->mutex);
    return 0;
}
