#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    char* buffer;
    long timestamp;
} record;

typedef struct {
    record** records;
    size_t max_records;
    size_t current_size;
    pthread_mutex_t lock;
} record_pool;

record_pool* create_record_pool(size_t max_records, size_t buffer_size) {
    record_pool* pool = (record_pool*)malloc(sizeof(record_pool));
    if (!pool) return NULL;

    pool->records = (record**)malloc(max_records * sizeof(record*));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    pthread_mutex_init(&pool->lock, NULL);

    for (size_t i = 0; i < max_records; ++i) {
        record* rec = (record*)malloc(sizeof(record));
        if (!rec) {
            for (size_t j = 0; j < i; ++j) free(pool->records[j]);
            free(pool->records);
            pthread_mutex_destroy(&pool->lock);
            free(pool);
            return NULL;
        }

        rec->buffer = (char*)malloc(buffer_size * sizeof(char));
        if (!rec->buffer) {
            for (size_t j = 0; j <= i; ++j) free(pool->records[j]->buffer);
            free(pool->records[i]);
            for (size_t j = 0; j < i; ++j) free(pool->records[j]);
            free(pool->records);
            pthread_mutex_destroy(&pool->lock);
            free(pool);
            return NULL;
        }

        rec->value = 0;
        rec->timestamp = time(NULL);
        pool->records[i] = rec;
    }

    pool->max_records = max_records;
    pool->current_size = max_records;

    return pool;
}

void destroy_record_pool(record_pool* pool) {
    for (size_t i = 0; i < pool->max_records; ++i) {
        free(pool->records[i]->buffer);
        free(pool->records[i]);
    }
    free(pool->records);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

record* get_record(record_pool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->current_size == 0) {
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
    record* rec = pool->records[--pool->current_size];
    pthread_mutex_unlock(&pool->lock);
    return rec;
}

void release_record(record_pool* pool, record* rec) {
    pthread_mutex_lock(&pool->lock);
    if (pool->current_size < pool->max_records) {
        pool->records[pool->current_size++] = rec;
    }
    pthread_mutex_unlock(&pool->lock);
}
