void manage_memory(long** offsets, int** keys, record** records, long* offset_size, int* key_size, int* record_size, int max_range) {
    // Free existing memory if allocated
    if (*offsets != NULL) free(*offsets);
    if (*keys != NULL) free(*keys);
    if (*records != NULL) free(*records);

    // Validate input parameters
    if (*offset_size <= 0 || *key_size <= 0 || *record_size <= 0 || max_range <= 0) {
        fprintf(stderr, "Invalid input parameters.\n");
        return;
