typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    record *record_ptr;
} pointer_struct;

void initialize_data_structures(int size, long *offsets, int *keys, record **records, pointer_struct **pointers) {
    // Initialize offsets array
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % 1000;
    }

    // Initialize keys array
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % 100;
    }

    // Allocate memory for records and pointers arrays
    *records = (record *)malloc(size * sizeof(record));
    *pointers = (pointer_struct *)malloc(size * sizeof(pointer_struct));

    if (*records == NULL || *pointers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Initialize records and pointers arrays
    for (int i = 0; i < size; i++) {
        (*records)[i].offset = offsets[i];
        (*records)[i].key = keys[i];
        (*pointers)[i].record_ptr = &(*records)[i];
    }
}

void free_data_structures(record **records, pointer_struct **pointers) {
    // Free allocated memory
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }

    if (*pointers != NULL) {
        free(*pointers);
        *pointers = NULL;
    }
}

int main() {
    int size = 10;
    long offsets[size];
    int keys[size];
    record *records;
    pointer_struct *pointers;

    initialize_data_structures(size, offsets, keys, &records, &pointers);

    // Use records and pointers arrays here

    free_data_structures(&records, &pointers);

    return 0;
}
