#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct job {
    int priority;
    double resource_consumption;
    char* description;
} Job;

typedef struct task {
    char identifier;
    time_t timestamp;
    Job job;
} Task;

typedef struct task_collection {
    Task* tasks;
    size_t max_tasks;
    size_t current_tasks;
    size_t max_description_length;
    time_t min_timestamp;
    time_t max_timestamp;
} TaskCollection;

TaskCollection* create_task_collection(size_t max_tasks, size_t max_description_length, time_t min_timestamp, time_t max_timestamp) {
    TaskCollection* collection = (TaskCollection*)malloc(sizeof(TaskCollection));
    if (!collection) {
        return NULL; // Memory allocation failed
    }
    collection->tasks = (Task*)calloc(max_tasks, sizeof(Task));
    if (!collection->tasks) {
        free(collection);
        return NULL; // Memory allocation failed
    }
    collection->max_tasks = max_tasks;
    collection->current_tasks = 0;
    collection->max_description_length = max_description_length;
    collection->min_timestamp = min_timestamp;
    collection->max_timestamp = max_timestamp;
    return collection;
}

void destroy_task_collection(TaskCollection* collection) {
    for (size_t i = 0; i < collection->current_tasks; ++i) {
        free(collection->tasks[i].job.description);
    }
    free(collection->tasks);
    free(collection);
}

int add_task(TaskCollection* collection, char identifier, time_t timestamp, Job job) {
    if (collection->current_tasks >= collection->max_tasks || timestamp < collection->min_timestamp || timestamp > collection->max_timestamp) {
        return -1; // Invalid task or collection full
    }
    Task new_task = {identifier, timestamp, job};
    collection->tasks[collection->current_tasks++] = new_task;
    return 0;
}

int update_task(TaskCollection* collection, char identifier, time_t timestamp, Job job) {
    for (size_t i = 0; i < collection->current_tasks; ++i) {
        if (collection->tasks[i].identifier == identifier && collection->tasks[i].timestamp == timestamp) {
            free(collection->tasks[i].job.description);
            collection->tasks[i] = (Task){identifier, timestamp, job};
            return 0;
        }
    }
    return -1; // Task not found
}

int remove_task(TaskCollection* collection, char identifier, time_t timestamp) {
    for (size_t i = 0; i < collection->current_tasks; ++i) {
        if (collection->tasks[i].identifier == identifier && collection->tasks[i].timestamp == timestamp) {
            free(collection->tasks[i].job.description);
            for (size_t j = i; j < collection->current_tasks - 1; ++j) {
                collection->tasks[j] = collection->tasks[j + 1];
            }
            --collection->current_tasks;
            return 0;
        }
    }
    return -1; // Task not found
}
