#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_DESCRIPTION_LENGTH 256
#define AMOUNT_RANGE_MIN -1000000.0
#define AMOUNT_RANGE_MAX 1000000.0

typedef struct Transaction {
    int timestamp;
    char description[MAX_DESCRIPTION_LENGTH];
    float amount;
} Transaction;

typedef struct Dataset {
    Transaction* transactions;
    size_t count;
    size_t capacity;
} Dataset;

Dataset* init_dataset(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    Dataset* dataset = (Dataset*)malloc(sizeof(Dataset));
    if (!dataset) {
        perror("Memory allocation failed for dataset");
        fclose(file);
        return NULL;
    }
    dataset->transactions = NULL;
    dataset->count = 0;
    dataset->capacity = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Transaction* transaction = (Transaction*)realloc(dataset->transactions, (dataset->count + 1) * sizeof(Transaction));
        if (!transaction) {
            perror("Memory allocation failed for transaction");
            free(dataset->transactions);
            dataset->transactions = NULL;
            fclose(file);
            return dataset;
        }
        dataset->transactions = transaction;

        char* token = strtok(line, " ");
        if (token != NULL) {
            dataset->transactions[dataset->count].timestamp = atoi(token);

            token = strtok(NULL, " ");
            if (token != NULL && strlen(token) > 0) {
                strncpy(dataset->transactions[dataset->count].description, token, MAX_DESCRIPTION_LENGTH - 1);
                dataset->transactions[dataset->count].description[MAX_DESCRIPTION_LENGTH - 1] = '\0';

                token = strtok(NULL, " ");
                if (token != NULL) {
                    dataset->transactions[dataset->count].amount = atof(token);

                    if (dataset->transactions[dataset->count].timestamp < 0 ||
                        strlen(dataset->transactions[dataset->count].description) == 0 ||
                        dataset->transactions[dataset->count].amount < AMOUNT_RANGE_MIN ||
                        dataset->transactions[dataset->count].amount > AMOUNT_RANGE_MAX) {
                        fprintf(stderr, "Validation error at line %zu: Invalid transaction\n", dataset->count + 1);
                    } else {
                        dataset->count++;
                    }
                } else {
                    fprintf(stderr, "Validation error at line %zu: Missing amount\n", dataset->count + 1);
                }
            } else {
                fprintf(stderr, "Validation error at line %zu: Empty description\n", dataset->count + 1);
            }
        } else {
            fprintf(stderr, "Validation error at line %zu: Missing timestamp\n", dataset->count + 1);
        }
    }

    fclose(file);
    return dataset;
}

void free_dataset(Dataset* dataset) {
    if (dataset->transactions != NULL) {
        free(dataset->transactions);
    }
    free(dataset);
}

// Additional functions to find earliest, most recent, highest amount, and longest description can be implemented here

int main() {
    Dataset* dataset = init_dataset("transactions.txt");
    if (dataset != NULL) {
        // Process the dataset
        free_dataset(dataset);
    }
    return 0;
}
