#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    double temperature;
    char status[20];
    time_t timestamp;
} TemperatureReading;

double calculateAverageTemperature(TemperatureReading *readings, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += readings[i].temperature;
    }
    return sum / count;
}

void logMessage(const char *message) {
    printf("%s\n", message);
}

TemperatureReading* initializeTemperatureData(int startTimestamp, int endTimestamp, double minTemp, double maxTemp, int *count) {
    time_t currentTimestamp = (time_t)startTimestamp;
    *count = endTimestamp - startTimestamp + 1;
    TemperatureReading *readings = (TemperatureReading*)malloc(*count * sizeof(TemperatureReading));

    if (readings == NULL) {
        logMessage("Memory allocation failed for temperature readings.");
        return NULL;
    }

    srand(time(NULL));
    while (currentTimestamp <= endTimestamp) {
        readings[currentTimestamp - startTimestamp].temperature = minTemp + (double)(rand() / (RAND_MAX / (maxTemp - minTemp)));
        strcpy(readings[currentTimestamp - startTimestamp].status, "Valid");
        readings[currentTimestamp - startTimestamp].timestamp = currentTimestamp;
        currentTimestamp++;
    }

    logMessage("Temperature data initialized successfully.");
    return readings;
}

void freeTemperatureData(TemperatureReading *readings, int count) {
    if (readings != NULL) {
        free(readings);
        logMessage("Temperature data freed successfully.");
    }
}

int main() {
    int startTimestamp = 1633072800; // Example timestamp
    int endTimestamp = 1633159200;
    double minTemp = -10.0;
    double maxTemp = 40.0;
    int count;

    TemperatureReading *readings = initializeTemperatureData(startTimestamp, endTimestamp, minTemp, maxTemp, &count);

    if (readings != NULL) {
        double averageTemp = calculateAverageTemperature(readings, count);
        printf("Average Temperature: %.2f\n", averageTemp);

        freeTemperatureData(readings, count);
    }

    return 0;
}
