import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

public class UserAuthenticationService {

    private ConcurrentHashMap<String, String> userProfiles = new ConcurrentHashMap<>();
    private AtomicInteger successfulAuthentications = new AtomicInteger(0);
    private AtomicInteger failedAttempts = new AtomicInteger(0);
    private AtomicLong totalRequestTime = new AtomicLong(0);

    public boolean authenticateUser(String username, String password) {
        long startTime = System.currentTimeMillis();
        try {
            // Simulate user authentication
            if (userProfiles.containsKey(username) && userProfiles.get(username).equals(password)) {
                successfulAuthentications.incrementAndGet();
                return true;
            } else {
                failedAttempts.incrementAndGet();
                return false;
            }
        } finally {
            long endTime = System.currentTimeMillis();
            totalRequestTime.addAndGet(endTime - startTime);
        }
    }

    public void addUserProfile(String username, String password) {
        userProfiles.put(username, password);
    }

    public int getSuccessfulAuthentications() {
        return successfulAuthentications.get();
    }

    public int getFailedAttempts() {
        return failedAttempts.get();
    }

    public double getAverageRequestTime() {
        long totalRequests = successfulAuthentications.get() + failedAttempts.get();
        if (totalRequests == 0) {
            return 0;
        }
        return (double) totalRequestTime.get() / totalRequests;
    }
}
