#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct record {
    long offset;
    int key;
    struct record *next;
    char *data;
} Record;

typedef struct dataset {
    Record **records;
    int size;
    pthread_mutex_t lock;
} Dataset;

Dataset* create_dataset(int size) {
    Dataset *ds = (Dataset*)malloc(sizeof(Dataset));
    ds->records = (Record**)calloc(size, sizeof(Record*));
    ds->size = size;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void destroy_dataset(Dataset *ds) {
    for (int i = 0; i < ds->size; i++) {
        Record *r = ds->records[i];
        while (r != NULL) {
            Record *next = r->next;
            free(r->data);
            free(r);
            r = next;
        }
    }
    pthread_mutex_destroy(&ds->lock);
    free(ds->records);
    free(ds);
}

void* init_dataset(void *arg) {
    Dataset *ds = (Dataset*)arg;
    for (int i = 0; i < ds->size; i++) {
        Record *r = (Record*)malloc(sizeof(Record));
        r->offset = i * 1024;
        r->key = rand() % 1000;
        r->next = NULL;
        r->data = (char*)malloc(1024);
        memset(r->data, 'A', 1023);
        r->data[1023] = '\0';
        pthread_mutex_lock(&ds->lock);
        ds->records[i] = r;
        pthread_mutex_unlock(&ds->lock);
    }
    return NULL;
}

void print_largest_key(Dataset *ds) {
    int max_key = -1;
    for (int i = 0; i < ds->size; i++) {
        Record *r = ds->records[i];
        while (r != NULL) {
            if (r->key > max_key) {
                max_key = r->key;
            }
            r = r->next;
        }
    }
    printf("Largest key: %d\n", max_key);
}

int main() {
    int size = 1000;
    Dataset *ds = create_dataset(size);

    pthread_t threads[size];
    for (int i = 0; i < size; i++) {
        pthread_create(&threads[i], NULL, init_dataset, ds);
    }

    for (int i = 0; i < size; i++) {
        pthread_join(threads[i], NULL);
    }

    print_largest_key(ds);

    destroy_dataset(ds);
    return 0;
}
