#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_REQUESTS 1000
#define MAX_ELEMENTS 10000
#define OFF_HEAP_THRESHOLD 2 * 1024 * 1024 * 1024 // 2GB

typedef struct record {
    int int_value;
    char* str_value;
    double* double_value;
    struct record* next;
} Record;

Record** allocate_records(int size) {
    if (size > MAX_ELEMENTS) {
        fprintf(stderr, "Error: Input size exceeds maximum allowed.\n");
        return NULL;
    }

    Record** records = (Record**)malloc(size * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            for (int j = 0; j < i; j++) free(records[j]);
            free(records);
            return NULL;
        }
    }

    return records;
}

void initialize_records(Record** records, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i]->int_value = rand() % 1000 + 1;
        records[i]->double_value = (double*)malloc(sizeof(double));
        *records[i]->double_value = records[i]->int_value * 0.1;

        char* input_str = "example_string";
        int str_len = strlen(input_str);
        if (str_len > 256) {
            records[i]->str_value = (char*)malloc(259); // 256 + 3 for "... "
            strncpy(records[i]->str_value, input_str, 256);
            records[i]->str_value[256] = '.';
            records[i]->str_value[257] = '.';
            records[i]->str_value[258] = '\0';
        } else {
            records[i]->str_value = strdup(input_str);
        }

        records[i]->next = NULL;
    }
}

void free_records(Record** records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i]->double_value);
        free(records[i]->str_value);
        free(records[i]);
    }
    free(records);
}

int main() {
    int size = 500; // Example size
    Record** records = allocate_records(size);
    if (records) {
        initialize_records(records, size);
        // Use the records array as needed
        free_records(records, size);
    }

    return 0;
}
