#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct record {
    int value;
    int flag;
    struct record *next;
    struct record *prev;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record *head;
    Record *tail;
    Record **records;
    size_t capacity;
    size_t size;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity) {
    RecordManager *manager = (RecordManager*)malloc(sizeof(RecordManager));
    manager->offsets = (long*)calloc(initial_capacity, sizeof(long));
    manager->keys = (int*)calloc(initial_capacity, sizeof(int));
    manager->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    manager->head = NULL;
    manager->tail = NULL;
    manager->capacity = initial_capacity;
    manager->size = 0;
    return manager;
}

bool insert_record(RecordManager *manager, int key, int value) {
    if (manager->size >= manager->capacity) {
        // Handle memory reallocation
        size_t new_capacity = manager->capacity * 2;
        long *new_offsets = (long*)realloc(manager->offsets, new_capacity * sizeof(long));
        int *new_keys = (int*)realloc(manager->keys, new_capacity * sizeof(int));
        Record **new_records = (Record**)realloc(manager->records, new_capacity * sizeof(Record*));

        if (!new_offsets || !new_keys || !new_records) {
            return false; // Memory allocation failed
        }

        manager->offsets = new_offsets;
        manager->keys = new_keys;
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->keys[i] == key) {
            return false; // Duplicate key
        }
    }

    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->value = value;
    new_record->flag = 0; // Assuming flag is initially set to 0
    new_record->next = NULL;
    new_record->prev = manager->tail;

    if (manager->tail) {
        manager->tail->next = new_record;
    } else {
        manager->head = new_record;
    }

    manager->tail = new_record;
    manager->keys[manager->size] = key;
    manager->records[manager->size++] = new_record;

    return true;
}

Record* get_record(RecordManager *manager, int key) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->keys[i] == key) {
            return manager->records[i];
        }
    }
    return NULL; // Record not found
}

void iterate_records(RecordManager *manager, void (*callback)(int, int)) {
    for (size_t i = 0; i < manager->size; ++i) {
        callback(manager->keys[i], manager->records[i]->value);
    }
}

void free_record_manager(RecordManager *manager) {
    Record *current = manager->head;
    while (current) {
        Record *next = current->next;
        free(current);
        current = next;
    }

    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    free(manager);
}
