typedef struct node {
    long id;
    Record* records;
    int num_records;
    struct node** children;
    int num_children;
    pthread_mutex_t lock;
} Node;

Node* create_node(long id, int num_records) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->id = id;
    new_node->records = (Record*)calloc(num_records, sizeof(Record));
    new_node->num_records = num_records;
    new_node->children = NULL;
    new_node->num_children = 0;
    pthread_mutex_init(&new_node->lock, NULL);
    return new_node;
}

void add_child(Node* parent, Node* child) {
    parent->num_children++;
    parent->children = (Node**)realloc(parent->children, parent->num_children * sizeof(Node*));
    parent->children[parent->num_children - 1] = child;
}

void free_node(Node* node) {
    pthread_mutex_lock(&node->lock);
    for (int i = 0; i < node->num_records; i++) {
        // Free any resources associated with records
    }
    if (node->children != NULL) {
        for (int i = 0; i < node->num_children; i++) {
            free_node(node->children[i]);
        }
        free(node->children);
    }
    pthread_mutex_unlock(&node->lock);
    pthread_mutex_destroy(&node->lock);
    free(node->records);
    free(node);
}

