#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define LOG_FILE "access_log.txt"
#define LOG_SIZE_LIMIT 1024 * 1024 // 1MB

typedef struct {
    int value;
} Record;

typedef struct {
    Record* records;
    size_t count;
    pthread_mutex_t lock;
} Database;

typedef struct {
    FILE* file;
    size_t size;
    pthread_mutex_t log_lock;
} AccessLog;

Database db = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};
AccessLog access_log = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

void init_database() {
    db.records = (Record*)malloc(MAX_RECORDS * sizeof(Record));
    if (!db.records) {
        fprintf(stderr, "Failed to allocate memory for database\n");
        exit(EXIT_FAILURE);
    }
}

void free_database() {
    pthread_mutex_lock(&db.lock);
    free(db.records);
    db.records = NULL;
    db.count = 0;
    pthread_mutex_unlock(&db.lock);
}

void init_access_log() {
    access_log.file = fopen(LOG_FILE, "a");
    if (!access_log.file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
}

void free_access_log() {
    pthread_mutex_lock(&access_log.log_lock);
    fclose(access_log.file);
    access_log.file = NULL;
    access_log.size = 0;
    pthread_mutex_unlock(&access_log.log_lock);
}

void log_access(size_t index) {
    time_t now = time(NULL);
    char* timestamp = ctime(&now);

    pthread_mutex_lock(&access_log.log_lock);
    if (ftell(access_log.file) + strlen(timestamp) > LOG_SIZE_LIMIT) {
        fclose(access_log.file);
        rename(LOG_FILE, "access_log_old.txt");
        access_log.file = fopen(LOG_FILE, "a");
    }

    fprintf(access_log.file, "%s Access index: %zu\n", timestamp, index);
    fflush(access_log.file);
    pthread_mutex_unlock(&access_log.log_lock);
}

void add_record(int value) {
    pthread_mutex_lock(&db.lock);
    if (db.count < MAX_RECORDS) {
        db.records[db.count].value = value;
        db.count++;
        log_access(db.count - 1);
    } else {
        fprintf(stderr, "Database is full\n");
    }
    pthread_mutex_unlock(&db.lock);
}

int get_record(size_t index) {
    int result = -1;

    pthread_mutex_lock(&db.lock);
    if (index < db.count) {
        result = db.records[index].value;
        log_access(index);
    } else {
        fprintf(stderr, "Invalid record index\n");
    }
    pthread_mutex_unlock(&db.lock);

    return result;
}

int main() {
    init_database();
    init_access_log();

    add_record(42);
    int value = get_record(0);
    printf("Retrieved value: %d\n", value);

    free_database();
    free_access_log();

    return 0;
}
