    pthread_mutex_t mutex;
} TreeManager;

TreeManager* create_tree_manager(size_t max_depth, size_t total_nodes) {
    TreeManager* manager = (TreeManager*)malloc(sizeof(TreeManager));
    if (!manager) return NULL;

    manager->nodes = (Node**)calloc(total_nodes, sizeof(Node*));
    manager->records = (Record**)calloc(total_nodes, sizeof(Record*));
    manager->offsets = (long*)calloc(total_nodes, sizeof(long));
    manager->keys = (int*)calloc(total_nodes, sizeof(int));
    manager->max_depth = max_depth;
    manager->total_nodes = total_nodes;

    if (!manager->nodes || !manager->records || !manager->offsets || !manager->keys) {
        free_tree_manager(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);

    for (size_t i = 0; i < total_nodes; ++i) {
        manager->nodes[i] = (Node*)malloc(sizeof(Node));
        if (!manager->nodes[i]) {
            free_tree_manager(manager);
            return NULL;
        }
        memset(manager->nodes[i], 0, sizeof(Node));
    }

    for (size_t i = 0; i < total_nodes; ++i) {
        manager->records[i] = (Record*)malloc(sizeof(Record));
        if (!manager->records[i]) {
            free_tree_manager(manager);
            return NULL;
