    for (size_t i = 0; i < total_nodes; ++i) {
        manager->keys[i] = rand() % 1000;
    }

    return manager;
}

void free_tree_manager(TreeManager* manager) {
    if (!manager) return;

    for (size_t i = 0; i < manager->total_nodes; ++i) {
        free(manager->nodes[i]);
        free(manager->records[i]);
    }

    free(manager->nodes);
    free(manager->records);
    free(manager->offsets);
    free(manager->keys);

    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void insert_node(TreeManager* manager, Node* parent, Node* new_node) {
