#define POOL_SIZE 1000000

typedef struct {
    int value;
} Record;

typedef struct {
    Record *pool;
    size_t pool_size;
    size_t next_index;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_size) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->pool = (Record*)malloc(initial_size * sizeof(Record));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pool->pool_size = initial_size;
    pool->next_index = 0;

    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    if (pool) {
        free(pool->pool);
        free(pool);
    }
}

Record* allocate_record(MemoryPool *pool) {
    if (pool->next_index >= pool->pool_size) {
        size_t new_size = pool->pool_size + POOL_SIZE;
        Record *new_pool = (Record*)realloc(pool->pool, new_size * sizeof(Record));
        if (!new_pool) return NULL;

        pool->pool = new_pool;
        pool->pool_size = new_size;
    }

    return &pool->pool[pool->next_index++];
}

void deallocate_record(MemoryPool *pool, Record *record) {
    // In a real scenario, you would implement a more sophisticated caching mechanism here
    // For simplicity, we'll just reset the index to reuse the record
    pool->next_index--;
}

int main() {
    MemoryPool *pool = create_memory_pool(POOL_SIZE);
    if (!pool) {
        fprintf(stderr, "Failed to create memory pool\n");
        return 1;
    }

    Record *record = allocate_record(pool);
    if (record) {
        record->value = 42;
        printf("Allocated record with value: %d\n", record->value);

        deallocate_record(pool, record);
        printf("Deallocated record\n");
    } else {
        fprintf(stderr, "Failed to allocate record\n");
    }

    destroy_memory_pool(pool);
    return 0;
}
