#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <signal.h>

#define INITIAL_BUFFER_SIZE 1024

typedef struct {
    int* buffer;
    size_t capacity;
    size_t count;
} IntegerBuffer;

void handle_signal(int signum) {
    // Handle signal interruption gracefully
    printf("Signal received, exiting gracefully.\n");
    exit(signum);
}

IntegerBuffer* create_buffer() {
    IntegerBuffer* buf = (IntegerBuffer*)malloc(sizeof(IntegerBuffer));
    if (!buf) return NULL;
    buf->buffer = (int*)malloc(INITIAL_BUFFER_SIZE * sizeof(int));
    if (!buf->buffer) {
        free(buf);
        return NULL;
    }
    buf->capacity = INITIAL_BUFFER_SIZE;
    buf->count = 0;
    return buf;
}

void resize_buffer(IntegerBuffer* buf, size_t new_capacity) {
    int* new_buffer = (int*)realloc(buf->buffer, new_capacity * sizeof(int));
    if (!new_buffer) {
        fprintf(stderr, "Memory reallocation failed.\n");
        exit(EXIT_FAILURE);
    }
    buf->buffer = new_buffer;
    buf->capacity = new_capacity;
}

void add_to_buffer(IntegerBuffer* buf, int value) {
    if (buf->count >= buf->capacity) {
        resize_buffer(buf, buf->capacity * 2);
    }
    buf->buffer[buf->count++] = value;
}

int find_largest_integer(IntegerBuffer* buf) {
    if (buf->count == 0) return INT_MIN; // Return minimum integer if buffer is empty
    int max_value = INT_MIN;
    for (size_t i = 0; i < buf->count; ++i) {
        if ((long long)max_value > (long long)INT_MAX - buf->buffer[i]) {
            fprintf(stderr, "Integer overflow detected.\n");
            exit(EXIT_FAILURE);
        }
        max_value = (buf->buffer[i] > max_value) ? buf->buffer[i] : max_value;
    }
    return max_value;
}

void free_buffer(IntegerBuffer* buf) {
    free(buf->buffer);
    free(buf);
}

int main() {
    signal(SIGINT, handle_signal); // Register signal handler for graceful exit
    IntegerBuffer* buffer = create_buffer();
    if (!buffer) {
        fprintf(stderr, "Failed to create buffer.\n");
        return EXIT_FAILURE;
    }

    int value;
    while (scanf("%d", &value) == 1) {
        add_to_buffer(buffer, value);
    }

    int largest_value = find_largest_integer(buffer);
    printf("Largest integer: %d\n", largest_value);

    free_buffer(buffer);
    return EXIT_SUCCESS;
}
