import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

@Service
public class OrderService {

    @Autowired
    private OrderRepository orderRepository;

    @Autowired
    private UserService userService;

    @Autowired
    private PaymentGateway paymentGateway;

    public Order createOrder(Order order) {
        // Validate input data
        if (order == null || order.getItems() == null || order.getItems().isEmpty()) {
            throw new IllegalArgumentException("Invalid order data");
        }

        // Generate unique order reference number
        String orderId = generateOrderId();

        // Save order to database
        Order savedOrder = orderRepository.save(order);

        // Process payment
        paymentGateway.processPayment(savedOrder);

        return savedOrder;
    }

    public Order getOrder(String orderId) {
        return orderRepository.findById(orderId).orElseThrow(() -> new ResourceNotFoundException("Order not found"));
    }

    public Order updateOrder(String orderId, Order updatedOrder) {
        Order existingOrder = orderRepository.findById(orderId).orElseThrow(() -> new ResourceNotFoundException("Order not found"));

        // Update specific fields
        existingOrder.setItems(updatedOrder.getItems());
        existingOrder.setStatus(updatedOrder.getStatus());

        // Save updated order to database
        return orderRepository.save(existingOrder);
    }

    public void deleteOrder(String orderId) {
        Order order = orderRepository.findById(orderId).orElseThrow(() -> new ResourceNotFoundException("Order not found"));
        orderRepository.delete(order);

        // Refund payment if necessary
        paymentGateway.refundPayment(order);
    }

    private String generateOrderId() {
        // Implement unique order reference number generation logic
        return "ORD" + System.currentTimeMillis();
    }
}
