using System;
using System.Collections.Generic;
using System.IO;

public class DynamicValueGenerator
{
    private Random random;
    private double minFloatRange;
    private double maxFloatRange;
    private int minIntRange;
    private int maxIntRange;
    private bool isFloatInclusive;
    private bool isIntInclusive;
    private long seed = DateTime.Now.Ticks;

    public DynamicValueGenerator(double minFloat, double maxFloat, int minInt, int maxInt, bool isFloatInc, bool isIntInc)
    {
        SetRange(minFloat, maxFloat, minInt, maxInt, isFloatInc, isIntInc);
        random = new Random(seed);
    }

    public void SetRange(double minFloat, double maxFloat, int minInt, int maxInt, bool isFloatInc, bool isIntInc)
    {
        if (minFloat >= maxFloat || minInt >= maxInt)
        {
            Console.WriteLine("Invalid range. Please ensure the minimum value is less than the maximum.");
            return;
        }
        minFloatRange = minFloat;
        maxFloatRange = maxFloat;
        minIntRange = minInt;
        maxIntRange = maxInt;
        isFloatInclusive = isFloatInc;
        isIntInclusive = isIntInc;
    }

    public double GetRandomFloat()
    {
        return random.NextDouble() * (maxFloatRange - minFloatRange) + minFloatRange;
    }

    public int GetRandomInt()
    {
        return random.Next(minIntRange, maxIntRange + (isIntInclusive ? 1 : 0));
    }

    public List<object> GenerateSampleValues()
    {
        var samples = new List<object>();
        for (int i = 0; i < 15; i++)
        {
            if (i % 2 == 0)
                samples.Add(GetRandomFloat());
            else
                samples.Add(GetRandomInt());
        }
        return samples;
    }

    public override string ToString()
    {
        return $"Range: Float [{minFloatRange}, {maxFloatRange}] Int [{minIntRange}, {maxIntRange}]";
    }

    public void SaveRangeSettings(string filePath)
    {
        using (StreamWriter writer = new StreamWriter(filePath))
        {
            writer.WriteLine($"{minFloatRange},{maxFloatRange},{minIntRange},{maxIntRange},{isFloatInclusive},{isIntInclusive}");
        }
    }

    public void LoadRangeSettings(string filePath)
    {
        if (File.Exists(filePath))
        {
            string[] lines = File.ReadAllLines(filePath);
            string[] parts = lines[0].Split(',');
            SetRange(double.Parse(parts[0]), double.Parse(parts[1]), int.Parse(parts[2]), int.Parse(parts[3]), bool.Parse(parts[4]), bool.Parse(parts[5]));
        }
    }

    public List<object> GetRandomWithConstraints(int minVariance, int maxRepetition)
    {
        // Implementation of GetRandomWithConstraints
        return new List<object>();
    }
}

