#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

void log_message(const char *message) {
    printf("%s\n", message);
}

EVP_CIPHER_CTX* initialize_aes_cipher(const char *passphrase, size_t passphrase_len, long **offsets, int **keys, Record **records, size_t num_records, int range_start, int range_end) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        log_message("Failed to create cipher context");
        return NULL;
    }

    unsigned char key[32];
    unsigned char iv[16];
    SHA256((unsigned char*)passphrase, passphrase_len, key);

    if (RAND_bytes(iv, sizeof(iv)) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        log_message("Failed to generate IV");
        return NULL;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        log_message("Failed to initialize cipher");
        return NULL;
    }

    *offsets = (long*)malloc(num_records * sizeof(long));
    if (!*offsets) {
        EVP_CIPHER_CTX_free(ctx);
        log_message("Failed to allocate memory for offsets");
        return NULL;
    }

    *keys = (int*)malloc(num_records * sizeof(int));
    if (!*keys) {
        free(*offsets);
        EVP_CIPHER_CTX_free(ctx);
        log_message("Failed to allocate memory for keys");
        return NULL;
    }

    *records = (Record*)malloc(num_records * sizeof(Record));
    if (!*records) {
        free(*offsets);
        free(*keys);
        EVP_CIPHER_CTX_free(ctx);
        log_message("Failed to allocate memory for records");
        return NULL;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*offsets)[i] = i * sizeof(Record);
        (*keys)[i] = rand() % (range_end - range_start + 1) + range_start;
        (*records)[i].value = rand() % (range_end - range_start + 1) + range_start;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX *ctx, long *offsets, int *keys, Record *records, size_t num_records) {
    EVP_CIPHER_CTX_free(ctx);
    free(offsets);
    free(keys);
    free(records);
}
