#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct record {
    int value;
    char* str;
    double dbl;
    struct record* next;
} Record;

Record** create_records(int size) {
    if (size <= 0 || size > MAX_RECORDS) {
        fprintf(stderr, "Invalid array size. Must be between 1 and %d.\n", MAX_RECORDS);
        return NULL;
    }

    Record** records = (Record**)malloc(size * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for record pointers.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            // Free previously allocated records
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->value = rand() % 1000; // Normalize to 0-999
        records[i]->str = (char*)malloc(256 * sizeof(char));
        if (!records[i]->str) {
            fprintf(stderr, "Memory allocation failed for string in record %d.\n", i);
            free(records[i]);
            for (int j = 0; j < i; ++j) {
                free(records[j]->str);
                free(records[j]);
            }
            free(records);
            return NULL;
        }
        snprintf(records[i]->str, 256, "Record%d", i);

        records[i]->dbl = ((double)rand() / RAND_MAX) * 100.0; // Normalize to 0-99.99
        records[i]->next = NULL;
    }

    return records;
}

void free_records(Record** records, int size) {
    for (int i = 0; i < size; ++i) {
        free(records[i]->str);
        free(records[i]);
    }
    free(records);
}

int main() {
    int size = 1000; // Example size
    Record** records = create_records(size);

    if (records) {
        // Use the records array here

        free_records(records, size);
    }

    return 0;
}
```

This code snippet provides a basic structure for managing dynamic memory allocation for multiple data structures within a resource-constrained environment. It includes error handling for invalid input sizes and graceful memory deallocation in case of errors. The `create_records` function initializes an array of `Record` structures with random values, ensuring that the values are normalized to fit within acceptable bounds. The `free_records` function is used to free all allocated memory when it's no longer needed. This example can be extended and modified to include additional data types, structures, and features as required.']

