    if (sourceConnectionId == -1) {
        fprintf(stderr, "Error: Failed to connect to source database at %s\n", sourceDatabaseURI);
        return 1;
    }

    int targetConnectionId = connectToDatabase(targetDatabaseURI);
    if (targetConnectionId == -1) {
        fprintf(stderr, "Error: Failed to connect to target database at %s\n", targetDatabaseURI);
        closeConnection(sourceConnectionId);
        return 1;
    }

    if (validateSchema(sourceDatabaseURI, targetDatabaseURI, tableName) != 0) {
        fprintf(stderr, "Warning: Schema mismatch for table %s\n", tableName);
        closeConnection(sourceConnectionId);
        closeConnection(targetConnectionId);
        return 1;
    }

    int configLoadResult = loadMigrationConfig(migrationConfig, configVersion);
    if (configLoadResult != 0) {
        fprintf(stderr, "Warning: Incompatible migration configuration version %d\n", configVersion);
        closeConnection(sourceConnectionId);
        closeConnection(targetConnectionId);
        return 1;
    }

    int dataTransferResult = transferData(sourceConnectionId, targetConnectionId, tableName);
    if (dataTransferResult != 0) {
        fprintf(stderr, "Warning: Data migration failed\n");
        closeConnection(sourceConnectionId);
        closeConnection(targetConnectionId);
        return 1;
    }

    *migrationSuccessFlag = 1;
    closeConnection(sourceConnectionId);
    closeConnection(targetConnectionId);
    return 0;
}
