#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

typedef struct record {
    int key;
    int value;
    struct record *next;
} Record;

typedef struct linked_list {
    Record *head;
    size_t count;
} LinkedList;

void init_linked_list(LinkedList *list) {
    list->head = NULL;
    list->count = 0;
}

bool insert_record(LinkedList *list, int key, int value) {
    if (find_record(list, key)) return false; // Ensure uniqueness
    Record *new_record = malloc(sizeof(Record));
    if (!new_record) return false; // Handle allocation failure
    new_record->key = key;
    new_record->value = value;
    new_record->next = list->head;
    list->head = new_record;
    list->count++;
    return true;
}

bool delete_record(LinkedList *list, int key) {
    Record **current = &list->head;
    while (*current) {
        if ((*current)->key == key) {
            Record *temp = *current;
            *current = temp->next;
            free(temp);
            list->count--;
            return true;
        }
        current = &(*current)->next;
    }
    return false;
}

Record* find_record(LinkedList *list, int key) {
    Record *current = list->head;
    while (current) {
        if (current->key == key) return current;
        current = current->next;
    }
    return NULL;
}

void free_linked_list(LinkedList *list) {
    Record *current = list->head;
    while (current) {
        Record *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->count = 0;
}
