#define MAX_RECORDS 1000
#define MIN_KEY 1
#define MAX_KEY 10000

typedef struct {
    int key;
    char *userId;
} Record;

Record* recordSystem[MAX_RECORDS];
int currentRecords = 0;

void logOperation(const char* operation, const char* userId) {
    printf("%s for user ID: %s\n", operation, userId);
}

int initializeRecordSystem() {
    if (currentRecords > 0) {
        return -1; // System already initialized
    }
    currentRecords = 0;
    return 0;
}

int addUser(const char* userId) {
    if (currentRecords >= MAX_RECORDS) {
        logOperation("Failed to add user", userId);
        return -1; // Maximum records reached
    }

    for (int i = 0; i < currentRecords; i++) {
        if (strcmp(recordSystem[i]->userId, userId) == 0) {
            logOperation("Duplicate user ID", userId);
            return -2; // Duplicate user ID
        }
    }

    Record* newRecord = (Record*)malloc(sizeof(Record));
    if (!newRecord) {
        logOperation("Memory allocation failed", userId);
        return -3; // Memory allocation failure
    }

    newRecord->userId = strdup(userId);
    if (!newRecord->userId) {
        free(newRecord);
        logOperation("Memory allocation failed for user ID string", userId);
        return -4; // Memory allocation failure for user ID string
    }

    int key;
    do {
        key = MIN_KEY + rand() % (MAX_KEY - MIN_KEY + 1);
    } while (key == currentRecords); // Ensure unique key

    newRecord->key = key;

    recordSystem[currentRecords++] = newRecord;
    logOperation("User added", userId);

    return 0; // Success
}

void freeRecordSystem() {
    for (int i = 0; i < currentRecords; i++) {
        free(recordSystem[i]->userId);
        free(recordSystem[i]);
    }
    currentRecords = 0;
}
