#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define TABLE_SIZE 1024

typedef struct record {
    int key;
    float data;
    struct record *next, *prev;
} Record;

typedef struct hash_table {
    Record *buckets[TABLE_SIZE];
    pthread_mutex_t locks[TABLE_SIZE];
} HashTable;

HashTable* create_hash_table() {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    for (int i = 0; i < TABLE_SIZE; i++) {
        ht->buckets[i] = NULL;
        pthread_mutex_init(&ht->locks[i], NULL);
    }
    return ht;
}

void insert_record(HashTable *ht, int key, float data) {
    int index = key % TABLE_SIZE;
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->data = data;
    new_record->next = NULL;
    new_record->prev = NULL;

    pthread_mutex_lock(&ht->locks[index]);
    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = new_record;
    } else {
        Record *current = ht->buckets[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
        new_record->prev = current;
    }
    pthread_mutex_unlock(&ht->locks[index]);
}

Record* find_record(HashTable *ht, int key) {
    int index = key % TABLE_SIZE;
    Record *current = ht->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void free_hash_table(HashTable *ht) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Record *current = ht->buckets[i];
        while (current != NULL) {
            Record *temp = current;
            current = current->next;
            free(temp);
        }
        pthread_mutex_destroy(&ht->locks[i]);
    }
    free(ht);
}

int main() {
    srand(time(NULL));
    HashTable *ht = create_hash_table();

    int keys[] = {1, 2, 3};
    float data_values[] = {1.1, 2.2, 3.3};

    for (int i = 0; i < 3; i++) {
        insert_record(ht, keys[i], data_values[i]);
    }

    Record *record = find_record(ht, 2);
    if (record != NULL) {
        printf("Found record with key %d and data value %.1f\n", record->key, record->data);
    } else {
        printf("Record not found\n");
    }

    free_hash_table(ht);

    return 0;
}
