#include <string.h>
#include <pthread.h>

typedef struct {
    char *file_name;
    size_t file_size;
    time_t last_modified;
    unsigned char access_control[16];
} ResourceMetadata_t;

typedef struct {
    ResourceMetadata_t **metadata_array;
    size_t array_size;
    size_t used_count;
    pthread_mutex_t mutex;
} ResourceManager_t;

void init_resource_manager(ResourceManager_t *manager, size_t initial_size) {
    manager->metadata_array = (ResourceMetadata_t **)malloc(initial_size * sizeof(ResourceMetadata_t *));
    manager->array_size = initial_size;
    manager->used_count = 0;
    pthread_mutex_init(&manager->mutex, NULL);
}

void free_resource_manager(ResourceManager_t *manager) {
    for (size_t i = 0; i < manager->used_count; ++i) {
        free(manager->metadata_array[i]);
    }
    free(manager->metadata_array);
    pthread_mutex_destroy(&manager->mutex);
}

int add_or_update_resource(ResourceManager_t *manager, const char *file_name, size_t file_size, time_t last_modified, unsigned char *access_control) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->used_count; ++i) {
        if (strcmp(manager->metadata_array[i]->file_name, file_name) == 0) {
            // Update existing resource
            free(manager->metadata_array[i]);
            break;
        }
    }

    ResourceMetadata_t *new_metadata = (ResourceMetadata_t *)malloc(sizeof(ResourceMetadata_t));
    new_metadata->file_name = strdup(file_name);
    new_metadata->file_size = file_size;
    new_metadata->last_modified = last_modified;
    memcpy(new_metadata->access_control, access_control, sizeof(unsigned char) * 16);

    if (manager->used_count == manager->array_size) {
        manager->array_size *= 2;
        manager->metadata_array = (ResourceMetadata_t **)realloc(manager->metadata_array, manager->array_size * sizeof(ResourceMetadata_t *));
    }

    manager->metadata_array[manager->used_count++] = new_metadata;
    pthread_mutex_unlock(&manager->mutex);
    return 0;
}

void iterate_resources(ResourceManager_t *manager, void (*process_func)(ResourceMetadata_t *)) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->used_count; ++i) {
        process_func(manager->metadata_array[i]);
    }
    pthread_mutex_unlock(&manager->mutex);
}

void delete_resource(ResourceManager_t *manager, const char *file_name) {
    pthread_mutex_lock(&manager->mutex);
    for (size_t i = 0; i < manager->used_count; ++i) {
        if (strcmp(manager->metadata_array[i]->file_name, file_name) == 0) {
            free(manager->metadata_array[i]);
            memmove(&manager->metadata_array[i], &manager->metadata_array[i + 1], (manager->used_count - i - 1) * sizeof(ResourceMetadata_t *));
            manager->used_count--;
            break;
        }
    }
    pthread_mutex_unlock(&manager->mutex);
}

void log_request(const char *method, const char *resource_id, int status_code) {
    printf("%s %s %d\n", method, resource_id, status_code);
}
