#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB

typedef struct Record {
    int intValue;
    double doubleValue;
    char* stringValue;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    size_t memoryUsage;
    pthread_mutex_t mutex;
} MemoryManager;

MemoryManager* createMemoryManager() {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) {
        fprintf(stderr, "Failed to allocate memory for MemoryManager\n");
        return NULL;
    }
    manager->head = NULL;
    manager->memoryUsage = 0;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

void destroyMemoryManager(MemoryManager* manager) {
    Node* current = manager->head;
    while (current) {
        Node* next = current->next;
        free(current->record.stringValue);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void addRecord(MemoryManager* manager, int intValue, double doubleValue, const char* stringValue) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->memoryUsage + sizeof(Record) + strlen(stringValue) > MAX_MEMORY_USAGE) {
        fprintf(stderr, "Memory usage exceeded quota\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }
    newNode->record.intValue = intValue;
    newNode->record.doubleValue = doubleValue;
    newNode->record.stringValue = strdup(stringValue);
    newNode->next = manager->head;
    manager->head = newNode;
    manager->memoryUsage += sizeof(Record) + strlen(stringValue);
    pthread_mutex_unlock(&manager->mutex);
}

void removeRecord(MemoryManager* manager, int intValue) {
    pthread_mutex_lock(&manager->mutex);
    Node** current = &manager->head;
    while (*current) {
        if ((*current)->record.intValue == intValue) {
            Node* temp = *current;
            *current = (*current)->next;
            free(temp->record.stringValue);
            free(temp);
            manager->memoryUsage -= sizeof(Record) + strlen((*current)->record.stringValue);
            break;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&manager->mutex);
}

void logMemoryUsage(MemoryManager* manager) {
    printf("Current memory usage: %zu bytes\n", manager->memoryUsage);
}
