#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MAX_NAME_LENGTH 256

typedef struct {
    long offset;
    int key;
    double value;
    char name[MAX_NAME_LENGTH];
    bool active;
} record;

typedef struct {
    int parent[MAX_RECORDS];
    int rank[MAX_RECORDS];
} UnionFind;

void initUnionFind(UnionFind *uf, int n) {
    for (int i = 0; i < n; i++) {
        uf->parent[i] = i;
        uf->rank[i] = 0;
    }
}

int find(UnionFind *uf, int x) {
    if (uf->parent[x] != x)
        uf->parent[x] = find(uf, uf->parent[x]);
    return uf->parent[x];
}

void unionSets(UnionFind *uf, int x, int y) {
    int rootX = find(uf, x);
    int rootY = find(uf, y);

    if (rootX != rootY) {
        if (uf->rank[rootX] > uf->rank[rootY]) {
            uf->parent[rootY] = rootX;
        } else if (uf->rank[rootX] < uf->rank[rootY]) {
            uf->parent[rootX] = rootY;
        } else {
            uf->parent[rootY] = rootX;
            uf->rank[rootX]++;
        }
    }
}

int countDisjointPairs(UnionFind *uf, int n) {
    int disjointCount = 0;
    for (int i = 0; i < n; i++) {
        if (find(uf, i) == i)
            disjointCount++;
    }
    return disjointCount;
}

void initializeRecords(record *records, int *recordCount, FILE *dataSource, long offsetRangeStart, long offsetRangeEnd) {
    *recordCount = 0;
    while (*recordCount < MAX_RECORDS && fscanf(dataSource, "%ld %d %lf %255s %d", &records[*recordCount].offset, &records[*recordCount].key, &records[*recordCount].value, records[*recordCount].name, &records[*recordCount].active) == 5) {
        if (records[*recordCount].offset >= offsetRangeStart && records[*recordCount].offset <= offsetRangeEnd) {
            (*recordCount)++;
        }
    }
}

void processRecords(record *records, int recordCount, UnionFind *uf) {
    initUnionFind(uf, recordCount);
    for (int i = 0; i < recordCount; i++) {
        for (int j = i + 1; j < recordCount; j++) {
            if (records[i].key == records[j].key) {
                unionSets(uf, i, j);
            }
        }
    }
}

void logMemoryUsage(int memoryUsed) {
    printf("Memory Used: %d bytes\n", memoryUsed);
}

int main() {
    record records[MAX_RECORDS];
    int recordCount;
    FILE *dataSource = fopen("data.txt", "r");
    if (!dataSource) {
        perror("Failed to open data source");
        return EXIT_FAILURE;
    }

    long offsetRangeStart, offsetRangeEnd;
    printf("Enter offset range (start end): ");
    scanf("%ld %ld", &offsetRangeStart, &offsetRangeEnd);

    initializeRecords(records, &recordCount, dataSource, offsetRangeStart, offsetRangeEnd);
    fclose(dataSource);

    if (recordCount == 0) {
        printf("No valid records found.\n");
        return EXIT_SUCCESS;
    }

    UnionFind uf;
    processRecords(records, recordCount, &uf);

    int disjointPairs = countDisjointPairs(&uf, recordCount);
    printf("Number of disjoint pairs: %d\n", disjointPairs);

    logMemoryUsage(sizeof(record) * recordCount + sizeof(UnionFind));

    return EXIT_SUCCESS;
}
