                } else {
                    std::cerr << "Failed to verify service health." << std::endl;
                }
            } else {
                std::cerr << "Checksum validation failed." << std::endl;
            }
        } else {
            std::cerr << "Failed to open configuration file." << std::endl;
        }
    }

    std::mutex mutex_;
};

int main() {
    NetworkConfigManager& manager = NetworkConfigManager::getInstance();
    manager.loadConfiguration("config1.txt");
    manager.updateConfigurationAsync("config2.txt");
    manager.updateConfigurationSync("config3.txt");

    return 0;
}
