#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 1000

typedef struct Semaphore {
    char name[256];
    sem_t *sem;
} Semaphore;

Semaphore semaphore_pool[MAX_SEMAPHORES];
int pool_index = 0;

Semaphore* create_semaphore(const char *name, int initial_value) {
    if (pool_index >= MAX_SEMAPHORES) {
        fprintf(stderr, "Error: Semaphore pool is full\n");
        return NULL;
    }

    Semaphore *semaphore = &semaphore_pool[pool_index++];
    strncpy(semaphore->name, name, sizeof(semaphore->name));
    semaphore->name[sizeof(semaphore->name) - 1] = '\0';

    if (sem_init(&semaphore->sem, 0, initial_value) != 0) {
        fprintf(stderr, "Error: Failed to initialize semaphore %s\n", name);
        return NULL;
    }

    return semaphore;
}

void delete_semaphore(const char *name) {
    for (int i = 0; i < pool_index; i++) {
        if (strcmp(semaphore_pool[i].name, name) == 0) {
            sem_destroy(&semaphore_pool[i].sem);
            // Optionally, mark the slot as free
            semaphore_pool[i] = semaphore_pool[--pool_index];
            return;
        }
    }

    fprintf(stderr, "Error: Semaphore %s not found\n", name);
}

void monitor_semaphores() {
    for (int i = 0; i < pool_index; i++) {
        int value;
        sem_getvalue(semaphore_pool[i].sem, &value);
        printf("Semaphore %s: Value=%d\n", semaphore_pool[i].name, value);
    }
}

int main() {
    Semaphore *sem1 = create_semaphore("sem1", 0);
    if (sem1 != NULL) {
        sem_post(sem1->sem);
        delete_semaphore("sem1");
    }

    monitor_semaphores();

    return 0;
}
