    if (*records == NULL) {
        return -1; // Memory allocation failed
    }

    srand(time(NULL));

    for (size_t i = 0; i < initial_record_count; ++i) {
        (*records)[i].data.i = rand() % 1000; // Initialize integer field with random value
        (*records)[i].data.f = 0.0f; // Default float value
        (*records)[i].data.d = 0.0; // Default double value
        memset((*records)[i].value, 0, MAX_RECORD_SIZE); // Clear char array
    }

    return initial_record_count;
}

void free_records(Record *records) {
    if (records != NULL) {
        free(records);
    }
