#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int intValue;
    double doubleValue;
    char* stringValue;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    size_t memoryUsage;
    size_t maxMemoryUsage;
} LinkedList;

LinkedList* createLinkedList(size_t maxMemoryUsage) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        fprintf(stderr, "Failed to allocate memory for LinkedList\n");
        return NULL;
    }
    list->head = NULL;
    list->memoryUsage = 0;
    list->maxMemoryUsage = maxMemoryUsage;
    return list;
}

void freeRecord(Record* record) {
    if (record->stringValue) {
        free(record->stringValue);
    }
}

void freeNode(Node* node) {
    freeRecord(&node->data);
    free(node);
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        freeNode(current);
        current = next;
    }
    free(list);
}

int addRecord(LinkedList* list, int intValue, double doubleValue, const char* stringValue) {
    if (list->memoryUsage + sizeof(Record) > list->maxMemoryUsage) {
        fprintf(stderr, "Memory usage exceeded\n");
        return -1;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Failed to allocate memory for new node\n");
        return -1;
    }

    newNode->data.intValue = intValue;
    newNode->data.doubleValue = doubleValue;
    newNode->data.stringValue = strdup(stringValue);
    if (!newNode->data.stringValue) {
        free(newNode);
        fprintf(stderr, "Failed to allocate memory for string value\n");
        return -1;
    }

    newNode->next = list->head;
    list->head = newNode;
    list->memoryUsage += sizeof(Record);

    return 0;
}

void removeRecord(LinkedList* list, int intValue) {
    Node** current = &list->head;
    while (*current) {
        if ((*current)->data.intValue == intValue) {
            Node* temp = *current;
            *current = (*current)->next;
            freeRecord(&temp->data);
            free(temp);
            list->memoryUsage -= sizeof(Record);
            break;
        }
        current = &(*current)->next;
    }
}

void validateRecords(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        if (current->data.intValue < 0 || current->data.intValue > 1000) {
            fprintf(stderr, "Invalid intValue: %d\n", current->data.intValue);
        }
        // Add more validation checks as needed
        current = current->next;
    }
}

int main() {
    srand(time(NULL));
    LinkedList* list = createLinkedList(1024 * 1024); // 1MB max memory usage

    for (int i = 0; i < 100; i++) {
        int intValue = rand() % 1001;
        double doubleValue = (double)rand() / RAND_MAX;
        char* stringValue = "example";
        addRecord(list, intValue, doubleValue, stringValue);
    }

    validateRecords(list);

    freeLinkedList(list);
    return 0;
}
